COPLAS_PIEZA(6, [["frenk_t3-n5784",7,"Una gallina variada\nempolló un guajolotito;\neso sucede a menudo\ncon cualquier animalito.",135,2,-1,134,"Con un polvo y otro polvo",0,4,"io",119,0,-1,0,36,36,"5784","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5785",7,"Una gallina con pollos\na sus hijos mantenía\ncon el pico y las uñitas,\nporque chiches no tenía.",147,2,11,134,"El gallo",0,4,"ia",-1,0,-1,0,36,36,"5785","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5786",7,"Una gallina echada\ncon once huevos\nsacó diez pollos blancos (cielito lindo)\ny un pollo negro.\nLa cuidaremos,\npa que cuando te cases (mi vida)\nla mataremos.",138,2,6,134,"Cielito lindo",4,7,"eo",127,0,-1,0,36,36,"5786","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5787",7,"Los cenzontles con sus cantos\nalegran los corazones;\nencerrados en sus jaulas,\ncantan sus dulces canciones.",135,2,-1,134,"El pajarerito",0,4,"oe",34,0,-1,0,36,36,"5787","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n5788",7,"Un marinero al pasar,\nallá por el mes de enero\ndicen que se oyó gorjear\nel pájaro carpintero.",135,2,-1,134,"Estrofa suelta",1,4,"eo",38,0,-1,0,36,36,"5788","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5789",7,"De los pájaros primero\nque en este mundo han gorjeado,\nel cinzontle y el jilguero,\ny de lo más apreciado,\nel pájaro carpintero.",136,2,4,134,"El pájaro carpintero",7,5,"eo",38,0,-1,0,37,37,"5789","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5790",7,"En la cumbre de un cardón\ncantaban tres animales,\nuno parecía gorrión\ny los otros cardenales;\n¡ay!, qué parecidos son,\npero nunca son iguales.",136,2,4,134,"El pájaro cú",9,6,"ae",26,0,-1,0,37,37,"5790","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5791",7,"Volaron las amarillas\ncalandrias de los nopales;\nahora cantarán alegres\nlos pájaros cardenales.",135,2,-1,134,"La calandria",0,4,"ae",26,0,-1,0,37,37,"5791","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5792",7,"Cantó el cenzontle llanero,\nperdido en el matorral,\ny huyó el coyote matrero,\nespantado del corral.",135,2,-1,134,"El arreo",1,4,"a",1,0,-1,0,37,37,"5792","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5793",7,"El jilguero es muy ladino,\nvibra su canto en la sierra;\ncomiendo capulincitos,\ncanta mejor en su tierra.",135,2,-1,134,"El pajarerito",0,4,"ea",80,0,-1,0,37,37,"5793","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n5794",7,"Tecolote de la paz,\ndueño de mi fantasía,\nque canta toda la noche\npor tener por suyo el día.",145,2,17,134,"Los papaquis; El tecolote",0,4,"ia",0,0,-1,0,37,37,"5794","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5796",7,"Cri, cri, cri, cantaba el gallo,\ncri, cri, cri, muy de mañana,\ncri, cri, cri, y sin desmayo,\ncri, cri, cri, con voz timbrada.",135,2,-1,134,"El corral",0,4,"aa",-1,0,-1,0,37,37,"5796","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5797",7,"La güitacocha\nde Margarita\ncanta de noche\ny de mañanita.",145,2,17,134,"La güitacocha",6,4,"ia",50,0,-1,0,37,37,"5797","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5798",7,"Tú conmigo, yo contigo,\nde tu genio recomiendo;\nla chicharrita quiere cantar:\nque sí cantó, que no cantó,\nque cante ahora, que aquí estoy yo.",143,2,18,134,"La chicharra",7,5,"o",2,0,-1,0,38,38,"5798","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5799",7,"Ni con candado y cerrojos\npuedo cerrar la garganta\nde este gallito que canta\ny que despierta a los flojos.",142,2,8,134,"Estrofa suelta",11,4,"oo",99,0,-1,0,38,38,"5799","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5800",7,"Un gallo por la mañana\ndespertando el rancho está;\n¿de quién sacaría estas mañas?\nHay que hacerles madrugar.",135,2,-1,134,"El corral'T",0,4,"a",-1,0,-1,0,38,38,"5800","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5801",7,"Dicen que los gallos\ntambién son adivinos\ncuando salen de cantar\na la orilla de los caminos.",148,2,9,134,"Estrofa suelta",0,4,"io",206,0,-1,0,38,38,"5801","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5802",7,"Debajo de un limón verde\nme dio sueño y me dormí,\ny me despertó un gallito\ncantando quiquiriquí.",149,2,20,134,"El Quelite; El jarabe jaranero",0,4,"i",23,0,-1,0,38,38,"5802","",0,"","","",9,0,0,[],"",""],["frenk_t3-n5803",7,"Ticurús, cus, cus,\nticurús, cus, cus,\n¡qué bonito tecolotito!\nyo me lo quisiera llevar.",135,2,-1,134,"El tecolote",5,4,"a",-1,0,-1,0,38,38,"5803","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5804a",7,"Paseándome por la playa\ny vi a bordo de un vapor;\náhi compré una guacamaya,\ncon su pluma de color\ny en su pecho una medalla.",136,2,4,134,"La guacamaya’",7,5,"aa",249,0,-1,0,38,38,"5804a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5804b",7,"Pasé solo por la plaza\ny vi a bordo de un vapor;\npaseándome por la playa,\náhi compré una guacamaya,\ncon su pluma de color\ny en el pecho una medalla.",136,2,4,134,"La guacamaya",9,6,"aa",249,0,-1,0,38,38,"5804b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5805",7,"Cuando me vine de abajo\nme vine por los esteros,\nme traje un perico loro\nde los meros argüenderos.",143,2,18,134,"El guaco",0,4,"eo",22,0,-1,0,39,39,"5805","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5806a",7,"¡Ay, qué bonita perdiz,\ntan pintita y tan galana!\nMe la regaló un amigo\nen la feria de Santa Ana.",135,2,-1,134,"La perdiz",0,4,"aa",4,0,-1,0,39,39,"5806a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5807",7,"¡Ay, cuán bonita perdiz!,\nlástima que sea tan mula;\nme la regaló un amigo\nde ese pueblo de Sayula.",135,2,-1,134,"La perdiz",0,4,"ua",547,0,-1,0,39,39,"5807","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5808",7,"—[Señora], su jabalí,\ndígame, ¿quién se lo dio?\n—A mí nadie me da nada,\nmi dinero me costó.",137,2,3,134,"El jabalí; El malacate; La perdiz; La rosa; La venadita",0,4,"o",2,0,-1,0,39,39,"5808","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5809",7,"Este torito que traigo\nlo traigo desde Tepango,\ny lo vengo manteniendo\ncon cascaritas de mango.",136,2,4,134,"El torito; Estrofa suelta",0,4,"ao",596,0,-1,0,39,39,"5809","",0,"","","",10,0,0,[],"",""],["frenk_t3-n5810",7,"Este torito que traigo\nlo traigo desde Jalapa,\ny lo vengo manteniendo\ncon pura sopa borracha.",136,2,4,134,"El torito; El toro",0,4,"aa",-1,0,-1,0,39,39,"5810","",0,"","","",10,0,0,[],"",""],["frenk_t3-n5811",7,"Este torito que traigo\nlo traigo desde Campeche,\ny lo vengo manteniendo\ncon pura sopa de leche.",136,2,4,134,"El torito",0,4,"ee",180,0,-1,0,39,39,"5811","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n5812",7,"Este torito que traigo,\nlo traigo de Nueva York,\ny lo vengo manteniendo\ncon cerveza “Superior”.",136,2,4,134,"El torito",0,4,"o",-1,0,-1,0,40,40,"5812","",0,"","","",10,0,0,[],"",""],["frenk_t3-n5813",7,"Este torito que traigo\nlo traigo desde Sayula,\ny lo vengo manteniendo\nen las ancas de mi mula.",136,2,4,134,"El toro",0,4,"ua",547,0,-1,0,40,40,"5813","",0,"","","",10,0,0,[],"",""],["frenk_t3-n5814",7,"Tengo un caballo mesano\nen que me salgo a pasear,\nen el que yo subo y bajo\npara enseñarlo a cambiar.\nSoy puro veracruzano:'\nnunca lo puedo negar.",135,2,-1,134,"El caballito",9,6,"a",21,0,-1,0,40,40,"5814","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5815",7,"Tengo un caballo muy bueno,\nque se llama el Pavorreal;\nése no sabe de freno,\nsabe de puro bozal;\nme paseo en cualquier terreno,\nnunca me hace quedar mal.",141,2,1,134,"El caballito; El caballo",9,6,"a",1,0,-1,0,40,40,"5815","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5816",7,"Subí [al] árbol del sereno\ny a sacudir el rocío.\nAntes montaba lo ajeno,\nhoy sólo monto lo mío;\ntengo un caballo muy bueno,\nnunca se le acaba el brío.",136,2,4,134,"El caballito; Soy fandanguero",9,6,"io",3,0,-1,0,40,40,"5816","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5817",7,"Sólo mi yegüita mora,\nde toda mi caballada,\ntiene una quemadita\nde la crin hasta la cola.",137,2,3,134,"La caballada",5,4,"oa",-1,0,-1,0,40,40,"5817","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5818",7,"En la sombra de un juchital\nme puse a resolanear;\nme dieron para mi silla\nun caballo cardenal,\nme lo dieron por maleta,\ny me ha salido regular.",136,2,4,134,"Un día me fui a pasear; El toro",9,6,"a",-1,0,-1,0,40,40,"5818","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5819a",7,"Ayer compré una tarasca,\nde esas que venden por áhi,\ny como estaba tan flaca,\nno tan sólo comía el maiz:\nhasta los olotes masca.",136,2,4,134,"La tarasca",7,5,"aa",-1,0,-1,0,41,41,"5819a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5820",7,"Yo tenía mi gato blanco\narriba de esa pared;\npor agarrar una rata,\naganó un saltapared.",135,2,-1,134,"El gato’T",0,4,"e",598,0,-1,0,41,41,"5820","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5821",7,"Yo tenía mi gato blanco (mi vida)\narriba de un tendajón;\nestaba aguardando la rata,\npara hacer una función.",135,2,-1,134,"El gato",3,4,"o",31,0,-1,0,41,41,"5821","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5822",7,"Yo tenía un perico loro,\nque cantaba en el vergel,\ny Juanita en la mañana\nle llevaba de comer.",145,2,17,134,"El perico loro",0,4,"e",-1,0,-1,0,41,41,"5822","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5823",7,"Coni, coni, coconito,\nconi, coni, ¿pero cuándo?\nYo le daba su maicito,\nsiempre sí, pero cantando.",136,2,4,134,"El totolito",1,4,"ao",33,0,-1,0,41,41,"5823","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5824",7,"Coni, coni, coconito,\nconi, coni, ¡qué caray!\nYo le daba su maicito,\nantes sí, pero hora no hay.",136,2,4,134,"El totolito",1,4,"a",469,0,-1,0,41,41,"5824","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5825",7,"Yo tenía mi guacamaya,\nque siempre estaba culeca,\ny de tanto estar echada,\nya tenía la cola chueca.",136,2,4,134,"La guacamaya",0,4,"ea",594,0,-1,0,41,41,"5825","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5826",7,"Yo tenía mi guaco Chano,\nyo no lo quería vender;\nallá en la costa me daban\ntrescientos pesos por él.",145,2,17,134,"El guaco",0,4,"e",-1,0,-1,0,41,41,"5826","",0,"","","",5,0,0,[],"",""],["frenk_t3-n5827",7,"Voy a casar mi gallina\ncon un gallo de Jalapa,\npara que salgan los pollos\nvalientes como su papa.",136,2,4,134,"El gallo",0,4,"aa",297,0,-1,0,42,42,"5827","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5828",7,"Voy a comprarle a mi gallo\nuna gallina guinea,\npara que salgan los pollos\nbuenos para la pelea.",136,2,4,134,"El totolito",0,4,"ea",54,0,-1,0,42,42,"5828","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5829",7,"Voy a comprarle a mi gallina\nun gallo recopetón,\npara que salgan los pollos\ncon muy buenos espolones.",136,2,4,134,"El totolito",5,4,"oe",-1,0,-1,0,42,42,"5829","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5830",7,"Voy a casar mi pollita\ncon un gallo de la bola,\npara que nazcan los pollos\ncon un copete en la cola.",135,2,-1,134,"La gallina",0,4,"oa",321,0,-1,0,42,42,"5830","",0,"frenk_t4","","",5,0,0,[],"",""],["frenk_t3-n5831",7,"¡Qué buen caballo tiene\nmi amigo Nicolás!\nCamina pa delante,\ncamina para atrás.",147,2,11,134,"El Colás",0,4,"a",51,0,-1,0,42,42,"5831","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5832",7,"Dicen que este caporal\nmonta un caballo roano,\ncon un lucero en la frente,\ny le llaman el Cubano;\npa correr es el primero\nen las pistas y en los llanos.",135,2,-1,134,"El caporal",9,6,"ao",-1,0,-1,0,42,42,"5832","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5833",7,"Andaba yo trabajando\npor la tierra del Jazmín;\npor estar yo almorzando\nse me fue mi jabalín.",137,2,3,134,"El jabalí",1,4,"i",211,0,-1,0,42,42,"5833","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5834",7,"Andándome yo paseando\nen las orillas del Tajo,\nbuscando mi jabalí,\nque anda por ahí perdido.",135,2,-1,134,"El jabalí",5,4,"io",-1,0,-1,0,42,42,"5834","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5835",7,"Andando yo trabajando\npor la falda de aquel cerro,\nse me fue mi jabalí,\nporque no llevé mi perro.",135,2,-1,134,"El jabalí",0,4,"eo",379,0,-1,0,42,42,"5835","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5837",7,"En una jaula encerré\ndos elegantes perdices;\nmucho las acaricié,\nque muy bastante las quise,\ny el día que menos pensé\nse fueron sin despedirse.",142,2,8,134,"El pájaro cú",9,6,"ie",-1,0,-1,0,43,43,"5837","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5838",7,"Yo tenía una guacamaya\ny amanada por un pie,\ny como era tan canalla,\nse me desató, se fue\nque algún día te agarraré",136,2,4,134,"La guacamaya",7,5,"e",77,0,-1,0,43,43,"5838","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5839",7,"Yo tenía una guacamaya\nen una jaula de lata,\ny la rompió la canalla\ncon el pico y con la pata,\npa comerse una pitaya,\nque reservaba mi tata.",136,2,4,134,"La guacamaya",9,6,"aa",-1,0,-1,0,43,43,"5839","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5840",7,"Ya se me escapó el tejón\ny se fue por la barranca;\ncuando tanto lo quería\nel indino se me escapa;\ntejoncito, te jondeaba,\ndueño de mi corazón.",135,2,-1,134,"El nuevo tejón",9,6,"o",31,0,-1,0,43,43,"5840","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5841",7,"Ya con ésta me despido\nde mi amada Simonita;\nse le fue su guaco Chano\npor causa de Mariquita.",143,2,18,134,"El guaco Chano",0,4,"ia",50,0,-1,0,43,43,"5841","",0,"","","",72,0,0,[],"",""],["frenk_t3-n5842",7,"Yo tenía una perra meada,\nque me la orinó un zorrillo,\nbuena pa la mapachada\ny también pa el armadillo,\ny se me quedó enredada\nen una mata de frijolillo.",136,2,4,134,"Estrofa suelta",9,6,"io",228,0,-1,0,43,43,"5842","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5843",7,"Las nubes cubren el astro,\nya comienza a lloviznar,\ny de la yegua, ni rastro:\nni se le oye relinchar.",135,2,-1,134,"La potranca colorada",1,4,"a",21,0,-1,0,43,43,"5843","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5844",7,"Yo tenía mi conejito,\ny un perro me lo mató;\nno quiero que me lo paguen:\nmi conejo quiero yo.",136,2,4,134,"El conejo",0,4,"o",2,0,-1,0,44,44,"5844","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5845",7,"Yo tenía mi guaco Chano\ndebajo de las anonas;\nse lo comieron las auras:\n¡qué demonio de pelonas!",145,2,17,134,"El guaco",0,4,"oa",549,0,-1,0,44,44,"5845","",0,"","","",5,0,0,[],"",""],["frenk_t3-n5846",7,"Yo tenía mi guaco Chano\ndebajo de la enramada;\nse lo comieron las auras:\n¡qué demonio de peladas!",135,2,-1,134,"El guaco",0,4,"aa",-1,0,-1,0,44,44,"5846","",0,"","","",5,0,0,[],"",""],["frenk_t3-n5847",7,"Yo tenía mi guaco Chano\ndebajo de los zarzales;\nse lo comieron las auras:\n¡qué demonios de animales!",145,2,17,134,"El guaco",0,4,"ae",26,0,-1,0,44,44,"5847","",0,"","","",5,0,0,[],"",""],["frenk_t3-n5848",7,"Se murió mi gallo tuerto:\n¿qué sería de mi gallina?\nQuiquiriquí, cantaba el gallo,\nquiquiriquí, en la cocina.",138,2,6,134,"Estrofa suelta",3,4,"ia",11,0,-1,0,44,44,"5848","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5849",7,"Mi perico se murió,\nmi hermanita lo ha llorado,\nporque tenía el pico de oro\ny el copete colorado.",145,2,17,134,"El perico loro",0,4,"ao",14,0,-1,0,44,44,"5849","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5850",7,"Se llevó mi polla el gavilán pollero,\nmi pollita que más quiero;\nque me sirvan otra copa, cantinero:\nsin mi polla yo me muero.",135,2,-1,134,"El gavilán pollero",3,4,"eo",38,0,-1,0,44,44,"5850","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5851",7,"Dicen que los sapos muerden\nagarrándolos en ’l agua:\nyo agarré uno el otro día,\ny no más los ojos pelaba.",144,2,10,134,"Dicen que los sapos",0,4,"aa",-1,0,-1,0,44,44,"5851","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5852",7,"Dicen que la iguana muerde,\nyo digo que no, que no:\nyo agané una por la cola,\nno más la lengua sacó.",136,2,4,134,"La iguana",0,4,"o",2,0,-1,0,44,44,"5852","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5853",7,"Dicen que la iguana muerde,\nyo digo que no es verdad:\nyo agané una por la cola\ny me la comí en pipián..",147,2,11,134,"Estrofa suelta",0,4,"a",-1,0,-1,0,45,45,"5853","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5854",7,"Dicen que la iguana es verde\ny el pintaco es amarillo;\nyo agarré una por la cola\ny a orillas del ventorrillo.",136,2,4,134,"La iguana",0,4,"io",228,0,-1,0,45,45,"5854","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5855",7,"Dicen que la iguana es verde\ny el pintaco es colorado;\nyo agané una por la cola\nen los llanos de Alvarado.",136,2,4,134,"La iguana",0,4,"ao",14,0,-1,0,45,45,"5855","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5856",7,"Dicen que la iguana muerde,\nyo digo que son guayabas:\nyo agarré una por la cola\ny en los llanos de Orizaba.",136,2,4,134,"La iguana",0,4,"aa",-1,0,-1,0,45,45,"5856","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5857",7,"A las dos de la mañana\nsalen paseando a la iguana;\ntiraron un santo Cristo\npor aganar una iguana.",135,2,-1,134,"La iguana",0,4,"aa",-1,0,-1,0,45,45,"5857","",0,"","","",7,0,0,[],"",""],["frenk_t3-n5858",7,"Si el gavilán se comiera\ncomo se come el ganado,\nyo ya me hubiera comido\nal gavilán colorado.",150,2,24,134,"El gavilán colorado",0,4,"ao",14,0,-1,0,45,45,"5858","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5859",7,"En una cierta ocasión\na un buen conejo seguía,\ny montando un buen caballo\ny por todas partes seguía.",135,2,-1,134,"La ensalada",3,4,"ia",-1,0,-1,0,45,45,"5859","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5860",7,"—Vamos matando a ese gato\nque anda por esa ladera.\n—Ese gato no se mata,\nque es de la niña Severa.",145,2,17,134,"El gato",0,4,"ea",44,0,-1,0,45,45,"5860","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5861",7,"Yo me embarqué en un chalán\npor ir a saber a Texas,\ny al pasar el río Jordán\nun ruido traiban las viejas:\ntraiban al mero caimán,\ny agarrao de las orejas.",138,2,6,134,"El caimán",9,6,"ea",496,0,-1,0,45,45,"5861","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5862",7,"Que yo me arrimé a una laguna\na tirarle una pepexca,\ny me dijo la fortuna:\n“Hombre, déjala que crezca,\nponle de marca una pluma\npara que después parezca”.",136,2,4,134,"Me puse en un espiadero; El Balajú; El pájaro cú; Estrofa suelta",9,6,"ea",346,0,-1,0,46,46,"5862","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5863",7,"Las tortugas allí están,\npero ¿quién las coge? digo,\nporque el bejuco Julián\nes más malo que el de estribo,\ntamañas clavadas dan:\nmira yo cómo he salido.",136,2,4,134,"El siquisirí, Zapateado",9,6,"io",-1,0,-1,0,46,46,"5863","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5864",7,"¡Qué tristes aúllan\nlos coyotes en la selva!\n¡qué tristes cantan\nlos jilgueros en la rama!",143,2,18,134,"La paloma azul",3,4,"aa",-1,0,-1,0,46,46,"5864","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5865",7,"Áhi viene el agua\npor los cerritos,\nque se me mojan\nmis becerritos.",148,2,9,134,"Estrofa suelta",6,4,"io",254,0,-1,0,46,46,"5865","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5866",7,"Unos animalitos\nse mueren de hambre,\nporque son huerfanitos\nde padre y madre.",144,2,10,134,"Los animalitos",6,4,"ae",-1,0,-1,0,46,46,"5866","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5867",7,"La vida del zopilote\nes una vida arrastrada:\ntodo el año vuela y vuela\ncon la cabeza pelada.",135,2,-1,134,"El zopilote",0,4,"aa",49,0,-1,0,46,46,"5867","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5868",7,"El mulato en la barranca\ncanta con todo el esmero,\npero cuando menos piensa\nse lo pesca el pajarero.",135,2,-1,134,"El pajarerito",0,4,"eo",38,0,-1,0,46,46,"5868","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5869",7,"Si la venada supiera\nque hay lazos en la vereda,\nno pasara por ahí,\naunque el peno la mordiera.",135,2,-1,134,"La venadita",0,4,"ea",-1,0,-1,0,46,46,"5869","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5870",7,"Tecurrucú, ricú, ricú,\ntecurricú, ricú, ricú,\npobrecito tecolote,\nya se cansa de llorar.",142,2,8,134,"El tecolote",5,4,"a",-1,0,-1,0,47,47,"5870","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5871",7,"Pobrecita guacamaya,\n¡ay, qué lástima me da!\nSe acabaron las pitayas,\n¡ahora sí qué comerá!",136,2,4,134,"ay, qué lástima me dal Se acabaron las pitayas, ¡ahora sí qué comerá! [La guacamaya",0,4,"a",9,0,-1,0,47,47,"5871","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5872",7,"¡Ay!, revuela, vuela, vuela,\nvuela, vuela para el río:\nverás a la guacamaya\ntirititiando de frío.",136,2,4,134,"La guacamaya",0,4,"io",3,0,-1,0,47,47,"5872","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5873",7,"Pobrecita guacamaya,\nya se cansa de volar:\nse le acabaron las alas\npor andar en el palmar.",136,2,4,134,"La guacamaya",0,4,"a",21,0,-1,0,47,47,"5873","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5874",7,"La cucaracha\nya no puede caminar,\nporque le falta\nsus alas para volar.",135,2,-1,134,"La cucaracha",3,4,"a",21,0,-1,0,47,47,"5874","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5875",7,"Ya se cayó el arbolito\ndonde dormía el pavo real:\nahora dormirá en el suelo\ncomo cualquier animal.",147,2,11,134,"Guadalajara en un llano; El calero",3,4,"a",1,0,-1,0,47,47,"5875","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5876",7,"Señora, sus jabalines\npor áhi los vienen corriendo;\nde miedo de los violines,\nlas colitas van torciendo.",135,2,-1,134,"El jabalí",1,4,"eo",52,0,-1,0,47,47,"5876","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5877",7,"Ya miro que algunas aves\nvan regresando a su nido;\nsaltando entre los breñales\nva un venado presumido,\ny busca en los matorrales\na su cierva que ha perdido.",135,2,-1,134,"Mi cielo huasteco",9,6,"io",101,0,-1,0,47,47,"5877","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5878",7,"El becerro no ha mamado\nporque la vaca no vino,\ny abuelita lo mantiene\ncon basuras del camino.",135,2,-1,134,"El becerro",0,4,"io",199,0,-1,0,48,48,"5878","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5879",7,"Esta muía no es de aquí,\nes del estado de Texas,\ny como ayer no comió,\nno más para las orejas.",135,2,-1,134,"La mulita",3,4,"ea",-1,0,-1,0,48,48,"5879","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5880",7,"Y si el amo te pregunta\npor el machito tordillo,\nle dirás que en Guanajuato\nse murió de tabardillo.",135,2,-1,134,"¡Arre muía, arre macho!",0,4,"io",228,0,-1,0,48,48,"5880","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5881",7,"Y si el amo te pregunta\npor el machito rabón,\nle dirás que en San Felipe\nse murió de sarampión.",135,2,-1,134,"¡Arre muía, arre macho!",0,4,"o",31,0,-1,0,48,48,"5881","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5883",7,"¡Ese gavilán primito,\npequeño y tan volador,\nque se remonta en lo alto\npara echársele al pichón!",135,2,-1,134,"El gavilán colorado",0,4,"o",-1,0,-1,0,48,48,"5883","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5884",7,"Ya se va su gavilán,\nya se va para el potrero;\nse lleva todas las pollas\nque dejó en el gallinero.",136,2,4,134,"El gavilán",0,4,"eo",38,0,-1,0,48,48,"5884","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5885",7,"¿No vistes al gavilán\ncuando se llevó el palomo?\n¡Qué demonio de animal!,\nsi lo agarro me lo como.",142,2,8,134,"El palomo",0,4,"oo",349,0,-1,0,48,48,"5885","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5886",7,"Por áhi dicen que un coyote\nanda venteando el ganado\ny que va a brincar las trancas\ndonde lo tienen guardado.",135,2,-1,134,"La escondida",0,4,"ao",14,0,-1,0,48,48,"5886","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5887",7,"De miedo a ese coyote\nno baja mi chivo al agua:\nayer tarde que bajaba,\npobre chivo, ya le andaba.",137,2,3,134,"¡Uy tara la la!",0,4,"aa",28,0,-1,0,49,49,"5887","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5888",7,"Dicen que el caimán murió\nel día primero de enero;\nde recuerdo nos dejó\nun caimancito al estero;\nvarias pollas se tragó\ny no más dejó el plumero.",138,2,6,134,"El caimán",9,6,"eo",38,0,-1,0,49,49,"5888","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5889",7,"¡Qué caramba!, el gato\nya quiere llorar;\naganó la rata,\nla empezó a matar.",135,2,-1,134,"El gato",0,4,"a",21,0,-1,0,49,49,"5889","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5890",7,"Pobrecito gato,\nno hallaba qué hacer,\nagarró una rata\ny se la empezó a comer.",135,2,-1,134,"El gato",0,4,"e",20,0,-1,0,49,49,"5890","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5891",7,"Préstame tu gato prieto\npara ponerle calzones;\nme lo llevaré a mi casa\npara que coma ratones.",143,2,18,134,"El gato",0,4,"oe",34,0,-1,0,49,49,"5891","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5892",7,"¿Por qué tiene cascabel\nuna víbora traidora?\n¿Por qué es que nos quiere morder\ncuando menea la cola?",142,2,8,134,"Zapateado",0,4,"oa",-1,0,-1,0,49,49,"5892","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5893",7,"Andándome yo paseando\npor la sombra de una higuera,\nno era bulto, no era nada,\nera culebra pollera,\nque me quiso dar un susto,\nla maldita chirrionera.",135,2,-1,134,"La culebra pollera",9,6,"ea",44,0,-1,0,49,49,"5893","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5894",7,"La culebra me picó\nmuy cerquita del pescuezo;\nno me pudieron curar,\nporque era de rabo hueso.",136,2,4,134,"La culebra",0,4,"eo",48,0,-1,0,49,49,"5894","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n5895",7,"La culebra me picó\nmuy cerquita del tobillo;\nno me pudieron curar,\nporque era de coralillo.",136,2,4,134,"La culebra",0,4,"io",228,0,-1,0,49,49,"5895","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n5896",7,"La culebra me picó\nmuy cerquita de la corva;\nno me pudieron curar,\nporque era víbora sorda.",136,2,4,134,"La culebra",0,4,"oa",-1,0,-1,0,50,50,"5896","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n5897",7,"Saca tu machete, chungo,\ny vete pa la barranca,\na ver si contigo sale\nesta culebrita blanca.",135,2,-1,134,"La culebra",0,4,"aa",75,0,-1,0,50,50,"5897","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5898",7,"Saca tu machete, chungo,\ny vete para Cholula,\na ver si contigo sale\nesta culebrita mula.",135,2,-1,134,"La culebra",0,4,"ua",547,0,-1,0,50,50,"5898","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5899",7,"¡Córrele, muchacho, córrele!,\n¡córrele, córrele, por la vereda!,\nporque nos viene alcanzando\nla culebra chirrionera.",137,2,3,134,"La chirrionera",3,4,"ea",-1,0,-1,0,50,50,"5899","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5900",7,"¡Córrele, muchacho, córrele!,\n¡córrele, córrele pa el callejón!,\nporque nos viene alcanzando\nla culebra y el tejón.",137,2,3,134,"La chirrionera",3,4,"o",31,0,-1,0,50,50,"5900","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5901",7,"¡Corran, corran, muchachos, corran!,\nque ya el cangrejo viene llegando,\nafilando su tenacita,\npa ver si alcanza su hueso blando.",135,2,-1,134,"El cangrejo",3,4,"ao",33,0,-1,0,50,50,"5901","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5902",7,"Este animal es el tigre,\nes una fiera muy brava,\nque cuando se enoja brama;\nsi te agarra por allá,\nya no vuelves para acá.",145,2,17,134,"El tigre",7,5,"a",9,0,-1,0,50,50,"5902","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5903",7,"Entre los encinos\nlos lobos aúllan;\ntigres hambrientos (mi vida)\nme vendrán venteando.",135,2,-1,134,"El tigre",5,4,"ao",-1,0,-1,0,50,50,"5903","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5904",7,"Yo por los arroyos\nme voy escondiendo,\ndel miedo del tigre (mi vida):\nme vendrá siguiendo.",135,2,-1,134,"El tigre",0,4,"eo",52,0,-1,0,50,50,"5904","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5905",7,"Áhi por los arroyos\nyo me he venido escapando,\nde miedo del tigre (güerita):\nme venía venteando.",145,2,17,134,"El tigre",0,4,"ao",33,0,-1,0,50,50,"5905","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5906",7,"Yo me embarqué en un chalán,\npa saber al extranjero;\npor las orillas del mar\nme encontré un animalero,\ny entre ellos estaba el caimán,\ntragándose a un jaranero.",141,2,1,134,"El caimán",9,6,"eo",38,0,-1,0,51,51,"5906","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5907",7,"Por la causa del caimán\nno baja mi hija ahora al agua:\nayer tarde que bajó\nya mero se la llevaba.",135,2,-1,134,"La calandria",0,4,"aa",-1,0,-1,0,51,51,"5907","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5908",7,"Ya no vivo en el estero,\nahora vivo en la bahía;\ncuídate bien del caimán,\nteniendo tan duros cueros.",135,2,-1,134,"Las olas de la laguna",5,4,"eo",-1,0,-1,0,51,51,"5908","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5909",7,"Andando de lagartero\nagarré uno por la cola;\nle dije a mi compañero:\n“No dejes la panga sola,\neste caimán es matrero,\nya me reventó la piola”.",139,2,2,134,"El caimán",9,6,"oa",321,0,-1,0,51,51,"5909","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5910",7,"Me dicen que no hay caimán\nen ese río de Horconcitos:\nayer que me fui a bañar\n—iba con mis hermanitos—\nallí encontré al caimán,\ncon caimana y caimancitos.",138,2,6,134,"El caimán",9,6,"io",254,0,-1,0,51,51,"5910","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5911",7,"Canoero del río Arauca,\npásame pa el otro lado,\nque me viene persiguiendo\nel gavilán colorado.",150,2,24,134,"El gavilán colorado",0,4,"ao",14,0,-1,0,51,51,"5911","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5912",7,"Vuela, vuela, vuela,\nvuela para el mar,\ny verás la guacamaya\nque me picó al volar.",136,2,4,134,"La guacamaya",0,4,"a",21,0,-1,0,51,51,"5912","",0,"","","",17,0,0,[],"",""],["frenk_t3-n5913",7,"Guaco, guaco,\nya no hallo qué hacer;\nseñora, amarre su guaco (mi vida),\nque lo quiero conocer.",143,2,18,134,"El guaco",3,4,"e",20,0,-1,0,51,51,"5913","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5914",7,"Señora, amarre su perro,\nporque se lo voy a matar:\ncuando voy para la casa\ny el peno sale a ladrar.",136,2,4,134,"El perro",0,4,"a",21,0,-1,0,51,51,"5914","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5915",7,"Cuando voy para la casa\ny el perro salió ladrando;\nla dueña no me lo espanta,\ny antes me lo estaba usqueando.",136,2,4,134,"El perro",3,4,"ao",33,0,-1,0,52,52,"5915","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5916",7,"“¡Undelé, undelé!”,\nsale la vieja gritando:\n“Yo no sé por qué motivo\nya está mi perro ladrando”.",136,2,4,134,"El perro",0,4,"ao",33,0,-1,0,52,52,"5916","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5917",7,"¡Húyale, húyale!,\n¡húyale: perro, otra vez!\nQue si este perro me muerde,\ntendremos que ver al juez.",136,2,4,134,"El perro",3,4,"e",150,0,-1,0,52,52,"5917","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5918",7,"¡Undelé, undelé!,\n¡undelé; peno valiente!\nQue si este peno me muerde,\nyo le aviso al presidente.",136,2,4,134,"El perro",0,4,"ee",-1,0,-1,0,52,52,"5918","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5919",7,"¡Undelé, undelé!,\n¡undelé; penito blanco!\nQue si este peno me muerde,\nme llevan al camposanto.",136,2,4,134,"El perro",0,4,"ao",-1,0,-1,0,52,52,"5919","",0,"","","",3,0,0,[],"",""],["frenk_t3-n5920",7,"Un novillo despuntado\nde la hacienda de Homobono\na más de cuatro vaqueros\nles ha quitado lo mono.",142,2,8,134,"El novillo despuntado",0,4,"oo",530,0,-1,0,52,52,"5920","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5921",7,"Dicen que ese toro es malo,\nque es muy bravero y muy retozón:\na más de cuatro vaqueros\nles ha quitado lo cachetón.",136,2,4,134,"El toro",3,4,"o",31,0,-1,0,52,52,"5921","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5922",7,"El toro de Las Bajadas\nes un toro muy cenero:\na cualquiera le repara,\naunque le saquen el cuero.",136,2,4,134,"El torito de Las Bajadas",0,4,"eo",38,0,-1,0,52,52,"5922","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5923",7,"Ese toro no es de aquí;\nes del rancho La Parota;\nno más ha venido aquí\na ver qué macho le brota.",146,2,7,134,"El toro",1,4,"oa",432,0,-1,0,52,52,"5923","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5924",7,"Lo que es un toro costeño:\nno se puede ni soltar,\nle conocen hasta el dueño\ny hasta lo quieren comar.",136,2,4,134,"El torito de Las Bajadas",1,4,"a",21,0,-1,0,52,52,"5924","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5925",7,"Paloma blanca, piquito de oro,\nque con tus alas volando vas,\npasas los montes, pasas los ríos,\npasas las olas del ancho mar.",144,2,10,134,"Paloma blanca",3,4,"a",-1,0,-1,0,53,53,"5925","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5926",7,"Blanca paloma, blanca paloma,\npico de coral,\nabre tus alas, abre tus alas\ny échate a volar.",151,2,23,134,"Me siento junto a la peña",3,4,"a",-1,0,-1,0,53,53,"5926","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5927",7,"Vuela, vuela, vuela,\nvuela sin cesar,\nvuela, palomita blanca,\nvuela, pico de coral.",136,2,4,134,"La guacamaya",0,4,"a",-1,0,-1,0,53,53,"5927","",0,"","","",17,0,0,[],"",""],["frenk_t3-n5928",7,"Gorrioncito hermoso,\npico de rubí,\nte traigo una jaula\nde oro para ti.",140,2,12,134,"Estrofa suelta",0,4,"i",23,0,-1,0,53,53,"5928","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5929",7,"Gorrioncito hermoso,\npico de coral,\nte traigo una jaula\nde puro cristal.",140,2,12,134,"Estrofa suelta",0,4,"a",1,0,-1,0,53,53,"5929","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5930",7,"Pajarillo, pajarillo,\npaj arillo bandolero,\ncon ese cantar que tienes\nte pareces al jilguero.",137,2,3,134,"Pajarillo barranqueño; Estrofa suelta",0,4,"eo",38,0,-1,0,53,53,"5930","",0,"","","",9,0,0,[],"",""],["frenk_t3-n5931",7,"Ay, ay, ay, ay, ay, ay, ay,\npajarito jaralero,\nay, ay, ay, ay, ay, ay, ay,\nahora debes cantar.",135,2,-1,134,"Pajarito jaralero",5,4,"a",-1,0,-1,0,53,53,"5931","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5932",7,"En la voz de tu garganta\nhay música mexicana;\ntortolita, canta, canta,\nque tu voz arrulla el alma.",135,2,-1,134,"Canta, canta, tortolita",0,4,"aa",-1,0,-1,0,54,54,"5932","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5933",7,"Tortolita cantadora,\nque a pesar de la calor,\nme sigues acompañando\ncon tu amorosa canción,\nmientras la yunta sestea\ny se me seca el sudor.",135,2,-1,134,"La tortolita",9,6,"o",-1,0,-1,0,54,54,"5933","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5934",7,"Gualupita, que ayer tarde\ncantaste en el ciprés,\nayer cantaste solita\ny ahora cantas otra vez.",135,2,-1,134,"El turruntuntún",3,4,"e",150,0,-1,0,54,54,"5934","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5935",7,"Pajarito, que a la fuente\nibas contento a abrevar,\nya te cortaron las alas,\ny ya no puedes volar.",135,2,-1,134,"Estrofa suelta",0,4,"a",21,0,-1,0,54,54,"5935","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5936",7,"Pobre de ti, chupaflor,\nhasta lástima me das:\ncuando se seque esta flor,\nya veré qué chuparás.",152,2,13,134,"Estrofa suelta",1,4,"a",51,0,-1,0,54,54,"5936","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5937",7,"Ándale, guacamayita,\ndeja de tanto volar:\nse acabaron las pitayas,\nya no las podrás hallar.",135,2,-1,134,"La guacamaya",0,4,"a",21,0,-1,0,54,54,"5937","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5938",7,"Zanato, no eres de aquí,\nzanato, eres forastero;\n¡ándale, anda, vete\npara tu comedero!",140,2,12,134,"Estrofa suelta",0,4,"eo",38,0,-1,0,54,54,"5938","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5939",7,"¿Qué pajarillo es aquel,\nque canta en aquella torre?\nAnda, dile que no cante,\nque hasta la barranca se oye,",145,2,17,134,"Pajarillo barranqueño",0,4,"oe",-1,0,-1,0,54,54,"5939","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5940",7,"Parece que lleva el aire\nun gavilán temido;\ngavilancito, no vuele más;\nvolaba de su nido.",135,2,-1,134,"El gavilancito",3,4,"io",101,0,-1,0,54,54,"5940","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5941",7,"Vuela, vuela, vuela, perico,\nvete a la tierra caliente;\nhuye, huye, huye, perico,\nhuye, huye, húyete de la gente.",135,2,-1,134,"El perico",1,4,"ee",15,0,-1,0,55,55,"5941","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5942a",7,"Huye, huye, animalito,\nhuye, huye, animalote;\nno se volverá a comer\notra gallina el coyote.",142,2,8,134,"El cascabel",0,4,"oe",292,0,-1,0,55,55,"5942a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5942b",7,"Huye, huye, animalito,\nhuye, huye, animalote,\nque ahora se va a comer\notra gallina el coyote,\nque si acaso se la come,\nserá de los más grandotes.",136,2,4,134,"El cascabel",9,6,"oe",-1,0,-1,0,55,55,"5942b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5943",7,"Ya no me cantes, cigarra,\nque acabe tu sonsonete,\nque tu canto aquí en el alma\ncomo un puñal se me mete,\nsabiendo que cuando cantas\npregonando vas tu muerte.",135,2,-1,134,"La cigarra",9,6,"ee",-1,0,-1,0,55,55,"5943","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5944",7,"Canta, canta, tortolita,\npero canta más y más;\ntú que cantas a la vida,\nahora cántale a la mía,\na la mía, que se va.",135,2,-1,134,"Canta, canta, tortolita",7,5,"a",-1,0,-1,0,55,55,"5944","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5945",7,"Me ves de un lado,\nme ves del otro;\n]ay, tejoncito!,\nya te conozco.",135,2,-1,134,"El nuevo tejón",6,4,"oo",-1,0,-1,0,55,55,"5945","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5946",7,"Viborita de la mar,\nno me vayas a picar\nal pie de una mata en caña,\ny me vayas a acabar.",135,2,-1,134,"Viborita de la mar",0,4,"a",21,0,-1,0,55,55,"5946","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5947",7,"Viborita, viborita,\nviborita, viborón,\n¿cómo no me picas hora,\nque vengo de la Misión?",139,2,2,134,"La viborita",0,4,"o",31,0,-1,0,55,55,"5947","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n5948",7,"Viborita, viborita,\nviborita coralilla,\n¿cómo no me picas hora,\nque vengo de Jilitlilla?",139,2,2,134,"La viborita",0,4,"ia",162,0,-1,0,55,55,"5948","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5949",7,"Viborita, viborita,\nviborita mahuaquite,\n¿cómo no me picas hora,\nque vengo de Chalahuite?",139,2,2,134,"La viborita",0,4,"ie",315,0,-1,0,55,55,"5949","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n5950a",7,"Que te pongo el pie,\ny no me haces na;\nque te pisoteo,\ny no me haces na,\nculebra de Tonalá.",135,2,-1,134,"La culebra",7,5,"a",9,0,-1,0,56,56,"5950a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5951",7,"Vuela, palomita,\nvuela, como yo volé,\nde Veracruz a La Habana\ny de La Habana a San Andrés.",136,2,4,134,"La guacamaya",0,4,"e",-1,0,-1,0,56,56,"5951","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5954",7,"Pica, pica, pica, perico,\npica, pica, pica la rama;\npica, pica, pica, perico,\npica, pica, pica tu nana.",145,2,17,134,"El jarabe; El perico",0,4,"aa",-1,0,-1,0,56,56,"5954","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5955",7,"Guajito, a mí sí,\nmétete por aquí;\nguajito, a mí ya,\nmétete por acá.",135,2,-1,134,"El guajito",5,4,"a",9,0,-1,0,56,56,"5955","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5956",7,"A la medianía de un llano\nvide aullando un coyote;\nle dije: “Animal tirano,\n¿por qué no te vas al trote?”\nTú no tienes quién te arree,\nni tienes quién te eche azote.",136,2,4,134,"El cascabel",9,6,"oe",292,0,-1,0,56,56,"5956","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5957",7,"De la punta de aquel cerro\nvide bajar un tejón;\nél que me zampa carrera,\ny yo que le digo: “Epa, cabrón”.",142,2,8,134,"Estrofa suelta",3,4,"o",31,0,-1,0,56,56,"5957","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5958",7,"Salta pa arriba,\nsalta pa afuera,\nsalta, tejón\nde la tejonera.",143,2,18,134,"El tejón",6,4,"ea",44,0,-1,0,57,57,"5958","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5959",7,"Salta pa arriba,\nsalta pa abajo,\nsalta de joyo,\ntejón de atajo.",143,2,18,134,"El tejón",6,4,"ao",168,0,-1,0,57,57,"5959","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5960",7,"Brinca pa aniba,\nbrinca pa abajo,\nya te amolates,\ntejón de abajo.",135,2,-1,134,"El tejón",6,4,"ao",-1,0,-1,0,57,57,"5960","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5961",7,"¡Ándale, gato, bríncale, gato!,\nagárrame ese ratón;\n¡ándale, gato, y ándale pues!,\nque ya se metió al rincón!",135,2,-1,134,"El gato",3,4,"o",31,0,-1,0,57,57,"5961","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5963",7,"¡Arre alante, vaca pinta!,\nno te apartes del camino;\npa mí que traes compromiso\ncon algún toro ladino.",147,2,11,134,"El arreo",0,4,"io",-1,0,-1,0,57,57,"5963","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5964",7,"¡Corre, corre, caballito!,\n¡corre por esa vereda!\nEste caballo no corre\nporque le falta pastura.",136,2,4,134,"El caballo",5,4,"ua",-1,0,-1,0,57,57,"5964","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5965",7,"¡Corre, corre, caballito!,\n¡corre por ese potrero!,\ncorre, que vamos llegando\nen casa de don Sotero.",136,2,4,134,"El caballito",0,4,"eo",38,0,-1,0,57,57,"5965","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5966",7,"¡Corre, corre, caballito,\ncon ese paso ligero!,\nque tenemos que llegar\na la hacienda de Guerrero.",140,2,12,134,"El caballito",0,4,"eo",38,0,-1,0,57,57,"5966","",0,"","","",4,0,0,[],"",""],["frenk_t3-n5967",7,"Zopilote, dile al aura\nque ponga al quelele alerta,\nque abajo del ojo de agua\nestá la vaquilla muerta.",135,2,-1,134,"¡Arre muía, arre macho!; Cuando la muía relincha] [La vaquilla; El zopilote",0,4,"ea",267,0,-1,0,57,57,"5967","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5968",7,"Le dirás a la vaquilla\nque se baje para el plan,\nporque se le muere de hambre\nel becerro Gavilán.",145,2,17,134,"La vaquilla",0,4,"a",147,0,-1,0,58,58,"5968","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n5969",7,"Le dirás a la vaquilla\nque se baje del mogote,\nporque se le muere de hambre\nel becerro Capirote.",145,2,17,134,"La vaquilla",0,4,"oe",292,0,-1,0,58,58,"5969","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n5971",7,"Le dirás a la vaquilla\nque se baje pa el estero,\npara darle mamantones\na ese becerro grupero.",135,2,-1,134,"La vaquilla",0,4,"eo",38,0,-1,0,58,58,"5971","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5972",7,"Le dirás a la vaquilla\nque no se ande ladereando,\nque un becerro trae al pie\ny otro se le anda ahijando.",135,2,-1,134,"La vaquilla",0,4,"ao",33,0,-1,0,58,58,"5972","",0,"","","",8,0,0,[],"",""],["frenk_t3-n5973a",7,"La sirena se embarcó\nen un buque de madera\ny a medio mar se quedó\ncantando “La Petenera”.",141,2,1,134,"La Petenera",1,4,"ea",44,0,-1,0,62,62,"5973a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5974",7,"Viniendo de mar afuera,\nme encontré un viento muy fiero;\nvide venir la sirena\nnavegando por’l estero,\ncantando esta “Petenera”\ny hablándole a un marinero.",139,2,2,134,"La sirena",9,6,"eo",38,0,-1,0,62,62,"5974","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5975",7,"Petenera, ¡ay, Petenera!,\n¡quién te pudiera cantar!\nOjalá que yo pudiera\nsiquiera medio entonar,\ncomo canta la sirena\ncuando sale a Miramar.",138,2,6,134,"La Petenera",9,6,"a",21,0,-1,0,62,62,"5975","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5976",7,"Desde Veracruz salió\nuna ballena arponeada;\ncuando a Tampico llegó\nle dijo al pez de espadas\n“Ya la sirena cantó\ny una preciosa tonada”.",136,2,4,134,"La Petenera",9,6,"aa",-1,0,-1,0,62,62,"5976","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5977a",7,"Donde habita una sirena\nhay una hondura en el mar;\nun marinero, al pasar\nvíspera de Nochebuena,\ndice que la oyó cantar:\n“La pena y la que no es pena”.",136,2,4,134,"La Petenera",9,6,"ea",59,0,-1,0,62,62,"5977a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5977b",7,"En el mar está un lugar\ndonde habita la sirena;\nun marinero, al pasar,\ndice que de noche era;\ndicen que la oyó cantar\napenas al amanecer,\naunque no la pudo ver.",136,2,4,134,"‘‘La morena",4,7,"e",20,0,-1,0,63,63,"5977b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5978",7,"Y habita una sirenita,\nhay una hondura en el mar;\nun marinero, al pasar\nun día muy de mañanita\ndicen que la oyó cantar\nuna canción muy bonita.",136,2,4,134,"La Petenera",9,6,"ia",50,0,-1,0,63,63,"5978","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5979",7,"Navegando en alta mar,\noí cantar una sirena,\ny yo me puse a escuchar\nlos versos de una cadena\nque cantaba sin cesar.",138,2,6,134,"La sirena; La Petenera",7,5,"a",21,0,-1,0,63,63,"5979","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5980",7,"Es cosa muy temerosa\nel rugido de la mar;\n¡ay, qué serafina diosa!,\nsi quieres ir a escuchar,\nen el centro de una fosa\nla sirena irá a cantar.",136,2,4,134,"La Petenera",9,6,"a",21,0,-1,0,63,63,"5980","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5981",7,"La sirena les cantó\nentre su pulida aldea;\nsi la quieres retratar\ncon tinta, papel de oblea,\nen las alturas del mar,\nen donde ella se pasea.",136,2,4,134,"La Petenera",9,6,"ea",54,0,-1,0,63,63,"5981","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5982",7,"Al gorrión hermoso\ndel buche encamado\nse lo llevan preso\npor enamorado.",144,2,10,134,"El gorrión hermoso",0,4,"ao",14,0,-1,0,63,63,"5982","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5983",7,"Al gorrión hermoso\ndel buche amarillo\nse lo llevan preso\nporque era muy pillo.",144,2,10,134,"El gorrión hermoso",0,4,"io",228,0,-1,0,63,63,"5983","",0,"","","",2,0,0,[],"",""],["frenk_t3-n5984",7,"Miren, ya se va\nel gavilán del Sur,\ny ya se llevó\nla paloma azul.",139,2,2,134,"El gavilán del Sur",0,4,"u",-1,0,-1,0,63,63,"5984","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5985",7,"Miren, ya llegó\nel gavilán del Sur,\ny se enamoró\nla paloma azul.",139,2,2,134,"El gavilán del Sur",0,4,"u",-1,0,-1,0,63,63,"5985","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5986",7,"Pobrecita de la polla:\ncomo se vido solita,\nse fue para Zapotlán;\nse la llevó el gavilán,\ncon su vestido de seda,\nvestida de capitán.",135,2,-1,134,"Estrofa suelta",9,6,"a",147,0,-1,0,64,64,"5986","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5987",7,"El caimán cuando soltero\nera muy enamorado,\ny como tenía dinero,\nnunca era despreciado;\nse mantenía en el estero\ncomiendo puro pescado.",138,2,6,134,"El caimán",9,6,"ao",14,0,-1,0,64,64,"5987","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5988",7,"Este es el caimán de Texas,\nque pasó por Tamaulipas;\nallá dieron unas quejas:\nque se lleva a las pollitas,\ny hasta las gallinas viejas.",138,2,6,134,"El caimán",7,5,"ea",496,0,-1,0,64,64,"5988","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5989",7,"Una tortuga\nen el arenal\nsalió preñada\nde Pancho Real.",145,2,17,134,"La carreta",6,4,"a",1,0,-1,0,64,64,"5989","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5990a",7,"El caimán se fue a la playa,\nno supo lo que fue a hacer,\npero vino a proceder:\nenamoró la cuñada,\nhermana de su mujer.",138,2,6,134,"El caimán",7,5,"e",20,0,-1,0,64,64,"5990a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5990b",7,"El caimán en la paseada\nno pudo retroceder;\npor una mala tanteada,\nno supo lo que hay que hacer,\nsi enamorar su cuñada,\nla hermana de su mujer.",139,2,2,134,"El caimán",9,6,"e",20,0,-1,0,64,64,"5990b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5991",7,"El querreque se murió,\ndejó muy buena a la viuda;\npues su suegra le lloró\ncuando ya se lo llevaron\nallí pa la sepultura.",139,2,2,134,"El querreque",7,5,"ua",-1,0,-1,0,64,64,"5991","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5992",7,"Una mona en la serranía\nse enamoró de un mono;\nandaba con su porfía\nde ponerle su corona,\ny así de besarla algún día.",139,2,2,134,"La mona",7,5,"ia",0,0,-1,0,64,64,"5992","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5994",7,"En caminos de mi tierra\nme encontré un toro bramando,\npues estaba una becerra,\nque lo estaba enamorando.",136,2,4,134,"El torito de Las Bajadas",1,4,"ao",33,0,-1,0,65,65,"5994","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5995",7,"Y de rama en rama\ny de flor en flor,\ncanta un paj arillo\nrendido de amor.",136,2,4,134,"Estrofa suelta, Naranjas y limas",0,4,"o",72,0,-1,0,65,65,"5995","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5996",7,"Cuando la chuparrosa\ntoma su vuelo,\nlas flores se marchitan\ny caen al suelo;\ny si oyen decir\nque la chuparrosa vuelve,\nvuelven a abrir.",141,2,1,134,"El ausente",4,7,"i",157,0,-1,0,65,65,"5996","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5997",7,"Si yo fuera tecolote,\nno me ocuparía en volar;\nme estaría en mi nidito,\nacabándome de criar.",142,2,8,134,"El tecolote",0,4,"a",21,0,-1,0,65,65,"5997","",0,"","","",1,0,0,[],"",""],["frenk_t3-n5998",7,"La sirena de la mar\nme dicen que sale a tierra;\nyo la quisiera encontrar,\npa que una lección me diera\npara eso de enamorar,\nsin que nadie lo supiera.",138,2,6,134,"La Petenera",9,6,"ea",44,0,-1,0,65,65,"5998","",0,"","","",7,0,0,[],"",""],["frenk_t3-n5999",7,"La sirena de la mar\nme dicen que es muy bonita;\nyo la quisiera encontrar,\npa besarle su boquita,\npero como es animal,\nno se puede naditita.",139,2,2,134,"La Petenera; La sirena",9,6,"ia",50,0,-1,0,65,65,"5999","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6000",7,"Voy a empezar a cantar,\naunque sin voz deliciosa,\npero les voy a explicar\ncómo yo curé a su diosa\nen las alturas del mar,\nque es cosa muy temerosa.",136,2,4,134,"La Petenera",9,6,"oa",63,0,-1,0,65,65,"6000","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6001",7,"Ya no voy al ancho mar,\npor miedo del tiburón;\nme llegó la invitación;\nConchita se va a casar\ncon el novio Camarón.",139,2,2,134,"Las conchitas",7,5,"o",31,0,-1,0,65,65,"6001","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6002",7,"Estaban dos tortolitos\narrullándose en su nido;\npor más señas que les hice,\nse hicieron desentendidos.",142,2,8,134,"La Zandunga",0,4,"io",-1,0,-1,0,66,66,"6002","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6003",7,"Andaba la chachalaca\npor las orillas del cerro,\nandaba de enamorada\ncon el pájaro jilguero.",135,2,-1,134,"La chachalaca",0,4,"eo",-1,0,-1,0,66,66,"6003","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n6004",7,"Andaba la chachalaca\npor las orillas del llano,\nandaba de enamorada\ncon el pájaro paisano.",135,2,-1,134,"La chachalaca",0,4,"ao",81,0,-1,0,66,66,"6004","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n6005",7,"Andaba la chachalaca\npor las orillas del monte,\nandaba de enamorada\ncon el pájaro zinzontle.",135,2,-1,134,"La chachalaca",0,4,"oe",-1,0,-1,0,66,66,"6005","",0,"","","",10,0,0,[],"",""],["frenk_t3-n6006",7,"Andaba la chachalaca\npor las orillas del río,\nandaba de enamorada\ncon el pájaro tildío.",135,2,-1,134,"La chachalaca",0,4,"io",3,0,-1,0,66,66,"6006","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n6007",7,"Andaba la chachalaca\ncon una patita chueca:\nes que estaba enamorada\nde don Antonio Güereca.",146,2,7,134,"La chachalaca",0,4,"ea",594,0,-1,0,66,66,"6007","",0,"","","",10,0,0,[],"",""],["frenk_t3-n6008",7,"Andaba la chachalaca\npaseándose en San Miguel:\nes que estaba enamorada\nde doña Concha Michel.",146,2,7,134,"La chachalaca",0,4,"e",32,0,-1,0,66,66,"6008","",0,"","","",10,0,0,[],"",""],["frenk_t3-n6009",7,"Estaba la chachalaca\nsentada en una ramita,\ny el picaro chachalaco\nle meneaba la colita.",142,2,8,134,"La chachalaca",0,4,"ia",50,0,-1,0,66,66,"6009","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6010",7,"Estaba un triste coyote\nenamorando una tuza;\nde tanto que la quería,\nhasta se le iba de bruza.",135,2,-1,134,"La tuza",0,4,"ua",599,0,-1,0,66,66,"6010","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6011",7,"Estaba la tuza, estaba,\nsentada en el canapé,\ny el picaro del tucillo,\ndiciéndole no sé qué.",135,2,-1,134,"La tuza",0,4,"e",77,0,-1,0,66,66,"6011","",0,"frenk_t4","","",9,0,0,[],"",""],["frenk_t3-n6012",7,"Estaba la tuza, estaba\nescondid[a] en un terrado,\ny el pícaro del tucillo,\nechándosela de lado.",135,2,-1,134,"La tuza",0,4,"ao",14,0,-1,0,67,67,"6012","",0,"","","",9,0,0,[],"",""],["frenk_t3-n6013",7,"Estaba la tuza sentada,\nsentadita en un balcón,\ny el picaro del tucito\nle jaló su camisón.",142,2,8,134,"La tuza",0,4,"o",31,0,-1,0,67,67,"6013","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6014",7,"La paloma y el palomo\nvivían en un palo hueco;\nla paloma está preñada,\nel palomo está culeco.",142,2,8,134,"El palomo",0,4,"eo",320,0,-1,0,67,67,"6014","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6015",7,"Volaron cuatro palomas,\nvolaron al palo hueco;\nla paloma está cebada,\ny el palomo está culeco.",146,2,7,134,"El palomo",0,4,"eo",320,0,-1,0,67,67,"6015","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6016",7,"Una ranita esperando,\nesperando a su sapito;\ncuando el sapito llegó,\nuno, dos, tres, cuatro, cinco.",147,2,11,134,"La Sanmarqueña",0,4,"io",-1,0,-1,0,67,67,"6016","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6017",7,"Una noche muy oscura\ny oí un grito de repente:\nla querreca estaba mal,\ntenía un dolor en la frente;\nel querreque la curaba\ncon saliva y aguardiente.",139,2,2,134,"El querreque",9,6,"ee",15,0,-1,0,67,67,"6017","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6018",7,"El palomo y la paloma\nse fueron a presentar;\nsalieron primos hermanos,\nno se pudieron casar.",136,2,4,134,"El palomo",0,4,"a",21,0,-1,0,67,67,"6018","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6019",7,"La paloma y el palomo\nse fueron a presentar;\nla paloma salió mocha,\ny el palomo, federal.",144,2,10,134,"El palomo",0,4,"a",-1,0,-1,0,67,67,"6019","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6020",7,"La paloma y el palomo\nse fueron a confesar;\ndel camino se volvieron,\nporque no sabían rezar.",139,2,2,134,"El jarabe",0,4,"a",21,0,-1,0,67,67,"6020","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6021",7,"El palomo y la paloma\nse fueron un día a misa:\nla paloma, reza y reza,\ny el palomo, risa y risa.",136,2,4,134,"El palomo; El jarabe; La Sanmarquefia; Estrofa suelta",3,4,"ia",68,0,-1,0,68,68,"6021","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6022",7,"El cuervo en una ladera\nllora sin comparación,\nporque la cuerva no quiso\nvestirlo de pantalón.",145,2,17,134,"El cuervo’",0,4,"o",31,0,-1,0,68,68,"6022","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6024",7,"Estaba la tuza, estaba\nsentadita en un rincón,\ny el picaro del tucillo,\nhaciéndose el dormilón.",145,2,17,134,"La tuza",0,4,"o",31,0,-1,0,68,68,"6024","",0,"frenk_t4","","",9,0,0,[],"",""],["frenk_t3-n6025",7,"Estaba la tuza, estaba\ndormida en su blando lecho,\ny el picaro del tucillo,\ndándose golpes de pecho.",135,2,-1,134,"La tuza",0,4,"eo",60,0,-1,0,68,68,"6025","",0,"","","",9,0,0,[],"",""],["frenk_t3-n6026",7,"Y estaba la tuza haciendo\npara el tuzo una camisa;\nla tuza estaba en la escuela,\ny el tuzo estaba en la esquina.",136,2,4,134,"La tuza",0,4,"ia",-1,0,-1,0,68,68,"6026","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6027",7,"Dicen que ya no hay caimán\nen ese río de San Juan:\nayer que me fui a bañar\ncon mi querida Juliana,\n¡ay, mamá, qué feo animal\nbailando con la caimana!",135,2,-1,134,"El caimán",9,6,"aa",4,0,-1,0,68,68,"6027","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6028",7,"El caimán que no es de acuerdo\ndonde quiera ha de perder;\nyo lo vide en el Mar Negro,\ny a aquello de amanecer,\npeleándose con el suegro\npor culpa de la mujer.",139,2,2,134,"El caimán",9,6,"e",20,0,-1,0,68,68,"6028","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6029",7,"El caimán ya está muy viejo,\npero así se anda casando;\norillas de un pueblo viejo\nla boda está festejando;\nen la casa del cangrejo\nlas jaibas están guisando.",138,2,6,134,"El caimán",9,6,"ao",33,0,-1,0,69,69,"6029","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6030",7,"El caimán está muy flaco,\nno se puede mantener:\nse sienta y empieza a ver,\nla carne en el garabato,\nsin podérsela comer.",138,2,6,134,"El caimán",7,5,"e",20,0,-1,0,69,69,"6030","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6031",7,"Yo vi a un gato grosero\nen compañía de una zorra;\nbebiendo andaban de gorra\nen casa de un tabernero.",146,2,7,134,"Estrofa suelta",11,4,"eo",38,0,-1,0,69,69,"6031","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6032",7,"Con ésta ya se despide\ncon su canto el cardenal,\nque se desplegó del nido\npor un trago de mezcal.",135,2,-1,134,"Las mañanitas",0,4,"a",1,0,-1,0,69,69,"6032","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6033",7,"La guacamaya se fue\na buscar su guacamayo,\ny lo encontró echando copas (negrita)\ncon su amigo el papagayo.",135,2,-1,134,"La guacamaya",3,4,"ao",293,0,-1,0,69,69,"6033","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6034",7,"Estaba la tuza, estaba\nparadita en una esquina,\ny el picaro del tucillo,\nadentro de la cantina.",136,2,4,134,"La tuza",0,4,"ia",11,0,-1,0,69,69,"6034","",0,"frenk_t4","","",9,0,0,[],"",""],["frenk_t3-n6035",7,"Tan, tan, tan, que toca la puerta,\ntilín, tilín, que no tiene chapa;\ntan, tan, que será la tuza,\ntuza que viene borracha.",136,2,4,134,"La tuza",3,4,"aa",-1,0,-1,0,69,69,"6035","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6036",7,"Tan, tan, que tocan la puerta,\ntilín, tilín, que no tiene llave;\ntan, tan, que será la tuza,\ntuza que viene del baile.",136,2,4,134,"La tuza",3,4,"ae",-1,0,-1,0,69,69,"6036","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6037",7,"Dicen que no hay caimán\nen el río de La Mesa:\nayer que me fui a bañar\ncon mi comadre Teresa,\nallá me encontré al caimán,\nborrachito de cerveza.",139,2,2,134,"El caimán",9,6,"ea",108,0,-1,0,70,70,"6037","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6038",7,"La güitacocha de Nacha\nno canta ya de borracha;\n¡qué diablo de cucaracha!,\nno más de olerlo se empacha.",145,2,17,134,"La güitacocha",0,4,"aa",556,0,-1,0,70,70,"6038","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6039",7,"Una guacamaya pinta\nespiaba que amaneciera,\npara darse un agarrón,\ncon un pájaro cualquiera.",145,2,17,134,"El palo verde",0,4,"ea",44,0,-1,0,70,70,"6039","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6040",7,"El querreque en Jilitlilla\nme quiso pegar por malo:\nme tiró con una silla,\ny por poco se la agarro,\npero me fui como ardilla,\nbrincando de palo en palo.",141,2,1,134,"El querreque",9,6,"ao",-1,0,-1,0,70,70,"6040","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6041",7,"Un querreque allá en Tampico\nse mantenía de ratero;\nse encontró con un viejito,\nque andaba de carbonero;\nle robó su carboncito\ny todito su dinero.",139,2,2,134,"El caimán",9,6,"eo",38,0,-1,0,70,70,"6041","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6042",7,"Un león en su tribunal\ndio el imperio de su ley,\nporque quería ser el rey\nde todo mundo animal.",142,2,8,134,"Estrofa suelta",11,4,"a",1,0,-1,0,70,70,"6042","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6043",7,"La águila, siendo animal,\nse retrató en el dinero;\npara subir al nopal\npidió permiso primero.",147,2,11,134,"Guadalajara en un llano; Estrofa suelta",1,4,"eo",38,0,-1,0,70,70,"6043","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6044",7,"Allá en el monte\nvi un viejo zopilote,\nque hacía capote\ncon la pluma de un guajolote.",142,2,8,134,"Estrofa suelta",3,4,"oe",292,0,-1,0,70,70,"6044","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6045",7,"El tarachi es como el león:\nanda por las sabanillas,\ny en su casa no le falta\nel queso y la mantequilla.",148,2,9,134,"El tarachi",0,4,"ia",-1,0,-1,0,71,71,"6045","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6046",7,"El tarachi es como el león:\nsabe la ceca y la meca,\ny en su casa no le falta\nla carnita y la manteca.",148,2,9,134,"El tarachi",0,4,"ea",594,0,-1,0,71,71,"6046","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6047a",7,"Ayer que me fui a bañar\nen la poza del otate,\nme pasé pa el otro lado;\nallí conocí el caimán,\nbañándose con mecate.",138,2,6,134,"El caimán",7,5,"ae",384,0,-1,0,71,71,"6047a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6048",7,"Por áhi viene la potranca,\ncon su sombrero de lado,\ndiciéndole a los vaqueros\nque si bailan zapateados.",142,2,8,134,"La potranquita",0,4,"ao",-1,0,-1,0,71,71,"6048","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6049",7,"Tan, tan, que tocan la puerta.\ntilín, tilín, que la voy a abrir;\ntan, tan, que será la tuza,\ntuza que viene a dormir.",136,2,4,134,"La tuza; La tortolita",3,4,"i",157,0,-1,0,71,71,"6049","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6050",7,"Tan, tan, que tocan la puerta,\nse la estoy abriendo;\n¿si será la tuza, tuza,\nque viene durmiendo?",136,2,4,134,"La tuza",0,4,"eo",52,0,-1,0,71,71,"6050","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6051",7,"Tan, tan, que será la tuza,\ntuza, tucita, tuza, tuzando;\ntan, tan, que será la tuza,\ntuza, que viene durmiendo.",136,2,4,134,"La tuza",3,4,"eo",-1,0,-1,0,71,71,"6051","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6052",7,"Tan, tan, que toca la puerta,\ntilín, tilín, ¿por qué está tan dura?\nTan, tan, que será la tuza,\nla tuza, que trae basura.",136,2,4,134,"La tuza",3,4,"ua",-1,0,-1,0,72,72,"6052","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6053",7,"Una querreca anidó\ny en la cerca de mi casa;\nsalieron tres querrequitos,\nsalieron de mala raza;\ncomo no los educó,\nhoy son rebeldes sin causa.",139,2,2,134,"El querreque",9,6,"aa",-1,0,-1,0,72,72,"6053","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6054",7,"Voy a casar mi gallina\ncon un gallo de la Veta,\npara que saque los pollos\ncon chinos y con peineta.",144,2,10,134,"La gallina",0,4,"ea",200,0,-1,0,72,72,"6054","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6055",7,"Voy a casar mi gallina\ncon un gallo copetón,\npara que salgan los pollos\ncon chaqueta y pantalón.",137,2,3,134,"La gallina; El gallo; Naranjas y limas",0,4,"o",31,0,-1,0,72,72,"6055","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6056",7,"Voy a casar mi pollita\ncon un gallo de Durango,\npara que nazcan los pollos\ntemplados para el fandango.",135,2,-1,134,"La gallina",0,4,"ao",596,0,-1,0,72,72,"6056","",0,"frenk_t4","","",5,0,0,[],"",""],["frenk_t3-n6057",7,"Del cerro viene bajando\nun desesperado león;\ncon las uñas viene arando,\npor sacar un corazón\nque lo tiene aquí penando.",153,2,5,134,"Estrofa suelta",7,5,"ao",33,0,-1,0,72,72,"6057","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6058",7,"Cuatro palomas azules\nparadas en un balcón,\ny la más chiquita dice\nque le duele el corazón.",136,2,4,134,"El palomo",0,4,"o",31,0,-1,0,72,72,"6058","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6059",7,"Un jilguero en su aposento\narmonía en el campo daba;\ndecía que estaba contento:\nsólo él sabía cómo estaba,\nherido de un sentimiento,\nque todo lo lastimaba.",142,2,8,134,"Estrofa suelta",9,6,"aa",28,0,-1,0,72,72,"6059","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6060",7,"La golondrina en el viento\nplatica con el avión,\nle cuenta los sentimientos\nque abriga su corazón.",154,2,28,134,"Camino real de Colima",0,4,"o",31,0,-1,0,73,73,"6060","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6061",7,"El cuervo en una ladera\nlloraba su soledad,\nporque la cuerva no quiso\ndarle de amor caridad.",145,2,17,134,"El cuervo",0,4,"a",16,0,-1,0,73,73,"6061","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6062",7,"Un cuervo en una ladera\nlloraba sin compasión,\nporque la cuerva no quiso\nquererlo sin compasión;\nle dije a mi corazón:\n“Que me llevan prisionero\npara la villa de León”.",135,2,-1,134,"Estrofa suelta",4,7,"o",31,0,-1,0,73,73,"6062","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6063",7,"El querreque está perdido\npor andar de enamorado;\ntiene el corazón herido,\nque todito le causa enfado,\npor una mujer que ha querido.",139,2,2,134,"El querreque",7,5,"io",101,0,-1,0,73,73,"6063","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6064",7,"Sobre sufriendo\nel coyote se quedó,\nde ver que con la tucita\nnada se le concedió:\nse fue por siempre adiós,",135,2,-1,134,"La tuza",7,5,"o",-1,0,-1,0,73,73,"6064","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6065",7,"Este cuervito\nya se emborrachó,\npor una paloma\nque lo abandonó.",144,2,10,134,"El cuervito",6,4,"o",2,0,-1,0,73,73,"6065","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6066",7,"Suni, suni, suni, la zopilotita,\nsuni, suni, suni, se fue para el mar;\ndice que al zopilotito\nya lo piensa abandonar.",146,2,7,134,"El zopilote",3,4,"a",21,0,-1,0,73,73,"6066","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6067",7,"Suni, suni, suni, la zopilotita,\nsuni, suni, suni, se fue pa el palmar,\nen busca de un amorcito,\nque la pueda consolar.",146,2,7,134,"El zopilote",3,4,"a",21,0,-1,0,73,73,"6067","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6068",7,"Suni, suni, suni, la zopilotita,\nsuni, suni, suni, se fue pa La Joya;\ndice que al zopilotito\nlo enyerbaron con cebolla.",146,2,7,134,"El zopilote",3,4,"oa",453,0,-1,0,73,73,"6068","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6069",7,"Allá va la garza,\ndéjenla volar;\nsi los amores la llevan,\nallí los celos la traerán.",142,2,8,134,"Que comienzo, que comienzo",3,4,"a",-1,0,-1,0,74,74,"6069","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6070",7,"[Déjala] que vaya,\nque ella volverá;\nsi amores la llevan (mi vida),\ncelos la traerán.",137,2,3,134,"Las abajeñas",0,4,"a",-1,0,-1,0,74,74,"6070","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6071",7,"Un pescado de colores,\nafuera de un arroyuelo,\nsolito se revolcaba,\nporque lo mataba el celo.",142,2,8,134,"Estrofa suelta",0,4,"eo",10,0,-1,0,74,74,"6071","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6072",7,"Un león mató a una leona,\nde puros celos,\ny los animalitos\nse mueren de hambre\nlos pobrecitos.",147,2,11,134,"Estrofa suelta",7,5,"io",254,0,-1,0,74,74,"6072","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6073",7,"¿Qué pajarillo es aquel\nque ha bajado a beber agua,\nque con el pico la turbia,\npor no beberla tan clara?",136,2,4,134,"El pájaro cú",0,4,"aa",-1,0,-1,0,74,74,"6073","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6074",7,"Y en la punta de un pirú\nlloraba una chuparrosa,\ny le respondió Cupido:\n“No llores, mujer hermosa”.",135,2,-1,134,"Negra, ¿dónde están los lazos?",0,4,"oa",63,0,-1,0,74,74,"6074","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6075",7,"“¡Agua, cielo!”, dijo un pato\nen medio de una laguna,\ndándole el agua al pescuezo,\nsin esperanza ninguna.",142,2,8,134,"Estrofa suelta, Que comienzo, que comienzo",0,4,"ua",56,0,-1,0,74,74,"6075","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6076a",7,"La sirena está encantada,\nporque desobedeció:\nno más por una bañada\nque el Jueves Santo se dio,\ny en la Semana Sagrada.",138,2,6,134,"La Petenera",7,5,"aa",49,0,-1,0,74,74,"6076a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6077",7,"La sirena era muchacha;\nlo más profundo vagaba,\nno más por no obedecer\nlos consejos que daba;\nfue por siempre a padecer\na lo profundo del agua,\ndonde nadie pudo ver.",139,2,2,134,"La Petenera",4,7,"e",20,0,-1,0,75,75,"6077","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6078",7,"Ya murió la cucaracha,\nya la llevan a enterrar,\nentre cuatro zopilotes\ny un ratón de sacristán.",137,2,3,134,"La cucaracha; Don Gato; El jarabe. Estrofa suelta",0,4,"a",-1,0,-1,0,75,75,"6078","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6079",7,"Ya la tuza se murió,\nya la llevan a enterrar,\nentre cuatro lagartijos\ny un ratón de sacristán.",142,2,8,134,"La tuza",0,4,"a",-1,0,-1,0,75,75,"6079","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6080",7,"Hoy la pobre de la tuza\nya no comerá más caña,\nporque se la llevan presa\nlos soldados para España.",136,2,4,134,"La tuza",0,4,"aa",213,0,-1,0,75,75,"6080","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6081",7,"Hoy la pobre de la tuza\nya no comerá camote,\nporque se la llevan presa\nlos soldados a Perote.",147,2,11,134,"La tuza",0,4,"oe",292,0,-1,0,75,75,"6081","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6082",7,"A la pobre de la tuza\nle dieron su buena pela,\nporque vendió sin licencia\ncuatro cuartillos de vela.",136,2,4,134,"La tuza",0,4,"ea",-1,0,-1,0,75,75,"6082","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6083",7,"A la pobre de la tuza\nle dieron una paliza,\nporque vendió sin permiso\ndos metros de longaniza.",136,2,4,134,"La tuza",0,4,"ia",420,0,-1,0,75,75,"6083","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6084",7,"A la pobre de la tuza\nle dio mal de corazón,\nporque vido su retrato\npintado en un carretón.",136,2,4,134,"La tuza",0,4,"o",31,0,-1,0,76,76,"6084","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6085",7,"El amigo mono (caramba)\nse cayó del palo;\npor el aire dijo (caramba):\n“Válgame San Pablo”,\nque si no lo dice (caramba),\nse lo lleva el diablo.",136,2,4,134,"El canelo",9,6,"ao",567,0,-1,0,76,76,"6085","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6086",7,"El querreque en un fandango\nle quisieron hacer una treta:\nya lo iban a matar\ny guisarlo con manteca.",139,2,2,134,"Estrofa suelta",3,4,"ea",-1,0,-1,0,76,76,"6086","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6087",7,"Una gallina con pollos\n¡qué trabajos pasaría!\nEl gallo le preguntó\nque con qué los mantenía;\nle dijo que les rascaba,\nporque chiche no tenía.",136,2,4,134,"El gallo; El querreque",9,6,"ia",0,0,-1,0,76,76,"6087","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6088",7,"Paloma blanca, ¿qué andas buscando,\nqué andas buscando por la barranca?;\na un zopilote le estás gustando,\npaloma blanca de Ixtapalapa.",135,2,-1,134,"‘‘Paloma de Ixtapalapa",3,4,"aa",-1,0,-1,0,77,77,"6088","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6089",7,"Cuando te miro tender tu vuelo\nme estás mirando de amor y celo,\nporque áhi anda el zopilote,\ncruzando el monte de Los Remedios.",135,2,-1,134,"Paloma de Ixtapalapa",3,4,"eo",-1,0,-1,0,77,77,"6089","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6090",7,"Andas volando por la cañada,\nretedichosa y represumida;\nsi el zopilote se da sus mañas,\nsabrás muy pronto lo que es la vida.",135,2,-1,134,"‘‘Paloma de Ixtapalapa",3,4,"ia",37,0,-1,0,77,77,"6090","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6091",7,"Paloma, paloma, paloma blanca,\nten cuidado, no te vueles;\nsi te caes, ¿quién te levanta?,\npaloma de Ixtapalapa.",135,2,-1,134,"Paloma de Ixtapalapa",3,4,"aa",-1,0,-1,0,77,77,"6091","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6092",7,"Mariposa, ¿qué haces áhi,\nsentadita en ese ocote?\nCuídate, no te vaya a llevar\nel maldito tecolote.",142,2,8,134,"Estrofa suelta",3,4,"oe",292,0,-1,0,77,77,"6092","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6093",7,"Palomo, que cantas triste,\ntan lejos del palomar,\npor una paloma triste;\nsi no la pudiste hallar,\nel corazón me partistes:\nhoy cantas por no llorar.",150,2,24,134,"La luna",9,6,"a",21,0,-1,0,77,77,"6093","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6094",7,"Canta, calandria, y no llores,\nno me estés atormentando;\nen el jardín de las flores\nte vi una tarde cantando\nesta cadena de amores.",139,2,2,134,"La Malagueña",7,5,"oe",5,0,-1,0,77,77,"6094","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6095",7,"Pajarito jaralero,\nque naciste en un jaral,\nya no llores, pajarito,\ntú debieras de cantar.",135,2,-1,134,"Pajarito jaralero",0,4,"a",-1,0,-1,0,77,77,"6095","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6096",7,"Canta, pajarillo, canta,\nque yo te daré\nuna soga para el pie\ny otra para la garganta.",135,2,-1,134,"Estrofa suelta",11,4,"aa",148,0,-1,0,78,78,"6096","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6097",7,"Despierta, hermoso lagarto,\nde ese sueño tan profundo,\nque te viene a despertar\nun alma del otro mundo.",136,2,4,134,"‘‘El fandanguito",0,4,"uo",179,0,-1,0,78,78,"6097","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6098",7,"Tortolita, ¿de ’ónde vienes?\n¿de ’ónde vienes, vida mía?\n¿Cómo pasaste la noche?,\n¿cómo pasastes el día?",146,2,7,134,"La tortolita",0,4,"ia",0,0,-1,0,78,78,"6098","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6099a",7,"En la sierra de Morelia\nanda un gavilán volando;\nno te asustes, palomita:\npichones anda buscando.",142,2,8,134,"El gavilán; El gavilancillo",0,4,"ao",33,0,-1,0,78,78,"6099a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6100",7,"Gavilán, gavilán, gavilán,\nte llevaste mi polla, gavilán;\nsi tú vuelves mi polla para acá,\nyo te doy todito el gallinero.",135,2,-1,134,"El gavilán pollero",3,4,"eo",-1,0,-1,0,78,78,"6100","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6101",7,"Si buscas a tu marido,\nen el campo lo has de hallar,\ncon el pico entre las alas,\nqueriendo ticuruquiar.",135,2,-1,134,"‘‘El tecolote; Los papaquis",0,4,"a",21,0,-1,0,78,78,"6101","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6102",7,"Si buscas al tecolote,\nen el monte lo has de hallar,\nal peso de media noche\nempieza a cucuruquear.",135,2,-1,134,"El tecolote",0,4,"a",21,0,-1,0,78,78,"6102","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6103",7,"Querreque, ¡cómo te gusta mi son!,\nquerreque, ¡ay, qué bonito huapango!\nQuerreque, ya deja de vacilar,\nquerreque, mejor vete a emborrachar.",139,2,2,134,"El querreque",3,4,"a",21,0,-1,0,78,78,"6103","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6104",7,"Palomita, palomita,\nde las alas coloradas,\nsi te duele la cabeza,\namárrate las quijadas.",135,2,-1,134,"Estrofa suelta",0,4,"aa",282,0,-1,0,79,79,"6104","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6105",7,"Palomita, palomita,\nde las alas amarillas,\nsi te duele la cabeza,\namárrate las costillas.",135,2,-1,134,"Estrofa suelta, Chula la mañana",0,4,"ia",294,0,-1,0,79,79,"6105","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6106",7,"Zopilotes, a volar;\npresumido gavilán,\nlas palomas de San Juan\nlo pueden desplumar.",135,2,-1,134,"Maldita sea mi suerte",11,4,"a",-1,0,-1,0,79,79,"6106","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6107",7,"Guajito, ¿a mí qué?\nque medio que traía ya lo gasté;\nguajito, a mí no:\nya no te compro tu chicharrón.",135,2,-1,134,"El guajito",3,4,"o",-1,0,-1,0,79,79,"6107","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6108",7,"Cotorra del pico chueco,\nprima hermana del perico,\nsi denuncias mis amores\nque me traje de Tampico,\nte he de correr de mi milpa,\no si no, te corto el pico.",146,2,7,134,"El toro rabón",9,6,"io",141,0,-1,0,79,79,"6108","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6109",7,"Pajarito manzanero\ndel campo de Santa Marta,\ntú dices que no me atrevo,\nyo digo que no eres carta\npara llegar al tablero\ndonde se encuentra esa mata.",136,2,4,134,"El pájaro manzanero",9,6,"aa",-1,0,-1,0,79,79,"6109","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6110",7,"Un pájaro a mí me dijo:\n“Yo no tengo dueño:\nestoy en un pabellón\ndel águila mexicana”.",136,2,4,134,"El pájaro cú",5,4,"aa",-1,0,-1,0,79,79,"6110","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6111",7,"Al otro lado del río\nme chiflaba un lagartijo,\ny en el chiflido decía:\n“¡Gloria al Padre, gloria al Hijo!",135,2,-1,134,"El lagartijo",0,4,"io",122,0,-1,0,79,79,"6111","",0,"","","",15,0,0,[],"",""],["frenk_t3-n6112",7,"La tecolota me dijo,\narriba de los magueyes,\nque deseaba ser casada\nsolamente por dos leyes.",139,2,2,134,"El tecolote",0,4,"ee",600,0,-1,0,80,80,"6112","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6113",7,"La tecolota me dijo,\nallá por el mes de abril,\nque deseaba ser casada\nnada más por lo civil.",139,2,2,134,"El tecolote",0,4,"i",290,0,-1,0,80,80,"6113","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6114",7,"—Perico, ¿qué andas haciendo\ndebajo de los nogales?\n—Ando juntando mis nueces\npa ganar mis cuatro reales.",135,2,-1,134,"El perico",0,4,"ae",26,0,-1,0,80,80,"6114","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6115a",7,"—Palomita, ¿qué haces áhi,\nparada en ese hormiguero?\n—Juntando florecitas\npara el año venidero.",136,2,4,134,"El palomo",0,4,"eo",38,0,-1,0,80,80,"6115a","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6115b",7,"-Palomito, ¿qué haces áhi,\nparado en ese hormiguero?\n-Pepenando, pepenando,\npiedrecitas para el año\npara el año venidero.",135,2,-1,134,"‘‘El palomo",7,5,"eo",38,0,-1,0,80,80,"6115b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6116",7,"—Becerrito ¿qué haces áhi,\nen las llaves de ese buey?\n—Aquí me tiene mi padre\npara que [me] haga a su ley.",137,2,3,134,"‘‘El becerrito",0,4,"e",133,0,-1,0,80,80,"6116","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6117",7,"—Pajarito manzanero,\n¿por qué no comes manzanas?\n—Cómo quieres que las coma,\nsi no me bajas las ramas.",136,2,4,134,"‘‘El pájaro cú",0,4,"aa",-1,0,-1,0,80,80,"6117","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6118",7,"—Vuela y revuela y vuela,\nvuela paloma chiquita.\n-¿Y cómo quieres que vuele,\nsi me faltan las alitas?",136,2,4,134,"La guacamaya",0,4,"ia",-1,0,-1,0,80,80,"6118","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6119",7,"-Vuela, vuela, vuela,\nvuela, palomita.\n—¿Cómo quieres que vuele,\nadorada mamacita?",136,2,4,134,"La guacamaya",0,4,"ia",50,0,-1,0,80,80,"6119","",0,"","","",17,0,0,[],"",""],["frenk_t3-n6120",7,"—Zopilote, ¿de ónde vienes?\n—Vengo de la ranchería;\ndel primer caballo muerto,\n¡mal haya la porquería!",135,2,-1,134,"El zopilote",0,4,"ia",0,0,-1,0,80,80,"6120","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6121",7,"—Zopilote, ¿de ónde vienes?\n—Vengo de la mar, volando,\nde huida del gavilán,\nque ya me venía alcanzando.",135,2,-1,134,"El zopilote",0,4,"ao",33,0,-1,0,81,81,"6121","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6122",7,"—Cuervito, cuervito,\n¿qué haces en el río?\n—Pasando trabajos\ny muerto de frío.",136,2,4,134,"El cuervito",0,4,"io",3,0,-1,0,81,81,"6122","",0,"frenk_t4","","",7,0,0,[],"",""],["frenk_t3-n6123",7,"-Cuervito, cuervito,\n¿qué haces aquí parado?\n—Pasando trabajos\npor enamorado.",136,2,4,134,"El cuervito",0,4,"ao",-1,0,-1,0,81,81,"6123","",0,"frenk_t4","","",7,0,0,[],"",""],["frenk_t3-n6124",7,"—Cuervito, cuervito,\n¿qué haces en la peña?\n—Pasando trabajos\npor una trigueña.",136,2,4,134,"El cuervito",0,4,"ea",291,0,-1,0,81,81,"6124","",0,"frenk_t4","","",7,0,0,[],"",""],["frenk_t3-n6125",7,"—Cuervito, cuervito,\nqué haces en la loma?\n—Borracho perdido (¡caramba!)\npor una paloma.",144,2,10,134,"El cuervito",0,4,"oa",86,0,-1,0,81,81,"6125","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6126",7,"—¿Adónde vas, venadita,\ncon mucha alegría y afán?\n—A buscar nuevos amores\na las orillas del mar.",145,2,17,134,"La venadita",3,4,"a",-1,0,-1,0,81,81,"6126","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6127",7,"—Tecolote, ¿qué haces áhi,\nparado en ese granado?\n—Esperando mi tecolota,\nque con otro se ha fugado.",135,2,-1,134,"El tecolote",0,4,"ao",14,0,-1,0,81,81,"6127","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n6128",7,"—Tecolote, ¿de ónde vienes?\n—Vengo de la mar, volando,\nbuscando a mi tecolota,\nque también me anda buscando.",145,2,17,134,"El tecolote",0,4,"ao",33,0,-1,0,81,81,"6128","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6129",7,"—Tecolotito, ¿de dónde vienes?\n—Vengo de La Manzanía;\ntoditas vienen bajando,\nmás atrás viene la mía.",135,2,-1,134,"El tecolote",3,4,"ia",0,0,-1,0,81,81,"6129","",0,"frenk_t4","","",4,0,0,[],"",""],["frenk_t3-n6130",7,"—Tecolote, ¿qué haces áhi,\nsentado en esa pared?\n—Esperando a mi tecolota,\nque me traiga de comer.",142,2,8,134,"El tecolote",0,4,"e",-1,0,-1,0,81,81,"6130","",0,"","","",6,0,0,[],"",""],["frenk_t3-n6131",7,"—Tecolotito, ¿de dónde vienes?\n—Vengo del número uno,\nesperando mi tecolota,\nque me traiga el desayuno.",135,2,-1,134,"El tecolote",3,4,"uo",230,0,-1,0,82,82,"6131","",0,"frenk_t4","","",4,0,0,[],"",""],["frenk_t3-n6132",7,"—Tecolote, ¿qué haces áhi,\nparado en ese palmar?\n—Esperando mi tecolota,\nque me traiga de cenar.",135,2,-1,134,"El tecolote",0,4,"a",21,0,-1,0,82,82,"6132","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n6133",7,"—Palomita, ¿qué haces áhi,\nparada en esa ventana?\n—Esperando a mi palomo,\nque vendrá por la mañana.",135,2,-1,134,"El palomo",0,4,"aa",4,0,-1,0,82,82,"6133","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6134",7,"—Palomita, ¿qué haces áhi,\nparada en ese hormiguero?\n—Y esperando a mi palomo,\nque me traiga mi dinero.",136,2,4,134,"El palomo",0,4,"eo",38,0,-1,0,82,82,"6134","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6135",7,"—Palomita, ¿qué haces áhi,\nparadita en esa mesa?\n—Esperando a mi palomo,\nque me invite una cerveza.",136,2,4,134,"El palomo",0,4,"ea",108,0,-1,0,82,82,"6135","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6136",7,"Vengo de lejanas tierras,\nvolando de noche y día,\ncruzando ceños y mares,\nyo vengo de Alejandría.",146,2,7,135,"La tortolita",0,4,"ia",0,0,-1,0,83,83,"6136","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6137",7,"Soy sirena de la mar,\nque me mantengo en la peña,\ncon mi guitana en las manos,\ncantando “La Malagueña”.",142,2,8,135,"La Malagueña curreña; Soy de",0,4,"ea",291,0,-1,0,83,83,"6137","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6139",7,"—¿Cuándo quieres ser casada?\n—Yo no quiero ser casada,\nla sirena contestó,\nyo quiero ser encargada,\ny pa lo que Dios formó;\nyo quiero vivir honrada\ncon el ser que Dios me dio.",136,2,4,135,"La Petenera",4,7,"o",2,0,-1,0,83,83,"6139","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6140",7,"—Quisiera ser pavo real\npa tener plumas bonitas.\nLe respondió el cardenal:\n—Yo las tengo más bonitas,\nyo también pa nemorar\nno más abro mis alitas.",138,2,6,135,"La leva",9,6,"ia",258,0,-1,0,83,83,"6140","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6141",7,"Yo soy el pájaro cú,\nque sabe comer azúcar,\nporque me crió una currucucú,\ncomo el guamil de chuchuca,\nque huele donde pasas tú.",142,2,8,135,"Estrofa suelta",7,5,"u",73,0,-1,0,83,83,"6141","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6142",7,"Este es el lagartijo\nque canta a toda hora,\nsólo por venirte a ver,\nlagartija encantadora.",135,2,-1,135,"El lagartijo",0,4,"oa",107,0,-1,0,84,84,"6142","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6143",7,"Al otro lado del río\ncontento dormía un oso,\ny en su ronquido decía:\n“A mí nadie me mata,\nporque soy amoroso”.",138,2,6,135,"Estrofa suelta",7,5,"oo",160,0,-1,0,84,84,"6143","",0,"","","",15,0,0,[],"",""],["frenk_t3-n6144",7,"Ya la calandria voló\nde un solar para una higuera,\ny le respondió el gorrión:\n“¡Qué volar de primavera!”",142,2,8,135,"El pájaro cú",0,4,"ea",44,0,-1,0,84,84,"6144","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6145a",7,"La calandria voló\nde un solar a otro solar:\n“¡Ah, qué volar de animal!,\n¿cómo la cogeré yo?”",142,2,8,135,"El pájaro cú",5,4,"o",2,0,-1,0,84,84,"6145a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6145c",7,"Del solar a una garita\nuna paloma voló,\ny le respondió el gorrión\ncon una voz muy clarita:\n“¡Qué volar de palomita!,\n¿cómo la cogiera yo?”",142,2,8,135,"El pájaro cú",9,6,"o",-1,0,-1,0,84,84,"6145c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6146",7,"En orillas de Colima\nestaba un sapo parado,\ny decía una colimota:\n“¡Ay, qué cuerpo pa soldado!”",135,2,-1,135,"La colimota",0,4,"ao",14,0,-1,0,84,84,"6146","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6147",7,"El palomo y la paloma\nse salieron a pasear;\nel palomo le decía:\n“Vente, que voy a bailar”.",145,2,17,135,"El jarabe; El palomo",0,4,"a",21,0,-1,0,84,84,"6147","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6149",7,"El pajarillo hechicero\nle dice al madrugador:\n“No mates al carpintero,\nporque es el que cuida mi amor”.",148,2,9,135,"Tú sabías que era borracho",1,4,"o",72,0,-1,0,85,85,"6149","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6150a",7,"Soy el toro Requesón,\nque bajo al abrevadero,\ny sé que me han de lazar:\nno hay duda, me lazarán,\npero revuelco al vaquero.",136,2,4,135,"El toro Requesón’",7,5,"eo",38,0,-1,0,85,85,"6150a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6151",7,"Y es el toro Requesón,\nque viene por la ternera,\ndiciéndole a los vaqueros:\n“Échenme ese toro fuera\".",145,2,17,135,"El toro Requesón",0,4,"ea",44,0,-1,0,85,85,"6151","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6152",7,"Estaban cuatro palomas,\nestaban toreando un toro;\nla más chiquita decía:\n“Obre Dios y San Bartolo”.",146,2,7,135,"El palomo",0,4,"oo",-1,0,-1,0,85,85,"6152","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6153",7,"Cuando el ave se sacude,\ndebajo del árbol canta,\ny le dice a su zalea:\n“¡Vámonos de aquí, que espanta!”",147,2,11,135,"El borracho",0,4,"aa",148,0,-1,0,85,85,"6153","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6154",7,"Un gorrión en una rama\nestaba dando de gritos;\nle respondió la calandria:\n“¿Por qué lloras, pajarito?\nEl que tiene chiche mama,\ny el que no, se cría solito”.",142,2,8,135,"El pájaro cú",9,6,"io",119,0,-1,0,85,85,"6154","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6155",7,"Y un pájaro en una rama\nbrincaba y se sonreía;\nme encontré con la calandria:\n“¿Por qué chillas, vida mía?\nEl que tiene chichi mama,\ny el que no, solo se cría”.",136,2,4,135,"El pájaro cú",9,6,"ia",0,0,-1,0,85,85,"6155","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6156",7,"Soy la sirena encantada,\nporque Dios lo decretó;\npor Él fui sacrificada:\npor eso me encuentro yo\nen la inmensidad del agua.",138,2,6,135,"La sirena",7,5,"aa",-1,0,-1,0,85,85,"6156","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6157",7,"Soy un triste pajarito,\nque en el campo, es la verdad,\ncomo soy muy chiquitito,\ncanto con sinceridad;\ncomo soy muy pobrecito,\nno tengo esa libertad.",136,2,4,135,"El pájaro cú",9,6,"a",16,0,-1,0,86,86,"6157","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6158",7,"Yo soy el gurrión herido,\nque canta en noche de luna;\nYo no sé qué me ha sucedido,\nme ha azotado la fortuna:\nal dar mi primer volido\nse me han caído las plumas.",142,2,8,135,"El pájaro cú’T",9,6,"ua",-1,0,-1,0,86,86,"6158","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6159",7,"Y las palomas, que son tan chiquitas,\ndejan su nido y se van a volar;\nyo aquí me quedo, solito y triste,\ncuidando el nido de su palomar.",155,2,14,135,"Corazón sólido",3,4,"a",21,0,-1,0,86,86,"6159","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6160",7,"El pájaro que voló\nle dijo a la chuparrosa:\n“No te hagas ilusiones,\nque al fin que no es para ti esa rosa”.",139,2,2,135,"Estrofa suelta",3,4,"oa",63,0,-1,0,86,86,"6160","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6161",7,"Quisiera ser pavo real\npara tener plumas bonitas;\npero he sido cardinal,\ncriado en las tortolitas;\ncomo el que quiso [y] no pudo\nquerer a la más bonita.",142,2,8,135,"Estrofa suelta",9,6,"ia",-1,0,-1,0,86,86,"6161","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6162",7,"Y siempre salió la tuza,\nmuy triste y avergüenzada:\n“Yo creo que usted no me quiere,\nporque estoy toda pelada”.",135,2,-1,135,"La tuza",0,4,"aa",49,0,-1,0,86,86,"6162","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6163",7,"Una paloma en su nido,\nque tenía muy mal dormir;\ny el palomo, ya aburrido,\nle decía: “Me voy a ir”.",136,2,4,135,"El palomo",1,4,"i",157,0,-1,0,86,86,"6163","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6165",7,"La garza, como enojada,\nle dijo al pobre pelón:\n“Zopilote, si me muero,\nno te vuelvas a casar”.",146,2,7,135,"Estrofa suelta",5,4,"a",-1,0,-1,0,86,86,"6165","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6166",7,"Los pollitos, pío, pío,\nse los lleva el gavilán,\ny la gallina diciendo:\n“¡Ah, qué maldito animal!,\ntodo se lo está comiendo”.",136,2,4,135,"El pollo",7,5,"eo",52,0,-1,0,86,86,"6166","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6167",7,"Salen los pollos corriendo\npor la puerta de la reja,\ny la gallina diciendo:\n“¡Qué maldita comadreja!,\n¡todo me lo está comiendo!”",136,2,4,135,"‘‘El pollo",7,5,"eo",52,0,-1,0,87,87,"6167","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6169",7,"-Tecolote, ¿qué haces áhi,\nen esa rama cantando?\nLe respondió el armadillo:\n—En la concha me estás dando.",135,2,-1,135,"El tecolote",0,4,"ao",33,0,-1,0,87,87,"6169","",0,"","","",6,0,0,[],"",""],["frenk_t3-n6170",7,"El perro le dijo al chango:\n“Palabra que estás enfermo,\nanda, bautizas un cuerno”.\nSe fueron para Matiaco,\nfue perrada del gobierno.",135,2,-1,135,"‘‘La india",7,5,"eo",225,0,-1,0,87,87,"6170","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6171",7,"La polla le dice al pollo:\n“¿Pa qué me picas la cresta?”\nY el pollo le respondió:\n“Pollita, para hacer fuerzas”.",135,2,-1,135,"‘‘La gallina",0,4,"ea",-1,0,-1,0,87,87,"6171","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6172",7,"Yo soy el toro rabón,\nque habito en la serranía;\ndejo de pasearme un año,\npor pasearme noche y día;\ncomo soy becerro de año,\nno habito en la pastoría.",135,2,-1,135,"El toro rabón",9,6,"ia",0,0,-1,0,87,87,"6172","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6173",7,"Suspira el toro barroso\ncuando lo van a matar;\nresponde su seno hermoso:\n“Conmigo se han de encontrar;\nsoy soltero y animoso\ny no me sé rebajar”.",142,2,8,135,"Estrofa suelta",9,6,"a",21,0,-1,0,87,87,"6173","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6175",7,"En la jaula de Tampico\nun pájaro se paró,\ny le respondió el perico:\n“Éste sí que me ganó\na tener más largo el pico,\npero retorcido no”.",136,2,4,135,"El pájaro carpintero",9,6,"o",2,0,-1,0,88,88,"6175","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6176a",7,"Dijo el pájaro gorrión:\n“¿Pa qué son tantas habladas?\nNo vengo a acabarme el pico\ncon tunas agujeradas”.",137,2,3,135,"El caballo prieto",0,4,"aa",282,0,-1,0,88,88,"6176a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6177",7,"Un atrevido perico\nle dijo a una guacamaya:\n“Pa comerte la pitaya\ntendrás que limpiarte el pico;\ntengo una novia en Celaya\ny una que vive en Tampico”.",136,2,4,135,"La guacamaya",9,6,"io",141,0,-1,0,88,88,"6177","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6178",7,"El pájaro picó la tuna,\ny la picó con reflejo;\nle contestó el gorrión:\n“¡Qué pájaro tan pendejo!,\nque se babosea todito\ncon las sobras que yo dejo”.",142,2,8,135,"Estrofa suelta",9,6,"eo",264,0,-1,0,88,88,"6178","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6179",7,"Un querreque y un perico\nestaban trovando un verso:\n“No te he de dar un beso,\nporque a ti te apesta el pico”.",139,2,2,135,"El querreque",5,4,"io",141,0,-1,0,88,88,"6179","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6180",7,"Una paloma en su cuna\nle dijo a la cuchareta:\n“Color de rosa esta pluma,\npero mucho que reapesta”.",136,2,4,135,"El palomo’3",0,4,"ea",-1,0,-1,0,88,88,"6180","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6182",7,"El gorrión subió al nopal,\ny ahí se quedó dormido,\ny le dijo el cardenal:\n“Cuidado con la caída, amigo:\nno se vaya usted a matar,\ny yo me quedo en el nido”.",142,2,8,135,"Estrofa suelta",9,6,"io",-1,0,-1,0,88,88,"6182","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6183",7,"En medio del mar salado\nsuspiró un ave marina,\ny le respondió el pescado\ncon una voz muy melódica:\n“Tienes más sed que un casado,\nque un santo.........................”",136,2,4,135,"El pájaro carpintero",9,6,"ao",-1,0,-1,0,89,89,"6183","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6184",7,"Cuatro palomitas blancas\nsentadas en un huizache,\ny una a la otra le decía:\n“Vamos a tomar tepache,\nsi ha de ser, pues ¿cuándo no?.",136,2,4,135,"El palomo",7,5,"o",-1,0,-1,0,89,89,"6184","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6185",7,"La chinche pica y se va,\nel piojo pica y se acuesta,\npero la maldita pulga\nni siquiera duerme siesta.",137,2,3,136,"Estrofa suelta",0,4,"ea",406,0,-1,0,92,92,"6185","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6186",7,"¡Ay, cómo brincan!,\n¡ay, cómo saltan!\n¡ay, cómo brincan\nlas pulgas malditas!",135,2,-1,136,"Las pulgas",6,4,"ia",-1,0,-1,0,92,92,"6186","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6187",7,"¡Ay, cómo pican!,\n¡ay, cómo saltan!,\n¡ay, cómo pican\nlas pulgas ingratas!",144,2,10,136,"Las pulgas",6,4,"aa",-1,0,-1,0,92,92,"6187","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6188",7,"¡Ay, que me pican!,\n¡ay, que me matan\npulgas ingratas,\nchinas del alma!",140,2,12,136,"Las pulgas",6,4,"aa",-1,0,-1,0,92,92,"6188","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6189",7,"¡Ay!, estas pulgas\nno las puedo ver,\nporque me pican\na mí y a mi mujer.",140,2,12,136,"Las pulgas",3,4,"e",20,0,-1,0,92,92,"6189","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6190",7,"Yo con las pulgas\nme enojo de deveras,\nporque me pican\nentre las caderas.",156,2,32,136,"Las pulgas",3,4,"ea",103,0,-1,0,92,92,"6190","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6191",7,"Yo con las pulgas\nme enojo de repente.\nporque me pican\ndelante de la gente.",156,2,32,136,"Las pulgas",3,4,"ee",15,0,-1,0,92,92,"6191","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6192",7,"Yo con las pulgas\nme enojo y me da risa,\nporque me pican\nentre la camisa.",156,2,32,136,"Las pulgas",3,4,"ia",-1,0,-1,0,92,92,"6192","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6193",7,"A mí las pulgas\nme causan mucho miedo,\npor sus piquetes,\nque me dan en el cuero.",145,2,17,136,"'‘Las pulgas",3,4,"eo",-1,0,-1,0,93,93,"6193","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6194",7,"Yo con las pulgas\nestoy muy enojada,\nporque me pican\ndespués de acostada.",145,2,17,136,"Las pulgas",3,4,"aa",49,0,-1,0,93,93,"6194","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6195",7,"Ya no tengo uñas cabales,\nlas pulgas me hacen rabiar;\n¡qué rasquidos me hacen dar!\n¡Malhayan los animales!",135,2,-1,136,"Estrofa suelta",11,4,"ae",26,0,-1,0,93,93,"6195","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6196",7,"Quisiera ser guacamaya,\ncon mi pico de coral,\npara matar a piquetes\ntanto diablo de animal.",135,2,-1,136,"Estrofa suelta",0,4,"a",1,0,-1,0,93,93,"6196","",0,"","","",6,0,0,[],"",""],["frenk_t3-n6197",7,"De miedo de las pulgas\nme fui para un huizache;\nporque las pulgas\nlas traigo en un huarache.",144,2,10,136,"Las pulgas",3,4,"ae",531,0,-1,0,93,93,"6197","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6198",7,"De miedo de las pulgas\nme fui para un potrero;\nporque las pulgas\nlas traigo en el sombrero.",144,2,10,136,"Las pulgas",3,4,"eo",38,0,-1,0,93,93,"6198","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6200",7,"Espánteselas siquiera,\nno se las deje pegar,\nmire que si se le pegan\nmuy recio le han de picar.",135,2,-1,136,"Estrofa suelta",0,4,"a",21,0,-1,0,93,93,"6200","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6201",7,"Y ¡ay, cuántos piojos!,\ny ¡ay, cuántas pulgas!,\ny ¡ay, Dios mío,\nqué pulgas tan ingratas!",156,2,32,136,"Las pulgas",3,4,"aa",-1,0,-1,0,93,93,"6201","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6202",7,"Préstame tu peine blanco:\npor aquí me anda un gorgojo,\npréstame tu peine blanco,\npara quitarme los piojos.",136,2,4,136,"El cascabel; El piojo",0,4,"oo",-1,0,-1,0,93,93,"6202","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6204",7,"Dicen que sí,\ndicen que no,\ndicen que el mosco\nya te picó.",135,2,-1,136,"El mosquito",6,4,"o",2,0,-1,0,94,94,"6204","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6205",7,"Mosquito, no mortifiques\ncon tus cantos malsonantes:\nsi me cantas, no me piques,\nsi me picas, no me cantes.",135,2,-1,136,"La Zandunga",1,4,"ae",262,0,-1,0,94,94,"6205","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6206",7,"La pitacocha\nde San José\ntiene gorupos\nen el tupé.",144,2,10,136,"La güitacocha",6,4,"e",77,0,-1,0,94,94,"6206","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6207",7,"En el río anda el pescado,\nen el monte la serpiente,\nen el llano anda el ganado,\nen la población la gente,\ndiciendo: “El invertebrado\nes un animal sin dientes.”",136,2,4,136,"Zapateado",9,6,"ee",-1,0,-1,0,94,94,"6207","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6208",7,"En la punta de aquel ceno\ntrepada en un maguey,\nestaba una zona;\nyo que voy, que le jalo la cola,\ny ¿dónde queda el rey?",140,2,12,136,"Estrofa suelta",7,5,"e",133,0,-1,0,94,94,"6208","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6209",7,"En la punta de un cerro\nestaba parado un búho;\nyo subí para cogerlo,\ny no se púo.",157,2,33,136,"Estrofa suelta",3,4,"uo",601,0,-1,0,94,94,"6209","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6210",7,"A la puerta de tu casa,\nestaba cantando un sapo;\nyo lo quise aganar,\npero se me escapo.",147,2,11,136,"Estrofa suelta",0,4,"ao",466,0,-1,0,94,94,"6210","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6211",7,"Y al canto de una avestruz\nse me ha espantado un coyote;\nno lo vi por ser de noche,\ny al resplandecer la luz\ndevisé un zopilote,\nque me estaba haciendo “gus”.",136,2,4,136,"El pájaro cú",9,6,"u",270,0,-1,0,94,94,"6211","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6212",7,"¿Quién te manda, zopilote,\nhaberte echado a volar,\ncuando te podías estar\nen tu casa metidote?",135,2,-1,136,"Estrofa suelta",11,4,"oe",292,0,-1,0,94,94,"6212","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6214",7,"Yo tenía un perico\nque se quitaba las plumas;\nno, no era peladito:\nes que iba al baño encueradito.",147,2,11,136,"Estrofa suelta",5,4,"io",119,0,-1,0,95,95,"6214","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6216",7,"¿Quién es ese pajarito,\nque canta bajo mi banqueta?\nNo más que asome\npara que le rompa la jeta.",152,2,13,136,"Estrofa suelta",3,4,"ea",200,0,-1,0,95,95,"6216","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6217",7,"¿Qué cosa le sucedió\nal coyote en la cocina?\nSe comió a la cocinera,\ncreyendo que era gallina.",145,2,17,136,"El coyote viejo",0,4,"ia",11,0,-1,0,95,95,"6217","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6218",7,"Pobre del zopilotito,\nse lo llevaron para arriba,\nporque se estaba comiendo\nlas costillas de una hormiga,",146,2,7,136,"El zopilote",0,4,"ia",-1,0,-1,0,95,95,"6218","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6219",7,"Una iguana se cayó\nde aniba de una escalera,\ndel porrazo que llevó\nse lastimó las caderas.",136,2,4,136,"La iguana",0,4,"ea",-1,0,-1,0,95,95,"6219","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6220",7,"Una iguana se cayó '\nde la rama de un amate,\ndel porrazo que llevó\nse reventó los tomates.",135,2,-1,136,"La iguana",0,4,"ae",-1,0,-1,0,95,95,"6220","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6221",7,"Un pepeyote cayó\nde arriba de un cañamazo,\ntan fuerte golpe se dio,\nque se rompió el espinazo,\nla sangre que derramó\nno cupo en un calabazo.",136,2,4,136,"Estrofa suelta",9,6,"ao",43,0,-1,0,95,95,"6221","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6222",7,"Estaba un coyote viejo\nsentado en un hormiguero,\nsacándose las hormigas\nde las bolsas del dinero.",145,2,17,136,"El coyote viejo",0,4,"eo",38,0,-1,0,95,95,"6222","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6223",7,"Un pajarito voló\ndel higo pa la granada;\na la granada picó,\nal higo no le hizo nada,\nporque no quiso, si no\ntambién le da su llegada.",135,2,-1,136,"‘‘El pájaro cú; El querreque; Estrofa suelta",9,6,"aa",49,0,-1,0,96,96,"6223","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6225",7,"El guajolote, has de ver,\nsirve al hombre a doble pico:\nigual le da de comer\nque le despepita el chico.",135,2,-1,136,"Estrofa suelta",1,4,"io",141,0,-1,0,96,96,"6225","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6226",7,"¡Cuánto escándalo!, ¿qué es esto?,\nno entiendo lo que sucede;\nla mula está de cabeza,\nenseñando la meadera.",135,2,-1,136,"La mulita",5,4,"ea",-1,0,-1,0,96,96,"6226","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6227",7,"El querreque y la querreca\nse casaron grandototes;\nse fueron pa la Huasteca,\nallá formaron borlote;\na los dos años de casados\nnacieron dos zopilotes.",139,2,2,137,"El querreque",9,6,"oe",-1,0,-1,0,97,97,"6227","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6228",7,"Un querreque muy contento\nse fue a la feria a pasear\ny tuvo el atrevimiento\nde enseñarse a jinetear,\nse montó a un caballo muerto,\nque no lo pudo tumbar.",139,2,2,137,"El caimán",9,6,"a",21,0,-1,0,97,97,"6228","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6229",7,"En la orilla de un potrero\noí bramar a una vaca;\nla vaca traía becerro,\nel becerro, una petaca,\ndonde guardaba el dinero\nde los quesos de la vaca.",136,2,4,137,"El toro Requesón; El torito",9,6,"aa",457,0,-1,0,97,97,"6229","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6230",7,"Yo vide a un triste zancudo\nuna torre fabricando;\ncon su azadón en la mano\nestaba desquelitando.",135,2,-1,137,"Estrofa suelta",0,4,"ao",-1,0,-1,0,97,97,"6230","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6231",7,"Una pulga bailando\nrompió un ladrillo,\nuna tinaja de agua\ny un cantarillo.",135,2,-1,137,"La bamba",6,4,"io",228,0,-1,0,97,97,"6231","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6232",7,"Al bajar una ladera\nvide pasar un tejón,\ncon una carga de elotes,\nque llevaba en el pulmón.",143,2,18,137,"El tejón",0,4,"o",31,0,-1,0,97,97,"6232","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6233",7,"¡Ay, cómo me quemaban!,\nagua por Dios pedía,\ny un tiburón decía:\n“Eso sí que no hay aquí”.",135,2,-1,137,"Buscando peces",5,4,"i",-1,0,-1,0,97,97,"6233","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6234",7,"Desde Veracruz salió\ny un pescado en agonía;\ncuando a Tampico llegó\nllegó a la telegrafía\ny medicinas pidió\na las doce horas de un día.",138,2,6,137,"La Petenera",9,6,"ia",0,0,-1,0,98,98,"6234","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6235",7,"La sirena se murió\nen una balsa de madera,\npor habérsele atorado\ncasi una ballena entera.",139,2,2,137,"Estrofa suelta",0,4,"ea",44,0,-1,0,98,98,"6235","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6236",7,"Más vale llegar a tiempo\nantes después de la cena;\n¿cómo quieres que te coma?,\n¿que no ves que soy sirena?",135,2,-1,137,"El tiburón",0,4,"ea",59,0,-1,0,98,98,"6236","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6237",7,"La sirena pa salirse a pasear\nse pone varios vestidos:\npara salirse a pasear\na los Estados Unidos\ny volver a regresar\na los países conocidos.",138,2,6,137,"La Petenera",9,6,"io",255,0,-1,0,98,98,"6237","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6239",7,"El caimán tenía cultura,\npues era un gran literato;\nestudiaba para cura\nen Dolores, Guanajuato;\nse le metió una locura,\nque no llegó ni al curato.",138,2,6,137,"El caimán",9,6,"ao",19,0,-1,0,98,98,"6239","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6240",7,"Buen trabajo le ha costado\nal caimán vivir aquí;\nal fin fue seleccionado,\napoyado por el PRI;\nojalá y no sea olvidado\ny que se acuerde de mí.",138,2,6,137,"El caimán",9,6,"i",23,0,-1,0,98,98,"6240","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6241a",7,"Ayer que me fui a bañar\nen la poza de la isleta,\nme pasé pa el otro lado;\nallí conocí el caimán,\npaseándose en bicicleta.",138,2,6,137,"El caimán",7,5,"ea",200,0,-1,0,98,98,"6241a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6242",7,"En la orilla de un charco\nestaba cantando un sapo,\ny en sus cantidos decía:\n“Joven tacos, tacos joven”.",147,2,11,137,"Estrofa suelta",5,4,"oe",-1,0,-1,0,99,99,"6242","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6243",7,"Arriba de un árbol\ncantaba una gallareta,\ny en su cantido decía:\n“No me mates con pistola,\nmejor mátame con tu escopeta”.",138,2,6,137,"Estrofa suelta",7,5,"ea",200,0,-1,0,99,99,"6243","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6244",7,"[El piojo?] le dijo al peine:\n“Déjame bien madurar,\nque al cabo estoy en tu rancho,\ntú siempre me has de rasar”.",140,2,12,137,"Estrofa suelta",0,4,"a",21,0,-1,0,99,99,"6244","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6245",7,"Cuando pasé por el puente\nme chifló un tecolote,\ny en el chiflido decía:\n“Traes un piojo en el molote”.",148,2,9,137,"Estrofa suelta",0,4,"oe",292,0,-1,0,99,99,"6245","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6246",7,"¡Válgame San Juan Bautista!,\n¡qué prodigio, qué rareza!\nLa muía comienza a hablar:\n¡ya nos llevó la tristeza!",150,2,24,137,"La mulita",0,4,"ea",108,0,-1,0,99,99,"6246","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6248",7,"Suni sun, cantaba la rana,\nsuni sun, debajo del agua;\nsuni sun, y tuvo un hijito,\nsuni sun, de la marihuana.",142,2,8,137,"La marihuana",0,4,"aa",-1,0,-1,0,99,99,"6248","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6249",7,"¡Qué linda la mañana\ncuando sale el sol!\nSe agacha la gallina,\ny se le ve el calzón.",148,2,9,137,"Estrofa suelta",0,4,"o",-1,0,-1,0,99,99,"6249","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6251",7,"Un pescadito en el agua\nle dijo a otro en la corriente:\n“Si tantito te dilatas,\nhallas la casa con gente”.",135,2,-1,137,"Estrofa suelta",0,4,"ee",15,0,-1,0,100,100,"6251","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6252",7,"Aura pelona,\nde buen parecer,\nagarra la aguja\ny ponte a coser\nlas enaguas de tu mujer.",159,2,26,137,"Estrofa suelta",7,5,"e",20,0,-1,0,100,100,"6252","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6253a",7,"Voy a echarme, que estoy culeco,\nque por la mañana saco\nun pato y un patuleco\ny también un chachalaco.",135,2,-1,137,"La india",1,4,"ao",423,0,-1,0,100,100,"6253a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6254a",7,"Un carpintero en Tampico\nse estaba espulgando el fleco;\n“Échate, que estás culeco;\na ver si te saco un hijo\ncon el espinazo chueco”.",136,2,4,137,"El querreque",7,5,"eo",320,0,-1,0,100,100,"6254a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6255",7,"La pata le dice al pato:\n“En la laguna nos vemos;\nno te vayas a tardar,\npara que nos revolquemos”.",135,2,-1,137,"Estrofa suelta",0,4,"eo",127,0,-1,0,100,100,"6255","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6258",7,"Una burra en un corral\nlloraba su compromiso;\nel burro la consolaba;\nno toda, no más lo liso.",142,2,8,137,"Estrofa suelta",0,4,"io",92,0,-1,0,100,100,"6258","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6259",7,"Soy soldado de levita,\nde esos de caballería,\ny por eso canto yo\ncaminito de Santa María.",136,2,4,138,"El aguanieve’",3,4,"ia",0,0,-1,0,104,104,"6259","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6260",7,"Soy cometa del veintiuno,\ndel Catorce Batallón;\na las muchachas del baile,\nadiós, Huajuapan de León:\nya me voy para mi tiena,\nle dejo mi corazón.",135,2,-1,138,"La cucaracha",9,6,"o",31,0,-1,0,104,104,"6260","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6261",7,"Si le tiran al que vive\nlejos de Comanjillo,\nles dirá que soy soldado\ndel..................... batallón,\nrecordé con aflicción.",135,2,-1,138,"La india",7,5,"o",31,0,-1,0,104,104,"6261","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6262",7,"Señora, soy un riflero (mi vida),\nque hora acabo de llegar,\ncon mi maleta en la mano (mi vida),\ncansado de caminar.",145,2,17,138,"El riflero",3,4,"a",21,0,-1,0,104,104,"6262","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6263",7,"Señora, soy un riflero (mi vida),\nque cansado voy llegando,\ncomponiendo mis huaraches (mi vida),\npara seguir caminando.",145,2,17,138,"El riflero",3,4,"ao",33,0,-1,0,104,104,"6263","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6264",7,"Solterita, soy rielero,\nrecorro la serranía,\ncruzo el valle y el potrero\ny la [abrupta] serranía.",135,2,-1,138,"El rielero",1,4,"ia",-1,0,-1,0,104,104,"6264","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6265",7,"Trabajando noche y día,\nmuevo carga y pasajeros;\na la joven que yo quiero\nque canto en la lejanía.",135,2,-1,138,"El rielero",5,4,"ia",0,0,-1,0,104,104,"6265","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6266",7,"Si porque me miran con guantes,\npiensan que soy militar,\nyo soy puro garrotero\nde la línea nacional.",135,2,-1,138,"La rielera",0,4,"a",-1,0,-1,0,105,105,"6266","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6267",7,"Pescador y marinero\nha sido mi profesión;\nconozco el pescado mero;\nen mi casa yo lo vi,\ny otro poquito al salmón;\néste no cae con anzuelo,\nsolamente con arpón.",136,2,4,138,"La Petenera",4,7,"o",31,0,-1,0,105,105,"6267","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6268",7,"Andándome por la playa,\nel caimán me daba risa;\npues me quité la camisa\npara tirar la atarraya,\nsacando robalo y lisa\ny una que otra acamaya.",138,2,6,138,"El caimán",9,6,"aa",404,0,-1,0,105,105,"6268","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6269",7,"Ariles, mi bien, ariles,\nariles de la cañada;\nyo también fui marinero\nen la mera agua salada.",136,2,4,138,"El Balajú",0,4,"aa",49,0,-1,0,105,105,"6269","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6270",7,"¡Ay, iza, marinero, iza!,\n¡iza para Tehuacán!\nYo también fui marinero\nen el río de Jordán.",136,2,4,138,"El cascabel",0,4,"a",147,0,-1,0,105,105,"6270","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6271",7,"Cuando estuve en Portugal\na buzo me dediqué;\nallí nunca me fue mal (¡ay, vida mía!),\nporque de la mar saqué\nperla, diamante y coral.",136,2,4,138,"El pájaro carpintero;",7,5,"a",1,0,-1,0,105,105,"6271","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6272",7,"Cuando estuve en La Ventilk\nyo me ocupé de bucear;\ncomo diestro en la marina (¡ay, vida míal),\nde lo más hondo del mar\nsacaba la perla fina.",136,2,4,138,"El pájaro carpintero",7,5,"ia",11,0,-1,0,105,105,"6272","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6273",7,"Como pescador que soy,\nme pueden echar a la mar;\nno esperen que probe el coco\nel que no lo ha de salvar.",135,2,-1,138,"La india",0,4,"a",21,0,-1,0,105,105,"6273","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6274",7,"Voy a tirar mi atarraya,\na ver si pesco un jurel,\nno más andando en la playa,\nsin meterme a revolver,\nporque la manta y la raya\npican como el cascabel.",136,2,4,138,"El cascabel",9,6,"e",-1,0,-1,0,105,105,"6274","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6275",7,"Salí por el mar en fuera,\na navegar contra el viento,\nsin ningún consolamiento:\nsólo lo que Dios quisiera.\nDijo el piloto: “Se espera\nuna fuerte ventolina”.\nEntramos a la marina,\nqueriendo izar la mayor;\ncomo sé que es de valor,\nyo soy como la tonina.",136,2,4,138,"Zapateado",18,10,"ia",11,0,-1,0,106,106,"6275","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6276",7,"No quise ser marinero,\npor no andar en el agua;\nme dijo mi compañero:\n“La vida es desdichada:\ntienes que salvar el cuero,\ny si vas, no tapa el agua”.",139,2,2,138,"La Petenera",9,6,"aa",-1,0,-1,0,106,106,"6276","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6277",7,"Ya me voy a Apatzingán,\na hacer mis cargas;\na ver qué puedo vender (mi vida),\ny traer las varas.",137,2,3,138,"El tamarindo",3,4,"aa",-1,0,-1,0,106,106,"6277","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6279",7,"Carbonero soy, señora,\nque vengo bajando el cerro;\nvengo a vender mi carbón,\ny [a] acompañarme, mi perro.",135,2,-1,138,"El carbonero",0,4,"eo",379,0,-1,0,106,106,"6279","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6280",7,"Carbonero soy, señora,\nque vengo de los nopales;\nvengo a vender mi carbón\ny a sacudir mis costales.",135,2,-1,138,"El carbonero",0,4,"ae",26,0,-1,0,106,106,"6280","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6281",7,"Carbonero soy, señora,\nque vengo de los Martínez;\nvengo a vender mi carbón,\npara comprar calcetines.",135,2,-1,138,"El carbonero",0,4,"ie",272,0,-1,0,106,106,"6281","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6282",7,"Yo soy la patera,\nque viene a vender\nel pato cocido\nque ayer fui a coger.",137,2,3,138,"Flor de changunga",0,4,"e",20,0,-1,0,106,106,"6282","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6283",7,"Soy pitayero, señores,\nque vengo desde Sayula;\nvoy a vender mis pitayas (güerita)\na ese pueblo de Cocula.",145,2,17,138,"El pitayero",3,4,"ua",547,0,-1,0,106,106,"6283","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6284",7,"Soy pitayero, señora,\nque ahora acabo de llegar;\nvengo de cortar pitayas (mi vida):\ncomienzan a madurar.",145,2,17,138,"El pitayero",3,4,"a",21,0,-1,0,107,107,"6284","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6285",7,"Soy pitayero, señora,\nque vengo de Manzanillo;\nvengo de cortar pitayas (güerita)\ndel organito amarillo.",145,2,17,138,"El pitayero",3,4,"io",228,0,-1,0,107,107,"6285","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6286",7,"Soy pitayero, señora,\nque vengo del organal;\nsigo comprando guayules,\nme voy hasta el arenal.",135,2,-1,138,"El pitayero",0,4,"a",1,0,-1,0,107,107,"6286","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6287",7,"Soy pitayero, señora,\nque vengo del organal;\nsi no compra, no mallugue:\nretírese del huacal.",135,2,-1,138,"El pitayero",0,4,"a",1,0,-1,0,107,107,"6287","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6288",7,"Solito vengo, señora,\ncon mi carga de pitayas;\ntraigo de todos colores,\ncómpreme antes que me vaya.",135,2,-1,138,"El pitayero",0,4,"aa",-1,0,-1,0,107,107,"6288","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6289",7,"Capulinero, señora,\nque cada año vengo aquí;\nvengo de tierras lejanas,\ndesde San Luis Potosí.",145,2,17,138,"El capulinero",0,4,"i",23,0,-1,0,107,107,"6289","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6290",7,"Vengo de tierra caliente,\nyo vengo de la labor;\nvengo a traerte la muestra\ndel frijol enredador.",135,2,-1,138,"El frijolito; Estrofa suelta",0,4,"o",72,0,-1,0,107,107,"6290","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6291",7,"Yo soy el que vendo\nnaranjas y limas,\na cuatro por veinte\ny a tres por cuartilla.",136,2,4,138,"El pájaro cú",0,4,"ia",-1,0,-1,0,107,107,"6291","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6292",7,"Lagunero soy, señores,\nvendo maiz, vendo panelas;\ntraigo mi chaqueta prieta\ny una casa muy bonita.",160,2,19,138,"Lagunerita",5,4,"ia",-1,0,-1,0,107,107,"6292","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6293",7,"Soy indito, vendo maiz,\nsoy indito, vendo mi sal,\nsigo contento, voy a vender,\nmuy sabroso lo vas a comer.",160,2,19,138,"Los inditos tzeltales",3,4,"e",20,0,-1,0,107,107,"6293","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6294c",7,"Somos indítaras michoacanítaras,\nque nos andámoro por lo portal,\nvendiendo guájeres y jicarítaras\ny florecítaras de temporal.",158,2,22,138,"Zapateado",3,4,"a",1,0,-1,0,108,108,"6294c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6294d",7,"Vendiendo guájereles y jicarítaralas\ny florecítaralas del temporal,\naunque muy pobre la guarecita,\npero aseadita del delantal.",137,2,3,138,"Canción de las canacuas",3,4,"a",1,0,-1,0,108,108,"6294d","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6295",7,"Yo soy indito mexicanito,\nque me mantengo de mi rosal,\nvendiendo flores y amapolitas,\ntambién monitas de Tonalá.",160,2,19,138,"El indio mexicano",3,4,"a",-1,0,-1,0,108,108,"6295","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6296",7,"Yo soy indita mexicanita,\nde Puebla vengo, voy para León,\nentre azucenas y maravillas,\nque llevan preso mi corazón.",135,2,-1,138,"La indita",3,4,"o",31,0,-1,0,108,108,"6296","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6297",7,"Yo soy la pajarerita,\nque todo el día vendo flores,\npajaritos cantadores,\nque les vengo a regalar.",155,2,14,138,"Tarihuán, Tarichuz",5,4,"a",-1,0,-1,0,108,108,"6297","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6298",7,"Aquí traigo las redes, Rosita,\npara ver si los puedo agarrar;\npajarillos que canten alegres\na buen precio los hemos de dar.",135,2,-1,138,"La pajarera",3,4,"a",21,0,-1,0,108,108,"6298","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6299",7,"Aquí te traigo las peras,\nguayabas y los perones,\ny en cada esquina me paro:\n“¿No me mercan los guajolotes?”",137,2,3,138,"Felicitación indígena",0,4,"oe",-1,0,-1,0,109,109,"6299","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6300",7,"Aquí te traigo el pescado\nde la laguna, señores;\naquí te traigo las peras,\nguayabas y tejocotes,\ny en cada esquina me paro:\n“¿No me mercan los melones?”",137,2,3,138,"Felicitación indígena",9,6,"oe",-1,0,-1,0,109,109,"6300","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6301",7,"¡Ay, de lo de vera venga!\nTraigo de varios colores:\ntraigo flores y jazmines,\nrecuerdo de tus amores.",142,2,8,138,"Estrofa suelta",0,4,"oe",5,0,-1,0,109,109,"6301","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6302",7,"Ostiones alvaradeños,\nlos que vengo a realizar:\na un precio más que barato\ncasi vengo a regalar.",135,2,-1,138,"Ostiones alvaradeños",0,4,"a",21,0,-1,0,109,109,"6302","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6304",7,"No sabes, china del alma,\nlas borandungas que traigo aquí:\ncebollas y chiles verdes,\njitomates y perejil.",145,2,17,138,"No sabes, china del alma",3,4,"i",-1,0,-1,0,109,109,"6304","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6305",7,"Camotes y más camotes,\nmelón-sandía, melón-zapote,\nnaranja dulce con jitomate,\nchilito verde con aguacate.",161,2,15,138,"El riqui-riqui",3,4,"ae",384,0,-1,0,109,109,"6305","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6307a",7,"Vengan a comprar\nante colimóte\na dos por un real,\nmirando que el tiempo\nestá muy fatal.",135,2,-1,138,"Pregón del ante",7,5,"a",1,0,-1,0,109,109,"6307a","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6307b",7,"Vengan a comprar\nel ante de almendra,\nde anís y de azahar,\na cuarto por medio\ny a dos por un real.",135,2,-1,138,"Pregón del ante",7,5,"a",-1,0,-1,0,109,109,"6307b","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6307c",7,"¡Ándele, aquí está el antel,\n¡ándele, cómprelo usted!,\na cuatro por medio\ny a seis por un real,\nmirando que el tiempo\nestá muy fatal.",144,2,10,138,"Pregón del ante",9,6,"a",1,0,-1,0,110,110,"6307c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6308",7,"Vengan, pues, a regalarse\ncon el ante de turrón:\ntiene almíbar y canela\ny es de un gusto seductor.",135,2,-1,138,"Pregón del ante",0,4,"o",-1,0,-1,0,110,110,"6308","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6309",7,"Deliciosas calabazas de Castilla,\ncómelas con mole, que son sabrosas,\ny verás después qué chulas cosas;\nsólo pido no olvides mi pilón.",135,2,-1,138,"Las calabazas",3,4,"o",-1,0,-1,0,110,110,"6309","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6310",7,"Pasen a tomar atole\ntodos los que van pasando,\nque si el atole está bueno,\nla atolera se está agriando.",139,2,2,138,"El jarabe",0,4,"ao",33,0,-1,0,110,110,"6310","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6311",7,"Éstos son los chiles verdes,\nque los venden en la plaza;\nel que no vaya a comprar\nque se vaya pa la casa.",136,2,4,138,"Los chiles verdes",0,4,"aa",123,0,-1,0,110,110,"6311","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6312",7,"Agua de té,\nté de limón,\ncinco de azúcar\ny diez de café.",148,2,9,138,"Estrofa suelta",6,4,"e",77,0,-1,0,110,110,"6312","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6313",7,"Café molido\nlo vendo yo,\na real la libra,\nmuy superior.",136,2,4,138,"El café",6,4,"o",-1,0,-1,0,110,110,"6313","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6314",7,"Café molido\nlo vende usted,\na real la libra,\ncafé con té.",136,2,4,138,"El café",6,4,"e",-1,0,-1,0,110,110,"6314","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6315",7,"Yo vendo café\npero de la esquina;\nque le eche la azúcar,\nseñora Joaquina.",136,2,4,138,"El café",0,4,"ia",11,0,-1,0,110,110,"6315","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6316",7,"Tengo una tiendita nueva,\n¿quién me la querrá comprar?\nTiene azúcar y canela\ny conchitas de la mar.",135,2,-1,138,"Si quieres, vamos al mar",0,4,"a",21,0,-1,0,110,110,"6316","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6317",7,"Aquí está la niña bailando,\ncon flores de violetas,\ny échele en la charola\nun puñito de pesetas.",162,2,27,138,"‘‘Baile de la muñeca",3,4,"ea",525,0,-1,0,111,111,"6317","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6318",7,"Baila, baila, Mariquita,\nporque tú no eres coqueta;\ny dirás a los señores caseros\nque te den una peseta.",162,2,27,138,"‘‘Baile de la muñeca",3,4,"ea",200,0,-1,0,111,111,"6318","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6319",7,"Con mucho gusto y alegría\nya se va la muñequita,\npero que le den dinero:\nsiquiera una pesetita.",162,2,27,138,"Baile de la muñeca",3,4,"ia",50,0,-1,0,111,111,"6319","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6320",7,"Vengan a comprar\nversitos de a medio,\ncanciones de a real,\npara la persona\nque guste comprar.",135,2,-1,138,"‘‘Pregón de los azucarillos; Pregón del ante",7,5,"a",-1,0,-1,0,111,111,"6320","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6321",7,"Compren estos nuevos versos,\ncántenlos hasta las cachas;\ntodos los que no los compren\nse volverán cucarachas.",135,2,-1,138,"La cucaracha",0,4,"aa",589,0,-1,0,111,111,"6321","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6322",7,"Ya con ésta me despido,\nya les canté mi corrido;\nvayan comprando la hojita,\npa que la canten seguido.",135,2,-1,138,"El valiente de San Juan del Río; Estrofa suelta",0,4,"io",101,0,-1,0,111,111,"6322","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6323",7,"Este corrido, señores,\ncuenta una historia sin par,\nconsérvenlo en su memoria,\ncómprenlo para su hogar.",135,2,-1,138,"Corrido de la entrada a México de las fuerzas obregonistas y gonzalistas",0,4,"a",21,0,-1,0,111,111,"6323","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6324",7,"En fin, señores, termino,\ny les pido su clemencia;\nel que compre este corrido\ntiene un año de indulgencia.",135,2,-1,138,"‘‘La cucaracha",0,4,"ea",46,0,-1,0,111,111,"6324","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6325",7,"Si te agradó este corrido,\nte suplico lo conserves,\nque lo escribió un artesano:\nsoy tu servidor, Juan Pérez.",135,2,-1,138,"Corrido de la toma de Guadalajara",0,4,"ee",-1,0,-1,0,111,111,"6325","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6326",7,"Ya nos vamos, mis señores:\n¿hasta cuándo nos veremos?\nVengan temprano mañana\ny traigan harto dinero.",155,2,14,138,"Tarihuán, tarichuz",0,4,"eo",-1,0,-1,0,112,112,"6326","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6327",7,"El judero ya se va,\nvolverá hasta el año que entra,\na vender judas y judas\npara acabalar su cuenta.",135,2,-1,138,"El judero",0,4,"ea",-1,0,-1,0,112,112,"6327","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6328",7,"Allá viene el carbonero\npor todita la cuchilla,\ny viene dando las cargas,\na dos y medio y cuartilla.",135,2,-1,138,"El carbonero",0,4,"ia",162,0,-1,0,112,112,"6328","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6329",7,"Áhi viene el aguamielero,\npor el cerro de La Cruz;\nviene a vender su aguamiel,\nantes que la primera luz.",135,2,-1,138,"El aguamielero",0,4,"u",109,0,-1,0,112,112,"6329","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6331",7,"Ya se va el aguamielero,\npues su aguamiel ya vendió;\nahora va por la aguamiel\nque su amor le prometió.",135,2,-1,138,"El aguamielero",0,4,"o",2,0,-1,0,112,112,"6331","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6332",7,"Áhi viene la capireña,\ncapires trae a vender:\ncapires a diez por medio,\ncapires al escoger.",135,2,-1,138,"Estrofa suelta",0,4,"e",20,0,-1,0,112,112,"6332","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6333",7,"Qué bonito es un chinaco\ncon su gorra galoneada,\ny si monta luego un penco,\nhasta me voy de paseada.",135,2,-1,138,"El chinaco",0,4,"aa",49,0,-1,0,112,112,"6333","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6334",7,"El gusto de los rancheros\nes tener un buen caballo,\napretarle bien la silla\ny luego correr por el llano.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"ao",-1,0,-1,0,112,112,"6334","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6335",7,"El gusto de los rancheros\nes usar un buen calzado\ny ponérselo el domingo\ncuando bajan al poblado.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"ao",14,0,-1,0,113,113,"6335","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6336",7,"El gusto de las rancheras\nes tener un buen comal,\nechar unas gordas largas\ny gritarle al gavilán.",147,2,11,138,"Allá en el Rancho Grande; El riquiriqui",0,4,"a",-1,0,-1,0,113,113,"6336","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6337",7,"El gusto de las rancheras\nes comprar su buen chomite\ny sentarse por las tardes\ncon su cazuela de esquites.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"ie",-1,0,-1,0,113,113,"6337","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6338",7,"El gusto de las rancheras\nes lucir su lindo chal,\nbailar muy bien el jarabe\ny enredar al caporal.",135,2,-1,138,"Allá en el Rancho Grande’",0,4,"a",1,0,-1,0,113,113,"6338","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6339",7,"El gusto de las rancheras\nes bajar al agua al pozo\ny platicar con el novio\ny estar mordiendo el rebozo.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"oo",-1,0,-1,0,113,113,"6339","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6340",7,"Es su orgullo su traje de charro,\ntraer su pistola fajada en el cinto,\ntener su guitarra pa echar mucho tipo,\ny a las que presumen quitarles el hipo.",135,2,-1,138,"Ay, Jalisco, no te rajes",3,4,"io",602,0,-1,0,113,113,"6340","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6341",7,"Mi coletito de cuero,\nmangas, puños de sayal:\ny éstas son las galas\nde mi caporal.",163,2,21,138,"Aquí me siento a cantar",0,4,"a",1,0,-1,0,113,113,"6341","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6342",7,"Viniendo del Contadero\nme dijo uno de Cortázar:\n“En un caballo ligero\ny ¡ah, qué bonito se laza!\nY aunque sea malo el vaquero,\nno más que abra buena gaza”.",136,2,4,138,"El toro Requesón; El caballito",9,6,"aa",307,0,-1,0,113,113,"6342","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6343",7,"¡Ay, qué bonita es la silla\ncuando se sabe montar!,\npues hasta en la mera trilla\nse puede uno resbalar.",135,2,-1,138,"Los vaqueros",1,4,"a",21,0,-1,0,113,113,"6343","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6344",7,"El ranchero es campesino,\nque su tierra la labora;\nasí será su destino,\nporque ilumina la aurora\nla tierra de un potosino.",138,2,6,138,"El ranchero potosino",7,5,"io",199,0,-1,0,114,114,"6344","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6346",7,"¡Ay, qué tierras tan delgadas\npa la siembra del frijol!\nSi lo escardan, se da bueno\ny si lo riegan, mejor.",135,2,-1,138,"El frijolito",0,4,"o",-1,0,-1,0,114,114,"6346","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6347",7,"Si lo siembran en su tiempo,\nsi lo escardan, es mejor,\ny si le aciertan el riego,\n¡ah, qué abundancia de frijol!",139,2,2,138,"Estrofa suelta, El frijolito",0,4,"o",-1,0,-1,0,114,114,"6347","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6348",7,"El gusto de los arrieros\nes tener sus buenos burros,\npara alzar a los caminos\ny gastarse unos pesos duros.",137,2,3,138,"El riqui-riqui",0,4,"uo",-1,0,-1,0,114,114,"6348","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6349",7,"Mandé hacer a un carpintero\nuna almohadilla plateada,\ny fue tan fino en hacerla,\nque la hizo sobredorada.",136,2,4,138,"El carpintero",3,4,"aa",49,0,-1,0,114,114,"6349","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6351",7,"Yo conocí un carpintero\nque vivía en un campamento,\nque empalmaba un tinajero\ndel aire de puro viento;\n¡ése sí era carpintero\ny hombre de mucho talento!",136,2,4,138,"El pájaro carpintero",9,6,"eo",-1,0,-1,0,114,114,"6351","",0,"frenk_t4","","",13,0,0,[],"",""],["frenk_t3-n6352",7,"Yo conocí un carpintero\nque no era de los muy malos,\nque formaba un tinajero\nen la palma de la mano:\n¡ése sí era carpintero!",136,2,4,138,"El pájaro carpintero",7,5,"eo",38,0,-1,0,114,114,"6352","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6353",7,"Yo conocí a un carpintero\nque se llamaba Mariano,\ny formaba un tinajero\ncon el sombrero en la mano.",140,2,12,138,"El pájaro carpintero",1,4,"ao",81,0,-1,0,115,115,"6353","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6354",7,"Yo conocí un carpintero\nque se llamaba Manuel,\nque formaba un tinajero\ndel cojollo de un laurel:\n¡ése sí era un carpintero,\ny a ver qué me dices de él!",136,2,4,138,"El pájaro carpintero",9,6,"e",32,0,-1,0,115,115,"6354","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6355",7,"Yo conocí un carpintero\nque se nombra Francisquito;\nése era buen carpintero,\nque formaba su tinajerito\nen las ramas de un laurelito.",136,2,4,138,"El pájaro carpintero",7,5,"io",119,0,-1,0,115,115,"6355","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6356a",7,"Yo conocí un carpintero\nque se llamaba Felipe,\ny formaba un tinajero\nde los palos de un mezquite.",136,2,4,138,"El pájaro carpintero",0,4,"ie",-1,0,-1,0,115,115,"6356a","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6356b",7,"Yo conocí un carpintero\nque se llamaba Felipe,\nque formaba un tinajero\ndel cojollo de un quelite:\n¡ése sí era caipintero\nde los buenos quelequitos!",136,2,4,138,"El pájaro carpintero",9,6,"io",-1,0,-1,0,115,115,"6356b","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6357a",7,"Yo conocí un carpintero\nque se llamaba Gonzalo,\nque formaba un tinajero\nhasta que naciera el palo,\ny no cobraba dinero.",136,2,4,138,"El pájaro carpintero",7,5,"eo",38,0,-1,0,115,115,"6357a","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6357c",7,"Yo conocí a un carpintero,\ny éste se llamaba Pablo,\nque formaba un tinajero\ny antes que naciera el palo:\n¡éste sí era carpintero\nde los de primera mano!",136,2,4,138,"El pájaro carpintero",9,6,"ao",-1,0,-1,0,115,115,"6357c","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6358",7,"Yo conocí a un carpintero\nque se llamaba Delfín;\nte formaba un tirantero\nde la vara de un violín:\n¡ése sí era carpintero\ndel pueblo de Medellín!",136,2,4,138,"El pájaro carpintero",9,6,"i",211,0,-1,0,115,115,"6358","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6359",7,"Yo conocí a un carpintero\nque se llamaba tío Bucio,\nque formaba un tinajero (¡ay vida mía, vida\nen la cruz de un manco rucio,\ny no cobraba dinero.",136,2,4,138,"El carpintero",7,5,"eo",38,0,-1,0,116,116,"6359","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6360",7,"Yo conocí un carpintero\npor el camino de Amula,\nque formaba un tinajero\nde los huesos de una muía,\ny no cobraba dinero.",136,2,4,138,"El pájaro carpintero",7,5,"eo",38,0,-1,0,116,116,"6360","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6361",7,"Ya voy a cambiar de ruta:\nvoy a vender mi jarana,\nvoy a comerciar con fruta,\nya sean peras o manzanas,\nporque la mala conducta\nsuena más que una campana.",136,2,4,138,"El Balajú",9,6,"aa",-1,0,-1,0,116,116,"6361","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6363",7,"Cuando el marinero mira\nla borrasca por el cielo,\nalza la cara y suspira\ny le dice al compañero:\n“Si Dios me salva la vida,\nno vuelvo a ser marinero”.",136,2,4,138,"La sirena; La Petenera",9,6,"eo",38,0,-1,0,116,116,"6363","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6364",7,"Cuando el marinero mira\nla vela que se hace un arco,\nalza la vista y suspira,\nle dice al patrón del barco:\n“Mientras Dios me preste vida,\nque haiga otro que brinque el charco”.",138,2,6,138,"La Petenera",9,6,"ao",591,0,-1,0,116,116,"6364","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6365",7,"Al pie de un verde manzano\nme puse a considerar\nlos trabajos que pasaba\nel marinero en la mar.",135,2,-1,138,"Ya parece, ya parece",0,4,"a",21,0,-1,0,116,116,"6365","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6366",7,"Pobres ferrocarrileros:\nno pueden tener mujer,\nporque la vida la tienen\nentre las ruedas del tren.",161,2,15,138,"La rielera",0,4,"e",-1,0,-1,0,116,116,"6366","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6367",7,"¡Ay, pobres de los arrieros,\ntirados por los caminos,\ny las mujeres allá,\ncon diferentes maridos!",136,2,4,138,"Los arrieros",0,4,"io",-1,0,-1,0,117,117,"6367","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6368",7,"Yo soy el arriero tonche\ntirado por los caminos,\nque andando cortando pionches\ntirado por los caminos.",136,2,4,138,"Los arrieros",0,4,"io",-1,0,-1,0,117,117,"6368","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6369",7,"Dicen que los artilleros\ntienen la vida vendida,\nporque son tan lisonjeros,\nque tienen por su guarida.",135,2,-1,138,"‘‘Los artilleros",1,4,"ia",37,0,-1,0,117,117,"6369","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6370",7,"Arrejúntale los bueyes,\nque llegó la hora de uncir;\ntrabajando vive Pancho,\ntrabajando hasta morir.",135,2,-1,138,"El Pancho",0,4,"i",157,0,-1,0,117,117,"6370","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6371",7,"Y al carretero, mamá,\nse le perdieron los bueyes;\nhora los anda buscando (mamá)\ndebajo de los magueyes.",136,2,4,138,"El carretero",3,4,"ee",600,0,-1,0,117,117,"6371","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6372",7,"Y al carretero, mamá,\nse le perdieron las mulas;\nhora las anda buscando (mamá)\na orillas de la laguna.",136,2,4,138,"El carretero",3,4,"ua",-1,0,-1,0,117,117,"6372","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6373",7,"Y al carretero, mamá,\nse le rompió la carreta;\nhora la anda remendando (mamá)\ncon cachitos de baqueta.",136,2,4,138,"El carretero",3,4,"ea",200,0,-1,0,117,117,"6373","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6374",7,"Pobrecito carretero (mamá):\nse le rompió el carretón,\ny ahora lo va a remendar (mamá)\ncon cuerito de ratón.",140,2,12,138,"El carretero",3,4,"o",31,0,-1,0,117,117,"6374","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6375",7,"El carretero se va,\nya se va para Amacueca;\nel carretero no va:\nse le quebró la carreta.",145,2,17,138,"‘‘El carretero",0,4,"ea",-1,0,-1,0,117,117,"6375","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6376",7,"El carretero se va,\nya se va pa La Sauceda;\nel carretero no va;\nse le ha quebrado una rueda.",145,2,17,138,"‘‘El carretero",1,4,"ea",266,0,-1,0,117,117,"6376","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6377",7,"El carretero se va,\nya se va para Los Reyes;\nel carretero no va,\nporque le faltan los bueyes.",145,2,17,138,"El carretero",1,4,"ee",600,0,-1,0,118,118,"6377","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6378",7,"El carretero se va,\nya se va para Sayula;\nel carretero no va,\nporque le falta una mula.",145,2,17,138,"El carretero",1,4,"ua",547,0,-1,0,118,118,"6378","",0,"frenk_t4","","",11,0,0,[],"",""],["frenk_t3-n6379",7,"El carretero se va,\nya se va pa El Carrizal;\nel carretero no va,\nporque le falta un pretal.",145,2,17,138,"El carretero",1,4,"a",-1,0,-1,0,118,118,"6379","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6380",7,"El carretero se va,\nya se va pa Los Esteros;\nel carretero no va,\nporque le faltan los cueros.",145,2,17,138,"El carretero",1,4,"eo",22,0,-1,0,118,118,"6380","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6381",7,"El carretero se va,\nya se va para El Potrero;\nel carretero no va,\nporque le falta dinero.",145,2,17,138,"El carretero",1,4,"eo",38,0,-1,0,118,118,"6381","",0,"frenk_t4","","",11,0,0,[],"",""],["frenk_t3-n6382",7,"El carretero se va,\nya se va para La Unión;\nel carretero no va,\nporque le falta el camión.",145,2,17,138,"El carretero",1,4,"o",31,0,-1,0,118,118,"6382","",0,"frenk_t4","","",11,0,0,[],"",""],["frenk_t3-n6383",7,"Para salir el lucero,\ncanta el pájaro silvestre;\nse oye silbar al ranchero,\na la cintura el machete:\nva a trabajar al potrero.",138,2,6,138,"El ranchero potosino",7,5,"eo",38,0,-1,0,118,118,"6383","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6384",7,"Ya se va ocultando el sol,\nel huasteco va contento;\nregresa de su labor,\ny lleva en su pensamiento\na la dueña de su amor.",139,2,2,138,"Atardecer huasteco",7,5,"o",72,0,-1,0,118,118,"6384","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6385",7,"Áhi anda el pajarerito,\nbuscando por plan y cerros\ncenzontles muy cantadores,\nmulatitos y jilgueros.",135,2,-1,138,"El pajarerito",0,4,"eo",-1,0,-1,0,118,118,"6385","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6386",7,"Una indita en su chinampa\ncultivaba mirasoles,\ncultivaba nomeolvides\ny malvones de colores.",136,2,4,138,"Estrofa suelta",0,4,"oe",-1,0,-1,0,119,119,"6386","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6387",7,"Me subí a la punta del ceno\na divisar para el rincón;\nallá vi a mi negrito,\ncortando flor de algodón.\nPrimero le echo la tierra\ny después le pido perdón.",142,2,8,138,"Estrofa suelta",9,6,"o",31,0,-1,0,119,119,"6387","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6388",7,"El vecino de allí enfrente\ntiene su panadería;\na los ricos les fiaba\ny a los pobres les vendía.",135,2,-1,138,"Estrofa suelta",0,4,"ia",0,0,-1,0,119,119,"6388","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6389",7,"En la puerta de un zaguán\nlloraban los panaderos,\npor una pieza de pan\nque se llevaban los perros;\nyo se la voy a quitar,\naunque me embarre los dedos.",135,2,-1,138,"‘‘Los panaderos",9,6,"eo",-1,0,-1,0,119,119,"6389","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6390",7,"Un carbonero en su tierra\nloco se ha vuelto de gusto,\npero otro que es de razón\nse está zurrando del susto.",135,2,-1,138,"Estrofa suelta",0,4,"uo",497,0,-1,0,119,119,"6390","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6391",7,"Si buscas el marinero,\nya se lo llevó el navio,\ny dice que fue a salir\na San Juan Maravatío.",137,2,3,138,"El marinero",0,4,"io",3,0,-1,0,119,119,"6391","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6392",7,"Si buscas al marinero,\nen la mar lo encontrarás,\ncon las velas en la mano\ny los buques por detrás.",137,2,3,138,"El marinero",0,4,"a",51,0,-1,0,119,119,"6392","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6393",7,"Allá vienen unos,\nparecen arrieros;\npero no traen mulas:\nserán forasteros.",136,2,4,138,"‘‘El pájaro cú",0,4,"eo",22,0,-1,0,119,119,"6393","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6394",7,"Cuando la muía relincha\ndentro de un zacatonal\nes señal que los arrieros\n’tan cenando con tamal.",144,2,10,138,"‘‘Cuando la muía relincha",0,4,"a",1,0,-1,0,119,119,"6394","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6395",7,"Cuando el pescador empieza\na dar golpes en el remo\nsalen los indios diciendo:\n“Juiles son los que queremos”.",135,2,-1,138,"El fandanguito",0,4,"eo",-1,0,-1,0,119,119,"6395","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6396a",7,"Cuando el pescador empieza\na dar golpes en el banco\nsalen las indias diciendo:\n“Juiles y robalo blanco”.",136,2,4,138,"'Los juiles; El fandanguito",0,4,"ao",303,0,-1,0,120,120,"6396a","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n6397",7,"Cuando el pescador empieza\na dar golpes en el bote\nsalen las indias diciendo:\n“Juiles, robalo y jolote”.",136,2,4,138,"Los juiles",0,4,"oe",292,0,-1,0,120,120,"6397","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n6398",7,"Cuando el pescador empieza\na dar golpes en el río\nsalen las indias diciendo:\n“Todos los juiles son míos”.",135,2,-1,138,"Los juiles",0,4,"io",-1,0,-1,0,120,120,"6398","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n6399",7,"Lloraba el atajador\na orillas de una barranca,\nporque se le había perdido\nla mula prieta y la blanca.",135,2,-1,138,"Los arrieros",0,4,"aa",75,0,-1,0,120,120,"6399","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6400",7,"Lloraba el atajador\nlágrimas en el camino,\nporque se le había perdido\nel macho prieto y el pinto.",135,2,-1,138,"Los arrieros",0,4,"io",-1,0,-1,0,120,120,"6400","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6401",7,"Gritó un vaquero picado,\nperdido entre el matorral:\n“La potranca se ha pelado,\ny no vuelve a su corral”.",135,2,-1,138,"La potranca colorada",1,4,"a",1,0,-1,0,120,120,"6401","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6402",7,"De los vaqueros que tengo\nuno que sepa lazar\nquiero que lace el novillo\nque se salió del corral.",137,2,3,138,"El novillo despuntado",0,4,"a",-1,0,-1,0,120,120,"6402","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6403",7,"Allá viene el caporal,\npero con mucha alegría,\ndiciéndole a sus vaqueros:\n“Vamos a lo de Mejía”.",142,2,8,138,"El toro",0,4,"ia",0,0,-1,0,120,120,"6403","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6404",7,"Allá viene el caporal\nen su caballo retinto,\ndiciéndole a sus vaqueros:\n“Lácenme ese toro pinto”.",142,2,8,138,"El toro",0,4,"io",527,0,-1,0,120,120,"6404","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6405",7,"Por áhi viene el caporal,\ncayéndose de borracho,\ndiciéndole a los vaqueros:\n“¡Lácenme ese toro gacho!”",137,2,3,138,"El toro",0,4,"ao",310,0,-1,0,121,121,"6405","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6406",7,"Allá viene el caporal,\ncayéndose de borracho;\nun cuerno lo tiene roto,\ny el otro lo tiene gacho.",145,2,17,138,"El toro",0,4,"ao",310,0,-1,0,121,121,"6406","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6407",7,"Allá viene el caporal,\ncayéndose de trompeto,\ndiciéndole a los vaqueros:\n“¡Échenme ese toro prieto!”",135,2,-1,138,"El toro",0,4,"eo",-1,0,-1,0,121,121,"6407","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6408",7,"Por áhi viene el caporal,\npor áhi viene muy contento;\nno más que trae el morral:\n¿sabe lo que trae adentro?\nDinero para gastar\ny tabaco pa fumar.",138,2,6,138,"El toro Requesón",9,6,"a",21,0,-1,0,121,121,"6408","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6409",7,"Abran el corral, muchachos,\nque allá viene el caporal:\nviene coleando un novillo\npor ese camino real,\na ver si logra alcanzarlo\npa poderlo jinetear.",135,2,-1,138,"El caporal",9,6,"a",-1,0,-1,0,121,121,"6409","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6410",7,"Por áhi viene el caporal,\npor áhi viene, chiquitita;\ndice que no pudo hallar\nel toro y la becerrita\npara echarle una mangana,\nque hasta rechine la pita.",138,2,6,138,"El toro Requesón",9,6,"ia",50,0,-1,0,121,121,"6410","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6411",7,"Áhi les va mi caporal\npor la orilla de esa loma;\nanda queriendo lazar\nel toro y la novillona,\nque se salió del corral\njunto con la cuatezona.",139,2,2,138,"El toro Requesón",9,6,"oa",7,0,-1,0,121,121,"6411","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6412",7,"La vaquilla colorada\ny el novillo despuntado\nal torito cinco de oros\nlo dejaron olvidado:\nfueron por la potranquita\nque se quedó en el vallado.",135,2,-1,138,"Huapango de huapangos",9,6,"ao",14,0,-1,0,121,121,"6412","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6413",7,"¡Ay, pobres los vaqueros!,\nya no aguantan a la mora:\nanda con todos los toros\ndel rancho de ’ña Ramona;\nya se pasó los linderos\neste diablo de vaca mora.",135,2,-1,138,"La vaca mora",9,6,"oa",-1,0,-1,0,121,121,"6413","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6414",7,"Por áhi vienen los vaqueros\ncon sus trajes domingueros;\ntienen gusto, pues la mora\nya tuvo sus seis temeros:\nahora sí dejará en paz\na los pobres becerreros.",135,2,-1,138,"La vaca mora",9,6,"eo",22,0,-1,0,122,122,"6414","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6415",7,"En la hacienda del Limón\nse ha ofrecido una aventada;\ncon toda la vaquerada\nse fueron para Aragón.",135,2,-1,138,"La sandía",11,4,"o",31,0,-1,0,122,122,"6415","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6416",7,"Y cuando un vaquero dice\nen las puertas de un corral:\n“En el nombre de María,\nvoy a tirar este pial”.",136,2,4,138,"Un día me fui a pasear",0,4,"a",1,0,-1,0,122,122,"6416","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6417",7,"Cuando los vaqueros van\nal llano de Nopalapa\nen su caballo alazán,\ndiciéndole al toro: “¡Japa,\njapa, torito galán!”",136,2,4,138,"El torito",7,5,"a",147,0,-1,0,122,122,"6417","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6418",7,"Lucho puso el precio,\ny se han arreglado\nen treinta y dos pesos,\ncincuenta centavos.",136,2,4,138,"El toro",0,4,"ao",-1,0,-1,0,122,122,"6418","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6419",7,"Don Albino Lara,\ncomo hombre afamado,\nsalió este toro\npara este ganado.",136,2,4,138,"El toro",6,4,"ao",14,0,-1,0,122,122,"6419","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6420",7,"Don Albino Lara,\npara la campaña,\nmarcó veinticuatro,\nse fueron pa fuera,\ny salieron rumbo\npara la Galera.\nPara la campaña,\nel toro afamado,\npero no habían visto\nque lo habían aporreado.",136,2,4,138,"El toro",18,10,"ao",14,0,-1,0,122,122,"6420","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6421",7,"Traigo un estribillo\nde varios vaqueros,\ncon su tocadillo,\ncomo ganadero;\nles pongo cerillos\npa capar novillos\ny a los toros, cencerro.",136,2,4,138,"El toro",4,7,"eo",-1,0,-1,0,122,122,"6421","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6422",7,"Si fueres a los toros,\ncuando los haya,\nno montes en la rucia,\nsino en la baya.",136,2,4,138,"Churripampli se casa",6,4,"aa",404,0,-1,0,122,122,"6422","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6423",7,"Palmero, sube a la palma,\nsube a la palma, palmero,\ny de los cocos más grandes\nhazle su carga al arriero.",135,2,-1,138,"El palmero",0,4,"eo",38,0,-1,0,123,123,"6423","",0,"","","",16,0,0,[],"",""],["frenk_t3-n6424",7,"Palmero, sube a la palma\ny vela descojoyando,\npara hacerte tu sombrero,\nde los que se andan usando.",135,2,-1,138,"‘‘El palmero",0,4,"ao",33,0,-1,0,123,123,"6424","",0,"","","",16,0,0,[],"",""],["frenk_t3-n6425",7,"Ciérnele, ciérnele, panadero,\nciérnele, ciérnele sin cesar,\nque a las once de la noche\neste pan se ha de entregar.",139,2,2,138,"Los panaderos",3,4,"a",21,0,-1,0,123,123,"6425","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6426",7,"¿Dónde estabas, panadero,\nque no te pude hallar?\nDéjenmelo allí solito,\nque lo voy a castigar.",135,2,-1,138,"Estrofa suelta",0,4,"a",21,0,-1,0,123,123,"6426","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6427",7,"Vamos, remadores,\nvamos a remar,\na juntar conchitas\na orillas del mar.",147,2,11,138,"Las conchitas",0,4,"a",21,0,-1,0,123,123,"6427","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6431",7,"Carpintero, amigo mío,\nquiero mi cama dorada,\ny después te la pagaré\nallá por la madrugada.",140,2,12,138,"‘‘El pájaro carpintero",0,4,"aa",49,0,-1,0,123,123,"6431","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6432",7,"Carpintero de mi vida,\nhazme una cama decente,\nque te la voy a pagar\ncon el sudor de mi frente.",136,2,4,138,"El pájaro carpintero",0,4,"ee",15,0,-1,0,123,123,"6432","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6433",7,"Me dirás cuál es tu muía:\nsi es una muía retinta,\nme la prestarás mañana\npara pasear a Jacinta.",135,2,-1,138,"¡Arre muía, arre macho!",0,4,"ia",155,0,-1,0,124,124,"6433","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6434",7,"Soldadito, estáte alerta,\nque en el jardín hay bulla;\nsi oyes que tocan la puerta,\nresponde, por vida tuya;\naquí no hay mujeres de sobra:\ncada quien tiene la suya.",136,2,4,138,"Estrofa suelta",9,6,"ua",111,0,-1,0,124,124,"6434","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6435",7,"En la sierra no hay claveles,\nporque los marchita el hielo;\nsólo en tu jardín los hay,\nporque eres capulinero.",145,2,17,138,"El capulinero",0,4,"eo",-1,0,-1,0,124,124,"6435","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6436",7,"Señor carretero,\nle vengo a avisar\nque sus animales\nse le iban a ahogar,\nunos en la arena,\notros en la mar.",145,2,17,138,"El carretero",9,6,"a",21,0,-1,0,124,124,"6436","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6437",7,"Señor carretero,\nte vengo a avisar\nque encierres tus mulas\nen ese corral.",140,2,12,138,"El carretero",0,4,"a",-1,0,-1,0,124,124,"6437","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6438",7,"¡Ay, amigo, su carreta\nno se le vaya a quebrar!\nAvísele a los yunteros\nque la vengan a sacar.",145,2,17,138,"El carretero",0,4,"a",21,0,-1,0,124,124,"6438","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6439",7,"¡Órale, muchachos!,\nvengan a empujar,\npa que la carreta\npueda caminar.",147,2,11,138,"El carretero",0,4,"a",21,0,-1,0,124,124,"6439","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6440",7,"Por áhi va la rueda,\ndéjenla rodar,\nporque la carreta\nno puede llegar.",145,2,17,138,"El carretero",0,4,"a",21,0,-1,0,124,124,"6440","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6441",7,"Áhi viene el toro,\nahora chulapearemos;\ndeja que venga:\naquí lo capotearemos.",135,2,-1,138,"El torito",3,4,"eo",127,0,-1,0,125,125,"6441","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6442",7,"Vamos a correr el toro\nal llano de Nopalapa;\nvamos a correr el toro;\nunos dicen: “¡Japa, japa!”",136,2,4,138,"El toro",1,4,"aa",297,0,-1,0,125,125,"6442","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6443a",7,"¡Upa, toro!,\n¡áhi viene el toro!\nSácale vueltas,\npero con modo.",135,2,-1,138,"El toro",3,4,"oo",-1,0,-1,0,125,125,"6443a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6443b",7,"¡Ea, ea, toma, toma!,\n¡hazte, muchacho!,\nque áhi viene el toro;\nsácale vuelta,\npero con modo.",145,2,17,138,"El toro",7,5,"oo",-1,0,-1,0,125,125,"6443b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6444",7,"¡Átalo, átalo, átalo!,\nque se te iba;\néste ya me lo habían toreado:\nsi no, yo te bajo de arriba.",136,2,4,138,"El torito",3,4,"ia",140,0,-1,0,125,125,"6444","",0,"frenk_t4","","",3,0,0,[],"",""],["frenk_t3-n6445",7,"¡Lácenlo, hombre, lácenlo, hombre!,\n¡lácenme ese toro gacho!\n¡Lácenlo, hombre, lácenlo, hombre!,\n¡que no se vaya, muchacho!",135,2,-1,138,"El toro",1,4,"ao",310,0,-1,0,125,125,"6445","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6447",7,"¡Ay, qué mula tan rejega!,\nparece que está parida;\npónganle un tapojo nuevo,\nporque nos puede tumbar.",135,2,-1,138,"La mulita",5,4,"a",-1,0,-1,0,127,127,"6447","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6448",7,"Ya la muía está pasmada,\nya no la puedo montar;\npóngale un parche con unto,\nque no se vaya a respingar.",135,2,-1,138,"La mulita",0,4,"a",21,0,-1,0,127,127,"6448","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6449",7,"Ese toro no es de aquí:\nes del rancho Purangueo;\nel que le quiera montar\nno se quede con deseo.",146,2,7,138,"El toro",0,4,"eo",66,0,-1,0,127,127,"6449","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6450",7,"Ya volaron las torcazas\na la rama de un [laurel?];\náhi viene el toro de plaza,\nsalgan a jugar con él.",135,2,-1,138,"Las torcazas",0,4,"e",32,0,-1,0,127,127,"6450","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6451",7,"Ese toro no es de aquí:\nes bajado de la sierra;\néchenselo para fuera\nal señor Francisco Sierra.",146,2,7,138,"El toro",0,4,"ea",-1,0,-1,0,127,127,"6451","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6452",7,"El caporal ya llegó,\nmontado en muía retinta;\n¡anda, Pancho, pa el corral!,\n¡échale la vaca pinta!",135,2,-1,138,"El Pancho",0,4,"ia",155,0,-1,0,128,128,"6452","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6453",7,"¡Ay, ay, ay, ay!,\n¡córrele caporal!,\nque este torito es bravo,\nno te vaya a cornear.",146,2,7,138,"El toro",3,4,"a",-1,0,-1,0,128,128,"6453","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6454",7,"Áhi viene el toro bragado,\nel torito bramador;\nno sea usted tan arrugado,\nviejo tan vacilador.",135,2,-1,138,"‘‘Los vaqueros",1,4,"o",72,0,-1,0,128,128,"6454","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6455",7,"Échele bien ese peal,\nno le jale no más de una,\nque el chiste no está en el mear,\nsino en el hacer espuma.",135,2,-1,138,"Estrofa suelta",0,4,"ua",-1,0,-1,0,128,128,"6455","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6457a",7,"Muchachos, allá va el toro,\n¡no los vaya a revolcar!\nVáyanse al monte,\npara que lo puedan torear.",137,2,3,138,"‘‘El toro",3,4,"a",21,0,-1,0,128,128,"6457a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6457c",7,"Muchachotes, áhi va el tor\nno se lo dejen llegar,\nporque ese torito es bravo:\n¡no los vaya a remontar!\nÁhi les mandaré el capote\npa que lo puedan torear.",137,2,3,138,"El toro",9,6,"a",21,0,-1,0,128,128,"6457c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6458",7,"No se lo dejen llegar,\nporque ese torito..........;\náhi les mandaré un capote\npor fuera de las murallas.",137,2,3,138,"El toro",5,4,"aa",-1,0,-1,0,128,128,"6458","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6459",7,"Allá te va este toro,\nhijo de la Nana Cota;\nno te causará tu lloro,\nsi sabes jugar la sota.",135,2,-1,138,"Los vaqueros",1,4,"oa",432,0,-1,0,128,128,"6459","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6460",7,"Traigan sus lazos, vaqueros,\nno vino con la manada:\nse rezagó en los potreros\nla potranca colorada.",135,2,-1,138,"La potranca colorada",1,4,"aa",49,0,-1,0,129,129,"6460","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6461",7,"Vayan por el pedregal,\ncorran para la quebrada,\nronden por el manantial,\nsigan tras la yegua alzada.",135,2,-1,138,"La potranca colorada",1,4,"aa",49,0,-1,0,129,129,"6461","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6462",7,"Ve a ver cuál es el toro\nque brama tras de la loma,\nque ya no se le ven las patas:\nno más la cabeza asoma.",135,2,-1,138,"La vaca",0,4,"oa",86,0,-1,0,129,129,"6462","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6463",7,"Era su mirasol,\nya se le olvidó su mata;\nahí está esa vaca brava,\ncon Miguel, el de la cuadra:\nmírala, vele la pata.",137,2,3,138,"El mirasol",7,5,"aa",-1,0,-1,0,129,129,"6463","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6464",7,"Áhi vienen por la ladera,\ncuando los pierdas de vista;\nes el toro Requesón,\nque viene con la ternera;\nsíguele, viejo, la pista,\npos pa que entren al cañón.",139,2,2,138,"El toro Requesón",9,6,"o",31,0,-1,0,129,129,"6464","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6465",7,"Se va el toro con el peal,\nque ni la gaza le roza;\natajen ese animal,\nporque la troza y la troza,",135,2,-1,138,"Soy de Zacatula",1,4,"oa",195,0,-1,0,129,129,"6465","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6466",7,"La vaquilla cuernos mochos\nse subió en una ladera;\nanda, dile al patroncito\nque se meta y la eche fuera.",135,2,-1,138,"El toro",0,4,"ea",44,0,-1,0,129,129,"6466","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6467",7,"Le dirás al caporal\nque se venga por la orilla,\nque a la puerta del corral\ntengo lista la vaquilla.",145,2,17,138,"La vaquilla",1,4,"ia",162,0,-1,0,129,129,"6467","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6468",7,"Le dirás al caporal\nque se baje para el plan,\nque me traiga la vaquilla,\nporque ahora es día de San Juan.",135,2,-1,138,"La vaquilla",3,4,"a",147,0,-1,0,129,129,"6468","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6469",7,"Le dirás al caporal\nque se baje para el pozo,\nque se traiga la vaquilla\ncon el cabresto barroso.",135,2,-1,138,"La vaquilla",0,4,"oo",160,0,-1,0,129,129,"6469","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6470",7,"Le dirás al caporal\nque se baje pa el encino,\nque se traiga la vaquilla\ncon el cabresto más fino.",135,2,-1,138,"La vaquilla",0,4,"io",199,0,-1,0,130,130,"6470","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6471",7,"Vaquerito, vaquerito,\npide pienso al mayoral,\nque el ganado se te pierde,\nque el ganado se te va.",135,2,-1,138,"El vaquerito",0,4,"a",-1,0,-1,0,130,130,"6471","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6472",7,"Avísale al mayoral\nque el vaquero se mató,\nque en la puerta del corral (¡ay, amor, amor,\nel toro pinto lo hirió. [amor!)",136,2,4,138,"El toro",3,4,"o",-1,0,-1,0,130,130,"6472","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6474",7,"Avísale al caporal\nque un vaquero no ha llegado:\nlo sorprendió el caporal,\ncuando iba arreando el ganado,\nallá por el carrizal.",136,2,4,138,"El torito",7,5,"a",1,0,-1,0,130,130,"6474","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6475",7,"—Becerrero, becerrero,\n¿dónde dejaste los piales?\n—En la puerta del chiquero,\n[amor!) allí quedaron cabales.",146,2,7,138,"La cuera; El toro",3,4,"ae",26,0,-1,0,130,130,"6475","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6477",7,"Áhi viene la lluvia gruesa\npor aquellas dos lomitas;\nque nos llegue a la cabeza,\nque nazcan bien las milpitas,\nlos ejotes de la mesa,\ntambién las calabacitas.",135,2,-1,138,"Ahí viene el agua",9,6,"ia",258,0,-1,0,131,131,"6477","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6478",7,"¡Ay, compadrito, señor!,\n¡ay, qué bien va mi labor!\nSi se me da temprano,\ngrano por grano,\nya sin desgano\nbusco un amor.",137,2,3,138,"Las dos Marías",9,6,"o",72,0,-1,0,131,131,"6478","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6479",7,"¡Ay, yo seré escardador\ndel chayóte regador!\nCuando se viene tarde,\nmire compadre,\nsiento que me arde\nhasta el corazón.",137,2,3,138,"Las dos Marías",9,6,"o",-1,0,-1,0,131,131,"6479","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6480",7,"Te voy a hacer tu camisa\ncomo las que usa un ranchero:\ncon el cuello a media espalda\ny las mangas hasta el suelo.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"eo",-1,0,-1,0,131,131,"6480","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6481",7,"Te voy a hacer tus calzones\ncomo los usa el ranchero:\nte los comienzo de lana,\nte los acabo de cuero.",135,2,-1,138,"Allá en el Rancho Grande",0,4,"eo",38,0,-1,0,131,131,"6481","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6482",7,"Tengo yo mi galoneado\npara pasearme en el rancho;\nmi chata me lo ha adornado,\npues le gusta el sombrero ancho.",135,2,-1,138,"El sombrero ancho",1,4,"ao",-1,0,-1,0,131,131,"6482","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6483a",7,"En Celaya compré el hule,\nen Querétaro el sombrero,\nen Guanajuato le puse\ntoquilla de terciopelo.",135,2,-1,138,"El sombrero ancho",0,4,"eo",-1,0,-1,0,131,131,"6483a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6483b",7,"En Celaya compré el hule,\nen Querétaro el sombrero,\ny en Guanajuato le puse\ntoquilla de terciopelo;\ny una tarde allá en los toros\ncuatro jirones lo hicieron.",135,2,-1,138,"Las barrancas",9,6,"eo",-1,0,-1,0,131,131,"6483b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6484",7,"La vaquilla que yo busco\nno es pinta, ni es colorada:\nes una vaquilla hermosa,\nde las llaves asenada.",135,2,-1,138,"La vaquilla",0,4,"aa",49,0,-1,0,131,131,"6484","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6485",7,"Ando buscando un novillo\ndel fierro de doña Petra;\nhace tres días que lo vide,\njunto con la vaca prieta.",137,2,3,138,"El novillo despuntado",0,4,"ea",-1,0,-1,0,132,132,"6485","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6486",7,"Ando buscando un novillo\ndel fierro de Las Sauceras;\nhace tres días que lo vide,\njunto con las marineras.",137,2,3,138,"El novillo despuntado",0,4,"ea",103,0,-1,0,132,132,"6486","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6488",7,"Ando buscando un novillo\nque se salió del corral,\ntiene la frente morena,\ncomo la tiene mi amor.",135,2,-1,138,"El novillo despuntado",5,4,"o",-1,0,-1,0,132,132,"6488","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6489",7,"Mañana voy al rodeo\na aprender a manganear,\nporque me parece feo\nque todos sepan manguear,\ny yo nada más lo veo.",136,2,4,138,"El toro",7,5,"eo",66,0,-1,0,132,132,"6489","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6490",7,"Voy a comprarme mi reata\npara enseñarme a lazar;\nya conozco mi rodilla\npara echarme el primer pial.",138,2,6,138,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,132,132,"6490","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6491",7,"Voy a comprar mi soguilla\npara enseñarme a lazar;\ntraigo aquí mi rodillera\ny yo no me hago pa atrás.",135,2,-1,138,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,132,132,"6491","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6492",7,"Al pobre no le hacen caso,\nporque no le ven dinero;\nvoy a comprarme un buen lazo\ny un caballito ligero,\npara salir a lo raso,\na ver quién laza primero.",139,2,2,138,"El caballito; Estrofa suelta",9,6,"eo",38,0,-1,0,132,132,"6492","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6493",7,"Yo vide medir el oro\ny en un cuarterón de plata.\nPor aquí les traigo el toro,\nporque traigo buena reata;\na ver si me le acomodo\ny antes que salga la vaca.",136,2,4,138,"El toro Requesón",9,6,"aa",-1,0,-1,0,132,132,"6493","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6494",7,"Andando yo de vaquero,\na un toro le erré un lazo;\nle dije a mi compañero:\n“Adelante, que me atraso;\nmientras yo le busco el toro,\nyo le pego otro reatazo.”",139,2,2,138,"El toro Requesón",9,6,"ao",43,0,-1,0,132,132,"6494","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6495",7,"Ya no quiero ser vaquero\nde ese pueblo de Matlapa;\nvoy a comprarle su cuero\npara brillo de mi reata,\npara entrarle al potrero,\nporque hay mucha garrapata.",139,2,2,138,"El toro Requesón",9,6,"aa",74,0,-1,0,133,133,"6495","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6496",7,"Corté la flor de escobilla\nya mero pa reventar;\ncompré mi cuajo y mi silla\ny mi reata de alazán,\npara irme a la lagunilla\na ver los patos nadar.",136,2,4,138,"Estrofa suelta",9,6,"a",-1,0,-1,0,133,133,"6496","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6497",7,"Áhi viene bramando el toro,\nviene bramando por el corral;\neste toro muy rejego\nno lo he podido nunca domar.",136,2,4,138,"El toro",3,4,"a",-1,0,-1,0,133,133,"6497","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6498",7,"¡Oh, qué toro tan puntal!,\n¡a toditos ha arrastrado!\nParece perro del mal,\nsegún nos ha revolcado.",135,2,-1,138,"Estrofa suelta",1,4,"ao",14,0,-1,0,133,133,"6498","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6499",7,"Áhi salimos de resolana\na torear al guayabal,\nporque me creo de fama;\npero si da lugar,\ncono y boto y busco mi manzana.",136,2,4,138,"El torito",7,5,"aa",-1,0,-1,0,133,133,"6499","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6500",7,"Campeando en el campo raso\ny también donde hay espinas,\ny cuando llego a hacer lazo\ny algún bote me ilumina,\nde la reata no hago caso,\ny el fuste es el que rechina.",136,2,4,138,"El toro Requesón",9,6,"ia",11,0,-1,0,133,133,"6500","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6501",7,"¡Ay!, si de lazar se trata,\nasí te digo no más:\nallá le tiré a una vac?,\nla lacé por la mitad;\nque me apise la reata,\nacá echo pólvora y gas.",136,2,4,138,"El Balajú",9,6,"a",-1,0,-1,0,133,133,"6501","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6502",7,"Cuando yo lazo un toruno,\n¡ay! que va por la mitad,\ny mi caballo terruño\nlo dejaste anear pa atrás,\nque primero coge el rumbo\ny de allí a casa de...",136,2,4,138,"El torito",9,6,"e",-1,0,-1,0,133,133,"6502","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6503",7,"Cuando yo lazo un toruno,\na orilla de una matilla,\ny si me lo espanta alguno,\ndejo chonear la reatilla;\npongo a sacar el humo\nde la cabeza y de la silla.",136,2,4,138,"La morena",9,6,"ia",162,0,-1,0,133,133,"6503","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6505",7,"Santiago, como buen charro,\nle dijo a San Miguelito:\n“Para montar a caballo\nni de espuelas necesito.”",140,2,12,138,"El caballito",0,4,"io",119,0,-1,0,134,134,"6505","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6506",7,"A todos los animales,\naunque mi vieja no quiera,\nhe de hacer que me obedezcan\ncomo la muía maicera.",135,2,-1,138,"Huapango de huapangos",0,4,"ea",-1,0,-1,0,134,134,"6506","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6508",7,"Me gusta amansar caballos,\nyeguas brutas y becerros,\ntambién toros y novillos\nde los que anden por los cerros.",135,2,-1,138,"Huapango de huapangos",0,4,"eo",333,0,-1,0,134,134,"6508","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6509",7,"Yo a los toros los amanso\nsin braguero y sin bozal,\npues yo mismo los alcanzo\ny los amanso con sal.",136,2,4,138,"El torito de Las Bajadas",1,4,"a",1,0,-1,0,134,134,"6509","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6510",7,"¿Quién quiere abrir la puerta\npara el potrero?\nYo ya le quité a este toro (negrita)\nlo mitotero:\nirá como corderito (negrita)\na su chiquero.",136,2,4,138,"El toro Relajo",9,6,"eo",38,0,-1,0,134,134,"6510","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6511",7,"Me toreé un toro cadeno\nen el toril de Chilapan,\ny dejo a Santiago mozo\nque no se le atore tanto.",135,2,-1,138,"Ahora pregunto, pregunto",5,4,"ao",-1,0,-1,0,134,134,"6511","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6512",7,"Me dieron para ensillar\nun caballito amarado,\nde la silla de Avelino\ny de tiena colorado.",136,2,4,138,"El torito",0,4,"ao",14,0,-1,0,134,134,"6512","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6513",7,"Voy a amansar al Coquito\ny también al Requesón,\ndespués al caballo prieto\ny al palomo de pilón,\npa que la chata malora\nno crea que soy corretón.",135,2,-1,138,"Huapango de huapangos",9,6,"o",31,0,-1,0,134,134,"6513","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6514",7,"Voy a comprar una reata\nde purita lechugilla,\na ver si puedo lazar\nde ese caballo la silla,\npara ver si me la dan.",138,2,6,138,"El caballito",7,5,"a",-1,0,-1,0,135,135,"6514","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6515",7,"Voy a echar una corrida\nrumbo para el otro lado,\na ver si puedo agarrar\nese caballo melado,\nque se salió del corral\njunto con el colorado.",139,2,2,138,"El caballito^",9,6,"ao",14,0,-1,0,135,135,"6515","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6516",7,"Voy a salir a campear\nal paso de la barranca,\na ver si puedo lazar\nun caballo carablanca,\nque se salió del corral\njunto con una potranca.",136,2,4,138,"El caballito",9,6,"aa",75,0,-1,0,135,135,"6516","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6517",7,"Voy a echar una mangana\na orillas de aquel potrero;\nsi este caballo me mata,\nme quitaré de vaquero.",140,2,12,138,"El caballito",0,4,"eo",38,0,-1,0,135,135,"6517","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6518",7,"Voy a rayar mi caballo\na orillas de un tecorral;\nsi este caballo me mata,\nme quito de caporal.",140,2,12,138,"El caballito",0,4,"a",1,0,-1,0,135,135,"6518","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6519",7,"Voy a comprar una reata\nde purita seda negra,\npa ver si puedo lazar\nel caballo de mi suegra;\nsi ese caballo me mata,\náhi les encargo a mi nena.",138,2,6,138,"El caballito",9,6,"ea",-1,0,-1,0,135,135,"6519","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6520",7,"Vamos a correr el toro\nal llano de San Miguel,\na ver si yo mato el toro;\nsi no, me quedo con él.",136,2,4,138,"El toro",1,4,"e",32,0,-1,0,135,135,"6520","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6521",7,"Échalos para el carril\npor donde vive don Chon;\nquiero que me vea la güera\ncolear aquí esta ternera,\npara que vea que mi acción\nle va a quitar lo matrera.",139,2,2,138,"El toro Requesón",9,6,"ea",44,0,-1,0,135,135,"6521","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6522",7,"¡Apa!, que ahí viene el toro:\nes el Relajo;\nescóndete tras la tranca (negrita),\nque viene bravo;\naviéntame tu rebozo (negrita),\npara torearlo.",136,2,4,138,"El toro Relajo",9,6,"ao",-1,0,-1,0,135,135,"6522","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6523",7,"Échenme ese toro bravo;\nhijo de la vaca pinta,\nque lo quiero capotear\ndelante de la tía Jacinta.",144,2,10,138,"El toro",3,4,"ia",155,0,-1,0,136,136,"6523","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6524",7,"Échenme ese toro pinto,\nhijo de la vaca mora,\nque lo quiero capotear\ndelante de esa señora.",143,2,18,138,"El toro; Estrofa suelta",0,4,"oa",107,0,-1,0,136,136,"6524","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6525",7,"¿Cuál será ese toro bravo\nque brama por las mañanas?\n¡Suéltemelo, caporal!,\nahora que vengo con ganas.",143,2,18,138,"El toro",0,4,"aa",263,0,-1,0,136,136,"6525","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6526",7,"La mula está ya muy quieta,\nle voy a poner el cincho;\nno eches tanta respingada\nhija de la nana Cota.",150,2,24,138,"La mulita",5,4,"oa",-1,0,-1,0,136,136,"6526","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6527",7,"En eso me sale un toro,\ny le estoy echando el pial;\n¡ah, qué toro refregado!,\n¡quién te pudiera poner\nel cabezal dorado! (¡ay, mamá,\nMañana voy al rodeo.",136,2,4,138,"ah, qué toro refregado!, ¡quién te pudiera poner el cabezal dorado! (¡ay, mamá, mamá!",9,6,"eo",-1,0,-1,0,136,136,"6527","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6528",7,"Toro, toro, toro,\ntoro Relajo!,\nse te está quitando (torito),\nlo alebrestado.",136,2,4,138,"El toro Relajo",3,4,"ao",-1,0,-1,0,136,136,"6528","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6529",7,"Torito de Las Bajadas,\nsé que me quieres comar;\nno me pongas esa cara,\nasí te vas a quedar.",136,2,4,138,"El torito de Las Bajadas",0,4,"a",21,0,-1,0,136,136,"6529","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6530a",7,"Toma, toma, toma,\ntorito de la barranca;\nsi quieres comer salitre,\nsolito brinca las trancas,",137,2,3,138,"El toro",0,4,"aa",-1,0,-1,0,136,136,"6530a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6531",7,"Toro pinto, toro negro,\ntoro de siete corrales,\nte voy a acercar un lance\ndelante de estos señores.",136,2,4,138,"Un día me fui a pasear’’",5,4,"oe",-1,0,-1,0,137,137,"6531","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6532",7,"¡Toro, toro, toro!,\nentra de largo,\nque mi prieta linda (torito)\nme está mirando.",136,2,4,138,"El toro Relajo",3,4,"ao",-1,0,-1,0,137,137,"6532","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6538",7,"Pepa no quiere coser,\nni quiere tejer en gancho:\nse quiere civilizar\ncon uno de sombrero ancho.",135,2,-1,139,"El sombrero ancho. Estrofa suelta",0,4,"ao",380,0,-1,0,140,140,"6538","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6539a",7,"Para ser gendarme\nse deben de tener\nlos bigotes largos\ncomo Lucifer.",148,2,9,139,"Estrofa suelta",0,4,"e",20,0,-1,0,140,140,"6539a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6540",7,"—Oiga, señor De la Torre,\n¿por qué a un soldado cualquiera\nle dicen que está en carrera?\n—¿Por qué ha de ser? Porque corre.",142,2,8,139,"Estrofa suelta",11,4,"oe",136,0,-1,0,140,140,"6540","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6542",7,"Desde las cumbres de Talpa (mamá),\nse divisa el mundo entero,\npero más bien se divisa (¡ay, mamá!)\nla lumbre del carbonero.",164,2,16,139,"El carbonero",3,4,"eo",38,0,-1,0,140,140,"6542","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6543",7,"Desde la sierra más alta (mamá)\nse divisa el carbonero;\napenas se le divisa (mamá)\nla copa de su sombrero.",144,2,10,139,"El carbonero",3,4,"eo",38,0,-1,0,141,141,"6543","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6544",7,"Desde las cumbres de Talpa\nse divisa un marinero,\npero más bien se divisa (mi alma, mi vida)\nla hija del carbonero.",135,2,-1,139,"El carbonero",3,4,"eo",38,0,-1,0,141,141,"6544","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6545a",7,"El carpintero fue a misa\ny no tenía que rezar,\ny a los santos les pedía\nmadera para serrar.",136,2,4,139,"El carpintero",0,4,"a",21,0,-1,0,141,141,"6545a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6545c",7,"Y un carpintero fue a misa\ny no tenía qué rezar,\ny se quitó la camisa\ny la puso en el altar,\ny a los santos les pedía\nmadera para aserrar.",136,2,4,139,"El pájaro carpintero",9,6,"a",21,0,-1,0,141,141,"6545c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6546",7,"Un zapatero fue a misa,\nno encontrando qué rezar;\nandaba por todas partes:\n“¡Zapatos que remendar!”",135,2,-1,139,"La cucaracha; Corrido de los destinos; La Sanmarqueña; Estrofa suelta",0,4,"a",21,0,-1,0,141,141,"6546","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6547",7,"Un panadero fue a misa,\nno encontrando qué rezar;\nle pidió a la Virgen pura\nmarihuana que fumar.",135,2,-1,139,"La cucaracha",0,4,"a",21,0,-1,0,141,141,"6547","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6548a",7,"Un pescador en la barra\nno pudo dar golpe en bola:\npor pescar una mojarra,\npesca un sapo de la cola.",136,2,4,139,"La Petenera",1,4,"oa",321,0,-1,0,141,141,"6548a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6549",7,"Ariles y más ariles,\nariles de aquel que vino\na darle agua a su caballo,\ny se murió en el camino.",136,2,4,139,"El Balajú",0,4,"io",199,0,-1,0,142,142,"6549","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6550",7,"Ariles y más ariles,\nariles de aquel que fue\na darle agua a su caballo,\ny se le murió de sed.",136,2,4,139,"El Balajú; La guacamaya",0,4,"e",-1,0,-1,0,142,142,"6550","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6551",7,"Ariles y más ariles,\nariles de aquel que iba\na darle agua a su caballo\ny no se apeaba de arriba.",136,2,4,139,"El Balajú",0,4,"ia",140,0,-1,0,142,142,"6551","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6552",7,"[Ay, Soledad, Soledad!,\nSoledad, pa que el que fue\na darle agua a mi caballo:\npor eso se quedó a pie.",135,2,-1,139,"La Petenera",0,4,"e",77,0,-1,0,142,142,"6552","",0,"","","",18,0,0,[],"",""],["frenk_t3-n6553",7,"Ariles y más ariles,\nariles de aquel que iba\na darle agua a su caballo,\ny se le murió en la subida.",136,2,4,139,"El Balajú",0,4,"ia",-1,0,-1,0,142,142,"6553","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6555",7,"Yo ya no quiero sembrar,\nni quiero vivir en rancho:\nme quiero civilizar\ny ponerme sombrero ancho.",137,2,3,139,"El sombrero ancho",1,4,"ao",380,0,-1,0,142,142,"6555","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6556",7,"Como soy ranchero\nde pocas palabras,\ncuento mentiritas,\npero no muy largas.",137,2,3,139,"Las dos Marías",0,4,"aa",-1,0,-1,0,143,143,"6556","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6557",7,"Sácale cañas al tercio,\nque la muía está parada;\nme gusta mucho el comercio,\naunque nunca venda nada.",137,2,3,139,"El listoncillo",1,4,"aa",49,0,-1,0,143,143,"6557","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6558",7,"El ganado se perdió\npor andar con la guitarria;\nyo no lo he de ir a busquiar:\nvale más me condenaría.",137,2,3,139,"Flor de changunga",5,4,"ia",-1,0,-1,0,143,143,"6558","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6559",7,"Ya no quiero, ya no quiero\ntorear el toro rabón;\nsi la víbora te pica,\nte queda la comezón.",146,2,7,139,"El toro rabón",0,4,"o",31,0,-1,0,143,143,"6559","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6560",7,"De toda mi caballada,\nsólo mi caballo potro\npara mover un pie\nle pide licencia al otro.",137,2,3,139,"La caballada",0,4,"oo",275,0,-1,0,143,143,"6560","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6561",7,"Tengo un caballo\nde muy buena andadura,\nque no le queda\nmás que una herradura.",148,2,9,139,"Estrofa suelta",3,4,"ua",17,0,-1,0,143,143,"6561","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6562",7,"El toro estaba en Sayula,\ny yo estaba en Salvatierra;\nle tendí la manga al toro\nen las ancas de mi yegua.",136,2,4,139,"El toro",0,4,"ea",-1,0,-1,0,143,143,"6562","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6563",7,"Carbonero soy, señores,\nque vengo desde la Veta;\nle mordí la jeta a un burro,\npensando que era mi prieta.",144,2,10,139,"El carbonero",0,4,"ea",200,0,-1,0,143,143,"6563","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6564",7,"Carbonero soy, señores,\nque vengo desde Fresnillo;\nle mordí la jeta a un burro,\npensando que era membrillo.",144,2,10,139,"El carbonero",0,4,"io",228,0,-1,0,143,143,"6564","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6565",7,"Yo me encontré en el camino\nun burrito y un caballo,\npero estaban tan pesados,\nque no los quise traer.",155,2,14,139,"Tarihuán, tarichuz",5,4,"e",-1,0,-1,0,143,143,"6565","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6566a",7,"Vengo de tierra caliente,\ncansado de jinetear;\nme monté en un burro muerto,\nque no me pudo tirar.",135,2,-1,139,"‘‘Vengo de tierra caliente",0,4,"a",21,0,-1,0,144,144,"6566a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6567",7,"Yo soy un pobre vaquero,\nque no tiene ni sombrero,\npero se lo van a hacer\nde pellejo de becerro.",135,2,-1,139,"‘‘El vaquerito",0,4,"eo",-1,0,-1,0,144,144,"6567","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6568",7,"Yo soy un pobre vaquero,\nque no tiene ni alpargatas,\npero me las voy a hacer\ncon pellejo ’e garrapata.",147,2,11,139,"‘‘El vaquerito",0,4,"aa",-1,0,-1,0,144,144,"6568","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6569",7,"Yo soy un pobre vaquero,\nque no tiene ni calzones,\npero se los van a hacer\nde pellejo de ratones.",135,2,-1,139,"El vaquerito",0,4,"oe",34,0,-1,0,144,144,"6569","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6570",7,"Yo soy un pobre vaquero,\nque no tiene ni camisa,\npero se la van a hacer\nde tripa de longaniza.",135,2,-1,139,"‘‘El vaquerito",0,4,"ia",420,0,-1,0,144,144,"6570","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6571",7,"Soy pobrecita María,\nmis asientos son de banca,\ny si me siento en un banco,\nparece que estoy en zanco.",142,2,8,139,"‘‘La guacamaya",5,4,"ao",303,0,-1,0,144,144,"6571","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6572",7,"En la punta de aquel cerro\nlazaron un marrano capón;\nluego que le aviento el lazo\nle aviento el mojón.",140,2,12,139,"Estrofa suelta",3,4,"o",31,0,-1,0,144,144,"6572","",0,"","","",21,0,0,[],"",""],["frenk_t3-n6573",7,"Yo ya no quiero mulita,\nse la dejo al que la quera;\nme voy a tirar a pie,\npa andar más a la carrera.",135,2,-1,139,"La mulita",0,4,"ea",44,0,-1,0,144,144,"6573","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6574",7,"Ahi les dejo esta mulita,\nque salió de buena cría;\npor bien o mal que le vaya\nse han de acordar algún día,",135,2,-1,139,"La mulita",0,4,"ia",0,0,-1,0,144,144,"6574","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6575",7,"Áhi les tengo esta mulita,\nque está de lo mero bueno;\nno más no le monte en pelo,\npóngale macizo el freno.",135,2,-1,139,"‘‘La mulita",0,4,"eo",-1,0,-1,0,145,145,"6575","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6576",7,"Áhi les dejo esta mulita,\nque salió de buena cría\ny que puede con tres cargas,\nporque ya tiró la mía.",135,2,-1,139,"‘‘La mulita",0,4,"ia",0,0,-1,0,145,145,"6576","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6579",7,"Brindo y vuelvo a brindar,\nsentado en este banquillo,\nque si no mato este toro,\nque me piquen el corazón.",135,2,-1,139,"Las bombas viejas; Estrofa suelta",5,4,"o",-1,0,-1,0,145,145,"6579","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6580",7,"Del palo salen los leños,\ny de los leños, los leñitos;\nde los salineros viejos\nsalen los salineritos.",142,2,8,139,"Estrofa suelta",0,4,"io",254,0,-1,0,146,146,"6580","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6581",7,"¡Pobrecito panadero,\nque le picó el alacrán!\n¿Sabes dónde le picó?\nFue llegando a Petatlán.",135,2,-1,139,"Estrofa suelta",0,4,"a",147,0,-1,0,146,146,"6581","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6582",7,"Si te aprieta el zapatito,\nmándaselo al zapatero,\nque le aumente un poco más,\no que te vuelva el dinero.",145,2,17,139,"No sabes, china del alma",0,4,"eo",38,0,-1,0,146,146,"6582","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6583a",7,"El cuervo con tanta pluma\nno se puede mantener,\nel escribano con una\nmantiene moza y mujer.",145,2,17,139,"El cuervo",0,4,"e",20,0,-1,0,146,146,"6583a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6584",7,"En el puerto de Tampico\nmataron a un guajolote\ny de adentro le sacaron\nun gendarme con garrote.",147,2,11,139,"El cateto",0,4,"oe",292,0,-1,0,146,146,"6584","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6585",7,"En el puerto de Tampico\nmataron a un perico\ny de adentro le sacaron\nun gendarme con un pito.",147,2,11,139,"El cateto",0,4,"io",-1,0,-1,0,146,146,"6585","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6586",7,"Los músicos e impresores\ny los artistas de teatro\ntraen linternas de dos luces,\npor si acaso hay carbonato.",135,2,-1,139,"Linternas y linternitas",0,4,"ao",-1,0,-1,0,146,146,"6586","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6587",7,"Mecánicos y pintores,\nvarilleros, relojeros,\nno les gusta usar linterna:\nmejor su vela de sebo.",135,2,-1,139,"Linternas y linternitas",0,4,"eo",-1,0,-1,0,146,146,"6587","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6588",7,"Un pescador, que a los cielos\nse quejaba solamente,\ny les dice a sus anzuelos:\n“No me jalen de los dientes,\ncuando la rana críe pelos\ny el sapo sea presidente”.",135,2,-1,139,"Estrofa suelta",9,6,"ee",-1,0,-1,0,146,146,"6588","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6589",7,"Un pescador, que a los cielos\nse quejaba sólo a él,\ny les dice a sus anzuelos:\n“No me jalen del cordel,\ncuando la rana críe pelos\ny el sapo sea coronel”.",135,2,-1,139,"Estrofa suelta",9,6,"e",32,0,-1,0,147,147,"6589","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6590",7,"Un pescador a los cielos\nse quejaba a su fortuna,\ny les dijo a sus anzuelos:\n“No pesquen en mi laguna,\ncuando la rana críe pelos\ny el sapo en la cola, plumas”.",135,2,-1,139,"Estrofa suelta",9,6,"ua",-1,0,-1,0,147,147,"6590","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6591",7,"Un pescador, que a los cielos\nse vivía tocando tretas,\ny les dice a sus anzuelos:\n“No me enganchen de la jeta,\ncuando la rana críe pelos\ny el sapo tenga chaquetas”.",135,2,-1,139,"Estrofa suelta",9,6,"ea",-1,0,-1,0,147,147,"6591","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6592",7,"Un pescador, que a los cielos\nse quejaba en sus portones,\ny les dice a sus anzuelos:\n“No me enganchen los cojones,\ncuando la rana críe pelos\ny el sapo tenga calzones”.",135,2,-1,139,"Estrofa suelta",9,6,"oe",34,0,-1,0,147,147,"6592","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6593",7,"¡Pobrecita de la indita,\nque viene desde La Habana,\namasando el requesón\ny exprimiendo la cuajada!",142,2,8,139,"La indita",0,4,"aa",-1,0,-1,0,147,147,"6593","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6594",7,"Mordió un gato a un escribano,\ny él clamó con sentimiento:\n“¡Ten, gatito, miramiento,\nadvierte que soy tu hermano!”",135,2,-1,139,"Estrofa suelta",11,4,"ao",81,0,-1,0,148,148,"6594","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6595",7,"Dicen los malditos tecos\nque también son barreteros:\nUegando a Sierra Mojada\nson puritos limosneros.",144,2,10,139,"Dicen los malditos tecos",0,4,"eo",22,0,-1,0,148,148,"6595","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6596",7,"Las rancheritas que van a misa\nbajan la vista pa no mirar;\nsalen de misa, van a la plaza,\nson como un diablo pa murmurar.",144,2,10,139,"Paloma blanca",3,4,"a",21,0,-1,0,148,148,"6596","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6597",7,"Todo el pueblo de Matlapa\npide chamba de vaquero;\nno más aganan su reata\ny se van para el potrero\na levantar garrapatas,\nporque no hay uno vaquero.",138,2,6,139,"El toro Requesón",9,6,"eo",38,0,-1,0,148,148,"6597","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6598",7,"Yo conozco caporales\nque se la dan de gallones,\nque cuando ven un toro bravo\nse les caen los pantalones.",136,2,4,139,"El toro",0,4,"oe",34,0,-1,0,148,148,"6598","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6599",7,"Los merolicos y el circo\nya no conocen los reales:\npara que los siga la gente\nreciben hasta tamales.",135,2,-1,139,"La cucaracha",0,4,"ae",26,0,-1,0,148,148,"6599","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6600",7,"Herreros y hojalateros,\ny morrongos garbanceros\ntraen linternas muy mugrosas\ny son muy rete embusteros.",135,2,-1,139,"Linternas y linternitas",0,4,"eo",22,0,-1,0,148,148,"6600","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6601",7,"En todas las pulquerías\ntraen linternas de pulqueros;\ncomo son muy mujereros,\nhasta los dejan en cueros.",135,2,-1,139,"Linternas y linternitas",0,4,"eo",22,0,-1,0,148,148,"6601","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6602",7,"Empleados y diputados,\nmilitares y toreros,\nésos traen de a dos linternas,\npara así cobrar dos sueldos.",135,2,-1,139,"Linternas y linternitas",0,4,"eo",-1,0,-1,0,149,149,"6602","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6603",7,"De los choferes ¿qué dicen?\nÉsos no escogen linternas:\ncomo son muy topilleros,\nno les resulta una buena.",135,2,-1,139,"Linternas y linternitas",0,4,"ea",-1,0,-1,0,149,149,"6603","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6604",7,"Toditos los motoristas,\nlo mismo que camioneros,\nusan sus linternas negras:\nson buenas para los entierros.",135,2,-1,139,"Linternas y linternitas",0,4,"eo",-1,0,-1,0,149,149,"6604","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6605",7,"Vaquerito, vaqueró,\nbajo el agua y bajo el sol,\ncintura de cuerda prima\ny pecho de guitarrón.",135,2,-1,139,"El vaquerito",0,4,"o",-1,0,-1,0,149,149,"6605","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6606",7,"Si nació la potranquita\nen las tierras del Bajío,\nque no tiene ni remedio:\nsalió al burro [de] tu tío.",135,2,-1,139,"La potranca",0,4,"io",3,0,-1,0,149,149,"6606","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6607",7,"No más póngale cuidado,\nmírela, señor compadre:\nes toditito el retrato\ndel caballo de su padre.",135,2,-1,139,"La potranca",0,4,"ae",166,0,-1,0,149,149,"6607","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6608",7,"¡Ay, qué potranca tan chula!,\nmírela, señor compadre:\ncuatro patas blancas tiene,\nsalió todita a su madre.",135,2,-1,139,"La potranca",0,4,"ae",166,0,-1,0,149,149,"6608","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6609",7,"Nana Tula, Nana Pancha\ny también Nana Manuela\n¡ay, qué chula potranquita!,\n¡salió todita a su abuela!",135,2,-1,139,"La potranca",0,4,"ea",167,0,-1,0,149,149,"6609","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6610",7,"La vaca de mi comadre\nde pura muina se acalambró;\nel hijo de tu compadre\nla novillona le jineteó.",136,2,4,139,"El toro",3,4,"o",2,0,-1,0,149,149,"6610","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6611",7,"¡Ay, qué demonio de toro!,\nya se salió del corral;\ny las hijas de Teodoro,\nque les gusta jinetear,\ncon este torito moro\n¡qué gusto se van a dar!",146,2,7,139,"El toro",9,6,"a",21,0,-1,0,149,149,"6611","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6612",7,"Ya la güera está pelona:\n¡qué remona!, y se ve bien;\nno le hace que esté pelona,\npero que cabreste bien;\nparece una novillona\ny matrera pa correr.",138,2,6,139,"El toro Requesón",9,6,"e",-1,0,-1,0,150,150,"6612","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6613",7,"Échenme ese toro pinto,\nhijo de la vaca mora,\npara que cueme al patrón\ncuando se ponga malora.",135,2,-1,139,"El toro",0,4,"oa",107,0,-1,0,150,150,"6613","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6614",7,"Me subí a un devisadero\na devisar mi manada:\ndivisé una polvareda\ny el chivo que la llevaba.",148,2,9,139,"El tarachi",0,4,"aa",-1,0,-1,0,150,150,"6614","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6615",7,"Yo quisiera andar arando,\npero me hace falta un buey;\nresponden las del maguey:\n“Por aquí pasó pitando\nese maldecido buey,\ncon la coyunda arrastrando”.",135,2,-1,139,"Estrofa suelta",9,6,"ao",33,0,-1,0,150,150,"6615","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6616",7,"Calla la trompa, borrico,\ndeja de estar rebuznando:\nla silla te tengo puesta\ny el freno te ando buscando.",142,2,8,139,"Estrofa suelta",0,4,"ao",33,0,-1,0,150,150,"6616","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6617",7,"Aquí está ya el matraquero,\nmás picudo que una estaca,\nresuelto, cual papelero,\na tronarles la matraca.",135,2,-1,139,"Estrofa suelta",1,4,"aa",457,0,-1,0,150,150,"6617","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6618",7,"La vista se puso a herir\ny el sentido a complacer;\ny si llego a discutir\nque para no padecer,\nsi de ver nació el sentir,\npara no sentir no veo.",135,2,-1,140,"Ya el águila real voló",9,6,"eo",-1,0,-1,0,154,154,"6618","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6619",7,"Desconfiado y malicioso\npor donde quiera que esté,\npues aunque soy muy goloso,\nno vuelvo a poner un pie\nsi miro algún sospechoso.",139,2,2,140,"El gavilán",7,5,"oo",160,0,-1,0,154,154,"6619","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6620",7,"Dice un dicho muy certero,\nque por verdadero enfada,\nque en casa del jabonero\nel que no cae resbala,\ny no seré yo el primero\nde darme una resbalada.",142,2,8,140,"Estrofa suelta",9,6,"aa",-1,0,-1,0,154,154,"6620","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6621",7,"Uno viste al mono\npa que otro lo baile,\npor eso es que yo\nno me creo de naiden.",135,2,-1,140,"Los bueyes",0,4,"ae",-1,0,-1,0,154,154,"6621","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6622",7,"Yo soy como las tortugas,\nque traen su concha de acero:\nal tiempo le doy su tiempo,\nsi rueda el mundo, no más lo veo.",135,2,-1,140,"Qué padre es la vida",3,4,"eo",-1,0,-1,0,154,154,"6622","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6623",7,"Ser quisiera una paloma\npara pegar un volido;\ncomo no he tenido forma\ny me encuentro desvalido,\ncapulín, presta tu sombra\npara quedarme dormido.",135,2,-1,140,"El pájaro carpintero",9,6,"io",101,0,-1,0,154,154,"6623","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6624",7,"A mí no me quema, mamá,\na mí no me quema, papá,\na mí no me quema nada,\nni la candela, ni ’l aguarrás,\nni la candela que está apagada.",136,2,4,140,"La candela",7,5,"aa",49,0,-1,0,154,154,"6624","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6625",7,"Y si mañana o pasado\na alguien le parece mal,\npues a mí nada me importa,\npara mí todo es igual.",137,2,3,140,"Estrofa suelta, La chinita",0,4,"a",1,0,-1,0,155,155,"6625","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6626",7,"Tomen nota desde Adán\nhasta el último nacido:\nque yo nunca le he temido\nal temido “qué dirán”.",135,2,-1,140,"Estrofa suelta",11,4,"a",147,0,-1,0,155,155,"6626","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6627",7,"Por la calle del Vergel\nrodando mi suerte viene;\na mí me tienen por mala:\n¿qué he de hacer, si me conviene?;\npero más mala es aquella\nque a mí por mala me tiene.",142,2,8,140,"Estrofa suelta",9,6,"ee",70,0,-1,0,155,155,"6627","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6628",7,"Hora sí, mañana no,\nporque el gusto se acabó:\n¡qué se acabe en hora buena,\ncomo no me acabe yo!",163,2,21,140,"El carnaval; Estrofa suelta",0,4,"o",2,0,-1,0,155,155,"6628","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6629",7,"El mundo se va a acabar:\nel mundo ¿a mí qué me importa?\nSe acaba pa el que se muere,\ny a mí todavía no me toca.",135,2,-1,140,"El mundo es mío",3,4,"oa",-1,0,-1,0,155,155,"6629","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6630",7,"El amor nació un día,\nla pasión creció de noche;\nsi antes me paseé en tranvía,\nahora me paseo en coche.",135,2,-1,140,"Chiquita pero picosa",1,4,"oe",337,0,-1,0,155,155,"6630","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6631",7,"En Guanajuato le puse\ntres tiros a mi pistola;\nya tengo mis chaparreras\ny hora sí me voy de veras,\nahora sí que no me quedo\ncomo el que chifló en la loma.",135,2,-1,140,"El pájaro carpintero; Las barrancas",9,6,"oa",-1,0,-1,0,155,155,"6631","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6632",7,"Desnudo sin cueros vengo\npor mandato de Salomón;\nal fin que mi Dios no es viejo,\naunque lo pinten barbón.",142,2,8,140,"Estrofa suelta",0,4,"o",31,0,-1,0,155,155,"6632","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6633",7,"Sabes quién soy,\nyo soy así:\nsale el sol, y luego\nme acuesto a dormir.",145,2,17,140,"El agobiado",6,4,"i",-1,0,-1,0,155,155,"6633","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6634",7,"En el arroyo en la fuente\nme sacaron a recreo;\neso lo tengo presente,\nporque mis padres en vida,\ncomo criatura inocente,\nme han sacado muy seguido\na asociarme con la gente.",142,2,8,140,"El siquisirí",4,7,"ee",15,0,-1,0,156,156,"6634","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6635a",7,"Yo vine pa disiparme,\ny fue inútil mi deseo,\nporque a mí me gusta estar\ndonde se escucha el trineo.",142,2,8,140,"Zapateado",0,4,"eo",66,0,-1,0,156,156,"6635a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6636",7,"En el mar hay una mesa,\ny una garza morena\nse zambulle y saca arena.\nDios me ha de conceder\nque he de comer\ncaldito con yerbabuena.",136,2,4,140,"El ramo’T",9,6,"ea",59,0,-1,0,156,156,"6636","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6637",7,"Al quihúbole, quihúbole, quihúbole,\neso me gusta a mí:\nla rama de mejorana\ny el papel de pacholí.",145,2,17,140,"El quihúbole",3,4,"i",23,0,-1,0,156,156,"6637","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6638",7,"Redondas son las monedas,\npara que rueden ligero,\nlos billetes son papeles,\npara que emprendan el vuelo;\nla plata es para gozarla,\ny yo por gozarla muero.",135,2,-1,140,"Con el oro se compra de todo",9,6,"eo",-1,0,-1,0,156,156,"6638","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6639",7,"El oro se hace semilla,\nla semilla semillero:\nsácale semilla al oro,\nque semilla es lo que quiero.",135,2,-1,140,"El toro",0,4,"eo",38,0,-1,0,156,156,"6639","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6640",7,"Traigo gusto en demasía,\nque hasta yo mismo pregunto;\ny si me falla algún día,\nque yo llegue a ser difunto,\nsigo alegre todavía.",141,2,1,140,"El gusto",7,5,"ia",0,0,-1,0,156,156,"6640","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6641",7,"Yo quiero vivir mi vida,\nsiquiera mientras me dura,\namando y siempre cantando,\naun en medio de la amargura",135,2,-1,140,"Qué padre es la vida",0,4,"ua",17,0,-1,0,156,156,"6641","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6642",7,"Unos quieren saber mi nombre\ny también mi apelativo:\nLola Rodríguez me llamo\ny en este zacatal vivo.",142,2,8,140,"Zapateado",0,4,"io",351,0,-1,0,157,157,"6642","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6643a",7,"En la pila del bautismo,\ndonde yo me bauticé,\npor gusto de mis padrinos\nyo Pascual yo me llamé,\ny Campos mi apelativo.",138,2,6,140,"La azucena",7,5,"io",-1,0,-1,0,157,157,"6643a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6644",7,"Grande tengo la advertencia,\nles puedo yo asegurar;\náhi si me da la experiencia,\nles voy a garantizar\nlos dos hermanos Valencia,\npa lo que gusten mandar.",136,2,4,140,"La guacamaya",9,6,"a",21,0,-1,0,157,157,"6644","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6645",7,"Aficionado soy yo,\nsiempre me echo un gran pendiente;\npues míreme cómo soy:\ny me gusta el aguardiente,\ny amigos de La Misión,\naquí me tienen presente.",139,2,2,140,"La azucena",9,6,"ee",15,0,-1,0,157,157,"6645","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6646",7,"Ya con ésta me despido\ny le bebo a la botella;\ny yo soy Salvador Bemal,\nen mi tierra y en la ajena.",135,2,-1,140,"La india; La cucaracha; La víbora",0,4,"ea",-1,0,-1,0,157,157,"6646","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6647",7,"Si acaso no me conoces,\nyo me daré a conocer:\nfulano de tal me llamo,\nmarido de mi mujer.",136,2,4,140,"Estrofa suelta",0,4,"e",20,0,-1,0,157,157,"6647","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6648",7,"Soy una pobre mujer,\nbuena moza y bien vestida;\npregunto quién pueda ser,\nsi hubiera quien me lo diga.",138,2,6,140,"Estrofa suelta",0,4,"ia",-1,0,-1,0,157,157,"6648","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6649",7,"Quisiera ser avestruz,\npa pararme en una pata;\nsoy nacido en Veracruz\ny bautizado en Jalapa;\nhora vivo en Santa Cruz,\na orillas del Papaloapan.",136,2,4,140,"El siquisirí",9,6,"aa",-1,0,-1,0,157,157,"6649","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6650",7,"Me dices que soy guanajua\nporque traigo cobertor;\nno soy guanajua ni nada,\nsoy del purito interior.",135,2,-1,140,"‘‘Bonito San Juan del Río",0,4,"o",72,0,-1,0,158,158,"6650","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6651",7,"Me dicen que soy guanajua\nporque traigo mi patío:\nno soy guanajua ni nada;\nsoy puro San Juan del Río.",135,2,-1,140,"‘‘Bonito San Juan del Río",0,4,"io",3,0,-1,0,158,158,"6651","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6652",7,"Ya con ésta me despido,\nya me voy para el Bajío;\nya les dije a los panteras:\nsoy puro San Juan del Río.",135,2,-1,140,"‘‘El valiente de San Juan del Río",0,4,"io",3,0,-1,0,158,158,"6652","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6653",7,"Ya con ésta me despido:\nadiós les digo, paisanos;\nsoy de puro Tamaulipas,\nvecino de los tejanos.",135,2,-1,140,"El alegre tampiqueño",0,4,"ao",318,0,-1,0,158,158,"6653","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6654",7,"Soy abajeño cabal,\nmi semblante lo dirá,\ny en la palma de la mano\ntraigo la formalidad.",140,2,12,140,"Estrofa suelta",0,4,"a",-1,0,-1,0,158,158,"6654","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6655",7,"Oí cantar a un jilguero\nen las cumbres de un maizal;\npero soy hombre cabal;\nllegó uno de los primeros\nvecinos del jonotal.",142,2,8,140,"‘‘El siquisirí",7,5,"a",1,0,-1,0,158,158,"6655","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6656",7,"Yo soy de muy buena ley\nhumilde y muy pobrecito,\nno presumo de carey,\nvivo en humilde ranchita;\ncuando vayas a Maguey\npuedes contar con Juanito.",142,2,8,140,"El siquisirí",9,6,"io",119,0,-1,0,158,158,"6656","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6657",7,"Me dicen el presumido,\npero a nadie le presumo:\ncon mi cigarro encendido,\npero a nadien le echo el humo,\nporque no soy atrevido.",139,2,2,140,"La presumida",7,5,"io",101,0,-1,0,158,158,"6657","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6658",7,"Yo no presumo de ser valiente,\ntampoco digan soy hablador;\nsoy de esa tierra que nunca miente\ny soy jarocho de corazón.",147,2,11,140,"El jarocho",3,4,"o",-1,0,-1,0,158,158,"6658","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6659",7,"Yo no me doy en las veras,\nporque no soy calabaza:\nyo me doy en tierra buena\ncomo la ciruela pasa.",140,2,12,140,"Estrofa suelta",0,4,"aa",123,0,-1,0,158,158,"6659","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6660a",7,"Ya llegó la cal en piedra,\ny aquí me tienen ahora;\nno crean que soy un cualquiera,\nni tampoco soy malora,\npero mi bolsa no llora.",135,2,-1,140,"El albañil",7,5,"oa",107,0,-1,0,159,159,"6660a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6660b",7,"Ya llegó la cal con piedra,\naquí me tienen ahora;\nno me creas como una cualquiera,\nni tampoco de un malora;\ndirán que soy primavera,\npero mi bolsa no llora.",135,2,-1,140,"El albañil",9,6,"oa",107,0,-1,0,159,159,"6660b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6661",7,"Soy un pobre pasajero\nque visita esta región,\npero no soy bandolero\ncomo dice la opinión.",135,2,-1,140,"El gavilán",1,4,"o",31,0,-1,0,159,159,"6661","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6662",7,"Y si no quieren que enseñe yo el cobre,\nnada más les aviso que no;\nel que canta tal vez es muy pobre,\npero nunca a su amada vendió.",135,2,-1,140,"Los capulines",3,4,"o",2,0,-1,0,159,159,"6662","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6663",7,"Yo soy el hombre obediente\npara querer a Guatenango;\npara ir a mi tierra ausente\nnecesito bajar a Tenango;\npero yo soy buena gente,\nasí me la voy pasando.",136,2,4,140,"El siquisirí",9,6,"ao",-1,0,-1,0,159,159,"6663","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6664",7,"Soy un hombre que, impaciente,\nla suerte me trae volteando;\nde mi tiena vivo ausente,\ndistintas caras mirando,\npero siempre buena gente,\nasí me la voy pasando.",135,2,-1,140,"Ya el águila real voló",9,6,"ao",33,0,-1,0,159,159,"6664","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6665",7,"Yo soy Antonio Ramírez,\nmi destino es labrador,\nsoy amigo de los hombres,\nsoy amigo, no soy traidor.",135,2,-1,140,"La viuda",0,4,"o",72,0,-1,0,159,159,"6665","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6666",7,"Que soy león de montaña,\nque al caminar no hago ruido;\ncuando llego a parte extraña\nno me hago desconocido,\nporque no tengo esa maña\nde hacer menos mis amigos.",136,2,4,140,"El siquisirí",9,6,"io",-1,0,-1,0,159,159,"6666","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6667",7,"Y por eso vengo aquí,\ncantando con mi canción;\nyo soy el aventurero,\npuritito corazón.",135,2,-1,140,"El aventurero",0,4,"o",31,0,-1,0,159,159,"6667","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6668",7,"Yo soy el aventurero,\nel mundo me importa poco,\nsoy honrado y buen amigo,\nvacilador, mas sincero.",135,2,-1,140,"El aventurero",5,4,"eo",38,0,-1,0,159,159,"6668","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6669",7,"Aquí está el Águila Negra,\npa lo que ustedes gusten mandar;\namigo soy de los hombres,\ny de las hembras, pos ya ni hablar.",137,2,3,140,"‘El Águila Negra’T",3,4,"a",21,0,-1,0,160,160,"6669","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6670",7,"Soy amigo de la unión,\ny no soy interesable,\npero sí soy invariable,\ncuando no hay estimación.",142,2,8,140,"Estrofa suelta",11,4,"o",31,0,-1,0,160,160,"6670","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6671",7,"Tengo una flor en la mano\npara un amigo sincero,\nque la cultivo tanto\nen mayo como en enero.",139,2,2,140,"Estrofa suelta",0,4,"eo",38,0,-1,0,160,160,"6671","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6672",7,"Tengo pa mis amigos-\nun gran aprecio,\ny pa mis enemigos\nsólo desprecio.",135,2,-1,140,"El tamaulipeco",6,4,"eo",276,0,-1,0,160,160,"6672","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6673",7,"Soy de las peñas más altas,\ndonde habitan los venados;\nsoy amigo de los hombres\ny azote de los malcriados.",142,2,8,140,"El valiente; Estrofa suelta",0,4,"ao",18,0,-1,0,160,160,"6673","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6674",7,"Y aunque me vean de parranda,\nnunca soy hombre rajado;\nsoy amigo de los hombres\ny azote de los malcriados.",135,2,-1,140,"El valiente de San Juan del Río",3,4,"ao",-1,0,-1,0,160,160,"6674","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6675",7,"Yo soy la víbora negra,\nque.habito en los paredones;\nsoy amiga de los machos,\npero no de los ca...",135,2,-1,140,"La carretera",5,4,"a",-1,0,-1,0,160,160,"6675","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6676",7,"En la punta de aquel cerro,\ndonde habitan cuatro leones;\nsoy amigo de los hombres,\npero no de los collones.",137,2,3,140,"Verdad de Dios",0,4,"oe",-1,0,-1,0,160,160,"6676","",0,"","","",21,0,0,[],"",""],["frenk_t3-n6677",7,"¡Ay, corazón, corazón!,\ntú y yo somos algo grande:\nel mundo es mío no más,\ny no hay peno que me ladre.",135,2,-1,140,"El mundo es mío",0,4,"ae",-1,0,-1,0,160,160,"6677","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6678",7,"¡Ay!, arriba y aniba,\ny arriba irán;\nyo no soy marinero,\nsoy capitán.",136,2,4,140,"La bamba",6,4,"a",147,0,-1,0,161,161,"6678","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6679",7,"Mi padre nació de lima\ny mi madre de limón,\ny yo de naranja dulce;\n¡ay, Jesús, qué admiración!",142,2,8,140,"Estrofa suelta",0,4,"o",31,0,-1,0,161,161,"6679","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6681",7,"Soy de puro Tamaulipas\ny no lo ando presumiendo;\nyo soy de los meros jaibos\ny nunca lo ando diciendo.",135,2,-1,140,"El alegre tampiqueño",0,4,"eo",52,0,-1,0,161,161,"6681","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6682",7,"¡Qué bonito corre el agua\nen el hueco de un carrizo!\nYo soy de puro Huazolo,\nhasta la tierra que piso.",142,2,8,140,"Estrofa suelta",0,4,"io",92,0,-1,0,161,161,"6682","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6683",7,"Soy puro San Juan del Río,\ndonde nunca los engañan,\ny el que se junta conmigo\nni su mujer lo regaña.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"aa",-1,0,-1,0,161,161,"6683","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6684",7,"Soy de puro Chilpancingo,\ndonde nacen los malcriados;\nno rezo ni me persigno\ny nunca me voy de lado.",146,2,7,140,"Estrofa suelta",0,4,"ao",-1,0,-1,0,161,161,"6684","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6685",7,"Esta mula no es de aquí:\nla traje de Nuevo León;\nla montan los que son hombres,\nno la monta algún collón.",135,2,-1,140,"La mulita",0,4,"o",31,0,-1,0,161,161,"6685","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6686",7,"¡Ay, Juanita, ay, mamá de mi vida!,\nJuanita del otro lado;\ndondequiera doy un brinco\ny siempre caigo parado.",142,2,8,140,"La Juanita",3,4,"ao",14,0,-1,0,161,161,"6686","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6687",7,"Si porque toco charazca,\ndicen que estoy empautado,\nes mentira de la gente;\nes gracia que Dios me ha dado.",142,2,8,140,"Estrofa suelta",0,4,"ao",14,0,-1,0,161,161,"6687","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6688",7,"Soy doctor y no lo niego,\nsalí del palacio ayer,\ny hasta las muchachas dicen:\n“Vaya, vaya, vaya pues”.",135,2,-1,140,"La tos",0,4,"e",-1,0,-1,0,162,162,"6688","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6689",7,"Por un amor no suspiro\nni el color pierdo en la cara;\nyo soy como el gallo giro,\nque canta donde se para;\nel dinero que yo tiro\nlo gano con mi cuchara.",135,2,-1,140,"El albañil",9,6,"aa",57,0,-1,0,162,162,"6689","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6690",7,"Me voy para Catemaco\nel día primero de mayo;\ntengo la suerte del gato\ny la agilidad del gallo;\nsoy de a pie, monto a caballo\ncuando a las mujeres trato.",142,2,8,140,"La morena",9,6,"ao",-1,0,-1,0,162,162,"6690","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6691",7,"Viniendo de Tlacotalpan,\nno me gusta presumir:\naunque a mí me sobra plata,\nni crean que soy catrín;\nbonita se oye el arpa\ncuando la toca Tachín.",136,2,4,140,"El siquisirí",9,6,"i",211,0,-1,0,162,162,"6691","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6693",7,"No te creas que soy tan probe,\npues que tengo un camotal,\nsí mi cañaveral,\ny también paila de cobre.",135,2,-1,140,"La caña brava",5,4,"oe",-1,0,-1,0,162,162,"6693","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6694",7,"Si es cierto que gasto un peso\ny que ando muy alhajada,\na nadie le importa nada;\nserá mi gusto y por eso.",135,2,-1,140,"Estrofa suelta",11,4,"eo",48,0,-1,0,162,162,"6694","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6695a",7,"Soy soldado de guerrilla\ny también distingo el paso;\nno soy reata de cuartilla;\nsoy reata de lechuguilla.",147,2,11,140,"Estrofa suelta",5,4,"ia",162,0,-1,0,162,162,"6695a","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6696",7,"Soy el negro de la costa\nde Guerrero y de Oaxaca;\nno me enseñan a matar,\nporque sé cómo se mata;\nen el agua sé lazar\nsin que se moje la reata.",135,2,-1,140,"Costeña; La sureña; Estrofa",9,6,"aa",74,0,-1,0,163,163,"6696","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6697",7,"Cordeles de mi fortuna,\nreviéntense, calabrotes;\nyo no manejo la pluma,\npero hago también palotes;\nsoy pato de la laguna,\nde los meros picotones.",135,2,-1,140,"Estrofa suelta",9,6,"oe",-1,0,-1,0,163,163,"6697","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6698",7,"Como soy criado en los ranchos,\nyo por eso no me apeno:\ndonde quiera lavo y plancho\ny también costuro ajeno,\ny es porque mecate tiendo.",136,2,4,140,"El siquisirí",7,5,"eo",-1,0,-1,0,163,163,"6698","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6699",7,"Yo soy como el elotito,\nque a los tres días tengo cuates;\nasí como soy altito,\nme gusta entrar al combate,\nporque yo no necesito,\npara rodar, tecomate.",136,2,4,140,"El siquisirí",9,6,"ae",384,0,-1,0,163,163,"6699","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6700",7,"Yo soy como el oro fino,\nque en la feria pego fuerte;\nasí como soy altito\nme gusta alzar el copete,\nporque yo no necesito\npara nadar.........................",136,2,4,140,"El siquisirí",9,6,"a",-1,0,-1,0,163,163,"6700","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6701",7,"¡Viva, viva Zacatecas,\ntambién México y España!\nQue para usar mi camisa\nno necesito bretaña;\ntambién de manta las uso,\ny este cuero no lo extraña.",144,2,10,140,"Los gorgoritos",9,6,"aa",213,0,-1,0,163,163,"6701","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6702",7,"Corté la flor de cruceta\ny también la de rosario.\nYo cumplo lo que prometo,\nporque soy como el horario,\nque aunque mi color sea prieto,\nmi cuerpo no es ordinario.",142,2,8,140,"Zapateado",9,6,"ao",25,0,-1,0,163,163,"6702","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6703",7,"Soy el palo guayacán,\nde corazón amarillo;\ncomo soy hijo de Adán,\npor eso no me apolillo:\nyo soy más bueno que el pan,\nmás sabroso que un bolillo.",138,2,6,140,"La huazanga",9,6,"io",228,0,-1,0,163,163,"6703","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6704",7,"Cuando un árbol tumba la hoja,\nalgo tiene que sentir;\nyo por eso no me alojo\nen cualquier sombra a dormir.",142,2,8,140,"Estrofa suelta",0,4,"i",157,0,-1,0,164,164,"6704","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6705",7,"Se secó la yerbabuena\na pesar de mis cuidados;\na mí me van a tratar\ncomo se trata al pescado:\nque se coge con trabajos\ny se come con cuidado.",142,2,8,140,"La yerbabuena",9,6,"ao",-1,0,-1,0,164,164,"6705","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6706a",7,"Soy de puro Guanajuato,\ndonde se rebana el oro;\nyo me baño en agua limpia:\nno me revuelco en el lodo.",135,2,-1,140,"Estrofa suelta, Bonito San Juan del Río; El valiente",0,4,"oo",-1,0,-1,0,164,164,"6706a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6707",7,"Para el día que yo me muera\nla tierra se ha de lucir:\ncalandrias y primaveras\nde luto se han de vestir,\ny la mujer que me quiera\ntambién me debe sentir.",136,2,4,140,"María Chuchena; La huazanga; Mi permiso me han de dar; El siquisirí",9,6,"i",157,0,-1,0,164,164,"6707","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6708",7,"Soy extremosa en querer,\nsoy muy sensible en sentir,\nsola yo he de merecer,\nsola yo he de preferir.",135,2,-1,140,"Estrofa suelta",1,4,"i",157,0,-1,0,164,164,"6708","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6713",7,"Un cuervo en una ladera\nlloraba su soledad;\nno pago porque me quieran\nni ruego con mi amistad.",135,2,-1,140,"El cuervo",0,4,"a",16,0,-1,0,165,165,"6713","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6714",7,"No soy monedita de oro\npa caerles bien a todos:\nasí nací y así soy,\nsi no me quieren ni modo.",135,2,-1,140,"No soy monedita de oro",0,4,"oo",-1,0,-1,0,165,165,"6714","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6715",7,"Árboles de las barrancas,\n¿por qué no han [reverdecido]?\nSi les hace falta el agua,\n¿por qué no me la han pedido?",145,2,17,140,"El terrequeteque",0,4,"io",101,0,-1,0,165,165,"6715","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6716",7,"Dice Alejandro Durazo:\n“Soy gallo de buena raza,\nsoy linterna de la calle\ny oscuridad de mi casa”.",148,2,9,140,"Estrofa suelta",0,4,"aa",123,0,-1,0,165,165,"6716","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6717",7,"¡Ay! vuela, revuela y vuela,\nvuela, vuela, para la playa;\nyo soy la sombrita prieta\nde los campos de Celaya.",142,2,8,140,"La guacamaya",0,4,"aa",404,0,-1,0,165,165,"6717","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6718",7,"Soy relámpago sin trueno,\nque alumbra por el potrero;\ntodos dicen que soy bueno,\npero soy el hombre más malo\nque el mundo alojó en su seno.",139,2,2,140,"Estrofa suelta",7,5,"eo",76,0,-1,0,165,165,"6718","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6719",7,"Por andar en los fandangos,\nme pusieron fandanguero;\nporque soy afortunado,\nnunca nadie me ha ganado\nen amores y en el juego.",135,2,-1,140,"El fandanguero",7,5,"eo",-1,0,-1,0,165,165,"6719","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6720",7,"Tengo un caballo retinto,\ntengo un caballo torero;\ntraigo pistola en el cinto\ny mi chamarra de cuero:\nyo soy el mero vaquero\naquí por este recinto.",138,2,6,140,"El caballo",9,6,"io",527,0,-1,0,165,165,"6720","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6721",7,"Me despido, pero vuelvo\na demostrar lo que valgo.\nApolinar, no tengas miedo,\nque tú tienes mi respaldo;\nya ves cuánto, yerbabuena,\nle has de dar sabor al caldo,",142,2,8,140,"La yerbabuena",9,6,"ao",603,0,-1,0,165,165,"6721","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6722",7,"Ya me duele la boquita\ny me duele el paladar,\nme duele hasta la cintura\nya de tanto vacilar.",135,2,-1,140,"El vacilón",0,4,"a",21,0,-1,0,166,166,"6722","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6723",7,"Me dicen que soy coqueta,\nque padezco mal de amores,\npero al mundo no le importa:\ntengo alegre el corazón.",135,2,-1,140,"Al compás del 30-30",5,4,"o",-1,0,-1,0,166,166,"6723","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6724",7,"Me dicen que por amores\nme tiré a la perdición,\ny eso es purita mentira,\npues me gusta el vacilón.",135,2,-1,140,"El borrachito",0,4,"o",31,0,-1,0,166,166,"6724","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6725",7,"Y por eso tengo el alma\nde trovador y bohemio;\nyo soy el aventurero;\nbuenas tardes y áhi nos vemos.",135,2,-1,140,"El aventurero",3,4,"eo",-1,0,-1,0,166,166,"6725","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6726",7,"Si quieren saber quién soy.\npregúntenselo a Cupido:\nyo soy el muchacho alegre,\nde cielo favorecido.",142,2,8,140,"El muchacho alegre",0,4,"io",101,0,-1,0,166,166,"6726","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6727",7,"Yo soy el muchacho alegre,\nque me divierto cantando,\ncon mi botella de vino\ny mi baraja jugando.",142,2,8,140,"El muchacho alegre",0,4,"ao",33,0,-1,0,166,166,"6727","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6728",7,"Yo traigo de Guanajuato\nsu gusto y sus tradiciones,\ny busco el amor ingrato\nque rompe mil corazones;\nlo bueno es pasar el rato\nentre tequila y canciones.",135,2,-1,140,"Mi glorioso Guanajuato",9,6,"oe",34,0,-1,0,166,166,"6728","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6729",7,"Tres vicios tengo\ny los tengo muy arraigados:\nel ser borracho,\njugador y enamorado.",144,2,10,140,"El abandonado",3,4,"ao",-1,0,-1,0,166,166,"6729","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6730",7,"Me dicen el fanfarrón,\nporque mi vida es así;\nla culpa la tengo yo,\nporque en el juego perdí\nalma, vida y corazón.",135,2,-1,140,"El fanfarrón",7,5,"o",-1,0,-1,0,166,166,"6730","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6731",7,"Por Dios, que dirá mi madre:\n—¿Dónde andará ese inocente?\nY le respondió mi padre:\n—¡Qué vieja tan imprudente!\nA mi hijo le gusta el baile\ny también el aguardiente.",139,2,2,140,"El huerfanito",9,6,"ee",15,0,-1,0,167,167,"6731","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6732",7,"Yo juego baraja\ny sé parrandear;\nlo mismo les tomo\ntequila o mezcal,\nlo mismo pulquito,\ntambién el champán;\nlo mismo les bailo\nque un tango, que un vals,\ntambién un jarabe\no algún cha cha chá.",135,2,-1,140,"El aventurero",18,10,"a",-1,0,-1,0,167,167,"6732","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6733",7,"Traigo mi machete gacho,\nporque los vengo a tantear;\nsé bailar mi jarabito\ny beber mucho mezcal.",135,2,-1,140,"‘‘Capotear por lo lindo",0,4,"a",-1,0,-1,0,167,167,"6733","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6735",7,"Me cuadra mucho el jarabe,\nme cuadra, me ha de cuadrar,\nbebiendo muy buen tequila\ny aprendiendo a conquistar.",135,2,-1,140,"‘‘La chaparrita",0,4,"a",21,0,-1,0,167,167,"6735","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6736b",7,"Soy hijo de una tonada,\nde un verso nací pendiente,\nbautizado en vino y agua,\nconfirmado en aguardiente,\namigo de la paseada,\npero siempre buena gente.",138,2,6,140,"El querreque",9,6,"ee",15,0,-1,0,167,167,"6736b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6737",7,"Adiós, paseos primorosos\nde Jamaica a Santa Anita;\nya nos paseamos gustosos\nentonando “La casita”;\nque el hombre que es paseador\nsólo mi Dios se lo quita.",135,2,-1,140,"Los paseos de Santa Anita",9,6,"ia",50,0,-1,0,167,167,"6737","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6738",7,"Como muchacho soltero\nque está de buena gana,\naunque le falte dinero,\ntemprano y muy de mañana,\naprieta el guitarrero,\nduro azoto yo la jarana.",142,2,8,140,"El siquisirí",9,6,"aa",4,0,-1,0,168,168,"6738","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6739",7,"Entre la cal y la arena\nse encierra mi profesión,\ny en brazos de una morena\nse estrecha mi corazón;\nnunca me doy a la pena:\nsiempre ando de vacilón.",135,2,-1,140,"El albañil",9,6,"o",31,0,-1,0,168,168,"6739","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6740",7,"Yo soy como el alacrán de Durango,\nque no pica ni va al fandango:\nse la pasa por la sierra\ncantando bonitos huapangos.",138,2,6,140,"Estrofa suelta",3,4,"ao",-1,0,-1,0,168,168,"6740","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6741",7,"Nací en la costa caliente\nde ese puerto tropical;\nsoy alegre y soy valiente;\nmuy gallo para enamorar.",135,2,-1,140,"El alegre tampiqueño",0,4,"a",-1,0,-1,0,168,168,"6741","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6742",7,"Soy como el aire que corre,\nloco y desesperado;\nsoy como el gallo giro:\nvaliente y enamorado.",148,2,9,140,"Estrofa suelta",0,4,"ao",14,0,-1,0,168,168,"6742","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6743",7,"Yo soy como el gallo giro,\na nada tengo temor;\nsoy terror de los valientes\ny muy diablo en el amor.",135,2,-1,140,"Éntrale al toro",0,4,"o",72,0,-1,0,168,168,"6743","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6744",7,"Yo soy de León, Guanajuato,\ndel barrio de San Miguel;\ntengo el corazón de acero,\nporque lo debo a la ley.",135,2,-1,140,"Mi tierra es León, Guanajuato",0,4,"e",-1,0,-1,0,168,168,"6744","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6745",7,"Soy el ranchero afamado,\nque de la sierra he bajado;\nvengo a gastar mi dinero;\nno les vengo a pedir fiado.",137,2,3,140,"El ranchero afamado",0,4,"ao",14,0,-1,0,168,168,"6745","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6746",7,"Ya llegó la tigra,\nla que no han podido ver;\nno les pide fiado,\nni tampoco de comer.",140,2,12,140,"Estrofa suelta",0,4,"e",20,0,-1,0,168,168,"6746","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6747",7,"Soy el diablo y he llegado,\naunque no me puedan ver;\nno vengo pidiendo fiado,\nni tampoco de comer.",142,2,8,140,"Estrofa suelta",1,4,"e",20,0,-1,0,169,169,"6747","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6748",7,"¡Qué bonito es el alcohol\ncuando se está haciendo bolas!\nTraigo [parque] en mi fajilla\ny otro poco en mi pistola.",143,2,18,140,"La canelera",0,4,"oa",-1,0,-1,0,169,169,"6748","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6749",7,"Mi pantalón es de peto,\nmi chamarra de mezclilla;\ny no me la hagan de pleito,\nporque también soy malilla;\nme gusta tomar correcto\ncon toda mi palomilla.",135,2,-1,140,"El albañil’T",9,6,"ia",162,0,-1,0,169,169,"6749","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6750",7,"Los hombres que no son hombres\ntan sólo me hacen reír,\npero los machos valientes\nme gustan hasta el morir.",135,2,-1,140,"Donde las dan las toman",0,4,"i",157,0,-1,0,169,169,"6750","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6751",7,"Me dicen enamorado,\npero de eso nada tengo;\npor áhi me dicen el Negro,\nel Negro, pero con suerte,\nporque si me salta un gallo,\nno me le rajo a la muerte.",149,2,20,140,"El sinaloense",9,6,"ee",134,0,-1,0,169,169,"6751","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6752",7,"¡Ay, reata, no te revientes,\nque eres de San Juan del Río!\nSí, yo soy un rancherito\nde los que usan el patío,\nque hablándome al derechito\na nadie le tengo frío.",135,2,-1,140,"El queretanito",9,6,"io",-1,0,-1,0,169,169,"6752","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6753",7,"Yo soy un queretanito,\nla tierra de los camotes,\ndonde se usan los fandangos\nsin alardes ni mitotes;\nno le temo a los chiquitos,\nni tampoco a los grandotes.",135,2,-1,140,"El queretanito",9,6,"oe",565,0,-1,0,169,169,"6753","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6754",7,"Soy forastero en esta tierra,\nque vine por vez primera;\nno le temo a los balazos,\naunque la sangre me viera.",135,2,-1,140,"La canelera",0,4,"ea",44,0,-1,0,169,169,"6754","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6755",7,"Soy costeño, nacido en Guerrero,\nno me afrento de ser lo que soy;\na mí nunca se me arruga el cuero:\nsi me buscan, dondequiera estoy.",146,2,7,140,"Tierra Colorada",3,4,"o",112,0,-1,0,169,169,"6755","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6756",7,"Una aguililla chillona\nme quiso tronar el pico,\ny le contesté: “Pelona,\nno soy pobre ni soy rico;\nsoy puritito costeño,\nno me agrando ni me achico”.",135,2,-1,140,"El toro rabón",9,6,"io",141,0,-1,0,170,170,"6756","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6757",7,"Lo que sí les aseguro,\ndonde las pinten las brinco,\nque yo me rifo la vida\ncon dos, con tres, o con cinco.",135,2,-1,140,"Éntrale al toro",0,4,"io",559,0,-1,0,170,170,"6757","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6758",7,"No soy matón ni bravero,\nmás nunca me sé rajar;\nsi quieren buscar enredo,\ncon mi pistola se entenderán.",135,2,-1,140,"¡Arriba Sinaloa!",3,4,"a",-1,0,-1,0,170,170,"6758","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6759",7,"¿Quién dijo miedo, muchachos,\nsi para morir nacimos?\nTraigo mi cuarenta y cinco\ncon sus cuatro cargadores.",135,2,-1,140,"Traigo mi cuarenta y cinco",5,4,"oe",-1,0,-1,0,170,170,"6759","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6760",7,"Soy de Cerro Colorado,\ndonde está pintado el león;\nsoy pobre y no me rebajo\nni me tiento el corazón.",136,2,4,140,"El sacamandú",0,4,"o",31,0,-1,0,170,170,"6760","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6761",7,"Oyes, Esteban,\nno sale bien:\nel calero no se raja,\nmucho menos su mujer.",135,2,-1,140,"El calero",3,4,"e",-1,0,-1,0,170,170,"6761","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6762",7,"Traigo un gallo muy jugado,\npara echarlo de tapado,\nsi hay algún apostador;\ny también traigo pistola,\npor si alguno busca bola\ny me tacha de hablador.",145,2,17,140,"Cocula",9,6,"o",72,0,-1,0,170,170,"6762","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6763",7,"Hagan su apuesta, señores,\nque mi gallo va a pelear;\nno le temo a los traidores,\nsi me quieren espantar.",135,2,-1,140,"El gallo jaspeado",1,4,"a",21,0,-1,0,170,170,"6763","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6764",7,"No porque me ven tan pollo\nse quieren burlar de mí:\nsi quieren, vamos saliendo\ntres pasos fuera de aquí.",161,2,15,140,"Las pollas",0,4,"i",23,0,-1,0,170,170,"6764","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6765",7,"En mi caballo ensillado,\nmi machete y buena silla,\nde los hombres sinaloenses,\naunque me cueste la vida.",149,2,20,140,"¡Viva mi Sinaloa!",0,4,"ia",-1,0,-1,0,170,170,"6765","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6766",7,"Yo en la noche me he paseado\ncon mi sarape embrocado,\nmi pistola en la cintura,\ny en mi cuaco bien montado.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"ao",14,0,-1,0,171,171,"6766","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6767",7,"Esta pistola que cargo\nla cargo yo en la cintura;\nyo les pido lo. que el muerto:\nno más pura sepultura.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"ua",17,0,-1,0,171,171,"6767","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6768",7,"Yo no soy de los que gritan\ncuando ya está uno perdido;\nme muero en la mera raya,\npero nunca soy rendido.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"io",101,0,-1,0,171,171,"6768","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6769",7,"Yo no digo que soy hombre\nni que tengo buenos brazos;\ncon mi machete en las manos\nrecogerán los pedazos.",142,2,8,140,"Estrofa suelta",0,4,"ao",-1,0,-1,0,171,171,"6769","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6770",7,"Yo les digo a los panteras:\n“No vayan a venadear”;\nque me maten al derecho,\nsi es que me quieren matar.",135,2,-1,140,"Traigo mi cuarenta y cinco",0,4,"a",21,0,-1,0,171,171,"6770","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6771",7,"No porque me ven tan bueno,\nme voy a dejar matar;\ntambién sé defenderme\ny también sé pelear.",148,2,9,140,"Estrofa suelta",0,4,"a",21,0,-1,0,171,171,"6771","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6772",7,"Soy natural de Coahuila,\nnacido en mero Saltillo;\nsoy como los gavilanes:\naleteo, pero no chillo.",135,2,-1,140,"De purito Coahuila",0,4,"io",228,0,-1,0,171,171,"6772","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6773",7,"Y éstos son los barandales;\nconmigo no más tres piedras\ny más arriba,\ntres pedernales.",147,2,11,140,"Los barandales",3,4,"ae",26,0,-1,0,171,171,"6773","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6774",7,"Soy como el agua del río\nque corre en los arenales,\nconmigo no más tres piedras\ny también tres pedernales.",137,2,3,140,"El cuervo; El pescado nadador",0,4,"ae",26,0,-1,0,171,171,"6774","",0,"","","",6,0,0,[],"",""],["frenk_t3-n6775",7,"Con mi vestido de charro\ny mi chatita del brazo,\npara mí la pulpa es pecho\ny cadera el espinazo;\naquí me sobra otro peso:\nlo que es hora me emborracho.",135,2,-1,140,"Los paseos de Santa Anita",9,6,"ao",-1,0,-1,0,171,171,"6775","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6776",7,"Son muchas cacaraqueadas,\nno me van a convencer;\npa mí son más las echadas,\nque las que se van a poner.",135,2,-1,140,"El corral",1,4,"e",20,0,-1,0,172,172,"6776","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6777",7,"Me gusta oler el repollo\ny las flores del pitayó;\nsoy machito, y no un pimpollo,\nsoy de a pie y monto a caballo,\ny aunque me miren tan pollo,\ntengo más plumas que un gallo.",135,2,-1,140,"Amores con falsete",9,6,"ao",102,0,-1,0,172,172,"6777","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6778",7,"Soy aguador, no lo niego,\ny gano para ir al teatro;\nno porque me vean chiquito,\nsoy padre de más de cuatro.",142,2,8,140,"Estrofa suelta",0,4,"ao",604,0,-1,0,172,172,"6778","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6779",7,"Dudan que tengo colmillo\nlos que me ven muchachón,\npero ya tengo la cresta\ny también el espolón;\nfuímonos con el falsete,\nque se acabó la canción.",135,2,-1,140,"Amores con falsete",9,6,"o",31,0,-1,0,172,172,"6779","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6780",7,"Barrio alegre,\n¡qué ganas tenía de vertel;\ntú me vas a consolar;\ntodavía traigo dinero\npara poderme pasear;\nme paseo y me repaseo,\naunque me resulte mal.",137,2,3,140,"Barrio alegre",4,7,"a",-1,0,-1,0,172,172,"6780","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6781",7,"A mí me quieren matar,\nporque ando aquí paseando;\nhijos de un perico verde,\nno se anden equivocando.",135,2,-1,140,"La palomita",0,4,"ao",33,0,-1,0,172,172,"6781","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6782",7,"Dicen que me han de matar\nhora que ando en las paseadas;\nal cabo ¿qué me han de hacer\nlos hijos del as de espadas?",147,2,11,140,"La chinita",0,4,"aa",282,0,-1,0,172,172,"6782","",0,"","","",20,0,0,[],"",""],["frenk_t3-n6783",7,"Dicen que me han de matar\na orillas del camposanto;\nmentira, no me hacen nada,\nque estoy curado de espanto.",137,2,3,140,"María, María",0,4,"ao",30,0,-1,0,172,172,"6783","",0,"","","",20,0,0,[],"",""],["frenk_t3-n6784",7,"Dicen que me han de matar\ncon una daga muy buena:\nlas heridas que me hagan\nme las curo con arena.",145,2,17,140,"María, María",0,4,"ea",59,0,-1,0,172,172,"6784","",0,"","","",20,0,0,[],"",""],["frenk_t3-n6785",7,"A mí me quieren matar\npor esta calle real;\ndonde andan las aguilillas\nno vuela ni un gavilán.",135,2,-1,140,"La palomita",0,4,"a",-1,0,-1,0,172,172,"6785","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6786",7,"Yo soy gallito jugado\ny me juego con cualquiera;\nsi me toca mala suerte,\nya me curaré con tierra.",135,2,-1,140,"‘‘El valiente de San Juan del Río",0,4,"ea",-1,0,-1,0,173,173,"6786","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6787",7,"Los panteras no me asustan,\naunque los vea muy grandotes;\nno les temo a los balazos,\nmenos a los guajolotes.",135,2,-1,140,"La canelera",0,4,"oe",565,0,-1,0,173,173,"6787","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6788",7,"Yo soy de la Costa Chica,\nno me importan los valientes;\nme río de las calaveras,\nsi están pelando los dientes.",135,2,-1,140,"‘‘El palmero",0,4,"ee",252,0,-1,0,173,173,"6788","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6789",7,"Si con puñal soy valiente,\ncon pistola no se diga;\nalgo les pasa a las balas,\npues que la muerte es mi amiga.",135,2,-1,140,"‘‘Mi tierra es León, Guanajuato",0,4,"ia",232,0,-1,0,173,173,"6789","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6790",7,"Para mejorar mi vida,\nme enamoré de la muerte,\ny corrí con buena suerte,\nque la hice mi querida,\ny ahora me siento muy fuerte\nporque la tengo parida.",142,2,8,140,"Estrofa suelta",9,6,"ia",37,0,-1,0,173,173,"6790","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6791",7,"Queretano soy, señores,\ny le atoro a las manganas,\nle entro a todos los amores\nporque siempre me dan ganas,\ny tengo pa los traidores\nmi Cerro de las Campanas.",135,2,-1,140,"‘‘El queretano",9,6,"aa",263,0,-1,0,173,173,"6791","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6792",7,"Me he pasado hasta Coyuca,\ny en la ciudad de Candela\na toros, no becerritos,\nsiempre les traigo espuelas.",142,2,8,140,"Estrofa suelta",0,4,"ea",-1,0,-1,0,173,173,"6792","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6793",7,"Soy soldado de guerrilla;\nno doy a torcer el brazo;\ndoy vuelta a cabeza ’e silla,\ny aguarden el barquinazo.",135,2,-1,140,"Estrofa suelta",1,4,"ao",43,0,-1,0,173,173,"6793","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6794",7,"Soy coco de los malcriados\ny terror de las mujeres;\nme voy pa lejanas tierras\na buscar otros quereres.",135,2,-1,140,"El palmero",0,4,"ee",55,0,-1,0,173,173,"6794","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6795",7,"De Soyanque para abajo\nno se conocen los hombres;\nde que venga el mariscal,\ny hasta los perros se esconden.",142,2,8,140,"La Sanmarqueña",0,4,"oe",-1,0,-1,0,173,173,"6795","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6796",7,"En el barrio los malditos\ntodos se vuelven leones,\ncuando ven a la pantera\ntodos son puros camiones.",135,2,-1,140,"Traigo mi cuarenta y cinco",0,4,"oe",34,0,-1,0,174,174,"6796","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6797",7,"Yo soy como el gallo giro\ndel palenque de la feria,\ngritándole a los galleros\nque me suelten a cualquiera,\na ver si hago una ensalada\ncon todita la gallera.",135,2,-1,140,"Las dos Marías; Lucha María",9,6,"ea",44,0,-1,0,174,174,"6797","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6798",7,"A los pollos les aviso\nque caminen con cuidado,\nque les voy hacer un guiso\nde pollos en estofado.",136,2,4,140,"El pollo",1,4,"ao",14,0,-1,0,174,174,"6798","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6799",7,"Estos versitos compuse\nantes de llegar a Teapa;\npongan cuidado, muchachos,\nsoy de Cuajinicuilapa.",135,2,-1,140,"Ahora pregunto, pregunto",0,4,"aa",297,0,-1,0,174,174,"6799","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6800",7,"Mis versos a un tiempo van,\nlos canto sin indolencia;\nal pasar por Milibrán,\n¡ayl sin tener asistencia,\nno hay más leña en Ocotlán\nque la de Miguel Valencia.",136,2,4,140,"El siquisirí",9,6,"ea",46,0,-1,0,174,174,"6800","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6801a",7,"Donde están las aguilillas\nno rifan los gavilanes,\nni las naguas amarillas,\naunque les pongan olanes.",135,2,-1,140,"El jarabe; Los tulises",1,4,"ae",444,0,-1,0,174,174,"6801a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6802",7,"Para la que sea marota,\naquí traigo este torito,\ny como soy charrito,\nni las espuelas me quito;\nvoy con todas mis botas.",136,2,4,140,"El torito",7,5,"oa",-1,0,-1,0,174,174,"6802","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6803",7,"Cierto que echo mis habladas,\npero Sostenes me llamo;\na mí naiden me hace nada,\ncomo quiera yo les gano,\ny no hay ley más respetada,\nque un machete entre mis manos.",146,2,7,140,"La sureña",9,6,"ao",-1,0,-1,0,175,175,"6803","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6804",7,"A mí no me manda medio\nni me domina cuartilla;\npor donde quiera que yo ando\nninguna víbora chilla.",142,2,8,140,"El valiente; Estrofa suelta",0,4,"ia",162,0,-1,0,175,175,"6804","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6805",7,"Yo soy el que siempre fui,\nmi palabra siempre vale;\nme gusta cantar así,\ny no, hay quien me lo reclame;\nel que por su gusto es buey\nhasta la coyunda lame.",135,2,-1,140,"El fuereño",9,6,"ae",533,0,-1,0,175,175,"6805","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6806",7,"Soy de puro Jalisco,\nde los mentados valientes;\nsoy de los meros picudos,\na mí me pelan los dientes.",135,2,-1,140,"La canelera",0,4,"ee",252,0,-1,0,175,175,"6806","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6807",7,"“Quiquiriquí”, dice un gallo\ncuando lo van a pelear;\nsoy de puro Guanajuato,\ndonde se juega el puñal.",135,2,-1,140,"El gallerito",0,4,"a",-1,0,-1,0,175,175,"6807","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6808",7,"A mí me gusta pelear\ncon tres, cuatro, hasta con cinco,\nporque traigo mi charrasca\npara el que quiera atorarla.",135,2,-1,140,"De purito Coahuila",5,4,"aa",-1,0,-1,0,175,175,"6808","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6809",7,"Tengo mi par de pistolas\ncon sus cachas de marfil,\npara darme de balazos\ncon los del ferrocarril.",135,2,-1,140,"La rielera",0,4,"i",290,0,-1,0,175,175,"6809","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6810",7,"En la rama de un limón\nun pájaro me ha silbado;\náhi le contestó un gurrión:\n“Todos vengan bien parqueados,\nporque dice la canción\n«Ya llegó Juan Charrasqueado»”.",142,2,8,140,"El pájaro cú",9,6,"ao",-1,0,-1,0,175,175,"6810","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6811",7,"Ahora fui tras el infierno,\nya llegó el Águila Negra,\ny viene ajustando cuentas:\nno se pongan a temblar.",137,2,3,140,"El Aguila Negra",5,4,"a",-1,0,-1,0,175,175,"6811","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6812",7,"Que en este mundo engañoso\nno se queda nada oculto:\nel que la hace me la paga\npa que aprenda a ser formal.",137,2,3,140,"El Aguila Negra",5,4,"a",-1,0,-1,0,175,175,"6812","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6813",7,"—Oiga, amigo, usté ¿a quién busca?\n—Ando buscando un malora,\nque dicen que es muy picudo,\npero conmigo se atora.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"oa",107,0,-1,0,176,176,"6813","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6814",7,"Si mañana o el pasado\nde mí se quieren burlar,\npara que de mí se burlen\nla vida le ha de costar.",155,2,14,140,"Cuando salgo del trabajo",0,4,"a",21,0,-1,0,176,176,"6814","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6815",7,"En la isla del islote\ntambién hay muchos malditos;\nahora sí llegó su padre\nde todos estos malditos.",135,2,-1,140,"Traigo mi cuarenta y cinco",0,4,"io",-1,0,-1,0,176,176,"6815","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6816",7,"Vengo de Guadalajara,\nde Guadalajara vengo;\nyo no vengo a ver si puedo,\nsino porque puedo vengo.",136,2,4,140,"El Ahualulco",0,4,"eo",-1,0,-1,0,176,176,"6816","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6817",7,"Ya con ésta me despido,\ny áhi, traidores, les prevengo:\nyo no vengo a ver si puedo,\nsino porque puedo vengo.",135,2,-1,140,"Yo no vengo a ver si puedo",3,4,"eo",-1,0,-1,0,176,176,"6817","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6818",7,"Lo que digo de hoy en día,\nlo que digo lo sostengo:\nyo no vengo a ver si puedo,\nsino porque puedo vengo.",145,2,17,140,"Yo no vengo a ver si puedo",0,4,"eo",-1,0,-1,0,176,176,"6818","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6819",7,"Yo no vengo a ver si puedo,\nsino porque puedo vengo;\nlo que les digo borracho\nen mi juicio lo sostengo;\nya pueden irse fajando,\nque al cabo para todos tengo.",142,2,8,140,"Estrofa suelta",9,6,"eo",124,0,-1,0,176,176,"6819","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6820",7,"Cuando arranco en mi caballo\ncon mi reata y mis espuelas,\nganas de pelear me dan\npara dejarlos sin muelas.",135,2,-1,140,"El valiente de San Juan del Río",3,4,"ea",605,0,-1,0,176,176,"6820","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6821a",7,"Árboles de la alameda,\n¿por qué no han reverdecido?\n¿Qué dicen, calandrias, cantan?,\no les apachurro el nido.",135,2,-1,140,"La chinita; La calandria; El distinguido; El venadito",0,4,"io",101,0,-1,0,176,176,"6821a","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6822",7,"Andándome yo paseando,\nme encontré con don Crisanto;\nlo despaché al camposanto,\nporque me mató a mi tío;\nque también soy tapatío:\nde veras me las espanto.",135,2,-1,140,"Las barrancas; La esposa infiel",9,6,"ao",30,0,-1,0,177,177,"6822","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6823",7,"Ando entre la sombra del diablo\ny la cruz del Antecristo;\n¡ah, qué gente tan babosa!,\nparece que no me ha visto.",142,2,8,140,"Estrofa suelta",0,4,"io",273,0,-1,0,177,177,"6823","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6824",7,"¡Ay, chivito achivarradol,\nvuelve a pegar otro brinco;\n¡ay, qué admiración les cabe!,\nparece que nunca han visto.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"io",-1,0,-1,0,177,177,"6824","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6825",7,"De por allá abajo vengo,\narrastrando mi cubierta;\nhay quienes se me quedan viendo,\nque están con la trompa abierta.",142,2,8,140,"Que comienzo, que comienzo",0,4,"ea",267,0,-1,0,177,177,"6825","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6826",7,"Por esta calle derecha\nsalgo mi trompo bailando,\ny por eso digo: “¿Cuándo?”\na los que me están mirando\nque estoy mi trompo bailando.",136,2,4,140,"El trompo",7,5,"ao",33,0,-1,0,177,177,"6826","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6827",7,"El que quiera corazón\nque me lo venga a pedir,\naunque soy chico de edad,\nno tengo miedo al morir.",135,2,-1,140,"Traigo mi cuarenta y cinco",0,4,"i",157,0,-1,0,177,177,"6827","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6828",7,"No hay quien se atreva conmigo,\npues saben que han de perder;\nsi me tantean tan seguido,\nque me hablen de una vez.",135,2,-1,140,"La Valentina",0,4,"e",-1,0,-1,0,177,177,"6828","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6829",7,"Si hay alguno en la humedad,\nsi hay alguno que le duela,\nque le dé su consuelo,\nsu consuelo de verdad.",135,2,-1,140,"Maldita sea mi suerte",5,4,"a",16,0,-1,0,177,177,"6829","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6830",7,"He bajado hasta el poblado\npor el rumor que se corre;\ntengo fama de pelado\ny busco a alguien que la borre;\nquiero jugarme un volado,\nmas que me den en la torre.",135,2,-1,140,"El queretano",9,6,"oe",136,0,-1,0,178,178,"6830","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6831",7,"El que quiera y no le guste\nlo que acabo de cantar,\nque le salga afuera:\nyo nunca me sé rajar.",135,2,-1,140,"La canelera",0,4,"a",21,0,-1,0,178,178,"6831","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6832",7,"Yo soy puro fronterizo,\nsoy valiente y no me rajo;\nel que quiera probaditas\nque se presente y a darle.",135,2,-1,140,"De purito Coahuila",5,4,"ae",-1,0,-1,0,178,178,"6832","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6833",7,"Qué fuerte hervor de frijoles,\nel olor me está mareando;\ny si hay alguno que brinque,\npos ya le estamos dimos dando.",135,2,-1,140,"Las calabazas’T",0,4,"ao",33,0,-1,0,178,178,"6833","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6834",7,"Traigo carga en mi pistola\ny tiros en mi fajilla,\ny el que no lo quiera creer\nque salga para la orilla.",135,2,-1,140,"La canelera",3,4,"ia",162,0,-1,0,178,178,"6834","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6836",7,"A tlaco doy las trompadas,\ny a tlaco las he de dar,\ny al que me pida trompadas\ntrompadas le he de dar.",147,2,11,140,"Pregón de las trompadas",1,4,"a",-1,0,-1,0,178,178,"6836","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6837",7,"La mujer de Salomón (íic)\nlo vide y le quise hablar,\ny me respondió afligido:\n“Póngase a considerar,\nel que se meta conmigo\nla vida le va a costar”.",142,2,8,140,"Estrofa suelta",9,6,"a",21,0,-1,0,178,178,"6837","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6838",7,"Y si nací, nací para venturoso,\ny no nací para diversión del mundo;\nle pido a Dios que me dé una suerte buena;\n¡hora, panteras, voy que no salen al soll",144,2,10,140,"hora, panteras, voy que no salen al sol! [La luna",3,4,"o",-1,0,-1,0,178,178,"6838","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6839",7,"Traidores, yo soy su azote,\nmi cuchillo es el segundo,\nlos he de hacer a mi ley\no los separo del mundo.",142,2,8,140,"El valiente",0,4,"uo",179,0,-1,0,179,179,"6839","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6840",7,"Cabrones, aquí anda su manso,\npero no sabe de empelo;\ntodos lo quieren montar,\npero le sienten recelo.",142,2,8,140,"Estrofa suelta",3,4,"eo",10,0,-1,0,179,179,"6840","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6841",7,"Por esta calle derecha\nsembré chiles con vinagre;\nel que no me pueda ver\nque vaya a Chihuahua al baile.",137,2,3,140,"Verdad de Dios",0,4,"ae",-1,0,-1,0,179,179,"6841","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6842",7,"Como que quiere llover,\ncomo que quiere hacer aire;\ny el que no me pueda ver\nque vaya y vuelva a la tarde.",136,2,4,140,"La Manuelita; La Sanmarqueña",0,4,"ae",-1,0,-1,0,179,179,"6842","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6843",7,"Un gavilán ál volar,\nal volar, anchó la cola;\nsi no me lo quieren creer,\ncanallas, vengan, nos haremos bola.",142,2,8,140,"Estrofa suelta",3,4,"oa",321,0,-1,0,179,179,"6843","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6844",7,"¡Ay qué torres tan delgadas!,\n¡cómo no las tira el aire!\nEl que no lo quera creer\nque vaya y vuelva a la tarde.",147,2,11,140,"La higuera’",0,4,"ae",-1,0,-1,0,179,179,"6844","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6845",7,"Soy puro San Juan del Río,\nsoy valiente y no embustero,\ny el que no me pueda ver\nque me arremangue el sombrero.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"eo",38,0,-1,0,179,179,"6845","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6846",7,"Este corrido que canto\nse los canto a los malditos:\nno a la hora de los balazos\nanden pegando de gritos.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"io",254,0,-1,0,179,179,"6846","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6847",7,"Si sale algún decidido\nque se la quera rifar,\nvaya pensando en la viuda,\na quién se la va a dejar.",135,2,-1,140,"Mi tierra es León, Guanajuato",0,4,"a",21,0,-1,0,179,179,"6847","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6848",7,"En esta calle derecha\nvoy a formar un puente\ncon las costillas de chivo\ny la sangre de un valiente.",142,2,8,140,"Estrofa suelta, El guapo",0,4,"ee",15,0,-1,0,180,180,"6848","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6849",7,"Préstenme la carabina,\nla pistola de mi hermano;\nvamos pa dentro, muchachos,\nse me hace que yo les gano.",137,2,3,140,"El ranchero afamado",0,4,"ao",-1,0,-1,0,180,180,"6849","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6850",7,"Al otro lado del río\nvoy a sembrar mi labor,\ncon una yunta de [bueyes]\ny un chivo de sembrador.",138,2,6,140,"La muía de siete cuartas; La mulita; La sandía; Estrofa suelta",0,4,"o",72,0,-1,0,180,180,"6850","",0,"","","",15,0,0,[],"",""],["frenk_t3-n6851",7,"Al pájaro carpintero\nse lo llevó la borrasca.\nCon dinero o sin dinero,\nyo compro lo que me plazca,\nporque tengo un compañero\nque hasta los olotes masca.",147,2,11,140,"El venadito",9,6,"aa",597,0,-1,0,180,180,"6851","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6852",7,"Aquí me huele a mango,\npero al maduro de hoy.\nVe que si andan pelando,\nporque yo echo un catamoy;\na quien me lo anda cazando\nme sirve de entretención.",136,2,4,140,"El siquisirí",9,6,"o",-1,0,-1,0,180,180,"6852","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6854a",7,"Yo nací en Tehuantepec,\ny nunca lo ando diciendo;\nunos no son de aquí:\nno más andan presumiendo.",142,2,8,140,"La Zandunga",0,4,"eo",52,0,-1,0,180,180,"6854a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6854b",7,"Yo nací en el Rancho Grande\ny no ando presumiendo,\nalgunos no son de aquí\ny no más lo andan diciendo,\ncomo uno que conocí\ny que sigo conociendo.",136,2,4,140,"El caballo palomo",9,6,"eo",52,0,-1,0,180,180,"6854b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6854c",7,"Yo en Rancho Grande nací,\npero quiero este lugar,\ny nunca lo ando diciendo;\nhay quienes no son de aquí\ny no más van presumiendo,\ncomo uno que conocí\ny que sigo conociendo.",135,2,-1,140,"El caballo palomo",4,7,"eo",52,0,-1,0,181,181,"6854c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6855",7,"Si en algo me propaso\nváyame disimulando,\ny a la que le venga el saco,\nque se lo vaya abrochando.",142,2,8,140,"Estrofa suelta",0,4,"ao",-1,0,-1,0,181,181,"6855","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6856",7,"Ya con ésta me despido\nde los que me están oyendo,\ny a los que les venga el saco\nya se lo estarán poniendo:\nles multiplico sus cuentas,\ny hasta me salen debiendo.",161,2,15,140,"El buey",9,6,"eo",52,0,-1,0,181,181,"6856","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6857",7,"Hay muchos que en el cantar\ndan su envidia a conocer;\nhay muchos que prenden lumbre\ny no saben apagar.",147,2,11,140,"Estrofa suelta",5,4,"a",21,0,-1,0,181,181,"6857","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6859a",7,"Las lumbres que yo he prendido\nno las apaga cualquiera;\nyo conozco caporales\nque se han quemado en la hoguera.",147,2,11,140,"Estrofa suelta",0,4,"ea",44,0,-1,0,181,181,"6859a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6860",7,"Mañana me voy de aquí,\nya me voy para mi rancho,\nvoy a tostarle sus habas\na un camero que es mi sancho.",147,2,11,140,"El valiente de San Juan del Río’T coplas jactanciosas",0,4,"ao",380,0,-1,0,181,181,"6860","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6861",7,"En la puerta de mi casa\ntengo ensartado un farol;\nen la punta de mi daga,\nla lengua de un hablador.",135,2,-1,140,"Estrofa suelta",0,4,"o",-1,0,-1,0,182,182,"6861","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6862",7,"Soy el gallito giro,\nque canta en el cascarón;\na la buena soy tu amigo,\ny a la mala soy cabrón.",142,2,8,140,"Estrofa suelta",0,4,"o",31,0,-1,0,182,182,"6862","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6863",7,"Bajo un sol que abrasa tanto\nse baila y se canta el son;\nlos tordos tienen su canto,\ndiciendo: “Date un quemón”.",135,2,-1,140,"El hidalguense",1,4,"o",-1,0,-1,0,182,182,"6863","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6864",7,"Yo soy aquel oaxaqueño\nnacido entre los huajales;\nsi me quieres conocer,\nando por varios lugares.",142,2,8,140,"Yo soy aquel oaxaqueño",0,4,"ae",-1,0,-1,0,182,182,"6864","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6865",7,"¡Adentro, Maravatío,\nque Acámbaro ya perdió!\nSi no se halló suficiente,\n¿pa qué se comprometió?",137,2,3,140,"El caballo prieto; El caballo Lucero",0,4,"o",2,0,-1,0,182,182,"6865","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6866",7,"Su lengua es de doble filo,\npero le recuerdo yo\nque donde las dan las toman,\ny callarse es lo mejor.",135,2,-1,140,"Donde las dan las toman",0,4,"o",-1,0,-1,0,182,182,"6866","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6867",7,"Por las orillas del mar\nme vine faranduleando;\nel suyo parece el mío:\nsi quiere, vamos cambiando.",142,2,8,140,"Chilena de Jamiltepec’T",0,4,"ao",33,0,-1,0,182,182,"6867","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6868",7,"Amigo, si usted es mi amigo,\nno me lo deje a mí solo;\nlevánteme mi sombrero,\nque se me cayó en el lodo.",142,2,8,140,"Estrofa suelta",0,4,"oo",-1,0,-1,0,182,182,"6868","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6869",7,"Al tiempo de rayar el sol,\nse vio la sombra de un enano;\ndicen que usted sabe hacer seña:\nhágame una con la mano.",142,2,8,140,"Estrofa suelta",0,4,"ao",81,0,-1,0,182,182,"6869","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6870",7,"Al pasar por Zacatecas\nle dije a un zacatecano:\n“Usted, que sabe de señas,\nhágame una con la mano”.",147,2,11,140,"La Sanmarqueña",0,4,"ao",81,0,-1,0,183,183,"6870","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6871",7,"Estando en profundo sueño,\nme dio el viento de la brisa.\nEn ti traigo yo el empeño\nde quitarte a esta mestiza,\nporque a mí, que soy trigueño,\nbastante me simpatiza.",142,2,8,140,"La morena",9,6,"ia",420,0,-1,0,183,183,"6871","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6872",7,"En la cumbre de aquel cerro\ntengo un paño colorado,\ncon un letrero que dice:\n“Si no puede, hágase a un lado”.",144,2,10,140,"Estrofa suelta",0,4,"ao",14,0,-1,0,183,183,"6872","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6873",7,"Hay uno que en el cantar\nda su envidia a conocer;\nporque no fue caporal\nni lo quiso una mujer,\ncorrió al Palomo tan mal,\nque al patrón hizo perder.",135,2,-1,140,"El caballo palomo",9,6,"e",20,0,-1,0,183,183,"6873","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6875",7,"Por si te parece mal\ny te hace circo la carga,\nyo soy aquel del costal,\nque ni la boca le amarga.",135,2,-1,140,"Estrofa suelta",1,4,"aa",512,0,-1,0,183,183,"6875","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6876",7,"En la punta de aquel cerro\nhay un árbol de ahuehuete;\nyo soy tu amigo,\npero no tu alcahuete.",147,2,11,140,"Estrofa suelta",3,4,"ee",285,0,-1,0,183,183,"6876","",0,"","","",21,0,0,[],"",""],["frenk_t3-n6877",7,"Ya con ésta me despido\npor las cumbres de un ciprés;\nsi no le tomaste asunto,\nte la cantaré otra vez.",135,2,-1,140,"La viuda",0,4,"e",150,0,-1,0,183,183,"6877","",0,"","","",72,0,0,[],"",""],["frenk_t3-n6878",7,"Soy versero decidido,\ndonde quiera soy notado;\nsi usted quiere ser mi amigo,\nconteste cuando yo le hable,\nque yo en San Juanito vivo,\namigo, aunque no le cuadre.",159,2,26,140,"La azucena",9,6,"ae",-1,0,-1,0,183,183,"6878","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6879a",7,"Ya Ja lumbre se apagó,\nsólo un tizón quedó ardiendo;\nalza la cara, cabrón,\nque a ti te lo estoy diciendo.",142,2,8,140,"Estrofa suelta",0,4,"eo",52,0,-1,0,184,184,"6879a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6879b",7,"Ya la lumbre se apagó\ny el tizón se quedó ardiendo;\nalza la cara, bribón,\nque a usted se lo estoy diciendo;\nno más no espere patrón\nque se lo esté repitiendo.",135,2,-1,140,"En una hermosa mañana",9,6,"eo",52,0,-1,0,184,184,"6879b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6880",7,"Aquí le traigo su alfalfa\npara darle de comer,\ny si no quiere su alfalfa,\nyo le picaré el maguey,\npa agarrarlo de los cuernos\ny decirle; “¡Ceja, buey!”",161,2,15,140,"El buey",9,6,"e",133,0,-1,0,184,184,"6880","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6881",7,"Esto te lo digo yo:\nmi mente siempre respinga;\nsoy más viejo que un rebozo,\npero eso aquí tú te chingas;\nsi el verso no te gustó,\npuedes buscarme en Mandinga.",136,2,4,140,"El siquisirí",9,6,"ia",-1,0,-1,0,184,184,"6881","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6882",7,"Bueno, te lo digo yo\ny hago versos de mi agrado:\nsoy más fijo que un reloj,\nsi nacido en Alvarado,\ny si no te gustó,\ntendrás que ser mi entenado.",136,2,4,140,"El siquisirí",9,6,"ao",14,0,-1,0,184,184,"6882","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6883",7,"Fui soldado en Pueblo Viejo,\nteniente y hasta mayor;\ncon cualquiera me emparejo,\nno veo pelo ni color;\nno te arriesgues, perro viejo (íic?),\nque te quiero pa tambor.",136,2,4,140,"El querreque",9,6,"o",72,0,-1,0,184,184,"6883","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6884",7,"No más que no te me rajes,\nporque soy de los malvados,\ny cuando andaba con Villa\nera yo de sus Dorados,\ny no me andes con tanteadas,\nporque doy de puñaladas.",161,2,15,140,"La voltereta",9,6,"aa",282,0,-1,0,184,184,"6884","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6885",7,"Si quieres saber quién soy,\nven y te daré una prueba:\nvamos jugando un conquián\ncon una baraja nueva.",137,2,3,140,"El muchacho alegre",0,4,"ea",481,0,-1,0,184,184,"6885","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6886",7,"Soy de puro Guadalajara,\ndel barrio de la Canela;\nsoy muy hombre, y si lo duda,\nyo le ensarto la chaveta.",135,2,-1,140,"La chaparrita",0,4,"ea",-1,0,-1,0,184,184,"6886","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6887",7,"“Boca cenada no yerra”\nnos dice el viejo refrán,\nasí es que cierre la suya,\nsi es que la alcanza a cerrar.",135,2,-1,140,"Donde las dan las toman’",0,4,"a",-1,0,-1,0,185,185,"6887","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6888",7,"De allá abajo vengo yo\ncon mi campana rajada;\ncállese la trompa, amigo,\no se la callo a trompada.",142,2,8,140,"Estrofa suelta",0,4,"aa",49,0,-1,0,185,185,"6888","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6889",7,"De allá abajo vengo yo\ncon mi docena de cuetes;\ncállese la boca, amigo,\no se la callo a puro zoquete.",142,2,8,140,"Estrofa suelta",3,4,"ee",-1,0,-1,0,185,185,"6889","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6890a",7,"Por áhi va la despedida\ny en una tacita de agua;\nsi mueres, te la perdono,\ny si vives, me la pagas.",135,2,-1,140,"Jilguero desvanecido; La Sanmarqueña; Estrofa suelta",0,4,"aa",-1,0,-1,0,185,185,"6890a","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6890b",7,"Áhi te va la despedida\nen una tacita de agua;\nsi mueres, te la perdono,\ny si vives, me la pagas,\nsólo que tires con plomo\no de la tierra te vayas.",135,2,-1,140,"La calandria’",9,6,"aa",-1,0,-1,0,185,185,"6890b","",0,"","","",6,0,0,[],"",""],["frenk_t3-n6891",7,"Si porque se ve grandote\ny estira tanto la mano,\naunque yo esté chaparrito,\nya verán cómo le gano.",135,2,-1,140,"Serían las dos",0,4,"ao",81,0,-1,0,185,185,"6891","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6892",7,"No porque los veas grandotes\ncreas que por eso me enfado:\nsi yo los tengo de chivo,\ntú los tienes de venado.",145,2,17,140,"Yo ya me voy’",0,4,"ao",14,0,-1,0,185,185,"6892","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6893",7,"Ahora sí, gallito giro,\nya llegó tu amarrador;\nvámonos tirando un tiro,\na ver cuál es el mejor;\nveré si deveras puedes\no eres purito hablador.",135,2,-1,140,"El pájaro carpintero’",9,6,"o",72,0,-1,0,185,185,"6893","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6894",7,"Dicen que tú eres pantera\ny que a mí me andas buscando;\nmete mano a la cintura\ny ándale, vámonos dando.",135,2,-1,140,"El valiente de San Juan del Río",0,4,"ao",33,0,-1,0,185,185,"6894","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6895",7,"Es perico que no canta\ny se las da de maldito;\nno más que brinque la tranca,\npara darnos un tirito.",135,2,-1,140,"Santanón",0,4,"io",119,0,-1,0,185,185,"6895","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6896",7,"Hora sí, Tío Fuele Morga,\nojos coloraos de pargo,\nla ofensa que usted me hizo\nen el corazón la guardo.",142,2,8,140,"Estrofa suelta",0,4,"ao",-1,0,-1,0,186,186,"6896","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6897",7,"Lo escucho como a un perico\nembustero y parlanchín;\nsi es donde las dan las toman,\naquí estoy pa recibir.",135,2,-1,140,"Donde las dan las toman",0,4,"i",-1,0,-1,0,186,186,"6897","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6898",7,"Se me hace que es pistolero\nde esos que dan a la mala,\nvestido por su dinero,\npero que no vale nada.",135,2,-1,140,"Santanón",0,4,"aa",-1,0,-1,0,186,186,"6898","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6899",7,"Se me hace que es hablador,\nlo digo aunque no le cuadre;\nporque aquí llegó su padre,\nque se llama Santanón.",135,2,-1,140,"Santanón",5,4,"o",-1,0,-1,0,186,186,"6899","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6901",7,"En el cuartel del Sabino\ntengo mi amor verdadero.\nYo me voy por el camino\ny allá adelante te espero,\npara darte tu destino,\nquitarte lo embustero.",139,2,2,140,"Estrofa suelta",9,6,"eo",38,0,-1,0,186,186,"6901","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6902",7,"Esta noche salgo al puesto\ny a nadie le pido fiado;\naunque traigo poco resto,\npero no se me ha acabado;\nusted será buen cabrito,\npero le hace falta hilado.",135,2,-1,140,"Ya el águila real voló",9,6,"ao",14,0,-1,0,186,186,"6902","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6903",7,"Sobre la mesa te puse\nuna pera y un perón;\na mí me tuvo mi madre,\npero a ti, ¿quién, cabrón?",142,2,8,140,"Estrofa suelta",0,4,"o",31,0,-1,0,186,186,"6903","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6904",7,"El perro para morder\nprimero enseña los dientes.\nA mí me gusta perder\ncomo pierden los valientes;\nsi tú no vas a poder,\naviéntame a tus parientes.",135,2,-1,140,"El valedor; Estrofa suelta",9,6,"ee",252,0,-1,0,186,186,"6904","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6905",7,"Yo sé que me están buscando\ncon ansia desesperada;\ntambién yo me estoy quemando\npor conocer tu manada\ny verlos agonizando,\ncomiendo sangre empolvada.'",135,2,-1,140,"El patas blancas",9,6,"",-1,0,-1,0,187,187,"6905","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6906",7,"Dice aquí Manuel García,\narrecostado en la loma:\n“En este cuarenta y cuatro\ncarga la vida Carmona”.",135,2,-1,140,"Arbolito del camino",0,4,"oa",-1,0,-1,0,187,187,"6906","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6907",7,"¡Ah, qué noche tan oscura,\nbuena para las puñaladas!\nAquí anda el que me las debe,\ny esta noche me las pagas.",142,2,8,140,"Estrofa suelta",0,4,"aa",-1,0,-1,0,187,187,"6907","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6908",7,"En mi casa me dicen\nJorge Negrete,\nporque traigo pistolas\ny uso copete.",147,2,11,141,"La bamba",6,4,"ee",285,0,-1,0,190,190,"6908","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6909",7,"Estrellita reluciente,\ncomo un muchacho soltero;\na mí me gusta el ambiente,\nlo que me falta es dinero.",142,2,8,141,"La morena",1,4,"eo",38,0,-1,0,190,190,"6909","",0,"","","",11,0,0,[],"",""],["frenk_t3-n6910",7,"Me duele la cabeza,\nme duele el corazón,\npero más me duele\nestar de vacilón.",163,2,21,141,"Estrofa suelta",0,4,"o",31,0,-1,0,190,190,"6910","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6912",7,"Yo no soy de Veracruz,\nsoy de sus alrededores,\ny les pido a los valientes\nno me vayan a matar,\ny le pido a las panteras,\nmadre mía, tengan piedad.",135,2,-1,141,"El pájaro carpintero^",9,6,"a",-1,0,-1,0,190,190,"6912","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6913",7,"Yo soy Valentín Mancera,\nborrega nixtamalera,\nque a los primeros balazos\nse sube por la ladera.",135,2,-1,141,"Estrofa suelta",0,4,"ea",44,0,-1,0,190,190,"6913","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6914",7,"Aguilillas piernas gordas,\náguilas que andan volando;\nyo me mato con el muerto,\ny con las que están velando.",135,2,-1,141,"Aguilillas",0,4,"ao",33,0,-1,0,190,190,"6914","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6916",7,"Dicen que me han de quitar\nlas veredas que atravieso:\nno son tacos, ni enchiladas,\nni rebanadas de queso.",155,2,14,141,"Vengo a que me desengañes",0,4,"eo",48,0,-1,0,191,191,"6916","",0,"","","",12,0,0,[],"",""],["frenk_t3-n6917",7,"A orillas de una laguna\nsacó la cabeza un bagre,\ny gritó con valentía:\n“Vuelvan mejor a la tarde”.",147,2,11,141,"La chinita",0,4,"ae",-1,0,-1,0,191,191,"6917","",0,"","","",4,0,0,[],"",""],["frenk_t3-n6918",7,"Cuando me parió mi madre\nme parió en una banqueta;\ncuando llegó la partera\nyo me hacía la puñeta.",148,2,9,141,"El tarachi",0,4,"ea",-1,0,-1,0,191,191,"6918","",0,"","","",8,0,0,[],"",""],["frenk_t3-n6919",7,"El que quiera ser mi amigo\ntres cosas debe tener:\nbuena silla, buen dinero,\nbuenas viejas pa coger.",148,2,9,141,"Estrofa suelta",0,4,"e",20,0,-1,0,191,191,"6919","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6920",7,"¡Ay, Jesús, José y María!,\n¡ay, qué trompezón me di!\nPor andar toreando un toro\ny un chivo de los de aquí.",137,2,3,142,"Verdad de Dios",3,4,"i",23,0,-1,0,192,192,"6920","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6921",7,"No te metas a las honduras\nsi no sabes nadar,\nojos de lagarto prieto,\nbacinica de cagar.",142,2,8,142,"Estrofa suelta",0,4,"a",21,0,-1,0,192,192,"6921","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6922",7,"También sucede otra cosa\ncon los que son fanfarrones:\ncuando hablan en serio\nles pasa algo en sus calzones.",147,2,11,142,"La calandria",0,4,"oe",34,0,-1,0,192,192,"6922","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6923",7,"Tengo mi carro,\ntengo mi tren,\nchinga su madre\nyo ya sé quien.",147,2,11,142,"Tu madre es puta, tu padre es gacho",6,4,"e",242,0,-1,0,192,192,"6923","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6924",7,"Yo soy el gallito giro\nque vino de Guanajuato;\na mí me pelan tres chiles\ny el de mi compañero, cuatro.",142,2,8,142,"Estrofa suelta",3,4,"ao",-1,0,-1,0,192,192,"6924","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6925",7,"Ya te voy arrinconando\nal pie de la nopalera;\ncomo ya no sabes versos,\nempiezas con chingaderas.",142,2,8,142,"Estrofa suelta",0,4,"ea",-1,0,-1,0,192,192,"6925","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6926",7,"Chinga tu madre te digo,\nno te vayas a enojar;\ncontigo me limpio el culo\nacabando de cagar.",142,2,8,142,"Estrofa suelta",0,4,"a",21,0,-1,0,192,192,"6926","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6927",7,"Échenme ese pinolito\ncomido de los ratones,\nque yo le hago los mandados\ny me cojo los pilones.",135,2,-1,142,"Los papaquis",0,4,"oe",34,0,-1,0,192,192,"6927","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6928",7,"Me brinco la cama,\nme brinco el cajón,\nme cojo a tu hermana\ny a ti de pilón.",148,2,9,142,"Estrofa suelta",0,4,"o",31,0,-1,0,193,193,"6928","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6929",7,"Yo no soy poeta,\nni compositor de canciones,\npero sí me cojo a tu hermana\nsin bajarle los calzones.",148,2,9,142,"Estrofa suelta",0,4,"oe",34,0,-1,0,193,193,"6929","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6930",7,"Tú que te crees muy poeta\ny en el aire las compones,\nven a hacerme una puñeta,\ny lo que salga te lo comes.",135,2,-1,142,"Estrofa suelta",0,4,"oe",-1,0,-1,0,193,193,"6930","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6931",7,"Yo no soy un poeta,\nni tampoco me titulo;\nlo que traigo en la bragueta\nmuy bien te cabe en el culo.",148,2,9,142,"Estrofa suelta",1,4,"uo",535,0,-1,0,193,193,"6931","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6934",7,"Tu madre es puta, tu padre es gacho,\ntu hermano Nacho, puro cabrón,\ny tu hermanita la más chiquita\nya me ha pegado la purgación.",135,2,-1,142,"Tu madre es puta, tu padre es gacho",3,4,"o",31,0,-1,0,193,193,"6934","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6935",7,"Mi madre no me la mientes,\nmi madre ya está con Dios;\ntu madre, como era puta,\nel diablo se la cogió.",142,2,8,142,"Estrofa suelta",0,4,"o",-1,0,-1,0,193,193,"6935","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6936",7,"Ya salió la linda luna\nalumbrando aquella loma,\nya salió tu puta madre\nenseñando la paloma.",142,2,8,142,"Estrofa suelta",0,4,"oa",86,0,-1,0,193,193,"6936","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6937",7,"En el otro lado del mar\nhay chinches y camarones,\ny en el culo de tu madre\nhacen nido los ratones.",142,2,8,142,"Estrofa suelta",0,4,"oe",34,0,-1,0,193,193,"6937","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6938",7,"En la punta de aquel cerro\nviene bajando un toro mocho,\ny tu madre lo quería agarrar\ncon las barbas del bizcocho.",142,2,8,142,"Estrofa suelta",3,4,"oo",424,0,-1,0,194,194,"6938","",0,"","","",21,0,0,[],"",""],["frenk_t3-n6939",7,"En la puerta de mi casa\ntengo un palo de aguacate;\nyo no soy como tu madre,\nque tiene el perico cuate.",142,2,8,142,"Estrofa suelta",0,4,"ae",-1,0,-1,0,194,194,"6939","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6940",7,"En la puerta de mi casa\ntengo una mata de carrizo;\nyo no soy como tu madre,\nque tiene el perico liso.",142,2,8,142,"Estrofa suelta",0,4,"io",92,0,-1,0,194,194,"6940","",0,"","","",24,0,0,[],"",""],["frenk_t3-n6942",7,"En la punta de aquel cerro\ntengo una velita ardiendo,\npa metérsela a tu madre\nahorita que está cogiendo.",142,2,8,142,"Estrofa suelta",0,4,"eo",52,0,-1,0,194,194,"6942","",0,"","","",21,0,0,[],"",""],["frenk_t3-n6943",7,"A los quince años yo fui casado\ny abandonado a los dieciséis;\na los veinte años yo fui soldado\ny desertado a los veintitrés.",135,2,-1,143,"Las fuentes",3,4,"e",-1,0,-1,0,198,198,"6943","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6944",7,"Camino real de Colima,\nno me quisiera acordar\nlos trabajos que pasé\nen ese camino rfcal.",145,2,17,143,"Camino real de Colima; Estrofa suelta",0,4,"a",-1,0,-1,0,198,198,"6944","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6945",7,"Tomo la pluma en la mano\npara escribir y firmar\nlos trabajos que pasé\nen ese camino real.",145,2,17,143,"Camino real de Colima",0,4,"a",-1,0,-1,0,198,198,"6945","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6946",7,"Camino real de Colima,\nque tienes altos y bajos;\nen compañía de mi chata\nando pasando trabajos.",145,2,17,143,"Camino real de Colima; El gavilancillo’T",0,4,"ao",286,0,-1,0,198,198,"6946","",0,"","","",7,0,0,[],"",""],["frenk_t3-n6947",7,"Y al otro lado del mar\nvivo triste y sin consuelo,\nesperando al marinero,\nque me viniera a pasar.",158,2,22,143,"Y al otro lado del mar",5,4,"a",21,0,-1,0,198,198,"6947","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6948",7,"Ya el doctor está en la puerta,\nno me quiere recetar,\nun dolor que no me deja\nun momento resollar.",135,2,-1,143,"La tos",0,4,"a",21,0,-1,0,198,198,"6948","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6949",7,"¿Y dónde habías estado, rendegada suerte,\nque no habías venido por aquí pa verte?\nY hora no te vas, y hora aquí te estás,\nporque si te vas, me siento a llorar.",158,2,22,143,"La chicharra^",3,4,"a",-1,0,-1,0,198,198,"6949","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6950",7,"Ya me canso de sufrir\nesta vida tan penosa,\nArroyo de Buena Vista,\nCalzada de Santa Rosa.",135,2,-1,143,"El maracumbé",0,4,"oa",63,0,-1,0,199,199,"6950","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6951",7,"Pero esta vida que llevo\nya no lo puedo aguantar;\nen una de tantas veces,\n¡qué borlote voy a armar!",135,2,-1,143,"Antes y después",0,4,"a",21,0,-1,0,199,199,"6951","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6952",7,"Ya me estoy poniendo pardo,\ncomo el animal tejón;\nya me está tentando el diablo,\nya me dio un arrempujón.",135,2,-1,143,"Corrido de los destinos",0,4,"o",31,0,-1,0,199,199,"6952","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n6953",7,"Se rompió la estrella azul,\nla remendé con estambre;\nbien sabe el cielo piadoso\nque yo no lo hice por hambre,\ny aunque mi pecho esté herido,\nme revolcaré en mi sangre.",142,2,8,143,"Estrofa suelta",9,6,"ae",-1,0,-1,0,199,199,"6953","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6954",7,"De todo lo que me pasa\nsólo Dios es sabedor;\nme hallé metido en la gaza,\nperdiendo hasta mi color.",136,2,4,143,"Estrofa suelta",1,4,"o",72,0,-1,0,199,199,"6954","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6955",7,"Ya no llores, madrecita,\nyo sé que te hago sufrir;\ndéjame rifar mi suerte,\nvoy buscando un porvenir.",135,2,-1,143,"Mis querencias]",0,4,"i",157,0,-1,0,199,199,"6955","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6956",7,"Los ojitos de mi cara\n¿quién los compra?, que los vendo.\n¡Si seré yo desgraciada,\nque vendo lo que más quiero!",135,2,-1,143,"Estrofa suelta",0,4,"eo",-1,0,-1,0,199,199,"6956","",0,"","","",13,0,0,[],"",""],["frenk_t3-n6957",7,"Si este tiempo no se muda\no piedad no tiene el cielo,\nsólo la muerte podrá\ndar a mis males remedio.",135,2,-1,143,"Estrofa suelta",0,4,"eo",-1,0,-1,0,199,199,"6957","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6958",7,"San Pedro cayó y fue santo,\ny no se escandalizó;\n¿por qué de mí se habla tanto,\nno siendo el primero yo?\nSi un día hubiera algún quebranto,\nmi suerte lo permitió.",140,2,12,143,"La Malagueña mixteca",9,6,"o",2,0,-1,0,199,199,"6958","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6959",7,"Todas las penas me agobian,\nde triste, me ando alegrando,\ndonde voy seguido me odian:\nsólo iré de cuando en cuando.",145,2,17,143,"El agobiado",0,4,"ao",33,0,-1,0,199,199,"6959","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6960a",7,"Ya me voy, ya me retiro,\nporque aquí no tengo herencia;\nsi me voy, ¡qué dolor!,\nsi me quedo, ¡qué vergüenza!",142,2,8,143,"María, María’’",0,4,"ea",-1,0,-1,0,200,200,"6960a","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6961",7,"¡Ay, Dios!, ¿qué será de mí,\nque nadie me puede ver?\nAsí traigo mi destino,\nlo que no lo quiero creer.",142,2,8,143,"Estrofa suelta",0,4,"e",20,0,-1,0,200,200,"6961","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6962",7,"Hasta las piedras del campo\ntiran en contra de mí;\nsólo un amor que yo tengo\nse compadece de mí.",137,2,3,143,"El muchacho alegre; Estrofa suelta",0,4,"i",-1,0,-1,0,200,200,"6962","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6963",7,"Estuve muerto y tendido,\nsin saber quién me mató;\npues estoy bien convencido\nque hubo quien se condolió\nde mi suerte estando vivo.",139,2,2,143,"Estrofa suelta",7,5,"io",-1,0,-1,0,200,200,"6963","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6964",7,"Ariles, muy bien, ardes,\ny ariles, papel volando;\nmi padre me dio la vida,\ny éstos me la están quitando.",136,2,4,143,"El Balajú",0,4,"ao",33,0,-1,0,200,200,"6964","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6965",7,"Yo quiero ser el palo\npara romper la piñata,\nmas no puedo ser el palo\nporque yo soy la piñata.",147,2,11,143,"Estrofa suelta",1,4,"aa",-1,0,-1,0,200,200,"6965","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6966",7,"Y pájaro de la mata\nde la verbena,\nque la luna me ataranta (cielito lindo)\ny el sol me quema.",142,2,8,143,"El pájaro cú",3,4,"ea",-1,0,-1,0,200,200,"6966","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6967",7,"Yo no sé por qué razón\nme hicieron andar de codos;\nparece que no nací\npor donde nacimos todos.",142,2,8,143,"Estrofa suelta",0,4,"oo",418,0,-1,0,200,200,"6967","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6968",7,"Me fui a la guerra, perdí una pata,\nde un chingadazo que me tocó;\nla madre patria, que es muy ingrata,\ncon pura reata me lo pagó.",147,2,11,143,"Tu madre es puta, tu padre es gacho",3,4,"o",2,0,-1,0,200,200,"6968","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6969",7,"Vengo de la serranía,\nde los campos de Guerrero;\n“¿Qué suerte será la mía?,\niah, qué viejo tan rastrero!”\nle diré como decía\nel pájaro manzanero.",136,2,4,143,"El pájaro manzanero",9,6,"eo",38,0,-1,0,201,201,"6969","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6970",7,"Amanece, que amanece,\nya mi gallito cantó (¡ay!, mi vida).\nSeñores, ¿qué les parece\nla suerte que me tocó (mi vida)?\nSe me hace que ya no crece:\nchaparrita se quedó (mi vida).",138,2,6,143,"La madrugada",9,6,"ia",2,0,-1,0,201,201,"6970","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6971",7,"¡Ay, qué suerte tan chaparra!,\n¿hasta cuándo crecerá?\nY éstos son los tristes versos\nque te canta Trinidad.",145,2,17,143,"Estrofa suelta",0,4,"a",-1,0,-1,0,201,201,"6971","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6972",7,"Padres que tienen hijas\n¡qué mal las tratan!\nYo, que no tengo nada,\nDios me las mata.",146,2,7,143,"Pajarillo silguero",6,4,"aa",-1,0,-1,0,201,201,"6972","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6973",7,"Se tupió la veredita\npor donde iba el ameyal,\ny de purita sequía\nse marchitó el tulipán,\nque a diario me daba flores\npa el altar de Cuicatlán.",135,2,-1,143,"La tortolita",9,6,"a",147,0,-1,0,201,201,"6973","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6974",7,"Ya ese capulín se heló,\nya su sombra no cobija,\nya ese nopal no da tunas,\nni en él el pájaro chifla.",135,2,-1,143,"Estrofa suelta, Ya los pájaros cantan",0,4,"ia",-1,0,-1,0,201,201,"6974","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6975",7,"Aquí está la piedra lisa\nen donde yo me resbalé;\naquí no hay quien me levante,\nni quien la mano me dé.",142,2,8,143,"Las mañanitas",0,4,"e",77,0,-1,0,201,201,"6975","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6976",7,"La vida a mí no me quiere,\nla vida a mí me desprecia,\nla vida me está matando,\nme está matando la vida.",135,2,-1,143,"Qué padre es la vida",5,4,"ia",-1,0,-1,0,201,201,"6976","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6977",7,"Décimas de un arrancado,\nque, por su mucha pobreza,\nla suerte, con gran vileza,\ncruelmente lo ha maltratado.",135,2,-1,143,"Estrofa suelta",11,4,"ao",14,0,-1,0,201,201,"6977","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6978",7,"Pobre del que pobre nace;\nlo digo por mi pobreza,\nque si me tapo las piernas,\nme descubro la cabeza.",142,2,8,143,"La guacamaya’*",0,4,"ea",-1,0,-1,0,202,202,"6978","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6979",7,"[Ayl, pobre estoy, desventura,\nque hasta se pierde la fe;\nse me hace fea la figura\nque decirle.........................\neste son de Tamazula.",136,2,4,143,"La huazanga",7,5,"ua",-1,0,-1,0,202,202,"6979","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6980",7,"Cuando me vine de Puebla\nme vine en carro de roble,\nsus ruedas eran de cobre,\ntodas en silencio van;\nqué malo es ser uno pobre:\nni los buenos días le dan.",135,2,-1,143,"El pájaro carpintero",9,6,"a",147,0,-1,0,202,202,"6980","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6981",7,"Soy como el viento que corre\nalrededor de este mundo;\nando entre muchos placeres,\npero no estoy en ninguno.",138,2,6,143,"Estrofa suelta",0,4,"uo",-1,0,-1,0,202,202,"6981","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6982",7,"Aprendan, flores, de mí,\nlo que va de ayer a hoy:\nayer maravilla fui\ny ahora ni sombra soy.",142,2,8,143,"Estrofa suelta",1,4,"o",112,0,-1,0,202,202,"6982","",0,"","","",5,0,0,[],"",""],["frenk_t3-n6983",7,"¡Ay de mí!, Llorona,\nLlorona de ayer y hoy;\nayer maravilla fui (Llorona)\ny ahora ni sombra soy.",135,2,-1,143,"La Llorona; La Lloroncita; La Juanita",3,4,"o",112,0,-1,0,202,202,"6983","",0,"","","",35,0,0,[],"",""],["frenk_t3-n6984",7,"Ya no soy lo que antes era,\nni lo que solía ser:\nsoy un cuadro de tristeza\narrimado a la pared",153,2,5,143,"Estrofa suelta",0,4,"e",-1,0,-1,0,202,202,"6984","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6985a",7,"Una vez quise volar\nsin tener alas ninguna:\nel viento me fue llevando\na orillas de una laguna.",142,2,8,143,"Estrofa suelta",0,4,"ua",56,0,-1,0,202,202,"6985a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6985b",7,"Una vez quise volar\nsin tener alas ninguna,\nhaciéndome tobogán;\na orillas de una laguna\nayer me puse a llorar,\nte dije: “Ven, fortuna”.",135,2,-1,143,"Al pasar por los laureles",9,6,"ua",56,0,-1,0,203,203,"6985b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n6986",7,"¡Qué largas las horas son\nen el reloj de mi afán,\ny qué poco a poco dan\nalivio a mi corazón!",162,2,27,143,"Estrofa suelta",11,4,"o",31,0,-1,0,203,203,"6986","",0,"andina_t1","","",7,0,0,[],"",""],["frenk_t3-n6987",7,"Hubo un tiempo que fui muerto,\ny mi esperanza también;\nde negro manto cubierto,\nme revivió no sé quién:\nquedó mi sepulcro abierto.",141,2,1,143,"Estrofa suelta",7,5,"eo",88,0,-1,0,203,203,"6987","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6988",7,"Tengo un grande sufrimiento\npor lo que mi alma desea;\npara expresar lo que siento,\nfalta idioma, falta idea,\nfalta espacio y pensamiento.",135,2,-1,143,"Estrofa suelta, El gusto",7,5,"eo",94,0,-1,0,203,203,"6988","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6989",7,"Soy hijo de padecer,\nprimo hermano del tormento;\npara mí no hay ningún placer,\ny para mí el sufrimiento:\nmi vida triste ha de ser.",141,2,1,143,"El ausente; La Rosita; Soy hijo de padecer; Estrofa suelta",7,5,"e",20,0,-1,0,203,203,"6989","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6990",7,"Cuando Dios me dio la vida\nme la dio sin escrituras;\nasí, cuando él me la pida\nse la daré sin factura,\ny al cabo ya va perdida,\nderecho a la sepoltura.",139,2,2,143,"El huerfanito",9,6,"ua",17,0,-1,0,203,203,"6990","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6991",7,"Fastidiado de viviré,\npor mi suerte infortunada,\nmaldizco hasta mi insistir,\nporque mi tumba olvidada\nde hierba se ha de cubriré.",141,2,1,143,"El gusto",7,5,"e",77,0,-1,0,203,203,"6991","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6992",7,"¿Qué favor le debo al sol\npor haberme calentado,\nsi de chico fui a la escuela,\nsi de grande fui soldado,\nsi de casado, cabrón,\ny de muerto, condenado?",142,2,8,143,"Estrofa suelta",9,6,"ao",14,0,-1,0,203,203,"6992","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6993",7,"Por el barrio de Cochoapa,\nandan los perros aullando.\nNo sólo el que tiene vacas\ncarga su soga arrastrando;\nyo también cargo la mía\ny también la ando arrastrando.",135,2,-1,143,"La Malagueña curreña",9,6,"ao",-1,0,-1,0,204,204,"6993","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6994",7,"Yo soy el judío errante,\ny mi destino es andar;\nbusco en el mundo una sombra\npara poder descansar.",142,2,8,143,"Estrofa suelta",0,4,"a",21,0,-1,0,204,204,"6994","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6995",7,"De mi vida tan atroz\nse oyen los tristes sollozos;\nni a quién volver yo mis ojos,\nsino solamente a Dios.",135,2,-1,143,"Estrofa suelta",5,4,"o",87,0,-1,0,204,204,"6995","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6996",7,"¿Qué hacer si nos mantiene\ndestino adverso,\nsolos, solos en medio\ndel universo?",137,2,3,143,"La despedida",6,4,"eo",-1,0,-1,0,204,204,"6996","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6997a",7,"Corazón apasionado,\ndisimula tu tristeza;\nel que nace desgraciado\ndesde la cuna comienza\na vivir martirizado.",139,2,2,143,"La leva; El huerfanito; La pasión",7,5,"ao",14,0,-1,0,204,204,"6997a","",0,"","","",3,0,0,[],"",""],["frenk_t3-n6998",7,"Yo soy desdichado (¡caramba!)\ndesde que nací\ny a nadie le pasan (¡caramba!)\nlas cosas que a mí.",135,2,-1,143,"El caramba",3,4,"i",23,0,-1,0,204,204,"6998","",0,"","","",1,0,0,[],"",""],["frenk_t3-n6999",7,"Triste, desgraciado, fui\ndesde mi pequeña cuna;\nal momento comprendí\nque era negra mi fortuna:\ndime, Dios, por qué nací.",136,2,4,143,"El huerfanito",7,5,"i",23,0,-1,0,204,204,"6999","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7000",7,"Ya mi esperanza perdí,\npara mí no hay ilusión;\nen grandes penas me vi,\nrodeado de la traición:\ndime, Dios, por qué nací.\nSi fue para castigarme,\nyo sólo un favor te pido,\ny si para perdonarme,\n¿para qué vine a este mundo,\nsi pronto habían de llamarme?",135,2,-1,143,"‘‘La leva",18,10,"ae",35,0,-1,0,205,205,"7000","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7001",7,"¡Válgame Dios de los cielos!,\n¡qué desgraciado nací!,\nque hasta el agua de la pila\nse ha negado para mí.",135,2,-1,143,"Válgame Dios de los cielos; Estrofa suelta",0,4,"i",23,0,-1,0,205,205,"7001","",0,"","","",33,0,0,[],"",""],["frenk_t3-n7002",7,"Soy un pobre sin fortuna,\nque Dios puso en un camino;\nno tengo riqueza alguna,\nporque así fue mi destino:\nhuérfano desde mi cuna.",139,2,2,143,"El huerfanito",7,5,"ua",56,0,-1,0,205,205,"7002","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7003",7,"Nací en la Hana, Domingo [me] llamo,\ncomo azabache negro nací,\ncon una suerte tan desgraciada,\nque yo a mis padres no conocí.",158,2,22,144,"Nací en la Hana",3,4,"i",23,0,-1,0,206,206,"7003","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7004",7,"Soy huerfanito,\n¡ay, qué dolor!,\nNo tengo padre ni madre,\nsoy huerfanito yo.",137,2,3,144,"El huerfanito",3,4,"o",-1,0,-1,0,206,206,"7004","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7005",7,"Yo soy hijo de la malva,\ny de la malva nací,\nno tengo padre ni madre,\nni quien se duela de mí.",135,2,-1,144,"Las mañanitas",0,4,"i",23,0,-1,0,206,206,"7005","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7006",7,"Soy nacido de la nada\ny con la nada me crié,\nno tengo padre ni madre,\nni quien en mí tenga fe.",137,2,3,144,"El muchacho alegre",0,4,"e",77,0,-1,0,206,206,"7006","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7007a",7,"No tengo padre ni madre,\nni quien se duela de mí;\nsólo la cama en que duermo\nse compadeció de mí.",137,2,3,144,"El muchacho alegre",0,4,"i",-1,0,-1,0,206,206,"7007a","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7008",7,"Como huérfano me quejo,\npasando mi vida atroz;\ncomo ya voy para viejo,\nno me ampara más que Dios;\nmemorias al mundo dejo.",139,2,2,144,"El huerfanito",7,5,"eo",-1,0,-1,0,206,206,"7008","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7009",7,"Como huérfano me quejo,\npasando mi vida atroz;\nhoy te explico con mi voz:\nno tengo madre ni padre,\ny mi amparo es sólo Dios.",139,2,2,144,"Estrofa suelta",7,5,"o",87,0,-1,0,207,207,"7009","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7010",7,"¡Ay, qué muerte tan veloz,\nque a mis padres te llevaste!\nSin amparo, más que Dios,\na padecer me dejaste\nesta vida tan atroz.",141,2,1,144,"El huerfanito",7,5,"o",280,0,-1,0,207,207,"7010","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7011",7,"Como huérfano me quejo,\npensando en mi porvenir;\nal mismo tiempo reflejo,\nsiento que voy a morir,\nrecuerdo al mundo dejo.",135,2,-1,144,"El huerfanito; Estrofa suelta",7,5,"eo",264,0,-1,0,207,207,"7011","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7012",7,"Oíd los tristes lamentos\nque dirige un huerfanito:\nen sus grandes sufrimientos\nal cielo levanta el grito.",135,2,-1,144,"Tristes lamentos de un huerfanito",1,4,"io",119,0,-1,0,207,207,"7012","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7013",7,"Dichoso el que tiene madre,\npues a mí se me murió;\nle pido a Dios que la guarde,\nen compañía de mi padre.",147,2,11,144,"El huerfanito",5,4,"ae",-1,0,-1,0,207,207,"7013","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7014",7,"Dichoso el que tiene madre,\nporque a mí se me murió,\nno tengo más que a mi padre,\nque con trabajos me crió;\ncontigo mi pecho se abre\nal ver lo que me pasó.",136,2,4,144,"El huerfanito",9,6,"o",2,0,-1,0,207,207,"7014","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7015",7,"Cuando yo tenía mi madre\nestaba muy contentito,\ny ahora que Dios me la quita\nme he quedado huerfanito,\ntan solito con mi padre.",136,2,4,144,"El huerfanito",7,5,"ae",166,0,-1,0,207,207,"7015","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7016",7,"Para el huérfano no hay sol,\ntodos quieren ser el padre;\nprimos, parientes y hermanos\nse avergüenzan de mi sangre,\ny a cada paso que doy\nson recuerdos de mi madre.",135,2,-1,144,"El huerfanito",9,6,"ae",-1,0,-1,0,207,207,"7016","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7017",7,"Para el huérfano ya no hay sol,\nya no hay sol, ya no hay aire;\nlas palabras que me distes\nno las lloro por cobarde,\nlas lloro porque me acuerdo\nde la ausencia de mi madre.",137,2,3,144,"El huerfanito",9,6,"ae",-1,0,-1,0,208,208,"7017","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7018",7,"¡Qué triste vida la mía,\nsin esperanza y sin nadie,\nllorando mis tristes penas\ny recordando a mi madre!",135,2,-1,144,"Palomas que andan volando",0,4,"ae",-1,0,-1,0,208,208,"7018","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7019",7,"A los montes me retiro\na llorar mi sentimiento,\nque mi madre falleció,\ny no puedo hallar consuelo.",153,2,5,144,"Estrofa suelta",0,4,"eo",-1,0,-1,0,208,208,"7019","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7020",7,"Al morir la madre mía\nfui al cementerio solito,\nhalló el sepulcro mi guía;\nhe llorado, huerfanito,\nsobre la lápida fría.",139,2,2,144,"El huerfanito",7,5,"ia",0,0,-1,0,208,208,"7020","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7021",7,"Como la pluma en el aire,\nme encuentro solo en el mundo;\nsin mi padre y sin mi madre,\nando errante y vagabundo.\nCon sentimiento profundo\nlloro por aquel amor,\npero Dios, Nuestro Señor,\ndispuso que así se hiciera;\nmadre mía, ruega por tu hijo,\nmientras se encuentre en la tierra.",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"ea",-1,0,-1,0,208,208,"7021","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7024",7,"Madre mía, ¿por qué te fuiste\ny huérfano me has dejado?\nMírame cuán solo y triste,\nen el mundo abandonado.",135,2,-1,144,"Tristes lamentos de un huerfanito",1,4,"ao",14,0,-1,0,209,209,"7024","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7025",7,"Pobrecita madre mía,\ncon qué lástima murió;\nen un sueño muy profundo\ndormidita se quedó;\npero desdichado yo,\nque quedé solo en el mundo.",137,2,3,144,"El huerfanito",9,6,"uo",179,0,-1,0,209,209,"7025","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7026a",7,"¡Ay, qué muerte tan feroz,\nque a mi madre te llevaste!\nA padecer me dejaste\nen este mundo traidor;\nni tu bendición me echaste.",136,2,4,144,"El huerfanito",7,5,"ae",212,0,-1,0,209,209,"7026a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7027",7,"Hoy mi pecho se taladra\ncon las penas del dolor;\nhoy, madre, madre querida,\ntu hijo llora por tu amor;\ntú te fuiste y me dejaste\nen este mundo traidor.",135,2,-1,144,"El huerfanito",9,6,"o",72,0,-1,0,209,209,"7027","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7028",7,"Unas veces fui soldado,\ny otras, en prisión;\nhoy me encuentro abandonado,\nhoy me encuentro sin mi madre,\ny a cada paso que doy,\nhoy que reflexiono es tarde.",162,2,27,144,"El huerfanito",9,6,"ae",-1,0,-1,0,209,209,"7028","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7029",7,"¡Ay!, si mi madre viviera,\nno anduviera así penando;\nyo me quejaría con ella\nla vida que estoy pasando,\nde cantina por cantina,\ncomo las piedras, rodando.",135,2,-1,144,"Voy a tirarme a los vicios",9,6,"ao",33,0,-1,0,209,209,"7029","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7030",7,"Los hijos que estén presentes\npongan bastante atención\nen estos tristes lamentos\nque dirijo en la ocasión.\nMadre de mi corazón,\nme dejaste padecer;\npídele al supremo Ser\ncalme mi pena y dolor,\npara que viva en el mundo,\nrogando por ti al Creador.",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"o",72,0,-1,0,209,209,"7030","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7031",7,"Ya te doy mi despedida,\nmadre de mi corazón;\ndesde el cielo donde estás\nmándame tu bendición.",135,2,-1,144,"Corrido del hijo pródigo",0,4,"o",31,0,-1,0,210,210,"7031","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7032",7,"Ya se acabó mi tesoro,\nse murió mi madre amada;\nestas páginas que lloro\nno me sirven para nada.",135,2,-1,144,"Estrofa suelta",1,4,"aa",49,0,-1,0,210,210,"7032","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7033",7,"Aunque el pecho se ataladre\ncon el dolor más atroz,\nhe comprendido, aunque tarde:\njuro que después de Dios\nno hay amor como el de madre.",136,2,4,144,"El huerfanito’",7,5,"ae",-1,0,-1,0,210,210,"7033","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7034a",7,"No hay amor como el de madre\nen la vida transitoria;\nque la tierra le sea leve\ny Dios la lleve a la gloria.",135,2,-1,144,"Estrofa suelta",0,4,"oa",126,0,-1,0,210,210,"7034a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7035",7,"Mi madre era mi consuelo,\nera toda mi alegría,\nera mi encanto y mi anhelo.\n¿Adonde estás madre mía?\n¿Cuándo se llegará el día\nde vemos juntos los dos\nen la presencia de Dios,\npara calmar estas penas,\nque cual pesadas cadenas\nme dan sufrimiento atroz?",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"o",280,0,-1,0,210,210,"7035","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7036",7,"La madre es en este mundo\nel faro de la existencia\ndel hijo, que con paciencia\nla ama con amor profundo,\ncon cariño sin segundo.\nLa madre cuida por su hijo;\nle ve en algún precipicio,\nse expone a perder la vida;\npor eso siempre repito:\n¿dónde estás, madre querida?",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"ia",37,0,-1,0,210,210,"7036","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7037",7,"La madre es el gran tesoro\nque existe aquí en este suelo:\nmucho más fino que el oro,\ndespués de Dios en el cielo.\nEl hijo con grande anhelo\ndebe apreciar esa joya;\nque Dios la tenga en su gloria\na mi madre tan querida,\nmientras tu hijo aquí en la tiena\nllora tu veloz partida.",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"ia",37,0,-1,0,211,211,"7037","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7038",7,"Si la mamacita mía\nsupiera que ando penando,\ncogiera su lintemita\ny me anduviera buscando.",142,2,8,144,"Chilena de Jamiltepec",0,4,"ao",33,0,-1,0,211,211,"7038","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7039",7,"Dios creó una recompensa\npara el cariño más grande:\nnadie se la disputó\nal cariño de mi madre.",135,2,-1,144,"Estrofa suelta",0,4,"ae",-1,0,-1,0,211,211,"7039","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7041",7,"Soy huérfano siempre triste,\npaso mi vida entre abrojos;\n¿dónde estás, madre? Te fuiste,\nquerida luz de mis ojos;\nvarios consejos me diste\nque me causaban enojos.",139,2,2,144,"El huerfanito",9,6,"oo",99,0,-1,0,211,211,"7041","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7042",7,"Cuando mi madre vivía\nme daba muchos consejos;\ncon cariño me decía:\n“No me hagas tantos desprecios”.\nHoy recuerdo los bosquejos\nque ella me hacía de su vida;\nhoy, madre, madre querida,\ntu hijo llora amargo llanto;\nte fuiste y me dejaste\nen tan horrible quebranto.",135,2,-1,144,"Tristes lamentos de un huerfanito",18,10,"ao",30,0,-1,0,211,211,"7042","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7043",7,"Cuando yo me emborrachaba\nmi madre me iba a buscar;\ndondequiera que me hallaba\ntriste se ponía a llorar,\ny si algo me pasaba\nella me iba a consolar.",135,2,-1,144,"El huerfanito",9,6,"a",21,0,-1,0,211,211,"7043","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7044",7,"Pobre de mi madre querida,\n¡cuántos consejos me daba!\nTodos los días de mi vida\nen un rinconcito estaba,\nllorando muy afligida.",139,2,2,144,"El huerfanito",7,5,"ia",37,0,-1,0,212,212,"7044","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7045",7,"Pobrecita de mi madre,\nvarios consejos me dio;\ncon lágrimas en sus ojos\nsus bendiciones me echó.",135,2,-1,144,"Mis querencias",0,4,"o",2,0,-1,0,212,212,"7045","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7046",7,"Los consejos de mi madre\nyo los tengo muy presentes;\ny hoy que me encuentro abandonado,\nhoy que me encuentro atribulado,\ny a cada paso que doy\nsoy huérfano desgraciado.",162,2,27,144,"El huerfanito",9,6,"ao",14,0,-1,0,212,212,"7046","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7047",7,"Cuando me salía a pasear\nmi madre me decía:\n“No te salgas, vida mía,\nno te vayas a tardar”.",136,2,4,144,"El huerfanito",3,4,"a",21,0,-1,0,212,212,"7047","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7048",7,"Recuerdo que me decía,\ncuando se ponía a llorar:\n“Amor de la vida mía,\nno te vayas a tardar,\nque yo temo que algún día\nno me vayas a encontrar”.",135,2,-1,144,"El huerfanito",9,6,"a",21,0,-1,0,212,212,"7048","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7049",7,"Todos me dicen el feo,\nporque sin gracia he nacido,\nsi Dios me hubiera formado\ncon un pincel más pulido,\nno fuera prieto ni feo,\nni fuera mal parecido.",135,2,-1,145,"El feo",9,6,"io",101,0,-1,0,216,216,"7049","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7050",7,"De verme tan arruinado,\nme fui para Tuxtepec,\ny al poco de haber llegado,\nuna suerte me encontré,\ny no la he aprovechado,\nporque la desperdicié.",142,2,8,145,"Zapateado",9,6,"e",77,0,-1,0,216,216,"7050","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7051",7,"Cuando yo tenía a mis padres\ntodititos me querían;\nhora que estoy solitito,\nya me regaña mi tía:\n¡pescozones que me ha dado!,\n¡como a ella no le dolía!",138,2,6,145,"El huerfanito",9,6,"ia",0,0,-1,0,216,216,"7051","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7052",7,"Un día puse un espinel,\na ver si podía pescar;\nme decía una mujer,\nqueriéndome criticar:\n“No te apures por comer,\nque hambre no te ha de faltar”.",142,2,8,145,"Zapateado",9,6,"a",21,0,-1,0,216,216,"7052","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7053",7,"No hallo mujer que me convenga,\nni sombrero que me venga,\nni caballo que me sostenga,\nni fonda que me mantenga.",135,2,-1,145,"Estrofa suelta",0,4,"ea",407,0,-1,0,216,216,"7053","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7054",7,"Cuando yo tenía dinero\nme llamaban don Colás;\nhoy que no tengo nada\nme llaman Colás no más.",142,2,8,145,"El Colás; Estrofa suelta",0,4,"a",51,0,-1,0,216,216,"7054","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7055",7,"No lo digo por usted,\nlo digo por mi pobreza:\ncuando yo vendía sombreros\nningún cabrón tenía cabeza.",142,2,8,145,"Estrofa suelta",3,4,"ea",108,0,-1,0,216,216,"7055","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7056",7,"Ya no puedo con la carga,\nDon Pendejo me ha montado,\ncomo está muy fundillón\nya me llevó la fregada.",135,2,-1,145,"La mulita",5,4,"aa",-1,0,-1,0,216,216,"7056","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7057",7,"Ya la máquina se va,\n¡ay, amigos, qué dolor!,\ny el maquinista le da\nagua y bastante vapor.",135,2,-1,146,"Las campanitas",1,4,"o",72,0,-1,0,220,220,"7057","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7058",7,"Uu, iuu, iuu, tan, tan, tan,\nahora sí, ya se va el tren;\nadiós, todos mis amigos,\n¿cuándo los volveré a ver?",135,2,-1,146,"Las campanitas",3,4,"e",-1,0,-1,0,220,220,"7058","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7059",7,"Ya son las tres campanadas,\nahora sí ya va a salir;\nadiós, todos mis amigos,\nya se va el ferrocarril.",135,2,-1,146,"Las campanitas",0,4,"i",-1,0,-1,0,220,220,"7059","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7060",7,"Oigan, señores, el tren,\n¡qué lejos me va llevando!\nOigan los silbidos que echa\ncuando ya va caminando.",135,2,-1,146,"El tren",0,4,"ao",33,0,-1,0,220,220,"7060","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7061",7,"Oigan y oigan, señores,\noigan el tren caminar,\nel que se lleva a los hombres\na las orillas del mar.",135,2,-1,146,"El tren",0,4,"a",21,0,-1,0,220,220,"7061","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7062",7,"Voy a dar la despedida\ndel son del “toro rabón”:\nadiós, mi tierra querida,\nGuerrero, bella región,\nde la patria mexicana\nel más hermoso rincón.",146,2,7,146,"El toro rabón",9,6,"o",31,0,-1,0,220,220,"7062","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7063",7,"Por toda la Costa Chica\nse baila “El toro rabón”;\nadiós, mi patria querida,\nOaxaca tan bella región.",142,2,8,146,"El toro rabón",3,4,"o",31,0,-1,0,220,220,"7063","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7064",7,"Adiós, Guanajuato hermoso,\ncasas de tejamanil;\nadiós, pueblito de Rocha,\nquédate con Dios, Marfil.",161,2,15,146,"Estrofa suelta",0,4,"i",290,0,-1,0,220,220,"7064","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7065",7,"Esto que digo es muy cierto,\nnadie lo puede negar;\nadiós, mi Tuxpan, Jalisco,\nmi Tezatila y su mezcal.",135,2,-1,146,"Tuxpan",3,4,"a",-1,0,-1,0,221,221,"7065","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7066",7,"Adiós, querido Museo,\nadiós, Universidad,\nya me voy para el Paseo\na llorar mi soledad,\npues desterrado me veo.",135,2,-1,146,"Estrofa suelta",7,5,"eo",66,0,-1,0,221,221,"7066","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7067",7,"Adiós, Pahuatlán querido,\nya me despido de ti;\nno me echarás en olvido,\nsi tú me quieres a mí;\nsiempre seré yo tu amigo.",141,2,1,146,"Pahuatlán",7,5,"io",-1,0,-1,0,221,221,"7067","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7068",7,"Adiós, Tambuco y La Aguada,\nPlaya Larga y Manzanillo;\nadiós, muchachas del puerto,\nadiós, plaza del castillo.",135,2,-1,146,"Estrofa suelta",0,4,"io",228,0,-1,0,221,221,"7068","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7069",7,"Tierra suriana,\nyo te bendigo;\ncon mi guitarra en la mano\nya me despido.",142,2,8,146,"Cacahuatepec",6,4,"io",-1,0,-1,0,221,221,"7069","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7070",7,"Adiós, San Diego querido,\nya me voy a retirar,\ny les digo a las muchachas:\n“No me vayan a olvidar”.",135,2,-1,146,"Corrido de San Diego de la Unión",0,4,"a",21,0,-1,0,221,221,"7070","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7071",7,"Ausente me voy mañana,\npor la vía de Colima,\nadiós, parientes y hermanos,\néchenme la tierra encima.",145,2,17,146,"El durazno",0,4,"ia",302,0,-1,0,221,221,"7071","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7072",7,"Adiós, adiós, compañeros,\nya me voy muy afligido,\nporque me voy y los dejo;\npero a todos por parejo\nmis recuerdos dejaré.",146,2,7,146,"Despedimiento de un militar ascendido",7,5,"e",-1,0,-1,0,221,221,"7072","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7073",7,"¡Vuela, vuela, vuela,\nvuela sin cesar!\n¡Adiós, corriente del agua,\narroyo del pedregal!",136,2,4,146,"La guacamaya",0,4,"a",-1,0,-1,0,221,221,"7073","",0,"","","",17,0,0,[],"",""],["frenk_t3-n7074",7,"Adiós, torrente del agua,\narroyo del pedregal;\nque el encargo que te digo\nno se te vaya a olvidar;\nsi acaso se te olvida,\nte lo volveré a acordar.",142,2,8,146,"La morena’T",9,6,"a",21,0,-1,0,221,221,"7074","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7075",7,"¡Ay, qué suerte fue la mía!,\nque tengo que abandonar\nla tierra donde he nacido,\npara ir lejos a sufrir.",135,2,-1,146,"La canción del enganchado",5,4,"i",-1,0,-1,0,222,222,"7075","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7076",7,"Ya me despido de mis viejos cardenales,\npor esos montes y tierras de labor;\nya les canté a toditos mis parciales:\naquí les dejo la pena y el dolor.",137,2,3,146,"Las aves",3,4,"o",72,0,-1,0,222,222,"7076","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7077",7,"Adiós, palacio alumbrado,\nhasta que te vuelva a ver,\nme separo de tu lado;\ncon el tiempo has de saber\ndónde estoy avecindado\ny el fin que voy a tener.",135,2,-1,146,"La morena",9,6,"e",20,0,-1,0,222,222,"7077","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7078",7,"Adiós, corral de Barranco,\ncon tus jardines de flores;\nDios sabe quién volverá\na gozar de tus favores.",144,2,10,146,"Estrofa suelta",0,4,"oe",5,0,-1,0,222,222,"7078","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7079",7,"Virgencita de Zapopan,\nque me has visto padecer,\ndéjame llorar de pena,\npor si no te vuelvo a ver.",135,2,-1,146,"Virgencita de Zapopan",0,4,"e",20,0,-1,0,222,222,"7079","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7080",7,"Adiós, mi Guadalajara,\nya me voy, ¡qué le he de hacer!\nLa alegría de tu mariachi,\nmi San Pedro Tlaquepaque,\nya no volveré a ver;\nVirgencita de Zapopan,\ncuídame pa no caer.",135,2,-1,146,"Virgencita de Zapopan",4,7,"e",20,0,-1,0,222,222,"7080","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7082",7,"Adiós, barranca\nque fue mi nido,\ntengo presente\nque no te olvido.",145,2,17,146,"Mi tierra",6,4,"io",101,0,-1,0,222,222,"7082","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7083",7,"Adiós, barrio de Las Piedras,\nadiós mi barrio querido;\npor tus inquietas palmeras,\nbarrio chico, no te olvido.",142,2,8,146,"Estrofa suelta",0,4,"io",101,0,-1,0,222,222,"7083","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7084",7,"Adiós, Canelas, Durango,\nya me despido de ti;\nte juro que no te olvido,\npueblo donde yo nací.",135,2,-1,146,"A Canelas",0,4,"i",23,0,-1,0,222,222,"7084","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7085",7,"Mi voz se está despidiendo,\nlinda tierra tropical;\nte llevo en el pensamiento\ny en este nuevo cantar.",135,2,-1,146,"Ometepec",0,4,"a",-1,0,-1,0,223,223,"7085","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7086",7,"¡Ay, mi Querétaro lindo!,\nte llevo en el corazón;\nle voy cantando a tu cielo,\ntu cielo querido llenito de sol.",135,2,-1,146,"El queretano",3,4,"o",-1,0,-1,0,223,223,"7086","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7087",7,"¡Ay, Huaxolotitlán!,\npueblito de ensoñación;\ntienes fama por doquiera;\npor tu mujer que es sincera,\nte llevo en el corazón.",142,2,8,146,"Corrido de Huaxolotitlán",7,5,"o",31,0,-1,0,223,223,"7087","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7088",7,"Pueblo de Santiago del Río,\nnunca te puedo olvidar,\ndonde hay muchachas bonitas\ny limas, pues, sin contar.",142,2,8,146,"Santiago del Río",0,4,"a",21,0,-1,0,223,223,"7088","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7089",7,"Bellos lugares,\nbellas mujeres,\naunque me muera,\nno te olvido, Villa Juárez.",142,2,8,146,"Cacahuatepec",3,4,"ae",606,0,-1,0,223,223,"7089","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7091",7,"Pueblo querido,\npor lejos que ande,\nnunca te olvido.\nLindo pueblito,\n¡cómo me acuerdo\nde mi amorcito!",136,2,4,146,"Estampa jarocha",9,6,"io",119,0,-1,0,223,223,"7091","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7092",7,"El sol tempranito sale\npor ’l horizonte perdido;\naunque el firmamento escale,\ncanto muy entristecido:\npueblo de Tamazunchale,\nlejos, pero no te olvido.",138,2,6,146,"El caimán",9,6,"io",101,0,-1,0,223,223,"7092","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7093",7,"Tierra que no olvidaré,\na la que adoro y amé,\naunque lejos yo me encuentre,\nsiempre la recordaré.",142,2,8,146,"Chiquitita te vas criando",0,4,"e",77,0,-1,0,223,223,"7093","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7094",7,"Jamiltepec,\nte lo decía,\nque solamente muerto\nte olvidaría.",135,2,-1,146,"‘‘Chilena de Jamiltepec",6,4,"ia",0,0,-1,0,224,224,"7094","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7096",7,"Yo le canto con amor\na mi tierra tropical;\n¡qué bonito es Veracruz!,\nnunca lo podré olvidar.",136,2,4,146,"‘‘Canto a Veracruz",0,4,"a",-1,0,-1,0,224,224,"7096","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7097",7,"¡Ay, ay, Veracruz hermoso!,\nnunca te podré olvidar,\npor ser tus playas lejanas\nun encanto sin igual.",136,2,4,146,"Qué bello es Veracruz",0,4,"a",-1,0,-1,0,224,224,"7097","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7098",7,"Pinotepa Nacional,\ntierra que yo ya no piso;\n¡cómo pusieron los Valles\nese puerto de Minizo!",142,2,8,146,"Estrofa suelta",0,4,"io",95,0,-1,0,224,224,"7098","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7099",7,"Que me entierren en la siena\nal pie de los magueyales,\ny que me cubra la tierra,\nque es cuna de hombres cabales.",135,2,-1,146,"México lindo",0,4,"ae",26,0,-1,0,224,224,"7099","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7100",7,"Bendita tierra querida,\nno tiene comparación;\nquisiera tenerte cerca\ny darte mi corazón.",145,2,17,146,"Tuxpan",0,4,"o",31,0,-1,0,224,224,"7100","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7101",7,"¡Ay, Cananea, quién pudiera\nirse de aquí pa mi tierra!\nEsta vida ya no es vida,\nla tristeza me aniquila.",135,2,-1,146,"La canción del enganchado",5,4,"ia",-1,0,-1,0,224,224,"7101","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7102",7,"Ánimas de junto al río,\nque habitan en los jarales,\nsáquenme de Juchitlán\ny llévenme a Los Corrales.",135,2,-1,146,"Estrofa suelta",0,4,"ae",26,0,-1,0,224,224,"7102","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7103",7,"Por el cerro de la Cruz\nel sol ya se deja ver,\ny en el agua de tus presas\nla luna va a aparecer,\ny a tus cañaverales\nmuy pronto quiero volver.",135,2,-1,146,"Bonito Tecalitlán",9,6,"e",20,0,-1,0,224,224,"7103","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7104",7,"Ando ausente de Jalisco,\nhace tiempo que lo estoy;\nando lejos de mi tierra,\nsi Dios quiere, pronto voy.",145,2,17,146,"Mi tierra",0,4,"o",112,0,-1,0,225,225,"7104","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7105",7,"Acapulco ¡quién te viera!,\n¡quién por tus calles paseara!,\n¡quién a tu capilla fuera\na misa de madrugada!",135,2,-1,146,"Estrofa suelta",0,4,"aa",-1,0,-1,0,225,225,"7105","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7106",7,"¡Acapulco, alas quién tuviera\ny hasta tu vergel bajara!\n¡Quién tus calles paseara!,\n¡quién a ti feliz volviera\npara no dejarte ya!",135,2,-1,146,"La costeñita",7,5,"a",-1,0,-1,0,225,225,"7106","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7107",7,"Sonora querida,\ntierra consentida\nde dicha y placer;\nextraño tu suelo\ny cifro mi anhelo\nen volverte a ver.",148,2,9,146,"Sonora querida",9,6,"e",20,0,-1,0,225,225,"7107","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7108",7,"Cuando salí de mi tierra\nya me quería devolver;\n¡ay, qué amargas son las horas\npa el que tiene que volver!",135,2,-1,146,"La embarcación",0,4,"e",20,0,-1,0,225,225,"7108","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7109",7,"Si Acapulco me destierra,\nSan Marcos dice que no:\nque yo vaya y que yo vuelva,\npero desterrado, no.",135,2,-1,146,"La Sanmarqueña; Estrofa suelta",0,4,"o",-1,0,-1,0,225,225,"7109","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7110",7,"¡Ay, Soledad, Soledad!,\n¡ay, Soledad de mi tierra!\nCuando vengo por aquí\nhasta quedarme quisiera.",136,2,4,146,"El cascabel",0,4,"ea",-1,0,-1,0,225,225,"7110","",0,"","","",18,0,0,[],"",""],["frenk_t3-n7111",7,"Bonito Guadalajara:\n¡quién estuviera en el puente,\ncon su chinita en los brazos,\nviendo pasar a la gente!",136,2,4,146,"El Ahualulco; El parreño",0,4,"ee",15,0,-1,0,225,225,"7111","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7112",7,"Bonito Guadalajara,\n¡quién estuviera otra vez,\ncon su prietita en los brazos\ny un vasito de jerez!",135,2,-1,146,"La potranca; El Ahualulco",0,4,"e",150,0,-1,0,225,225,"7112","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7113",7,"Bonito Guadalajara,\n¡quién estuviera en San Pedro,\ntomando mucho tequila\nen compañía de mi negro!",135,2,-1,146,"El parreño",0,4,"eo",-1,0,-1,0,226,226,"7113","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7114",7,"Bonito es Guadalajara,\n¡quién estuviera en Pachuca,\ncon su chinita del brazo,\ntomando para Toluca!",136,2,4,146,"El Ahualulco",0,4,"ua",607,0,-1,0,226,226,"7114","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7115",7,"Bonito Guadalajara,\n¡quién estuviera en Europa,\ncon su chinita en los brazos\ny viendo pasar la tropa!",136,2,4,146,"El Ahualulco",0,4,"oa",608,0,-1,0,226,226,"7115","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7116",7,"Orizaba, ¡quién te viera\ninaugurando el Marqués,\ncon su chinita del brazo,\nborrachito de jerez!",136,2,4,146,"El Ahualulco",0,4,"e",150,0,-1,0,226,226,"7116","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7117",7,"Quisiera subir al cielo\nhasta las Siete Cabrillas,\npara divisar mi tierra,\nPinotepa y sus orillas.",142,2,8,146,"Indita del alma",0,4,"ia",294,0,-1,0,226,226,"7117","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7118",7,"Me subí a los altos ceños\na devisar para el plan;\nparece que estoy oyendo\nesas tarimas de Autlán.",145,2,17,146,"El pasacalle; El Cihualteco",0,4,"a",147,0,-1,0,226,226,"7118","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7119",7,"Nogales, frontera\npor donde quisiera\na mi suelo ver;\nFrontera querida,\nyo diera mi vida\npor volverte a ver.",148,2,9,146,"Sonora querida",9,6,"e",-1,0,-1,0,226,226,"7119","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7121",7,"Barrio lind[o] de las flores,\nbarrio que yo tanto amaba;\npero se llegó la ocasión\nque hasta los perros me echaban.",142,2,8,146,"Estrofa suelta",0,4,"aa",-1,0,-1,0,226,226,"7121","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7122",7,"Todos se admiran de mí\nporque sufro en tiena ajena:\nTehuantepec es mi tierra,\ndonde se da la azucena.",142,2,8,146,"La Zandunga",0,4,"ea",-1,0,-1,0,226,226,"7122","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7123",7,"Soy un errabundo, que ando\nlejos de la tierra mía,\nlas costumbres estudiando\nentre penas y alegrías,\ntriste pero no llorando.",136,2,4,146,"‘‘El gusto; La Malagueña",7,5,"ao",33,0,-1,0,227,227,"7123","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7124",7,"Campanitas del rosario,\n¿cuándo se repicarán?\nCada que me acuerdo de ellas\nganas de llorar me dan.",147,2,11,146,"Las campanitas",0,4,"a",147,0,-1,0,227,227,"7124","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7125",7,"No soporto este dolor;\nque aquí en mi mente se aferra\ncon el cariño mayor:\nson recuerdos de la tierra\nde este viejo trovador.",139,2,2,146,"El huerfanito",7,5,"o",72,0,-1,0,227,227,"7125","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7126",7,"Yo me vine de mi tierra,\njunto a la orilla del mar,\na refugiarme a la selva\npa que me coma un jaguar.",135,2,-1,146,"El tiburón",0,4,"a",21,0,-1,0,227,227,"7126","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7127",7,"Dame razón de mi rancho,\nde todos los de La orilla:\nNana Tula y Nana Pancha,\n¿qué hace tu hermana Toribia?",144,2,10,146,"Anselmo’T",0,4,"ia",-1,0,-1,0,227,227,"7127","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7128",7,"Ahora que me encuentro lejos\nde la tierra en que nací,\n¡ay de mis padres queridos!,\n¡cuánto han sufrido por mí!",135,2,-1,146,"Mis querencias",0,4,"i",23,0,-1,0,227,227,"7128","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7129",7,"Ayer tarde recibí carta\nque mis padres me mandaron,\nen que llorando me dicen\ny suplican que me vaya.",135,2,-1,146,"Canción del Interior",5,4,"aa",-1,0,-1,0,227,227,"7129","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7130",7,"Yo no sé qué tiene Pancho,\nque toda la noche llora:\nestá lejos de su rancho\ny no puede llegar ahora.",145,2,17,146,"El Pancho",1,4,"oa",107,0,-1,0,227,227,"7130","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7131",7,"Devisaba pa su tierra,\ny era un purito llorar:\n“Adiós, todos mis amigos,\nlos del barrio del Nopal”.",135,2,-1,146,"Aguilillas",0,4,"a",-1,0,-1,0,227,227,"7131","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7132",7,"A los tres días de camino\nya no podías caminar:\nvolteabas para tu tierra,\ny era llorar y llorar.",163,2,21,146,"La chinita; Estrofa suelta",0,4,"a",21,0,-1,0,227,227,"7132","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7133",7,"Campo chiquito\nde San Joaquinito,\ncampo mediano\nde San Cayetano,\ncampo mayor\nde San Salvador.",135,2,-1,147,"Estrofa suelta",9,6,"o",72,0,-1,0,228,228,"7133","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7134",7,"México tiró las cartas,\nTampico las barajó,\nVeracruz echó el albur,\ny Acapulco lo ganó.",135,2,-1,147,"La Sanmarqueña",0,4,"o",2,0,-1,0,228,228,"7134","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7135",7,"De Acapulco a La Sabana\nno se lleva más que un día;\nlucero de la mañana,\nresplandor de mediodía.",142,2,8,147,"La garza",1,4,"ia",0,0,-1,0,228,228,"7135","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7136",7,"Una, dos, tres, cuatro, cinco,\ncinco, cuatro, tres, dos, una;\nsiete y siete son catorce,\ntres por siete veintiuna;\nen Veracruz sale el sol\ny en Acapulco la luna.",136,2,4,147,"Estrofa suelta",9,6,"ua",56,0,-1,0,228,228,"7136","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7137",7,"Ahora sí ya están unidos\nAlvarado y Tlacotalpan\ny sólo están divididos\npor el río del Papaloapan.",136,2,4,147,"El jarabe loco; El querreque; Estrofa suelta",3,4,"aa",-1,0,-1,0,228,228,"7137","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7138",7,"Tancítaro queda en lo alto\ny Acahuato en la ladera\ny Apatzingán en lo plano,\npor la mesma cordillera.",137,2,3,147,"El relámpago",0,4,"ea",44,0,-1,0,228,228,"7138","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7139",7,"Palmero, sube a la palma,\nallá te divertirás,\nmirando la Peña Blanca\nque se mira de San Blas.",135,2,-1,147,"El palmero",0,4,"a",51,0,-1,0,228,228,"7139","",0,"","","",16,0,0,[],"",""],["frenk_t3-n7140",7,"Me subí al cerro más alto\na devisar los planes;\nno pude devisar más\nque el cerro de Villanes.",148,2,9,147,"Estrofa suelta",0,4,"ae",444,0,-1,0,229,229,"7140","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7141",7,"Desde la sierra se ven\nlas olas del mar azul;\nse ve la Sierra Nevada,\nlas haciendas de Terul.",135,2,-1,147,"Desde la sierra se ven",0,4,"u",545,0,-1,0,229,229,"7141","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7142",7,"Del Cerro del Cimatorio\nse divisa todo el plan:\nde La Cruz hasta Santa Ana,\nSan Roque y San Sebastián.",135,2,-1,147,"El queretanito",0,4,"a",147,0,-1,0,229,229,"7142","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7143",7,"Del cerro de la Silleta\nse devisa Huehuetlán;\n¡qué bonita la Huasteca!,\nnunca se me olvidará;\nse devisa la Huasteca,\ncomo todos lo dirán.",138,2,6,147,"qué bonita la Huastecal, nunca se me olvidará; se devisa la Huasteca,",9,6,"a",-1,0,-1,0,229,229,"7143","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7144",7,"De Tampico adelante\nluego se mira\ncarretera del Mante (cielito lindo),\npor Altamira;\ny sus ramales,\nEstación Manuel (cielito lindo),\nVilla González.",139,2,2,147,"Cielito lindo",4,7,"ae",609,0,-1,0,229,229,"7144","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7145",7,"Pachuca y Ixmiquilpan —por Zimapán.\nla Encarnación.\nSan Nicolás, Jacala —Pinar, La Cuesta\ny La Misión;\ntambién Pachuca -por Pisaflores,\nChapulhuacán, Santana\ny Tamazunchale —de mis amores.",138,2,6,147,"Cielito lindo",4,7,"oe",5,0,-1,0,229,229,"7145","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7146",7,"Me vine de Pachuca —por Ixmiquilpan\ny Zimapán;\nya pasé por Tlaxcala —y Pisaflores,\nvine a Tamán;\ny a Pisaflores,\nde ahí La Misión (cielito lindo)\nde mis amores.",139,2,2,147,"Cielito lindo",4,7,"oe",5,0,-1,0,229,229,"7146","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7147",7,"Tamazunchale y Axtla —Aquismón y Valles,\ntierras divinas,\nque se canta huapango (cielito lindo),\nla potosina;\ntierras hermanas,\nla huasteca hidalguense (cielito lindo),\nveracruzana.",139,2,2,147,"Cielito lindo",4,7,"aa",-1,0,-1,0,229,229,"7147","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7148",7,"Tierra de los aztecas (cielito lindo),\nque Dios nos hizo:\nson estas tres huastecas (cielito lindo)\nun paraíso;\nson tres hermanas:\nla huasteca hidalguense —la potosina\ny veracruzana.",141,2,1,147,"Cielito lindo",4,7,"aa",-1,0,-1,0,230,230,"7148","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7149",7,"De todos los poblados\nXilitla quiero,\nTamazunchale y Axtla (cielito lindo),\nValles primero;\ny es cosa cierta,\nporque ella es la puerta (cielito lindo)\nde la Huasteca.",147,2,11,147,"Cielito lindo",4,7,"ea",-1,0,-1,0,230,230,"7149","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7150",7,"Las Tres Huastecas\ntiene lindos paisajes:.\nLa Cascada de Míelos (cielito lindo),\npor Barrio Valles,\nrío tan bonito,\nque va paso a Tamuín (cielito lindo),\nrumbo a Tampico.",139,2,2,147,"Cielito lindo",4,7,"io",-1,0,-1,0,230,230,"7150","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7151",7,"Huasteca veracruzana,\ntienes mucho que admirar\neste pueblo de Ozuloama,\nTantoyuca y Macozal\nque gozan de mucha fama,\nPánuco, El Higo y Tempoal.",138,2,6,147,"El gusto",9,6,"a",1,0,-1,0,230,230,"7151","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7152",7,"Jamiltepec es querido;\nHuazolotitlán, adorado;\nOmetepec, consentido;\nPinotepa, el apreciado.",142,2,8,147,"Estrofa suelta",1,4,"ao",14,0,-1,0,230,230,"7152","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7153",7,"En el nombre de Jesús,\ncomo quiera me convenzo,\npues ya Dios me dio su luz;\nes bonito San Lorenzo,\nmi Pánuco y Veracruz.",139,2,2,147,"El San Lorenzo",7,5,"u",109,0,-1,0,230,230,"7153","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7154",7,"El estado de Guerrero\ntiene dos costas preciosas:\nCosta Chica, Costa Grande,\nque cantó Fernando Rosas.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"oa",61,0,-1,0,230,230,"7154","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7155",7,"De toditos los estados\nMéxico fue lo primero,\nvino luego Sinaloa,\nhermanos por ello fueron.",149,2,20,147,"¡Viva mi Sinaloa!",0,4,"eo",-1,0,-1,0,230,230,"7155","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7156",7,"Tierra de la Santa Cruz,\nmi choza tlaliscoyana;\norgullo eres, Veracruz,\nde la nación mexicana.",135,2,-1,147,"La iguana",1,4,"aa",4,0,-1,0,231,231,"7156","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7157",7,"De Alvarado y de Las Lomas\nllega gente de a montón,\npues dicen que Tlacotalpan\nes tierra de promisión.",136,2,4,147,"Estrofa suelta",0,4,"o",31,0,-1,0,231,231,"7157","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7158",7,"-¿Qué dices, chata, nos vamos\no nos quedamos aquí?\n—Vámonos para Oaxaca:\nmás bonito es por allá.",142,2,8,147,"Yo soy aquel oaxaqueño",5,4,"a",-1,0,-1,0,231,231,"7158","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7159",7,"Al pasar por Santa Rita\nen compañía de mis amigos;\ny si discuto una cosa ahorita,\nya que todos nos escuchan:\n“¡Qué bonita es Poza Rica!”",136,2,4,147,"La Rosita",7,5,"ia",-1,0,-1,0,231,231,"7159","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7160",7,"Aquí cualquier hombre vale\nporque reina la alegría;\n“Es lo mismo”, dijo el chale,\n“pa mí no hay categoría:\n¡qué viva Tamazunchale!”",138,2,6,147,"El sombrero; La leva",7,5,"ae",202,0,-1,0,231,231,"7160","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7161",7,"Ya con ésta me despido,\nadiós, tranvía del nogal,\npues se ha sacado la palma\nPinotepa Nacional.",135,2,-1,147,"Al pasar por los laureles",0,4,"a",1,0,-1,0,231,231,"7161","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7162",7,"Muchos recuerdos yo tengo\nde mi tierra sin igual;\ncasi puedo asegurar\nque como Tuxpan, ninguno.",145,2,17,147,"Tuxpan",5,4,"uo",-1,0,-1,0,231,231,"7162","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7163",7,"Pues saludo a la reunión\nsin ofender a ninguno,\ncontando uno por uno,\nno hay pueblo como Platón.",136,2,4,147,"Los chiles verdes",11,4,"o",31,0,-1,0,231,231,"7163","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7164",7,"Tierra donde hay mucha luz,\ny que como ella no hay dos;\nal cantar un avestruz\ngritaba con alta voz:\n“¡Qué bonito es Veracruz!,\nlugar como ése no hay dos”.",136,2,4,147,"Puerto sin igual",9,6,"o",87,0,-1,0,231,231,"7164","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7165",7,"Todos los días pido a Dios\nque cuide nuestra bandera;\nse lo digo en alta voz,\nque, aunque le pese a cualquiera,\ncomo Veracruz no hay dos\nen la República entera.",136,2,4,147,"El siquisirí; El jarabe loco",9,6,"ea",44,0,-1,0,231,231,"7165","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7166",7,"Y aunque me falla la voz,\nme animo con mi jarana;\ndigo versos, hasta dos,\ny con expresión más cristiana;\ncomo Veracruz no hay dos\nde la nación mexicana.",138,2,6,147,"La huazanga",9,6,"aa",4,0,-1,0,232,232,"7166","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7167",7,"Soy de esa tierra de luz,\ntan bella como no hay dos;\nes mi lindo Veracruz,\ntierra bendita de Dios.",136,2,4,147,"Canto a Veracruz",1,4,"o",87,0,-1,0,232,232,"7167","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7168",7,"Soy de puro Veracruz,\ntierra jarocha y bravia;\nno hay hombre como el de aquí,\nni tierra como la mía;\nDios la vino a bendecir,\nporque se lo merecía.",135,2,-1,147,"De puro Veracruz",9,6,"ia",0,0,-1,0,232,232,"7168","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7169",7,"La luna con su reflejo\nen el mar pintó un renglón,\ny con todo su destello\niluminó mi región;\n“Sólo Veracruz es bello”,\ndijo el sabio Salomón.",136,2,4,147,"El siquisirí; El jarocho",9,6,"o",31,0,-1,0,232,232,"7169","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7170",7,"Ya lo dijo el Santo Papa,\ny lo dijo voz en cuello:\n“¡Chingue su madre Jalapa,\nsólo Veracruz es bello!”",147,2,11,147,"Estrofa suelta",1,4,"eo",12,0,-1,0,232,232,"7170","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7171",7,"Mi verso yo lo declaro,\nmi palabra lo relata;\ny del puerto de Alvarado,\nla ruta de Tlacotalpan;\nsólo Veracruz es bello\ncon su capital Jalapa.",136,2,4,147,"El siquisirí",9,6,"aa",-1,0,-1,0,232,232,"7171","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7172",7,"Tierra de los aztecas,\nque Dios nos hizo,\nforman las tres huastecas (cielito lindo)\ny un paraíso.",136,2,4,147,"Cielito lindo",3,4,"io",92,0,-1,0,232,232,"7172","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7173",7,"Esas Huastecas\nyo no sé lo que tendrán:\nel que una vez las conoce\nregresa y se queda allá.",138,2,6,147,"Las tres Huastecas",3,4,"a",-1,0,-1,0,232,232,"7173","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7174",7,"No te dejo de querer,\nHuasteca, eres muy hermosa,\nporque tú siempre has de ser\nde todas la más preciosa,\nen tu hermoso atardecer.",139,2,2,147,"Atardecer huasteco",7,5,"e",20,0,-1,0,232,232,"7174","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7175",7,"La Huasteca potosina\ntiene flores de a montón,\nsierras llenas de neblina\ny laderas de ilusión.",138,2,6,147,"Las tres Huastecas",1,4,"o",31,0,-1,0,233,233,"7175","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7177",7,"La Huasteca es tierra santa,\ndonde Dios formó su nido;\naquí es donde el tordo canta\nsu prolongado silbido,\nque a todo el mundo le encanta.",138,2,6,147,"El caimán",7,5,"aa",148,0,-1,0,233,233,"7177","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7178",7,"Como lo dijo el Papa de Roma\ny lo dijo con voz en cuello:\n“¡Viva, señores, Jalisco!,\npero Chapulhuacán es más bello”.",139,2,2,147,"Estrofa suelta",3,4,"eo",12,0,-1,0,233,233,"7178","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7179",7,"“Como México no hay dos”,\ndijo el pato en la laguna,\ny el gavilán le contestó:\n“Como Mérida, ninguna”.",152,2,13,147,"Estrofa suelta",3,4,"ua",56,0,-1,0,233,233,"7179","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7180",7,"¡Ay, qué bonito!\nle dije a mi corazón:\nparece que ando en Jalisco,\npaseándome en el vagón.",135,2,-1,147,"El cuervo’T",3,4,"o",31,0,-1,0,233,233,"7180","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7181",7,"Tienen fama sus caballos,\nque los charros jinetean,\ny sus chinas son luceros\nde belleza sin igual.",135,2,-1,147,"Jalisco nunca pierde",5,4,"a",-1,0,-1,0,233,233,"7181","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7182a",7,"Tamazunchale engreidor,\nque a todos los ilusiona,\nyo quisiera ser pintor\npa pintarte una paloma\ndentro de tu corazón.",138,2,6,147,"El sacamandú",7,5,"o",-1,0,-1,0,233,233,"7182a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7182b",7,"Tamazunchale engreidor,\nque a todos los ilusiona,\nyo quisiera ser pintor\npa pintarte una paloma\ndentro de tu corazón,\nen lugar de mi persona.",138,2,6,147,"El sombrero; El huerfanito",9,6,"oa",-1,0,-1,0,234,234,"7182b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7183",7,"Hoy te traigo, mi Huejutla,\nun ramo de flores blancas,\nque las he encontrado en mi rancho,\nen mitad de las barrancas.",139,2,2,147,"Estrofa suelta",0,4,"aa",443,0,-1,0,234,234,"7183","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7184",7,"Estas calles de Atoyac\nyo las tengo que empedrar;\nlas piedras han de ser de oro\ny la arenita de cristal.",142,2,8,147,"La garza",0,4,"a",-1,0,-1,0,234,234,"7184","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7185",7,"Atitalaquia, lindo pueblito,\nel más taurino de la región,\na sus mujeres y a mis amigos\nyo les doy mi corazón.",138,2,6,147,"Estrofa suelta",3,4,"o",31,0,-1,0,234,234,"7185","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7186",7,"Voy a empezar a cantar,\nseñores, pido atención,\npara poder saludar\ny brindar mi corazón\nal pueblo de Pahuatlán.",141,2,1,147,"Pahuatlán",7,5,"a",-1,0,-1,0,234,234,"7186","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7187",7,"Le han cantado a Veracruz,\na Jalisco y Tamaulipas;\ncon gusto le canto a Hidalgo,\nque tiene cosas bonitas.",138,2,6,147,"El hidalguense",0,4,"ia",-1,0,-1,0,234,234,"7187","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7188",7,"Yo le canto a Veracruz\ny a mi San Luis Potosí,\na mis paisanos del Norte\ny también a los de aquí.",135,2,-1,147,"El as de los huapangos",0,4,"i",23,0,-1,0,234,234,"7188","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7189",7,"Aquí estoy, Tenochtitlán,\nhoy vengo con muchas ganas,\npara ofrecerte jaranas\nde mi tierra, Yucatán.",152,2,13,147,"Estrofa suelta",11,4,"a",147,0,-1,0,234,234,"7189","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7190",7,"Voy a cantarle a Zipatla,\na Tamán y Cortazar,\na las Tres Marías las santas,\na la sierra y su faisán;\nalegres las aves cantan\ncuando les silba el faisán.",139,2,2,147,"San Simón",9,6,"a",-1,0,-1,0,234,234,"7190","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7191",7,"Yo le canto a la Huasteca,\nbonita tierra mía;\ntambién le canto a Platón,\ndonde nace la luz del día.",136,2,4,147,"El sacamandú",0,4,"ia",0,0,-1,0,234,234,"7191","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7192",7,"Tierra donde yo nací,\nmi tierra aquí, en la Huasteca;\npor eso le canto así;\nes buena porque es prieta,\npuro San Luis Potosí.",138,2,6,147,"El fandanguito",7,5,"i",23,0,-1,0,235,235,"7192","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7193",7,"Con gusto voy a cantarles\nel falsete de mi tierra:\nes mi lindo Tamaulipas,\nde donde yo voy a hablarles\ny decir cosas bonitas.",141,2,1,147,"El falsete de mi tierra",7,5,"ia",-1,0,-1,0,235,235,"7193","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7194",7,"Con esta humilde jarana\nte quisiera agasajar;\ntu expresión es tan indiana,\ncon que quiero hacer notar:\nhuasteca veracruzana,\ntú me diste tus cantos",139,2,2,147,"El gusto",9,6,"ao",-1,0,-1,0,235,235,"7194","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7195",7,"Le cantaré a Veracruz\nun huapango retozón,\nallí donde vi la luz\ny donde tengo a mi amor,\ntierra de la Santa Cruz,\ndonde la Virgen naciera:",136,2,4,147,"que viva mi Veracruz, la tierra más bullanguera! [Canto a Veracruz",9,6,"ea",-1,0,-1,0,235,235,"7195","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7196",7,"Ya canté con toda el alma\npa todito Veracruz,\nmi tierra linda, adorada,\ndonde vi la primera luz.",135,2,-1,147,"De puro Veracruz",0,4,"u",109,0,-1,0,235,235,"7196","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7197",7,"Tierra de luz,\nmi Veracruz;\ncon mi jarana\ncanto a mi tierra\nveracruzana.",136,2,4,147,"Puerto sin igual",7,5,"aa",4,0,-1,0,235,235,"7197","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7198",7,"A mi pueblo Alto Lucero\nle canto este huapanguito;\npor lo mucho que lo quiero\nse lo compuse bonito,\nporque es un pueblo sincero,\ny allí tengo mi amorcito.",136,2,4,147,"Estampa jarocha",9,6,"io",119,0,-1,0,235,235,"7198","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7199",7,"De Veracruz a Alvarado,\nhermana de esta región,\ny con “El siquisirí” estamos;\nquiero en la gran devoción\ncantarte con mi guitarra",136,2,4,147,"El siquisirí",7,5,"aa",-1,0,-1,0,235,235,"7199","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7201",7,"Ometepec, tierra mía,\nmi voz te viene a cantar;\ncon el alma de costeño\nyo te quiero enamorar;\ntus palmeras altaneras\nte hacen bello y tropical.",135,2,-1,147,"Ometepec",9,6,"a",-1,0,-1,0,236,236,"7201","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7202",7,"Señores, pido silencio,\nque aquí les voy a cantar\ncanciones que son recuerdos\nde Sinaloa y su capital.",135,2,-1,147,"¡Arriba Sinaloa!",3,4,"a",-1,0,-1,0,236,236,"7202","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7203",7,"Pinotepa, que es la reina\nde toda esta región,\nserá la perla elegida\npara cantar mi canción.",135,2,-1,147,"Chiquitita te vas criando’",0,4,"o",31,0,-1,0,236,236,"7203","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7204",7,"Ya me voy a despedir,\ncantando se los diré;\nya se va el indio suriano,\ncantándole a Ometepec.",146,2,7,147,"El indio suriano",0,4,"e",-1,0,-1,0,236,236,"7204","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7205",7,"México es mi madre patria,\ndonde nací mexicano;\néchame tu bendición\ncon tu poderosa mano.",135,2,-1,147,"Despedida de un norteño",0,4,"ao",81,0,-1,0,236,236,"7205","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7206",7,"Y allá en el bosque de las Indias\ndonde resplandece el sol,\ndonde crecen las palmeras,\nallí, morena, nací yo.",144,2,10,147,"La Malagueña",3,4,"o",-1,0,-1,0,236,236,"7206","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7207",7,"Juquila, mi patria amada,\ntierra donde yo nací,\nno te pongas colorada,\néchame la culpa a mí.",142,2,8,147,"La Sanmarqueña",1,4,"i",23,0,-1,0,236,236,"7207","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7208",7,"Camino real de Colima\ndicen que yo no lo sé:\n¡cómo no lo he de saber,\nsi en el camino me crié!",145,2,17,147,"Camino real de Colima",0,4,"e",-1,0,-1,0,236,236,"7208","",0,"frenk_t4","","",7,0,0,[],"",""],["frenk_t3-n7209",7,"Camino real de Colima\ndicen que yo no lo sé;\nen compañía de mi chata\nde rodillas lo andaré.",145,2,17,147,"Camino real de Colima",0,4,"e",77,0,-1,0,236,236,"7209","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7210",7,"La chilena va a empezar,\ncantando yo les diré\nque en el rincón de Guerrero\nse encuentra mi Ometepec.",146,2,7,147,"Ometepec",0,4,"e",-1,0,-1,0,236,236,"7210","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7211",7,"Camino de Santa Rosa,\nla sierra de Guanajuato,\nahí no más traslomita,\nse ve Dolores Hidalgo,\ny allí me quedo, paisano:\nallí es mi pueblo adorado.",135,2,-1,147,"Camino de Guanajuato",9,6,"ao",-1,0,-1,0,237,237,"7211","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7212",7,"Cuando toco mi jarana\nganas me dan de llorar;\ncomo todos lo dirán,\nyo soy de Xilitla, hermano,\nnunca lo puedo negar.",138,2,6,147,"El sombrero",7,5,"a",-1,0,-1,0,237,237,"7212","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7213",7,"Hora sí voy a cantar,\nse lo digo desde horita;\ntambién me voy a excitar,\npues yo, yo soy de Xilitla,\nTamazunchale es mi lugar.",138,2,6,147,"La pasión",7,5,"a",21,0,-1,0,237,237,"7213","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7214",7,"Soy de puro Michoacán,\nde su hermosa capital;\nno más a pasear me vine\ndel pueblo del Peribán.",135,2,-1,147,"La palomita",0,4,"a",-1,0,-1,0,237,237,"7214","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7215",7,"Tipití, tipití (¡Canelo!),\ntipití, tipití;\nyo no soy de aquí (¡Canelo!),\nsoy de San Andrés.",136,2,4,147,"El Canelo",5,4,"e",-1,0,-1,0,237,237,"7215","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7216",7,"Soy de tierra donde se ama,\ntierra donde vi la luz;\nsoy del cantón de Ozuluama,\nestado de Veracruz,\nRepública Mexicana.",147,2,11,147,"El pijul; Quiéreme, chiquita",7,5,"aa",-1,0,-1,0,237,237,"7216","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7217",7,"De aquellos mejores paños\nyo corté lo mejorcito;\ny van pasando los años;\nyo soy puro Tepetzintla,\ndonde se ama sin engaños.",136,2,4,147,"El tepetzintleco",7,5,"ao",518,0,-1,0,237,237,"7217","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7218",7,"Soy de Guadalajara,\ncharrita de nombradía,\ncon mis enaguas de lana,\nmis medias de Andalucía.",135,2,-1,147,"La chaparrita",0,4,"ia",0,0,-1,0,237,237,"7218","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7220",7,"Yo soy charro de Jalisco,\nde esta tierra tapatía,\nque despierta con canciones\ny se duerme con amor.",135,2,-1,147,"Jalisco nunca pierde",5,4,"o",-1,0,-1,0,238,238,"7220","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7221",7,"Soy de la peña más alta,.\ndonde da primero el sol;\nsoy costeño, no lo niego,\npuritito corazón.",142,2,8,147,"Estrofa suelta",0,4,"o",-1,0,-1,0,238,238,"7221","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7222",7,"Soy de purito Chihuahua,\nmi semblante lo dirá,\nuso sombrero tejano\npor pura formalidad,\ny cuando tiendo la mano\nla doy con sinceridad.",135,2,-1,147,"El caporal",9,6,"a",16,0,-1,0,238,238,"7222","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7223",7,"Soy de un pueblo de valor,\ncomo lo es el de Alvarado;\ndicen que soy cumplidor,\npero que soy muy pelado:\nla culpa no tengo yo\nde nacer en Alvarado.",135,2,-1,147,"De puro Veracruz",9,6,"ao",14,0,-1,0,238,238,"7223","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7224",7,"Soy nacido en Tierra Colorada,\ndonde todos se nombran de tú,\ny por eso no me importa nada;\nasí somos todos los del sur.",146,2,7,147,"Tierra Colorada",3,4,"u",-1,0,-1,0,238,238,"7224","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7225",7,"Yo no soy de Monterrey,\nsoy de sus alrededores,\ny pedimos a los gringos\nque nos guisen los frijoles.",137,2,3,147,"La chinita. Estrofa suelta",0,4,"oe",-1,0,-1,0,238,238,"7225","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7226",7,"Viva el Distrito de Minas,\narriba mi pueblo entero,\nhasta las cumbres y cimas,\nel estado de Guerrero.",146,2,7,147,"Coyuca de Catalán",0,4,"eo",38,0,-1,0,238,238,"7226","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7227",7,"¡Viva mi tierra caliente,\nCoyuca de Catalán!\nLo diré cantando siempre,\ncon orgullo y con afán.",146,2,7,147,"Coyuca de Catalán",0,4,"a",147,0,-1,0,238,238,"7227","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7229",7,"¡Qué lindo es León, Guanajuato,\npor ser el rey del Bajío!\nPor eso grito orgulloso:\n“Ese terruño es el mío”.",135,2,-1,147,"Mi tierra es León, Guanajuato",0,4,"io",3,0,-1,0,239,239,"7229","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7230",7,"San Pedro Atoyac,\nSan Luis Potosí,\n¡qué bonita tierra,\ndonde yo nací!",142,2,8,147,"La Malagueña curreña",0,4,"i",23,0,-1,0,239,239,"7230","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7231",7,"Bonito Hermosillo,\nchiquito y sencillo,\nen donde nací;\ntus noches aquellas,\ntan claras y bellas.",148,2,9,147,"Sonora querida",7,5,"ea",89,0,-1,0,239,239,"7231","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7232",7,"Nunca he cometido falta\ncuando vengo por aquí;\nsiempre te canto en voz alta,\nno puedo echar un mentís;\n¡qué bonito es Tlacotalpan!,\nel pueblo donde nací.",136,2,4,147,"La guacamaya",9,6,"i",-1,0,-1,0,239,239,"7232","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7233",7,"¡Ay, Jalisco, tierra mía!,\neres linda desde Ameca a Zapotlán,\n¡Ay, Jalisco, tapatío!,\nes mi orgullo haber nacido por acá.",135,2,-1,147,"Jalisco nunca pierde’",3,4,"a",-1,0,-1,0,239,239,"7233","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7234",7,"Mi Jalisco nunca pierde,\ny cuando pierde: arrebata,\ny le atora a los peligros\nsin echarse nunca atrás.",135,2,-1,147,"Jalisco nunca pierde",5,4,"a",-1,0,-1,0,239,239,"7234","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7235",7,"Tierra linda de Jalisco,\ncariñosa tierra mía,\ndonde he visto a las estrellas\ny la luna platicar.",135,2,-1,147,"Jalisco nunca pierde",5,4,"a",-1,0,-1,0,239,239,"7235","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7236",7,"Todos somos de Jalisco\nlos que andamos por aquí;\ntierra linda y soberana,\nte saludo desde aquí.",145,2,17,147,"Mi tierra",0,4,"i",-1,0,-1,0,239,239,"7236","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7237",7,"Es mi orgullo ser costeño\nde linda tierra norteña,\ncuna del “Cielo lindo”\ny también “La Malagueña”.",135,2,-1,147,"El alegre tampiqueño",0,4,"ea",291,0,-1,0,239,239,"7237","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7238",7,"Yo soy mujer de la Huasteca,\ntierra divina y hermosa,\nsoy tu gran admiradora\nporque Dios te puso hermosa,\nmi Huasteca encantadora.",136,2,4,147,"La azucena",7,5,"oa",-1,0,-1,0,239,239,"7238","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7240",7,"Yo me salí a recorrer\ndel Golfo y hasta el Océano,\ny si alguien quiere saber\nlo que yo traigo entre manos,\ntengo el orgullo de ser\njarocho veracruzano.",136,2,4,147,"El siquisirí",9,6,"ao",-1,0,-1,0,240,240,"7240","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7241",7,"Soy de la tierra de Dios,\nde los jarochos hermano,\nsoy huasteco de nación,\nhuasteco veracruzano,\nde donde es la raíz del sol\ny la mata del huapango.",138,2,6,147,"La huazanga",9,6,"ao",-1,0,-1,0,240,240,"7241","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7242",7,"Por eso digo que es bella\nmi tierra veracruzana:\nlo grita mi corazón,\nporque es linda desde el puerto\nhasta el último rincón.",136,2,4,147,"Estampa jarocha",7,5,"o",31,0,-1,0,240,240,"7242","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7243",7,"Es tan bello mi Fortín,\ntierra de las frescas flores,\nde gardenias sus olores;\nesa linda mariposa\nque ahora acaba de pasar\naquí te daré, mi esposa,\nvirgencita tropical.",136,2,4,147,"Canto a Veracruz",4,7,"a",-1,0,-1,0,240,240,"7243","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7244",7,"Una flor que no se seca\ny que su aroma convence\nes mi querida Huasteca,\nesa Huasteca hidalguense.",138,2,6,147,"El hidalguense",1,4,"ee",610,0,-1,0,240,240,"7244","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7245",7,"Huasteca linda,\n¿cómo te podré olvidar,\nsi nací con su querencia,\nsi nací con su cantar?",138,2,6,147,"Las tres Huastecas",3,4,"a",21,0,-1,0,240,240,"7245","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7247",7,"“¡Ay, Jalisco, no te rajes!”\nme sale del alma gritar con calor;\nabrir todo el pecho pa echar este grito:\n“¡Qué lindo es Jalisco, palabra de honor!”",135,2,-1,147,"¡Ay, Jalisco, no te rajes!",3,4,"o",72,0,-1,0,241,241,"7247","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7248",7,"¡Ay, Jalisco, Jalisco, Jalisco!,\ntú tienes tu novia que es Guadalajara;\nmuchacha más guapa, la perla más rara\nde todo Jalisco es mi Guadalajara.",135,2,-1,147,"¡Ay, Jalisco, no te rajes!",3,4,"aa",57,0,-1,0,241,241,"7248","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7249",7,"Este pueblito de Putla\nes muy lindo de verdad,\npues parece nacimiento\nde la corte celestial.",142,2,8,147,"Chilena de Putla",0,4,"a",-1,0,-1,0,241,241,"7249","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7250",7,"Bonita plaza de armas\ntenía Porfirio Díaz,\nrodeada de mujeres,\ny en medio artillería.",142,2,8,147,"El Colás",0,4,"ia",-1,0,-1,0,241,241,"7250","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7251",7,"Bonita plaza de armas\nque en Veracruz está,\nrodeada de muchachas,\ny en medio Nicolás.",136,2,4,147,"El Colás",0,4,"a",-1,0,-1,0,241,241,"7251","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7252",7,"Bonita la glorieta\nque está en el malecón,\nrodeada de muchachas,\ny en medio Díaz Mirón.",136,2,4,147,"El Colás",0,4,"o",31,0,-1,0,241,241,"7252","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7253",7,"Bonita la glorieta\nque en Veracruz está,\nle llaman La Maqueta,\nque en Veracruz se ve.",136,2,4,147,"El Colás",5,4,"e",-1,0,-1,0,241,241,"7253","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7254",7,"Por la calle de Pacheco Noriega\ny de Francisco Noriega\ncantan palomas moradas,\nsentadas en las palmeras.",146,2,7,147,"Ometepec",3,4,"ea",-1,0,-1,0,241,241,"7254","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7255",7,"¡Qué bonitas sus campanas\ncuando se oyen repicar,\nllamando a todos los fieles\na que vayan a rezar!",135,2,-1,147,"A Canelas",0,4,"a",21,0,-1,0,242,242,"7255","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7256",7,"Bonito Matamoros,\nvamos y lo verás:\nrodeado de fortines,\ny en medio Nicolás.",159,2,26,147,"Estrofa suelta",0,4,"a",51,0,-1,0,242,242,"7256","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7257",7,"Al oriente la ladera,\nal Poniente está el Sillón,\ny en las cumbres de este cerro\nestá la Cruz del Perdón.",135,2,-1,147,"A Canelas",0,4,"o",31,0,-1,0,242,242,"7257","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7258",7,"¡Ay, qué bello es Veracruz!,\nel puerto más afamado,\ncon su faro y su alumbrado\nrefleja en el mar su luz.",136,2,4,147,"Qué bello es Veracruz",11,4,"u",109,0,-1,0,242,242,"7258","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7259",7,"¡Qué bonito es Veracruz!,\nla heroica por tradición;\nlo visita la multitud\ny el público en reunión;\nporque ahí conoció la luz\ndon Salvador Díaz Mirón.",142,2,8,147,"El siquisirí’T",9,6,"o",31,0,-1,0,242,242,"7259","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7260",7,"Si a Tampico vas un día,\nsi te quisieras pasear,\nno dejes de preguntar\nque por dónde va el tranvía\nque va para Miramar.",138,2,6,147,"Las conchitas",7,5,"a",21,0,-1,0,242,242,"7260","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7261",7,"A un paso está El Rosario\ncon sus jardines y flores\ny las aguas de los ríos,\nrefrescando los amores.",142,2,8,147,"Chilena de Putla",0,4,"oe",5,0,-1,0,242,242,"7261","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7262",7,"Jamiltepec,\ntierra de amores,\ndonde aterrizan\nlos aviadores.",142,2,8,147,"Chilena de Jamiltepec",6,4,"oe",5,0,-1,0,242,242,"7262","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7263",7,"¡Qué bonito pueblo de Ameca!,\nbonita su calle real,\npero más bonito es\nsu Ferrocarril Central.",135,2,-1,147,"Pueblo de Ameca’T",0,4,"a",1,0,-1,0,242,242,"7263","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7264",7,"[Qué bonito pueblo de Ameca!,\nbonito su Puente Grande;\ncuando paso por ahí\nganas me dan de quedarme.",135,2,-1,147,"Pueblo de Ameca",0,4,"ae",-1,0,-1,0,242,242,"7264","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7265",7,"¡Qué bonito pueblo de Ameca!,\nahora sí ya está en bonanza;\nmolinos por todo el río,\ntrigales en la Esperanza.",135,2,-1,147,"Pueblo de Ameca",0,4,"aa",163,0,-1,0,243,243,"7265","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7266",7,"¡Qué bonito es Acapulcol,\nque desde lejos se ve;\nse devisan los Amates,\nla capilla de San José.",135,2,-1,147,"Estrofa suelta",0,4,"e",77,0,-1,0,243,243,"7266","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7267",7,"¿Qué es aquello que deviso\nen aquel hermoso plan?\nSon las luces del Palacio\ndel pueblo de Apatzingán.",137,2,3,147,"El calero; Estoy al vender una ingrata",0,4,"a",147,0,-1,0,243,243,"7267","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7268",7,"En sus más grandes ramales\nel sol refleja su luz,\nsus dos grandes forestales\nen mi lindo Veracruz.",136,2,4,147,"Qué bello es Veracruz",1,4,"u",109,0,-1,0,243,243,"7268","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7269",7,"¡Qué bonito es mi Canelas!,\nde cerros está rodeado,\ny con jardines de flores\nmi Dios lo tiene sembrado.",135,2,-1,147,"A Canelas",0,4,"ao",14,0,-1,0,243,243,"7269","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7270",7,"Pueblecito de Atoyac,\n¿por qué eres tan engreidor?\nSerá por los arbolitos\nque tienes alrededor.",142,2,8,147,"La garza; Bonito San Juan del Río; El güerito; La Sanmarqueña; Estrofa suelta",0,4,"o",72,0,-1,0,243,243,"7270","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7271",7,"Los tamarindos de Iguala\nen callada procesión;\ncon lo fresco de su rama\nrefresco mi corazón.",146,2,7,147,"Camino de Chilpancingo",0,4,"o",31,0,-1,0,243,243,"7271","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7272",7,"¡Ay, mi Coyuca tan lindo!,\neres mi único encanto;\nbien sabes que por tu río,\nbien sabes que te amo tanto.",146,2,7,147,"Coyuca de Catalán",0,4,"ao",30,0,-1,0,243,243,"7272","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7273",7,"Te acaricia hasta la brisa\ndel Río Balsas y el...,\nte refresca la sonrisa\ny el perfume de un lirio.",146,2,7,147,"Coyuca de Catalán",5,4,"io",-1,0,-1,0,243,243,"7273","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7274",7,"¡Qué chula tierra,\nqué bella es!,\ncon sus cascadas\nsiempre a la vez.",145,2,17,147,"Mi tierra",6,4,"e",150,0,-1,0,243,243,"7274","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7275",7,"Árboles de la alameda,\n¿por qué no han enverdecido?\nPorque no los han regado\ncon agua del Río Florido.",151,2,23,147,"Me siento junto a la peña",0,4,"io",101,0,-1,0,244,244,"7275","",0,"","","",5,0,0,[],"",""],["frenk_t3-n7276",7,"Pinotepa, Pinotepa,\ncon tu cogollera real,\neres la perla costeña,\nPinotepa Nacional.",135,2,-1,147,"Chiquitita te vas criando",0,4,"a",1,0,-1,0,244,244,"7276","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7277",7,"Pinotepa, Pinotepa,\ntierra que yo siempre piso,\ndonde se encuentra ese puerto,\nese puerto de Minizo.",135,2,-1,147,"Chiquitita te vas criando",0,4,"io",95,0,-1,0,244,244,"7277","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7278",7,"De toditos los barrios\nme gusta onde vives tú:\ntiene flores y palmeras,\nbarrio de la Santa Cruz.",146,2,7,147,"El indio suriano",0,4,"u",-1,0,-1,0,244,244,"7278","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7279",7,"Bonito Tamazunchale,\ncon su río tan caudaloso,\nsus tardes muy tropicales\ny su aguardiente sabroso,\nonde siempre hallo el reposo.",138,2,6,147,"El sombrero",7,5,"oo",160,0,-1,0,244,244,"7279","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7280",7,"Bonitos cañaverales\nhay de aquel lado del río;\ntambién miro platanales\npor aquel lado sombrío,\natravesando pastales\nsolo en mi cuaco contigo.",135,2,-1,147,"Mi cielo huasteco",9,6,"io",-1,0,-1,0,244,244,"7280","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7281",7,"Ya me voy a despedir\ny lo haré gustosamente;\n¡vivan tus alegres zonas,\nCacahuatepec valiente!",142,2,8,147,"Cacahuatepec",0,4,"ee",15,0,-1,0,244,244,"7281","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7282",7,"En Tequisquiapan, canastas,\nen Cadereyta, metates,\nde San Juan del Río, las reatas,\ndel Pueblito, jitomates,\nde Hércules y La Cañada,\nlos mejores aguacates.",135,2,-1,147,"El queretanito",9,6,"ae",283,0,-1,0,244,244,"7282","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7283",7,"De Cocula es el mariachi,\nde Tecalitlán, los sones,\nde San Pedro es su cantar,\nde Tequila, su mezcal;\n¡ah!, los machos de Jalisco,\nafamados por entrones:\npor eso traen pantalones.",145,2,17,147,"Cocula",4,7,"oe",34,0,-1,0,244,244,"7283","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7284",7,"Tierra de la Costa Chica,\ntus gallos son los más bravos,\ncaballo de primer clase\ny cría del mejor ganado.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"ao",-1,0,-1,0,245,245,"7284","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7286",7,"Ese barrio de San Pedro\nes chiquito y muy bonito,\ndonde siembran la verdura,\nmuy buena pa el picadillo.",137,2,3,147,"Estrofa suelta",0,4,"io",-1,0,-1,0,245,245,"7286","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7287",7,"Somos del sur del estado,\nAltamira es nuestra tierra;\nen el bus hemos llegado\npor la falda de la sierra;\ncon gusto hemos elogiado\nlo que produce la tierra.",135,2,-1,147,"La leva",9,6,"ea",80,0,-1,0,245,245,"7287","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7288",7,"En Costa Grande se aprecia\nsus verdes grandes palmares,\nde sus bajíos, platanares,\nen sus sierras, cafetales.",135,2,-1,147,"Las dos costas de Guerrero’",0,4,"ae",-1,0,-1,0,245,245,"7288","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7290",7,"Bonito Tamazunchale,\nbonito y mantenedor;\nallá se mantiene el rico\ny también el vendedor;\nno más un defecto tiene:\nse encierra mucho el calor.",139,2,2,147,"La leva; Estrofa suelta",9,6,"o",72,0,-1,0,245,245,"7290","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7291",7,"Veracruz es un rincón\nredondeado de la playa;\nahí se ha inventado el son\ny pescar con atarraya,\ny también con el arpón,\nporque así nunca nos falla.",136,2,4,147,"Puerto sin igual",9,6,"aa",249,0,-1,0,245,245,"7291","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7292",7,"Allá por los cocoteros\nse escucha trinar el arpa;\nregresan los pescadores,\nvienen cantando contentos,\ncon buena pesca en su barca.",136,2,4,147,"Estampa jarocha",7,5,"aa",-1,0,-1,0,245,245,"7292","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7293",7,"Bonito que es Veracruz,\ny no se puede negar;\nahí es donde se conoce\nel tiburón y el caimán.",136,2,4,147,"Estrofa suelta",0,4,"a",-1,0,-1,0,246,246,"7293","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7294a",7,"De Veracruz a Alvarado\ntengo andada esta región;\nse come muy buen pescado,\nes muy sabroso el ostión;\ntambién se come guisado\nde jaiba y de camarón.",136,2,4,147,"El siquisirí; La morena",9,6,"o",31,0,-1,0,246,246,"7294a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7294b",7,"Mis palabras se desatan;\nde Veracruz a Alvarado\ntengo andada la región;\nse come muy buen pescado,\nes muy sabroso el ostión;\ntambién se come guisado\nla jaiba y el camarón.",136,2,4,147,"Mis palabras se desatan",4,7,"o",31,0,-1,0,246,246,"7294b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7295",7,"En San Simón de pasada\namarillo hay que tomar,\ntambién una trucha asada,\npa poderla saborear,\nallá por la madrugada\ncuando cantan “El llorar”.",139,2,2,147,"San Simón",9,6,"a",21,0,-1,0,246,246,"7295","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7297",7,"Mañana me voy al Istmo,\ny me voy con gran razón;\nahí no me muero de hambre,\ncon cinco de totopo\ny cinco de camarón.",142,2,8,147,"Estrofa suelta",7,5,"o",31,0,-1,0,246,246,"7297","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7298",7,"Valladolid gran Sací,\ntodo lo tuyo es muy bueno:\ntu Xtabentún y el relleno\nde Cay-cutz y jabalí.",152,2,13,147,"Estrofa suelta",11,4,"i",23,0,-1,0,246,246,"7298","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7299",7,"De la ciudad moreleña\ndicen que allá vive usted;\n¡mal haya sus malagueñas!,\nChina, su famoso té.",136,2,4,147,"El Ahualulco",0,4,"e",-1,0,-1,0,246,246,"7299","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7300",7,"¡Cuándo llegará ese cuándo,\nque en este San Luis dichoso\nhaya vino más sabroso\ncomo es el colonche! ¿cuándo?",138,2,6,147,"Estrofa suelta",11,4,"ao",-1,0,-1,0,247,247,"7300","",0,"","","",5,0,0,[],"",""],["frenk_t3-n7301",7,"Pachuca, la bella airosa,\nde mi tierra capital,\nde la que vivo orgulloso\npor su rico mineral.",138,2,6,147,"El hidalguense",0,4,"a",1,0,-1,0,247,247,"7301","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7302",7,"Otra cosa hay en Colima,\naparte de los pericos:\nunos pajaritos verdes,\nque tiene chatos los picos.",145,2,17,147,"El palmero",0,4,"io",319,0,-1,0,247,247,"7302","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7303",7,"Otra cosa hay en Colima,\naparte de los pericos,\nunas palomas azules,\nque cantan muy tristecico.",135,2,-1,147,"El colimóte",0,4,"io",-1,0,-1,0,247,247,"7303","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7304",7,"-¿Qué quieres que te traiga\nde Panzacola?\n—Una paloma blanca\ncon larga cola.",135,2,-1,147,"La bamba’T",6,4,"oa",321,0,-1,0,247,247,"7304","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7305",7,"Éntrale [a] Jerez,\nvamos a la villa,\na cortar rositas\nblancas y de Castilla.",144,2,10,147,"El Jerez",0,4,"ia",-1,0,-1,0,247,247,"7305","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7306",7,"De las ferias rumbosas\ny más bonitas\nes la que se celebra\nen Buenavista.",142,2,8,147,"Cacahuatepec",6,4,"ia",-1,0,-1,0,247,247,"7306","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7307",7,"Es Chavinda, donde hay gallos\ny canciones muy alegres,\ncorre en junio sus caballos,\ngasta plata por diciembre.",135,2,-1,147,"Estrofa suelta",0,4,"ee",-1,0,-1,0,247,247,"7307","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7308",7,"Feria del veinte de enero,\nte recuerdo hoy como ayer,\ndonde se pelean los gallos,\nsin cuartel, hasta vencer.",135,2,-1,147,"Mi tierra es León, Guanajuato",0,4,"e",20,0,-1,0,247,247,"7308","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7309",7,"Bonito León, Guanajuato,\nsu feria con su jugada;\nahí se apuesta la vida\ny se respeta al que gana;\nallí, en mi León, Guanajuato,\nla vida no vale nada.",135,2,-1,147,"Camino de Guanajuato",9,6,"aa",-1,0,-1,0,247,247,"7309","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7310",7,"Costa Grande está de feria,\nque nunca se olvidará;\nallí se canta y se reza\nal Señor de Petatlán.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"a",-1,0,-1,0,248,248,"7310","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7311",7,"Es una feria un recreo\ndesde aquí para Tamán;\nno, no me lo cuentan, lo veo:\nunos vienen, otros van,\naunque el camino está feo.",138,2,6,147,"Estrofa suelta",7,5,"eo",66,0,-1,0,248,248,"7311","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7312a",7,"Bonito Chapulhuacán\ny su fiesta tan hermosa,\ndonde se toca “El caimán”\ny de la vida se goza,\nzapateando la tal “Rosa”.",139,2,2,147,"Estrofa suelta",7,5,"oa",63,0,-1,0,248,248,"7312a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7313",7,"Paracho, pueblo de músicos,\nen ti anida la alegría;\nvamos a darle a la bola\nhasta que amanezca el día.",137,2,3,147,"Estrofa suelta",0,4,"ia",0,0,-1,0,248,248,"7313","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7314",7,"Hermosa la tierra mía,\ndonde toman tan formal;\ndigo con simpatía:\n“Tómese una Colosal\ny juegue a la lotería\".",141,2,1,147,"La leva",7,5,"ia",0,0,-1,0,248,248,"7314","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7315",7,"Tierra Colorada,\nlindo nombre y lugar tropical,\ndonde todos al son de guitarras\nmuy alegres salen a bailar.",146,2,7,147,"Tierra Colorada",3,4,"a",-1,0,-1,0,248,248,"7315","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7317",7,"De mi nación mexicana,\nla tierra que ando pisando\nen petróleo tuvo la fama;\ndejen las aves volando,\nhuasteca veracruzana,\ntú eres reina del huapango.",138,2,6,147,"La huazanga",9,6,"ao",-1,0,-1,0,248,248,"7317","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7318",7,"En todita la región\nse oyen alegres cantar\ny se acoplan con el son\nentre arrullos del palmar.",136,2,4,147,"Canto a Veracruz",1,4,"a",21,0,-1,0,249,249,"7318","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7319",7,"Allá por la madrugada\nse toca en re menor,\nse oyen dulces tonadas\ninspiradas con amor.",136,2,4,147,"Canto a Veracruz",0,4,"o",72,0,-1,0,249,249,"7319","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7321",7,"Soy de los alrededores\nde ese puerto sin igual;\ndicen que hay otros mejores:\neso es lo que hay que alegar,\nporque como trovadores\nninguno le ha de igualar.",136,2,4,147,"Puerto sin igual'T",9,6,"a",21,0,-1,0,249,249,"7321","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7322",7,"Que en la cuna del amor\nVeracruz es cantador;\noye bien cómo batea,\npara cumplir lo que desea;\nyo le pido a Dios que adoro\nque a mí con piedad me vea.",136,2,4,147,"El siquisirí",9,6,"ea",54,0,-1,0,249,249,"7322","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7323",7,"Es para mí Veracruz\ntierra alegre y tropical,\ndonde vi la primer luz\ny me enseñé yo a cantar;\ntierra bonita y preciosa,\nen donde “La camba”\naprendí yo a bailar,\njunto con “El Ánualulco”,\ntambién el Jarabe,\nson tradicional.",136,2,4,147,"Estrofa suelta",18,10,"a",-1,0,-1,0,249,249,"7323","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7324",7,"“¡Arriba mi Sinaloa!”\nles grito con toda el alma,\ncuando oigo que la tambora\nme toca “El sauce y la palma”.",135,2,-1,147,"¡Arriba Sinaloal",0,4,"aa",125,0,-1,0,249,249,"7324","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7325",7,"“¡Arriba mi Sinaloa!”\nmi pecho se los repite,\ncuando oigo que la tambora\nse arranca con “El Quelite”.",135,2,-1,147,"¡Arriba Sinaloal",0,4,"ie",315,0,-1,0,249,249,"7325","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7326",7,"Jarocho de corazón\ny también de nacimiento,\nel huapango retozón\nen mi corazón lo siento.",136,2,4,147,"A orillas del Papaloapan",1,4,"eo",94,0,-1,0,250,250,"7326","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7327",7,"Para el puerto de Alvarado\nyo quiero que tú me lleves;\nallí viviré cantando,\naprendiendo el zapateado\nque llevan las aguasnieves.",136,2,4,147,"Estampa jarocha",7,5,"ee",611,0,-1,0,250,250,"7327","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7328",7,"Me despido, que me voy,\nque me voy pa Veracruz,\nporque en el barrio de La India\nvenden “El pájaro cú”.",142,2,8,147,"El pájaro cú",0,4,"u",-1,0,-1,0,250,250,"7328","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7329",7,"De Agustín Ramírez fue\nsu más grande inspiración,\nque en Costa Chica cantaran\nchilena, bambuco y son.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"o",31,0,-1,0,250,250,"7329","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7330",7,"Para que en nosotros piensen,\ntienen Chilapa, Acapulco,\nOlinalá y Ahualulco\ntrovadores guerrerenses.",135,2,-1,147,"Ometepec",5,4,"ee",-1,0,-1,0,250,250,"7330","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7331",7,"Todos los astros del cielo\ntiene la Virgen María;\ndonde están los mexicanos\nsiempre reina la alegría.",135,2,-1,147,"Estrofa suelta",0,4,"ia",0,0,-1,0,250,250,"7331","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7332",7,"Viva Dios, viva la luna,\nviva la Virgen María;\ndonde están los oaxaqueños\nnunca falta la alegría.",142,2,8,147,"La Sanmarqueña",0,4,"ia",0,0,-1,0,250,250,"7332","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7333",7,"Ya me voy para la costa,\nallá son buenos cristianos:\npara no perder la sangre,\nse casan primos hermanos.",135,2,-1,147,"El Cihualteco",0,4,"ao",318,0,-1,0,250,250,"7333","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7334",7,"Cruz Grande de Costa Chica\nen un bonito lugar,\ngente pobre y gente rica\ndemuestra franca amistad.",135,2,-1,147,"La crucefiita",0,4,"a",-1,0,-1,0,250,250,"7334","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7335",7,"Cómo quiero yo a Canelas\ncon toda su ranchería;\nallá se brinda la amistad\nsin lucir la valentía.",135,2,-1,147,"A Canelas",0,4,"ia",0,0,-1,0,250,250,"7335","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7336",7,"¡Qué bonita y qué bonita\nes la costa de Guerrero!\nHay mujeres sensitivas,\nhombres bravos y de acero.",146,2,7,147,"El toro rabón",0,4,"eo",38,0,-1,0,251,251,"7336","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7337",7,"Si México está sentado\nen medio de una laguna,\n¡que vivan los mexicanos,\nque pican la penca en la uña!",144,2,10,147,"Estrofa suelta",0,4,"ua",-1,0,-1,0,251,251,"7337","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7338",7,"Tierra suriana,\ntierra caliente;\n¡cómo dan tus mujeres,\nhombres valientes!",142,2,8,147,"Cacahuatepec",6,4,"ee",-1,0,-1,0,251,251,"7338","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7339",7,"Si hay guerra con Guatemala,\nllamen sólo a un tapatío,\ndenle tequila y cuchillo\n—y ésta es la pura verdad—,\ny de fijo triunfará.",135,2,-1,147,"Estrofa suelta",7,5,"a",-1,0,-1,0,251,251,"7339","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7340",7,"Ya me voy para San Marcos:\nhay puertas y corredores,\ndonde son los guerrerenses\nlos consentidos de amores.",135,2,-1,147,"La Sanmarqueña",0,4,"oe",5,0,-1,0,251,251,"7340","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7341",7,"No te olvides que el Tuxpeño,\ncomo buen veracruzano,\nanda siempre muy risueño\ny un anzuelo en cada mano.",136,2,4,147,"El tuxpeño",1,4,"ao",81,0,-1,0,251,251,"7341","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7342",7,"¡Ay, qué torito que brama!\nLos muchachos de mi tierra\nqué bonito están naciendo\nen todita esta nación.",137,2,3,147,"El torito",5,4,"o",-1,0,-1,0,251,251,"7342","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7343",7,"Pues si al mundo Adán viniera\ny viera a una mexicana\nbailar jarabe ligera,\ntemo que a comer volviera\nla consabida manzana.",135,2,-1,147,"Estrofa suelta",7,5,"aa",4,0,-1,0,251,251,"7343","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7344",7,"Iremos a Tlacotalpan\na beber agua de coco,\nveremos a las jarochas\nal compás de la jarana\nbailar el “Jarabe loco”,",136,2,4,147,"Estampa jarocha",7,5,"oo",152,0,-1,0,251,251,"7344","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7346",7,"Bonita por delante,\nbonita de costado,\n¡ay, qué bonito bailan\nlas mujeres de Alvarado!",147,2,11,147,"El Colás",0,4,"ao",14,0,-1,0,252,252,"7346","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7347",7,"Cuando fui caballerango\nrecorrí todo el estado.\nNo me vengo dando el rango\npor lo que me han ponderado,\nque para bailar huapango,\nlas muchachas de Alvarado.",135,2,-1,147,"El siquisirí, Zapateado",9,6,"ao",-1,0,-1,0,252,252,"7347","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7348",7,"Las putlequitas bonitas\nson como los cascabeles:\nbailan, bailan la chilena,\ncon dos rosas en las piernas.",142,2,8,147,"Chilena de Putla",5,4,"ea",-1,0,-1,0,252,252,"7348","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7349",7,"Les cantaré la chilena,\nsímbolo de Costa Chica,\ndonde bailan zapateado\nlas preciosas morenitas.",142,2,8,147,"Cacahuatepec",0,4,"ia",-1,0,-1,0,252,252,"7349","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7350",7,"No hay muchacha que sea fea\ncuando viste de jarocha,\ny más cuando zapatea\ncon su gracia de morocha;\nla tarima se cimbrea:\n¡ésa es mi tierra jarocha!",136,2,4,147,"El siquisirí",9,6,"oa",441,0,-1,0,252,252,"7350","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7351",7,"Para naranjas, Uruapan,\npara plátanos, el Plan,\npara muchachas bonitas,\nel pueblo de Apatzingán.",135,2,-1,147,"La palomita; Estrofa suelta",0,4,"a",147,0,-1,0,252,252,"7351","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7352",7,"Pa mujeres, Tulancingo,\nlo mismo Zacualtipán;\nhay unas coloraditas\nque hasta calentura dan.",139,2,2,147,"El hidalguense",0,4,"a",147,0,-1,0,252,252,"7352","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7353",7,"San Marcos tiene la fama\nde las mujeres bonitas;\ntambién Acapulco tiene\nde diferentes caritas.",142,2,8,147,"La Sanmarqueña; Chilena de Putla",0,4,"ia",258,0,-1,0,253,253,"7353","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7354",7,"Tiene mujeres bonitas,\nhembras de carne morena;\nen lo rojo de sus labios\nse desfloran las chilenas.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"ea",-1,0,-1,0,253,253,"7354","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7355",7,"La chilena va a empezar,\ny la empezaré, si quieres:\n¡Viva Cacahuatepec!,\ny ¡que vivan sus mujeres!",142,2,8,147,"Cacahuatepec",0,4,"ee",55,0,-1,0,253,253,"7355","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7356",7,"Viva Jalisco,\ntierra de amores,\nlindas mujeres\ncomo las flores.",145,2,17,147,"Mi tierra",6,4,"oe",5,0,-1,0,253,253,"7356","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7357",7,"En Los Altos es de machos\nrespetar la valentía,\ncoplas de la tierra\ny su ley son unos ojos,\nque enamoran al mirar.",135,2,-1,147,"Jalisco nunca pierde",7,5,"a",-1,0,-1,0,253,253,"7357","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7358",7,"¡Que viva Guadalajara!,\nla tierra de nombradía;\n¡que viva y que redonviva,\nla graciosa tapatía!",135,2,-1,147,"La chaparrita",0,4,"ia",-1,0,-1,0,253,253,"7358","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7359",7,"Guadalajara es la tierra\nde las puras tapatías,\ndel parque de Villanueva\nal jardín de Rosalía.",136,2,4,147,"El Ahualulco",0,4,"ia",-1,0,-1,0,253,253,"7359","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7360",7,"¡Ay, querido Guadalajara,\nciudad de las ansias mías!,\nel mismo cielo envidiara\ntus divinas tapatías.",145,2,17,147,"El jarabe tapatío",1,4,"ia",214,0,-1,0,253,253,"7360","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7361",7,"¡Ay, Jalisco, Jalisco, Jalisco!,\ntú tienes tu novia, que es Guadalajara;\nmuchachas bonitas, rechulas de cara,\nasí son las hembras de Guadalajara.",147,2,11,147,"¡Ay, Jalisco, no te rajes!",3,4,"aa",57,0,-1,0,253,253,"7361","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7362",7,"Yo subí a la peña verde\na devisar para el plan,\ndevisé a las zihuatecas\nque andaban en Zihuatlán.",135,2,-1,147,"El Cihualteco",0,4,"a",147,0,-1,0,254,254,"7362","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7363",7,"En la barranca de Apureo\nsuspiraba un gavilán,\ny en el suspiro decía:\n“Muchachas de Camaguay”.",135,2,-1,147,"El gavilán colorado",0,4,"a",-1,0,-1,0,254,254,"7363","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7364",7,"¡Qué bonito pueblo de Ameca\ncuando entra la primavera!\nMuchachas de San Miguel,\njuntas con las de La Higuera.",135,2,-1,147,"Pueblo de Ameca",0,4,"ea",44,0,-1,0,254,254,"7364","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7365",7,"Dicen que bien se fue,\nque se fue para las peñas;\nPuerto Rico y su café\ny a Huatusco y sus trigueñas.",136,2,4,147,"El Ahualulco",1,4,"ea",281,0,-1,0,254,254,"7365","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7366",7,"Bonito San Juan del Río,\n¿por qué eres tan engreidor?\nSerá por tanta muchacha\nque tienes alrededor.",164,2,16,147,"Bonito San Juan del Rio",0,4,"o",72,0,-1,0,254,254,"7366","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7368",7,"Huamantla de mis amores,\ntierra de hermosas mujeres,\nen tu suelo los negritos\nparecen cual primavera",150,2,24,147,"Huamantla",5,4,"ea",-1,0,-1,0,254,254,"7368","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7369",7,"Tamazunchale bonito,\ncon tus cielos y bajíos,\nes un edén de placeres:\nsus árboles y sus ríos,\ny divinas sus mujeres.",138,2,6,147,"La Malagueña",7,5,"ee",55,0,-1,0,254,254,"7369","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7370",7,"¡Ay, sierra, qué linda eres,\npor tus ríos y montañas!\nSon muy lindas tus mujeres,\npor esas negras pestañas,\nque te exceden de placeres.",141,2,1,147,"Pahuatlán",7,5,"ee",55,0,-1,0,254,254,"7370","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7371",7,"Esos cerros que te miran\nson negros cual hondas penas,\nreflejan tus negros ojos\nde tus mujeres morenas.",150,2,24,147,"Huamantla",0,4,"ea",62,0,-1,0,254,254,"7371","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7372",7,"Bonito Tecalitlán\npor sus mujeres hermosas;\ncuando me salí a bailar\nel son de “Las mariposas”,\npero ¡qué gusto me da\nacordarme de esas cosas!",135,2,-1,147,"Bonito Tecalitlán",9,6,"oa",61,0,-1,0,255,255,"7372","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7373",7,"Vía Acapulco está San Marcos,\nde Margelia a Ometepec;\na mis costeñas bonitas\nsiempre yo les cantaré.",135,2,-1,147,"Las dos costas de Guerrero",0,4,"e",-1,0,-1,0,255,255,"7373","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7374",7,"Voy a cantar un huapango,\npor toditos los lugares,\nmuchachas de Huauchinango,\ntambién las de Villa Juárez,\nde esas que están como mango.",141,2,1,147,"Pahuatlán",7,5,"ao",596,0,-1,0,255,255,"7374","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7375",7,"Que le echen agua, que no hagan polvo,\nque estoy bailando con mi querer;\n¡arriba el Norte con sus mujeres,\nque son rositas de amanecer!",159,2,26,147,"Redowa",3,4,"e",20,0,-1,0,255,255,"7375","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7376",7,"Tus jarochas tan hermosas,\ntoditas son de valor,\nparecen rosas preciosas\nque fascinan con su olor.",135,2,-1,147,"Qué bello es Veracruz",1,4,"o",72,0,-1,0,255,255,"7376","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7377",7,"Las flores que allí bajan\nson muy hermosas,\nporque son las mejores\nque hay en la costa.",142,2,8,147,"Cacahuatepec",6,4,"oa",-1,0,-1,0,255,255,"7377","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7378",7,"Lloren, lloren, poblanitas,\nnunca dejen de llorar;\ny muchas muchachas bellas\nhe visto en este lugar,\nque parecen virgencitas\ncuando salen a pasear.",136,2,4,147,"Las poblanitas",9,6,"a",21,0,-1,0,255,255,"7378","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7379",7,"¡Qué bonita y qué bonita\nes la costa oaxaqueña,\nde mujeres sensitivas\ncon esclavos que domeñan!",142,2,8,147,"El toro rabón",0,4,"ea",-1,0,-1,0,255,255,"7379","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7380",7,"Pinotepa me gustó,\nson sensuales sus inditas;\nTacubaya me encantó\npor sus lindas morenitas.",142,2,8,147,"Cacahuatepec; Ometepec",1,4,"ia",258,0,-1,0,255,255,"7380","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7381",7,"Dicen que soy de Palo Semita,\nlos de Santana lo dirán;\nen el centro de Chapulhuacán\nsalen unas morenitas\nque hasta calentura dan.",138,2,6,147,"La presumida",7,5,"a",147,0,-1,0,255,255,"7381","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7382",7,"Costa Chica, eres encanto\ndonde tanto disfruté;\nserá por tus morenitas\nde allá de Cacahuatepec.",142,2,8,147,"Cacahuatepec",0,4,"e",-1,0,-1,0,256,256,"7382","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7383",7,"No sufras porque me veas,\nte engañabas por el vulgo;\nno hay morena que sea fea\nbajo el cielo de Acapulco.",146,2,7,147,"Camino de Chilpancingo",0,4,"uo",-1,0,-1,0,256,256,"7383","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7384",7,"Soy torete sin fierro,\nque me nombran El Mexteño;\nno hay morena que sea fea;\nsi no sabes, no te metas,\nbajo el cielo oaxaqueño.",142,2,8,147,"Estrofa suelta",7,5,"eo",138,0,-1,0,256,256,"7384","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7385",7,"¡Ay, morenas, ay, morenas!,\nblancas muy preciosas;\nasí son las mujeres\nde mi tierra tan hermosa.",139,2,2,147,"Estrofa suelta",0,4,"oa",-1,0,-1,0,256,256,"7385","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7386",7,"La tierra de donde vengo,\nla luna mucho brilla;\nlas muchachas son muy guapas,\nno se dan en cascarilla.",142,2,8,147,"Estrofa suelta",0,4,"ia",162,0,-1,0,256,256,"7386","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7387",7,"¡Qué lindas las mañanas\ncuando sale el sol!\nAsí son las alteñas\nde este alrededor.",135,2,-1,147,"Las alteñitas",0,4,"o",-1,0,-1,0,256,256,"7387","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7388",7,"¡Qué alegres y bonitas\ntodo el tiempo están,\nlas lindas alteñitas\nde Tepatitlán!",135,2,-1,147,"Las alteñitas",1,4,"a",147,0,-1,0,256,256,"7388","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7389",7,"En los baños de Colima\nhay tuba y agua de coco,\ny las vendedoras son\nlas que vuelven a uno loco.",135,2,-1,147,"La colimota; Estrofa suelta",0,4,"oo",152,0,-1,0,256,256,"7389","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7390",7,"Bonitas las tapatías\ncuando se van a bañar:\nlo primero que se lavan\nson los pies, para bailar.",135,2,-1,147,"Guadalajara en un llano; La indita; La Llorona; La Sanmarqueña",0,4,"a",21,0,-1,0,256,256,"7390","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7391",7,"A mí me gustan las sanmarqueñas\ncuando se van a bañar;\nson morenas y preciosas,\nse van a la orilla del mar.",142,2,8,147,"La Sanmarqueña",3,4,"a",21,0,-1,0,257,257,"7391","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7392",7,"Si te fueras a Colima,\nte bajarás en Palmar,\nverás a las costeñitas,\nvan a las olas del mar.",135,2,-1,147,"El colimóte; El palmero",0,4,"a",21,0,-1,0,257,257,"7392","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7393",7,"Arriba de Cihuatlán\nle nombran la Agua Escondida,\ndonde se van a bañar\ncihualtecas de mi vida.",145,2,17,147,"El Cihualteco",0,4,"ia",37,0,-1,0,257,257,"7393","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7394",7,"Mi orgullo de Costa Chica,\nnunca te podré olvidar:\ntienes tu arroyo en Talapa,\nque siempre invita a soñar,\nadonde van tus costeñas\ntodos los días a bañar.",135,2,-1,147,"Ometepec",9,6,"a",21,0,-1,0,257,257,"7394","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7395",7,"¡Ay, Huasteca, tierra hermosa,\nque nunca podré olvidar!\nMe paso horas deliciosas\ncontemplando su palmar,\ny sus mujeres hermosas\nson más bellas que un palmar.",136,2,4,147,"La huazanga",9,6,"a",-1,0,-1,0,257,257,"7395","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7396",7,"Cosamaloapan es la cuna\nde las mujeres más bellas,\na donde brilla la luna\ny el cielo con las estrellas,\ny si me caso con una,\nme caso con una de ellas.",136,2,4,147,"El siquisirí",9,6,"ea",89,0,-1,0,257,257,"7396","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7397",7,"En Jalisco se quiere a la buena,\nporque es peligroso querer a la mala;\npor una morena echar mucha bala\ny bajo la luna cantar en Chapala.",135,2,-1,147,"lAy, Jalisco, no te rajes!",3,4,"aa",330,0,-1,0,257,257,"7397","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7398",7,"En la Huasteca hidalguense\nno se alquila el corazón;\nel que diga: “Usted dispense”\nno amanece en el colchón.",138,2,6,147,"Las tres Huastecas",1,4,"o",31,0,-1,0,257,257,"7398","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7400",7,"Flor de Chiapas tierra hermosa\ndonde todas las mujeres\nson alegres y bonitas\ny buenas pa los quereres.",160,2,19,147,"Las chiapanecas",0,4,"ee",55,0,-1,0,258,258,"7400","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7402",7,"Huasteca potosina,\ntierra divina,\nla tierra del huapango —linda Huasteca,\nla potosina;\ncuna de amores,\npor sus lindas mujeres —de ojos negros,\nencantadores.",141,2,1,147,"‘‘Cielito lindo",4,7,"oe",5,0,-1,0,258,258,"7402","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7404",7,"Tus lindas mujeres\nencienden quereres,\nson hembras de amor;\nCajeme, tan rico,\ndonde hasta el más chico\ngana su tostón.",148,2,9,147,"Sonora querida",9,6,"o",-1,0,-1,0,258,258,"7404","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7406",7,"¡Qué bonita es esta tierra\nde hombres nobles y sincerosl,\ndonde también las mujeres\ndan el corazón entero\nal hombre que las prefiere.",136,2,4,147,"Estrofa suelta",7,5,"ee",-1,0,-1,0,258,258,"7406","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7407",7,"¡Ay, morenita linda\nde la costa caliente!\nLa tierra de los jarochos\nes tierra que nunca miente.",136,2,4,147,"‘‘A orillas del Papaloapan",0,4,"ee",15,0,-1,0,258,258,"7407","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7408",7,"En mi San Luis Potosí\nlas hembras son puro amor;\nen el Norte son de arranque\ncuando dan su corazón.",135,2,-1,147,"El as de los huapangos",0,4,"o",-1,0,-1,0,259,259,"7408","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7409",7,"Las muchachas de mi tierra\nesas sí saben querer:\ncuando muerden el rebozo\ny es para corresponder.",139,2,2,147,"Las chaparreras",0,4,"e",20,0,-1,0,259,259,"7409","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7410",7,"Cuando me mientan la costa\nparece que mientan gloria,\nporque las costeñas tienen\namores que son historias.",142,2,8,147,"Estrofa suelta",0,4,"oa",-1,0,-1,0,259,259,"7410","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7411",7,"Cuando una costeña dice “quiero”\nquiere y está comprobado,\nporque se meten con hombres,\nno con putos aguados.",142,2,8,147,"Estrofa suelta",3,4,"ao",-1,0,-1,0,259,259,"7411","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7412",7,"Perla de la Costa Chica,\nquiero ser tu trovador,\npara cantarle a tus hembras,\nque son fieles al amor.",135,2,-1,147,"Ometepec",0,4,"o",72,0,-1,0,259,259,"7412","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7413",7,"Subí al cerro del Bernal\na vivir junto a Casita,\nestado de Tamaulipas\na mi amor.........................",136,2,4,147,"El caimán",3,4,"o",-1,0,-1,0,259,259,"7413","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7414",7,"¡Oh, Guaymas hermoso!,\npuerto delicioso,\nen donde encontré\nuna encantadora\nhija de Sonora,\na la que adoré.",148,2,9,147,"Sonora querida",9,6,"e",77,0,-1,0,259,259,"7414","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7415",7,"Tamazunchale y Axila —Aquismón y Valles,\ntierra divina:\nla tierra del huapango —linda Huasteca\nla potosina;\ncuna de amores,\npor ti, linda morena —de negros ojos,\nperdí favores.",138,2,6,147,"Cielito lindo",4,7,"oe",5,0,-1,0,259,259,"7415","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7416",7,"Lloren, lloren, poblanitas,\ncorazones de madera.\nSoy de Atlixco de las Flores,\ndonde dejé mi querer;\nmuy pronto pienso volver\na Atlixco de mis amores.",135,2,-1,147,"Las poblanitas",9,6,"oe",5,0,-1,0,259,259,"7416","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7417",7,"En Ometepec quisiera\nentregarme a sus placeres,\naunque después me muriera\nen brazos de sus mujeres.",135,2,-1,147,"Ometepec",1,4,"ee",55,0,-1,0,259,259,"7417","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7418",7,"Ya me voy a despedir,\npor eso vine a cantar\na mis dos costas bravias,\nque me enseñaron a amar.",142,2,8,147,"Las dos costas de Guerrero",0,4,"a",21,0,-1,0,259,259,"7418","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7419",7,"Adiós, Acapulco,\nnosotros nos vamos,\nporque eres el azote (Acapulco)\nde los extraños.",135,2,-1,148,"Adiós, Acapulco",3,4,"ao",-1,0,-1,0,260,260,"7419","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7420",7,"Santo Domingo es gloria,\nTapextla es segundo cielo,\nCortijos es el purgatorio,\nMaldonado es quinto infierno.",142,2,8,148,"Estrofa suelta",0,4,"eo",-1,0,-1,0,260,260,"7420","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7421",7,"Si nuestro padre Adán\nal mundo otra vez volviera,\nen todas partes viviera,\nmenos en Pajacuarán.",135,2,-1,148,"Estrofa suelta",11,4,"a",147,0,-1,0,260,260,"7421","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7422",7,"Parece que estamos\nen Pajacuarán,\ndonde los borregos,\nya vienen y van.",135,2,-1,148,"Ya vienen... y no",0,4,"a",147,0,-1,0,260,260,"7422","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7423",7,"En cambio los tímidos\ndicen sin cesar:\n“Silencio, que estamos\nen Pajacuarán”.",135,2,-1,148,"Ya vienen... y no",0,4,"a",-1,0,-1,0,260,260,"7423","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7424",7,"Casas de adobe destruidas,\nun cura viejo y tontón,\nun médico sin fortuna,\ndos boticas homicidas:\nZumpango de la Laguna.",135,2,-1,148,"Estrofa suelta",7,5,"ua",56,0,-1,0,260,260,"7424","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7426",7,"Perro, perico y poblano\nno lo toques con la mano:\ntócalo con un palito,\nporque es animal maldito.",147,2,11,148,"Estrofa suelta",5,4,"io",119,0,-1,0,260,260,"7426","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7427",7,"De Colima para abajo\ntoda la gente es muy rica:\nel que no tiene dinero\ntiene manchas de jiricua.",135,2,-1,148,"La colimota; Estrofa suelta",0,4,"ia",-1,0,-1,0,261,261,"7427","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7428",7,"Si vas a Tlaxcalantongo,\nprocura ponerte chango,\nporque allí a Barbastenango\nle sacaron el mondongo.",135,2,-1,148,"Estrofa suelta",11,4,"oo",484,0,-1,0,261,261,"7428","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7429",7,"Si fueras a Tlacomulco,\narregla el negocio y vente,\nporque si el pueblo es de a tlaco,\n¿de a cómo será la gente?",135,2,-1,148,"Estrofa suelta",0,4,"ee",15,0,-1,0,261,261,"7429","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7430",7,"Cuando te lleve a Sayula\nlo primero que verás\nson los bueyes por delante\ny el bueyero por detrás.",137,2,3,148,"La chinita",0,4,"a",51,0,-1,0,261,261,"7430","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7431",7,"Otra cosa hay en Colima,\nno te vayas a admirar;\nallá está una piedra lisa,\nno vayas a resbalar.",135,2,-1,148,"El colimóte",0,4,"a",21,0,-1,0,261,261,"7431","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7432",7,"Adiós, villa de Colima,\ndonde salí esta mañana;\nnada llevo y antes dejo\ntoda la mera fierrada.",145,2,17,148,"El colimóte",0,4,"aa",-1,0,-1,0,261,261,"7432","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7433",7,"Adiós, Autlán” de la Grana,\ndonde salí esta mañana;\nsólo aquel que sea tarugo\nvolverá de buena gana.",135,2,-1,148,"El colimote’T",0,4,"aa",4,0,-1,0,261,261,"7433","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7434",7,"Adiós, Jalapa querida,\nde mis calles yo me alejo;\nme voy requetejodido,\nregreso si soy pendejo.",142,2,8,148,"Estrofa suelta",0,4,"eo",264,0,-1,0,261,261,"7434","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7435",7,"El tren va echando demonios\npor esas calles de León;\npor muchos demonios que eche,\nmás demonios echo yo.",144,2,10,148,"La jota del ferrocarril",0,4,"o",-1,0,-1,0,261,261,"7435","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7436",7,"Vámonos para Morelia\na tomar el guayabate,\nque si te quedas aquí,\nte remiendan el zunfiate.",137,2,3,148,"Que viva la rumba",0,4,"ae",384,0,-1,0,261,261,"7436","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7437",7,"¡Ay, qué sierra tan horrible es allá!,\naullando lobos y tigres, sí;\nyo ya me voy a salir de allá\npara nunca volver, no volver para allá.",135,2,-1,148,"El tigre",3,4,"a",-1,0,-1,0,262,262,"7437","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7438",7,"¡Ay, qué siena tan bonita,\ndonde hay lobos y tigres!\nSi Dios me presta la vida,\nyo me voy a ir para allá\npara no volver para acá.",145,2,17,148,"El tigre",7,5,"a",9,0,-1,0,262,262,"7438","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7439",7,"De Colima para abajo\nhay muchas cosas que ver;\nmuchas muchachas bonitas\npintadas en la pared.",135,2,-1,148,"Vengo de tierra caliente",0,4,"e",-1,0,-1,0,262,262,"7439","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7440",7,"Me gustan las abajeñas\npor altas y presumidas:\nse bañan y se componen,\ny siempre descoloridas.",135,2,-1,148,"Las abajeñas; Estrofa suelta",0,4,"ia",279,0,-1,0,262,262,"7440","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7441",7,"En el pueblo viejo de Ures,\nlas muchachas sandungueras,\nparecen chicharras viejas\npor lo feas y mitoteras.",148,2,9,148,"La iguana",0,4,"ea",-1,0,-1,0,262,262,"7441","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7442",7,"Las muchachas de San Pedro\nson altas y cotorronas;\nde que bajan al riyito\nparecen yeguas pelonas.",148,2,9,148,"La iguana",0,4,"oa",549,0,-1,0,262,262,"7442","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7443",7,"Las muchachas de Magdalena\nson bastante perezosas:\ncuando las llama el trabajo\nse vuelven lobas furiosas.",148,2,9,148,"La iguana",0,4,"oa",61,0,-1,0,262,262,"7443","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7444",7,"Las muchachas matapeñas\nson bastante retobadas;\nse quitan la atarria a golpes\ny el tapojo a manotadas.",135,2,-1,148,"La iguana",0,4,"aa",282,0,-1,0,262,262,"7444","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7445",7,"Las muchachas de Tepache\ncompraron una romana,\npara pesarse las piernas\ntres veces a la semana.",135,2,-1,148,"La iguana",0,4,"aa",4,0,-1,0,262,262,"7445","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7446",7,"De San Marcos para acá\nno me caso con ninguna,\nporque les jiede la boca\na pescado de laguna.",135,2,-1,148,"La Sanmarqueña",0,4,"ua",56,0,-1,0,262,262,"7446","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7447",7,"De Acapulco para abajo\nya no se puede besar,\nporque les huele la boca\na pescado de la mar.",135,2,-1,148,"La Sanmarqueña",0,4,"a",21,0,-1,0,263,263,"7447","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7448",7,"Las muchachas de Hermosillo\nson como el atole frío:\nla cabeza enlistonada\ny el estómago vacío.",148,2,9,148,"La iguana; La Sanmarqueña; Estrofa suelta",0,4,"io",3,0,-1,0,263,263,"7448","",0,"frenk_t4","","",3,0,0,[],"",""],["frenk_t3-n7449",7,"Las muchachas de Batuco\nviven en puros jacales;\nde que bajan a la plaza\nparecen las principales.",148,2,9,148,"La iguana",0,4,"ae",26,0,-1,0,263,263,"7449","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7450",7,"Las chicas de Nacozari\nson altas y delgaditas.\npero son más pedigüeñas\nque las ánimas benditas.",148,2,9,148,"La iguana; María, María; Estrofa suelta",0,4,"ia",258,0,-1,0,263,263,"7450","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7454",7,"Lloren, lloren, poblanitas,\n¡qué bonitas morenitas!\nSon tan bonitas, que inspiran,\ncuando el hombre las adora,\npero no saben querer.",136,2,4,148,"Las poblanitas",7,5,"e",-1,0,-1,0,263,263,"7454","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7455",7,"Me gustan las abajeñas\nque saben la ley de Dios,\nque dejan a su marido\npara irse con otros dos.",145,2,17,148,"Las abajeñas",0,4,"o",87,0,-1,0,263,263,"7455","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7456",7,"Mujer que quiera a uno solo\ny banqueta para dos\nno se hallan en Guanajuato\nni por el amor de Dios.",135,2,-1,148,"Estrofa suelta",0,4,"o",87,0,-1,0,264,264,"7456","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7458",7,"Las muchachas de Hermosillo\nya no toman leche fría;\nahora la toman caliente,\npor medio de tubería.",148,2,9,148,"El tarachi",0,4,"ia",0,0,-1,0,264,264,"7458","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7459",7,"Buenas tardes,\nbuenas tardes, señorito,\nvenimos a cantar\ny también a visitar.",135,2,-1,149,"Canción de las canacuas",3,4,"a",21,0,-1,0,268,268,"7459","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7460",7,"Traigo versos, y bonitos,\ncomo ocho mil y un ciento,\npara cantárselos a Cupido\nel día de tu casamiento.",139,2,2,149,"Estrofa suelta",3,4,"eo",94,0,-1,0,268,268,"7460","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7461a",7,"Y a la capotín tintintín,\nque esta noche no te vas;\na la capotín tintintín,\nmañana madrugarás.",144,2,10,149,"El capotín’T",3,4,"a",51,0,-1,0,268,268,"7461a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7461b",7,"Tin, tin, el bien que adoro,\nsácale la vuelta al toro.\nA la capotín, tin, tin,\nesta noche no te vas;\na la capotín, tin, tin,\nmañana te casarás.",145,2,17,149,"El capotín’T",9,6,"a",51,0,-1,0,268,268,"7461b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7462",7,"Cuatro rosas cartulinas\nflorecen en el estrado:\nla novia y el desposado,\nel padrino y la madrina.\nLa omnipotencia divina\nlos esté regocijando\ny los ángeles, cantando\nla gloria con alegría;\ntambién Jesús y María\na ambos esté cobijando.",135,2,-1,149,"Estrofa suelta",18,10,"ao",33,0,-1,0,268,268,"7462","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7463",7,"En el mundo no se hará\notro mejor casamiento;\nel nuestro será el ejemplo,\nque el cura nos casará.\nEse día te vestirás\ncon puro vestido fino;\nhabrá cerveza, habrá vino,\nmuchos chocolates y pan,\nmucho mole comerán,\nsiempre que lo dé el padrino.",136,2,4,149,"Estrofa suelta",18,10,"io",199,0,-1,0,268,268,"7463","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7464",7,"Mi padre y mi madre lloran,\nporque me van a casar;\nno lloren, padre ni madre,\nque no me van a matar.",136,2,4,149,"El Jerez",0,4,"a",21,0,-1,0,269,269,"7464","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7465",7,"Ya con ésta me despido,\nme despido muy contento;\nya te canté este corrido\nque fue de tu casamiento.",161,2,15,149,"El apasionado",1,4,"eo",94,0,-1,0,269,269,"7465","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7466",7,"Me voy a Guadalajara\na traer a la Trinidad,\npa cantar las mañanitas,\nque es santo de su mamá,\ny si no le gusta allí,\nla vuelvo a llevar pa allá.",135,2,-1,149,"Huapango de huapangos",9,6,"a",9,0,-1,0,269,269,"7466","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7467",7,"En el nombre de Dios Padre\ny la Virgen Celestial,\ncantemos a nuestra madre\nun coro por memorial.",135,2,-1,149,"Las mañanitas para las madres",1,4,"a",1,0,-1,0,269,269,"7467","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7468",7,"En este día venturoso\nyo le canto a mi mamá,\nperturbando su reposo\nporque dormidita está.",135,2,-1,149,"Las mañanitas para las madres",1,4,"a",9,0,-1,0,269,269,"7468","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7469",7,"Por ser un día sagrado,\na vuestras plantas llegué,\ncon mañanitas cantando,\nque a mi mamá dediqué.",135,2,-1,149,"Las mañanitas para las madres",0,4,"e",77,0,-1,0,269,269,"7469","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7470",7,"El tesoro, mi riqueza,\nsólo tú lo eres, mamá;\noye el canto a mi promesa,\nque amaneciendo ya está.",135,2,-1,149,"Las mañanitas para las madres",1,4,"a",9,0,-1,0,269,269,"7470","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7471",7,"Levántate, mamacita,\ny escucha mi voz,\ncon la que te felicita\ntu hijo por gracia de Dios.",135,2,-1,149,"Las mañanitas para las madres",1,4,"o",87,0,-1,0,269,269,"7471","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7472",7,"Mamacita consentida,\nyo te ofrezco mi cantar;\ndespierta, si estás dormida,\nque yo te quiero saludar.",136,2,4,149,"Estrofa suelta",1,4,"a",21,0,-1,0,269,269,"7472","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7473",7,"Que la luz del alto cielo\nsea corona también;\nmamacita, mi consuelo,\nrecibe mi parabién.",135,2,-1,149,"Las mañanitas para las madres",1,4,"e",242,0,-1,0,269,269,"7473","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7474",7,"Son las tres de la mañana,\nel reloj las marca ya;\nyo a tus pies vengo postrado,\ntoma un beso, mamacita.",135,2,-1,149,"Las mañanitas para las madres",5,4,"ia",-1,0,-1,0,270,270,"7474","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7475",7,"Estas flores son benditas\npor la mano del Creador;\nrecíbelas, mamacita,\nprenda de todo mi amor.",135,2,-1,149,"Las mañanitas para las madres",0,4,"o",72,0,-1,0,270,270,"7475","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7476",7,"Toma esta humilde corona\nde las flores de este mes;\nmira, tu hijo te la endona,\nde rodillas a tus pies.",135,2,-1,149,"Las mañanitas para las madres",1,4,"e",218,0,-1,0,270,270,"7476","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7477",7,"Dedico estas mañanitas\na mi estimable comadre,\ny se las dejo ya escritas,\npara que siempre las guarde.",135,2,-1,149,"Las mañanitas",0,4,"ae",-1,0,-1,0,270,270,"7477","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7478",7,"Ya salieron las Tres Marías\ny el lucero está cerquita;\nyo vengo a darle los días\na mi amable comadrita.",135,2,-1,149,"Las mañanitas",1,4,"ia",-1,0,-1,0,270,270,"7478","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7479",7,"Abra ya sus ventanitas,\nque viene alborando el día;\ncantando estas mañanitas\nme iré, comadrita mía.",135,2,-1,149,"Las mañanitas",1,4,"ia",-1,0,-1,0,270,270,"7479","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7480",7,"Como es muy de mañanita,\nhoy que le vengo a cantar,\ndispénseme, comadrita,\nya se debía levantar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,270,270,"7480","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7481",7,"Repica una campanita\ncon agradable sonido;\nlevántese, comadrita,\nque a saludarla he venido.",135,2,-1,149,"Las mañanitas",1,4,"io",101,0,-1,0,270,270,"7481","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7482",7,"Perdóneme, comadrita,\nque la vine a despertar;\nreciba esta amapolita\nacabada de cortar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,270,270,"7482","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7483",7,"Con una flor de alelía\nla vengo a felicitar;.\nperdone, comadre mía,\nque la vine a despertar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,270,270,"7483","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7484",7,"Despierte, mi comadrita,\nsi acaso dormida está,\ncantando la felicita\nquien las mañanas le da.",135,2,-1,149,"Las mañanitas’’",1,4,"a",9,0,-1,0,271,271,"7484","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7485",7,"Mi apreciable comadrita,\nla vine a felicitar;\nquiero escuche animadita\nlo que hoy le vengo a cantar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,271,271,"7485","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7486",7,"Con gusto, comadre mía,\nla vengo a felicitar;\nque sea feliz en su día,\neso le puedo desear.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,271,271,"7486","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7487",7,"Escuche, mi comadrita,\nestos alegres cantares;\nla Virgen la felicita\ncoronándola de azahares.",135,2,-1,149,"Las mañanitas",1,4,"ae",164,0,-1,0,271,271,"7487","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7488",7,"Deseándole feliz cumpleaños\nen su venturoso día,\nque viva usted muchos años,\nquerida comadre mía.",135,2,-1,149,"Las mañanitas",3,4,"ia",0,0,-1,0,271,271,"7488","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7489",7,"Con este dulce licor\nla vengo a felicitar;\ncomo es de muy buen sabor,\ngustosa lo ha de tomar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,271,271,"7489","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7490",7,"Aquí me siento a cantar\nencima de este gran ramo;\ny éstas son las donas\nde mi señor amo.",163,2,21,149,"Aquí me siento a cantar",0,4,"ao",100,0,-1,0,271,271,"7490","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n7491",7,"Flores de Castilla,\nrosas de San Juan,\ndispénseme, caballero,\nque lo vine a molestar.",161,2,15,149,"Las mañanitas",0,4,"a",-1,0,-1,0,271,271,"7491","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7492",7,"El Creador le dé salud\ny plata hasta no desear,\npara que pase su vida\nen un continuo gozar.",135,2,-1,149,"Viva usted años felices",0,4,"a",21,0,-1,0,271,271,"7492","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7493",7,"Todos nos hemos reunido\nen este día de gran gala,\npara dar la bienvenida\nal jefe, señor Bandala.",142,2,8,149,"La garbosa",0,4,"aa",330,0,-1,0,271,271,"7493","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7494",7,"No te arrugues, cuero viejo,\nque te quiero pa tambor,\npa tocar unas mañanitas\nal señor gobernador.",140,2,12,149,"Estrofa suelta",0,4,"o",72,0,-1,0,271,271,"7494","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7495",7,"Mas ya tocaron la diana,\nel general lo mandó;\nsoldados, armas al hombro,\nmiren que ya amaneció.",135,2,-1,149,"Las mañanitas",0,4,"o",2,0,-1,0,272,272,"7495","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7496",7,"Corre, vuela, palomita,\nvete al compás de una garza,\nque aquí acaban las mañanas\ndel señor Jesús Esparza.",144,2,10,149,"Mañanas barranqueñas",0,4,"aa",-1,0,-1,0,272,272,"7496","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7497",7,"Ya me voy, ya me despido,\ndándole vuelta a un ocote;\na las doce volveremos\nal mole de guajolote.",135,2,-1,149,"Las mañanitas",0,4,"oe",292,0,-1,0,272,272,"7497","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7498",7,"Los ángeles con alegría\nentonan sus dulces cantos,\ndeseándole dichoso día,\npor ser hoy el de su santo.",135,2,-1,149,"Las mañanitas",3,4,"ao",-1,0,-1,0,272,272,"7498","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7499",7,"Con gusto entono este canto\npara conmemorar su día;\nque sea dichosa otro tanto\noyendo esta melodía.",135,2,-1,149,"Las mañanitas",1,4,"ia",0,0,-1,0,272,272,"7499","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7500",7,"San Pedro vino a cantarle\ncon su dulce melodía,\ny vine a felicitarla\nen su venturoso día.",135,2,-1,149,"Las mañanitas",0,4,"ia",0,0,-1,0,272,272,"7500","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7501",7,"Todos del cielo vinieron\ngustosos para cantar:\nunos con otros se unieron,\nqueriéndola felicitar.",135,2,-1,149,"Las mañanitas",1,4,"a",21,0,-1,0,272,272,"7501","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7502",7,"La luna brilla radiante,\nlas aves revolotean,\ntodos feliz la desean\nun porvenir muy brillante.",135,2,-1,149,"Las mañanitas",11,4,"ae",47,0,-1,0,272,272,"7502","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7503",7,"Celebremos con gusto, señores,\neste día de placer tan dichoso;\nque en su santo se encuentre gustoso\ny tranquilo tu fiel corazón.",135,2,-1,149,"Las mañanitas",3,4,"o",-1,0,-1,0,272,272,"7503","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7504",7,"Viva usted años felices\ndisfrutando de contento,\nteniendo muchos dineros,\ncon todo su pensamiento.",135,2,-1,149,"Viva usted años felices",0,4,"eo",-1,0,-1,0,272,272,"7504","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7505",7,"¡Qué linda está la mañana\nen que vengo a saludarte!\nVenimos todos reunidos,\ncon gusto a felicitarte.",136,2,4,149,"Las mañanitas",0,4,"ae",8,0,-1,0,273,273,"7505","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7506",7,"Por ser hoy día de tu santo,\ncon prósperas alegrías\na tus puertas vengo a dar\nvísperas, noches y días.",135,2,-1,149,"Estrofa suelta",0,4,"ia",214,0,-1,0,273,273,"7506","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7507",7,"Las garzas andan volando\ntoditas en compañía,\nandan que se despedazan\npor felicitar tu día.",135,2,-1,149,"Las mañanitas",0,4,"ia",0,0,-1,0,273,273,"7507","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7508",7,"Con jazmines y flores\nhoy te vengo a saludar;\nhoy por ser día de tu santo,\nte venimos a cantar.",135,2,-1,149,"Las mañanitas",0,4,"a",21,0,-1,0,273,273,"7508","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7509",7,"Vengo a endulzarte el oído\ncon este mi tierno canto,\na entonar las mañanitas,\nahora, que es día de tu santo.",135,2,-1,149,"Las mañanitas",3,4,"ao",30,0,-1,0,273,273,"7509","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7510",7,"Yo prosigo en mis cantares,\ndeseando alegrar tu hogar,\ny con un ramo de flores\nte vengo a felicitar.",135,2,-1,149,"Las mañanitas",0,4,"a",21,0,-1,0,273,273,"7510","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7511",7,"De riquezas a montones\nquisiera verte colmada,\nllena de dicha y contento\ny de todos celebrada.",135,2,-1,149,"Las mañanitas",0,4,"aa",49,0,-1,0,273,273,"7511","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7512",7,"Solamente un recuerdo ha quedado\nde la infancia que al fin ya pasó;\ncelebremos tu día tan dichoso\ntus amigas, amigos y yo.",145,2,17,149,"Las mañanitas",3,4,"o",2,0,-1,0,273,273,"7512","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7513",7,"Levántate, amiga mía,\nque te vengo a despertar;\nahora, que es día de tu santo,\nquiero contigo gustar.",158,2,22,149,"Las mañanitas",3,4,"a",21,0,-1,0,273,273,"7513","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7514",7,"Levántate, Teresita,\nque se ha llegado tu día;\nbailemos y tomaremos\nhasta que San Juan se ría.",135,2,-1,149,"Las mañanitas",0,4,"ia",0,0,-1,0,274,274,"7514","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7515",7,"Las buenas noches da Dios\nte las daremos ahora;\npor ser el día de tu santo\nte ponen esta corona.",136,2,4,149,"Saludo para santo",0,4,"oa",-1,0,-1,0,274,274,"7515","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7516",7,"La corona que te indico,\nde rosas y de amaranto,\nte la entrego muy gustoso\nahora, que es día de tu santo.",135,2,-1,149,"Las mañanitas",3,4,"ao",30,0,-1,0,274,274,"7516","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7517",7,"Las estrellas se visten de gala\ny la luna se llena de encanto\nal saber que hoy es día de tu santo:\n¡Dios bendiga este día de placer!",136,2,4,149,"Las mañanitas",3,4,"e",-1,0,-1,0,274,274,"7517","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7518",7,"La luna resplandeciente\nextiende su blanco manto,\nviene a iluminar tu ambiente\ny a congratular tu santo.",135,2,-1,149,"Las mañanitas",1,4,"ao",30,0,-1,0,274,274,"7518","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7519",7,"Los pajarillos gorjean\nsus trinos con alegría;\ntodos acordes desean\nque seas feliz en tu día.",135,2,-1,149,"Las mañanitas",1,4,"ia",0,0,-1,0,274,274,"7519","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7522",7,"Las mañanitas que aquí\ncon tanta pasión hoy canto,\nlas canto con alegría\npor ser el día de tu santo.",135,2,-1,149,"Las mañanitas",0,4,"ao",30,0,-1,0,274,274,"7522","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7523",7,"Quiso la suerte amorosa\nque en doce meses, ufano,\nte dirigiera mis trovas,\nsiendo hoy el día de tu santo.",135,2,-1,149,"Las mañanitas",0,4,"ao",-1,0,-1,0,274,274,"7523","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7524",7,"Hoy, que es el día de tu santo,\nte traigo una linda estrella,\npara que me eche su luz\ncuando platique con ella.",138,2,6,149,"Estrofa suelta",0,4,"ea",6,0,-1,0,275,275,"7524","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7525",7,"En la fresca y perfumada\nmañanita de tu santo,\nrecibe, mi bien amada,\nla dulzura de mi canto.",135,2,-1,149,"Las mañanitas",1,4,"ao",30,0,-1,0,275,275,"7525","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7526",7,"Dispensa que te interrumpa\ncon mis trinos, no te enfades:\n“¡Que viva el santol” te dicen\ntu amante y tus amistades.",135,2,-1,149,"Las mañanitas",0,4,"ae",373,0,-1,0,275,275,"7526","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7527",7,"Dios bendiga este día venturoso\ny bendiga la prenda que adoro;\nhoy los ángeles cantan en coro\npor los años que vas a cumplir.",135,2,-1,149,"Las mañanitas",3,4,"i",-1,0,-1,0,275,275,"7527","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7528",7,"Volaron cuatro palomas\npor todita la ciudad,\ndeseándote, amada mía,\ntodo género de felicidad.",147,2,11,149,"Las mañanitas; Estrofa suelta",3,4,"a",16,0,-1,0,275,275,"7528","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7529",7,"En fin, vida de mi vida,\n¡qué de dones celestiales!\nSiempre por siempre te veas\nllena de felicidades.",135,2,-1,149,"Las mañanitas",0,4,"ae",-1,0,-1,0,275,275,"7529","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7530",7,"Al dedicarte este canto,\nque mi lira transcribió\nconmemorando tu santo,\nya por ahora terminó.",135,2,-1,149,"Las mañanitas",1,4,"o",2,0,-1,0,275,275,"7530","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7531",7,"¿Es aquí o no es aquí,\no será más adelante?\nPorque dicen que aquí vive\nla princesa más constante.",135,2,-1,149,"Los papaquis",0,4,"ae",47,0,-1,0,275,275,"7531","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7532",7,"Pregunto por el señor,\ndueño de este lugar:\n“¿Me da permiso de cantar\nunos versitos de amor,\nque traigo pa disipar?”",159,2,26,149,"La azucena",7,5,"a",21,0,-1,0,275,275,"7532","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7533",7,"Señores, pido licencia\npara cantarle a mi amor\ny decirles lo que siente\nel pescado nadador.",135,2,-1,149,"El pescado nadador",0,4,"o",72,0,-1,0,276,276,"7533","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7534",7,"Aquí se planta un huasteco,\nrasgueándole a la jarana;\nviene entonando los sones\nde su Huasteca lejana,\npara ver si así consigue\nel amor de una serrana.",147,2,11,149,"El huasteco enamorado",9,6,"aa",4,0,-1,0,276,276,"7534","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7535",7,"¡Qué bonitas mañanitas,\ncon su cielo de zafir,\ncon su sol resplandeciente,\nque nos alegra el vivir!",135,2,-1,149,"Las mañanitas’’",0,4,"i",157,0,-1,0,276,276,"7535","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7536",7,"La luna resplandeciente\nilumina esta mañana\ncon más claridad su ambiente,\nmostrándose muy ufana.",135,2,-1,149,"Las mañanitas",1,4,"aa",4,0,-1,0,276,276,"7536","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7537",7,"Los astros del alto cielo\ndisputan supremacía;\ntodos activan su vuelo,\ndemostrando su alegría.",135,2,-1,149,"Las mañanitas",1,4,"ia",0,0,-1,0,276,276,"7537","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7538",7,"Ya las horas se adelantan,\nla luna pierde su brillo,\nlas aves alegres cantan,\nentonando su estribillo.",135,2,-1,149,"Las mañanitas",1,4,"io",228,0,-1,0,276,276,"7538","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7539",7,"Las notas vibran sonoras,\nunidas con el aliento,\nconmemorando, apacibles,\nde las flores el portento.",135,2,-1,149,"Las mañanitas",0,4,"eo",94,0,-1,0,276,276,"7539","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7540",7,"Las flores todas se animan\ny derraman sus olores;\nunas con otras se arriman\npara alegrar sus amores.",135,2,-1,149,"Las mañanitas",1,4,"oe",5,0,-1,0,276,276,"7540","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7541",7,"El éter siente, animado,\ntransformarse en armonía,\ny el aire muy perfumado\nte lleva esta melodía.",135,2,-1,149,"Las mañanitas",1,4,"ia",0,0,-1,0,276,276,"7541","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7542",7,"A la aurora, a la aurora levántate,\nMalagueña, dando céfiro,\nadornando su angélica bóveda,\nalabando así al autor.",151,2,23,149,"Las mañanitas’’",3,4,"o",-1,0,-1,0,276,276,"7542","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7543",7,"En el quicio de esta puerta\nel pie derecho pondré,\ny después de haberlo puesto,\nlos buenos días te daré.",135,2,-1,149,"Las mañanitas",0,4,"e",77,0,-1,0,277,277,"7543","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7544",7,"Ya asoman las Tres Marías,\nlo mismo el Carro brillante;\nme acerco a darte los días\ncon mi lira sollozante.",135,2,-1,149,"Las mañanitas",1,4,"ae",47,0,-1,0,277,277,"7544","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7545",7,"Dispensa nuestros cantares\ndel jardín de florecitas,\nque gustoso te dedico\nestas nuevas mañanitas.",135,2,-1,149,"Las mañanitas",0,4,"ia",258,0,-1,0,277,277,"7545","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7546",7,"Al pie de tu ventana\nte venimos a cantar,\ny mi dulce serenata\nte viene a despertar.",135,2,-1,149,"Las mañanitas",0,4,"a",21,0,-1,0,277,277,"7546","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7547",7,"Abre, niña, tus ojitos,\npara que nos puedas ver\ncon esos dos luceritos\nal tiempo de amanecer.",146,2,7,149,"Caminatas’T",1,4,"e",20,0,-1,0,277,277,"7547","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7548",7,"De las estrellas del cielo\nyo te diré las que quieres:\nlas Tres Marías, los Tres Reyes,\nlas Cabrillas y el lucero.",135,2,-1,149,"La banda",5,4,"eo",-1,0,-1,0,277,277,"7548","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7549",7,"¡Quién pudiera de los cielos\nbajarte dos jerarquías:\nuna para saludarte\ny otra para darte los días!",145,2,17,149,"Los papaquis",3,4,"ia",214,0,-1,0,277,277,"7549","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7550",7,"Quisiera ser un san Juan,\nquisiera ser un san Pedro,\npa venirte a saludar\ncon la música del cielo.",135,2,-1,149,"Las mañanitas",0,4,"eo",-1,0,-1,0,277,277,"7550","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7551",7,"San Pedro ha tomado parte\nen la celeste armonía;\nél también viene a cantarte\ncon su dulce melodía.",135,2,-1,149,"Las mañanitas",1,4,"ia",0,0,-1,0,277,277,"7551","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7552",7,"Los ángeles en el cielo\nentonan sus melodías,\nporque es su único anhelo\nel venirte a dar los días.",135,2,-1,149,"Las mañanitas",1,4,"ia",214,0,-1,0,277,277,"7552","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7553",7,"Los ángeles y los santos\ny la corte celestial\nentonan sus dulces cantos\ncon alegría sin igual.",135,2,-1,149,"Las mañanitas",1,4,"a",1,0,-1,0,278,278,"7553","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7554",7,"Encontrarás en tu reja\nun fresco ramo de flores,\nque mi corazón te deja,\nchinita de mis amores.",135,2,-1,149,"Las mañanitas",1,4,"oe",5,0,-1,0,278,278,"7554","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7555",7,"De la celeste mansión\nel soberano Señor\nle ha enviado su bendición\npara inculcarla su amor.",135,2,-1,149,"Las mañanitas",1,4,"o",-1,0,-1,0,278,278,"7555","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7556",7,"Lucero de la mañana,\nno te puedo relatar,\nsi mi pecho no me ayuda,\no yo no sabré cantar;\na mí me enseñó un sinsonte\nlos trinos de un cardenal.",135,2,-1,149,"Estrofa suelta",9,6,"a",-1,0,-1,0,278,278,"7556","",0,"","","",22,0,0,[],"",""],["frenk_t3-n7557",7,"Desde aquí me iré arrimando\ny me gusta la alegría;\ncon vergüenza estoy cantando,\npor no saber todavía;\napenas me ando enseñando\npara cantarte otro día.",159,2,26,149,"La azucena",9,6,"ia",0,0,-1,0,278,278,"7557","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7558",7,"Desde lejos vengo aquí\npa venirte a saludar;\nme gusta cantar así,\npues canto sin falsedad:\nen la Huasteca aprendí\nsiempre a decir verdad.",135,2,-1,149,"El huasteco",9,6,"a",16,0,-1,0,278,278,"7558","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7559",7,"No te duermas, vida mía,\nasómate a la ventana,\nque te saluda tu dueño\na la luz de la mañana.",147,2,11,149,"Estrofa suelta",0,4,"aa",4,0,-1,0,278,278,"7559","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7560",7,"No duermas tanto, Sanjuana,\ny escucha a tu trovador;\nyo al cielo pido licencia\nde ser dueño de tu amor.",161,2,15,149,"Valentín Mancera",0,4,"o",72,0,-1,0,278,278,"7560","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7562",7,"A la luz de los faroles\nte llevaré serenata;\nprefiero pan con frijoles;\nno te me vueles, mi chata.",147,2,11,149,"Estrofa suelta",1,4,"aa",74,0,-1,0,279,279,"7562","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7563",7,"Muchachita del barrio alto,\n¿por qué me han aborrecido?\n¿Porque les vengo a cantar\neste son de “El distinguido”?",135,2,-1,149,"El distinguido",0,4,"io",101,0,-1,0,279,279,"7563","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7565a",7,"En el paso del Saucito\nse me olvidaron los remos.\nSi tu amor no tiene grito,\naquí nos amanecemos,\ncantando este “Fandanguito”.",138,2,6,149,"El fandanguito",7,5,"io",119,0,-1,0,279,279,"7565a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7566",7,"Ahora sí, mi consentida,\ntraigo mariachis y vino;\nvengo dispuesto a cantarte\nmi huapango “El coscolino”,",135,2,-1,149,"El coscolino",0,4,"io",199,0,-1,0,279,279,"7566","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7567",7,"Lloro por un cascabel,\ntraigo regando alegría;\ny en la torre de Babel\nse oyó tanta algarabía;\ny a arrullarte, vida mía,\nhoy he venido con él.",147,2,11,149,"El cascabel",9,6,"e",32,0,-1,0,279,279,"7567","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7568",7,"Yo soy de mucho talento,\npor eso ando en los huapangos;\nsólo y una cosa siento:\nque las horas van pasando;\nquisiera más grande el tiempo\npara seguirte cantando.",136,2,4,149,"El pájaro carpintero",9,6,"ao",33,0,-1,0,279,279,"7568","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7569",7,"Y ariles y más ariles,\ny ariles mucho lo siento\nel que no te cante más,\nporque me falta el aliento.",136,2,4,149,"El Balajú",0,4,"eo",94,0,-1,0,279,279,"7569","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7570",7,"Con ésta y no más con ésta\nya me despido,\nramillete de flores,\njardín florido.",146,2,7,149,"Con ésta y no más con ésta",3,4,"io",101,0,-1,0,280,280,"7570","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7571",7,"Ya con ésta me despido\ncortando los Jericó;\naquí se acaban cantando, sí,\nlas mañanas de tú y yo.",151,2,23,149,"Las mañanitas",3,4,"o",2,0,-1,0,280,280,"7571","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7572",7,"Ya me despido, morena,\nte mando el adiós postrero;\naquí se acaban cantando\nlos versitos de tu dueño.",135,2,-1,149,"La despedida",0,4,"eo",-1,0,-1,0,280,280,"7572","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7573",7,"Me quisiera despedir,\npero no de tu amistad;\nno más te vengo a decir\nque este negro ya se va,\npero muy agradecido\nde tu fina voluntad.",135,2,-1,149,"Vil [Viborita de la mar; Al pasar por los laureles, Las torcazas",9,6,"a",-1,0,-1,0,280,280,"7573","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7574",7,"Ya me voy por lo divino,\npues también soy peregrino;\nya me voy a retirar,\nporque de veras te estimo;\nvoy a seguir mi camino,\nya te vine a saludar.",142,2,8,149,"Corrido de Huaxolotitlán",9,6,"a",21,0,-1,0,280,280,"7574","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7575",7,"Corté la flor del laurel\ny la puse a marchitar;\nera de comprender,\nblanca concha del mar;\ny aquí tienes a Manuel,\nque ya se va a retirar.",142,2,8,149,"El cascabel",9,6,"a",21,0,-1,0,280,280,"7575","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7576",7,"Josefina, fina, fina,\nfina, fina del vestido,\ny hasta luego, Carolina,\nya con ésta me despido.",146,2,7,149,"Mariquita, quita, quita",1,4,"io",101,0,-1,0,280,280,"7576","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7578",7,"Despedida te propuso\ntu marinero en el mar;\niba pasando el vapor\ncuando nos vieron pasar.",135,2,-1,149,"La Sanmarqueña",0,4,"a",21,0,-1,0,280,280,"7578","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7579",7,"Pajarillo, pajarillo,\nque canta en la madrugada;\naquí se acaba cantando\nmi canción enamorada.",145,2,17,149,"Pajarillo barranqueño",0,4,"aa",49,0,-1,0,281,281,"7579","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7580",7,"¡Ay de mí, Llorona!,\nLlorona tus ojos negros;\nya con ésta se despide\ntu negrito cariñoso.",147,2,11,149,"La Llorona",5,4,"oo",-1,0,-1,0,281,281,"7580","",0,"","","",35,0,0,[],"",""],["frenk_t3-n7581",7,"Ya me voy, sureña mía;\nme he tardado despidiendo,\nporque en la boca tenía\nun besito deteniendo;\nya mero te lo pedía,\npara írmelo comiendo.",142,2,8,149,"La sureña",9,6,"eo",52,0,-1,0,281,281,"7581","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7583",7,"Ya con ésta me despido,\nhora sí encontré mi amor;\ny aquí se acaban los versos\ndel “Pescado nadador”.",147,2,11,149,"El pescado nadador",3,4,"o",72,0,-1,0,281,281,"7583","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7584",7,"Ya con ésta me despido,\ndiciéndote: “Adiós, adiós”;\nquiero que recuerdes\nque fuimos amorcitos del mismo amor.",135,2,-1,149,"Amorcito consentido",3,4,"o",-1,0,-1,0,281,281,"7584","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7585",7,"Ya ninguna estrella brilla,\nla luna ya se opacó;\nrayando ya viene el día,\ny aquí el canto terminó.",135,2,-1,149,"Las mañanitas",3,4,"o",2,0,-1,0,281,281,"7585","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7586",7,"La luna para salir\nal sol le pide su audiencia,\ny yo para comenzar,\nseñores, pido licencia.",153,2,5,150,"Estrofa suelta",0,4,"ea",46,0,-1,0,282,282,"7586","",0,"","","",14,0,0,[],"",""],["frenk_t3-n7587",7,"Licencia pido, señores,\npara cantar mi canción;\ndedico a Huatabampo,\nme lo pide el corazón.",135,2,-1,150,"Corrido de Huatabampo",0,4,"o",31,0,-1,0,282,282,"7587","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7588",7,"Licencia para cantar\na esta Gloria le pido,\ny si no puedo entonar,\nuna copita de vino\ntendrán que irme a mercar.",142,2,8,150,"Zapateado",7,5,"a",21,0,-1,0,282,282,"7588","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7589",7,"Señores, pido licencia\npara empezar a cantar;\nno me vaya a equivocar\ny quede yo en vergüenza;\nno me vaya a festejar\nlo que dice la licencia.",138,2,6,150,"El huerfanito",9,6,"ea",-1,0,-1,0,282,282,"7589","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7590a",7,"Mi permiso me han de dar\npara cantar otros sones,\ny a ver si a medio cantar\nel pecho se me compone;\nsi me llego a equivocar,\npido a usted que me perdone.",136,2,4,150,"Mi permiso me han de dar; El siquisirí",9,6,"oe",613,0,-1,0,282,282,"7590a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7591",7,"Yo permiso les pido\ny también para cantar,\ny si no puedo entonar,\npido que se me perdone:\notros pueden cantar\nmientras mi voz se compone.",142,2,8,150,"Zapateado",9,6,"oe",613,0,-1,0,282,282,"7591","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7592",7,"Yo pido a la concurrencia\nque perdone mi osadía,\ny a todos pido clemencia\npara mi galantería.",136,2,4,150,"La morena",1,4,"ia",0,0,-1,0,283,283,"7592","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7593",7,"Hoy me hallo en esta región\npara saludar a ustedes;\npido con educación\nun ratito, si se puede,\ncantar en este salón\nentre hombres y mujeres.",142,2,8,150,"La guacamaya",9,6,"ee",-1,0,-1,0,283,283,"7593","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7594",7,"Ya llegué a estación Pérez,\ndonde me voy a embarcar;\nyo no diré que se puede,\npero si me dan lugar,\ncon el permiso de ustedes,\nseñores, quiero cantar.",142,2,8,150,"Zapateado",9,6,"a",21,0,-1,0,283,283,"7594","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7595",7,"Con licencia, valedores,\nvoy a cantar este son;\nguarden silencio, señores,\ny préstenme su atención,\ny también las bailadoras\nque están en esta función.",136,2,4,150,"Estrofa suelta",9,6,"o",31,0,-1,0,283,283,"7595","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7596",7,"Señores, voy a cantar;\ncon permiso, cantadores,\nhagan favor de escuchar;\nsaludo yo a los señores\nque se encuentran en este lugar.",136,2,4,150,"El fandanguito; Los chiles verdes; La liebre",7,5,"a",21,0,-1,0,283,283,"7596","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7597",7,"Con su permiso, señores,\nlos saluda un mexicano;\ncon mi sombrero en la mano,\npor estos alrededores\nsaludo a los espectadores\ny a todo el género humano.",142,2,8,150,"La guacamaya",9,6,"ao",81,0,-1,0,283,283,"7597","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7598b",7,"Para empezar a cantar\nse necesita primero\nel saberse acomodar (morena)\ny tener buen segundero.",142,2,8,150,"La morena",3,4,"eo",38,0,-1,0,283,283,"7598b","",0,"","","",6,0,0,[],"",""],["frenk_t3-n7599",7,"En esta casa hemos llegado\ncon respeto y sin faltar,\nque en casa de gente honrada\nasí se debe llegar.",136,2,4,150,"Estrofa suelta",0,4,"a",21,0,-1,0,283,283,"7599","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7600",7,"Por ser la primera vez\nque yo en esta casa canto,\ngloria al Padre, gloria al Hijo,\ngloria al Espíritu Santo.",136,2,4,150,"El siquisirí; La garza; Estrofa suelta",0,4,"ao",30,0,-1,0,284,284,"7600","",0,"machado_venezuela, andina_t1","","",10,0,0,[],"",""],["frenk_t3-n7601",7,"Al llegar a esta casa\nel pie derecho ponemos;\nmis compañeras y yo\nlas buenas noches daremos.",136,2,4,150,"Saludo para santo",0,4,"eo",127,0,-1,0,284,284,"7601","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7602",7,"Muy buenas tardes señores,\ntengan la bondad de oírme;\nno vengo a cantar honores,\nsólo vengo a divertirme\npor estos alrededores.",136,2,4,150,"El siquisirí",7,5,"oe",5,0,-1,0,284,284,"7602","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7603",7,"Mis amigos son testigos\nque aquí he venido a cantar;\nhoy, que estamos reunidos,\nes preciso el saludar:\n“Muy buenas noches, amigos”.",136,2,4,150,"El gusto",7,5,"io",-1,0,-1,0,284,284,"7603","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7604",7,"Saludar es mi deber\na los que presente están;\ngozaremos del placer,\nahora que venimos a gustar también.",140,2,12,150,"El aguajacado",3,4,"e",-1,0,-1,0,284,284,"7604","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7605",7,"Un día que salí a cazar\nle dije adiós a una niña;\nhoy me hallo en este lugar,\ny si mi alma se encariña,\nhoy los quiero saludar\nen la feria de la piña.",142,2,8,150,"La guacamaya",9,6,"ia",170,0,-1,0,284,284,"7605","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7606",7,"Tirananá, vengo yo\na cantar, aunque no sé:\n¡que siga y que siga el gusto\ny que viva Ometepec!",135,2,-1,150,"Ometepec",0,4,"e",-1,0,-1,0,284,284,"7606","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7607",7,"“¡Ave María!” dijo un ángel\ncuando a la gloria iba a entrar;\n“¡Ave María!” digo yo\npara empezar a cantar.",161,2,15,150,"Las mañanitas",0,4,"a",21,0,-1,0,284,284,"7607","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7608",7,"Que comienzo, que comienzo,\nno quisiera comenzar,\nporque el que comienza acaba,\ny yo no quiero acabar.",135,2,-1,150,"Que comienzo, que comienzo; La Llorona; María del Carmen; María, María; La Sanmarqueña",0,4,"a",21,0,-1,0,284,284,"7608","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7610",7,"Voy a empezar a cantar,\nluego les diré quién soy:\nyo soy el indio suriano,\nque para servirle estoy.",146,2,7,150,"El indio suriano",0,4,"o",112,0,-1,0,285,285,"7610","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7611",7,"Soy cantador de ustedes,\nque me anuncien: soy Rivera,\ny antes de llegar aquí\nle di vuelta a la alameda;\nsoy el servidor de ustedes\ny cantaré lo que pueda.",142,2,8,150,"Zapateado",9,6,"ea",266,0,-1,0,285,285,"7611","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7612",7,"Poniendo todo mi empeño\npara empezar a cantar,\ndirán que soy halagüeño\nyendo por ese lugar,\npues somos tlacotalpeños\npa lo que quieran mandar.",136,2,4,150,"El siquisirí",9,6,"a",21,0,-1,0,285,285,"7612","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7613",7,"Ya sea aquí o no sea aquí,\ndonde hemos venido a dar;\npues si fuere o no fuere,\nempecemos a cantar.",163,2,21,150,"El carnaval",3,4,"a",21,0,-1,0,285,285,"7613","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7614",7,"De México han mandado\nque no cantemos:\ncomo somos muchachos,\ncantar queremos.",135,2,-1,150,"Estrofa suelta",6,4,"eo",127,0,-1,0,285,285,"7614","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7615",7,"A ver si puedo o no puedo\nque aquí voy a comenzar;\nme dispensarán ustedes\nmi manera de cantar:\nse la aprendí a las mujeres\ncuando se van a bañar.",142,2,8,150,"El siquisirí",9,6,"a",21,0,-1,0,285,285,"7615","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7616",7,"Si supiera que cantando\nlos habría de divertir,\naunque perdiera el dormir,\ncantaría toda la noche.",142,2,8,150,"La guacamaya",5,4,"oe",-1,0,-1,0,285,285,"7616","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7617",7,"Si yo cantando, cantando,\ncantando me mantuviera,\ncantaría toda la noche\nhasta que me amaneciera.",135,2,-1,150,"La víbora; La callejera; Que comienzo que comienzo",0,4,"ea",44,0,-1,0,285,285,"7617","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7618",7,"Cupido me fue a ver\ndonde estaba trabajando:\nque si yo quería aprender\nversos para andar cantando,\nque me fuera yo con él\npara andarlos estudiando.",147,2,11,150,"El Cupido",9,6,"ao",33,0,-1,0,286,286,"7618","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7619",7,"Tengo verso sobre verso,\ny por verso no he de quedar:\ntengo una saca llena\ny otra por destapar.",142,2,8,150,"Estrofa suelta",0,4,"a",21,0,-1,0,286,286,"7619","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7620",7,"Echan versos sobre versos,\ny versos no han de faltar:\nTraigo una cajita llena\ny una que voy a empezar.",135,2,-1,150,"Al pasar por tu ventana",0,4,"a",21,0,-1,0,286,286,"7620","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7621",7,"Como versitos me pidan,\nversos traigo de a montón:\naquí traigo un morral lleno\ny un costal sin desatar,\ny en la copa del sombrero,\nlos que acabo de cantar.",155,2,14,150,"Delgadita de cintura",9,6,"a",21,0,-1,0,286,286,"7621","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7622",7,"Tengo un versito bonito,\nque me regaló el mexicano;\nde tantos versos que tengo,\nhasta los traigo en la mano.",142,2,8,150,"Estrofa suelta",0,4,"ao",81,0,-1,0,286,286,"7622","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7623",7,"En la inmensidad del agua\nfueron mis habitaciones;\na mí nunca se me acaban\nlos versos de mis canciones,\nque canto en esta tonada.",138,2,6,150,"La sirena",7,5,"aa",-1,0,-1,0,286,286,"7623","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7624",7,"La sirena en el mar cantaba,\nluciendo su cotón pinto;\nyo a ninguno le hago mal,\nni tampoco me les hinco;\ntraigo versos pa cantar\ndoscientos setenta y cinco.",142,2,8,150,"Estrofa suelta",9,6,"io",559,0,-1,0,286,286,"7624","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7625a",7,"Yo no canto porque sé,\nni porque mi voz sea buena:\ncanto porque tengo gusto,\nen mi tierra y en la ajena.",149,2,20,150,"El Quelite; Cuatro esquinas tiene un catre; La Sanmarqueña; Estrofa suelta",0,4,"ea",59,0,-1,0,286,286,"7625a","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7625c",7,"Me vine de la Huasteca\ny a rodar como la arena;\nyo no canto porque sepa,\nni porque mi voz sea buena:\ncanto para divertirme\nen mi tierra y en la ajena.",138,2,6,150,"La madrugada",9,6,"ea",59,0,-1,0,287,287,"7625c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7626",7,"Yo no canto porque sé,\nni porque canto bonito:\ncanto porque soy alegre,\nel cantar es apetito.",142,2,8,150,"Zapateado",0,4,"io",119,0,-1,0,287,287,"7626","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7627",7,"Yo no canto porque sepa,\nni porque yo sea poeta;\nsolamente sé decir\nque a mí nadie me da mueca.",135,2,-1,150,"Soy de Zacatula",0,4,"ea",-1,0,-1,0,287,287,"7627","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7628",7,"Me dicen que en Alvarado,\nestá un poeta popular:\ncon ése sí no he cantado;\nfuera de ése, en general,\nhe recorrido el estado,\nestuve en la capital.",142,2,8,150,"Zapateado",9,6,"a",1,0,-1,0,287,287,"7628","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7629",7,"Entre buenos cantadores\nhe paseado con esmero,\ndándoles distribuciones\nde todito el mundo entero\ny toditas las naciones\nque tiene el reino extranjero.",141,2,1,150,"La Petenera",9,6,"eo",38,0,-1,0,287,287,"7629","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7630",7,"Un saludo muy decente\nde Tlalixcoyan portamos;\nlo hacemos galantemente\nporque muy pronto nos vamos,\ny a todos los concurrentes\nmuy buenas noches les damos.",136,2,4,150,"El siquisirí",9,6,"ao",116,0,-1,0,287,287,"7630","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7631",7,"Corté la flor de la cud\ny también la del tabaco.\nMe voy para Veracruz,\na ver si allá me emborracho,\ncantando “El pájaro cú”\ncon toditos los muchachos.",142,2,8,150,"El pájaro cú",9,6,"ao",-1,0,-1,0,287,287,"7631","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7632",7,"Vámonos muchachos,\nque ya son las nueve:\nno venga la ronda,\ny a todos nos lleve.",136,2,4,150,"Naranjas y limas; Estrofa suelta",0,4,"ee",474,0,-1,0,288,288,"7632","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7633",7,"Pues arriba y arriba,\nyo ya me voy;\npase usted buenas noches\nmañana y hoy.",136,2,4,150,"La bamba",6,4,"o",112,0,-1,0,288,288,"7633","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7634",7,"Bomba me pides,\nbomba te doy:\ntú ya te quedas,\nyo ya me voy.",147,2,11,150,"Estrofa suelta",6,4,"o",112,0,-1,0,288,288,"7634","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7635",7,"Bomba me das,\nbomba te doy,\ny con el saludo\nme voy.",147,2,11,150,"Estrofa suelta",6,4,"o",112,0,-1,0,288,288,"7635","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7637",7,"Acaban de dar las nueve\nen catedral las campanas;\nme voy a dormir un poco,\nseñores, hasta mañana.",135,2,-1,150,"La mulita",0,4,"aa",-1,0,-1,0,288,288,"7637","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7638",7,"Me despido del violín\ny también de la guitarra,\nporque me voy a dormir:\nseñores, hasta mañana.",140,2,12,150,"El gusto",0,4,"aa",-1,0,-1,0,288,288,"7638","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7639",7,"Ya con ésta me despido,\nflorecita de alvellana;\ncon el sombrero en la mano,\nseñores, hasta mañana.",160,2,19,150,"El indio mexicano",0,4,"aa",4,0,-1,0,288,288,"7639","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7640",7,"Ya con ésta me despido,\nrebanando una manzana;\nya los vine a despertar:\nseñores, hasta mañana.",135,2,-1,150,"Las mañanitas; La Zandunga",0,4,"aa",4,0,-1,0,288,288,"7640","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7641",7,"Voy a echar mi despedida\npor los ojos de la luna;\nmuchas gracias, compañeros,\nque [nos] dimos una y una.",137,2,3,150,"La Malagueña",0,4,"ua",56,0,-1,0,289,289,"7641","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7642",7,"Voy a dar la despedida\ncomo la de un marinero:\ncon su sombrero en la mano,\n“Hasta luego, compañeros”.",142,2,8,150,"La Sanmarqueña",0,4,"eo",-1,0,-1,0,289,289,"7642","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7643",7,"Voy a echar la despedida,\nporque ya no sé otra cosa,\nque en el panteón del olvido\nyo fui el que pinté una rosa.",142,2,8,150,"Chilena de Jamiltepec; La Malagueña cu rreña; María del Carmen",0,4,"oa",63,0,-1,0,289,289,"7643","",0,"","","",8,0,0,[],"",""],["frenk_t3-n7644",7,"Y se acaban ya las coplas,\nterminando la canción;\ncon un beso a las pelonas,\ny que siga la función.",135,2,-1,150,"Ya no lloverá, pelonas",0,4,"o",31,0,-1,0,289,289,"7644","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7645",7,"Ya me voy a despedir,\nrobándome una sandía;\nya los vine a divertir,\nnos veremos otro día.",135,2,-1,150,"La Zandunga",1,4,"ia",0,0,-1,0,289,289,"7645","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7646",7,"Con esta otra despedida\nlos voy a desengañar;\n¿qué más quieren que les digan?,\n¿todavía queren buscar?\ntraigo besos.....................\ny arenas trae de la mar.",135,2,-1,150,"Al pasar por los laureles",9,6,"a",21,0,-1,0,289,289,"7646","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7647",7,"Ya con ésta me despido,\nme despido de mi amor;\nya conocí al licenciado\ny también al gobernador.",142,2,8,150,"Estrofa suelta",0,4,"o",72,0,-1,0,289,289,"7647","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7648",7,"Ya me voy, ya me despido,\ncon sentimiento y dolor;\nvoy a darle vuelta al mundo\ny a vacilar con mi amor.",135,2,-1,150,"Alza los ojos",0,4,"o",72,0,-1,0,289,289,"7648","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7649",7,"En el irme y el quedarme,\nestoy por no despedirme:\nquiero irme y quiero quedarme,\npero ni quedarme ni irme.",135,2,-1,150,"La Sanmarqueña; Negra, ¿dónde están los lazos?",1,4,"ie",184,0,-1,0,289,289,"7649","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7650",7,"Todos echan despedida,\npero como yo, ningun[a]:\nuna, dos, tres, cuatro, cinco,\ncinco, cuatro, tres, dos, una,\ncuatro por siete veintiocho,\ntres por siete son veintiuna.",136,2,4,150,"El siquisirí’",9,6,"ua",56,0,-1,0,290,290,"7650","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7651",7,"Todos echan despedida,\npero no como la mía:\nen la punta de la lengua\ntraigo a la Virgen María.",135,2,-1,150,"Costeña",0,4,"ia",0,0,-1,0,290,290,"7651","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7652",7,"Voy a echar la despedida,\nla que echó Cristo en Belén:\n“Adiós por todos los siglos\ny de los siglos, amén”.",142,2,8,150,"Que comienzo, que comienzo; La Sanmarqueña; Estrofa suelta",0,4,"e",242,0,-1,0,290,290,"7652","",0,"","","",8,0,0,[],"",""],["frenk_t3-n7653",7,"Despedida no les doy,\nporque no la traigo aquí:\nse la dejé al Santo Niño\ny al Señor de Mapimí.",135,2,-1,150,"El corrido de Cananea",0,4,"i",23,0,-1,0,290,290,"7653","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7655",7,"Con ésta y no más ésta,\nporque mi amante\ncon los ojos me dice\nque ya no cante.",142,2,8,150,"Negra del alma",6,4,"ae",47,0,-1,0,290,290,"7655","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7656",7,"La reina mora tiene\nen su turbante (¡zamba que le da!)\nun letrero que dice\nque ya no cante (¡zamba que le da!).",146,2,7,150,"La zamba",3,4,"a",47,0,-1,0,290,290,"7656","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7657",7,"Ya se va y se despide Rosita,\nse despide con gusto y afán,\nya se va la pajarerita:\n¿quién de ustedes con ella se va?",135,2,-1,150,"La pajarera",3,4,"a",-1,0,-1,0,290,290,"7657","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7658",7,"Ya me despido, señores,\nya se va el gallo jaspeado;\nya me cansé de cantar\ny pronto voy a regresar.",135,2,-1,150,"El gallo jaspeado",5,4,"a",21,0,-1,0,291,291,"7658","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7659",7,"Porque me voy a lo verde,\npara consolar a un triste\ncanta el pajarillo alegre;\ncon ésta me despido,\nporque me voy a lo verde.",137,2,3,150,"El veinte",7,5,"ee",-1,0,-1,0,291,291,"7659","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7660",7,"Y aquí me despido,\nvámonos andando;\nvuelen pajarillos,\nvuelen vigilando.",136,2,4,150,"El jarabe loco",0,4,"ao",33,0,-1,0,291,291,"7660","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7661",7,"Ya con ésta me despido,\nderecho para otro punto,\ndonde les voy a cantar\nestas quejas que hoy apunto.",161,2,15,150,"Cuatro esquinas tiene un catre",0,4,"uo",36,0,-1,0,291,291,"7661","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7662",7,"Ya me voy a despedir,\nporque mi camino es largo;\nsólo les quiero decir\nque me voy para el santuario,\ny si me llego a morir,\nme recen un novenario.",136,2,4,150,"El siquisirí; El Balajú; Cuando a despedirme fui; La guacamaya; Mi permiso me han de dar; Mis palabras se desatan,",9,6,"ao",25,0,-1,0,291,291,"7662","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7663",7,"Voy a echar la despedida\npara que se vayan yendo;\n¡cómo siento el que se vayan! (¡ay, vida mía!),\nque a mí me dejan queriendo.",135,2,-1,150,"El carpintero",3,4,"eo",52,0,-1,0,291,291,"7663","",0,"","","",8,0,0,[],"",""],["frenk_t3-n7664",7,"Se las vuelvo a referir\ncon tinta y papel sellado,\nmas no dejen de saber\nque el que cantó aquí es su criado.",135,2,-1,150,"Valona de las juimas",0,4,"ao",14,0,-1,0,291,291,"7664","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7665",7,"Allá les va la despedida,\nque soy hombre de palabra;\neste corrido es compuesto\npor el trovador Grijalva.",164,2,16,150,"Corrido de Santanón",0,4,"aa",-1,0,-1,0,291,291,"7665","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7666",7,"Ya con ésta me despido\npor la sombra de una higuera;\nestos versos son compuestos\npor Filipito Rivera.",161,2,15,150,"Corrido de José Villanueva",0,4,"ea",44,0,-1,0,292,292,"7666","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7667",7,"Ya con ésta me despido\npor las orillas del plan;\nestos versos son compuestos\npor el señor Villafán.",137,2,3,150,"El riqui-riqui",0,4,"a",147,0,-1,0,292,292,"7667","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7668",7,"Mas en fin, ya me despido,\nyéndome para La Unión;\naquí se acaban los versos\nque compuso Palemón.",146,2,7,150,"El toro’T",0,4,"o",31,0,-1,0,292,292,"7668","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7669",7,"Aquí terminan los versos,\ny si han logrado gustar,\nson compuestos por Lozano,\nun coplero popular.",135,2,-1,150,"Corrido de El cuartelazo felicista; Corrido de La toma de México por el general Pablo González",0,4,"a",21,0,-1,0,292,292,"7669","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7670",7,"Ya con ésta me despido,\ncon apretón de manos;\nestos versos son compuestos\npor los nobles mexicanos.",135,2,-1,150,"De las tres que vienen áhi",0,4,"ao",318,0,-1,0,292,292,"7670","",0,"frenk_t4","","",72,0,0,[],"",""],["frenk_t3-n7671",7,"Adiós, señores y amigos,\nlindo barrio de Cochoapa;\nesta chilena es compuesta\npor el indio de Igualapa.",135,2,-1,150,"El tiburón",0,4,"aa",297,0,-1,0,292,292,"7671","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7672",7,"Estos versos los compuse\nen Culiacán, Sinaloa;\nsi en algo puedo servirles,\nyo soy Victorio Gamboa.",135,2,-1,150,"A Canelas",0,4,"oa",614,0,-1,0,292,292,"7672","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7673",7,"“Ya me voy, ya me despido,\ny se los diré cantando”,\nasí me dijo Cupido\ncuando andaba trabajando.",135,2,-1,150,"El rosario de mi suegra",1,4,"ao",33,0,-1,0,292,292,"7673","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7674",7,"Ya con ésta me despido,\ncon esta triste canción,\nque si no fue bien cantada,\nperdonen de corazón.",135,2,-1,150,"En busca de Margarita",0,4,"o",31,0,-1,0,292,292,"7674","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7675",7,"Estas son “Las campanitas”,\nlas que acabé de cantar;\npero si están mal trovadas,\ncreo que me han de dispensar.",135,2,-1,150,"Las campanitas",0,4,"a",21,0,-1,0,292,292,"7675","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7676",7,"Ya me voy a despedir,\ndispensen lo mal trovado:\nno soy práctico en corridos,\npero soy aficionado.",135,2,-1,150,"Corrido de La feria estatal de Oaxaca; Corrido de La muerte del general Benigno Serratos",0,4,"ao",14,0,-1,0,293,293,"7676","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7677",7,"Ya se despide su gallo,\ny les dejo mi canción;\ncuídense bien, chiquititas,\nguárdenme su corazón.",135,2,-1,150,"El dicharachero",0,4,"o",31,0,-1,0,293,293,"7677","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7678",7,"Adiós, muchachos de Lerdo,\nde Gómez y de Torreón;\nya se van los garroteros,\nya se acabó la función.",135,2,-1,150,"La rielera",0,4,"o",31,0,-1,0,293,293,"7678","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7679",7,"Ya con ésta me despido\npor las hojas de un laurel;\naunque quieran o no quieran,\n¡vivan siempre los del riell",135,2,-1,150,"vivan siempre los del riell [La Julia",0,4,"e",-1,0,-1,0,293,293,"7679","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7680",7,"Ya me voy a despedir\ncon mucho gusto y afán;\n¡que siga y que siga el gusto\ny que viva Huehuetán!",135,2,-1,150,"Arbolito del camino; Arriba, caballo bayo",0,4,"a",147,0,-1,0,293,293,"7680","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7681",7,"Ya me voy a despedir;\nme gusta la voz del bajo\ncuando le dan borloneado;\nme acuerdo de mis terrenos,\nSan Nicolás Maldonado.",135,2,-1,150,"Por lo alto doy cincuenta",7,5,"ao",14,0,-1,0,293,293,"7681","",0,"","","",13,0,0,[],"",""],["frenk_t3-n7682",7,"Yo ya me despido, amigo;\nya sabe lo que pasó:\nque yo ya vendí la mula,\ny aquí el cuento se acabó.",135,2,-1,150,"La mulita",3,4,"o",2,0,-1,0,293,293,"7682","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7683",7,"En fin, yo ya me despido,\nya me voy para El Zapote;\náhi se quedará sufriendo\nel mentado zopilote.",146,2,7,150,"El zopilote’",0,4,"oe",292,0,-1,0,293,293,"7683","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7684",7,"Este son de “Las conchitas”\nque estamos cantando aquí,\ncon palabras muy bonitas\nsoy despedido de aquí,\nporque han sido muy bonitas.",136,2,4,150,"Las conchitas",7,5,"ia",-1,0,-1,0,293,293,"7684","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7685",7,"Me despido saludando:\nadiós, muchachas bonitas;\nsi no les gusta el huapango,\nadiós, quédense solitas;\ny aquí se acaban cantando\nlos versos de “Las conchitas”.",136,2,4,150,"Las conohitas",9,6,"ia",258,0,-1,0,293,293,"7685","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7686",7,"Yo soy un hombre sincero\npara esto de improvisar;\nno digan que soy soltero,\nporque le voy a explicar,\nporque el son de “Los arrieros’\nya le acabo de cantar.",136,2,4,150,"Los arrieros",9,6,"a",21,0,-1,0,294,294,"7686","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7687",7,"Por áhi va la despedida\nen el llano y lo parejo;\nyo me vuelvo a mi guarida,\nno más un recuerdo dejo\na toditos mis amigos:\nel “Corrido del conejo”.",135,2,-1,150,"El conejo",9,6,"eo",264,0,-1,0,294,294,"7687","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7688",7,"Ya con ésta me despido,\nnos vemos hasta mañana;\naquí les dejo los versos\ndel corrido de “La calandria”.",142,2,8,150,"La calandria",0,4,"aa",-1,0,-1,0,294,294,"7688","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7689",7,"Ya con ésta me despido\nal pie de una azucenita;\nya les canté a mis amigos\nla canción de mi “Juanita”.",138,2,6,150,"La Juanita",0,4,"ia",50,0,-1,0,294,294,"7689","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7690",7,"Ya con ésta me despido,\ncon el sombrero de lado;\nya les canté a mis amigos\n“El novillo despuntado”.",137,2,3,150,"El novillo despuntado",0,4,"ao",14,0,-1,0,294,294,"7690","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7692",7,"Linternas y linternitas\nde toditos los colores,\nya se los canté a mis cuatas\ny a todos mis valedores.",135,2,-1,150,"Linternas y linternitas",0,4,"oe",5,0,-1,0,294,294,"7692","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7693",7,"Con ésta, y no digo más,\ncomo dijo un pajarito,\npues me voy a retirar:\nya los divertí un ratito;\naquí se acaban cantando\nlos versos del “Venadito”.",147,2,11,150,"El venadito",9,6,"io",119,0,-1,0,294,294,"7693","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7694",7,"Ya con ésta me despido,\nhermosa flor de alelía,\nque aquí se acaban cantando\nlos versos de “La sandía”.",137,2,3,150,"La sandía",0,4,"ia",0,0,-1,0,294,294,"7694","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7695",7,"Ariles y más ariles,\ncantaba un pájaro cú;\naquí se acaba cantando\neste son del “Balajú”.",136,2,4,150,"El Balajú",0,4,"u",73,0,-1,0,294,294,"7695","",0,"","","",24,0,0,[],"",""],["frenk_t3-n7696",7,"Ya con ésta me despido,\npor las hojas de un quebracho,\ny aquí se acaban cantando\nlos versitos del “Borracho”.",137,2,3,150,"El borracho",3,4,"ao",-1,0,-1,0,295,295,"7696","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7697",7,"En fin, yo ya me despido\ncon un vaso de aguardiente;\naquí se acaban cantando\nlos versitos del “Valiente”.",142,2,8,150,"El valiente",0,4,"ee",15,0,-1,0,295,295,"7697","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7698",7,"Ya con ésta me despido,\nvámonos, que estoy borracho;\nque se acabe esta chilena,\nlos versos de “El toro gacho”.",142,2,8,150,"El toro",0,4,"ao",310,0,-1,0,295,295,"7698","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7699",7,"Allá va la despedida,\ndeshojando un clavelito;\naquí se acaban cantando\nlos versos del “Sombrerito”.",154,2,28,150,"El sombrerito",0,4,"io",119,0,-1,0,295,295,"7699","",0,"","","",25,0,0,[],"",""],["frenk_t3-n7700",7,"Aquí va la despedida,\nmirando una amapolita;\naquí se acaban cantando\nlos versos de “La mulita”.",135,2,-1,150,"La mulita",0,4,"ia",50,0,-1,0,295,295,"7700","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7701",7,"Ya con ésta me despido,\ndeshojando una limita;\ny aquí se acaban cantando\nlos versos de mi “Chinita”.",137,2,3,150,"La chinita",3,4,"ia",50,0,-1,0,295,295,"7701","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7702",7,"Ya con ésta me despido,\nentre perfume de azahares;\naquí se acaban\n“Los barandales”.",147,2,11,150,"Los barandales",3,4,"ae",-1,0,-1,0,295,295,"7702","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7703",7,"Ya con ésta me despido,\npor áhi está un campo verde;\ny aquí se acaba cantando\nel son del “Muchacho alegre”.",137,2,3,150,"El muchacho alegre",3,4,"ee",-1,0,-1,0,295,295,"7703","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7704",7,"Ya con ésta me despido,\nal pasar por el saltito;\ny aquí se acaban cantando\nlos versos del “Pajarito”.",137,2,3,150,"Pajarillo barranqueño; El pajarillo",3,4,"io",119,0,-1,0,295,295,"7704","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7705",7,"Ya con ésta me despido,\npor las ramas de una higuera,\ny aquí se acaban cantando\nversos de “La Canelera”.",137,2,3,150,"La canelera",3,4,"ea",44,0,-1,0,296,296,"7705","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7706",7,"Ya con ésta me despido,\ncon mi sombrero de lado,\ny aquí se acaban cantando\nlos versitos del “Pelado”.",161,2,15,150,"El pelado",3,4,"ao",-1,0,-1,0,296,296,"7706","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7707",7,"Ya con ésta me despido (mi bien),\npor las faldas de un sombrero,\ny aquí se acaban cantando (mi bien)\nlos versitos de “Laredo”.",137,2,3,150,"Corrido de Laredo",3,4,"eo",-1,0,-1,0,296,296,"7707","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7708",7,"Ya con ésta me despido,\npor las barbas de un rebozo;\naquí se acaban cantando\nlos versitos del “celoso”.",137,2,3,150,"El celoso",0,4,"oo",160,0,-1,0,296,296,"7708","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7709",7,"Ya con ésta me despido,\npor las hojas de un manzano;\naquí se acaban cantando\nlos versitos de “El gusano”.",137,2,3,150,"El gusano",0,4,"ao",-1,0,-1,0,296,296,"7709","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7710",7,"Ya con ésta me despido\nen las cumbres de un encino;\naquí se acaba el corrido\nde los “Versos del destino”.",135,2,-1,150,"Corrido de los destinos",1,4,"io",-1,0,-1,0,296,296,"7710","",0,"frenk_t4","","",72,0,0,[],"",""],["frenk_t3-n7711",7,"Ya con ésta me despido,\nal salir de la garita,\ny aquí se acaban cantando\nlos versitos de “La indita”.",137,2,3,150,"La indita",3,4,"ia",50,0,-1,0,296,296,"7711","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7712",7,"Soy como el ave de paso,\nsemejante al alacrán;\naquí se acaban cantando\nlos versos del “Gavilán”.",135,2,-1,150,"El gavilán",0,4,"a",147,0,-1,0,296,296,"7712","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7713",7,"Vuela, vuela, palomita,\nvuela aunque vayas herida;\ny aquí se acaban cantando\nlos versos de “La escondida”.",135,2,-1,150,"La sscond’da",3,4,"ia",37,0,-1,0,296,296,"7713","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7714",7,"Aquí se acaban cantando\nlos versos de las pelonas,\nque hoy la moda están usando\nhasta las viejas jamonas.",135,2,-1,150,"Ya no lloverá, pelonas",1,4,"oa",549,0,-1,0,296,296,"7714","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7716",7,"Ya con ésta me despido,\ny si no lo hago, no como;\nseñores, aquí se acaban\nlos versitos del “Palomo”.",136,2,4,150,"El palomo",0,4,"oo",349,0,-1,0,297,297,"7716","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7717",7,"Allá va la despedida,\npor debajo del palmero;\naquí se acaban cantando\nlos versos del “Periquero”.",135,2,-1,150,"El perico",0,4,"eo",38,0,-1,0,297,297,"7717","",0,"","","",25,0,0,[],"",""],["frenk_t3-n7718",7,"Ya con ésta me despido,\ncon gusto y con alegría,\ny aquí se acaban cantando\nlos versitos de María.",162,2,27,150,"El baile de la muñeca",3,4,"ia",0,0,-1,0,297,297,"7718","",0,"","","",72,0,0,[],"",""],["frenk_t3-n7719",7,"Ahora acabo de llegar del Ahualulco,\ncantando les digo ya\nque este son del moreliano\nhasta aquí se terminó.",136,2,4,150,"El Ahualulco",3,4,"o",-1,0,-1,0,297,297,"7719","",0,"","","",12,0,0,[],"",""],["frenk_t3-n7720",7,"Ahora acabo de llegar del Ahualulco,\ndándoles la despedida,\nporque aquí se acaba el son,\ny el jarabe se termina.",136,2,4,150,"El Ahualulco",3,4,"ia",-1,0,-1,0,297,297,"7720","",0,"","","",12,0,0,[],"",""],["frenk_t3-n7721",7,"Vuela, vuela, vuela,\nvuela, pa la playa;\npor el camino nos vemos,\ncantando “La Guacamaya”.",136,2,4,150,"La guacamaya",0,4,"aa",404,0,-1,0,297,297,"7721","",0,"","","",17,0,0,[],"",""],["frenk_t3-n7722",7,"Huapanguero, huapanguerito,\nhuapanguero, ¡ay qué bonito!,\nhuapanguero, ¡ay, ya merito\nse acaba mi huapanguito!",136,2,4,150,"El huapanguero",0,4,"io",119,0,-1,0,297,297,"7722","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7723",7,"Mi huapango se acabó,\nse acabó mi huapanguerito,\npero pronto ha de regresar\ncon su son tan sabrosito.",136,2,4,150,"El huapanguero",0,4,"io",119,0,-1,0,297,297,"7723","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n7724",7,"Y aquí va la despedida,\nárboles que van floreando;\n¡que vivan los cantadores\ny el maestro que está tocando!",142,2,8,150,"La Juanita",3,4,"ao",33,0,-1,0,297,297,"7724","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7725",7,"Aquí hemos venido,\nporque hemos llegado\nlos dos por distinto lado;\ncantando canciones\npasamos la vida,\nun poco más divertida.",135,2,-1,150,"Corrido del descarrilamiento",9,6,"ia",37,0,-1,0,298,298,"7725","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7726",7,"Oigan, que les traigo aquí,\nigual que un ramo de flores,\nlas coplas que en mi país\nentonan los trovadores.",135,2,-1,150,"Estrofa suelta",0,4,"oe",5,0,-1,0,298,298,"7726","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7727",7,"Ahórale, indita, sí,\néntrale con calor,\nque de Guerrero vinimos,\nhicimos, trujimos\nesta canción.",146,2,7,150,"Indita del alma",7,5,"o",-1,0,-1,0,298,298,"7727","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7728",7,"De esta tierra de Cocula,\nque es el alma del mariachi,\nvengo yo por mi cantar;\nvoy camino a Aguascalientes,\na la feria de San Marcos,\na ver lo que puedo hallar.",145,2,17,150,"Cocula",9,6,"a",21,0,-1,0,298,298,"7728","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7729",7,"Jarocho yo soy, señores,\nque ahora acabo de llegar;\nde la tierra de las flores\nyo les traigo este cantar,\ncon trino de ruiseñores\ny con arrullos del mar.",136,2,4,150,"El siquisirí; El jarocho",9,6,"a",21,0,-1,0,298,298,"7729","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7730",7,"Vengo de alto, señores,\nde la tierra michoacana,\nles vengo entonando sones\nal compás de mi jarana.",145,2,17,150,"El maracumbé",0,4,"aa",4,0,-1,0,298,298,"7730","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7732a",7,"De Altamira, Tamaulipas,\ntraigo este alegre son;\nal son del viejo violín\nmi jarana traigo yo.",135,2,-1,150,"Estrofa suelta",0,4,"o",-1,0,-1,0,299,299,"7732a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7732b",7,"De Altamira, Tamaulipas,\ntraigo esta alegre canción,\ny al son de [1] viejo violín\nmis jaranas canto yo,\na las mujeres bonitas,\nque son de mi adoración.",159,2,26,150,"El mil amores",9,6,"o",-1,0,-1,0,299,299,"7732b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7734",7,"Como soy buen misionero,\nyo vengo de La Misión;\ny vengo desde Guerrero,\npreguntando por el son\ndel “Pájaro carpintero”.",136,2,4,150,"El pájaro carpintero",7,5,"eo",38,0,-1,0,299,299,"7734","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7735",7,"Éste es “El zopilotito”\nde Ayahualco de Guerrero,\nque lo cantan nuestros indios\ncon su acento lastimero.",146,2,7,150,"El zopilote",0,4,"eo",38,0,-1,0,299,299,"7735","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7736",7,"Éste es “El capulinero’;\nque se canta por el plan,\nóiganlo muy bien, señores,\nel son de Tecalitlán.",145,2,17,150,"El capulinero",0,4,"a",147,0,-1,0,300,300,"7736","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7737",7,"Este son que estoy cantando\ncon todo mi corazón\nse baila en todo Guerrero:\nel son del “Toro rabón”.",146,2,7,150,"El toro rabón",0,4,"o",31,0,-1,0,300,300,"7737","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7738",7,"Voy a cantar este son,\n“El jarabe de la peña”,\nque cantan las tapatías\ny bailan las moreleñas.",136,2,4,150,"El Ahualulco",0,4,"ea",-1,0,-1,0,300,300,"7738","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7739",7,"Como soy tamaulipeco,\ny al son del tulipán,\nal compás de mi jarana\nvoy a entonar “El caimán”.",135,2,-1,150,"El alegre tampiqucño",0,4,"a",147,0,-1,0,300,300,"7739","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7740",7,"Lo digo como hermano:\ncon toda el alma,\ncomo veracruzano,\ncanto “La bamba”.",136,2,4,150,"La bamba",6,4,"aa",-1,0,-1,0,300,300,"7740","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7741",7,"Yo le canto “La bamba’\ncon gratitud,\nporque así la cantamos\nen Veracruz,",136,2,4,150,"La bamba",6,4,"u",-1,0,-1,0,300,300,"7741","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7742",7,"Si me canto “La bamba”\ncomo morocho,\ny me sale del alma,\npues soy jarocho.",136,2,4,150,"La bamba",6,4,"oo",424,0,-1,0,300,300,"7742","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7743",7,"No diré que nunca peco,\nporque soy un ser humane,\noigan la voz de un huasteco\ncon su instrumento en la mano,\ncantando “El Tepetzintleco”\ny a estilo veracruzano.",136,2,4,150,"El tepetzintleco; La huazanga",9,6,"ao",81,0,-1,0,300,300,"7743","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7744",7,"De los sones más bonito¿\nque cantan los jarochos,\npor ejemplo “El fandanguito”\nes un lindo son jarocho.",136,2,4,150,"El fandanguito",0,4,"oo",-1,0,-1,0,300,300,"7744","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7745",7,"El son del “Tilingo lingo-'\nes un baile improvisado,\nque se baila muy bonito\nen el puerto de Alvarado.",136,2,4,150,"El tilingo-lingo",0,4,"ao",14,0,-1,0,300,300,"7745","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7746",7,"¡Ay, qué bonito, qué bonito y qué bonito\nes este son, canción de “La yerbabuena”!,\nque hay un compás, un compás muy suavecito,\nque se baila en toda la tierra porteña.",136,2,4,150,"La yerbabuena",3,4,"ea",-1,0,-1,0,301,301,"7746","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7747",7,"De Tamaulipas a California,\nSonora y Juárez, Lerdo y Torreón,\ndesde Durango hasta Sinaloa\nbailan redowa con animación.",159,2,26,150,"Redowa",3,4,"o",31,0,-1,0,301,301,"7747","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7748",7,"Como tengo buena fama\ny buena controlación,\nal compás de mi jarana\nvoy a dedicar el son\na mi patria mexicana.",136,2,4,150,"La Llorona",7,5,"aa",4,0,-1,0,301,301,"7748","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7749",7,"Este son que está empezando\nlo vamos a dedicar;\nse lo diremos cantando;\nhoy mismo lo han de escuchar.",136,2,4,150,"Estrofa suelta",1,4,"a",21,0,-1,0,301,301,"7749","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7750",7,"Esta canción de la niña\ntiene versos de virtud,\ny a los señores que la oyen\nse las canto a su salud.",135,2,-1,150,"Baile de la muñeca; Corrido de Juanita Alvarado; Cuatro esquinas tiene un catre",0,4,"u",278,0,-1,0,301,301,"7750","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7751",7,"Yo les canto “La Bamba”\na toda hora,\nporque va dedicada\na la señora.",136,2,4,150,"La bamba",6,4,"oa",107,0,-1,0,301,301,"7751","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7752",7,"En el nombre sea de Dios\ny de la Virgen María,\nvoy a cantar estos versos,\nlos versos de “La sandía”.",137,2,3,150,"La sandía",0,4,"ia",0,0,-1,0,301,301,"7752","",0,"","","",7,0,0,[],"",""],["frenk_t3-n7753",7,"Arreboles me han pedido,\ny arreboles he de dar;\nprimero supe arreboles\nque saberme persignar.",145,2,17,150,"Estrofa suelta",0,4,"a",21,0,-1,0,301,301,"7753","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7755",7,"Voy a dar mis borradores,\na ver si puedo entonar;\nlas frases no son autores (sá\ncon que me quiero expresar:\nel huapango de “Las flores”\ncon gusto voy a cantar.",139,2,2,150,"Las flores",9,6,"a",21,0,-1,0,301,301,"7755","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7756",7,"Pues yo les digo, señores,\nque aquí me encuentro solito;\na la fuente de las flores\nvoy cantando “El bejuquito”,\npues trinan los ruiseñores.",139,2,2,150,"El bejuquito",7,5,"oe",5,0,-1,0,302,302,"7756","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7757",7,"Aunque mi voz no sea buena,\npero les estoy cantando,\ny el decirlo me da pena,\nque escuchen este huapango\nque traigo yo: es “La azucena”.",136,2,4,150,"La azucena",7,5,"ea",59,0,-1,0,302,302,"7757","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7758",7,"Señores, voy a cantar\nel huapango del “Mosquito”:\nvamos a decir verdad\nde este pobre animalito.",135,2,-1,150,"El mosquito",0,4,"io",119,0,-1,0,302,302,"7758","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7759",7,"Señores, pongan cuidado\nlo que les voy a cantar:\nlos versos del “Guaco Chano”,\nque hoy acaba de llegar.",143,2,18,150,"El guaco Chano",0,4,"a",21,0,-1,0,302,302,"7759","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7760",7,"Les voy a cantar en breve\ncon todo mi corazón\nlos versos del “Aguanieve”,\nque me llenan de ilusión,\ny mi pecho se conmueve.",138,2,6,150,"El aguanieve",7,5,"ee",474,0,-1,0,302,302,"7760","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7761",7,"Los versos del “Aguanieve”\nse cantan sin compromiso;\nagua que del cielo llueve\nse convierte en granizo\ncantándote “El aguanieve”.",139,2,2,150,"El aguanieve",7,5,"ee",474,0,-1,0,302,302,"7761","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7762",7,"Sólo que mi mente peque,\nya no cortaré más flores;\nsólo que la mar se seque,\npues, óiganme bien, señores,\nse terminará “El querreque”.",138,2,6,150,"El querreque",7,5,"ee",615,0,-1,0,302,302,"7762","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7763",7,"Cuando canto “La bamba”\nme siento ufano,\nporque sé que es el himno\nveracruzano.",136,2,4,150,"La bamba",6,4,"ao",81,0,-1,0,302,302,"7763","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7764",7,"Yo les canto “La bamba”\nsin pretensión,\npues me sale de adentro\ndel corazón.",136,2,4,150,"La bamba",6,4,"o",31,0,-1,0,302,302,"7764","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7765",7,"Aunque soy chiquitito,\nde inspiración,\ntambién canto “La bamba”\nde corazón.",136,2,4,150,"La bamba",6,4,"o",31,0,-1,0,302,302,"7765","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7766",7,"Cuando canto “La bamba”\nyo estoy contento,\nporque yo me acompaño\ncon mi instrumento.",147,2,11,150,"La bamba",6,4,"eo",94,0,-1,0,303,303,"7766","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7767",7,"No te arrimes a la orilla:\nse derrumba el paredón;\neste sonecito, mi alma,\nle nombramos “El tejón”.",158,2,22,150,"El tejón",0,4,"o",31,0,-1,0,303,303,"7767","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7769",7,"Aquí me siento a cantar,\nal pie de una azucenita,\na ver si puedo cantar\nla canción de mi “Juanita”.",138,2,6,150,"La Juanita; Estrofa suelta",1,4,"ia",50,0,-1,0,303,303,"7769","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7770",7,"Voy a cantar el jarabe\nque compuse esta mañana;\nlo compuse en Veracruz,\ny ya se canta en La Habana.",135,2,-1,150,"El jarabe loco",0,4,"aa",4,0,-1,0,303,303,"7770","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7771",7,"Voy a cantar la chilena,\nese sufrir con mi son;\nyo sólo vengo a decirte\nque me comas, tiburón.",135,2,-1,150,"El tiburón",0,4,"o",31,0,-1,0,303,303,"7771","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7772",7,"Dicen que no hay caimán\nen el río de Pisaflores;\ncomo todos lo dirán,\nbailando con sus amores,\nahí les traigo un refrán.",139,2,2,150,"El caimán",7,5,"a",147,0,-1,0,303,303,"7772","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7773",7,"Vengo aquí con mi jarana\ny les vengo yo a cantar,\nvengo cantando huapango\ncon falsete, y nada más.",135,2,-1,150,"El gallo jaspeado",0,4,"a",-1,0,-1,0,303,303,"7773","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7774",7,"Como humilde jaranero,\naquí me tienen cantando\npa decirles lo que quiero;\nque escuchen este huapango,\nque se los canto en ligero.",136,2,4,150,"El perdiguero",7,5,"eo",38,0,-1,0,304,304,"7774","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7775",7,"Llevo tristes decepciones\nen esta feliz tardeada;\ncantaremos este son,\nhoy fecha tan esmerada,\nen su séptima edición,\ncorregida y aumentada.",147,2,11,150,"El gusto",9,6,"aa",49,0,-1,0,304,304,"7775","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7776",7,"Si se presta mi memoria,\ncantaré versos modernos\ny les contaré una historia:\nque ayer salí del infierno,\nhoy me coloqué en la gloria\npara pasar el invierno.",142,2,8,150,"Zapateado",9,6,"eo",225,0,-1,0,304,304,"7776","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7777",7,"Atención pongan, señores,\nlo que les voy a cantar:\nvoy a hablar de unos barbeños\nque están a orillas del mar.",146,2,7,150,"Estrofa suelta",0,4,"a",21,0,-1,0,304,304,"7777","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7778",7,"Cancioneros de ese pueblo,\ninspirador de chilenas,\nse inspira Vidal Ramírez\ncantando “La malagueña”.",146,2,7,150,"Ometepec",0,4,"ea",-1,0,-1,0,304,304,"7778","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7779",7,"De la cola de un gurrión\nvoy a hacerte un abanico;\ny como puedo componer,\nyo en mi verso les digo\nque soy Francisco Rangel,\nhijo de don Federico.",142,2,8,150,"Zapateado",9,6,"io",-1,0,-1,0,304,304,"7779","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7780",7,"A la sombra de un acuyo\nme puse a rejoloneai.\nLes canto con mucho orgullo,\nblanca concha del mar,\nque aquí tienen a Refugio,\nque está llenito de orgullo,\npa lo que quieran mandar.",142,2,8,150,"El cascabel",4,7,"a",21,0,-1,0,304,304,"7780","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7781",7,"Yo salí de los Marcuiles\npara venirle a cantar;\nme correrás tus perfiles,\nno dejen de escuchar;\nsoy hijo de Norberto Aguirre,\npara lo que quieran mandar.",136,2,4,150,"El siquisirí",9,6,"a",21,0,-1,0,304,304,"7781","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7782",7,"Desde los llanos he venido\na cantar a los potreros,\ny si no me han conocido,\nyo soy Pánfilo Valerio,\nque a este lugar he venido.",136,2,4,150,"La morena",7,5,"io",101,0,-1,0,304,304,"7782","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7783",7,"Me llamo Pancho Romero,\néste se llama Zenón,\néste es mi primo tercero,\nque para bailar el son\ndonde quiera es el primero,\npues no hay otro en la región.",136,2,4,150,"El siquisirí",9,6,"o",31,0,-1,0,305,305,"7783","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7784",7,"Zandunga mandé tocar,\ncanto para ser feliz;\nsi preguntan quién cantó,\ndirán que Máximo Ortiz.",142,2,8,150,"La Zandunga",0,4,"i",335,0,-1,0,305,305,"7784","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7785",7,"Corté el capulín de oreto,\nme puse a rejolonear.\nA todo me comprometo,\npero menos a bailar;\nse despide María Prieto:\n¿quieren oírla cantar?",142,2,8,150,"La morena",9,6,"a",21,0,-1,0,305,305,"7785","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7786",7,"Ya se despide María,\nya así lo anunció Beto;\nyo sigo con mi botella\ny a todo me comprometo;\nya se despide María,\nla que se apellida Prieto.",142,2,8,150,"La morena",9,6,"eo",543,0,-1,0,305,305,"7786","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7787",7,"Volando en un areoplano\nllegué al puerto de Alvarado;\ncomo me llamo Epifanio,\nyo soy un hombre ilustrado;\ncon mi jarana en la mano\nsoy el diablo desatado.",136,2,4,150,"La guacamaya; El carpintero",9,6,"ao",-1,0,-1,0,305,305,"7787","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7788",7,"No sufras porque me veas,\nte engañabas por el mundo;\nno hay guitarra sin Ramírez\nbajo el cielo de Acapulco.",146,2,7,150,"Camino de Chilpancingo",0,4,"uo",-1,0,-1,0,305,305,"7788","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7789",7,"No canto todos los días,\náhi le digo cosas raras;\nno siga con tonterías,\nviéndose cara a cara,\nyo vivo en Santa María;\nsoy el que toca la guitarra.",142,2,8,150,"El siquisirí",9,6,"aa",-1,0,-1,0,305,305,"7789","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7790a",7,"La música es alegría\nde todo género humano;\nsoy un indito serrano,\ny la Huasteca es tierra mía.",141,2,1,150,"La leva",11,4,"ia",0,0,-1,0,305,305,"7790a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7790b",7,"La música es alegría\nde todo género humano;\ndemuestro mi simpatía,\nporque soy veracruzano,\nla Huasteca es tierra mía.",136,2,4,150,"La leva; El gusto; La huazanga",7,5,"ia",0,0,-1,0,305,305,"7790b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7791a",7,"Como yo soy de Lindero,\nsiempre me gusta cantar;\nen los cantares me excedo\ny yo no les canto mal;\nsiempre he tenido rival.",136,2,4,150,"La leva",7,5,"a",1,0,-1,0,306,306,"7791a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7792",7,"En Chicontepec nací,\nestado de Veracruz,\ndonde una madre dio a luz\nal joven que canta aquí.",147,2,11,150,"La huazanga] '",11,4,"i",23,0,-1,0,306,306,"7792","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7793",7,"Hora sí voy a cantar,\npues firmando en mis contratas,\npero me voy a explicar,\ny los músicos que tocan,\nvecinos de Temamatla.",138,2,6,150,"La Malagueña",7,5,"aa",-1,0,-1,0,306,306,"7793","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7794",7,"Yo soy el ave que canta\nen cielo tamaulipeco;\nmi corazón no se aguanta\ncuando canto mi son huasteco,\nsalido de mi garganta.",135,2,-1,150,"El caimán",7,5,"aa",148,0,-1,0,306,306,"7794","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7795a",7,"Para cantar “El muchacho”,\neso sí me la echo yo;\npara rezar el rosario,\nmi abuela la que se murió.",140,2,12,150,"El muchacho",0,4,"o",2,0,-1,0,306,306,"7795a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7796",7,"Soy hombre que en los huapangos\nhe gozado de primores,\ny nunca me la ando echando,\nni a nadie le hago yo honores,\nde lo que siempre, cantando,\nhe sido de los mejores.",135,2,-1,150,"La morena; El pájaro carpintero",9,6,"oe",5,0,-1,0,307,307,"7796","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7797",7,"Los que cantamos canciones\nsomos un poco aguzados\ny hacemos nuestra linterna\ncon canciones y huapangos.",135,2,-1,150,"Linternas y linternitas",0,4,"ao",-1,0,-1,0,307,307,"7797","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7798",7,"Las trovas del igualteco,\ngorrioncillo de Chilapa,\nbien valen lo que un lucero\nsobre el río de las Balsas.",146,2,7,150,"Camino de Chilpancingo",0,4,"aa",-1,0,-1,0,307,307,"7798","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7799",7,"Si hago una barbaridad,\npido que se me perdone;\ncantando no soy decente,\nporque no soy preparado:\nlo dice toda la gente.",142,2,8,150,"El siquisirí",7,5,"ee",15,0,-1,0,307,307,"7799","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7800",7,"Yo quisiera cantar alto,\npero mi pecho no aguanta:\ncon el polvo del camino\nse me cerró la garganta.",142,2,8,150,"La garza",0,4,"aa",148,0,-1,0,307,307,"7800","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7801a",7,"Por vida suya, señores,\nno murmuren del que canta:\npor el polvo del camino\ntraigo seca la garganta.",142,2,8,150,"La Zandunga; La azucena",0,4,"aa",148,0,-1,0,307,307,"7801a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7802",7,"El pecho traigo cerrado\nde tanto mascar canela,\npor eso canto contigo\nronquito de esta manera.",135,2,-1,150,"La víbora",0,4,"ea",-1,0,-1,0,307,307,"7802","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7803",7,"Canto un tono muy agudo,\nno se me puede aliviar;\nhoy la voz se me hace nudo,\npor eso yo lo saludo;\naguanieve ando buscando.",136,2,4,150,"El aguanieve",7,5,"ao",-1,0,-1,0,307,307,"7803","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7804",7,"Con vergüenza estoy cantando,\nporque tengo la voz seca;\nustedes escucharán\nla chilena “Sanluisteca”.",146,2,7,150,"Sanluisteca",0,4,"ea",594,0,-1,0,308,308,"7804","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7805",7,"No soy poeta ni soy nada:\nsoy un triste jornalero,\ny al que no le haya gustado\nle devuelvo su dinero.",137,2,3,150,"La gotera",0,4,"eo",38,0,-1,0,308,308,"7805","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7806",7,"Yo no soy tamaulipeco:\nyo soy puro potosino;\ntraigo en estilo huasteco;\ny también me gusta el vino,\npero aquí sí he estado seco.",138,2,6,150,"La huazanga",7,5,"eo",320,0,-1,0,308,308,"7806","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7807",7,"Pico, pico, pico, pico,\npico, pico, mendorico;\nsi quieren que yo les cante,\nya me remojan el pico.",161,2,15,150,"El pelado",0,4,"io",141,0,-1,0,308,308,"7807","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7808",7,"Ya me canso de cantar,\nya me duele la garganta;\nserá porque no he tomado\nde esa agüita que ataranta.",161,2,15,150,"El pelado; La azucena; Las mañanitas; El siquisirí; Estrofa suelta",0,4,"aa",148,0,-1,0,308,308,"7808","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7809",7,"De tanto cantar y cantar\nya me duele la cabeza,\nporque no nos quieren dar\nun tarrito de cerveza.",147,2,11,150,"Las mañanitas",1,4,"ea",108,0,-1,0,308,308,"7809","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7810",7,"Yo les canto mi tristeza,\ny por eso no me acuerdo;\ncomo no perdí la cuenta,\náhi le digo, amigo güero,\nque nos falta una cerveza.",138,2,6,150,"La pasión",7,5,"ea",-1,0,-1,0,308,308,"7810","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7811",7,"Voy a tomar mi retiro,\nte lo digo en mi pobreza.\nYo vivo con el suspiro;\nyo le digo aquí, amigo,\nque dispare la cerveza.",138,2,6,150,"La Cecilia",7,5,"ea",108,0,-1,0,308,308,"7811","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7812",7,"Se turbó mi compañero,\npero lo voy a enmendar;\nse turban ios licenciados\nque están en el tribunal,\ncuantimás mi compañero,\nque hasta ahora viene a cantar.",159,2,26,150,"La azucena; Estrofa suelta",9,6,"a",-1,0,-1,0,309,309,"7812","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7813",7,"Ándale, compañerito,\ncántale, y vamos cantando;\nusted me apunta sus versos,\ny yo los cantaré llorando.",141,2,1,150,"La huazanga",0,4,"ao",33,0,-1,0,309,309,"7813","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7814",7,"Ya mi caballo no bebe,\nporque el ánimo perdió,\npero si usted no se atreve,\npara no perderlo yo,\ncantaremos “La aguanieve”.",135,2,-1,150,"El aguanieve; Estrofa suelta",7,5,"ee",474,0,-1,0,309,309,"7814","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7815",7,"Yo te ayudo, canta amorcito,\nque mi voz es de engañado;\nque vivo entre rositas\nyo siempre lo he demostrado;\ncantando este “Fandanguito”,\ny siempre he disimulado.",136,2,4,150,"El fandanguito",9,6,"ao",14,0,-1,0,309,309,"7815","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7816",7,"-Indita, ¿yo qué le digo,\nsi yo no sé el español?\n—Indito, sigue mi canto,\ny así lo haremos mejor.",137,2,3,150,"Felicitación indígena",0,4,"o",-1,0,-1,0,309,309,"7816","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7818b",7,"Si no mandas otra cosa,\nyo te cantaré mejor;\npalabra de quien te invoca\ncon el tono en La menor;\nme llamo Leonardo Sota,\ncon esto invoco a un servidor.",136,2,4,150,"La morena",9,6,"o",72,0,-1,0,309,309,"7818b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7819",7,"Aquí me voy a sentar a cantar\ndebajo de esta ramada;\nsi me dejas, canto,\nsi no, no canto nada.",142,2,8,150,"La Malagueña curreña",3,4,"aa",49,0,-1,0,309,309,"7819","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7820",7,"Con gusto les canto yo\na mis cuates con razón,\na las mujeres por lindas\ny al amigo en corazón.",135,2,-1,150,"El as de los huapangos",0,4,"o",31,0,-1,0,309,309,"7820","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7821a",7,"Me gusta cantar huapangos,\npero que tengan falsete,\ny brindar por esos mangos\nque no tengan pretendientes.",138,2,6,150,"Estrofa suelta",0,4,"ee",-1,0,-1,0,310,310,"7821a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7821b",7,"Me gusta cantar huapangos,\npero que tengan falsete,\ny llegar a los fandangos\ncon botellas de aguardiente\ny brindar por esos mangos\nque no tengan pretendiente.",138,2,6,150,"Estrofa suelta, Amores con falsete",9,6,"ee",15,0,-1,0,310,310,"7821b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7823",7,"Yo no canto como un loco,\nen toditos los placeres,\ncon mi cantar no provoco;\nyo vengo a cantar un poco:\nque se animen las mujeres.",142,2,8,150,"El siquisirí",7,5,"ee",55,0,-1,0,310,310,"7823","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7824",7,"Mañanitas mexicanas,\nque nos causan frenesí,\nmañanitas de mi tierra:\nno hay otras que sean así.",135,2,-1,150,"Las mañanitas",0,4,"i",23,0,-1,0,310,310,"7824","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7825",7,"Éste es “El Maracumbé”,\nel rey de todos los sones,\nquerido de las mujeres\ny apreciado de los hombres.",145,2,17,150,"El maracumbé; El cuatro",0,4,"oe",-1,0,-1,0,310,310,"7825","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7826",7,"Este trío de huapangueros\nalegran esta ocasión,\nen todito el mundo entero\nno tiene comparación;\n“La huazanga” es lo primero.",138,2,6,150,"La huazanga",7,5,"eo",38,0,-1,0,310,310,"7826","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7827",7,"El son jarocho\nes el mejor que se ha dado;\nes el baile más decente,\npues no se baila abrazado.",136,2,4,150,"A orillas del Papaloapan",3,4,"ao",14,0,-1,0,310,310,"7827","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7828",7,"Al son de tierra caliente,\ndonde quiera es aceptado\nque este baile es muy decente\npor toditito el estado,\ny por eso dignamente\ndebe de ser comentado.",136,2,4,150,"El siquisirí",9,6,"ao",14,0,-1,0,311,311,"7828","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7830",7,"Cuando yo me confesaba\ncon un padre chaparrito,\nde penitencia me daba\nque cantara “el fandanguito”,\ny hasta que yo me cansara.",138,2,6,150,"El fandanguito",7,5,"aa",-1,0,-1,0,311,311,"7830","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7831",7,"Esta “Media bamba”\nes muy diferente:\nno es aquella “Bamba”\nque baila la gente.",136,2,4,150,"La media bamba",1,4,"ee",15,0,-1,0,311,311,"7831","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7832",7,"Y la luna en su apogeo\ny el sol tan capacitado.\nLas chispas de los deseos,\ncomo el que llega a Alvarado,\nque oye del arpa el trineo\ndel “Siquisirí” afamado.",142,2,8,150,"‘‘El siquisirí",9,6,"ao",14,0,-1,0,311,311,"7832","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7833",7,"Me quiero ir a Yucatán\ncon el rumbo de Ozuluama.\nAl pasar el río Tuxpán\nme dijo una mexicana:\n“Éste es el mero «Caimán»,\nel huapango de la fama”.",136,2,4,150,"El caimán",9,6,"aa",-1,0,-1,0,311,311,"7833","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7834",7,"Cuando vino “El fandanguito”\nnadie lo sabía bailar,\ny ahora que lo saben todos\nno lo dejan descansar.",135,2,-1,150,"El fandanguito",3,4,"a",21,0,-1,0,311,311,"7834","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7835",7,"Me vine de Puerto Rico\nen un barco navegando;\npara llegar a Tampico\noí que estaban tocando\neste son del “Fandanguito”,\nque es muy bonito huapango.",136,2,4,150,"El fandanguito; El bejuquito; El taconcito",9,6,"ao",-1,0,-1,0,311,311,"7835","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7836",7,"Yo soy el indio huasteco,\nque ando por aquí guaseando,\ny en mi cantar me hacen caso,\nporque me están escuchando\ny el son de un “Tepetzintleco”,\nque es muy bonito huapango.",136,2,4,150,"El tepetzintleco",9,6,"ao",-1,0,-1,0,312,312,"7836","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7837",7,"Hoy después de saludar,\ncontento de verte buena,\nde esta guitarra que suena\nde muy bonito cantar\neste son de “La azucena”.",141,2,1,150,"La azucena",7,5,"ea",59,0,-1,0,312,312,"7837","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7838",7,"¡Qué bonito es el jarabe!,\n¡qué bonito es ese charro!,\n¡qué bonita es esa china!,\n¡qué bonito es bailar todos!",139,2,2,150,"El jarabe",5,4,"oo",-1,0,-1,0,312,312,"7838","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7839",7,"El son del “Huateque”\nes muy singular,\nporque tiene ritmo\npara zapatear.",136,2,4,150,"El huateque",0,4,"a",21,0,-1,0,312,312,"7839","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7840",7,"El son del “Huateque”\nes muy singular:\nhasta los viejitos\nlo pueden bailar.",136,2,4,150,"El huateque",0,4,"a",21,0,-1,0,312,312,"7840","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7841",7,"¡Ay, qué bonito, qué bonito este fandango!,\ncon su ritmo ¡y cómo le rezumba el mango!\n¡Ay, qué bonito, qué bonito es este son!,\ncon su ritmo calientito y sabrosón.",135,2,-1,150,"La yerbabuena’’",3,4,"o",31,0,-1,0,312,312,"7841","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7842",7,"¡Ay, lelito, ay, lelango!,\n¡cómo me gusta el huapango!\n¡Ay, lelito, lelito, lelito!,\n¡ay, lelito, lelito, lelón!",136,2,4,150,"El lelito",3,4,"o",-1,0,-1,0,312,312,"7842","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7843",7,"¡Ay, milongo, ay, milongo!,\n¡ay, milongo, al amanecer!,\n¡ay, milongo, a la medianoche!,\n¡ay, milongo, al anochecer!",146,2,7,150,"Ay, milongo",0,4,"e",20,0,-1,0,312,312,"7843","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7844",7,"¡Ay, qué sonecito!,\n¡ay, que por él me muero!\n¡Ay, qué sonecito\npara un “Sombrero”!",144,2,10,150,"El sombrero ancho",3,4,"eo",38,0,-1,0,312,312,"7844","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7845",7,"¡Ay, qué lindo siento\ncuando me pongo a cantar\n“El falsete de mi tierra”,\nque es gusto muy singular!",141,2,1,150,"El falsete de mi tierra",0,4,"a",21,0,-1,0,313,313,"7845","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7846",7,"Alegre son de mi patria,\nme fascina “El fandanguito”;\npara alborotar la gallera,\nque me avienten un torito.",135,2,-1,150,"El as de los huapangos",0,4,"io",119,0,-1,0,313,313,"7846","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7847",7,"¡Qué bonita es esta polka!,\nlástima que no la sé;\nmi Juanita la bailaba\nde punta, talón y pie.",135,2,-1,150,"La Juanita",0,4,"e",77,0,-1,0,313,313,"7847","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7848",7,"El hombre no se remanga\npara bailar este son;\ncuando tocan “La huazanga”\ncualquier hilacho es cotón,\nabriéndole boca y manga.",138,2,6,150,"La huazanga",7,5,"aa",616,0,-1,0,313,313,"7848","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7849",7,"¡Ay, qué bonito es bailar\nel son del “Tilingo-lingo”!,\nque lo pueden zapatear\ntanto el chino como el gringo.",136,2,4,150,"El tilingo-lingo",1,4,"io",426,0,-1,0,313,313,"7849","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7850",7,"Bello puerto de Tampico,\nelegante y renombrado;\n“En mi casa lo repito,\ndijo un ranchero afamado,\n¡qué bonito “El fandanguito”,\ncantándolo con agrado!”",136,2,4,150,"El fandanguito",9,6,"ao",14,0,-1,0,313,313,"7850","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7851",7,"¡Qué bonito es “El jarabe”\ncuando lo saben tocar!,\npero más bonito es\ncuando lo saben cantar.",136,2,4,150,"El jarabe loco",0,4,"a",21,0,-1,0,313,313,"7851","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7852",7,"Quise cortar un clavel,\nque lo revolcaba el viento;\nbonito es “El cascabel”\ny cantarlo con acento.",135,2,-1,150,"La morena",1,4,"eo",94,0,-1,0,313,313,"7852","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7853",7,"¡Qué bonito es “El caimán”\ncuando lo saben bailar!\nRevueltas y más revueltas,\ncomo la arena del mar.",141,2,1,150,"El caimán",0,4,"a",21,0,-1,0,313,313,"7853","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7854",7,"¡Qué bonitos “Gorgoritos”\ncuando ya está lloviznando!,\npero más bonitos son\ncuando los estoy bailando.",144,2,10,150,"Los gorgoritos",0,4,"ao",33,0,-1,0,314,314,"7854","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7855",7,"¡Ay qué bonitos\n“Los enanitos”\ncuando los bailan\nagachaditos!",136,2,4,150,"Los enanos",6,4,"io",254,0,-1,0,314,314,"7855","",0,"frenk_t4","","",6,0,0,[],"",""],["frenk_t3-n7856",7,"¡Ay qué bonitos\nson “Los enanos”\ncuando los bailan\nlos mexicanos!",145,2,17,150,"El jarabe; Los enanos",6,4,"ao",318,0,-1,0,314,314,"7856","",0,"","","",6,0,0,[],"",""],["frenk_t3-n7857",7,"“Ariles y más ariles”,\ndigo, fumando un cigarro;\nbonito es “El Balajú”\ncuando lo bailan los charros.",136,2,4,150,"El Balajú",0,4,"ao",-1,0,-1,0,314,314,"7857","",0,"","","",24,0,0,[],"",""],["frenk_t3-n7858",7,"¡Qué bonita es “La bamba”\nen la madrugada\ncuando todos la bailan\nen la enramada!",136,2,4,150,"La bamba",6,4,"aa",-1,0,-1,0,314,314,"7858","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7859",7,"¡Qué bonito es bailar el jarabe\ncon rebozo y sombre[r]o jarano,\ncon vestidos de china y charro\ny un sarape color moreliano!",139,2,2,150,"El jarabe",3,4,"ao",-1,0,-1,0,314,314,"7859","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7860",7,"Retumba y retumba y chilla,\ncascabelito engarzado;\n¡qué bien suena la tarima\ncuando le dan al tablado!",136,2,4,150,"El cascabel’T",3,4,"ao",14,0,-1,0,314,314,"7860","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7861",7,"El cascabel de Leonor\n...que es cosa fina,\ny hasta la más bella flor,\nLuz, Conchita, Josefina,\ncuando “El cascabel” termina,\ntodas suspiran de amor.",147,2,11,150,"El cascabel",9,6,"o",72,0,-1,0,314,314,"7861","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7863a",7,"Este son de “El taconcito”\na muchos les ha gustado,\nporque es alegre y bonito\npa el que anda de enamorado,\npaseando con su amorcito.",136,2,4,150,"‘‘El taconcito",7,5,"io",119,0,-1,0,315,315,"7863a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7864",7,"Este “Aguajacado”,\nque no tiene fin,\nmientras más lo cantan\nmás chilla el violín.",146,2,7,150,"El aguajacado",0,4,"i",211,0,-1,0,315,315,"7864","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7866a",7,"“Fandanguito” encantador,\neres el rey de los sones\ny alegras los corazones,\nque dan ganas de bailar.",135,2,-1,150,"El fandanguito",5,4,"a",-1,0,-1,0,315,315,"7866a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7867",7,"Me gusta “El fandanguito”,\nporque es el rey de los sones;\nse pasa echando flores\ncuando estoy con mi amorcito.",139,2,2,150,"El fandanguito",5,4,"io",119,0,-1,0,315,315,"7867","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7868",7,"Este son que yo te traigo\nes el son del “Maracumbé”,\napreciado de los hombres;\neste son me tiene ocupado\ny alegrado el corazón.",137,2,3,150,"El maracumbé",7,5,"o",-1,0,-1,0,315,315,"7868","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7869",7,"Lucero de la mañana,\nel rey de todos los sones,\ncanta “La Martiniana” (¡ay, mamá!)\nque rompe los corazones.",142,2,8,150,"La Martiniana",3,4,"oe",34,0,-1,0,315,315,"7869","",0,"","","",22,0,0,[],"",""],["frenk_t3-n7870",7,"“El bejuco” es un huapango\nque se canta en la Huasteca;\nalegra cualquier fandango\ny gusta a quien lo interpreta,\ntambién quien lo anda nadando.",141,2,1,150,"El bejuquito",7,5,"ao",-1,0,-1,0,316,316,"7870","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7871",7,"Y el huapango es un baile\nde lo más gracioso\ny más sandunguero (salero),\ny al bailar con tu amada — no hay nada\nque nos haga feliz.",135,2,-1,150,"Ya no lloverá pelonas",7,5,"i",-1,0,-1,0,316,316,"7871","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7872",7,"Oyendo “El cielito lindo”,\n“La azucena” y “El caimán”,\nse alegran los corazones\ny las tristezas se van.",141,2,1,150,"Fiesta huasteca",0,4,"a",147,0,-1,0,316,316,"7872","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7873",7,"Cuando tengo alguna pena\ny la quiero disipar,\nen mi guitarra que suena\nme pongo luego a cantar\nun verso de “La azucena”,\npa poderlo falsetear.",141,2,1,150,"El falsete de mi tierra",9,6,"a",21,0,-1,0,316,316,"7873","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7874",7,"Éste es “El jarabe loco”,\nque a los muertos resucita:\nsalen de la sepultura,\nmeneando la cabecita.",135,2,-1,150,"El jarabe loco; El gusto",0,4,"ia",50,0,-1,0,316,316,"7874","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7875",7,"Cuando a la noche serena\nse divierten las estrellas,\nsi no miro a mi morena,\nme ilusiono yo con ellas\ny les canto “La azucena”.",138,2,6,150,"La azucena",7,5,"ea",-1,0,-1,0,316,316,"7875","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7876",7,"El que ama mujer morena\nle ha tocado buena suerte:\nnada del mundo le apena,\nni se acuerda de la muerte\ncuando canta “La azucena”.",136,2,4,150,"La azucena",7,5,"ea",59,0,-1,0,316,316,"7876","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7877",7,"Soy como la yerbabuena:\npor donde quiera me extiendo;\nyo le digo a mi morena\nque cuando me esté muriendo\nque me canten “La azucena”.",136,2,4,150,"La azucena; Estrofa suelta",7,5,"ea",59,0,-1,0,316,316,"7877","",0,"","","",3,0,0,[],"",""],["frenk_t3-n7878",7,"Niña, cuando yo muera\nno llores sobre mi tumba:\ncántame un lindo son (¡ay, mamá!),\ncántame “La Zandunga”.",142,2,8,150,"La Martiniana",3,4,"ua",-1,0,-1,0,317,317,"7878","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7879",7,"En la sangre de tus venas,\nel fuego de mis canciones;\ncuando cantas a mi tierra\narrebatas corazones.",135,2,-1,150,"Canta, canta, tortolita",0,4,"oe",34,0,-1,0,317,317,"7879","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7880",7,"Contento me pongo yo\ncuando canto a mi trompito,\nporque soy un..............................\ny por eso digo yo:\n“Soy un triste rancherito”.",136,2,4,150,"El trompo",7,5,"io",119,0,-1,0,317,317,"7880","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7881",7,"Cuando yo canto “El falsete”,\nque es gusto de mi región,\nse anima luego la gente\ny grita con emoción,\npero eso sí, muy decente.",141,2,1,150,"El falsete de mi tierra",7,5,"ee",15,0,-1,0,317,317,"7881","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7882",7,"“El tilingo” es un huapango\nde las tierras de Alvarado,\npero hay que ponerse chango\npara echar versos trovados.",136,2,4,150,"El tilingo-lingo",0,4,"ao",-1,0,-1,0,317,317,"7882","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7883",7,"Para bailar “La bamba”\nse necesita\nuna poca de gracia\ny otra cosita.",136,2,4,150,"La bamba; La manta",6,4,"ia",50,0,-1,0,317,317,"7883","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7884",7,"El son del “Tilingo-lingo”\ntiene un ritmo sabrosón,\nque se baila con estilo\nde “La bamba” y el danzón.",136,2,4,150,"El tilingo-lingo",0,4,"o",31,0,-1,0,317,317,"7884","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7885",7,"Vean qué bonito,\nqué bonito son,\nse baila de punta,\nde punta y talón.",135,2,-1,150,"El huateque",0,4,"o",31,0,-1,0,318,318,"7885","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7887",7,"Me embarqué en “El Yucatán”\npor salir al otro lado,\ny al pasar el río Jordán\nme dijo un matriculado\nque éste es el mero “Caimán”,\nque se baila zapateado.",136,2,4,150,"El caimán",9,6,"ao",14,0,-1,0,318,318,"7887","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7888",7,"No es de pisada ligera\nese mentado “Caimán”:\nzapateada verdadera,\nde veras es con afán,\nque se hace la polvareda,\nque ya después barrerán.",135,2,-1,150,"El caimán",9,6,"a",147,0,-1,0,318,318,"7888","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7889",7,"Si el “Caimán” quieres bailar\npara lucir con destreza\ntu habilidad y admirar,\nlleva el paso con firmeza,\ny mal no habrás de quedar.",141,2,1,150,"El caimán",7,5,"a",21,0,-1,0,318,318,"7889","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7890",7,"“El tilingo” es un fandango\nde ritmo muy singular:\nhay que ponerse muy chango\npa poderlo zapatear.",136,2,4,150,"El tilingo-lingo",1,4,"a",21,0,-1,0,318,318,"7890","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7891",7,"¡Qué bonito es el huapango\ncuando el arpa lo acompaña,\nbajo la sombra de un mango\ny adorno de flor de caña!\nHay qué ponerse muy chango\npara zapatear con maña.",142,2,8,150,"El siquisirí; El Ahualulco",9,6,"aa",213,0,-1,0,318,318,"7891","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7892",7,"“La Malagueña curreña”\nno hay quien la sepa cantar:\nsólo los marineritos\nque navegan en la mar,",142,2,8,150,"La Malagueña curreña; La Petenera",0,4,"a",21,0,-1,0,319,319,"7892","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7893",7,"Soy cucullo de la mar,\nque me mantengo en las peñas;\ndejo de cantar “El gusto”,\npor oír “La Malagueña”;\n“La Malagueña curreña”\nno hay quien la sepa cantar.",146,2,7,150,"La Malagueña curreña",9,6,"a",21,0,-1,0,319,319,"7893","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7894",7,"Señores, “El espinado”\nnadie lo sabe bailar,\npues para eso es necesario\na su chatita mirar.",135,2,-1,150,"El espinado",0,4,"a",21,0,-1,0,319,319,"7894","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7895a",7,"Todos cantan “El jarocho”\nque cantan por allá abajo;\npor aquí también lo cantan,\npero les cuesta trabajo.",135,2,-1,150,"Estrofa suelta",0,4,"ao",168,0,-1,0,319,319,"7895a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7895b",7,"Este es “El maracumbé”\nque cantan por allá abajo,\npero no todos lo cantan,\nni saben tocar el bajo,\nporque les cuesta trabajo.",135,2,-1,150,"El maracumbé",7,5,"ao",168,0,-1,0,319,319,"7895b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7896",7,"—Señores, ¿qué son es éste?\n—Señores, “El fandanguito”.\n—La primera vez que lo oigo:\n¡válgame Dios, qué bonito!",136,2,4,150,"El fandanguito",0,4,"io",119,0,-1,0,319,319,"7896","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7897",7,"El diablo le dijo al guardia,\nel guardia le dijo al juez:\n“¿De dónde salió este ritmo\nllamado «Merecumbé»?”",148,2,9,150,"El merecumbé",0,4,"e",-1,0,-1,0,319,319,"7897","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7898",7,"—¿Qué pajarillo es aquél,\nque viene por la varita?\n—Es el “Pajarillo alegre”,\nque bailaba Margarita.",138,2,6,150,"Pajarillo barranqueño",0,4,"ia",50,0,-1,0,319,319,"7898","",0,"","","",8,0,0,[],"",""],["frenk_t3-n7899",7,"Cihualteco de mi vida,\ndime quién te bautizó,\n¿quién te puso “Cihualteco”\npara que te cante yo?",145,2,17,150,"El Cihualteco; La Malagueña; Estrofa suelta",0,4,"o",2,0,-1,0,320,320,"7899","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7900",7,"Yo tenía una cachuchita\nde terciopelo morado,\ny como era tan bonita,\nse la regalé a un soldado.",155,2,14,150,"La cachucha",1,4,"ao",14,0,-1,0,320,320,"7900","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7901",7,"Yo tenía mi cascabel\ny se lo puse a un pandero;\n¡ay, qué bonito sonaba\ncuando rascaba en el cuero!",136,2,4,150,"El cascabel’T",0,4,"eo",38,0,-1,0,320,320,"7901","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7902",7,"Si mi cascabel sonara,\nyo la quisiera por él,\npero como ya no suena,\nyo lo procuro vender.",136,2,4,150,"El cascabel",0,4,"e",-1,0,-1,0,320,320,"7902","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7903",7,"Yo tenía mi cascabel\ncon su piedrecita adentro;\n¡ay!, como sonaba tanto,\nse lo regalé a un sargento,\npara que juegue con él\nla víspera de su santo.",136,2,4,150,"El cascabel",9,6,"ao",30,0,-1,0,320,320,"7903","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7904a",7,"Yo tenía mi cascabel\ncon una cinta morada,\ny como era de oropel,\nse lo di a mis hermanitos,\npa que jugaran con él.",147,2,11,150,"El cascabel",7,5,"e",32,0,-1,0,320,320,"7904a","",0,"","","",10,0,0,[],"",""],["frenk_t3-n7905",7,"Para hacer un cascabel,\nle metí cinco piedritas,\nlo envolví con un papel,\nse lo di a tus hermanitas,\npara que jueguen con él\ny se diviertan solitas.",147,2,11,150,"El cascabel",9,6,"ia",258,0,-1,0,321,321,"7905","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7907",7,"Bonito tu cascabel,\nmi vida, ¿quién te lo dio?\nRezumba, rezumba y suena\nel cascabel con cadena.",136,2,4,150,"El cascabel",5,4,"ea",59,0,-1,0,321,321,"7907","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7908",7,"—Bonito tu cascabel,\nvida mía, ¿quién te lo dio?\n—A mí no me lo dio nadie:\nmi dinero me costó;\nel que quiera cascabel\nque lo compre, como yo.",146,2,7,150,"El cascabel",9,6,"o",2,0,-1,0,321,321,"7908","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7909",7,"¿Qué dices, mi alma?\nTe lo decía:\nsi no fuera por La loba,\naquí nos amanecía.",145,2,17,150,"La loba",3,4,"ia",0,0,-1,0,321,321,"7909","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7910",7,"Una vieja mitotera,\nque salió de su jacal,\nfue la que sacó el mitote\nque anda una loba del mal.",145,2,17,150,"La loba",0,4,"a",1,0,-1,0,321,321,"7910","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7911",7,"Dicen que la Petenera\nes una mujer bonita,\nque se va a lavar de tarde\ny viene a la mañanita.",135,2,-1,150,"La Petenera",0,4,"ia",50,0,-1,0,321,321,"7911","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7912",7,"Dicen que la Petenera\nes una santa mujer,\nque se va a lavar de tarde\ny viene al amanecer.",135,2,-1,150,"La Petenera; Que dice la media muerte; Estrofa suelta",0,4,"e",20,0,-1,0,322,322,"7912","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7913",7,"La Varsoviana\nse quiere casar,\ncon naguas blancas\ny su delantal.",147,2,11,150,"La Varsoviana",6,4,"a",-1,0,-1,0,322,322,"7913","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7914",7,"—Varsoviana, Varsoviana,\n¿quién te trajo aquí?\n—Yo solita, yo solita\nvine a dar aquí.",147,2,11,150,"La Varsoviana",0,4,"i",-1,0,-1,0,322,322,"7914","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7915",7,"Aguanieve se ha perdido,\nsu mamá la anda buscando:\n“¿Quién ha visto por aquí\naguanieve lloviznando?”",136,2,4,150,"El aguanieve, Zapateado",0,4,"ao",33,0,-1,0,322,322,"7915","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7916",7,"Aguanieve ando buscando\ny no la puedo encontrar:\nestá muy lejos de aquí\ny no la puedo encontrar.",136,2,4,150,"El aguanieve",0,4,"a",-1,0,-1,0,322,322,"7916","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7917",7,"—¿Dónde vas, Canelo,\ntan de mañanita?\n—A comprar dos cirios (canelo)\npara Margarita.",135,2,-1,150,"El Canelo",1,4,"ia",50,0,-1,0,322,322,"7917","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7918",7,"—¿Dónde vas, Canelo (caramba)\ntan de madrugada?\n—A buscar lechuga (caramba)\npara la ensalada.",136,2,4,150,"El Canelo",1,4,"aa",49,0,-1,0,322,322,"7918","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7919",7,"Canelo murió,\nlo van a enterrar,\nlo llevan vestido a Canelo,\na lo militar.",136,2,4,150,"El Canelo",0,4,"a",21,0,-1,0,322,322,"7919","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7920a",7,"Se murió Canelo (caramba),\nlo van a enterrar:\nsepultura de oro (Canelo),\ncaja de cristal.",136,2,4,150,"El Canelo",0,4,"a",-1,0,-1,0,323,323,"7920a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7921",7,"El telele se murió,\nya lo llevan a entenar:\ncinco dragones y un cabo\ny un zorro de sacristán.",135,2,-1,150,"El telele",0,4,"a",-1,0,-1,0,323,323,"7921","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7922",7,"El telele se murió,\nsin poderlo remediar,\ny nos dejó por herencia\nel modito de temblar.",135,2,-1,150,"El telele",0,4,"a",21,0,-1,0,323,323,"7922","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7923",7,"Cupido, Cupido, me muero,\nCupido, ya le vas dando,\nnos hemos ya de ver,\nporque nos estamos mirando.",142,2,8,150,"El Cupido",0,4,"ao",33,0,-1,0,323,323,"7923","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7924",7,"¡Ay, Cupido, Cupido, Cupido!,\n¡ay, Cupido, Cupido tirano!,\n¡que me muero, me muero, Cupido!,\n¡Cupido, dame la mano!",135,2,-1,150,"El Cupido",3,4,"ao",81,0,-1,0,323,323,"7924","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7925",7,"¡Ay, Cupido, Cupido, Cupido!,\n¡ay, Cupido, Cupido traidor!,\ndame la mano, Cupido,\nCupido, rey del amor.",136,2,4,150,"El Cupido",3,4,"o",72,0,-1,0,323,323,"7925","",0,"","","",9,0,0,[],"",""],["frenk_t3-n7926",7,"Unos chiquitos\ny otros tamaños,\n¡ay qué preciosos\nson los enanos!",135,2,-1,150,"Los enanos",6,4,"ao",-1,0,-1,0,323,323,"7926","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7927",7,"Ya los enanos\nya se enojaron,\nporque a la enana\nla pellizcaron.",145,2,17,150,"El jarabe; Los enanos; Estrofa suelta",6,4,"ao",41,0,-1,0,323,323,"7927","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7928",7,"El tapextle está rodeado\nde purito cantador,\nno quieren quedarse a un lado,\ntodos cantan lo mejor.",147,2,11,150,"Fiesta huasteca",1,4,"o",72,0,-1,0,324,324,"7928","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7929",7,"Camino de Chilpancingo,\nbajo la brisa suriana,\niba mi amor en domingo;\nrascándole a la jarana.",146,2,7,150,"Camino de Chilpancingo",1,4,"aa",4,0,-1,0,324,324,"7929","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7930",7,"Éntrenle al vacilón,\nque hay pulquito y guajolote,\ny oigan esta canción,\nque resultó de borlote.",135,2,-1,150,"Las calabazas",1,4,"oe",292,0,-1,0,324,324,"7930","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7931",7,"Es muy divino y no olvidar\nestas hermosas noches,\nplenas de alegría\ncon tu hermoso cantar.",139,2,2,150,"Estrofa suelta",3,4,"a",21,0,-1,0,324,324,"7931","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7932",7,"Es un vals compuesto de amor;\nuna niña de poco vivir,\ncomo estaba apasionada,\nno sabía su porvenir.",144,2,10,150,"Los carretones",3,4,"i",157,0,-1,0,324,324,"7932","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7933",7,"Por ésta me fui paseando\ny. en una lancha pesquera;\ncon lo que me fui encontrando\ndebajo de una palmera:\n’tán dos morenas cantando\ny el son de “La Petenera”.",136,2,4,150,"La Petenera",9,6,"ea",44,0,-1,0,324,324,"7933","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7934",7,"Del cielo viene cayendo\nun ramo con seis claveles:\ndos Pepes y dos Antonios\ny dos pulidos Manueles.",144,2,10,150,"Estrofa suelta",0,4,"ee",97,0,-1,0,324,324,"7934","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7935",7,"Bombas vienen,\nbombas van,\npero tan sólo se quedan\nlas bombas de Yucatán.",152,2,13,150,"Estrofa suelta",3,4,"a",147,0,-1,0,324,324,"7935","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7936",7,"A las bombas viejas\nvamos a jugar,\ny el que no las cante\nno le damos de tomar.",135,2,-1,150,"Las bombas viejas",0,4,"a",21,0,-1,0,324,324,"7936","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7937",7,"Bomba arriba\nbomba abajo;\ntú te subes,\nyo me bajo.",147,2,11,150,"Estrofa suelta",3,4,"ao",168,0,-1,0,324,324,"7937","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7938",7,"Pos arriba y arriba,\nya voy llegando,\ncomo las palomitas\nque van volando.",142,2,8,150,"La bamba",6,4,"ao",33,0,-1,0,325,325,"7938","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7939",7,"Ay, arriba y arriba\ny arriba iré,\nhasta el cerro más alto\nde San Andrés.",136,2,4,150,"La bamba",6,4,"e",-1,0,-1,0,325,325,"7939","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7940",7,"Que súbele, que súbele, que baja,\nque lléguele, que lléguele pa atrás;\n¿a dónde irán los muertos?,\n¡quién sabe a dónde irán!",147,2,11,150,"quién sabe a dónde irán! [El sube y baja",3,4,"a",-1,0,-1,0,325,325,"7940","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7941",7,"Con el lingo, lingo,\ncon el lingo laira,\ncon el limón verde,\nsu fresco limonar.",144,2,10,150,"Delgadina",5,4,"a",-1,0,-1,0,325,325,"7941","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7942",7,"Agua lica, mi cauca, sonaja,\nagua lica, mi cauca, catera,\nagua lica, mi tonche, mi tonche,\nmi mala catonche de la mecatera.",135,2,-1,150,"Canción a un santo",3,4,"ea",44,0,-1,0,325,325,"7942","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7943",7,"En las ramas de un roblito\nescuché un pájaro gorjear,\ny como era tan chiquito,\nle dije al cardenal:\n“No puedo cantar bonito,\npero puedo improvisar”.",142,2,8,150,"El pájaro cú",9,6,"a",-1,0,-1,0,325,325,"7943","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7944",7,"Yo ya no quiero cantar\nlos mismos versos sabidos,\nalgo quería improvisar\npara cambiar de sonido,\ny los que van a escuchar\nque queden agradecidos.",136,2,4,150,"El siquisirí",9,6,"io",-1,0,-1,0,325,325,"7944","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7945",7,"Este verso bonito,\nimprovisado,\nha de ser un recuerdo\nnunca olvidado;\ncon mucho gusto,\nporque lo interpretamos\nen el concurso.",135,2,-1,150,"Cielito lindo",4,7,"uo",-1,0,-1,0,325,325,"7945","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7946",7,"Yo no sé letrear a,\nni una letra sé,\ny este “Aguajacado”\nyo lo improvisé.",140,2,12,150,"El aguajacado",0,4,"e",77,0,-1,0,325,325,"7946","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7947",7,"Voy a escribir estos versos\ncon un grande desatino;\ncon su permiso, señores,\nvoy a tomar mi camino.",148,2,9,150,"Estrofa suelta",0,4,"io",199,0,-1,0,326,326,"7947","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7948",7,"Tomé la pluma en la mano\ny me puse a pensar\na ver si puedo\nunos versos arreglar.",148,2,9,150,"Estrofa suelta",3,4,"a",21,0,-1,0,326,326,"7948","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7949",7,"A pesar de que soy chamaco,\nya pienso en tener,\na ver si puedo\nestos versos componer.",148,2,9,150,"Estrofa suelta",3,4,"e",20,0,-1,0,326,326,"7949","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7950",7,"Dicen que soy valiente,\ndicen que soy atroz;\nvoy a escribir estos versos\ncon el permiso de Dios.",135,2,-1,150,"Estrofa suelta",0,4,"o",87,0,-1,0,326,326,"7950","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7951",7,"Corté la flor de limón,\ny también la de cruceta.\nAllá va mi composición,\npa que vean que soy poeta;\nsoy medio de esta región:\nyo vengo de Villa Azueta.",142,2,8,150,"El siquisirí",9,6,"ea",200,0,-1,0,326,326,"7951","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7952",7,"Para cantar mis versos,\npara mí no hay cosa rara;\néste es el son que compongo,\nque nos parezca más claro\ncantándolo Pedro Alfonso,\nAndrés y Gertrudis Vergara.",136,2,4,150,"El siquisirí",9,6,"aa",57,0,-1,0,326,326,"7952","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7953",7,"Para mí no hay cosa rara,\ncantando con claridad,\ncon mi querido papá,\nPedro y Gertrudis Vergara.",136,2,4,150,"El siquisirí",5,4,"aa",57,0,-1,0,326,326,"7953","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7954a",7,"Soy compositor de fama,\nyo se lo doy a saber;\ndígame cómo se llama,\npa poderle componer.",142,2,8,150,"El siquisirí",1,4,"e",20,0,-1,0,326,326,"7954a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7955a",7,"Y también la de la ilama,\nporque se quería secar.\nEn verdad que te voy a hallar,\ndígame cómo se llama,\npa que se apure a escuchar.",142,2,8,150,"El siquisirí",7,5,"a",21,0,-1,0,326,326,"7955a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7956",7,"Voy a cantarte un versito\nsin ninguna hipocresía;\nlo digo así sin.....................\nsólo la ciencia mía;\ncomo si fuera en funciones,\nno más que sólo le hacía.",135,2,-1,150,"El carpintero",9,6,"ia",0,0,-1,0,327,327,"7956","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7957",7,"Cantando no soy sangrón,\nla verdad les voy a hablar;\nvengo de Minatitlán,\nporque esta grabación\na la capital va ir a dar.",136,2,4,150,"El siquisirí",7,5,"a",-1,0,-1,0,327,327,"7957","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7958",7,"Digo con satisfacción,\nla verdad te estoy hablando;\nsi me escuchan la canción\no si no están escuchando,\ndigo con satisfacción;\n“Ay, tú me estás escuchando”.",136,2,4,150,"La morena’",9,6,"ao",-1,0,-1,0,327,327,"7958","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7959",7,"Como soy trabajador,\nme encuentro un poco estropeado;\nte digo con mucho amor\nque es ciencia que Dios me ha dado,\naunque no soy trovador.",136,2,4,150,"El siquisirí'*",7,5,"o",72,0,-1,0,327,327,"7959","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7960",7,"Aunque me he puesto ronquito,\ntraigo mi traje muy grande,\npara subir a saludar\n—lo digo recio y quedito—\na [Fulano], mi amiguito.",136,2,4,150,"La huazanga",7,5,"io",119,0,-1,0,327,327,"7960","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7961",7,"Y vuela, revuela, vuela,\nmis palabras se me escapan,\nsaludando a Federico,\nque se encuentra en Jalapa.",136,2,4,150,"La guacamaya",0,4,"aa",-1,0,-1,0,327,327,"7961","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7962",7,"Me gusta cuando te pones\ncolorada y manzanita;\nla Señora de Alatorre\npues yo la saludo ahorita,\na ver si un versó compone.",139,2,2,150,"La presumida",7,5,"oe",-1,0,-1,0,327,327,"7962","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7963",7,"Aunque me haga contrapeso,\npero digo que lo fío,\ny mira que doy un peso,\npara que veas que te confío;\npues mi verso es el progreso,\npues yo saludo a Rocío.",139,2,2,150,"El caimtn",9,6,"io",3,0,-1,0,327,327,"7963","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7964",7,"Corté la flor de la vid\ny también la de manzano.\nHoy me encuentro por aquí,\nque a las dos de la mañana\nsaludo a Gloria Ruiz,\nuna linda mexicana.",142,2,8,150,"El pájaro cú",9,6,"aa",4,0,-1,0,328,328,"7964","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7965",7,"Aficionado soy yo,\npero canto dondequiera,\npero siempre digo yo,\nque saludo a Omar Rivera,\nque él es el grabador.",139,2,2,150,"La azucena",7,5,"o",-1,0,-1,0,328,328,"7965","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7966",7,"Ángel de la primavera,\nahora sí vine a cantar;\nyo les digo en mi trovar:\naquí saludo a un amigo,\ny que se llama Omar\ny se apellida Rivera.",139,2,2,150,"La Cecilia",9,6,"ea",44,0,-1,0,328,328,"7966","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7967",7,"Horita voy a cantar\nhasta que el alma me duela;\nluego empiezo a saludar\nal joven Omar Rivera\ntambién a Adán Aguilar.",139,2,2,150,"La azucena",7,5,"a",21,0,-1,0,328,328,"7967","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7968",7,"La música destino (cielito lindo),\nsin compromiso,\nal amigo Rufino,\nal profe y también Perico;\nde corazón\nsaludo a Flavio González,\nIsmael y don Ramón.",138,2,6,150,"Cielito lindo",4,7,"o",31,0,-1,0,328,328,"7968","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7969",7,"Me mandaron a llamar\nde allá de La Mixtequilla;\nyo le pude contestar\ncon una razón sencilla,\nsaludando aquí al güero\ny a toda su palomilla.",136,2,4,150,"María Chuchena",9,6,"ia",162,0,-1,0,328,328,"7969","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7970",7,"Dispense usted, don Agustín,\nque culpa no tengo en nada,\npues el señor [Perengano]\nnos mandó a que le cantara.",135,2,-1,150,"Las mañanitas",0,4,"aa",-1,0,-1,0,328,328,"7970","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7971",7,"Me pediste, Mantea,\nque esto lo hiciera\ncon cariño y respeto\npara la güera.",136,2,4,150,"La bamba",6,4,"ea",44,0,-1,0,328,328,"7971","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7972",7,"Yo voy a cantar horita\ny saludo adondequiera;\nperdonen mi vocecita,\npor parte de Omar Rivera\npues yo saludo a Conchita.",139,2,2,150,"La presumida",7,5,"ia",50,0,-1,0,328,328,"7972","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7973",7,"Dicen que soy trovador,\nmi vida, pues tú bien sabes;\ny hoy saludo con amor\ny a la familia González,\npor parte del grabador.",139,2,2,150,"‘‘La leva",7,5,"o",72,0,-1,0,329,329,"7973","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7974",7,"Lo que digo lo sostengo:\nsiempre he llevado un compás;\nyo me he visto entre los buenos\ny hoy que vengo por acá,\nahora yo saludo a Beño,\npor mandado de este Jas.",136,2,4,150,"‘‘El siquisirí",9,6,"a",-1,0,-1,0,329,329,"7974","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7975",7,"Tengo un caballo bonito,\npero no es tamaulipeco;\npa enamorar es vivito\ncon su pasito huasteco;\nA Beto Ávila felicito\nde parte del Trío Huasteco.",138,2,6,150,"‘‘El caballito",9,6,"eo",-1,0,-1,0,329,329,"7975","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7976",7,"Viva el barrio de Talapa,\ncon su hermosa melodía;\nse inspira Vidal Ramírez,\npor Angélica García.",146,2,7,150,"Ometepec",0,4,"ia",0,0,-1,0,329,329,"7976","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7977",7,"Compañero, por aquí\na cantar me determino;\ncantando lo digo así,\ncon este canto latino;\ncon gusto le canto a Luis,\nque le dicen Capulino.",136,2,4,150,"Estrofa suelta",9,6,"io",199,0,-1,0,329,329,"7977","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7978",7,"Cantando con frenesí\nen mi pueblo de Alvarado,\ntrovando lo digo así,\nporque vengo preparado:\nespecial a María Luisa\neste verso es dedicado.",136,2,4,150,"Estrofa suelta",9,6,"ao",14,0,-1,0,329,329,"7978","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7979",7,"Decir se me facilita,\nporque tengo disciplina;\nhablando con voz clarita:\nesta es teja, no es cantina,\nle canto a doña Margarita,\nque es la mamá de Farina.",136,2,4,150,"Estrofa suelta",9,6,"ia",-1,0,-1,0,329,329,"7979","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7980",7,"Por todito lo que sé,\nyo nunca le clavo el pico;\ny cantando les diré:\nni más pobre ni más rico,\ncantando para José,\ntambién canto a Federico.",136,2,4,150,"La guacamaya",9,6,"io",141,0,-1,0,329,329,"7980","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7981",7,"Recuerda lo que dijiste,\nyo no soy aficionado;\nen la mente prometiste;\nsoy nacido en Alvarado;\nBeño, como no veniste,\ny este son va dedicado.",135,2,-1,150,"El siquisirí",9,6,"ao",14,0,-1,0,330,330,"7981","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7982",7,"Recuerda lo que dijiste\nen un momento feliz,\nsólo me lo prometiste;\ncantando te digo así:\n“Beño, como no veniste,\nva dedicado pa ti”.",136,2,4,150,"El siquisirí",9,6,"i",23,0,-1,0,330,330,"7982","",0,"","","",4,0,0,[],"",""],["frenk_t3-n7983",7,"Es amigo a todo dar,\ny estos versos yo los hago;\nsi me escuchan mi cantar,\nmi frase yo me declaro:\npues a Manlio Salazar\ncantando digo “Estimado”.",138,2,6,150,"El caimán",9,6,"ao",-1,0,-1,0,330,330,"7983","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7984",7,"No me lo vas a creer,\nsigo derecho:\npara Moisés Hervert,\npara Lacho y Morquecho,\npues no me engañan,\npara Octavio González\ny amigos que lo acompañan.",138,2,6,150,"Cielito lindo",4,7,"aa",617,0,-1,0,330,330,"7984","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7985",7,"Cuando me voy a correr\nen mi caballo bonito,\ncanto y no lo van a creer;\nte digo en este versito:\n“Óyeme, Moisés Hervert,\naquí está tu «Caballito»”.",138,2,6,150,"El caballito",9,6,"io",119,0,-1,0,330,330,"7985","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7986",7,"Siempre trovo de carrera\ny aprovecho el momentito;\noyendo la huapanguera\ny la jarana un ratito,\nese mi amigo Omar Rivera\nyo le ofrezco “El sombrerito”.",139,2,2,150,"El sombrero",9,6,"io",119,0,-1,0,330,330,"7986","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7987",7,"Una bella criaturita\npaseándose por aquí;\na la señorita Olguita\ndedicamos “El siquisirí”.",136,2,4,150,"El siquisirí",3,4,"i",23,0,-1,0,330,330,"7987","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7988",7,"Andando por esta zona,\nyo les digo en mi prefacio;\ny me dijo la patrona:\n“Pues al primo de Epitacio\nyo le dedico «La mona»”.",139,2,2,150,"La mona",7,5,"oa",7,0,-1,0,330,330,"7988","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7989",7,"Ahorita voy a trovar,\ny lo hago sin condición;\nse lo dedico mi trovar\na mis amigos de La Misión.",139,2,2,150,"Estrofa suelta",3,4,"o",31,0,-1,0,330,330,"7989","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7990",7,"Me palpita el corazón,\naunque sea de pasadita;\naprovecho la ocasión,\nde mi frase más bonita;\npaisano de La Misión,\nyo le ofrezco esta “Levita”.",139,2,2,150,"La leva",9,6,"ia",50,0,-1,0,331,331,"7990","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7991",7,"Aunque mi garganta queda,\nya me duele el corazón;\ny es que aunque ya no pueda,\nal pueblo de La Misión\nyo le dedico esta “Leva”.",139,2,2,150,"La leva",7,5,"ea",-1,0,-1,0,331,331,"7991","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7992",7,"Aquí les cantaré yo\ncon esta voz tan ufana;\nsiempre me queda el dolor,\npero........................................;\namigos de La Misión,\ny aquí nos vemos mañana.",139,2,2,150,"El triunfo",9,6,"aa",4,0,-1,0,331,331,"7992","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7993a",7,"Este “Cielito lindo”\nque estoy cantando\nes para los señores (cielito lindo)\nque están grabando:\nse los dice un buen amigo.",139,2,2,150,"Estrofa suelta",7,5,"io",-1,0,-1,0,331,331,"7993a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7993b",7,"Este “Cielito lindo”\nque estoy cantando,\nes para los señores (cielito lindo)\nque están tomando;\nyo se los digo:\nse los está cantando (cielito lindo)\nun buen amigo.",139,2,2,150,"Cielito lindo",4,7,"io",106,0,-1,0,331,331,"7993b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n7994",7,"Ayer salí del Oriente\ncon grata satisfacción;\nmi sentir es simplemente\nde entonarle su canción;\npara el güero de los lentes\nva dedicado este son.",136,2,4,150,"El torito",9,6,"o",31,0,-1,0,331,331,"7994","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7995",7,"Con esta grande trovada\nmi mente se precipita;\nno te quería decir nada;\nesta familia Avilita,\nde todos muy apreciada.",138,2,6,150,"La leva",7,5,"aa",49,0,-1,0,331,331,"7995","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7996",7,"Con mi voz tan lisonjera,\npues aunque sea con rigor,\ncantando un verso cualquiera,\nsuplicando con honor,",139,2,2,150,"viva la familia Rivera! [La Cecilia",1,4,"o",72,0,-1,0,331,331,"7996","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7997",7,"Quiero decir una cosa\ncon mi frase pasajera,\ncon mi pasión lastimosa:\n¡Que viva Omar Rivera,\ndel pueblo de Santa Rosa!",139,2,2,150,"La leva",7,5,"oa",63,0,-1,0,331,331,"7997","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7998",7,"Siempre has sido muy formal,\ny así, te digo, me tratas,\nte digo: “Yo soy igual,\n¡que viva el de Temamatla,\ny su nombre es Pascual!”",138,2,6,150,"La Malagueña",7,5,"a",1,0,-1,0,332,332,"7998","",0,"","","",1,0,0,[],"",""],["frenk_t3-n7999",7,"Viva el ingeniero Rubio,\nque se llama don Pascual,\nque no conoce lo turbio,\nporque es de puro Michoacán.",137,2,3,150,"Que viva la rumba",3,4,"a",-1,0,-1,0,332,332,"7999","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8000",7,"Cantando yo soy sincero,\nsin ninguna hipocresía;\nsólo decirles quiero\nque, hechos en la ciencia mía,\ncomo don Pifas Gutiérrez\nno nacen todos los días.",136,2,4,150,"El pájaro carpintero",9,6,"ia",-1,0,-1,0,332,332,"8000","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8001",7,"Yo siempre les he cantado,\ny cantando este versito\nyo nunca me he quedado;\nPaco Ávila felicito,\npues porque estoy desarmado.",138,2,6,150,"El caimán’",7,5,"ao",14,0,-1,0,332,332,"8001","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8003",7,"¡Ay, Zandunga, qué Zandunga Solís,\nmamá, por Dios!\nZandunga, tú eres de Ortiz,\ncielos de mi corazón.",142,2,8,150,"La Zandunga",3,4,"o",-1,0,-1,0,332,332,"8003","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8004",7,"La alegría viene a mí,\nsiento yo un gran placer\ncuando la alegría en mí;\npor eso es el frenesí,\nque hoy me ha hecho comprender\nque miro yo a Gloria Ruiz,\nuna preciosa mujer.",142,2,8,150,"El pájaro cú",4,7,"e",20,0,-1,0,332,332,"8004","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8005",7,"Estrellita reluciente,\nque vas saliendo del mar,\nalúmbrale más cerquita\na Silvestre Mariscal.",135,2,-1,150,"Estrofa suelta",0,4,"a",-1,0,-1,0,332,332,"8005","",0,"","","",11,0,0,[],"",""],["frenk_t3-n8006",7,"Cantando con mi jarana,\nsigo con mi porfía;\nlo digo galantemente,\nme entretengo noche y día;\ndon Valerio está viejón,\npero sirve todavía.",136,2,4,150,"El siquisirí",9,6,"ia",0,0,-1,0,332,332,"8006","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8007",7,"Te digo y te estimo (cielito lindo),\nde corazón,\npara cantar, Rufino (cielito lindo),\ncon don Ramón;\n¿pa qué negarlo?\npara bebidas buenas,\nen el salón Montecarlo.",138,2,6,150,"Cielito lindo",4,7,"ao",236,0,-1,0,333,333,"8007","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8008",7,"Ahora sí voy a cantar,\nporque es el día que te miro,\npero me voy a explicar,\ny lo digo de grandeza:\n¡pos que viva don Bonfilio!,\nque dispare la cerveza.",138,2,6,150,"La Cecilia",9,6,"ea",108,0,-1,0,333,333,"8008","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8009",7,"Hora sí voy a cantar,\nahora con una botella,\nporque así ya es mi destino,\ny voy diciendo: “¡Que viva,\nque viva Chencho Martínez!”",138,2,6,150,"El caballito",7,5,"ie",-1,0,-1,0,333,333,"8009","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8010",7,"Hora sí voy a cantar,\nen mi casa no me han visto;\npero me voy a explicar,\nlo digo de vez primero\nhoy a mi amigo don Sixto,\nmuy bueno pa cantinero.",138,2,6,150,"La Cecilia",9,6,"eo",38,0,-1,0,333,333,"8010","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8011",7,"Canto mi verso al revés,\nhablo con voz muy quedita;\ncon lo que le digo a usted\nle voy a decir ahorita:\n“Qué bueno estuvo el café\nque me invitó ahora Teresita”.",136,2,4,150,"El siquisirí",9,6,"ia",50,0,-1,0,333,333,"8011","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8012",7,"Con la música de afuera\nle toco en mi violincito;\nel corazón se me alegra,\nyo les canto muy quedito:\n“¡Qué chula señora güera!,\ncon gusto la felicito”.",139,2,2,150,"El huerfanito",9,6,"io",119,0,-1,0,333,333,"8012","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8013",7,"Contemplaba el firmamento\ncon la mirada decente (mi vida),\nvoy a decirle lo que siento,\nalegrando yo a la gente (mi vida)\nme dicen que el Banco del Centro\ncuenta con muy buen gerente.",138,2,6,150,"La madrugada",9,6,"ee",15,0,-1,0,333,333,"8013","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8014",7,"Lo digo, y no me arrepiento,\ntoco guitarra y violín;\npongo todo el sentimiento\ny al cantar no tengo fin;\nHellmer está muy contento,\nporque conoció a Tachín.",136,2,4,150,"El pájaro carpintero",9,6,"i",211,0,-1,0,333,333,"8014","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8015",7,"Toco guitarra y violín\ncon palabra salerosa;\ncantando no tengo fin;\nno interrumpiendo otra cosa,\nhora que toque el Tachín\ncon uno de los Pedroza.",136,2,4,150,"Estrofa suelta",9,6,"oa",195,0,-1,0,333,333,"8015","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8016",7,"Vengo con voz muy clarita,\ncon esta voz mexicana;\ntodo se me facilita\nal compás de mi jarana;\nTachín es el nuevo artista\nde la nación mexicana.",136,2,4,150,"El Ahualulco",9,6,"aa",4,0,-1,0,334,334,"8016","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8017",7,"El güero es un buen señor,\nnos honra con su presencia;\nhonrado y trabajador\ny de mucha inteligencia,\nporque ha sido lo mejor\nde toda su descendencia.",136,2,4,150,"El Balajú",9,6,"ea",46,0,-1,0,334,334,"8017","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8018",7,"Yo lo trato con cariño;\nun saludo muy decente,\npara que veas que te estimo;\nno tomo el aguardiente,\nestoy mirando que se fijen:\nte ves simpático con lentes.",136,2,4,150,"El siquisirí",9,6,"ee",-1,0,-1,0,334,334,"8018","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8019",7,"Le canto un verso decente\nal momento que llegué;\ncomo soy complaciente\nen mis versos te diré:\n“Con esos bonitos lentes,\ngüero, qué bien te ves”.",136,2,4,150,"El pájaro carpintero; El siquisirí; Estrofa suelta",9,6,"e",-1,0,-1,0,334,334,"8019","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8020",7,"Volando en un areoplano,\na este lugar llegué;\ncomo me llamo Epifanio,\ncantando te lo diré:\n“Con tu reloj en la mano,\n¡ah, qué bonito te ves!”",136,2,4,150,"El pájaro cú; El carpintero; Estrofa suelta",9,6,"e",-1,0,-1,0,334,334,"8020","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8021",7,"Y a orillas de aquel pueblito,\ndonde yo me bauticé,\ny dejé mi nombre escrito\ncon una G y una P;\nfumando tu cigarrito,\n¡ay, mi hijo, qué bien te ves!",136,2,4,150,"El Balajú; El pájaro cú",9,6,"e",-1,0,-1,0,334,334,"8021","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8022",7,"Les canto con gran franqueza\nal momento que llegué;\nque les canto con tristeza,\nen mi verso le diré:\n“Con esa foto en la mesa,\n¡ah, qué bonito se ve!”",136,2,4,150,"El carpintero",9,6,"e",77,0,-1,0,334,334,"8022","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8023",7,"Güero, tú debes de saber\nque yo toco mi jarana;\ncumpliendo eres un vergel\nen tierra veracruzana,\ny si no tienes mujer,\nte puedo dar a mi hermana.",135,2,-1,150,"La guacamaya",9,6,"aa",4,0,-1,0,334,334,"8023","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8024",7,"Porque soy inteligente,\nla verdad debo de hablar,\ncantándoles tiernamente,\ny el público va a escuchar;\n“Los señores de allí enfrente\nme quieren apantallar”.",135,2,-1,150,"La morena",9,6,"a",21,0,-1,0,335,335,"8024","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8025",7,"Y que esto les digo yo,\nno me puedo equivocar;\npara improvisar..............\ncuando me pongo a cantar;\nVíctor Hugo no se quedó;\nGloria, quiero practicar.",136,2,4,150,"Estrofa suelta",9,6,"a",21,0,-1,0,335,335,"8025","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8026",7,"A aquel que me lo decía,\nseñores, se lo hago ver,\ncon toda gallardía,\ncomo deben comprender,\nque a don Severiano Díaz\nyo quisiera conocer.",136,2,4,150,"Estrofa suelta",9,6,"e",20,0,-1,0,335,335,"8026","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8027",7,"Yo les cantaré este son\ny cantando nunca dudo;\nsi me pones atención,\nBeto Ávila, te pregunto:\n¿en tu reloj a qué horas son?",138,2,6,150,"Estrofa suelta",7,5,"o",-1,0,-1,0,335,335,"8027","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8028",7,"Para eso de la cantada\nyo siempre me pongo listo\ny le digo en mi cantar,\nsiempre le digo a don Sixto,\ntomando su alimentito.",138,2,6,150,"El huerfanito",7,5,"io",-1,0,-1,0,335,335,"8028","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8029",7,"Oiga, doña Rita Blanco,\nblanca flor de Alejandría,\nyo le vine a preguntar\ndónde está José María.",144,2,10,150,"El güerito",0,4,"ia",0,0,-1,0,335,335,"8029","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8030",7,"No me puedo equivocar,\nporque yo me pongo alerta;\ncantando en este lugar,\nyo les digo cosas ciertas:\n“A Jaime le fui a tocar,\npero no me abrió la puerta”.",136,2,4,150,"Estrofa suelta",9,6,"ea",-1,0,-1,0,335,335,"8030","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8031",7,"Pues tú me has de dispensar,\nque yo canto con amor;\npor aquí vino a pasear\nese señor grabador\ny del Distrito Federal.",139,2,2,150,"La leva",7,5,"a",-1,0,-1,0,335,335,"8031","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8032",7,"Estoy que el viento me azora,\nque ya no puedo ni hablar;\nque esto que le digo ahora\nno se le vaya a olvidar:\nque vino una profesora\naquí merito a grabar.",142,2,8,150,"Zapateado",9,6,"a",21,0,-1,0,335,335,"8032","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8033",7,"Al pasar por este puente\nmi cantar se precipita;\nlo digo galantemente,\ncomo dijo el agüelito:\n“El güero porta los lentes\npara conservar la vista”.",136,2,4,150,"El siquisirí",9,6,"ia",-1,0,-1,0,336,336,"8033","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8034",7,"Cuando me pongo a cantar,\na mí no me sirve el llanto;\ncomo te quiero tanto,\nen verso te voy a hablar:\n“Guáguara, no comas tanto,\nno te vayas a enfermar’”.",136,2,4,150,"El pájaro cú",9,6,"a",21,0,-1,0,336,336,"8034","",0,"","","",5,0,0,[],"",""],["frenk_t3-n8035",7,"Salí de mi casa al trote\na este lugar a cantar;\npresumo de mi gañote\ny en verso le voy a hablar:\n“Guáguara, con su bigote\nya parece general”.",136,2,4,150,"El carpintero",9,6,"a",-1,0,-1,0,336,336,"8035","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8036",7,"Voy a cantar un versito\ncon palabra muy ladina;\nlo digo recio y quedito:\nse murió mi Marina;\nel güero para comer\nle zumba la carabina.",136,2,4,150,"María Chuchena",9,6,"ia",11,0,-1,0,336,336,"8036","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8037",7,"En el lugar donde habito,\nlo digo con garantía,\nSIS\nes mi ciencia, jarochito,\nlo adivino que me río;\nestoy mirando aquel cojito,\npor Dios, un tío mío.",136,2,4,150,"El siquisirí",4,7,"io",-1,0,-1,0,336,336,"8037","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8038",7,"Huasteco yo soy, señores,\nahora acabo de llegar,\ny busco un tamaulipeco,\nde esos que sepan cantar\nal estilo Pueblo Viejo,\no como se hace en Zempoal.",136,2,4,150,"El huasteco",9,6,"a",-1,0,-1,0,336,336,"8038","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8039",7,"Pregunto y quiero saber\nquién es aquí el versador;\nsabrás que, aunque soy el peor,\nsólo a ti me he de oponer,\nporque he llegado a saber\nque, de once cielos que ha habido,\nninguno los ha medido\npor dirección a esta parte,\ny yo, por no avergonzarte,\nseñores, me había dormido.",136,2,4,150,"Estrofa suelta",18,10,"io",101,0,-1,0,336,336,"8039","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8040",7,"Yo también quiero licencia\ny a todos pido atención;\nme consume la impaciencia\npor dar mi contestación.",136,2,4,150,"La morena",1,4,"o",31,0,-1,0,336,336,"8040","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8041",7,"Soy un guía de San Andrés\ny también republicano,\ny aquí donde tú me ves;\nconmigo se dan la mano;\ntú me cantas en inglés,\nyo canto veracruzano.",135,2,-1,150,"La bamba",9,6,"ao",81,0,-1,0,337,337,"8041","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8042",7,"Si usted es buen compositor,\ncomponga un verso cantando,\nque el principio sea de amor\ny el final, despreciando.",142,2,8,150,"Estrofa suelta",1,4,"ao",33,0,-1,0,337,337,"8042","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8043",7,"¿Qué hay de aquellos cinco panes\nque Dios con su amor formó?\nPregunto: ¿quién se los dio\npara que los ensalzare,\no qué contuvo la vara\nque san José floreció?\nSupuesto es gusto de Dios,\npues para haber florecido,\npájaro, busca tu nido,\nque el águila real llegó.",136,2,4,150,"Estrofa suelta",18,10,"o",-1,0,-1,0,337,337,"8043","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8044",7,"Yo oí cantar un jilguero,\nque venía de Barragán;\nla respuesta de este verso\nsólo los viejos la dan:\n“¿De qué palo es el madero\ndel Señor de Petatlán?”",142,2,8,150,"Estrofa suelta",9,6,"a",147,0,-1,0,337,337,"8044","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8045",7,"Corté la flor de la tuna,\ninjertada con llanté.\nSin ofender a ninguna,\nquiero que me diga usted\ncuántos días tiene la luna.",135,2,-1,150,"Estrofa suelta",7,5,"ua",56,0,-1,0,337,337,"8045","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8046",7,"Para decírtelo a ti,\nconté la minutería;\nte voy a decir la cuenta,\nte digo con garantía,\nmil cuatrocientos cuarenta\ntiene la noche y el día.",142,2,8,150,"Zapateado",9,6,"ia",0,0,-1,0,337,337,"8046","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8047",7,"San Andrés con su reloj\nel horario está apuntando,\ny el minutero está dando\nlas horas que daba el ó.\nLa teología no sé yo,\npara que tú me profanes;\nno preguntes por caimanes,\nque así te contesto yo:\n“Qué si la aurora rayó,\nave maría, gavilanes”.",136,2,4,150,"Estrofa suelta",18,10,"ae",444,0,-1,0,337,337,"8047","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8048",7,"Te lo he dicho varias veces\ncon voz de diversos tipos;\nla ciencia nunca se crece\ncantándote así quedito,\na lo largo se parece\nnada más por lo gordito.",136,2,4,150,"Estrofa suelta",9,6,"io",119,0,-1,0,337,337,"8048","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8051",7,"Dando vueltas a un jagüey\nme puse a considerar:\nhora quero que me digas\ncuántos pelos tiene un buey.",139,2,2,150,"Estrofa suelta",5,4,"e",133,0,-1,0,338,338,"8051","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8056",7,"Siente grandes ilusiones\na veces este ranchero;\nno tendrá para calzones,\npero avienta hasta el sombrerc\noyendo tocar los sones.",138,2,6,150,"El ranchero potosino",7,5,"oe",34,0,-1,0,339,339,"8056","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8057",7,"El sombrero que me pongo,\nlo traje de San Martín;\na veces que me lo pongo\nvengo a escuchar el violín\ny me pongo mi jorongo.",139,2,2,150,"El sombrero",7,5,"oo",484,0,-1,0,339,339,"8057","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8058",7,"Viniendo de San Martín,\ncantando por las bodegas,\nla guitarra y el violín\n¡qué bonito se aconsejan!\nParecen recién casados:\ncada vueltita se besan.",138,2,6,150,"El caimán; La Malagueña",9,6,"ea",-1,0,-1,0,339,339,"8058","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8059",7,"Esta guitarrita mía\ntiene lengua y quiere hablar,\nsólo le faltan los ojos\npara ponerse a llorar,",135,2,-1,150,"Estrofa suelta",0,4,"a",21,0,-1,0,339,339,"8059","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8060",7,"Esta guitarra es de fierro,\nlas clavijas, de nogal;\nsólo las cuerdas le faltan\npara empezar a llorar.",135,2,-1,150,"Esta guitarra es de fierro",0,4,"a",-1,0,-1,0,339,339,"8060","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8061",7,"Cuando comienza el fandango\nya se empiezan a afinar,\nse arrancan con un huapango\ny se ponen a cantar.",136,2,4,150,"Canto a Veracruz",1,4,"a",21,0,-1,0,339,339,"8061","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8062",7,"¿En dónde está\nmi saxofón,\nque no lo veo\nen el rincón?",147,2,11,150,"El saxofón",6,4,"o",31,0,-1,0,339,339,"8062","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8063",7,"¡Dale, dale a esa guitarra\ny acábala de quebrar!,\nque en ese Guadalajara\nhay guitarras a Dios dar,\npero no se dan en guías\npara llegar y cortar.",145,2,17,150,"Estrofa suelta",9,6,"a",21,0,-1,0,339,339,"8063","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8064",7,"Este violín es un piano,\nlas clavijas, de nogal;\nel que lo toca es indiano,\nel que canta es Pascual,\nal estilo mexicano.",138,2,6,150,"El huerfanito",7,5,"ao",81,0,-1,0,339,339,"8064","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8065",7,"Comenzaron a pasear,\nle dieron pa el Barrio Abajo,\nJuan Silva con su instrumento\ny Juventino con su bajo.",146,2,7,150,"Estrofa suelta",0,4,"ao",168,0,-1,0,340,340,"8065","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8066",7,"A las dos de la mañana\n[oí a un mariachi tocar]:\nera el Mariachi Vargas,\nque andaba por el portal,\ndándole serenata\na las flores del lugar.",145,2,17,150,"oí a un mariachi tocar]: era el Mariachi Vargas, que andaba por el portal,",9,6,"a",-1,0,-1,0,340,340,"8066","",0,"","","",7,0,0,[],"",""],["frenk_t3-n8067",7,"Contratiempo del mariachi\ncanta en toda su alegría,\nentre vuelos de manganas\ny relinchos de dolor.",135,2,-1,150,"Jalisco nunca pierde",5,4,"o",-1,0,-1,0,340,340,"8067","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8068",7,"¡Canten, canten, canten,\naunque no haya orquesta,\nesta “Media bamba”,\nque es de mi Huasteca!",136,2,4,150,"La media bamba",6,4,"ea",-1,0,-1,0,340,340,"8068","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8069",7,"Ándenle, muchachos,\nque ya llegó el pajarillo,\ny nos llegó la mañana\ncon toditos sus amigos.",142,2,8,150,"La Malagueña curreña",0,4,"io",-1,0,-1,0,340,340,"8069","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8070",7,"¡Toca, toca, mi jarana!,\n¡llora, llora, mi violín!,\n¡canta, canta, huapanguero!,\nque me quiero divertir.",135,2,-1,150,"Estrofa suelta",0,4,"i",-1,0,-1,0,340,340,"8070","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8071",7,"Si quieres que no te olvide,\nsi quieres que te recuerde,\ncanta sones alegres (mi vida),\nmúsica que nunca muere.",135,2,-1,150,"La Martiniana’T",3,4,"ee",-1,0,-1,0,340,340,"8071","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8072",7,"¡Ay, te pido, te pido\nde compasión\nque se acabe “La bamba”\ny venga otro son.",136,2,4,150,"La bamba",6,4,"o",31,0,-1,0,340,340,"8072","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8073",7,"Echa versos, Marcelina,\nque alegran los corazones,\nque para subir al cielo\nno es necesario escalones.",142,2,8,150,"La Sanmarqueña",0,4,"oe",34,0,-1,0,340,340,"8073","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8074",7,"En esta estación cariñosa,\ndonde alegres cantaban las aves,\nvamos pues, mi querida Rosita,\na escuchar estos bellos cantares.",135,2,-1,150,"La pajarera’",3,4,"ae",-1,0,-1,0,341,341,"8074","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8075",7,"¡Por Dios, qué borracho vengo!\nQue me siga la tambora,\nque me toquen “El quelite”,\ndespués “El niño perdido”\ny por último “El torito”,\npa que vean cómo me pinto.",149,2,20,150,"El sinaloense",9,6,"io",-1,0,-1,0,341,341,"8075","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8076",7,"Quiero que toquen\n“Mi preferida”,\npara que pueda\nalegrarme la vida.",135,2,-1,150,"Mi preferida",3,4,"ia",37,0,-1,0,341,341,"8076","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8077",7,"Vengan canciones,\nque ando contento,\npara olvidarme\nde un sentimiento.",135,2,-1,150,"Mi preferida",6,4,"eo",94,0,-1,0,341,341,"8077","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8078",7,"Ahorita no sé quién soy,\nmesero, traiga otro trago,\nmariachis, cántenme ya,\ngrítenme, piedras del campo.",135,2,-1,150,"Que me lleve el diablo",0,4,"ao",-1,0,-1,0,341,341,"8078","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8079",7,"Amigos, yo soy sincero,\ny aquí lo estoy demostrando;\nque toquen los panuqueros,\nlos que tocan el huapango,\nque se los den de dinero.",136,2,4,150,"El perdiguero",7,5,"eo",-1,0,-1,0,341,341,"8079","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8080",7,"Choquen las copas\nahora que hay modo,\nque al fin y al cabo\n¡qué importa todo!",135,2,-1,150,"Mi preferida",6,4,"oo",261,0,-1,0,341,341,"8080","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8081",7,"Ahora sí, mis cancioneros,\ncántense una, pero buena,\nla de “morir con ellas”,\nque nos hagan suspirar.",137,2,3,150,"El Aguila negra’",5,4,"a",-1,0,-1,0,341,341,"8081","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8082",7,"Para olvidarme de tantas penas,\nya no las siente mi corazón;\nvengo a cantarles a las morenas,\npa que se acuerden de mi canción.",137,2,3,150,"Las morenitas",3,4,"o",31,0,-1,0,341,341,"8082","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8083",7,"Me gusta cantar falsete\npara calmar mis pesares,\nme gusta cantar falsete\npara disipar mis males.",135,2,-1,150,"Amores en falsete",0,4,"ae",-1,0,-1,0,342,342,"8083","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8084",7,"Yo canto cuando quiero\ny estoy contento,\ny ahogo con mis cantares\nmis sufrimientos\ny mis lamentos.",135,2,-1,150,"El tamaulipeco",7,5,"eo",234,0,-1,0,342,342,"8084","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8085",7,"Bajo la sombra de un árbol\ny al compás de mi guitarra,\ncanto alegre este huapango,\nporque la vida se acaba,\ny quiero morir cantando,\ncomo muere la cigarra.",147,2,11,150,"La cigarra",9,6,"aa",-1,0,-1,0,342,342,"8085","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8086",7,"El que escuche mi cantar\ndirá que estoy muy contento:\nyo canto por divagar\nesta pasión que yo siento\ny que no puedo olvidar.",138,2,6,150,"El sueño*! 19",7,5,"a",21,0,-1,0,342,342,"8086","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8087",7,"No creas que porque canto (Llorona)\ntengo el corazón alegre:\ntambién de dolor se canta (¡ay, Llorona!)\ncuando llorar no se puede.",142,2,8,150,"La Llorona",3,4,"ee",-1,0,-1,0,342,342,"8087","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8088",7,"¡Ay, corazón!,\n¡ay, corazón!,\n¡canta, canta tu dolor,\ncorazón!",135,2,-1,150,"Canta, corazón, canta",6,4,"o",-1,0,-1,0,342,342,"8088","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8089",7,"Yo no canto porque me oigan,\nni porque mi voz sea buena (¡ay de mí, Llo-\nyo canto porque no caiga [rona!),\nel dolor sobre la pena (¡ay de mí, Llorona!).",136,2,4,150,"La Llorona",3,4,"oa",-1,0,-1,0,342,342,"8089","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8090a",7,"Debajo del árbol canta\ny el pájaro cuando llueve,\ntambién de pesar se canta\ncuando llorar no se puede.",135,2,-1,150,"Chilena de [amiltepec; Ahora acabo de llegar",0,4,"ee",-1,0,-1,0,342,342,"8090a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8091",7,"Las avecillas que cantan en el viento\nhagan el duelo que yo también haré;\nvengo a cantarles de amor un sentimiento,\npero aunque triste, las acompañaré.",137,2,3,150,"Las aves",3,4,"e",77,0,-1,0,343,343,"8091","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8092",7,"Es muy triste recordar\nlo que somos en la vida;\nponiéndonos a pensar,\nson ilusiones perdidas\nlas que vamos a cantar.",136,2,4,150,"La presumida; El amor que te has robado",7,5,"a",21,0,-1,0,343,343,"8092","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8093",7,"Yo soy un cantadorcito,\nque vivo desengañado,\ny me lamento solito\nporque siendo desdichado,\nhoy canto este “Bejuquito”\ny siempre disimulado.",136,2,4,150,"'El bejuquito; El fandanguito",9,6,"ao",14,0,-1,0,343,343,"8093","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8094",7,"Cuando me encuentro solito\nganas me dan de llorar;\nluego les echo un grito\ny les empiezo a cantar,\neste hermoso “Fandanguito”.",135,2,-1,150,"El fandanguito",7,5,"io",119,0,-1,0,343,343,"8094","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8095",7,"¡Qué bonito es lo bonitol,\n¿a quién no le ha de gustar?\nCuando canto “El bejuquito”\nganas de llorar me dan\ncuando me encuentro solito.",139,2,2,150,"El bejuquito",7,5,"io",119,0,-1,0,343,343,"8095","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8096",7,"Cuando canto “El fandanguito”\nganas de llorar me dan;\nrecuerdo de un amorcito\nque he dejado en Miramar,\nen el puerto de Tampico.",138,2,6,150,"El fandanguito",7,5,"io",-1,0,-1,0,343,343,"8096","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8097",7,"El Norte y el Sur peleando,\ntambién la atmósfera azul;\nque cuando canta “El pijul”\nmi alma se suelta llorando.",136,2,4,150,"El pljul’",3,4,"ao",33,0,-1,0,343,343,"8097","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8098",7,"Ya me voy a retirar,\nporque está soplando el viento;\nque cuando canta “El pijul”\nme lleno de sentimiento.",136,2,4,150,"El pijul’T",0,4,"eo",94,0,-1,0,343,343,"8098","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8099",7,"Naciendo empecé a cantar,\ny cantando me despido;\ndicen que no sé llorar,\naunque viva entristecido,\ny es que yo me sé aguantar,\naunque llueva muy tupido.",135,2,-1,150,"De puro Veracruz",9,6,"io",101,0,-1,0,343,343,"8099","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8100",7,"Con permiso, compañeros,\nles diré lo que conviene:\neste cantar de mujer\nel músico es lo que pide:\n¡ay, esta pasión lo hiere!",136,2,4,150,"El huerfanito",7,5,"ee",-1,0,-1,0,344,344,"8100","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8101",7,"Ya con ésta me despido\ncon el alma entristecida;\nya les canté los dolores\ny [las penas] de mi vida.",142,2,8,150,"Pajarillo barranquefio",0,4,"ia",37,0,-1,0,344,344,"8101","",0,"","","",72,0,0,[],"",""],["frenk_t3-n8102",7,"Ya está la sala regada\ncon aguardiente y mistela:\nparece que se han juntado\nel clavo con la canela.",151,2,23,150,"Ya está la sala regada",0,4,"ea",167,0,-1,0,344,344,"8102","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8104",7,"Un amigo y yo con él\ncompramos una jarana,\ntocamos un “Cascabel”,\ny lo bailó Miguel Triana.",136,2,4,150,"El cascabel",1,4,"aa",4,0,-1,0,344,344,"8104","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8105",7,"Les dedico este huapango\ncon redobles de jarana;\nme gusta pa zapatearlo\ncon alma muy mexicana.",135,2,-1,150,"El as de los huapangos",0,4,"aa",4,0,-1,0,344,344,"8105","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8106",7,"Váyanse parando\ntodos a bailar\neste nuevo baile,\nque les va a gustar.",136,2,4,150,"El huateque",0,4,"a",21,0,-1,0,344,344,"8106","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8107",7,"Este bailecito\nque yo traigo aquí\nes pa divertirse\ny también para reír.",135,2,-1,150,"Las bombas viejas",0,4,"i",-1,0,-1,0,344,344,"8107","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8108a",7,"Zumba, rezumba,\ny que siga zumbando\neste sonecito\nque les va gustando.",136,2,4,150,"La media bamba",3,4,"ao",33,0,-1,0,344,344,"8108a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8109",7,"Bailen, bailen, bailen,\ny sigan bailando\nesta “Media bamba”\nque les va gustando.",136,2,4,150,"La media bamba",0,4,"ao",33,0,-1,0,345,345,"8109","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8110",7,"Bailen, bailen, y no dejen de bailar,\nen la tarima no dejen de zapatear;\néste es el son que se baila en toda mi tierra,\nque le dicen canción de “La yerbabuena”.",136,2,4,150,"La yerbabuena",3,4,"ea",-1,0,-1,0,345,345,"8110","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8111",7,"Baila, baila, baila, indito,\nno bailes de mala gana;\nsi se rompen tus guaraches,\nte los compraré mañana.",136,2,4,150,"A la Virgen de Guadalupe",0,4,"aa",4,0,-1,0,345,345,"8111","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8112",7,"Proseguid, monarca,\nbaila tocotín,\ncon pasos mundanza\ny el cuerpo gentil.",140,2,12,150,"Los tocotines",0,4,"i",-1,0,-1,0,345,345,"8112","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8113",7,"Bailen, bailen, palomitas,\ny no dejen de bailar,\nque aunque esté el palomo triste,\nbailando se va a alegrar.",135,2,-1,150,"La palomita",0,4,"a",21,0,-1,0,345,345,"8113","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8114",7,"Bailen, bailen, bailen,\ncon mucha atención,\nque el son del “Huateque”\nes un vacilón.",136,2,4,150,"El huateque",0,4,"o",31,0,-1,0,345,345,"8114","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8115",7,"Bailen, bailen, bailen,\nbailen sin parar,\nque el son del “Huateque”\nya se va a acabar.",136,2,4,150,"El huateque",0,4,"a",21,0,-1,0,345,345,"8115","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8116",7,"Viborita, viborita,\nviborita de colores,\nsáquenle la vueltecita,\ny al estilo Pisaflores.",139,2,2,150,"La viborita",1,4,"oe",5,0,-1,0,345,345,"8116","",0,"frenk_t4","","",8,0,0,[],"",""],["frenk_t3-n8117",7,"Hazte chiquito,\nhazte grandote,\nlos enanitos,\nlos enanotes.",136,2,4,150,"Los enanos; Estrofa suelta",6,4,"oe",-1,0,-1,0,346,346,"8117","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8118",7,"Échale un pasito,\nque es muy divertido:\nhasta los viejitos\npierden el sentido.",136,2,4,150,"La media bamba",0,4,"io",-1,0,-1,0,346,346,"8118","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8119",7,"Fandanguero, fandanguero,\nfan[dan]guero, fandanguerito,\nsi quieres tener mi cariño,\nbáñame este “Fandanguito”.",135,2,-1,150,"El huapanguero",0,4,"io",-1,0,-1,0,346,346,"8119","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8120",7,"Ándele, compadre,\nsaque a su comadre,\nque si no la saca,\nyo le acabo el baile.",135,2,-1,150,"La botella’’",0,4,"ae",-1,0,-1,0,346,346,"8120","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8121",7,"Bailaba Marcelina,\nbailaba para acá;\nasí estaban cantando\nlos versos del “Colás”.",136,2,4,150,"El Colás",0,4,"a",-1,0,-1,0,346,346,"8121","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8122",7,"Si quieres, si puedes,\nsi no, tú me dirás;\n¡ay, qué bonito baila\nla mujer de Nicolás!",136,2,4,150,"El Colás",0,4,"a",51,0,-1,0,346,346,"8122","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8123",7,"¡Qué florecita más bella\npara alegrar la reunión!\nHan bajado las estrellas:\nno hay mayor satisfacción\nque mirar a unas bellas\ncuando están bailando el son.",136,2,4,150,"El siquisirí",9,6,"o",31,0,-1,0,346,346,"8123","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8124",7,"En las ramas de un caimito\ncanta un pájaro galán;\náhi le dice un gurrioncito\ncon anhelo y con afán:\n“Mujeres, bailen bonito,\nque les está cantando Juan”.",142,2,8,150,"El siquisirí",9,6,"a",147,0,-1,0,347,347,"8124","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8125",7,"Todas esas niñas de la Bella Union,\nbailan muy alegres danza y rigodón;\nparecen señoras de gran calidad\ny a la pasadita, tan darín darán.",135,2,-1,150,"La pasadita",3,4,"a",-1,0,-1,0,347,347,"8125","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8126",7,"¡Qué bien se escucha el violín\ncon jarana y huapanguera!\n¡Qué bien baila don Fermín\ncon la que va a ser mi suegra!",136,2,4,150,"La vara de mi violín’T",0,4,"ea",-1,0,-1,0,347,347,"8126","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8127a",7,"Ya salieron a bailar\nla rosa con el clavel:\nla rosa tirando flores,\nel clavel a recoger.",135,2,-1,150,"Ahora pregunto, pregunto; Que comienzo, que comienzo",0,4,"e",-1,0,-1,0,347,347,"8127a","",0,"","","",5,0,0,[],"",""],["frenk_t3-n8128",7,"Ése que salió a bailar\ntiene cuerpo de soldado;\nla mujer que lo acompaña\nparece un clavel morado.",135,2,-1,150,"Estrofa suelta",0,4,"ao",14,0,-1,0,347,347,"8128","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8129",7,"La mujer que anda bailando\ntrae perlas en el pescuezo;\nel hombre que la acompaña\n¿por qué no le brinda un beso?",151,2,23,150,"Ya está la sala regada",0,4,"eo",48,0,-1,0,347,347,"8129","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8130",7,"Bailadores, tengan cuidado,\nque el cangrejito les anda cerca;\nvaya fuerte ese zapateado\ncon sabrosura y muy alerta.",135,2,-1,150,"El cangrejo",3,4,"ea",-1,0,-1,0,347,347,"8130","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8131",7,"Es de los que bailan\ngrande obligación\ndarle a su pareja\nvino y polvorón.",141,2,1,150,"Los panaderos",0,4,"o",31,0,-1,0,347,347,"8131","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8132",7,"La güerita del fandango\nya se cansó de bailar:\ncomo ya es de madrugada\nya comienza a bostezar.",141,2,1,150,"‘‘Fiesta huasteca",0,4,"a",21,0,-1,0,348,348,"8132","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8133",7,"Este baile se acabó,\nyo a mis hijas me las llevo,\nel que bailó, bailó,\ny si no, hasta el año nuevo.",147,2,11,150,"Estrofa suelta",1,4,"eo",240,0,-1,0,348,348,"8133","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8134",7,"Vamos al baile, y verás qué bonito,\ndonde se alumbran con veinte linternas,\ndonde se bailan las danzas modernas,\ndonde se baila de mucho vacilón.",138,2,6,150,"La Jesusita",3,4,"o",-1,0,-1,0,348,348,"8134","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8135",7,"Vamos al baile, y verás qué bonito,\ndonde se alumbran con cuatro faroles,\ndonde es el gusto de todos los hombres,\ndonde se baila de punta y talón.",144,2,10,150,"La Jesusita",3,4,"o",-1,0,-1,0,348,348,"8135","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8137",7,"Cuando vayas al fandango\nponte tus naguas azules,\npa que salgas a bailar\nsábado, domingo y lunes.",145,2,17,150,"Las copetonas; La indita; María Lupe; La negra",0,4,"ue",-1,0,-1,0,348,348,"8137","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8138",7,"Cuando vayas al fandango\nponte tus naguas rabonas,\npa que salgas a bailar\nel son de “Las copetonas”.",135,2,-1,150,"Las copetonas",0,4,"oa",549,0,-1,0,348,348,"8138","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8139",7,"Aniba de Cihuatlán\nme dio el agua a la rodilla,\nsólo por bailar contigo,\ncihualteca de mi vida.",143,2,18,150,"El Cihualteco",0,4,"ia",-1,0,-1,0,348,348,"8139","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8140",7,"Muy alegres bailemos jarabe,\nun jarabe muy bien zapateado,\nque se luzca tu cuerpo gracioso,\nchaparrita de mi corazón.",135,2,-1,150,"Ya no lloverá, pelonas",3,4,"o",-1,0,-1,0,349,349,"8140","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8141",7,"Arrímese tantito,\nno se haga para atrás;\nrejúntese un poquito,\nno vaya a resbalar.",135,2,-1,150,"El amor de mi vida",0,4,"a",-1,0,-1,0,349,349,"8141","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8142",7,"Ándale, María Lupe,\nno me hagas un desaire,\ny arrejúntate conmigo\npara tupirle al baile.",135,2,-1,150,"María Lupe",0,4,"ae",-1,0,-1,0,349,349,"8142","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8143",7,"Hora dale y dale durito,\nvenimos pa estar bailando;\nhe venido por el aire,\nno me baile usted toreando.",142,2,8,150,"El cascabel",3,4,"ao",33,0,-1,0,349,349,"8143","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8144",7,"Ese que bailó contigo\ndices que te ama de veras;\nyo no sé lo que consigo\nrecordando lo que fueras;\nhoy bailarás conmigo,\naunque quieras o no quieras.",136,2,4,150,"El Balajú",9,6,"ea",103,0,-1,0,349,349,"8144","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8146",7,"Bailemos, bailemos\nla “Flor de naranjo”;\ncantemos, cantemos\nla “Flor de naranjo”;\nvamos, criatura, bailemos\nla “Flor de naranjo”;\nven, ven, bailemos\nla “Flor de naranjo”;\nquiéreme, quiéreme,\ncantando la “Flor de naranjo”.",142,2,8,150,"Flor de naranjo",18,10,"ao",-1,0,-1,0,349,349,"8146","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8147",7,"Ahora que estamos juntos\nvamos a jugar con brillo,\ntomar y bailar contentos\nhasta quebrar el ladrillo.",135,2,-1,150,"Las mañanitas",0,4,"io",228,0,-1,0,349,349,"8147","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8148",7,"Saca tu pañuelo, que vas a bailar\neste son huasteco, que te va a gustar;\ndespués, vida mía, te voy a cantar\nel ‘Cielito lindo” y también “El caimán”.",136,2,4,150,"La vara de mi violín",3,4,"a",-1,0,-1,0,349,349,"8148","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8149",7,"¡Qué guapa y recién peinada\nque te veo salir bailando!\nPon cuidado en mi versada\nporque te voy explicando:\nno me dejes la tirada,\nque me están martirizando.",142,2,8,150,"El siquisirí",9,6,"ao",33,0,-1,0,350,350,"8149","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8150a",7,"Luego iremos a la feria\na bailar un zapateado,\nal compás de los huapangos,\ncon pasitos muy marcados.",139,2,2,150,"El rebozo",0,4,"ao",-1,0,-1,0,350,350,"8150a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8150b",7,"Tú irás de china poblana,\ncon tus vestidos chillantes,\ny yo vestido de charro:\nnos veremos elegantes.",135,2,-1,150,"El rebozo",0,4,"ae",262,0,-1,0,350,350,"8150b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8150c",7,"Nos iremos a la feria\na bailar un zapateado;\nirás de china poblana,\ncon tus zapatos brillantes,\ny yo vestido de charro:\nnos veremos elegantes.",150,2,24,150,"El rebozo",9,6,"ae",262,0,-1,0,350,350,"8150c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8151",7,"Si zapateas bonito,\nyo te prometo\nhacer con el polvito —de tus zapatos\nun amuleto,\nque me dé suerte,\npara que no me olvides —y me acompañes\nhasta la muerte.",135,2,-1,150,"Cuidadito",4,7,"ee",134,0,-1,0,350,350,"8151","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8152",7,"Si zapateas bonito\nyo te prometo\ny hacer con el polvito —de tus zapatos\nun amuleto;\nmucho cuidado,\nque si pisan tu sombra —yo te aseguro\nque me han pisado.",142,2,8,150,"Cuidadito",4,7,"ao",14,0,-1,0,350,350,"8152","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8153",7,"Y arrima tu butaquito —tu butaquito\ny tu butacón,\ny pégale recio, recio —de puntillas\ny de tacón.",136,2,4,150,"Cielito lindo",3,4,"o",31,0,-1,0,350,350,"8153","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8154",7,"Que mira mi negra, mi santa,\n¿cómo quieres que te quiera,\nchiquitita de mi vida?\nVamos a ver cómo te mueves;\ntú, mi negra, baila, santa.",136,2,4,150,"La bamba",7,5,"aa",-1,0,-1,0,350,350,"8154","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8155",7,"-Indita, ¿por qué estás triste?\n—Señores, por fandanguera:\n¡Cómo bailan las inditas,\nseñores, de esta manera!",160,2,19,150,"El indio mexicano",0,4,"ea",44,0,-1,0,350,350,"8155","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8156",7,"Desde la orilla del mar\ncontemplo el gusto exquisito\nque practicas al bailar;\ntus pies de seda, repito,\nme seducen al pasar.",141,2,1,150,"El fandanguito",7,5,"a",21,0,-1,0,351,351,"8156","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8157",7,"Tanta gracia te dio el cielo\npara bailar, prenda mía,\nque al verte bailar jarabe\njuré no eras de este suelo.",135,2,-1,150,"Estrofa suelta",5,4,"eo",10,0,-1,0,351,351,"8157","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8158",7,"Oye pues, baila, sí,\n“El can-can” con los pies;\nbaila, te lo ruego,\nbáilamelo otra vez.",135,2,-1,150,"El can-can",0,4,"e",150,0,-1,0,351,351,"8158","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8160",7,"Oiga usted, morenita,\nbaile usted recio;\npueda ser que algún día\nle dé a usted un beso.",142,2,8,150,"La bamba",6,4,"eo",-1,0,-1,0,351,351,"8160","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8161",7,"No te alejes, no te alejes,\nno te alejes, doña Clarita,\nque van a empezar a bailar\neste son “huapanguerito”.",136,2,4,150,"El huapanguero",5,4,"io",-1,0,-1,0,351,351,"8161","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8162",7,"Con violín y huapanguera\n¡qué bien se escucha este son!\nQue salga a bailar la güera,\npa tupirle al vacilón.",147,2,11,150,"Fiesta huasteca",1,4,"o",31,0,-1,0,351,351,"8162","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8163",7,"Venga ya, comadre Juana,\ndéjese de misticismos;\nbailaremos “El jarabe”\ny perderemos el juicio;\nno hay nada que me cuadre\ncomo este zangoloteo.",135,2,-1,150,"El jarabe",9,6,"eo",-1,0,-1,0,351,351,"8163","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8164",7,"Ándele, comadre,\nbaile la botella,\ny si me la tumba,\nme la vuelve llena.",135,2,-1,150,"El jarabe; La botella",0,4,"ea",-1,0,-1,0,351,351,"8164","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8165",7,"Damos la vuelta,\ny sube, Ramona;\nparece sentirse\nmuy sabrosona.",141,2,1,150,"La pollita pinta",6,4,"oa",7,0,-1,0,351,351,"8165","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8166",7,"¡Cuando quisiera que me amaras\ny que tú quisieras enseñarme a mí\na bailar como tú bailas\n“El can-can” hermoso que fue!",135,2,-1,150,"El can-can",3,4,"e",-1,0,-1,0,352,352,"8166","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8167",7,"¡Qué tristeza me ha de dar\ncuando yo salga y no te halle\npa que salgas a bailar\nese son del “Pasacalle”!",137,2,3,150,"El pasacalle",1,4,"ae",371,0,-1,0,352,352,"8167","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8168",7,"Cuando ella sale al jardín\ny tocan “La Sanmarqueña”,\nparece sentir cosquillas\npara bailar la chilena.",142,2,8,150,"Chilena de Putla",0,4,"ea",-1,0,-1,0,352,352,"8168","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8169",7,"Voy a empezar a cantar\neste son de “El cascabel”,\na ver si puedo entonar\ncomo baila esa mujer,\ny si no puedo llegar,\nseguirá mi padecer.",136,2,4,150,"El cascabel",9,6,"e",20,0,-1,0,352,352,"8169","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8170",7,"Esa que salió a bailar\nmi corazón la persigue;\ndígame cómo se llama,\nyo preguntaré dónde vive.",142,2,8,150,"Estrofa suelta",0,4,"ie",-1,0,-1,0,352,352,"8170","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8171",7,"La huasteca está de fiesta,\nvengan todos a bailar;\nque me echen “El fandanguito”\npa poderlo pespuntear.",147,2,11,150,"Fiesta huasteca",0,4,"a",21,0,-1,0,352,352,"8171","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8172",7,"Todos me miran a mí\npor la gracia que yo tengo;\nal golpe de la tambora\nyo les bailo este merengue.",146,2,7,150,"El muñeco de la ciudad",5,4,"ee",-1,0,-1,0,352,352,"8172","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8173",7,"Negro, negro nací,\nporque así lo quiso Dios;\nme gusta bailar el merengue\nasí como bailo yo.",146,2,7,150,"El muñeco de la ciudad",0,4,"o",-1,0,-1,0,352,352,"8173","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8174",7,"Ahora acabo de llegar del Ahualulco\nde bailar con las cubanas;\n“Vamos para mi tierra”\nme dijo una mexicana.",136,2,4,150,"El Ahualulco",3,4,"aa",-1,0,-1,0,352,352,"8174","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8175",7,"Ahora acabo de llegar del Ahualulco,\nde cantar y bailar en Catemaco,\ncon mi china moreleña,\nque de ella traigo el retrato.",136,2,4,150,"El Ahualulco",3,4,"ao",-1,0,-1,0,352,352,"8175","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8176",7,"Ahora acabo de llegar del Ahualulco,\nde cantar y bailar en el santuario,\ncon las hembras tapatías,\nque llevan su escapulario.",136,2,4,150,"El Ahualulco",3,4,"ao",25,0,-1,0,353,353,"8176","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8177",7,"Ahora acabo de llegar del Ahualulco,\nde cantar y bailar en Tres Zapotes,\nque bailan este jarabe\nlas muchachas de Perote.",136,2,4,150,"El Ahualulco",3,4,"oe",-1,0,-1,0,353,353,"8177","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8178",7,"Ahora acabo de llegar del Ahualulco,\nde bailar el jarabe moreliano,\nque bailan las tapatías\ny muchachas mexicanas.",136,2,4,150,"El Ahualulco",3,4,"aa",-1,0,-1,0,353,353,"8178","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8179",7,"Ahora acabo de llegar del Ahualulco,\nde bailar este jarabe tapatío,\ncomo dicen que lo cantan y lo bailan\nlas muchachas bailadoras del Bajío.",136,2,4,150,"El Ahualulco",3,4,"io",3,0,-1,0,353,353,"8179","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8180",7,"Ahora acabo de llegar del Ahualulco,\nde cantar este jarabe de Morelia,\ncomo dicen que lo cantan y lo bailan\nlas muchachas bailadoras de mi tierra.",136,2,4,150,"El Ahualulco",3,4,"ea",-1,0,-1,0,353,353,"8180","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8181",7,"Ahora acabo de llegar del Ahualulco,\nde cantar este jarabe moreliano,\ncomo dicen que lo cantan y lo bailan\nlas muchachas bailadoras de los llanos.",136,2,4,150,"El Ahualulco",3,4,"ao",-1,0,-1,0,353,353,"8181","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8182",7,"Ahora acabo de llegar del Ahualulco,\nde bailar este jarabe moreliano,\nque me dicen que se mueren por bailarlo\nlas muchachas bailadoras de mi barrio.",147,2,11,150,"El Ahualulco",3,4,"ao",-1,0,-1,0,353,353,"8182","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8183",7,"Ahora acabo de llegar del Ahualulco,\nde bailar este jarabe con más ganas,\nque me dicen que se mueren por bailarlo\nlas simpáticas y bellas mexicanas.",136,2,4,150,"El Ahualulco",3,4,"aa",263,0,-1,0,353,353,"8183","",0,"","","",12,0,0,[],"",""],["frenk_t3-n8184",7,"Por la carretera de Iguala\nme alumbraban con ocote\ncuando me puse a bailar\neste son del “Zopilote”.",146,2,7,150,"El zopilote",0,4,"oe",292,0,-1,0,354,354,"8184","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8185",7,"No quiero luna,\nni quiero sol:\nyo lo que quiero\nes bailar rocanrol.",147,2,11,150,"Estrofa suelta",3,4,"o",24,0,-1,0,354,354,"8185","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8186",7,"De cansancio estoy muriendo,\nsin dejar a nadie herencia,\nporque esto se está volviendo\nun baile de resistencia.",152,2,13,150,"Estrofa suelta",1,4,"ea",46,0,-1,0,354,354,"8186","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8187",7,"Ya con ésta me despido,\nsubiendo y bajando lomas;\nbailaré como pudiere,\nno ando divirtiendo monas.",144,2,10,150,"Estrofa suelta",0,4,"oa",-1,0,-1,0,354,354,"8187","",0,"","","",72,0,0,[],"",""],["frenk_t3-n8188",7,"Hoy que es día de Todos Santos\ndice un loco en sus tonteras:\n“Son muchas las calaveras\ny muy pocos camposantos”.",135,2,-1,151,"Estrofa suelta",11,4,"ao",618,0,-1,0,355,355,"8188","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8189",7,"Oremos, oremos,\nangelitos sernos,\ndel cielo bajamos\npidiendo limosnas,\nsi no nos la dan,\npuertas y ventanas\nnos la pagarán.",144,2,10,151,"Pedir el muerto",4,7,"a",147,0,-1,0,355,355,"8189","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8190",7,"Si es la ofrenda un don sincero\nque se cede al que no existe,\nno hay un difunto más triste\nque un bolsillo sin dinero.\nY siendo mi bolsa cero,\nsoy muerto repartidor,\nque la ofrenda al suscriptor\npido con afán notorio;\ny él saque del purgatorio\nmi bolsa con su favor.",135,2,-1,151,"Estrofa suelta",18,10,"o",72,0,-1,0,355,355,"8190","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8191",7,"Antes que se acerque el día\nde Todos Santos y Muertos,\ny antes que nos veamos yertos\npor la Parca cruel e impía,\nimploro de tu hidalguía,\nuna ofrenda pequeñita,\npara comprar mi tumbita,\nmi entierro y mi calavera,\nunas velitas de cera\ny una preciosa animita.",135,2,-1,151,"Estrofa suelta",18,10,"ia",50,0,-1,0,355,355,"8191","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8192",7,"Aquí concluye la ofrenda\ndedicada a las placeras,\nque si hoy se encuentran vivas,\npronto se irán en partidas\na vivir con calaveras.",147,2,11,151,"Estrofa suelta",7,5,"ea",103,0,-1,0,355,355,"8192","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8193",7,"Áhi viene el agua\npor la ladera,\ny se me moja\nmi calavera.",144,2,10,151,"Estrofa suelta",6,4,"ea",44,0,-1,0,355,355,"8193","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8194",7,"La muerte calaca,\nni gorda, ni flaca;\nla muerte casera,\npegada con cera.",135,2,-1,151,"Estrofa suelta",5,4,"ea",44,0,-1,0,356,356,"8194","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8195",7,"La muerte siriquisiaca,\njalando su carretón,\nparece una sombra flaca\nbailando en el malecón.",147,2,11,151,"Los padres de San Francisco",1,4,"o",31,0,-1,0,356,356,"8195","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8196",7,"¡Qué rebundio había de muertos\nen el panteón de Belén!\nBailaban danzas y polkas\ncon la punta y el talón.",135,2,-1,151,"Estrofa suelta",5,4,"o",-1,0,-1,0,356,356,"8196","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8197",7,"Al pasar por el panteón\nyo vide una calavera,\ncon su cigarro en la boca (niña de mi corazón),\ncantando “La Petenera”.",145,2,17,151,"La Petenera",3,4,"ea",44,0,-1,0,356,356,"8197","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8199",7,"De San Sebastián salimos,\ndel barrio del Arrabal;\na pasar hemos venido\nla fiesta del carnaval.",163,2,21,151,"El carnaval",0,4,"a",1,0,-1,0,356,356,"8199","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8200",7,"De Tlaxcala hemos venido,\nde Tlaxcala para acá,\na jugar Carnestolendas\nal uso de por allá.",150,2,24,151,"Estrofa suelta, El carnaval; Los papaquis",0,4,"a",9,0,-1,0,356,356,"8200","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8201",7,"De Tlaxcala hemos llegado\ncon todita nuestra gente;\nnos la queremos echar\nde pulquito y aguardiente.",162,2,27,151,"zón), [Baile de la muñeca",0,4,"ee",15,0,-1,0,356,356,"8201","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8202",7,"Vamos, toquen el clarín,\nrevuelen la bandera,\nque nos vamos a la batalla\nde las Carnestolendas.",162,2,27,151,"Baile de la muñeca",0,4,"ea",-1,0,-1,0,356,356,"8202","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8203",7,"Jefes y soldados,\ntenemos que presenciar,\nque el martes estamos solicitados;\ncaretas y gorros que han de votar.",162,2,27,151,"Baile de la muñeca",3,4,"a",21,0,-1,0,357,357,"8203","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8204",7,"Soldado valiente,\nno se acobarde en su carrera,\nque el martes en la tarde\nestamos en la guerra.",162,2,27,151,"Baile de la muñeca’T",0,4,"ea",-1,0,-1,0,357,357,"8204","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8205",7,"Suenen, suenen “Los papaquis”,\nremolinen las banderas,\nporque estamos ya de fiesta\ny usando las chaparreras.",135,2,-1,151,"Los papaquis",0,4,"ea",-1,0,-1,0,357,357,"8205","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8206",7,"Vivan, vivan los papaquis,\ndonde están los cascarones;\noiga, amigo, no se raje,\nconquiste los corazones.",145,2,17,151,"Los papaquis",0,4,"oe",34,0,-1,0,357,357,"8206","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8207",7,"Cúbranse los cascarones\ncon amor y con cariño,\nque en estas carnestolendas\nsoy yo quien anda de niño.",145,2,17,151,"Los papaquis",0,4,"io",176,0,-1,0,357,357,"8207","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8208",7,"Ya se van los monos (Canelo)\npa el barrio de Santa Ana,\nel mono más grande (Canelo)\nlo lleva mi hermano.",136,2,4,151,"El Canelo",5,4,"ao",-1,0,-1,0,357,357,"8208","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8209",7,"Ya se van los monos (Canelo)\nmuy lejos de aquí,\ny el mono más grande dice (Canelo)\n“Échenmelo a mf’,\nque si no lo dice (Canelo),\nque te lo echen a ti.",136,2,4,151,"El Canelo",9,6,"i",23,0,-1,0,357,357,"8209","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8210",7,"Vámonos, vámonos, jovencitos,\nvámonos, vámonos a bailar;\nigualemos de alegría\nlas cintas del carnaval.",152,2,13,151,"El baile de las cintas; Estrofa suelta",3,4,"a",-1,0,-1,0,357,357,"8210","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8211",7,"Yo suplico a las autoridades\nque no quiten la diversión,\nque tengan gusto los indios\ny también los de razón.",162,2,27,151,"Baile de la muñeca",3,4,"o",31,0,-1,0,357,357,"8211","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8212",7,"¡Viva Huixquilucan!,\n¡viva el Palacio Municipal!,\n¡vivan los ciudadanos\nque nos dan licencia del Carnaval!",162,2,27,151,"Baile de la muñeca",3,4,"a",1,0,-1,0,357,357,"8212","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8214",7,"En el nombre sea de Dios,\nvamos a comenzar a bailar,\nque el permiso lo tenemos\ndel Palacio Municipal.",162,2,27,151,"■Baile de la muñeca",3,4,"a",-1,0,-1,0,358,358,"8214","",0,"","","",7,0,0,[],"",""],["frenk_t3-n8215",7,"Ave María, que ha llegado\nla máscara a la plaza;\nles saludamos, señores,\na todos los de esta casa.",162,2,27,151,"Baile de la muñeca",0,4,"aa",123,0,-1,0,358,358,"8215","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8216",7,"Ya llegó la niña,\nviene muy gustosa\na saludar a los señores,\na todos los de esta casa.",135,2,-1,151,"Baile de la muñeca",5,4,"aa",-1,0,-1,0,358,358,"8216","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8217",7,"Esta niña no es de aquí,\nes venida de Toluca;\nha venido aquí a gustar\nen el pueblo de Huixquilucan.",162,2,27,151,"Baile de la muñeca",0,4,"ua",-1,0,-1,0,358,358,"8217","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8218",7,"Esta niña no es de aquí,\nes venida de Veracruz;\nha venido aquí a gustar\nen el pueblo de Santa Cruz.",162,2,27,151,"Baile de la muñeca",0,4,"u",109,0,-1,0,358,358,"8218","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8219",7,"Esta niña que está bailando,\nbailando con amor,\nuna niña muy bonita,\nque se parece a una flor.",162,2,27,151,"Baile de la muñeca",0,4,"o",72,0,-1,0,358,358,"8219","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8220",7,"Levántate, niña hermosa,\nno te canses en bailar,\nmira que te están mirando\ncon su medio y con su real.",163,2,21,151,"El carnaval",3,4,"a",-1,0,-1,0,358,358,"8220","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8221",7,"Saludamos a esta casa\ncon mucho gusto y esmero,\ny que nos den un pulquito\ny un poco de dinero.",162,2,27,151,"Baile de la muñeca",0,4,"eo",38,0,-1,0,358,358,"8221","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8222",7,"Hoy que es día de gustar\nlos venemos a felicitar;\npara el año venidero\nsabe Dios quén vivirá.",162,2,27,151,"Baile de la muñeca",3,4,"a",-1,0,-1,0,359,359,"8222","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8223",7,"Vive Dios, que ya llegamos\na este palacio dichoso,\ndonde habita placentero\nun señor muy generoso.",135,2,-1,151,"Los papaquis",0,4,"oo",160,0,-1,0,359,359,"8223","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8224",7,"El señor que nos escucha\nbien nos puede dispensar\nque a deshoras de la noche\nyo lo venga a despertar.",135,2,-1,151,"Los papaquis",0,4,"a",21,0,-1,0,359,359,"8224","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8225",7,"Buenos días les dé Dios,\n¿cómo están, cómo les va?\n¿cómo están todos los niños?,\n¿no han tenido novedad?",145,2,17,151,"Los papaquis",0,4,"a",-1,0,-1,0,359,359,"8225","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8226",7,"Al señor Pancho Rivo,\npor ser un troncón,\nsu esposa, la rama\ny sus hijas, la flor.",146,2,7,151,"Los papaquis",0,4,"o",-1,0,-1,0,359,359,"8226","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8227",7,"Por aquí pasó la muerte\ncon su aguja y su dedal,\nremendando sus nagüitas\npara el día del carnaval.",147,2,11,151,"Estrofa suelta",0,4,"a",1,0,-1,0,359,359,"8227","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8228",7,"Que dice la media muerte\nque la dejen descansar,\nque ya llegó la Cuaresma,\ny se quiere confesar.",135,2,-1,151,"Que dice la media muerte; El siquisirí",0,4,"a",21,0,-1,0,359,359,"8228","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8229",7,"Despídanse de la carne,\ntambién de la longaniza,\nporque se nos va llegando\nel miércoles de ceniza.",135,2,-1,151,"Los papaquis; El güerito",0,4,"ia",420,0,-1,0,359,359,"8229","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8230a",7,"Vamos cantando, hermanito,\nque no se nos vuelva risa,\nque se nos está llegando\nel miércoles de ceniza.",135,2,-1,151,"La india",0,4,"ia",420,0,-1,0,359,359,"8230a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8231",7,"Por áhi viene la cuaresma\ncon un mes de requisitos:\nya no comeremos carne,\ncomeremos pescaditos.",145,2,17,151,"El carnaval",0,4,"io",254,0,-1,0,360,360,"8231","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8232",7,"Por áhi viene la cuaresma\ncon su maldito jornal;\nya no comeremos carne,\ncomeremos de pipián.",145,2,17,151,"El carnaval",0,4,"a",-1,0,-1,0,360,360,"8232","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8233",7,"Ya se llegó la cuaresma:\nahora todos los catrincitos\nya no tomarán carnita,\nsino puros nopalitos.",162,2,27,151,"Baile de la muñeca",3,4,"io",254,0,-1,0,360,360,"8233","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8234",7,"Ahí va la despedida,\nporque no nos vaya mal;\nsi vivimos de aquí a un año,\nnos acordaremos del carnaval.",162,2,27,151,"‘‘Baile de la muñeca",3,4,"a",1,0,-1,0,360,360,"8234","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8235",7,"Hasta el año venidero\nse repite la función,\ny entonces a este hervidero\nle repica el corazón.",145,2,17,151,"‘‘Los papaquis’T SS7",1,4,"o",31,0,-1,0,360,360,"8235","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8236",7,"Alabando a Dios,\nen primer lugar,\nPascuas de Año Nuevo\nvenimos a dar.",136,2,4,151,"‘‘Naranjas y limas",0,4,"a",21,0,-1,0,360,360,"8236","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8237",7,"Muy buenas noches,\nporque ya llegamos,\nporque en esta casa\nlas gracias les damos.",136,2,4,151,"Naranjas y limas",6,4,"ao",116,0,-1,0,360,360,"8237","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8238",7,"Alabando a Dios,\nporque ya llegamos,\n“Naranjas y limas”\nvenimos cantando.",136,2,4,151,"Naranjas y limas",0,4,"ao",-1,0,-1,0,360,360,"8238","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8239",7,"Alabando a Dios,\ny en primer lugar,\nlicencia pedimos\npara comenzar.",136,2,4,151,"Naranjas y limas",0,4,"a",21,0,-1,0,360,360,"8239","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8240",7,"Licencia pedimos,\nfamilia decente;\nsi los he ofendido,\ndispense a mi gente.",135,2,-1,151,"Naranjas y limas’T",0,4,"ee",15,0,-1,0,360,360,"8240","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8241",7,"Han de perdonar\nque ando incomodando:\nes el Año Nuevo\nque ando celebrando.",136,2,4,151,"Naranjas y limas’",0,4,"ao",33,0,-1,0,361,361,"8241","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8242",7,"Ya vienen las Pascuas,\nya vienen llegando,\npor eso nosotros\nlas andamos dando.",142,2,8,151,"Naranjas y limas",0,4,"ao",33,0,-1,0,361,361,"8242","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8243",7,"Les damos las Pascuas\ncon mucha alegría,\ncomo se las damos\na la Virgen María.",136,2,4,151,"Naranjas y limas’",0,4,"ia",0,0,-1,0,361,361,"8243","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8244",7,"Yo le doy la Pascua,\nno por su dinero,\nsólo por los santos\nque están en el cielo.",136,2,4,151,"Naranjas y limas’",0,4,"eo",-1,0,-1,0,361,361,"8244","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8245",7,"Les damos las Pascuas,\nno por su dinero,\nporque en esta casa\nvive un caballero.",136,2,4,151,"Naranjas y limas",0,4,"eo",38,0,-1,0,361,361,"8245","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8246",7,"Alabando a Dios,\nquítense el sombrero,\nporque en esta casa\nvivió un caballero.",135,2,-1,151,"Naranjas y limas",0,4,"eo",38,0,-1,0,361,361,"8246","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8247",7,"Vivió un caballero,\nvivió un general;\na la rama verde\nle vino a cantar.",136,2,4,151,"Naranjas y limas",0,4,"a",-1,0,-1,0,361,361,"8247","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8248",7,"Desde las montañas\nvenimos andando,\ny al señor Carrasco\nvenimos buscando.",136,2,4,151,"Naranjas y limas; Estrofa suelta",0,4,"ao",-1,0,-1,0,361,361,"8248","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8249",7,"No es la corona imperial,\nni la ciudad de Sevilla:\nes la Rama de escobilla,\nque te viene a visitar.",135,2,-1,151,"Estrofa suelta",5,4,"a",-1,0,-1,0,361,361,"8249","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8250",7,"Ya llega la Rama\ny sus cantadores,\npidiendo a esta casa\nun ramo de flores.",136,2,4,151,"Naranjas y limas",0,4,"oe",5,0,-1,0,361,361,"8250","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8251",7,"Naranjas y dulces,\nlimas y limones,\nasí son las fiestas\nde todas las flores.",147,2,11,151,"Estrofa suelta",0,4,"oe",-1,0,-1,0,362,362,"8251","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8252",7,"Blancas azucenas,\nlindos girasoles,\nnaranjas y limas,\nlimas y limones.",136,2,4,151,"Naranjas y limas",0,4,"oe",-1,0,-1,0,362,362,"8252","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8253",7,"Levántese usted\ny ponga atención:\nmire lo que anda\npor esta región.",136,2,4,151,"Naranjas y limas",6,4,"o",31,0,-1,0,362,362,"8253","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8254",7,"Salgan para afuera,\nverán qué [primores]:\nvprán a la Rama\ncubierta de flores.",136,2,4,151,"Naranjas y limas",6,4,"oe",5,0,-1,0,362,362,"8254","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8255",7,"Salgan para fuera,\nverán qué bonito:\nverán a la Rama\ncon su farolito.",136,2,4,151,"Naranjas y limas",0,4,"io",119,0,-1,0,362,362,"8255","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8256",7,"Vamos para afuera\ny verán qué bonito:\ndejamos la Rama\njuntito al olivo.",136,2,4,151,"Naranjas y limas",0,4,"io",-1,0,-1,0,362,362,"8256","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8257",7,"Salí de mi casa\ny ya estoy aquí,\naquí está la Rama,\nla que te ofrecí.",136,2,4,151,"Naranjas y limas",0,4,"i",23,0,-1,0,362,362,"8257","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8258",7,"Usted, señorita,\ncomo es muy decente,\nrecita la Rama\ncon toda su gente.",136,2,4,151,"Naranjas y limas",0,4,"ee",15,0,-1,0,362,362,"8258","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8259",7,"Ya nos despedimos\ncon mucha alegría,\ncomo la que tuvo\nsan José y María.",136,2,4,151,"Naranjas y limas",0,4,"ia",0,0,-1,0,362,362,"8259","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8260",7,"Ya nos despedimos\ny al pie de la puerta;\nhasta el Año Nuevo\ndaremos la vuelta.",136,2,4,151,"Naranjas y limas",0,4,"ea",-1,0,-1,0,362,362,"8260","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8261",7,"Este pobre viejo\nse muere de risa,\nporque a media noche\nse vuelve ceniza.",136,2,4,151,"Canto de Año Nuevo",0,4,"ia",420,0,-1,0,363,363,"8261","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8262",7,"Ésta sí que es Nochebuena,\nnoche de comer buñuelos,\ny en mi casa no los hacen,\npor falta de harina y huevo.",136,2,4,151,"Canto de Posadas",0,4,"eo",-1,0,-1,0,363,363,"8262","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8263",7,"La Nochebuena se viene,\nla Nochebuena se va,\ny nosotros nos iremos\ny no volveremos más.",135,2,-1,151,"Canto de Nochebuena",0,4,"a",-1,0,-1,0,363,363,"8263","",0,"palau_cantares","","",3,0,0,[],"",""],["frenk_t3-n8264a",7,"Una limosnita\npara este pobre viejo,\nque ha dejado hijos\npara el Año Nuevo.",135,2,-1,151,"Canto de Año Nuevo",3,4,"eo",-1,0,-1,0,363,363,"8264a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8265",7,"Y el señor Carrasco\ndebe dispensamos\ncon el aguinaldo\nque conmemoramos.",136,2,4,151,"Naranjas y limas",0,4,"ao",-1,0,-1,0,363,363,"8265","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8266",7,"Denme mi aguinaldo,\nsi me lo han de dar,\nque la noche es corta,\ny tenemos que andar.",136,2,4,151,"Naranjas y limas; Estrofa suelta",0,4,"a",21,0,-1,0,363,363,"8266","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8267",7,"Se secó la rosa,\nse secó el botón;\ndenme mi aguinaldo,\nmanque sea un tostón.",136,2,4,151,"Naranjas y limas’T festividades",0,4,"o",31,0,-1,0,363,363,"8267","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8268",7,"Demen mi aguinaldo,\nsi me lo han de dar,\npara el alumbrado\nRodríguez Beltrán.",136,2,4,151,"Naranjas y limas",0,4,"a",-1,0,-1,0,364,364,"8268","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8269",7,"Denme el aguinaldo\npoquito a poquito,\nabran la botella\ny den un poquito.",136,2,4,151,"Naranjas y limas",0,4,"io",-1,0,-1,0,364,364,"8269","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8270",7,"Yo no quiero quinto,\ntampoco de a veinte:\nquiero una botella\nllena de aguardiente.",136,2,4,151,"Naranjas y limas",0,4,"ee",-1,0,-1,0,364,364,"8270","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8271",7,"Cogollo de lima,\nramo de laurel,\nqueremos buñuelo\ncon bastante miel.",136,2,4,151,"Naranjas y limas",0,4,"e",32,0,-1,0,364,364,"8271","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8272",7,"Naranjas y limas,\nlimas y limones,\npa los muchachos\nque son bien tragones.",147,2,11,151,"Estrofa suelta",6,4,"oe",34,0,-1,0,364,364,"8272","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8273",7,"Demen los tamales,\ny aunque sean de masa;\nsi no me los dan,\nles quemo la casa.",136,2,4,151,"Naranjas y limas",0,4,"aa",123,0,-1,0,364,364,"8273","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8274",7,"Yo quiero buñuelos,\ntambién quiero amoles,\ny si no me los dan,\nles aviento la Rama.",136,2,4,151,"Naranjas y limas",5,4,"aa",-1,0,-1,0,364,364,"8274","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8275",7,"¡Ay, Jesús, Jesús,\nqué puerta tan dura!\n¿Dónde está la llave\nde la cerradura?",136,2,4,151,"Naranjas y limas; La tuza",0,4,"ua",17,0,-1,0,364,364,"8275","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8276",7,"Yo ya me despido\ny al pie de la Cruz,\nhasta el año entrante,\nsi Dios da salud.",136,2,4,151,"Naranjas y limas",0,4,"u",-1,0,-1,0,364,364,"8276","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8277",7,"Si Dios da salud,\nvolveré a cantar,\npero mi aguinaldo\nme tienen que dar.",136,2,4,151,"Naranjas y limas",0,4,"a",21,0,-1,0,364,364,"8277","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8278",7,"Y alabando a Dios,\nporque ya nos vamos,\nyo y mis compañeros\nlas gracias les damos.",136,2,4,151,"Naranjas y limas; Estrofa suelta",0,4,"ao",116,0,-1,0,365,365,"8278","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8279",7,"Pedimos al cielo\nque esta caridad\nos premie colmándoos\nde felicidad.",136,2,4,151,"Canto de Posadas",0,4,"a",16,0,-1,0,365,365,"8279","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8280",7,"Y a la banda de oro,\ncon ella nos vamos;\nfeliz compañeros,\nlas gracias les damos,\nporque ya nos vamos.",136,2,4,151,"Naranjas y limas",7,5,"ao",116,0,-1,0,365,365,"8280","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8281",7,"Ya con ésta, adiós,\nporque ya nos fuimos;\nyo y toda mi gente\nlas gracias les dimos.",142,2,8,151,"Naranjas y limas",0,4,"io",329,0,-1,0,365,365,"8281","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8282",7,"Ya se va la Rama\nmuy agradecida,\nporque en esta casa\nfue bien recibida.",142,2,8,151,"Naranjas y limas; Estrofa suelta",0,4,"ia",37,0,-1,0,365,365,"8282","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8283",7,"Ya se va la Rama\nmuy desconsolada,\nporque en esta casa\nno le dieron nada.",136,2,4,151,"Naranjas y limas; Estrofa suelta",0,4,"aa",-1,0,-1,0,365,365,"8283","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8284",7,"Ya se va la Rama\ncon todo y panderos,\nporque en esta casa\nson muy cicateros.",136,2,4,151,"Naranjas y limas",0,4,"eo",22,0,-1,0,365,365,"8284","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8285",7,"Ya se va la Rama\ncon punta de alambre,\nporque en esta casa\nestán muertos de hambre.",136,2,4,151,"Naranjas y limas; Estrofa suelta",0,4,"ae",288,0,-1,0,365,365,"8285","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8286",7,"Piña madura,\ncastaña asada;\n¡que viva, que viva\nel de la posada!",147,2,11,151,"Canto de Posadas",6,4,"aa",49,0,-1,0,366,366,"8286","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8289",7,"Con ojitos vendados\ny mano en el bastón,\npara darle a la piñata,\nsin tenerle compasión.",135,2,-1,151,"Canto de Posadas",0,4,"o",31,0,-1,0,366,366,"8289","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8290",7,"Castaña verde,\npiña madura,\ndale de palos\na la olla dura.",138,2,6,151,"Canto de Posadas",6,4,"ua",17,0,-1,0,366,366,"8290","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8291",7,"Bajen la piñata,\nbájenla un poquito,\nque le den de palos\npoquito a poquito.",147,2,11,151,"Estrofa suelta",0,4,"io",-1,0,-1,0,366,366,"8291","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8292",7,"Dale, dale, dale,\nno pierdas el tino,\nmira la piñata\nque hay en el camino.",147,2,11,151,"Canto de Posadas",0,4,"io",199,0,-1,0,366,366,"8292","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8293a",7,"Dale, dale, dale,\nno pierdas el tino,\nmide la distancia\nque hay en el camino.",147,2,11,151,"Canto de Posadas",0,4,"io",199,0,-1,0,366,366,"8293a","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8293c",7,"Dale, dale, dale,\nno pierdas el tino,\nmide la distancia\nque hay en el camino,\ny si no le das,\nde un palo te empino.",147,2,11,151,"Estrofa suelta",9,6,"io",199,0,-1,0,367,367,"8293c","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8294",7,"Dale, dale, dale,\nno pierdas el tino,\nporque si lo pierdes,\npierdes el camino.",135,2,-1,151,"Canto de Nochebuena; Estrofa",0,4,"io",199,0,-1,0,367,367,"8294","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8295",7,"Si le pego yo,\nrecio o quedito,\nse mueve y se escapa\ny me hace guajito.",135,2,-1,151,"Canto de Posadas",6,4,"io",119,0,-1,0,367,367,"8295","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8296",7,"No quiero oro,\nni quiero plata:\nyo lo que quiero\nes quebrar la piñata.",147,2,11,151,"Canto de Posadas, Naranjas y lii ¡",3,4,"aa",74,0,-1,0,367,367,"8296","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8297",7,"No quiero bolillo,\nni quiero pambazo:\nyo lo que quiero\nes romper el payaso.",147,2,11,151,"Estrofa suelta",3,4,"ao",145,0,-1,0,367,367,"8297","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8298",7,"Esta piñata\nes de muchas mañas:\nsólo contiene\nnaranjas y cañas.",147,2,11,151,"Estrofa suelta",6,4,"aa",42,0,-1,0,367,367,"8298","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8301",7,"De los cerritos\ny los cerrotes\nsaltan y brincan\nlos tejocotes.",147,2,11,151,"Canto de Posadas",6,4,"oe",565,0,-1,0,367,367,"8301","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8302",7,"Esta noche de posadas\nque a Lupita le tocó,\ntrajo muchas canastitas\ny todas las repartió.",135,2,-1,151,"Estrofa suelta",0,4,"o",2,0,-1,0,368,368,"8302","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8303",7,"A todos los muchachos\nnos toca la colación;\nrezamos y cantamos\ncon mucha devoción.",135,2,-1,151,"Canto de Posadas",0,4,"o",31,0,-1,0,368,368,"8303","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8304",7,"Castaña asada,\npiña cubierta,\nechen regalos\na los de la puerta.",135,2,-1,151,"Canto de Posadas",6,4,"ea",267,0,-1,0,368,368,"8304","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8305",7,"Echen confites\ny canelones,\npa los muchachos,\nque son muy tragones.",147,2,11,151,"Canto de Posadas",6,4,"oe",34,0,-1,0,368,368,"8305","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8306",7,"Echen confites,\ngordas calientes,\npa las viejitas\nque no tienen dientes.",135,2,-1,151,"Canto de Posadas",6,4,"ee",252,0,-1,0,368,368,"8306","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8307",7,"Tengo una canasta\nllena de alberjones,\npara mis muchachos,\nque son muy tragones.",147,2,11,151,"Estrofa suelta",0,4,"oe",34,0,-1,0,368,368,"8307","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8308",7,"A los de adentro\nles están dando,\ny los de afuera\nse están saboreando.",147,2,11,151,"Estrofa suelta",3,4,"ao",33,0,-1,0,368,368,"8308","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8309",7,"Ándale, Rosa,\nno te alborotes\ncon la canasta\nde los tejocotes.",147,2,11,151,"Estrofa suelta",6,4,"oe",565,0,-1,0,368,368,"8309","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8310",7,"Ándale, Lucha,\nsal de puntitas,\ncon la canasta\nde las palomitas.",147,2,11,151,"Estrofa suelta",6,4,"ia",258,0,-1,0,368,368,"8310","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8311",7,"Ándale, Juana,\nno te hagas menos\ncon la canasta\nde los caramelos.",147,2,11,151,"Estrofa suelta",6,4,"eo",-1,0,-1,0,368,368,"8311","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8312",7,"Ándale, Juana,\nno te dilates\ncon la canasta\nde los cacahuates.",135,2,-1,151,"Canto de Posadas",6,4,"ae",283,0,-1,0,369,369,"8312","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8313",7,"Ándale, Chole,\nno te arrincones\ncon la canasta\nde las colaciones.",147,2,11,151,"Estrofa suelta",6,4,"oe",34,0,-1,0,369,369,"8313","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8314",7,"Ándale, Jorge,\nsal del rincón,\ncon la canasta\nde la colación.",147,2,11,151,"Canto de Posadas",6,4,"o",31,0,-1,0,369,369,"8314","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8315",7,"Ándale pronto,\nno te dilates,\ncon el montón\nde la colación.",147,2,11,151,"Estrofa suelta",6,4,"o",31,0,-1,0,369,369,"8315","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8316",7,"Anda, Juanito,\ncabeza de araña,\nanda y reparte\npedazos de caña.",135,2,-1,151,"Canto de Posadas",6,4,"aa",213,0,-1,0,369,369,"8316","",0,"frenk_t4","","",3,0,0,[],"",""],["frenk_t3-n8318",7,"Ándale, chato,\nsal de la hornilla,\ncon la botella\nde la manzanilla.",147,2,11,151,"Estrofa suelta",6,4,"ia",162,0,-1,0,369,369,"8318","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8319",7,"Ándale, niño,\nsal otra vez,\ncon la botella\ndel vino jerez.",147,2,11,151,"Estrofa suelta",6,4,"e",150,0,-1,0,369,369,"8319","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8320",7,"Ándale, Susi,\ncabeza de paja,\ndame siquiera\nun pedazo de naranja.",147,2,11,151,"Estrofa suelta",3,4,"aa",-1,0,-1,0,370,370,"8320","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8321",7,"Juanito, Juanito,\nno te hagas payaso,\ny de ese ponche\nlléname mi vaso.",147,2,11,151,"Estrofa suelta",6,4,"ao",145,0,-1,0,370,370,"8321","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8322",7,"No quiero limas,\nni limones;\nyo lo que quiero\nes comer colaciones.",147,2,11,151,"Estrofa suelta",3,4,"oe",34,0,-1,0,370,370,"8322","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8323",7,"No quiero luna,\nni quiero sol;\nyo lo que quiero\nes comer colación.",147,2,11,151,"Estrofa suelta",3,4,"o",-1,0,-1,0,370,370,"8323","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8324",7,"Hay serpentinas\ny hay confites,\ny lo que quiero\nes que no me los quites.",147,2,11,151,"Estrofa suelta",3,4,"ie",235,0,-1,0,370,370,"8324","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8325",7,"¡Cómo está alegre\nesta posada!,\npero en mi copa\nno has servido nada.",147,2,11,151,"Estrofa suelta",6,4,"aa",49,0,-1,0,370,370,"8325","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8326",7,"En esta posada\nnos hemos chasqueado,\nporque de cubitas\nnada nos han dado.",147,2,11,151,"Estrofa suelta",0,4,"ao",14,0,-1,0,370,370,"8326","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8327",7,"Ahora sí ya se acabó,\nahora sí vayan saliendo;\nno más no vayan diciendo:\n“A mí nada me tocó”.",147,2,11,151,"Estrofa suelta",11,4,"o",2,0,-1,0,370,370,"8327","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8329",7,"Éste es el Judas traidor,\nque vendió a Nuestro Señor;\ntiene alas de infierno\ny huele a purito cuerno.",135,2,-1,151,"El judero",5,4,"eo",225,0,-1,0,370,370,"8329","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8330",7,"Es este Judas traidor,\nfigura mal parecida,\ncon cara muy colorada\ny conciencia pervertida.",135,2,-1,151,"El judero",0,4,"ia",37,0,-1,0,371,371,"8330","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8332",7,"Inocente palomita,\nque te has dejado engañar,\nsabiendo que en este día\nnada se debe prestar.",135,2,-1,151,"Estrofa suelta",0,4,"a",21,0,-1,0,371,371,"8332","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8333",7,"nerodes, cruel e inclemente,\nnos dice desde su fosa\nque considera inocente\nal que presta alguna cosa.",135,2,-1,151,"Estrofa suelta",1,4,"oa",63,0,-1,0,371,371,"8333","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8334",7,"Hoy vinimos en reunión\na felicitar tu día,\na comerte lo que tienes,\ny a fregarte todo el día.",145,2,17,152,"Las mañanitas",0,4,"ia",-1,0,-1,0,374,374,"8334","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8335",7,"No traigo corona de oro,\nni tampoco de cristal:\nsólo traigo a mis amigos,\nque se tomen el mezcal.",135,2,-1,152,"Las mañanitas",0,4,"a",1,0,-1,0,374,374,"8335","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8336",7,"No traigo arco de carrizo,\nni tampoco de sotole;\nsólo traigo a mis amigos,\nque se coman el pozole.",135,2,-1,152,"‘‘Las mañanitas",0,4,"oe",619,0,-1,0,374,374,"8336","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8337",7,"Por darte los buenos días,\nte doy yo las madrugadas;\nlevántate, amigo mío,\npara que hagas enchiladas.",145,2,17,152,"Las mañanitas",0,4,"aa",282,0,-1,0,374,374,"8337","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8338",7,"Ya no duermas tanto, tanto,\nni te acuestes noche, noche,\nmejor levántate pronto,\npara que te hagas un ponche.",145,2,17,152,"Las mañanitas",0,4,"oe",-1,0,-1,0,374,374,"8338","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8339",7,"Si no nos abres la puerta,\nnos vamos sólo por eso,\na la tarde volveremos\na los tamales de queso.",135,2,-1,152,"Las mañanitas",0,4,"eo",-1,0,-1,0,374,374,"8339","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8340",7,"Adiós, Mariquita mía,\naquí me siento a cantar\ndebajo de esa enramada;\nparece que canto, canto,\ny no canto nada.",142,2,8,152,"María, María",7,5,"aa",49,0,-1,0,374,374,"8340","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8341",7,"Asómate a la vergüenza,\ncara de poca ventana,\ny dame un beso de sed,\nque me estoy muriendo de agua.",135,2,-1,152,"El tapatío; Coahuayana’T",0,4,"aa",-1,0,-1,0,374,374,"8341","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8342",7,"Con permiso, valedores,\nque va a cantar un chambón;\nno digan que soy grosero,\nni tampoco un metelón:\nlicencia pido primero\npara cantar este son.",136,2,4,152,"La morena",9,6,"o",31,0,-1,0,375,375,"8342","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8343",7,"Cantando con gusto “El gusto”,\ngustosamente les canto;\nla vacuna contra el susto\nme he aprendido, y por lo tanto\ncon gusto les canto “El gusto”,\npues curado estoy de espanto.",147,2,11,152,"El gusto",9,6,"ao",30,0,-1,0,375,375,"8343","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8344",7,"Esta canción es bonita,\nno se le puede negar,\npero más bonita fuera\nsi la supiera cantar.",161,2,15,152,"Cuatro esquinas tiene un catre",0,4,"a",21,0,-1,0,375,375,"8344","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8345",7,"Voy a cantar un corrido,\ncorrido de vacilada,\nde esos que lo dicen todo,\npero que no dicen nada;\ny no te aflijas, chinita,\nque vuelvo a la madrugada.",135,2,-1,152,"La voltereta",9,6,"aa",49,0,-1,0,375,375,"8345","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8346",7,"Ya nosotros ya nos vamos\npor el mismo caminito,\ny los de adentro dirán:\n“Váyase, me importa un pito”.",146,2,7,152,"Ya nosotros ya nos vamos",0,4,"io",119,0,-1,0,375,375,"8346","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8348",7,"Un amigo de mi infancia,\nque se llama José Cruz,\na pesar de su ignorancia\nhoy radica en Veracruz.",152,2,13,152,"Estrofa suelta",1,4,"u",109,0,-1,0,375,375,"8348","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8349",7,"Ariles, que así contaba\nla difunta Liberata,\ny si no se hubiese muerto,\ncantara y fuera mi chata.",136,2,4,152,"La morena",0,4,"aa",74,0,-1,0,375,375,"8349","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8350",7,"Así se llamaba una:\nRosa, Jazmín y Violeta,\ny si no me hubiera muerto\n—corre linda, ya me ves,\noye bien lo que te digo—,\ncantara y fuera mi chata",142,2,8,152,"El cascabel’",9,6,"aa",-1,0,-1,0,375,375,"8350","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8351",7,"Despedida no les echo,\nporque no las uso yo;\n¿qué más despedida quieren?,\nla canción ya se acabó.",138,2,6,152,"La muía de siete cuartas; Estrofa suelta",0,4,"o",2,0,-1,0,376,376,"8351","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8352",7,"Voy a echar la despedida,\ncomo la que echó el arriero:\ncon la tortilla en la mano (morena)\ny la carne en el sombrero.",142,2,8,152,"La morena",3,4,"eo",38,0,-1,0,376,376,"8352","",0,"","","",8,0,0,[],"",""],["frenk_t3-n8353",7,"Y con ésta me despido,\nporque me voy a dormir;\nmi petate tiene pulgas,\ny lo voy a sacudir.",142,2,8,152,"Estrofa suelta",0,4,"i",157,0,-1,0,376,376,"8353","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8354",7,"Colás, Colás,\nColás y Nicolás,\nsi tienes un hermano,\nmételo a matacuás.",147,2,11,152,"El Colás",3,4,"a",51,0,-1,0,376,376,"8354","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8355",7,"En la punta de aquel cerro\nmaté una paloma mora;\nde las tripas le saqué\na Martín y la Nabora.",140,2,12,152,"Estrofa suelta",0,4,"oa",107,0,-1,0,376,376,"8355","",0,"","","",21,0,0,[],"",""],["frenk_t3-n8356",7,"En la puerta de este circo\nmaté un Lucifer;\nen las tripas le saqué\na Lupe Alonso y su mujer.",140,2,12,152,"Estrofa suelta",3,4,"e",-1,0,-1,0,376,376,"8356","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8357",7,"En el puerto de Acapulco\nmataron un tiburón,\ny de la panza le sacaron\na [Fulana] en camisón.",163,2,21,152,"Estrofa suelta",0,4,"o",31,0,-1,0,376,376,"8357","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8358",7,"En el portal de mi casa\nhay un nido de ratones,\ny a la pobre de [Fulana]\nle comieron los chones.",163,2,21,152,"Estrofa suelta",0,4,"oe",34,0,-1,0,376,376,"8358","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8360",7,"Mi comadre está bailando:\n¡qué bonito las dispara!\nSi no fuera mi comadre,\notro gallo nos cantara.",137,2,3,152,"Mi comadre’’",0,4,"aa",57,0,-1,0,377,377,"8360","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8361",7,"¡Qué bonita palomita!,\nlástima que esté gordita;\nsi estuviera más flaquita,\nyo la enseñaría a bailar.",135,2,-1,152,"La palomita",5,4,"a",-1,0,-1,0,377,377,"8361","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8366",7,"Cuando vayas a la estación\ny veas un velizón,\nacuérdate del pachangón\nque echamos en el salón.",147,2,11,152,"Estrofa suelta",0,4,"o",31,0,-1,0,377,377,"8366","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8367",7,"Cuando bailes cha cha chá,\ncuando bailes rock and roll,\nacuérdate de la pachanga\nque echábamos en el salón.",147,2,11,152,"Estrofa suelta",0,4,"o",-1,0,-1,0,377,377,"8367","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8368",7,"¿Te acuerdas, linda Teté,\nque en el baile de kuiché\nbailaste con Lol Chalé\nel son “Siribincunté”?",152,2,13,152,"Estrofa suelta",0,4,"e",77,0,-1,0,377,377,"8368","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8369",7,"Hazte chiquito,\nhazte grandote,\nya te pareces\nal guajolote.",145,2,17,152,"El jarabe; Los enanos",6,4,"oe",292,0,-1,0,377,377,"8369","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8370",7,"-Madre, tengo hambre:\ntlaco pa pan.\n—Hija, no tengo:\nbaile el can-can.",135,2,-1,152,"E1 can-can",6,4,"a",147,0,-1,0,377,377,"8370","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8371",7,"Una ñifla en un baile\nrompió un vapor,\nuna tinaja de agua\ny un comedor.",142,2,8,152,"La bamba",6,4,"o",72,0,-1,0,378,378,"8371","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8372",7,"Una niña en un baile\nrompió un chical,\nuna tinaja de agua\ny un tihuapal.",142,2,8,152,"La bamba",6,4,"a",1,0,-1,0,378,378,"8372","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8373",7,"Al pasar por un panteón\nme encontré una calavera;\ncomo soy muy abusado,\ndije: “Ja, es de muerto”.",152,2,13,152,"Estrofa suelta",5,4,"eo",-1,0,-1,0,378,378,"8373","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8374",7,"Al pasar por el panteón\nme salió una calavera\ny me dijo: “Tú tocas el tambor,\ny yo muevo la cadera”.",147,2,11,152,"Estrofa suelta",3,4,"ea",44,0,-1,0,378,378,"8374","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8375",7,"Ya te vide, calavera,\ncon un diente y una muela,\nsaltando como una pulga\nque tiene barriga llena.",145,2,17,152,"El jarabe; Estrofa suelta",0,4,"ea",-1,0,-1,0,378,378,"8375","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8376",7,"Estaba la Media Muerte\nsentada en su taburete;\nlos muchachos, de traviesos,\nle picaron el rodete.",145,2,17,152,"El jarabe; Estrofa suelta",0,4,"ee",285,0,-1,0,378,378,"8376","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8377",7,"Estaba la Media Muerte\nsentada en un tecomate,\ndiciéndole a los muchachos:\n“Vengan, beban chocolate”.",145,2,17,152,"Estaba la muerte",0,4,"ae",384,0,-1,0,378,378,"8377","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8378",7,"Al pasar por un panteón\nme dijo una calavera:\n“No vengas a hacer tu cochinada,\nporque me enseñas la mollera”.",147,2,11,152,"Estrofa suelta",3,4,"ea",44,0,-1,0,378,378,"8378","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8379",7,"Estaba la Muerte un día\nsentada en un arenal,\ncomiendo tortilla fría,\npa ver si podía engordar.",144,2,10,152,"Estaba la muerte",0,4,"a",-1,0,-1,0,378,378,"8379","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8384",7,"Dale, dale, dale,\nno pierdas el tino,\nporque si lo pierdes,\npierdes a tu tío.",147,2,11,152,"Estrofa suelta",0,4,"io",-1,0,-1,0,379,379,"8384","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8385",7,"No quiero cinco,\nni quiero centavo,\nquiero la pistola\nde Juan Charrasqueado.",136,2,4,152,"Naranjas y limas",3,4,"ao",-1,0,-1,0,379,379,"8385","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8386",7,"En esta posada\nnos dieron semillas,\nporque la madrina\nempeñó las faldillas.",147,2,11,152,"Estrofa suelta",0,4,"ia",-1,0,-1,0,379,379,"8386","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8387",7,"En esta posada\nnos dieron piñones,\nporque el padrino\nempeñó los calzones.",147,2,11,152,"Estrofa suelta",3,4,"oe",34,0,-1,0,379,379,"8387","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8388",7,"Diga si nos ha de abrir,\npa no estarnos esperando:\nno somos tinajas de agua\npara estarnos serenando.",135,2,-1,152,"Las mañanitas",0,4,"ao",33,0,-1,0,380,380,"8388","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8389",7,"Yo quisiera del gallo el canto\ny del músico los dedos,\ny en este día de tu santo\nsacarte todos los pedos..",142,2,8,152,"Estrofa suelta",3,4,"eo",620,0,-1,0,380,380,"8389","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8390",7,"Si el matrimonio quebranta,\na mi Dios le envío la queja;\nsiendo tu alegría tanta,\nde la música te alejas:\ncompadre, ¿por qué no cantas?,\n¿o tu vieja no te deja?",135,2,-1,152,"El siquisirí",9,6,"ea",-1,0,-1,0,380,380,"8390","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8391",7,"Ya comienza la función,\npongan atención toditos,\nabran ojos y orejitas;\nya vienen las pantorrillas;\nyo diré una que otra leva,\npara divertir a ustedes,\npero no tengo de poeta\nni aquellos cabellos largos:\nsólo tengo aquí una horqueta\npara la que no le cuadre.",143,2,18,152,"Estrofa suelta",18,10,"ae",-1,0,-1,0,380,380,"8391","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8392",7,"Hoy que vengo por acá,\nque aquí en mi pecho no cabe,\n-siempre he llevado un compás,\nmi mente siempre lo sabe;\nBeño, su amigo de Jas,\nque vaya y chingue a su madre.",136,2,4,152,"El siquisirí",9,6,"ae",-1,0,-1,0,380,380,"8392","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8393",7,"Recuerda lo que dijiste;\nya Isidoro lo sabe;\nsólo me lo prometiste,\ny aquí en mi pecho no cabe;\nBeño, como no veniste,\nvas a chingar a tu madre.",136,2,4,152,"El siquisirí",9,6,"ae",-1,0,-1,0,380,380,"8393","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8394",7,"Recuerda lo que dijiste,\nen mis versos lo diré:\na Isidoro prometiste,\nlo digo y no sé por qué,\npero como no viniste\nla vas a chingar otra vez.",136,2,4,152,"El siquisirí",9,6,"e",-1,0,-1,0,381,381,"8394","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8395",7,"Yo me salí de recreo,\ntocándote mi jarana;\nhoy que estoy en mi apogeo,\nde cantar me dieron ganas;\ny, Beño, tú no eres feo:\nasí han de ser tus hermanas.",136,2,4,152,"El pájaro carpintero; María Chuchena; El pájaro cú; El siquisirí",9,6,"aa",263,0,-1,0,381,381,"8395","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8396",7,"Me dicen que usted\nes muy buen poeta,\naún sin tener estudios;\nahora quiero que me diga\ncuántos pliegues tiene el culo.",142,2,8,152,"Estrofa suelta",7,5,"uo",-1,0,-1,0,381,381,"8396","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8397",7,"Estaba el [Pedro] sentado,\nsentado en un taburete;\nel [Pedro] que se descuida,\ny el [Carlos] que se la mete.",148,2,9,152,"Estrofa suelta",0,4,"ee",285,0,-1,0,381,381,"8397","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8398",7,"Por esta calle derecha\niba un caballo tordillo,\ny el [Fulano] lo lazó\ncon los pelos del fundillo.",148,2,9,152,"Estrofa suelta",0,4,"io",228,0,-1,0,381,381,"8398","",0,"","","",8,0,0,[],"",""],["frenk_t3-n8399",7,"El señor que está allí\nme presume de anteojos:\nse le miran los calzones,\n¡cómo los tiene de piojos!",147,2,11,152,"Estrofa suelta",0,4,"oo",99,0,-1,0,381,381,"8399","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8400",7,"Todos los que están enfrente,\ntodos están muy felices,\npero mírenles la panza,\ny están llenos de lombrices.",137,2,3,152,"La Sanmarqueña; Estrofa suelta",0,4,"ie",113,0,-1,0,381,381,"8400","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8401",7,"Ya se va, ya se despide,\nya se va el capulinero;\npor eso cantando digo:\n“Eres puro cilindrero”.",145,2,17,152,"El capulinero",0,4,"eo",38,0,-1,0,381,381,"8401","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8402",7,"Ya les doy la despedida,\nya me voy para Los Reyes;\nno más esperen tantito\nque se vayan estos virreyes.",147,2,11,152,"La Sanmarqueña",0,4,"ee",600,0,-1,0,382,382,"8402","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8403",7,"Ya nosotros ya nos vamos,\ny a usted le importará un cuerno,\npero nos hemos de ver\nen las puertas del infierno.",135,2,-1,152,"Ya nosotros ya nos vamos",0,4,"eo",225,0,-1,0,382,382,"8403","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8404",7,"Ya con ésta me despido,\ncon ésta les hago ver\nque no traen ni calcetines\ny quieren traer mujer.",135,2,-1,152,"Estrofa suelta",0,4,"e",20,0,-1,0,382,382,"8404","",0,"","","",72,0,0,[],"",""],["frenk_t3-n8405",7,"Ya me voy a despedir,\ncomo dijo la cotona:\n“Unos pagan sus canciones,\ny otros oyendo de gorra”.",162,2,27,152,"La Sanmarqueña",0,4,"oa",-1,0,-1,0,382,382,"8405","",0,"","","",13,0,0,[],"",""],["frenk_t3-n8406",7,"Si fueras a Yucatán,\nbailarás una jarana,\npero ten mucho cuidado:\nno te zurren la badana.",152,2,13,152,"Estrofa suelta",0,4,"aa",4,0,-1,0,382,382,"8406","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8407",7,"De Yucatán he venido\narrastrando mi capote,\nsólo por verte bañar,\ncarilla de zopilote.",140,2,12,152,"La Zandunga; Estrofa suelta",0,4,"oe",292,0,-1,0,382,382,"8407","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8408",7,"Bomba arriba,\nbomba abajo,\nmi pareja\nhuele a tasajo.",152,2,13,152,"Estrofa suelta",3,4,"ao",168,0,-1,0,382,382,"8408","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8409",7,"Zancas de hilillo,\npies de popote,\nbáilele, báilele\nal chichicuilote.",147,2,11,152,"Estrofa suelta",6,4,"oe",292,0,-1,0,382,382,"8409","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8410",7,"¡Y baila morenal,\n¡baila requetebién!\nY mira, si no bailas,\nte damos un puntapié.",148,2,9,152,"El merecumbé",0,4,"e",-1,0,-1,0,382,382,"8410","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8411",7,"Soledad le da y le da,\nle da gusto a la cadera;\ntodo se le va en bailar,\ny lo hace como cualquiera.",135,2,-1,152,"Mariquita quita, quita",0,4,"ea",44,0,-1,0,382,382,"8411","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8412",7,"¡Ay, qué Severiana,\ntan buena pa nada!,\nque la saqué a bailar,\ny ni se meneaba.",135,2,-1,152,"Yo no sé qué tiene Pancha",0,4,"aa",-1,0,-1,0,383,383,"8412","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8413",7,"De esos dos que andan bailando\na ninguno desagero:\nuno parece de hilacha,\ny otro parece de cuero.",135,2,-1,152,"Estrofa suelta",0,4,"eo",38,0,-1,0,383,383,"8413","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8414",7,"De los dos que andan bailando\nDios bendiga su hermosura;\nuno parece chorizo,\ny otro parece asadura.",137,2,3,152,"La Sanmarqueña; De las tres que vienen áhi",0,4,"ua",17,0,-1,0,383,383,"8414","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8415",7,"De las dos que andan bailando\nlas dos me parecen bien:\nuna parece un zancudo,\ny la otra un jején.",142,2,8,152,"Estrofa suelta",0,4,"e",242,0,-1,0,383,383,"8415","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8416",7,"Sal a bailar con ése:\nte lo permito,\ny si te mira mucho —dile que se ande\ncon cuidadito,\nporque yo creo\nque, siendo tan aguado —no sirve el niño\nni pa el recreo.",135,2,-1,152,"Cuidadito",4,7,"eo",66,0,-1,0,383,383,"8416","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8417",7,"Esta posada\nle toca a Carmela;\nsi no da nada,\nle saco una muela.",147,2,11,152,"Estrofa suelta",6,4,"ea",167,0,-1,0,383,383,"8417","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8418",7,"Esta posada\nle toca a Mengana;\nsi no da nada,\nle doy una nalgada.",147,2,11,152,"Estrofa suelta",3,4,"aa",49,0,-1,0,383,383,"8418","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8419",7,"Esta piñata\nestá muy compuesta;\néchenle palos\na los de la puerta.",144,2,10,152,"Estrofa suelta",6,4,"ea",-1,0,-1,0,383,383,"8419","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8420",7,"[Piña madura,]\ncastaña asada,\ndenle de palos\na los de la entrada.",147,2,11,152,"Canto de Posadas",6,4,"aa",49,0,-1,0,383,383,"8420","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8421",7,"Castaña asada,\npiña cubierta,\nechen a palos\na los de la puerta.",147,2,11,152,"Canto de Posadas",6,4,"ea",267,0,-1,0,384,384,"8421","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8422",7,"Té de canela,\nté de limón,\nechen de palos\na los del colchón.",147,2,11,152,"Estrofa suelta",6,4,"o",31,0,-1,0,384,384,"8422","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8423",7,"Chile pasilla,\nchile mulato,\ndenle de palos\na los del banco.",147,2,11,152,"Estrofa suelta",6,4,"ao",-1,0,-1,0,384,384,"8423","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8424",7,"Chile poblano,\nchile pasilla,\nechen a palos\na los de la silla.",147,2,11,152,"Estrofa suelta",6,4,"ia",162,0,-1,0,384,384,"8424","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8425",7,"Echen confites\ny tortillas duras,\npara las muchachas\nque vienen mechudas.",147,2,11,152,"Estrofa suelta",6,4,"ua",-1,0,-1,0,384,384,"8425","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8426",7,"Ándale, niña,\nsal del rincón,\nechando brincos\ncomo ratón.",147,2,11,152,"Estrofa suelta",6,4,"o",31,0,-1,0,384,384,"8426","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8427",7,"Y no te escondas\nen la cocina,\no ya verás\ncon mi tia Catalina.",147,2,11,152,"Canto de Posadas",3,4,"ia",11,0,-1,0,384,384,"8427","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8428",7,"No sea malo, caballero,\nno le pegue a su mujer:\n¿qué no ve que es la piñata,\ny no se sabe defender?",147,2,11,152,"Estrofa suelta",0,4,"e",20,0,-1,0,384,384,"8428","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8429",7,"No quiero plata,\nni quiero oro:\nsólo lo que quiero\nes darle en el coco.",147,2,11,152,"Canto de Posadas",6,4,"oo",-1,0,-1,0,384,384,"8429","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8430",7,"Levántate, amigo,\ny enciende el cerillo;\nmira lo que te anda\npor los calzoncillos.",136,2,4,152,"Naranjas y limas",0,4,"io",-1,0,-1,0,385,385,"8430","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8431",7,"La madrina es una rosa,\nel padrino es un clavel,\nla novia es una mocosa,\nel novio por cierto es.",135,2,-1,152,"El jarabe",0,4,"e",-1,0,-1,0,385,385,"8431","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8432",7,"No hay cielo como mi cielo,\nni tierra como la mía,\nni amor como amor de madre,\nni luz cual la luz del día.",135,2,-1,153,"Estrofa suelta",0,4,"ia",0,0,-1,0,388,388,"8432","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8433",7,"Adán habló en francés,\nEva en italiano,\nel diablo en inglés,\ny Dios en castellano..",163,2,21,153,"Estrofa suelta",1,4,"ao",81,0,-1,0,388,388,"8433","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8434",7,"En el nombre sea de Dios\ny de la Virgen María,\nque penas no puede dar\nel que con leche se cría.",135,2,-1,153,"Estrofa suelta",0,4,"ia",0,0,-1,0,388,388,"8434","",0,"","","",7,0,0,[],"",""],["frenk_t3-n8435",7,"Hay muchos refranes,\nsentencias, si quieren:\naquel que es perico\ndonde quiera es verde.",135,2,-1,153,"Los celotes",0,4,"ee",-1,0,-1,0,388,388,"8435","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8436",7,"No sé si será verdad\nlo que todo mundo dice;\nyo creo que es realidad\nque sin mentira se dice:\nque aquel que Dios se la da\nsan Pedro se la bendice.",136,2,4,153,"El siquisirí",9,6,"ie",621,0,-1,0,388,388,"8436","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8437",7,"El hombre que es transitante\ngoza de mil alegrías,\nmayormente si es tunante,\ngozará mejores días:\nse va por delante.",136,2,4,153,"La huazanga",7,5,"ae",47,0,-1,0,388,388,"8437","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8438",7,"Todo el hombre que es de suerte\nrecorre varias guaridas,\ncanta, baila, se divierte,\ntiene novias y queridas;\ncuando le llegue la muerte\nya le dio gusto a la vida.",136,2,4,153,"El siquisirí",9,6,"ia",-1,0,-1,0,388,388,"8438","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8439",7,"¡Caramba, pero ay, caramba!,\n¡ay, qué caramba es la vida!\nNos juega como muñecos,\npero, ¡ay, qué padre es la vida!",135,2,-1,153,"ay, qué caramba es la vida! Nos juega como muñecos, pero, ¡ay, qué padre es la vida! [Qué padre es la vida",0,4,"ia",-1,0,-1,0,389,389,"8439","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8440",7,"Todo cabe en un jarrito,\nsabiéndolo acomodar;\nno más que sea grandecito,\nporque puede reventar.",140,2,12,153,"El gusto",1,4,"a",21,0,-1,0,389,389,"8440","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8441a",7,"¡Qué bonito es lo bonito!,\n¿y a quién no le ha de gustar?\nTodo cabe en un jarrito,\nsabiéndolo acomodar.",140,2,12,153,"El gusto",1,4,"a",21,0,-1,0,389,389,"8441a","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8441c",7,"Le pregunté a un muchachito\nsi era bueno para amar,\ny me dijo el angelito,\nque apenas me pudo hablar:\n“Todo cabe en un jarrito,\nsabiéndolo acomodar”.",146,2,7,153,"La curreña",9,6,"a",21,0,-1,0,389,389,"8441c","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8442",7,"Los caballos en pesebre\nnunca comen pasto vano;\nme admira que, siendo liebre,\nno sepas correr en llano;\nno hay canilla que se quiebre\napretándole la mano.",147,2,11,153,"El venadito",9,6,"ao",81,0,-1,0,389,389,"8442","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8443",7,"Estoy aserrando un palo\nen la sierra de Teneque;\nsólo aquel que no es cristiano\nno tiene su trespeleque,",135,2,-1,153,"El teneque",0,4,"ee",615,0,-1,0,389,389,"8443","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8444",7,"¡Ay de mí, Llorona!,\nLlorona del otro lado;\nel que por su gusto muere (Llorona),\naunque lo entierren parado.",142,2,8,153,"La Llorona",3,4,"ao",14,0,-1,0,389,389,"8444","",0,"","","",35,0,0,[],"",""],["frenk_t3-n8445",7,"El que la debe la paga:\nasí es la ley de la vida,\nque aunque sea tarde o temprano,\nDios tarda, pero no olvida.",150,2,24,153,"Estrofa suelta",0,4,"ia",37,0,-1,0,390,390,"8445","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8446",7,"Despedida no les doy,\nporque a mí no me conviene,\nque en esta vida y la otra\nlo que uno granjea, eso tiene.",137,2,3,153,"El dientito de cabada",0,4,"ee",70,0,-1,0,390,390,"8446","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8448",7,"El padre desobligado,\nque no cumple su deber,\néste se irá a padecer\nal infierno condenado.",135,2,-1,153,"Estrofa suelta",11,4,"ao",14,0,-1,0,390,390,"8448","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8449a",7,"Le dice un verde perico:\n“No carguen al forastero,\nque el día se ha de llegar\nque el burro mande al arriero”.",137,2,3,153,"El caballo prieto",0,4,"eo",38,0,-1,0,390,390,"8449a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8451a",7,"Para el toro, la garrocha,\npara el caballo, la espuela,\npara la mujer bonita,\nel zapato y la chinela.",136,2,4,154,"El toro",0,4,"ea",167,0,-1,0,391,391,"8451a","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8451b",7,"Para el toro, la garrocha,\npara el caballo, la espuela,\npara la mujer bonita,\nel cigarro y la candela,\ny para los fantasiosos,\nel espejo y la polvera.",136,2,4,154,"El torito",9,6,"ea",-1,0,-1,0,391,391,"8451b","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8452",7,"Para subir al cielo\nse necesita\nuna escalera grande\ny otra chiquita.",136,2,4,154,"La bamba; La zamba",6,4,"ia",50,0,-1,0,391,391,"8452","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8453",7,"El perfume que se estima\npoquito se ha de poner;\nel chile para que pique\nchiquitín tiene que ser.",135,2,-1,154,"Las chaparritas",0,4,"e",20,0,-1,0,391,391,"8453","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8454",7,"El hombre para ser hombre\ntres gustos debe tener:\ndebe beber aguardiente,\ndebe oler a tabaco\ny tener tufo de mujer.",142,2,8,154,"Estrofa suelta",7,5,"e",20,0,-1,0,391,391,"8454","",0,"","","",7,0,0,[],"",""],["frenk_t3-n8455a",7,"Yo no estoy civilizado,\npero trabajo de titulante;\noye bien lo que te digo,\npero puedo asegurarte:\nel hombre que está curado\nno sale a ninguna parte.",136,2,4,154,"La guacamaya",9,6,"ae",8,0,-1,0,392,392,"8455a","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8455b",7,"Hice un verso en el estado,\ny aunque yo no escudo el arte,\nyo no soy civilizado,\npero puedo asegurarte\nque el hombre que está curado\nno sale a ninguna parte.",136,2,4,154,"El siquisirí",9,6,"ae",8,0,-1,0,392,392,"8455b","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8456",7,"Así se la pone el guapo,\nde esta manera, indiscreto;\nasí son los zaramullos\ny los zaragates secos.",136,2,4,154,"El guapo",0,4,"eo",-1,0,-1,0,392,392,"8456","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8457",7,"Es verdad lo que usted dice,\ny en su verdad no hay engaño:\ndonde lloran está el muerto,\ny donde hay zopilotes hay daño.",142,2,8,154,"Estrofa suelta, Por lo alto doy cincuenta",3,4,"ao",40,0,-1,0,392,392,"8457","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8458",7,"Ariles y más ariles,\nariles del campo verde;\ncuando la perrita es brava\nhasta a los de casa muerde.",136,2,4,154,"El Balajú",0,4,"ee",154,0,-1,0,392,392,"8458","",0,"","","",24,0,0,[],"",""],["frenk_t3-n8460",7,"Secreto de dos\nsólo Dios;\nsecreto de tres\nsecreto no es.",159,2,26,154,"Estrofa suelta",6,4,"e",218,0,-1,0,392,392,"8460","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8461",7,"Hay un dicho que es muy cierto,\ny tal vez tú ya lo sabes:\n“No tiene la culpa el indio,\nsino el que lo hace compadre”.",135,2,-1,154,"No tiene la culpa el indio",0,4,"ae",-1,0,-1,0,392,392,"8461","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8462",7,"Preso me he llegado a ver,\nque en una cárcel de alambre;\ny me dice la mujer:\n“Regresa, que ya era grande:\nel que por su gusto es buey\nhasta la coyunda lame”.",136,2,4,154,"La guacamaya",9,6,"ae",-1,0,-1,0,392,392,"8462","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8463",7,"Cuando me volví tulís\nmi padre me lo evitó;\nuno sabe dónde nace,\npero dónde muere, no.",144,2,10,154,"Los tulises",0,4,"o",2,0,-1,0,392,392,"8463","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8464",7,"¡Ay de mí, Llorona!,\nLlorona del campo verde,\nel que derrotado sale (Llorona)\nhasta la cola se muerde.",142,2,8,154,"La Llorona’’",3,4,"ee",154,0,-1,0,393,393,"8464","",0,"","","",35,0,0,[],"",""],["frenk_t3-n8465",7,"¿Por qué te doblas, cuchillo,\nsiendo de tan fino acero?\nAsí se doblan los hombres\ncuando no tienen dinero.",148,2,9,154,"Estrofa suelta, Guadalajara en un llano; La Llorona; La Petenera",0,4,"eo",38,0,-1,0,393,393,"8465","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8466",7,"En las montañas más altas\nsilba el pájaro y gorjea;\nla liebre en el campo corre\ny el pez en el mar olea;\nel que está preso se amuela,\ny el que está libre pasea.",142,2,8,154,"Estrofa suelta",9,6,"ea",-1,0,-1,0,393,393,"8466","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8467",7,"Todos los días que amanece\nla perdiz anda cantando;\nel que la tiene la masca,\ny el que no, la anda buscando.",135,2,-1,154,"La perdiz",0,4,"ao",33,0,-1,0,393,393,"8467","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8468",7,"Voy a dar la despedida\nal pie de un chirimoyito;\ny el que tiene chichi mama,\ny el que no, se cría penchito.",142,2,8,154,"La garza; Ahora acabo de llegar",3,4,"io",119,0,-1,0,393,393,"8468","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8469",7,"Pa sacarle el agua al coco\nse le hace un agujerito;\ny el que tiene chiche mama,\ny el que no, se cría sanchito.",137,2,3,154,"El palmero",3,4,"io",119,0,-1,0,393,393,"8469","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8470",7,"Pa sacarle el agua al coco\nse le hace un agujerito;\nque el que tiene medio baila,\ny el que no, baila solito.",161,2,15,154,"El riqui-riqui",0,4,"io",119,0,-1,0,393,393,"8470","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8471",7,"Eso dicen los ancianos\nque han vivido más que yo:\nque las tunas se maduran,\npero los nopales, no.",135,2,-1,154,"El jarabe",0,4,"o",2,0,-1,0,393,393,"8471","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8472",7,"Eso mismo digo yo,\npero usted me la ganó:\n“El buey solito se lame,\npero amancomado, no”.",142,2,8,154,"Estrofa suelta",0,4,"o",2,0,-1,0,393,393,"8472","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8473",7,"De nada sirven riquezas\ncuando el hogar es infierno;\nse goza entre las pobrezas\ncuando se vive de acuerdo:\nno hay lugar a las tristezas.",138,2,6,154,"Estrofa suelta",7,5,"ea",528,0,-1,0,394,394,"8473","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8474",7,"Cuando el tecolote canta\nel indio muere:\nno será cierto,\npero sucede.",135,2,-1,154,"Estrofa suelta",6,4,"ee",-1,0,-1,0,394,394,"8474","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8475",7,"Pon muy atento el oído\ncuando rechine la puerta:\nhay muertos que no hacen ruido,\ny son muy gordas sus penas.",135,2,-1,154,"Allá en el Rancho Grande",0,4,"ea",-1,0,-1,0,394,394,"8475","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8476",7,"En el tribuna] divino\n¿quién ha de ser castigado?\n¿el padre consentidor\no el hijo mal educado?",136,2,4,154,"Estrofa suelta",0,4,"ao",14,0,-1,0,394,394,"8476","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8477",7,"En México está lloviendo,\nen Puebla, la nublazón;\nen un dedo está la nigua,\ny en otro la comezón.",138,2,6,154,"La Juanita",0,4,"o",31,0,-1,0,394,394,"8477","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8478",7,"Vergüenza es robar un briago\ny que ya no pueda andar;\npor eso yo no lo hago,\npues se te puede voltear.",138,2,6,154,"La huazanga",1,4,"a",21,0,-1,0,394,394,"8478","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8479",7,"Si un cigarro se te apaga,\nno lo vuelvas a encender;\nsi una amiga te desprecia,\nno la vuelvas a querer.",147,2,11,154,"Estrofa suelta, Ya no lloverá, pelonas",0,4,"e",20,0,-1,0,394,394,"8479","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8480",7,"El que no tenga dinero\ny tenga bien la chaveta,\nque se haga disimulado,\ny tomo a su garraleta.",145,2,17,154,"La coqueta",0,4,"ea",200,0,-1,0,394,394,"8480","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8482",7,"No hay que hablar de una mujer,\nporque una de ellas nos crió:\ndebemos de comprender\nlos trabajos que pasó\nella por vernos nacer.",138,2,6,154,"Las flores",7,5,"e",20,0,-1,0,395,395,"8482","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8483",7,"Levántate, Severiana,\nno te hagas la remolona,\nque la mujer dormilona\nno goza de la mañana.",136,2,4,154,"El siquisirí",11,4,"aa",4,0,-1,0,395,395,"8483","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8484",7,"Una indita chiquita y bonita\nle dijo a una queretana:\n“Si quiere tener dinero,\nlevántese de mañana”.",144,2,10,154,"Una indita chiquita y bonita",3,4,"aa",4,0,-1,0,395,395,"8484","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8485",7,"Cubierta de paño negro\nuna vez te vi pasar;\nno hay paso más inseguro,\nsi al cielo quieres llegar.",147,2,11,154,"La Llorona",0,4,"a",21,0,-1,0,395,395,"8485","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8486",7,"El que fuere tu enemigo\ndarle bien por castigo,\ny el que diciere una ofensa\ndarle el bien por recompensa.",140,2,12,154,"Estrofa suelta",5,4,"ea",622,0,-1,0,395,395,"8486","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8487",7,"Muchos dicen que el cuerpo es de tierra,\nque el alma que encierra\nes la que ha de vivir;\npues dejemos el cuerpo en la calma,\nsigamos al alma,\nque sabe sentir.",147,2,11,154,"Clarín de campaña",9,6,"i",157,0,-1,0,395,395,"8487","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8488",7,"Y aquel que no oye consejo\nnunca a viejo llegará;\nsi rasuran al vecino,\npon tu barba a remojar.",135,2,-1,154,"Tres consejos",0,4,"a",-1,0,-1,0,395,395,"8488","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8489",7,"Pajarero que se duerme\nno pesca pájaro en nido;\nen todas partes cabrás\nsi tú eres acomedido.",135,2,-1,154,"Estrofa suelta",0,4,"io",101,0,-1,0,395,395,"8489","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8490",7,"Ni te compro limas,\nni te compro peras,\nni te comprometas\na lo que no puedas.",147,2,11,154,"Estrofa suelta",0,4,"ea",-1,0,-1,0,395,395,"8490","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8491",7,"En lo alto de aquel risco\nhay una tabla con letras,\nque dice muy bien clarito:\n“Si no sabes, no te metas”.",147,2,11,154,"Estrofa suelta",0,4,"ea",-1,0,-1,0,395,395,"8491","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8492",7,"Un gorrión quiso poner\nun nido en medio del mar,\nlo que le pudo valer\nque le dice el cardenal:\n“Hay que pensar para hacer\ny no hacer para pensar”.",136,2,4,154,"El siquisirí; El pájaro cú",9,6,"a",-1,0,-1,0,396,396,"8492","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8493",7,"El orgullo, por mi cuenta,\nes un juicio sin recato,\nque forma el odio y lo aumenta:\nno te hinches en tu mandato,\nporque el que se hincha revienta.",153,2,5,154,"Estrofa suelta",7,5,"ea",229,0,-1,0,396,396,"8493","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8494",7,"Cada vez que considero,\nme pongo a considerar\nque los gustos son del cuerpo,\ny el alma los va a pagar.",142,2,8,155,"Estrofa suelta",0,4,"a",21,0,-1,0,397,397,"8494","",0,"","","",14,0,0,[],"",""],["frenk_t3-n8495",7,"Bastante desdicha tiene\nel que a tierra ajena va:\ntodos lo miran y dicen:\n“Éste, ¿qué mañas tendrá?”",136,2,4,155,"Estrofa suelta",0,4,"a",9,0,-1,0,397,397,"8495","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8496",7,"A la mar se le pregunta\ny a mí se me toma el dicho:\n“Camarón que salta a tierra\npronto se lo come el picho”.",153,2,5,155,"Estrofa suelta",0,4,"io",623,0,-1,0,397,397,"8496","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8497",7,"Eso sí será dolor,\nde querer y no poder;\nteniendo el agua en la boca,\ny no poderla beber.",142,2,8,155,"Estrofa suelta",0,4,"e",20,0,-1,0,397,397,"8497","",0,"frenk_t2","","",2,0,0,[],"",""],["frenk_t3-n8498",7,"Ahora sí, cachucha mía,\nvámonos para Tampico;\nque para pasar trabajos,\nlo mismo es pobre que rico.",155,2,14,155,"La cachucha",0,4,"io",141,0,-1,0,397,397,"8498","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8500",7,"“¡Ay, qué bonito!”\ndicen las de Atemajac,\nque para pasar trabajos\nlo mismo es aquí que allá.",135,2,-1,155,"El cuervo",3,4,"a",-1,0,-1,0,397,397,"8500","",0,"","","",4,0,0,[],"",""],["frenk_t3-n8501",7,"Estaba la Lloroncita\nplaticándole a Tomás\nque para pasar trabajos\nlo mismo es acá que allá.",136,2,4,155,"La Lloroncita",0,4,"a",-1,0,-1,0,398,398,"8501","",0,"","","",10,0,0,[],"",""],["frenk_t3-n8502",7,"Estaba la Lloroncita\nplaticándole a David\nque para pasar trabajos\nlo mismo es allá que aquí.",136,2,4,155,"La Lloroncita",0,4,"i",-1,0,-1,0,398,398,"8502","",0,"frenk_t4","","",10,0,0,[],"",""],["frenk_t3-n8503",7,"Estaba la Lloroncita\nplaticándole a su mama\nque para pasar trabajos\nlo mismo es hoy que mañana.",136,2,4,155,"La Lloroncita",0,4,"aa",-1,0,-1,0,398,398,"8503","",0,"","","",10,0,0,[],"",""],["frenk_t3-n8504",7,"Estaba la Lloroncita\nplaticándole a su primo\nque para pasar trabajos\nlo mismo es plan que camino.",136,2,4,155,"La Lloroncita",0,4,"io",-1,0,-1,0,398,398,"8504","",0,"","","",10,0,0,[],"",""],["frenk_t3-n8505",7,"Estaba la Lloroncita\nplaticándole a una niña\nque para pasar trabajos\nlo mismo es aquí que arriba.",136,2,4,155,"La Lloroncita",0,4,"ia",-1,0,-1,0,398,398,"8505","",0,"","","",10,0,0,[],"",""],["frenk_t3-n8506",7,"Estaba la Lloroncita\nplaticándole al ranchero\nque para pasar trabajos\nlo mismo es el plan que el cerro.",136,2,4,155,"La Lloroncita",0,4,"eo",-1,0,-1,0,398,398,"8506","",0,"","","",10,0,0,[],"",""],["frenk_t3-n8507",7,"No se crean, amigos míos,\nde esta canción lastimera:\n“El que no muere en el río\nlo matan en la piedrera”.",146,2,7,155,"Estrofa suelta",0,4,"ea",44,0,-1,0,398,398,"8507","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8508",7,"Yo vide una alegación\nde un cuervo con un perico;\nel cuervo tenía razón\nporque le sobraba pico;\naquél que nace panzón,\naunque lo fajen de chico.",139,2,2,155,"El cuervo",9,6,"io",141,0,-1,0,398,398,"8508","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8509",7,"Los árboles en el monte\ntienen su separación:\nunos nacen para santos\ny otros para hacer carbón.",135,2,-1,155,"Estrofa suelta",0,4,"o",31,0,-1,0,398,398,"8509","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8510",7,"Éstos son los versos de “La mancha”,\nque nadie se ofenda ni vaya a decir,\nporque el rico hace menos al pobre,\ny si no es por el rico, no puede vivir.",135,2,-1,155,"La pobreza",3,4,"i",157,0,-1,0,398,398,"8510","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8511",7,"No hay comisión que se atreva\na molestar a un decente,\npero al pobre prontamente\nen las filas aparece,\nporque en cualquier ocasión\nsiempre el pobre desmerece.",135,2,-1,155,"Estrofa suelta",9,6,"ee",64,0,-1,0,399,399,"8511","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8512",7,"Se ofrece hacer la vela,\nel rico siempre pasea,\npero el pobre ni se menea,\nporque si se sale, la lleva;\nvuelvo [, pues, a] repetir:\nsiempre el pobre desmerece.",135,2,-1,155,"Estrofa suelta",9,6,"ee",-1,0,-1,0,399,399,"8512","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8513",7,"El rico desde la cuna\ntiene pulido latón,\ny el pobre en su mal cajón,\ncon una manta importuna;\ndelicadeza ninguna:\nsiempre el pobre desmerece («cj.",135,2,-1,155,"Estrofa suelta",9,6,"",-1,0,-1,0,399,399,"8513","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8514",7,"Está el niño pobretón\ntirado en cualquier rincón\no en el suelo, si se ofrece,\nporque en cualquier ocasión,\nsiempre el pobre desmerece.",135,2,-1,155,"Estrofa suelta",7,5,"ee",64,0,-1,0,399,399,"8514","",0,"frenk_t4","","",2,0,0,[],"",""],["frenk_t3-n8515",7,"Cuando un rico se toma sus copas:\n“Ahí viene malito, malito el señor”;\ncuando un pobre se toma sus copas:\n“Borracho, perdido, canalla, traidor”.",151,2,23,155,"‘‘La pobreza; La miseria",3,4,"o",72,0,-1,0,399,399,"8515","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8516",7,"Cuando un pobre se emborracha\ntodos dicen: “Bonachón”;\ncuando un rico se las pone:\n“Qué alegrito va el señor”.",135,2,-1,155,"La Julia",0,4,"o",-1,0,-1,0,399,399,"8516","",0,"","","",5,0,0,[],"",""],["frenk_t3-n8517",7,"Cuando un pobre se emborracha\ny el rico en su compañía,\npara el pobre es borrachera\npara el rico es alegría.",142,2,8,155,"Estrofa suelta",0,4,"ia",0,0,-1,0,399,399,"8517","",0,"","","",5,0,0,[],"",""],["frenk_t3-n8518",7,"Cuando un rico amanece tomado\ntodita la gente con gusto: “¡El señor!”\nPara el rico no hay cárcel, no hay pena;\ncometió un delito, sale con honor.",151,2,23,155,"La pobreza",3,4,"o",72,0,-1,0,399,399,"8518","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8519",7,"Cuando el pobre está más arruinado\nni los de su casa lo pueden ver:\nes pelado, es borracho, es plebeño,\ntrabaja al rendir y no sabe cumplir.",151,2,23,155,"La pobreza",3,4,"i",-1,0,-1,0,399,399,"8519","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8520",7,"Para el pobre siempre es tarde,\naunque Uegue a mediodía,\ny habiendo de las calientes,\nsiempre le dan de la fría.",135,2,-1,155,"El siquisirí",0,4,"ia",0,0,-1,0,399,399,"8520","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8521",7,"El pobre cuando se muere\ncon tierra queda tapado;\nolvidan si lo han querido\ny lo que ha pedido fiado;\ntrabaja pa no ser pobre\ny no juntes demasiado.",135,2,-1,155,"Con el oro se compra de todo",9,6,"ao",14,0,-1,0,400,400,"8521","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8522",7,"De la pila nace el agua,\ndel agua, los pescaditos,\ny los pescados más grandes\nse comen a los chiquitos.",135,2,-1,155,"De la arena nace el agua",0,4,"io",254,0,-1,0,400,400,"8522","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8523",7,"Por todo el mundo he andado,\ny no he visto conformidad;\nsólo los palos del monte\nviven en buena hermandad:\naunque caiga uno sobre otro,\nno le dice “Hazte pa allá”.",142,2,8,155,"Estrofa suelta",9,6,"a",-1,0,-1,0,400,400,"8523","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8524",7,"Lo cierto es que en todas partes\nhay quien sepa aprovechar\nel trabajo de los otros,\nsin ponerse a trabajar.",137,2,3,155,"La plpiolita",0,4,"a",21,0,-1,0,400,400,"8524","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8525",7,"Uno es el santito,\ny otro hace el milagro;\npor eso es que a muchos\nse los lleva el diablo.",135,2,-1,155,"Los bueyes",0,4,"ao",-1,0,-1,0,400,400,"8525","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8526",7,"Rema, guarecita, rema,\nrema para San Miguel,\nque unos sembraron la tuna,\ny otros se comen su miel.",135,2,-1,155,"Estrofa suelta, La guarecita",0,4,"e",32,0,-1,0,400,400,"8526","",0,"","","",8,0,0,[],"",""],["frenk_t3-n8527",7,"Cierto artífice pintó\nuna lucha en que, valiente,\nun hombre solamente\na un horrible león venció;\notro león, que el cuadro vio,\nsin preguntar por su autor,\nen tono despreciador\ndijo: “Bien se deja ver\nque es pintar como querer,\ny no fue león el pintor”.",135,2,-1,155,"Estrofa suelta",18,10,"o",72,0,-1,0,400,400,"8527","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8528",7,"En este mundo traidor\nnada es verdad ni mentira:\ntodo es según el color\ndel cristal con que se mira.",136,2,4,155,"Estrofa suelta",1,4,"ia",372,0,-1,0,400,400,"8528","",0,"frenk_t4","","",3,0,0,[],"",""],["frenk_t3-n8530",7,"San Agustín escribió\nque glorias no más hay una;\nborradores nos dejó\nque los bienes de fortuna\nhoy son y mañana no.",136,2,4,155,"El huerfanito",7,5,"o",2,0,-1,0,400,400,"8530","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8532",7,"Un pajarito en la mar\nal verse tan solo lloraba,\nno más de considerar\nque todo cuanto hay se acaba.",140,2,12,155,"La presumida",1,4,"aa",28,0,-1,0,401,401,"8532","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8533",7,"Que suenen las campanas\nde Malibrán;\nque suenen, que suenen,\nque ya doblarán.",135,2,-1,155,"Estrofa suelta",6,4,"a",147,0,-1,0,401,401,"8533","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8534",7,"Si la vida fuera alfalfa,\nretoñara cada mes;\nla vida cuando se va\nse va para de una vez.",135,2,-1,155,"Corrido de Rafaelita",0,4,"e",150,0,-1,0,401,401,"8534","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8535",7,"En un árbol corpulento\ncantaba un viejo en la selva:\n“Hojas que arrebata el viento\njamás esperen que vuelvan”.",142,2,8,155,"Estrofa suelta",0,4,"ea",-1,0,-1,0,401,401,"8535","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8536",7,"El cuervo, con ser tan negro,\nrelumbra más que la plata;\nmás altas suben las nubes,\ny el aire las desbarata.",135,2,-1,155,"El cuervo. Estrofa suelta",0,4,"aa",74,0,-1,0,401,401,"8536","",0,"","","",3,0,0,[],"",""],["frenk_t3-n8537",7,"El viento tumba las hojas,\ntambién las sabe arrastrar;\nlas nubes, por altas que anden,\nlas sabe desbaratar.",135,2,-1,155,"Estrofa suelta",0,4,"a",21,0,-1,0,401,401,"8537","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8538",7,"Hay cosas que, al parecer,\nparecen ser inocentes,\notras hay que, sucediendo,\napenas se pueden creer,\nsólo porque.....................",147,2,11,155,"El llorar",7,5,"oe",-1,0,-1,0,401,401,"8538","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8539",7,"¡Ay, Soledad, Soledad!,\nSoledad para el Oriente;\nel más amigo es traidor,\nel más verdadero miente.",135,2,-1,155,"La Petenera",0,4,"ee",15,0,-1,0,401,401,"8539","",0,"","","",18,0,0,[],"",""],["frenk_t3-n8540",7,"Subí a la altura de un cuervo,\npor ver la dicha de un hombre\nsi la vide, no me acuerdo,\nsi me acuerdo, no sé en dónde.",145,2,17,155,"Estrofa suelta",0,4,"oe",-1,0,-1,0,401,401,"8540","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8541",7,"Las flores que ya perdieron\nsu color y su fragancia\nmártires del tiempo fueron:\nno tuvieron más bonanza\nque las aguas que corrieron.",135,2,-1,155,"Estrofa suelta",7,5,"eo",105,0,-1,0,402,402,"8541","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8542",7,"Y ya me voy a despedir,\nporque así debe de ser;\nsólo les voy a decir\nque deben de comprender\nque tenemos que surgir\npara después perecer.",136,2,4,155,"El siquisirí",9,6,"e",20,0,-1,0,402,402,"8542","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8544",7,"¡Caramba, pero ay caramba!,\n¡ay, qué caramba es la vida!\nEmpieza siempre llorando\ny así llorando termina.",147,2,11,155,"ay, qué caramba es la vida! Empieza siempre llorando y así llorando termina. [Estrofa suelta",0,4,"ia",-1,0,-1,0,402,402,"8544","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8545",7,"De aquel lado que no vaya\npuede tener su guardado;\ntenlo bien asegurado,\ntápalo con su atarraya.",135,2,-1,155,"El tuxpeño",11,4,"aa",404,0,-1,0,402,402,"8545","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8546",7,"Ya te he dicho que no vayas\na lavar al ojo de agua:\ngastadero de jabón\ny derramadero de agua.",135,2,-1,155,"El Cihualteco; El pajarillo",0,4,"aa",-1,0,-1,0,402,402,"8546","",0,"","","",6,0,0,[],"",""],["frenk_t3-n8547",7,"Esas malas compañías\nno te las puedo quitar;\nmira, que si no las dejas,\nte vas a perjudicar.",162,2,27,155,"Ojitos negros y chinos",0,4,"a",21,0,-1,0,402,402,"8547","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8548",7,"Como amigo te aconsejo\nque el mundo tiene mudanzas;\ncon extremos de cariño,\nno gasta tanta confianza:\npronto te da tu retiro,\nno lo tengas a la chanza.",135,2,-1,155,"Al pasar por los laureles",9,6,"aa",163,0,-1,0,402,402,"8548","",0,"","","",2,0,0,[],"",""],["frenk_t3-n8549",7,"¡Ay!, el cielo se nubló,\nya comienza a lloviznar;\nno pienses que de esta agua\nen ella te vas a ahogar;\npiensa bien y no resbales:\nno se te vaya a olvidar..",142,2,8,155,"Estrofa suelta",9,6,"a",21,0,-1,0,402,402,"8549","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8550",7,"Porque del plato a la boca\na veces se cae la sopa,\nmás vale ser desconfiado,\ny así nunca sufrirás.",135,2,-1,155,"Tres consejos",5,4,"a",-1,0,-1,0,403,403,"8550","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8551",7,"No engordes a puerca chica,\nque toda se va en crecer,\nni obsequies a gente rica,\nque no lo ha de agradecer.",135,2,-1,155,"Estrofa suelta",1,4,"e",20,0,-1,0,403,403,"8551","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8552",7,"Si quisiereis prosperar,\ncatrincitos, en la vida,\nsacudid a los de abajo\ny adulad a los de arriba.",135,2,-1,155,"Estrofa suelta, El pastelero",0,4,"ia",-1,0,-1,0,403,403,"8552","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8553",7,"No hay que afligirse, bien mío,\naunque el dolor nos maltrate;\ny aunque la puerca te muerda,\nno le sueltes el mecate.",135,2,-1,155,"Estrofa suelta",0,4,"ae",384,0,-1,0,403,403,"8553","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8554",7,"Disfrutemos del gusto\nantes que llegue la muerte,\nporque cayendo al sepulcro,\nya no hay quien se despierte.",142,2,8,155,"Estrofa suelta",0,4,"ee",134,0,-1,0,403,403,"8554","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8555",7,"Es una cosa bonita\nel tener mucho dinero,\npa darle vuelo a la hilacha\ny comprar un lindo cuero.",137,2,3,156,"La chinita",0,4,"eo",38,0,-1,0,406,406,"8555","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8556",7,"Tratar con desesperados\nen política es atroz\nporque estando bien con Dios,\nlos santos y excomulgados\ntodos hacen los mandados.",152,2,13,156,"Estrofa suelta",7,5,"ao",18,0,-1,0,406,406,"8556","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8557",7,"Y al gusto lo nombran “gusto”,\ny al apelativo “llanto”;\nel que padece de susto\nno puede morir de espanto;\nel padecer es muy justo:\npoquito, pero no tanto.",139,2,2,156,"El gusto",9,6,"ao",30,0,-1,0,406,406,"8557","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8558",7,"Pescando en el mar salado,\nme dijo don tío Genovevo,\nque dicen en Alvarado\nque a nadie le tiene miedo:\n“Y para comer pescado,\nhay que mojarse los huevos”.",136,2,4,156,"Estrofa suelta",9,6,"eo",-1,0,-1,0,406,406,"8558","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8559",7,"¡Cuánta naranja madura!,\n¡cuánto limón por el suelo!,\n¡cuánta muchacha bonita!,\n¡cuánto catrín sin dinero!",145,2,17,156,"El huizache; El baulito; Que viva la rumba; Estrofa suelta",0,4,"eo",-1,0,-1,0,406,406,"8559","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8560",7,"Vuela, vuela, vuela,\npájaro azulejo;\nla cáscara guarda el palo,\ny la cascaría, al pellejo.",136,2,4,156,"La guacamaya",0,4,"eo",264,0,-1,0,406,406,"8560","",0,"","","",17,0,0,[],"",""],["frenk_t3-n8561",7,"La cáscara guarda al palo,\nmas si el pollo es un muchacho\ny la cáscara, de mugre,\nhuele a puro chivo malo.",135,2,-1,156,"Estrofa suelta",0,4,"ao",-1,0,-1,0,407,407,"8561","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8562",7,"El tejón sale y se esconde\ny se burla de nosotros,\nporque dice que los hombres\nsomos retementirosos.",135,2,-1,156,"El nuevo tejón",0,4,"oo",-1,0,-1,0,407,407,"8562","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8564",7,"Cuando te pidan cigarro\nno des cigarro y cerillo,\nporque si das las dos cosas,\nte tantearán de zorrillo.",135,2,-1,156,"Allá en el Rancho Grande",0,4,"io",228,0,-1,0,407,407,"8564","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8565",7,"A caballo andan los hombres,\nen muía, los alcahuetes,\nen burro, los más pendejos\ny a pie, los que son ojetes,",135,2,-1,156,"Estrofa suelta",0,4,"ee",505,0,-1,0,407,407,"8565","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8566",7,"¡Cuánto te gusta mi son!,\n¡cuánto te gusta bailar!\nDéjate del vacilón,\ntrabaja, no seas huevón.",139,2,2,156,"El querreque",5,4,"o",31,0,-1,0,407,407,"8566","",0,"","","",1,0,0,[],"",""],["frenk_t3-n8567",7,"Pájaros azules,\npájaros bermejos;\n¡ay, qué trabajos\npasan los pendejos!",138,2,6,156,"Estrofa suelta",6,4,"eo",149,0,-1,0,407,407,"8567","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8568",8,"Ya el cielo de la tarde\nse está nublando,\ny todo el horizonte\nse está apagando.",166,2,-1,157,"Atardecer huasteco",6,4,"ao",33,0,-1,0,28,28,"8568","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8569a",8,"La tarde se va muriendo\nen los brazos de la noche,\nunas flores van abriendo\ny otras cerrando su broche.",166,2,-1,157,"El gusto; El lunarcito",1,4,"oe",337,0,-1,0,28,28,"8569a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8569b",8,"Ya la tarde va muriendo\nen los brazos de la noche;\nunas flores van abriendo\ny otras, cerrando su broche,\nsus aromas esparciendo.",167,2,2,157,"Estrofa suelta",7,5,"eo",52,0,-1,0,28,28,"8569b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8570",8,"La tarde se va muriendo,\nya va agonizando el día,\nse alborotan los papanes\npor toda la serranía;\ncaminando voy, cantando\na la Huastequita mía.",166,2,-1,157,"Mi cielo huasteco",9,6,"ia",0,0,-1,0,28,28,"8570","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8571",8,"La luz de la luna llena\ncorre por todo el potrero,\nla van siguiendo las nubes\ncon gotitas de aguacero.",168,2,11,157,"El arreo",0,4,"eo",38,0,-1,0,28,28,"8571","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8572",8,"Las calles están desiertas,\nlas nubes vagan perdidas,\nestán las aves despiertas\ny las estrellas [dormidas].",169,2,8,157,"Asómate a la ventana",1,4,"ia",279,0,-1,0,28,28,"8572","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8573",8,"Marinero, marinero,\nque navegas en el mar,\nuna noche tan hermosa\nno la has visto ni verás.",168,2,11,157,"Estrofa suelta",0,4,"a",-1,0,-1,0,28,28,"8573","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8574",8,"Esta noche, nuevo el cielo;\nlas estrellas en el viento\nme parecen margaritas,\ncomo prado y su ornamento.",170,2,7,157,"Caminata",0,4,"eo",94,0,-1,0,29,29,"8574","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8575",8,"Salgan acá fuera,\nverán maravillas,\nverán las estrellas\nqué bonito brillan.",171,2,4,157,"Naranjas y limas",0,4,"ia",-1,0,-1,0,29,29,"8575","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8576",8,"Las estrellitas del cielo\nbrillan con su luz de plata;\nSantiago las fue sembrando\ncon sus espuelas de plata.",172,2,23,157,"Las estrellas del cielo",0,4,"aa",-1,0,-1,0,29,29,"8576","",0,"","","",25,0,0,[],"",""],["frenk_t4-n8577",8,"De las estrellas del cielo\nyo te diré cuál es mía;\ny ese lucero brillante\nque sigue a las Tres Marías.",169,2,8,157,"La Juanita",0,4,"ia",-1,0,-1,0,29,29,"8577","",0,"","","",7,0,0,[],"",""],["frenk_t4-n8578",8,"La luna viene saliendo,\nel lucero no aparece;\nme basta con su lumbrita,\npara saber que amanece.",173,2,17,157,"El súchil",0,4,"ee",64,0,-1,0,29,29,"8578","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8579",8,"La luna y el sol\nse pusieron a platicar,\ny la luna le decía:\n“No te vayas a enojar”.",174,2,9,157,"Estrofa suelta",0,4,"a",21,0,-1,0,29,29,"8579","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8580",8,"La tierra y la mar\nse pusieron a cantar,\ny la tierra le decía:\n“Tú sí sabes entonar”.",166,2,-1,157,"Estrofa suelta",0,4,"a",21,0,-1,0,29,29,"8580","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8581",8,"El mar canta sus querellas,\nel cielo, al oír sus cuitas,\ny decía con frases bellas,\ncon palabras exquisitas:\n“Si tú me das [tus] estrellas,\nyo te ofrezco mis conchitas”.",175,2,6,157,"Las conchitas",9,6,"ia",258,0,-1,0,29,29,"8581","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8582",8,"Por las orillas del mar\nme puse a regar corales,\npara que coloradeen\nla mar y los arenales.",169,2,8,157,"Chilena de Jamiltepec; Estrofa suelta",0,4,"ae",26,0,-1,0,29,29,"8582","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8583",8,"En el mar se crían conchitas,\npero no en todos lugares;\nhay grandes y hay chiquitas,\npero en los reinos polares\nse crían otras más bonitas,\nde anacarados lunares.",175,2,6,157,"Las conchitas",9,6,"ae",164,0,-1,0,30,30,"8583","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8584",8,"Feliz guía del marinero,\neres la estrella del mar;\nen la tierra y en el cielo\nyo te vengo a saludar.",170,2,7,157,"Caminatas",3,4,"a",21,0,-1,0,30,30,"8584","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8585",8,"Allá en el mar, donde estuvimos\ndentro del agua cerca de un mes,\nhabía unos peces tan chiquititos\ncomo la punta de un alfiler.",166,2,-1,157,"Buscando peces",3,4,"e",-1,0,-1,0,30,30,"8585","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8587",8,"Ya viene la primavera\nsembrando flores,\nya los campos se visten\nde mil colores;\ncantan las aves,\nlos zinzontes repiten\nsus trinos suaves.",166,2,-1,157,"La primavera",4,7,"ae",129,0,-1,0,30,30,"8587","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8588",8,"Por entre estos montes\n—¡oh sierra elevada!—\nlas aves gorjean\na la madrugada.",166,2,-1,157,"Pastorcita virgen",0,4,"aa",49,0,-1,0,30,30,"8588","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8589",8,"Las nubes todas se esfuman,\nlas aves alegres cantan,\nlas flores todas perfuman,\nlas colmenas se levantan.",166,2,-1,157,"Las mañanitas",1,4,"aa",564,0,-1,0,30,30,"8589","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8590",8,"Los árboles enverdecen,\ny alegra la primavera,\ny la venada ligera\nse divisa muy veloz.",173,2,17,157,"La venadita",5,4,"o",-1,0,-1,0,31,31,"8590","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8591",8,"Escucha los dulces cantos\ndel zenzontle y el jilguero;\nmira qué verdes los campos,\nqué montoso está el potrero;\nde flores, mirtos y nardos\nestá revestido el cerro.",166,2,-1,157,"Ahi Viene el agua’’",9,6,"eo",-1,0,-1,0,31,31,"8591","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8592",8,"Por ahí pasó volando\ny una calandria morada,\ny en su piquito llevaba\nuna rosa colorada.",176,2,3,157,"La calandria'*",0,4,"aa",-1,0,-1,0,31,31,"8592","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8593a",8,"Por aquí pasó volando\nuna calandria amarilla,\nen el piquito llevaba\nuna rosa de Castilla.",166,2,-1,157,"La calandria; El palomo",0,4,"ia",162,0,-1,0,31,31,"8593a","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8593b",8,"Por aquí pasó volando\nuna calandria amarilla,\nen el piquito llevaba\nuna rosa de Castilla,\nque el viento le deshojaba.",166,2,-1,157,"María Chuchena",7,5,"aa",28,0,-1,0,31,31,"8593b","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8593c",8,"Por aquí pasó volando\nuna calandria amarilla,\ny en el piquito llevaba\nuna rosa de Castilla,\nque el viento la deshojaba\ncomo blanca maravilla.",171,2,4,157,"María Chuchena; La azucena",9,6,"ia",162,0,-1,0,31,31,"8593c","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8594a",8,"Por aquí pasó volando\nuna bella chuparrosa,\ny en su piquito llevaba\ntres claveles y una rosa,\nque el viento le deshojaba.",171,2,4,157,"María Chuchena",7,5,"aa",28,0,-1,0,31,31,"8594a","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8594b",8,"Por aquí pasó volando\nuna bella chuparrosa,\ny en su piquito llevaba\ndos claveles y una rosa,\nque el viento le deshojaba\ncomo grata mariposa.",171,2,4,157,"María Chuchena",9,6,"oa",63,0,-1,0,31,31,"8594b","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8595",8,"La azucena es una flor\nmás linda que los jazmines:\nsu perfume es el mejor,\nporque es más encantador,\nmejor que el de los jazmines.",175,2,6,157,"La azucena",7,5,"ie",-1,0,-1,0,32,32,"8595","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8596",8,"La rosa pa que sea buena\nse corta de mañanita,\nmayormente la azucena,\nque es una flor exquisita:\nen la noche se serena,\nviene el sol y la marchita.",175,2,6,157,"La azucena",9,6,"ia",50,0,-1,0,32,32,"8596","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8597",8,"Árbol frondósorolo,\nde verde prádorolo,\nque yo he soñádorolo.\ny en mi niñez.",176,2,3,157,"Canción de las canacuas",6,4,"e",-1,0,-1,0,32,32,"8597","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8598",8,"Pajarillos tiernos\nque cantáis al alba,\nárboles vestidos\nde verde esmeralda.",166,2,-1,157,"Canto de Eva",0,4,"aa",-1,0,-1,0,32,32,"8598","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8599",8,"Bonitos son los palmares,\nbonito temperamento;\nandan muchos animales,\nque causan divertimento.",166,2,-1,157,"El palmero",0,4,"eo",94,0,-1,0,32,32,"8599","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8601",8,"¡Qué bonito frijolito,\nqué bonito se enmaraña!\nArriba, flores y guías,\nabajo, vainas y vainas.",166,2,-1,157,"Estrofa suelta",0,4,"aa",-1,0,-1,0,32,32,"8601","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8602",8,"¡Ay, Solita, ay, Soledad!,\nSoledad del horizonte,\ncon este tiempo se quema\nla leña verde del monte.",171,2,4,157,"La Petenera",0,4,"oe",325,0,-1,0,32,32,"8602","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8603",8,"El día primero de junio\ncomienzan los aguaceros,\ncantan muchas chicharritas\nen medio de los potreros.",177,2,18,157,"La chicharra",0,4,"eo",22,0,-1,0,32,32,"8603","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8604",8,"Yo le dije a mi mamá\nque me llevara al llanito,\na ver cómo corría el agua\ndebajo del zacatito.",178,2,10,157,"Estrofa suelta",0,4,"io",119,0,-1,0,32,32,"8604","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8606",8,"Y a la capotín tintintín,\nque esta noche va a llover,\ny a la capotín tintintín,\ncerca del amanecer.",178,2,10,157,"El capotín",3,4,"e",20,0,-1,0,33,33,"8606","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8607",8,"Al pie de una nube negra\nyo vide relampaguear:\nes segurito aguacero,\nque nos viene a alcanzar.",176,2,3,157,"El relámpago",0,4,"a",21,0,-1,0,33,33,"8607","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8608",8,"Se mirarán en el cielo\ncuatro astros en conjunción,\ny habrá peste y aflicción,\nhambre y sequía en este suelo\ny un diluvio en conclusión.",166,2,-1,158,"Estrofa suelta",7,5,"o",31,0,-1,0,36,36,"8608","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8609",8,"No hay tiempo, según comprendo,\nde noticiar estos días,\nporque ya se están cumpliendo\nde Cristo las profecías.",166,2,-1,158,"Estrofa suelta",1,4,"ia",214,0,-1,0,36,36,"8609","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8610",8,"¡Penitencia, penitencia!,\nya no peques, hombre atroz,\nexamina tu conciencia,\nven al templo, oye la voz.",166,2,-1,158,"Estrofa suelta",1,4,"o",280,0,-1,0,36,36,"8610","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8611",8,"¡Jesús, María'\nque me espanto,\nporque los negritos\nvan a acostar,\nque la gente muere\nsin confesar.",171,2,4,158,"Los negritos",9,6,"a",21,0,-1,0,36,36,"8611","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8612",8,"Diablo que anda en Castilla,\ncon vuelillos y golilla,\n¿quién será, quién será?\n¡Jesucristo, qué fracaso!\nYa está aquí; dejadle paso.",179,2,26,158,"Estrofa suelta",7,5,"ao",145,0,-1,0,36,36,"8612","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8613",8,"¿Cuándo llegará ese cuándo\nque el príncipe Lucifer\nvuelva a tener la fortuna\nde que le digan Luzbel?",166,2,-1,158,"Estrofa suelta",0,4,"e",-1,0,-1,0,36,36,"8613","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8614",8,"Sus ojos divinos\nmiro cerraditos,\npero están mirando\ntodos mis delitos.",166,2,-1,158,"Canto de Nochebuena",0,4,"io",254,0,-1,0,36,36,"8614","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8615",8,"Las ovejas somos\nde este Pastorcito,\nno nos apartemos\nde su dulce aprisco.",166,2,-1,158,"Canto de Nochebuena",0,4,"io",-1,0,-1,0,37,37,"8615","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8616",8,"Pescadores somos\ndel género humano,\na quien nunca en vano\ntendemos la red.",176,2,3,158,"Pescadores somos",5,4,"e",-1,0,-1,0,37,37,"8616","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8617",8,"Dios para formar al hombre\ndescendencia no buscó:\ntomó un pedazo de barro\ny al momento lo formó.",168,2,11,159,"Estrofa suelta",0,4,"o",2,0,-1,0,38,38,"8617","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8618",8,"Toquen las panderetas,\nruido y más ruido,\nporque las profecías\nya se han cumplido.",170,2,7,159,"Estrofa suelta",6,4,"io",101,0,-1,0,38,38,"8618","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8619",8,"De aquel pecado primero\nque hizo nuestro padre Adán\nel Mesías profetizado\nel pecado borrará.",180,2,25,159,"En el portal de Belén",0,4,"a",-1,0,-1,0,38,38,"8619","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8620",8,"El demonio —¡qué amargura!—\nde este gusto causará\nque de una pura criatura\nnos venga la libertad",180,2,25,159,"En el portal de Belén",0,4,"a",-1,0,-1,0,38,38,"8620","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8621",8,"Nací de alta jerarquía,\nme despeñó mi altivez,\nyo vencí al mundo después,\ny a mí me venció María.",166,2,-1,159,"Estrofa suelta",11,4,"ia",0,0,-1,0,38,38,"8621","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8622",8,"La idolatría fue vencida,\nhumillado fue Satán;\nen esta fecha querida\nhonrad la estirpe de Adán.",166,2,-1,159,"Los moros",1,4,"a",147,0,-1,0,38,38,"8622","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8623",8,"A orillas del río Jordán\nse vieron mil maravillas:\nvide a Cristo de rodillas\nbautizándolo San Juan.",176,2,3,159,"Estrofa suelta, La Sanmarqueña; Versos de San Juan’’",11,4,"a",147,0,-1,0,38,38,"8623","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8624",8,"En la fuente bebió Cristo\nagua de San Juan de Dios,\nque con sus aguas bautizaba\nSan Juan a Nuestro Señor.",170,2,7,159,"Los papaquis",0,4,"o",-1,0,-1,0,38,38,"8624","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8625",8,"Toda la Semana Santa\nfueron penas para el Señor;\n¡válgame, Dios de los cielos,\nqué tristeza, qué dolor!",169,2,8,159,"Estrofa suelta",0,4,"o",72,0,-1,0,39,39,"8625","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8626",8,"En el huerto de las flores\napresaron al Señor\ny de prisiones le echaron\ncuatro flores de color",173,2,17,159,"Estrofa suelta",0,4,"o",72,0,-1,0,39,39,"8626","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8627",8,"—Arre, borreguitos,\n¿por qué van tan recio?\n—A ver a Jesús,\nque lo llevan preso.",171,2,4,159,"Naranjas y limas",0,4,"eo",-1,0,-1,0,39,39,"8627","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8628",8,"—Arre, borreguito,\n¿dónde vas volando?\n—Voy a ver al Niño,\nque lo están matando.",171,2,4,159,"Naranjas y limas",0,4,"ao",33,0,-1,0,39,39,"8628","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8629",8,"—¿Quién es aquella señora\nque cuida por el corredor?\n—Santa María Magdalena,\nque anda en busca del Señor.",181,2,15,159,"Estrofa suelta",0,4,"o",72,0,-1,0,39,39,"8629","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8630",8,"Con esos tres clavos\nque tiene la cruz,\ncon ellos clavaron\na nuestro Jesús.",181,2,15,159,"A la Santa Cruz",0,4,"u",270,0,-1,0,39,39,"8630","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8631",8,"Entré por la sacristía,\nsalí por ’l altar mayor (mi vida),\nencontré la Virgen María,\nhincadita de rodillas (mi vida),\nllorando por el Señor (mi vida).",175,2,6,159,"La madrugada",7,5,"ia",72,0,-1,0,39,39,"8631","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8632",8,"Jueves Santo murió Cristo,\nviernes él hizo el entierro,\nsábado subió a la gloria,\nel domingo sube a los cielos.",170,2,7,159,"Los papaquis",0,4,"eo",-1,0,-1,0,39,39,"8632","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8633",8,"Lloró Simón Cirineo\nde ver penar a Jesús,\nle ayudó a cargar la cruz\ny le puso el mascabeo;\ntambién lloró San Mateo\npor causa que es bien sabida;\nen su escritura decía:\n“Llorando con gran despecho,\nuna mujer en el pecho\nun santo Cristo tenía”.",171,2,4,159,"Estrofa suelta",18,10,"ia",0,0,-1,0,39,39,"8633","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8634",8,"Del costado de Jesús\nsale el tesoro precioso\ncon que, cual fiador piadoso,\npaga a Dios desde la cruz;\ny mirado a buena luz,\nporque se gloría en las penas,\nquiere que en ígneas cadenas\nse acrisolen almas justas\ny que en fuego logren juntas\nel tesoro de sus venas.",166,2,-1,159,"Estrofa suelta",18,10,"ea",62,0,-1,0,40,40,"8634","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8635",8,"La sangre que está cayendo\ncae en un cáliz sagrado;\nel hombre que la bebiere\nserá bienaventurado.",173,2,17,159,"Estrofa suelta",0,4,"ao",14,0,-1,0,40,40,"8635","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8636",8,"La muerte del justo\nserá maldición\nal infame pueblo\nque lo condenó.",168,2,11,159,"Estrofa suelta",0,4,"o",-1,0,-1,0,40,40,"8636","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8637",8,"Todo aquel que misa toma\nningún accidente tema,\npues ni la lumbre le quema,\nni tiene hambre, aunque no coma.",166,2,-1,159,"Estrofa suelta",11,4,"oa",86,0,-1,0,40,40,"8637","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8639",8,"Y pues hay ejemplos tantos\nque esta reliquia preserva\ndel demonio y sus encantos,\ndichoso aquel que conserva\nlos cuatro evangelios santos.",170,2,7,159,"Estrofa suelta",7,5,"ao",618,0,-1,0,40,40,"8639","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8640",8,"Angélicos coros,\nvenid a la guerra;\nquien venciere viva,\nquien se rinda muera.",181,2,15,159,"Estrofa suelta",0,4,"ea",-1,0,-1,0,40,40,"8640","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8641",8,"Tropas de Jesús,\nvamos a la guerra,\nno desmaye nadie,\nsigan su bandera.",178,2,10,159,"Las tropas de Jesús",0,4,"ea",-1,0,-1,0,40,40,"8641","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8642",8,"Las tropas del Salvador,\nmarchen a paso veloz,\nsigan con crecido amor\ny a las banderas de Dios.",166,2,-1,159,"Las tropas del Salvador",1,4,"o",-1,0,-1,0,40,40,"8642","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8643",8,"Junto al monte pasaba Juan Diego,\nse acercó hacia luego\nal oír cantar.\nEn la tilma, entre rosas pintadas,\nsu imagen sagrada\nse dignó de paz.",171,2,4,159,"A la Virgen de Guadalupe",9,6,"a",-1,0,-1,0,40,40,"8643","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8644",8,"Cuando Juan llegó, llegó,\nlo tomaron de insensato;\nel obispo no sabía\nque ahí llevaba el retrato.",171,2,4,159,"A la Virgen de Guadalupe",0,4,"ao",19,0,-1,0,41,41,"8644","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8645",8,"Cuando Juan llegó, llegó,\nal momento se le hincó,\ndiciendo que lo perdonara\npor lo que se le negó.",171,2,4,159,"A la Virgen de Guadalupe",0,4,"o",2,0,-1,0,41,41,"8645","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8647",8,"Por lo que se ve y se ha visto,\nmiren un hecho insolente,\ny se acordará el viviente\ncómo premia Jesucristo.",166,2,-1,159,"Estrofa suelta",11,4,"io",273,0,-1,0,41,41,"8647","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8648",8,"Ven, pecador, a mis brazos,\nolvida el pecado fiero,\nven a buscarme piadoso,\nno me aguardes justiciero.",166,2,-1,159,"Estrofa suelta",0,4,"eo",38,0,-1,0,41,41,"8648","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8649",8,"Levántate, alma dormida,\nque en el cielo tengo flores;\nven con mi Madre querida,\nrefugio de pecadores.",171,2,4,159,"Estrofa suelta",1,4,"oe",5,0,-1,0,41,41,"8649","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8650a",8,"Del tronco nació la rama\ny de la rama, la flor;\nde la flor nació María,\ny de María, el Redentor.",171,2,4,159,"Versos de San [uan; En el portal de Belén, Canto de Nochebuena; Estrofa suelta",0,4,"o",72,0,-1,0,41,41,"8650a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8650b",8,"De un tronco nació una rama\ny de la rama, una flor,\ny de la flor ha nacido\nel Divino Redentor,\nque nos pondrá en libertad.",166,2,-1,159,"Canto de Nochebuena",7,5,"a",-1,0,-1,0,41,41,"8650b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8651",8,"En el Puerto Milagros\nse ha quedado en este día\nla apariencia milagrosa\nde la celestial María.",171,2,4,159,"A la Virgen de Guadalupe",0,4,"ia",0,0,-1,0,41,41,"8651","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8652",8,"El Niño de Atocha\nno se halla en Plateros,\nse halla en los caminos,\namparando arrieros.",178,2,10,159,"El Niño de Atocha",0,4,"eo",22,0,-1,0,41,41,"8652","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8653",8,"El niño Dios se ha perdido,\nen el cielo no aparece;\nestá en la orilla del río,\nconsultando con los peces.",166,2,-1,159,"Canto de Nochebuena",0,4,"ee",-1,0,-1,0,42,42,"8653","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8655",8,"La Virgen María\nsu pelo tendió;\nhizo una cadena,\nque al cielo llegó.",171,2,4,159,"Naranjas y limas",0,4,"o",2,0,-1,0,42,42,"8655","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8656",8,"Allí está la Virgen\nen el corredor,\ncosiendo la capa\nde Nuestro Señor.",178,2,10,159,"Canción de cuna",0,4,"o",72,0,-1,0,42,42,"8656","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8657",8,"—¿Y para qué y para cuándo\nquieres el manto?\n—Para las estaciones\ndel Viernes Santo.",171,2,4,159,"El pájaro cú",3,4,"ao",30,0,-1,0,42,42,"8657","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8658",8,"En el portal de Belén\nhay una piedra redonda,\ndonde el Señor pone el pie\npara subir a la gloria.",166,2,-1,159,"Canto de Nochebuena",0,4,"oa",-1,0,-1,0,42,42,"8658","",0,"","","",32,0,0,[],"",""],["frenk_t4-n8659",8,"Caminando va José,\ncaminando va María,\ny como van a Nazaret,\ncaminando de alegría.",171,2,4,159,"Canto de Nochebuena, Pastorcita virgen",0,4,"ia",0,0,-1,0,42,42,"8659","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8660",8,"Dicen que han venido\ndesde Nazaret\nlos tiernos esposos\nMaría y José.",171,2,4,159,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,42,42,"8660","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8661",8,"La más agraciada,\nVirgen nazarena,\na tierras lejanas\nsalió muy serena.",171,2,4,159,"Naranjas y limas",0,4,"ea",59,0,-1,0,42,42,"8661","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8662",8,"Salió acompañada\nde su fiel esposo,\na buscar morada\nal Dios poderoso.",171,2,4,159,"Naranjas y limas",1,4,"oo",160,0,-1,0,42,42,"8662","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8663",8,"Por entre estas peñas,\npor entre estos cerros,\nviene caminando\nla reina del cielo.",166,2,-1,159,"Pastorcita virgen’*",0,4,"eo",-1,0,-1,0,43,43,"8663","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8665",8,"De la real Jerusalén\nsale una estrella brillando,\nque a los pastores va guiando\npara el portal de Belén.",180,2,25,159,"En el portal de Belén",11,4,"e",242,0,-1,0,43,43,"8665","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8667",8,"Le dice María:\n“Despierta, José,\nque el rey de los cielos\nya quiere nacer”.",166,2,-1,159,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,44,44,"8667","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8668",8,"La Virgen iba a Belén,\nle dio el parto en el camino,\ny entre la mula y el buey\nnació el Cordero Divino.",166,2,-1,159,"Canto de Nochebuena; Estrofa suelta",3,4,"io",199,0,-1,0,44,44,"8668","",0,"rm_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],"",""],["frenk_t4-n8669",8,"Esa noche a medianoche,\ncuando Dios quiso nacer,\nbajó el ángel San Gabriel\nen su caballito blanco,\nalumbrando todo el campo.",166,2,-1,159,"Estrofa suelta",7,5,"ao",-1,0,-1,0,44,44,"8669","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8670",8,"Un pastor comiendo sopas\nen el aire divisó\nun ángel que le decía:\n“Ya ha nacido el Redentor”.",166,2,-1,159,"Canto de Nochebuena",0,4,"o",-1,0,-1,0,44,44,"8670","",0,"rm_t4, palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],"",""],["frenk_t4-n8671",8,"A las doce de una noche,\nque más feliz no se vio,\nnació en un Ave-María\nsin romper el alba, el sol.",166,2,-1,159,"Canto de Nochebuena",0,4,"o",-1,0,-1,0,44,44,"8671","",0,"lafuente_madrid","","",3,0,0,[],"",""],["frenk_t4-n8672",8,"A la madrugada\nnació el niño Dios,\ncomo a la alborada\ndio su luz el sol.",166,2,-1,159,"Canto de Nochebuena",0,4,"o",-1,0,-1,0,44,44,"8672","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8673",8,"El galló cantó,\ndándonos aviso\nque Cristo nació\nen aquel paraíso.",169,2,8,159,"Naranjas y limas",1,4,"io",92,0,-1,0,44,44,"8673","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8674",8,"El rey de los cielos\nen Belén nació;\nlleno de consuelo\nun gallo cantó.",171,2,4,159,"Naranjas y limas",0,4,"o",2,0,-1,0,44,44,"8674","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8675",8,"A la medianoche\nun gallo cantó,\ny en su canto dijo:\n“Ya Cristo nació”.",171,2,4,159,"Naranjas y limas; Miren cuántas luces, Canto de Nochebuena",0,4,"o",2,0,-1,0,44,44,"8675","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8676",8,"Bueno el gallo que cantó,\ndando aviso al mundo entero\nque había nacido el Cordero,\ndiciendo: “Cristo nació”.\nSi éste de alegría cantó\npor los hombres, ¿que sería\nen ver que mero venía\nJesucristo al mundo, pues?\nY por eso digo que es\nnoche de mucha alegría.",171,2,4,159,"Estrofa suelta",18,10,"ia",0,0,-1,0,45,45,"8676","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8677",8,"Ábranse las puertas,\nrómpanse estos quicios,\nque a la media noche\nha nacido Cristo.",171,2,4,159,"Naranjas y limas",0,4,"io",-1,0,-1,0,45,45,"8677","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8678",8,"Oigan lo que pasa\ncon mucha alegría,\npues muy bien sabía\nque nació el Mesías.",171,2,4,159,"Naranjas y limas",0,4,"ia",-1,0,-1,0,45,45,"8678","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8679",8,"El infierno tiembla\ny el demonio llora\nal ver que ha nacido\nel rey de la gloria.",166,2,-1,159,"Canto de Noohebuena",0,4,"oa",-1,0,-1,0,45,45,"8679","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8681",8,"El Dios humanado\npor fin ya se ve;\nla madre es María,\nsu padre José.",166,2,-1,159,"Canto de Nochebuena",0,4,"e",77,0,-1,0,45,45,"8681","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8682",8,"En pobre portal\nel Dios humanado\nnace y nos redime\nde todo pecado.",166,2,-1,159,"Canto de Nochebuena",0,4,"ao",14,0,-1,0,45,45,"8682","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8683",8,"En un portalito\nnació el niño Dios,\na pagar las culpas\nque Adán cometió.",171,2,4,159,"Naranjas y limas",0,4,"o",-1,0,-1,0,45,45,"8683","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8684",8,"Ha nacido en un portal\nllenito de telarañas,\nentre la mula y el buey,\nel Redentor de las almas.",166,2,-1,159,"Canto de Nochebuena",0,4,"aa",-1,0,-1,0,45,45,"8684","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8685",8,"Esta es la choza\ndonde está el amor\ndel Dios divino,\nnuestro Redentor.",171,2,4,159,"Canto de Nochebuena",6,4,"o",72,0,-1,0,45,45,"8685","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8687",8,"En el portal de Belén\nhay muy grande claridad,\nporque ha nacido el Mesías\ny nos pondrá en libertad.",180,2,25,159,"En el portal de Belén",0,4,"a",16,0,-1,0,46,46,"8687","",0,"","","",32,0,0,[],"",""],["frenk_t4-n8688",8,"Un rústico techo\nabrigo le da;\npor cuna un pesebre,\npor templo un portal.",171,2,4,159,"Naranjas y limas",0,4,"a",-1,0,-1,0,46,46,"8688","",0,"nicomedes_obra2","","",2,0,0,[],"",""],["frenk_t4-n8689",8,"Humilde la cuna\nque Él escogió\ny su cabecita\nallí descansó.",168,2,11,159,"Estrofa suelta",6,4,"o",2,0,-1,0,46,46,"8689","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8690",8,"A la medianoche\nun rayo de luz\ny una hermosa estrella\nalumbró a Jesús.",171,2,4,159,"Naranjas y limas",0,4,"u",270,0,-1,0,46,46,"8690","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8691",8,"Al pobre pesebre\ndel niño Jesús\nestrellas del cielo\nle dan suave luz.",168,2,11,159,"Estrofa suelta",0,4,"u",109,0,-1,0,46,46,"8691","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8692",8,"En lecho de pajas\ndesnudito está\nquien ve las estrellas\na sus pies brillar.",166,2,-1,159,"Naranjas y limas",0,4,"a",-1,0,-1,0,46,46,"8692","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8693",8,"Si le vemos como niño,\nentre pajas junto a un buey,\nalgún día le veremos\nen la gloria como rey.",171,2,4,159,"Estrofa suelta",0,4,"e",133,0,-1,0,46,46,"8693","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8694",8,"En un portalito\nde cal y de arena\nnació Jesucristo\npor la Nochebuena.",171,2,4,159,"Naranjas y limas; Estrofa suelta",0,4,"ea",59,0,-1,0,46,46,"8694","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8695",8,"En un portalito\nde cal y basura\nnació Jesucristo\nuna noche oscura.",166,2,-1,159,"Naranjas y limas",0,4,"ua",17,0,-1,0,46,46,"8695","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8696",8,"El Niñito llora\ncon llantos agudos\nde frío que tiene\npor estar desnudo.",169,2,8,159,"Naranjas y limas",0,4,"uo",-1,0,-1,0,47,47,"8696","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8697",8,"El buey con el vaho\ncalentó al Señor,\nla muía se espanta\ncon su resplandor.",166,2,-1,159,"Canto de Nochebuena, Ésta es la",0,4,"o",72,0,-1,0,47,47,"8697","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8698",8,"Partió del campo muy leal\nun buey con mucho cariño;\npara calentar al Niño\nse fue inclinando al portal;\nél, queriéndolo vajear,\nse acometió presuroso,\nen ver a un Niño gracioso;\ncon el vaho que le echaba\na un niño Dios calentaba\nen un pesebre dichoso.",166,2,-1,159,"Estrofa suelta",18,10,"oo",160,0,-1,0,47,47,"8698","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8699",8,"La madre le acaricia,\nel padre mira en él,\ny los dos, extasiados,\ncontemplan aquel ser.",166,2,-1,159,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,47,47,"8699","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8700",8,"Durmiendo en cunita\nde pajas está,\nmas cuando despierta\nno se oye llorar.",168,2,11,159,"Estrofa suelta",0,4,"a",-1,0,-1,0,47,47,"8700","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8703",8,"En el portal de Belén\nhay estrella, sol y luna:\nla Virgen y San José\ny el niño Dios en la cuna.",166,2,-1,159,"Canto de Nochebuena",0,4,"ua",56,0,-1,0,47,47,"8703","",0,"","","",32,0,0,[],"",""],["frenk_t4-n8704",8,"La Virgen María,\ncuando Dios nació,\nhizo una corona\ny lo coronó.",171,2,4,159,"Naranjas y limas",0,4,"o",2,0,-1,0,47,47,"8704","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8705",8,"En el portal de Belén\nhay un espejo cuadrado,\ndonde se mira el Señor\ncon la Virgen a su lado.",166,2,-1,159,"Canto de Nochebuena",0,4,"ao",14,0,-1,0,48,48,"8705","",0,"","","",32,0,0,[],"",""],["frenk_t4-n8706",8,"Al hombre cuando ha nacido,\nque María lo ha parido\nsin tener ningún dolor,\nmiren que el gozo es cumplido\nel día de Nuestro Señor.",166,2,-1,159,"Canto de Nochebuena",7,5,"o",72,0,-1,0,48,48,"8706","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8707",8,"Ésta sí que es Nochebuena\nen que nació el niño Dios,\nésta sí que es Nochebuena,\nésta sí, que las otras no.",166,2,-1,159,"Canto de Nochebuena",0,4,"o",-1,0,-1,0,48,48,"8707","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8708",8,"Llegan los pastores\ncon grande alegría\na dar parabienes\nal niño Mesías.",171,2,4,159,"Naranjas y limas",0,4,"ia",-1,0,-1,0,48,48,"8708","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8709",8,"Los pastores daban saltos\ny bailaban de contento,\nal par que los angelitos\ntocaban los instrumentos.",166,2,-1,159,"Canto de Nochebuena, Estruja suelta",0,4,"eo",-1,0,-1,0,48,48,"8709","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",5,0,0,[],"",""],["frenk_t4-n8710",8,"Al brillar tan pura estrella\nhoy los Magos se apresuran\ny caminan con premura\nal fulgor de luz tan bella.",166,2,-1,159,"Canto de Nochebuena",5,4,"ea",6,0,-1,0,48,48,"8710","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8711",8,"La muía y el buey\nvinieron también\na adorar al Niño\nque nació en Belén.",169,2,8,159,"Naranjas y limas",0,4,"e",242,0,-1,0,48,48,"8711","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8712",8,"De alegría los pajaritos\ntodos cantan a la par,\nmirando que en el portal\nha nacido Jesucristo;\nvengan, pues, los pastorcitos\ny verán su eterna luz.\nLos reyes a ver a Jesús\ndesde el Oriente vinieron;\nlos tres aquí se vinieron,\nporque ya nació Jesús.",171,2,4,159,"Estrofa suelta",18,10,"u",-1,0,-1,0,48,48,"8712","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8713",8,"Los tres reyes del Oriente,\npara adorar al Mesías,\n¡qué viaje ¿an excelente\nhicieron en trece días!,\npasando las noches frías,\ndulces y tiempos penosos\nen los campos peligrosos\ndonde les faltó el aliento;\nahí llegaron con su intento\na Belén con grande gozo.",171,2,4,159,"Estrofa suelta",18,10,"oo",-1,0,-1,0,48,48,"8713","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8714",8,"¡Ay, Dios mío, poderoso\ndueño del universo!,\nquiero que me des paciencia\npara componerte este verso.",166,2,-1,160,"Estrofa suelta",0,4,"eo",624,0,-1,0,49,49,"8714","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8715",8,"¡Viva tu santa cruz,\nviva tu noble madero!\nAmado buen Jesús,\ntú eres Dios verdadero.",182,2,21,160,"Danza de los tecuanes",1,4,"eo",38,0,-1,0,49,49,"8715","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8716",8,"De los pueblos y ciudades\ntodos se van retirando;\ntú nos vas acompañando\ny nos libras de los males.",170,2,7,160,"Canto de Nochebuena",5,4,"ae",-1,0,-1,0,49,49,"8716","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8717",8,"Señor de Plateros,\nestrella brillante,\nválganos tu cruz,\ntu cuerpo y tu sangre.",178,2,10,160,"A nuestro Padre Jesús Nazareno",0,4,"ae",-1,0,-1,0,49,49,"8717","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8718",8,"En este santo templo\nunidos te adoramos\ny tus gracias, rendidos,\npor siempre proclamamos.",166,2,-1,160,"Danza de los tecuanes",0,4,"ao",116,0,-1,0,49,49,"8718","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8719",8,"Alábente en las ramas\nlos pájaros ufanos,\ny en el agua los peces\ncanten tu nombre santo.",178,2,10,160,"En este nuevo día",0,4,"ao",-1,0,-1,0,49,49,"8719","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8720",8,"Divino Jesús,\nes tu dulce nombre;\ncon tu eterna luz\nilumináis el orbe.",183,2,19,160,"Estrofa suelta",0,4,"oe",-1,0,-1,0,49,49,"8720","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8721",8,"Bienvenido seas,\nNiñito adorado,\nbienvenido seas,\nautor de lo creado.",181,2,15,160,"Saludo al Niño",1,4,"ao",14,0,-1,0,49,49,"8721","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8722",8,"Naces entre pajas\nsólo por mi amor;\nel mundo es hoy gloria,\ny no hay más dolor.",166,2,-1,160,"Canto de Nochebuena",0,4,"o",72,0,-1,0,50,50,"8722","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8724",8,"El incienso, oro y mirra\nque los Magos hoy te ofrecen\nson los dones que merecen\ntu grandeza y ley divina.",166,2,-1,160,"Canto de Nochebuena",5,4,"ia",-1,0,-1,0,50,50,"8724","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8725",8,"Niñito de Atocha,\nManuel de Jesús,\nreluciente antorcha,\nnuestro amparo y luz.",178,2,10,160,"El Niño de Atocha",0,4,"u",109,0,-1,0,50,50,"8725","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8726",8,"Eres hijo de María,\nNiño de mi corazón,\nde Atocha su advocación\ny del Fresnillo alegría.",166,2,-1,160,"Estrofa suelta.",11,4,"ia",0,0,-1,0,50,50,"8726","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8727",8,"Año de mil quinientos\ntreinta y nueve del pasado,\ncuando fuiste aparecido,\nmi Jesús sacramentado.",166,2,-1,160,"Al Señor de Sacromonte",0,4,"ao",14,0,-1,0,50,50,"8727","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8728",8,"Los ángeles en el cielo\nte alaban con grande fe,\ny nosotros en la tierra\nalabamos a José.",167,2,2,160,"Ave María",0,4,"e",77,0,-1,0,50,50,"8728","",0,"","","",10,0,0,[],"",""],["frenk_t4-n8729",8,"Los ángeles en el cielo\nte alaban con alegría,\ny nosotros en la tierra\nalabamos a María.",167,2,2,160,"Ave María",0,4,"ia",0,0,-1,0,50,50,"8729","",0,"","","",10,0,0,[],"",""],["frenk_t4-n8730",8,"Eres hija de Dios padre,\ndel santo Espíritu esposa,\ndel divino Verbo madre,\nreina del cielo gloriosa.",166,2,-1,160,"Estrofa suelta",1,4,"oa",63,0,-1,0,50,50,"8730","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8731",8,"Pastorcita virgen,\ngloria de Belén,\nde un príncipe madre\ny también de un rey.",168,2,11,160,"Estrofa suelta, Pastorcita Virgen",0,4,"e",-1,0,-1,0,50,50,"8731","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8732",8,"Eres pastorcita,\neres tan linda y tan bella,\nque al sol das ventaja,\na la luna, estrellas.",166,2,-1,160,"Pastorcita Virgen",0,4,"ea",-1,0,-1,0,51,51,"8732","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8733",8,"Bendita sea tu pureza\ny eternamente lo sea,\npues todo un Dios se recrea\nen tan graciosa belleza.",181,2,15,160,"Bendita sea tu pureza",11,4,"ea",-1,0,-1,0,51,51,"8733","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8734",8,"Virgen, celestial princesa,\nVirgen, sagrada María,\nyo te alabo en este día,\nsaludando a tu belleza.",170,2,7,160,"Caminatas",11,4,"ea",108,0,-1,0,51,51,"8734","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8736",8,"Eres, Virgen sacrosanta,\nclara luz que al mundo dio;\na los ángeles encantas\nahora que ya amaneció.",170,2,7,160,"Caminatas",0,4,"o",2,0,-1,0,51,51,"8736","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8737",8,"Eres relicario\nde ornamento lleno,\neres fuerte escudo,\ny en ti fe tenemos.",178,2,10,160,"A nuestro Padre Jesús Nazareno",0,4,"eo",-1,0,-1,0,51,51,"8737","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8738",8,"Malagueña venturosa,\nVirgen que oyes mis querellas,\neres tú la más piadosa,\nque te envidian las estrellas,\nVirgencita milagrosa.",167,2,2,160,"La Malagueña",7,5,"oa",63,0,-1,0,51,51,"8738","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8739",8,"Eres rosa de Castilla\nde las que la Virgen dio;\nescogida la más grande,\na Juan Diego le regaló.",171,2,4,160,"A la Virgen de Guadalupe",0,4,"o",2,0,-1,0,51,51,"8739","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8740",8,"Eres, Guadalupe,\nblanca flor de olivo;\ntú te apareciste\npor todos los siglos.",166,2,-1,160,"Estrofa suelta",0,4,"io",-1,0,-1,0,51,51,"8740","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8741",8,"¡Oh, Virgen Guadalupana,\npatrona de la nación!,\nhermosa perlita indiana,\nrecibo tu bendición.",169,2,8,160,"Estrofa suelta",1,4,"o",31,0,-1,0,51,51,"8741","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8742",8,"En este nuevo día\ngracias te tributamos,\n¡oh, Dios omnipotente,\nSeñor de lo creado!",178,2,10,160,"En este nuevo día’T",0,4,"ao",-1,0,-1,0,52,52,"8742","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8743",8,"Madre, Virgen de San Juan,\neres clara luz del día;\naquí están tus visitantes,\ndando gracias, madre mía.",166,2,-1,160,"Estrofa suelta",0,4,"ia",0,0,-1,0,52,52,"8743","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8744",8,"Tu milagro en la ocasión,\nVirgen de la Soledad,\nlo tengo en el corazón,\npues tenéis de mí piedad.",166,2,-1,160,"Estrofa suelta",1,4,"a",16,0,-1,0,52,52,"8744","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8745",8,"¡Oh, siempre virgen María!,\n¿qué aguinaldo daréis vos,\na quien mil veces os diga:\n“Virgen y madre de Dios”?",166,2,-1,160,"Estrofa suelta",0,4,"o",87,0,-1,0,52,52,"8745","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8747",8,"Duérmete, Jesús mío,\nduerme en mis brazos,\ny no llores, no llores\npor mis pecados;\nduérmete, duerme,\ny aunque llorar me sientas,\nno te despiertes.",184,2,14,160,"Por el valle de rosas",4,7,"ee",-1,0,-1,0,52,52,"8747","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8748",8,"Clavadas al cielo\ntus sienes divinas,\ncon barras de juncos\ny agudas espinas.",178,2,10,160,"A nuestro Padre Jesús Nazareno",0,4,"ia",243,0,-1,0,52,52,"8748","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8749",8,"En el nombre sea de Dios\ny de la Virgen María,\nque no hay hombre como Dios\nni mujer como María.",178,2,10,160,"El güerlto",1,4,"ia",-1,0,-1,0,52,52,"8749","",0,"","","",7,0,0,[],"",""],["frenk_t4-n8750",8,"Alabado sea, alabado sea,\nalabado, caminante,\nalabado sea, alabado sea,\nel Señor que hizo estrella tan brillante.",166,2,-1,160,"Estrella brillante",3,4,"ae",47,0,-1,0,52,52,"8750","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8751",8,"Y bendito y alabado\npor toda la eternidad,\ny así sea por los siglos\ny de los siglos, amén.",185,2,13,160,"Estrofa suelta",5,4,"e",-1,0,-1,0,53,53,"8751","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8752",8,"Venció al moro el cristiano,\na pesar de su altivez;\nque Dios sólo es soberano;\nrindámosle gloria y prez.",166,2,-1,160,"Los moros",1,4,"e",150,0,-1,0,53,53,"8752","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8753",8,"¡Dulce, dulce, dulce gloria,\ngloria, gloria de Belén!\n¡Padre, padre, padre, padre,\npadre también de un rey!",168,2,11,160,"Estrofa suelta",0,4,"e",-1,0,-1,0,53,53,"8753","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8754",8,"Él es nuestro amparo,\nbálsamo al enfermo,\nque cura las almas\ny alivia los cuerpos.",178,2,10,160,"A nuestro Padre Jesús Nazareno",0,4,"eo",-1,0,-1,0,53,53,"8754","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8755",8,"Sana los tullidos,\nda vista a los ciegos,\nes, pues, poderoso\ny de bondad lleno.",178,2,10,160,"A nuestro Padre Jesús Nazareno",0,4,"eo",-1,0,-1,0,53,53,"8755","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8756",8,"El Cristo de tu montaña\ndel cerro El Cubilete,\nconsuelo de los que sufren,\nadoración de la gente.",166,2,-1,160,"Camino de Guanajuato",0,4,"ee",-1,0,-1,0,53,53,"8756","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8757",8,"¡Bendito el instante\nque nos anunció\ntan santo prodigio,\nbendito sea Dios!",166,2,-1,160,"Cantando marchamos",0,4,"o",-1,0,-1,0,53,53,"8757","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8758",8,"¡Quién como Dios!\nAlaba su poder,\nsanto, santo, santo,\nseñor San Miguel.\n¡Quién como Dios!,\nNadie como Él.",168,2,11,160,"Estrofa suelta",9,6,"e",32,0,-1,0,53,53,"8758","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8759",8,"Alabar a Dios\nal grito de gracia,\ntoda la familia\ny gente de casa.",169,2,8,160,"Naranjas y limas",0,4,"aa",-1,0,-1,0,53,53,"8759","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8760",8,"Alabando a Dios\ncon mucha alegría,\na cantarle vengo\nal hijo de María.",171,2,4,160,"Naranjas y limas",0,4,"ia",0,0,-1,0,53,53,"8760","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8761",8,"Este precioso Niño\nyo me muero por Él;\nsus ojitos me encantan,\nsu boquita también.",166,2,-1,160,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,54,54,"8761","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8762",8,"Es tan precioso el Niño,\nque nunca podrá ser\nque su belleza copien\nel lápiz ni el pincel.",166,2,-1,160,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,54,54,"8762","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8763",8,"Dicen que su madre\nes como un lucero,\ncomo flor del campo,\ncomo lirio bello.",166,2,-1,160,"Canto de Nochebuena",0,4,"eo",-1,0,-1,0,54,54,"8763","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8764",8,"Esta que ves es María,\nclara luz, divina estrella;\nsi el que la hizo nació de ella,\ncontempla qué tal la haría.",166,2,-1,160,"Estrofa suelta",11,4,"ia",0,0,-1,0,54,54,"8764","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8766",8,"Si los ángeles volando\npasan de estrella en estrella,\nuna criatura tan bella\nno han de poder encontrar.",166,2,-1,160,"Canto de Nochebuena",5,4,"a",-1,0,-1,0,54,54,"8766","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8767",8,"¡Viva la Virgen María!,\n¡viva la nación indiana!\nQue se quede con nosotros\nla Virgen Guadalupana.",171,2,4,160,"A la Virgen de Guadalupe",0,4,"aa",4,0,-1,0,54,54,"8767","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8768",8,"¡Viva la Guadalupana!,\n¡viva su santo estandarte!,\n¡vivan los indios guerreros\nque vienen a venerarte!",166,2,-1,160,"A la Virgen de Guadalupe",0,4,"ae",8,0,-1,0,54,54,"8768","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8769",8,"Del cielo bajó\ntriunfante y ufana\ny a favorecernos\nla Guadalupana.",166,2,-1,160,"Estrofa suelta",0,4,"aa",4,0,-1,0,54,54,"8769","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8770",8,"¡Qué mañana tan hermosa\nel día en que se avistó\nesta muy fragante rosa\nluego que ya amaneció!",166,2,-1,160,"Alabanzas a la Virgen de San Juan de los Lagos",1,4,"o",2,0,-1,0,55,55,"8770","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8771",8,"En la ciudad de México\nhay una corona hermosa;\nen la mano derecha,\nuna estrella relumbrosa.",186,2,27,160,"Baile de la muñeca",0,4,"oa",63,0,-1,0,55,55,"8771","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8772",8,"De la bamba han venido\nnuevos pintores,\na adorar a la Virgen\nllena de flores.",169,2,8,160,"Estrofa suelta",6,4,"oe",5,0,-1,0,55,55,"8772","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8773",8,"De La Habana vinieron (Cecilia)\npintores, y no lo supe,\na pintar a la Virgen (Cecilia),\ny a la Virgen de Guadalupe.",187,2,12,160,"La Cecilia",3,4,"ue",271,0,-1,0,55,55,"8773","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8774",8,"De La Habana vinieron (Cecilia),\nvinieron pintores dos,\na pintar a la Virgen (Cecilia),\nCecilita, y al Niño Dios.",187,2,12,160,"La Cecilia",3,4,"o",87,0,-1,0,55,55,"8774","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8776",8,"De La Habana vinieron (Cecilia),\nvinieron pintores cuatro,\na pintar a la Virgen (Cecilia)\ny al Señor de Guanajuato.",187,2,12,160,"La Cecilia",3,4,"ao",-1,0,-1,0,55,55,"8776","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8777",8,"De La Habana vinieron (Cecilia),\nvinieron pintores cinco,\na pintar a la Virgen (Cecilia),\ny al Señor de Jalacingo.",187,2,12,160,"La Cecilia",3,4,"io",-1,0,-1,0,55,55,"8777","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8778",8,"De La Habana ha llegado\nun nuevo pintor,\na pintar a la Virgen\nde los Dolores.",171,2,4,160,"La bamba",6,4,"oe",-1,0,-1,0,55,55,"8778","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8779",8,"¡Ave María Purísima del Refugio,\nsin pecado original concebida!\n¡Bendita sea la hora\nque canta la aurora,\nel hombre la reza\ny el ángel la adora!",178,2,10,160,"La oración de la tarde",9,6,"oa",107,0,-1,0,55,55,"8779","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8780a",8,"Pase la escogida,\nla Niña dichosa,\nla flor de los campos,\nacá misteriosa.",166,2,-1,160,"Canto de Nochebuena",0,4,"oa",63,0,-1,0,55,55,"8780a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8781",8,"Repique en San Francisco,\nresponde Catedral:\n¡Qué limpia va bajando\nla Santa Trinidad!",187,2,12,160,"Estrofa suelta",0,4,"a",-1,0,-1,0,56,56,"8781","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8782",8,"Alabado y ensalzado\nsea el divino Sacramento,\nen quien Dios ocultamente\nes de las almas el sustento.",178,2,10,160,"Alabado viejo",0,4,"eo",94,0,-1,0,56,56,"8782","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8783",8,"Voy a ver a mi güerito\ncon su padre y con su madre.\n¡Ay qué primor!,\n¡ay qué bonito!,\n¡ay qué güerito\nestá mi Señor!",166,2,-1,160,"Estrofa suelta",9,6,"o",72,0,-1,0,56,56,"8783","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8784",8,"¡Gracias a Dios!,\n¡gracias a Dios!,\ngracias le demos\na la Madre de Dios.",178,2,10,160,"En este nuevo día",3,4,"o",-1,0,-1,0,56,56,"8784","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8785",8,"Ya viene el alba,\nya viene el día,\ndaremos gracias,\nAve María.",178,2,10,160,"Estrofa suelta",6,4,"ia",0,0,-1,0,56,56,"8785","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8786",8,"Las gracias le demos\na la Santa Cruz,\nmadero sagrado,\ncama de Jesús.",181,2,15,160,"A la Santa Cruz",0,4,"u",270,0,-1,0,56,56,"8786","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8788",8,"Si San Juan supiera\ncuando era su día,\nbailaran las piedras\nde pura alegría.",176,2,3,160,"Estrofa suelta",0,4,"ia",0,0,-1,0,56,56,"8788","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8790",8,"Aquí venimos caminando\ny al toque de la campana,\ny [a] conocerte venimos,\nCristo, Rey de la montaña.",186,2,27,161,"Salutación",3,4,"aa",-1,0,-1,0,58,58,"8790","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8791",8,"Venimos a adorarte\nporque eres rey eterno,\ny con tu gracia y ley\nvencemos al averno.",182,2,21,161,"Danza de los tecuanes",0,4,"eo",225,0,-1,0,58,58,"8791","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8792",8,"Virgen agraciada,\ndivina María,\nvenimos gustosas\ncon grande alegría.",170,2,7,161,"Caminatas",0,4,"ia",0,0,-1,0,58,58,"8792","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8793",8,"Virgen agraciada,\ndivina señora,\nprenda de mi amor,\nvengo a tu santuario:",170,2,7,161,"Caminatas",5,4,"ao",-1,0,-1,0,58,58,"8793","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8794",8,"Me habéis conquistado,\nmi madre y señora,\nprenda de mi amor,\nvengo a tu santuario.",170,2,7,161,"Caminatas",5,4,"ao",-1,0,-1,0,58,58,"8794","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8795",8,"De nuevo aquí nos tienes,\npurísima doncella,\nmás que la luna bella,\npostrados a tus pies.",178,2,10,161,"De nuevo aquí nos tienes, Canto de Nochebuena",5,4,"e",-1,0,-1,0,58,58,"8795","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8796",8,"Por eso con el vergüenza\nte cantamos la canción,\nofreciéndote un suspiro\nde éste nuestro corazón.",176,2,3,161,"Felicitación indígena",0,4,"o",31,0,-1,0,58,58,"8796","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8797",8,"Te vengo a adorar\ncon bastante anhelo,\nque está en el portal\nel rey de los cielos,",171,2,4,161,"Naranjas y limas",0,4,"eo",-1,0,-1,0,58,58,"8797","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8798",8,"¿Dónde estás, recién nacido?,\n¿dónde paras, rey del cielo?\nTe buscamos con anhelo,\na besar tus pies venimos.",166,2,-1,161,"Canto de Nochebuena",5,4,"io",-1,0,-1,0,59,59,"8798","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8799",8,"No llores, Jesús, no llores,\nque nos vas a hacer llorar,\nque los niños de esta casa\nte queremos consolar.",168,2,11,161,"Vamos, niños, al sagrario",0,4,"a",21,0,-1,0,59,59,"8799","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8800a",8,"Ya se acerca el buey,\ntambién la mulita;\nel frío que hoy tienes\ncon su vaho te quita.",168,2,11,161,"Estrofa suelta",0,4,"ia",50,0,-1,0,59,59,"8800a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8801",8,"A la rorro, rorro, niño,\na la rorro, rorro, ya,\nya se durmió el chiquitito,\nya se durmió el Redentor.",188,2,24,161,"Canto de Nochebuena",5,4,"o",-1,0,-1,0,59,59,"8801","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8802",8,"Yo tengo licencia\ny por eso canto,\nvine de la iglesia,\nme dieron los cantos.",171,2,4,161,"Naranjas y limas",0,4,"ao",-1,0,-1,0,59,59,"8802","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8804",8,"Ábranme la puerta,\nsi quieren que cante;\nal niño Jesús\ntraigo por delante.",171,2,4,161,"Naranjas y limas",0,4,"ae",47,0,-1,0,59,59,"8804","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8805",8,"Salgan acá fuera,\nverán qué primor,\nque a la medianoche\nha nacido el sol.",171,2,4,161,"Naranjas y limas",0,4,"o",-1,0,-1,0,59,59,"8805","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8806",8,"Levántate, amigo,\ny enciende tu luz,\nmira lo que le anda\nal Niño Jesús.",166,2,-1,161,"Naranjas y limas",0,4,"u",270,0,-1,0,60,60,"8806","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8807",8,"Vamos, niños, al sagrario,\nque Jesús llorando está;\npero viendo tantos niños,\n¡qué contento se pondrá!",166,2,-1,161,"Vamos, niños, al sagrario",0,4,"a",9,0,-1,0,60,60,"8807","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8808",8,"Venid, adoremos\nla sagrada imagen\nde Jesús Nazareno,\nque es nuestro consuelo.",178,2,10,161,"A nuestro Padre Jesús Nazareno",5,4,"eo",-1,0,-1,0,60,60,"8808","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8809",8,"Marchemos cantando\ncon gozo y fervor,\npara ir saludando\nlas glorias de Dios.",166,2,-1,161,"Marchemos cantando",0,4,"o",-1,0,-1,0,60,60,"8809","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8810",8,"Andemos aprisa,\nno nos detengamos,\nque ya del santuario\nlas señas miramos.",170,2,7,161,"Caminatas",0,4,"ao",-1,0,-1,0,60,60,"8810","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8811",8,"Venid y vamos todas\ncon flores a María,\ncon flores a porfía,\nque madre nuestra es.",178,2,10,161,"Estrofa suelta",5,4,"e",-1,0,-1,0,60,60,"8811","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8812",8,"Vamos caminando\ncon gusto y contento,\na ver a la Virgen\nen su santo templo.",170,2,7,161,"Caminatas",0,4,"eo",-1,0,-1,0,60,60,"8812","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8813",8,"Ésta es la Señora\nque el ángel nos dijo,\nque alumbró un Infante\ncon gran regocijo.",170,2,7,161,"Ésta es la Señora",0,4,"io",122,0,-1,0,60,60,"8813","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8814",8,"Compañeros, corramos todos,\npa que puédamos llegar\na colocar a la Virgen\nen su venerable altar.",171,2,4,161,"A la Virgen de Guadalupe",0,4,"a",21,0,-1,0,60,60,"8814","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8815",8,"Ya llegamos, compañeros,\ntodos con velas y flores;\nvenimos aquí a adorar\nal divino Sacramento,\nmanifiesto en el altar.",186,2,27,161,"La cruz",7,5,"a",21,0,-1,0,60,60,"8815","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8816",8,"Ya llegamos, compañeros,\ntodos juntos en camino,\nvamos a formar la cruz,\npasión del Divino Rostro,\nque nosotros veneramos.",186,2,27,161,"La cruz",7,5,"ao",-1,0,-1,0,61,61,"8816","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8817",8,"¡Qué paloma tan dichosa\nes el vientre de María!,\ny de José ¡qué alegría\nque logró ser venturoso,\nser de la Virgen esposo\ny padre del Redentor,\nque vino por nuestró amor\na damos laureles y palmas!\nVámonos con gloria, mi alma,\npara la iglesia mayor.",171,2,4,161,"Estrofa suelta",18,10,"o",72,0,-1,0,61,61,"8817","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8818a",8,"Ariles y más ariles,\nariles, llévame a ver\na la reina de los cielos,\nque la quiero conocer.",171,2,4,161,"El Balajú",0,4,"e",20,0,-1,0,61,61,"8818a","",0,"","","",24,0,0,[],"",""],["frenk_t4-n8818b",8,"Un morena me dijo\nque la llevara yo a ver\na la reina de los cielos,\nque la quería conocer,\ny después de haberla visto,\nque la volviera a traer.",171,2,4,161,"La morena; La Petenera",9,6,"e",20,0,-1,0,61,61,"8818b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8819",8,"Soledad, llévame a vere\na la reina de los cielos,\nque ésa es todo mi querere,\ny después de haberla visto,\nme volverás a traere.",166,2,-1,161,"La Petenera",7,5,"ee",115,0,-1,0,61,61,"8819","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8820",8,"Pastorcitas somos,\ndel cerro bajamos\na comer los frutos\nde los verdes ramos.",166,2,-1,161,"Caminatas",0,4,"ao",116,0,-1,0,61,61,"8820","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8821",8,"—Indito, ¿de adonde vienes?\n—Del cerro del Tepeyac;\nfuimos a ver a la Virgen,\naquí la traemos ya.",171,2,4,161,"A la Virgen de Guadalupe",0,4,"a",-1,0,-1,0,61,61,"8821","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8822",8,"Voy para Belén,\nsiguiendo una luz,\na ver a la Virgen\ny al Niño Jesús.",170,2,7,161,"Canto de Nochebuena",0,4,"u",270,0,-1,0,61,61,"8822","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8823",8,"A José y María\nlos vengo a adorar\ny esta melodía\nles vengo a cantar.",171,2,4,161,"Naranjas y limas",1,4,"a",21,0,-1,0,62,62,"8823","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8824",8,"Pastores, pastores,\nha llegado ya\nla grata noticia\nque os sorprenderá.",171,2,4,161,"Canto de Nochebuena",0,4,"a",9,0,-1,0,62,62,"8824","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8825",8,"En Belén a medianoche\nun niñito nacerá;\nalegraos, pastorcitos,\nque el que nace Dios será.",171,2,4,161,"Estrofa suelta",0,4,"a",9,0,-1,0,62,62,"8825","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8826",8,"Albricias, pastores,\nhabéis de saber\nque toda la gloria\nse vino a Belén.",166,2,-1,161,"Estrofa suelta",0,4,"e",-1,0,-1,0,62,62,"8826","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8827",8,"Albricias, pastores,\nya parió María\nun niño tan lindo\ncual la luz del día.",166,2,-1,161,"Canto de Nochebuena",0,4,"ia",0,0,-1,0,62,62,"8827","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8828",8,"¿Quién de estos contornos,\ncon noticia tal,\nse queda durmiendo\nsin ir al portal?",166,2,-1,161,"Canto de Nochebuena",0,4,"a",1,0,-1,0,62,62,"8828","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8829",8,"Vayan para Unión,\ntoda la familia;\na que el Niño nazca,\nno tengan envidia.",169,2,8,161,"Naranjas y limas",0,4,"ia",-1,0,-1,0,62,62,"8829","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8830",8,"Venid, pastorcillos,\ndejad vuestros campos,\nque a Belén un niño\ndel cielo ha bajado.",166,2,-1,161,"Canto de Nochebuena",0,4,"ao",-1,0,-1,0,62,62,"8830","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8831",8,"A Belén, pastorcillos, marchemos,\nBato y Gila, adorad al Creador,\ny con canto sonoro y hermoso\nlevantemos hasta Él nuestra voz.",171,2,4,161,"Estrofa suelta",3,4,"o",-1,0,-1,0,62,62,"8831","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8832",8,"Pastores, a Belén\nvamos con alegría,\na Jesús, José y María.\n¡A Belén, a Belén,\na ver a nuestro rey,\na Belén, pastores!",166,2,-1,161,"Estrofa suelta",9,6,"oe",-1,0,-1,0,62,62,"8832","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8833",8,"Ya salió el lucero,\nya viene brillando;\nlevanten, pastoras,\nvamos caminando.",170,2,7,161,"Caminatas",0,4,"ao",33,0,-1,0,63,63,"8833","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8834",8,"Aguas cristalinas,\n¡cómo están vertiendo\nde las altas peñas\nque vamos subiendo!",181,2,15,161,"Canto de Nochebuena",0,4,"eo",52,0,-1,0,63,63,"8834","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8835",8,"¡Qué cerros tan altos!\nParece que ya\nllegamos felices\ny sin novedad.",181,2,15,161,"Canto de Nochebuena",0,4,"a",-1,0,-1,0,63,63,"8835","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8836",8,"¡Qué cerros tan altos!,\nlindor nos parece;\njunten al ganado,\nporque ya amanece.",181,2,15,161,"Canto de Nochebuena",0,4,"ee",64,0,-1,0,63,63,"8836","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8837",8,"Ándale, Batito,\nchíflale al ganado:\nvamos a dar agua\nal río Colorado.",166,2,-1,161,"Canto de Nochebuena",0,4,"ao",14,0,-1,0,63,63,"8837","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8838",8,"¡Qué bonitas flores\nhay por este cerro!\nCórtalas, Gilita,\npara tu sombrero.",181,2,15,161,"Canto de Nochebuena",0,4,"eo",-1,0,-1,0,63,63,"8838","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8839",8,"Camina, Gilita,\nque vendrás cansada;\npor aquellos montes\nharemos posada.",166,2,-1,161,"Canto de Nochebuena",0,4,"aa",49,0,-1,0,63,63,"8839","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8841",8,"¿No veis esa estrella\nque luce en los cielos,\ny a Belén os guían\nsus dulces destellos?",166,2,-1,161,"Canto de Nochebuena",0,4,"eo",-1,0,-1,0,63,63,"8841","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8842",8,"Caminen, pastores (¡caramba!),\nque ahí viene Miguel,\ncon la espada en la mano (¡caramba!)\npara Lucifer (¡ay, caramba!).",168,2,11,161,"Canto de Nochebuena",3,4,"aa",-1,0,-1,0,63,63,"8842","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8843",8,"Caminen, pastores,\nvamos a Belén,\na ver a la Virgen,\nal Niño también.",181,2,15,161,"Canto de Nochebuena, Naranjas y limas; El pájaro cú",0,4,"e",242,0,-1,0,64,64,"8843","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8844",8,"Vamos, pastorcitos,\nvamos caminando,\na ver a la Virgen\nque estamos adorando.",170,2,7,161,"Caminatas",0,4,"ao",33,0,-1,0,64,64,"8844","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8845",8,"Vamos, pastores, vamos,\nvamos a Belén,\na ver en aquel Niño\nla gloria del Edén.",166,2,-1,161,"Canto de Nochebuena",0,4,"e",242,0,-1,0,64,64,"8845","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8846",8,"Vamos, pastores,\nvamos a Belén,\na adorar al Niño\nque acaba de nacer.",168,2,11,161,"Estrofa suelta",3,4,"e",-1,0,-1,0,64,64,"8846","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8847a",8,"Vámonos, pastores,\nvamos a Belén,\nque ha nacido el Niño\npara nuestro bien.",183,2,19,161,"Estrofa suelta",0,4,"e",242,0,-1,0,64,64,"8847a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8848",8,"Miren cuántas luces,\ncuántos resplandores;\nsin duda es Belén:\n¡qué gloria, pastores!",166,2,-1,161,"Canto de Nochebuena",0,4,"oe",5,0,-1,0,64,64,"8848","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8849",8,"Daos prisa, pastores,\nque ya urge verlo,\ndicen que es Dios Niño,\nun niño muy bello.",166,2,-1,161,"Canto de Nochebuena",6,4,"eo",-1,0,-1,0,64,64,"8849","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8850",8,"Vamos, pastores, vamos a ver\nal Dios humanado, que quiso nacer\nen pobres pajas, en campo verde,\nen un pesebre junto a Belén.",170,2,7,161,"Canto de Nochebuena",3,4,"e",-1,0,-1,0,64,64,"8850","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8852",8,"Pastores todos, con alegría,\npues ya la noche parece día;\npastores todos, sigan cantando,\nya al Nacimiento vamos llegando.",166,2,-1,161,"Canto de Nochebuena",3,4,"ao",33,0,-1,0,65,65,"8852","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8853",8,"Pastores, venid, venid,\nveréis lo que no habéis visto:\nen el portal de Belén\nel nacimiento de Cristo.",166,2,-1,161,"Canto de Nochebuena; Estrofa suelta",0,4,"io",273,0,-1,0,65,65,"8853","",0,"rm_t4, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["frenk_t4-n8854",8,"Pastores, venid,\npastores, llegad,\na adorar al Niño\nque ha nacido ya.",166,2,-1,161,"Canto de Nochebuena",0,4,"a",-1,0,-1,0,65,65,"8854","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8855a",8,"Venid, pastorcitos,\nvenid, venid, venid,\nvenid a adorar,\nvenid, venid.",169,2,8,161,"Estrofa suelta",3,4,"i",-1,0,-1,0,65,65,"8855a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8856",8,"Venid, pastorcillos,\nvenid a adorar\nal rey de los cielos,\nque ha nacido ya.",171,2,4,161,"Naranjas y limas; Estrofa suelta",0,4,"a",-1,0,-1,0,65,65,"8856","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8857",8,"Venid, pastorcillos,\nvenid a Belén,\nvenid, que ha nacido\nel Dios de Israel.",171,2,4,161,"Estrofa suelta",0,4,"e",-1,0,-1,0,65,65,"8857","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8858",8,"Venir, pastorcitos,\nvenir, acudir,\na ver al Infante,\nque ha nacido ya.",183,2,19,161,"Estrofa suelta",5,4,"a",-1,0,-1,0,65,65,"8858","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8859",8,"Gloria, gloria, gloria a Dios,\ny en todo el llano, paz.\nVenid, venid, pastores,\ncantemos con fervor,\nque los campos se cubren\nde gloria y esplendor.",166,2,-1,161,"Canto de Nochebuena",9,6,"o",72,0,-1,0,65,65,"8859","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8860",8,"Bailad, pastorcitos,\nbailad en Belén,\nque Dios ha nacido\npara nuestro bien.",166,2,-1,161,"Canto de Nochebuena",0,4,"e",242,0,-1,0,66,66,"8860","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8861",8,"Entren, pastorcitas,\néste es el lugar,\néste es el santuario\ndonde han de bailar.",170,2,7,161,"Caminatas",0,4,"a",21,0,-1,0,66,66,"8861","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8862",8,"Almas amantes, tiernas,\nlas que los ven venir,\nvenid a Nazaret,\nvenid, almas, venid.",171,2,4,161,"Canto de Nochebuena",0,4,"i",-1,0,-1,0,66,66,"8862","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8863",8,"Pastores, para el portal,\na ver al recién nacido,\nque está temblando de frío,\nsin tener ningún abrigo.",170,2,7,161,"Canto de Nochebuena",0,4,"io",-1,0,-1,0,66,66,"8863","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8864",8,"Ya los Magos han llegado\ncon sus dones al portal;\nvamos, vamos, pastorcillos,\naquel acto a presenciar.",166,2,-1,161,"Canto de Nochebuena",0,4,"a",-1,0,-1,0,66,66,"8864","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8866",8,"Esta noche es Nochebuena,\nnoche de mucha alegría,\nnoche que nació Jesús,\nnoche que parió María,\ny por eso digo que es\nnoche de mucha alegría.",171,2,4,161,"Estrofa suelta",9,6,"ia",0,0,-1,0,66,66,"8866","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8867",8,"¡Ave María, qué contento,\nqué contento y qué alegría\ntenemos en este día\nen tan luminoso afrento!\nque hasta la región del viento\ncelebra en su jerarquía,\ny nosotros con alegría\ncantemos luz y canciones\nque alegran los corazones,\nporque ya parió María.",171,2,4,161,"Estrofa suelta",18,10,"ia",0,0,-1,0,66,66,"8867","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8868",8,"¡Ah, qué hermosa flor\nviene reventando!\nLa reina del cielo\nque están adorando.",170,2,7,161,"Caminatas",0,4,"ao",33,0,-1,0,66,66,"8868","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8869",8,"Salgan acá fuera,\nverán qué bonito,\nverán los pastores\ncon sus borreguitos.",171,2,4,161,"Naranjas y limas",0,4,"io",-1,0,-1,0,66,66,"8869","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8870",8,"Humildes peregrinos,\nJesús, María y José,\nmi alma os doy, con,ella\nmi corazón también.",168,2,11,162,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,67,67,"8870","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8871",8,"Recibe, Dios mío,\nnuestros corazones,\nnuestras tres potencias,\nsentidos y dones.",181,2,15,162,"Estrofa suelta",0,4,"oe",34,0,-1,0,67,67,"8871","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8872",8,"De mi corazón quisiera\nhaceros una carroza,\npa que en ella caminaran\nel pastor José y su esposa.",168,2,11,162,"Estrofa suelta",0,4,"oa",63,0,-1,0,67,67,"8872","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8873",8,"Niño, no podemos\npagar tus favores,\npero te ofrecemos\nnuestros corazones.",181,2,15,162,"Saludo al Niño",0,4,"oe",-1,0,-1,0,67,67,"8873","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8874",8,"Yo te vengo a regalar\neste par de borreguitos,\npara que juegues con ellos\ncuando ya estés grandecito.",170,2,7,162,"Canto de Nochebuena",0,4,"io",-1,0,-1,0,67,67,"8874","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8875",8,"A ofrecerte venimos\nflores del bajo suelo;\ncon cuánto amor y anhelo,\nSeñora, tú lo ves.",178,2,10,162,"De nuevo aquí nos tienes",5,4,"e",-1,0,-1,0,67,67,"8875","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8876",8,"Ahora que gustosos vienen\nlos límpidos corazones,\nacepta nuestra corona\nde sonrosados botones.",166,2,-1,162,"Las mañanitas",0,4,"oe",34,0,-1,0,67,67,"8876","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8877",8,"Esta noche con la luna\ny mañana con el sol,\ncogeremos pajarita\npara la iglesia mayor.",180,2,25,162,"Estrofa suelta",0,4,"o",-1,0,-1,0,67,67,"8877","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8878",8,"Por Santiago sale el sol,\npor San Francisco se mete;\ngüerito San Sebastián,\náhi te traen tu taburete.",178,2,10,162,"El güerito",3,4,"ee",285,0,-1,0,68,68,"8878","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8879",8,"Te iba yo a decir un verso\napretado de cortesía,\npero me ha dado vergüenza,\nde ver tanta señoría.",190,2,20,162,"Canción a un santo",0,4,"ia",0,0,-1,0,68,68,"8879","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8880",8,"Niñito de Atocha,\nya vine de viaje,\ny aquí te traigo\ntu varita y tu guaje.",178,2,10,162,"El Niño de Atocha",0,4,"ae",231,0,-1,0,68,68,"8880","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8881",8,"Y por eso,\ncon tu permiso,\ntata niñito,\nvoy a cantar.",176,2,3,162,"Canción de las canacuas",3,4,"a",-1,0,-1,0,68,68,"8881","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8882",8,"Traemos dentro del pecho\nhenchido el corazón,\npara darte a ti las gracias\npor esta humilde canción.",169,2,8,162,"Estrofa suelta",0,4,"o",31,0,-1,0,68,68,"8882","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8883",8,"Como que soy mexicana,\npor eso vengo muy de mañana,\na cortar flores de las más lindas\npara la Virgen Guadalupana.",171,2,4,162,"A la Virgen de Guadalupe",3,4,"aa",4,0,-1,0,68,68,"8883","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8884",8,"Soy pichichagua del alma mía,\nsoy pichichagua del otro día;\naquí le traigo estas flores\na la Virgen María.",171,2,4,162,"A la Virgen de Guadalupe",3,4,"ia",0,0,-1,0,68,68,"8884","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8885",8,"Los pastores y zagalas\ncaminan hacia el portal,\nllevando llenos de fruta\nel cesto y el delantal.",166,2,-1,162,"Canto de Nochebuena; Estrofa suelta",0,4,"a",1,0,-1,0,68,68,"8885","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8886",8,"Los pastores de Belén\ntodos juntos van por leña,\npara calentar al Niño\nque nació en la Nochebuena.",166,2,-1,162,"Canto de Nochebuena; Estrofa suelta",0,4,"ea",-1,0,-1,0,68,68,"8886","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8887",8,"Del Oriente somos\ntodos los pastores,\ny traemos al Niño\ncanastas de flores.",170,2,7,162,"Ésta es la Señora",0,4,"oe",5,0,-1,0,68,68,"8887","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8888",8,"Pastorcillos somos,\ndel cerro bajamos,\ny traemos al Niño\ndulces de los ramos.",170,2,7,162,"Ésta es la Señora",0,4,"ao",116,0,-1,0,69,69,"8888","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8889",8,"Todos le llevan al Niño,\nyo también le llevaré\nuna torta de manteca\ny un jarro de blanca miel.",166,2,-1,162,"Canto de Nochebuena",0,4,"e",-1,0,-1,0,69,69,"8889","",0,"rm_t4, palau_cantares, lafuente_madrid","","",9,0,0,[],"",""],["frenk_t4-n8890",8,"Todos le llevan al Niño,\nyo no tengo qué llevarle;\nlas alas del corazón\nque le sirvan de pañales.",166,2,-1,162,"Canto de Nochebuena",0,4,"ae",-1,0,-1,0,69,69,"8890","",0,"rm_t4, palau_cantares, lafuente_madrid","","",9,0,0,[],"",""],["frenk_t4-n8891",8,"Nada tengo de contado,\npor mi pobreza importuna,\nni joya tengo ninguna\nque darte en esta ocasión,\nsi ya no es mi corazón,\nque te ofrezco para cuna.",166,2,-1,162,"Canto de Nochebuena",9,6,"ua",56,0,-1,0,69,69,"8891","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8892",8,"—Yo le llevo al Niño\nun blanco cordero.\n—Y yo, en una jaula,\nle llevo un jilguero.",166,2,-1,162,"Canto de Nochebuena",0,4,"eo",38,0,-1,0,69,69,"8892","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8893",8,"Mi mulita se perdió,\ny la lloro con razón,\nporque en ella le llevaba\nal Niño su colación.",168,2,11,162,"Canto de Nochebuena",0,4,"o",31,0,-1,0,69,69,"8893","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8894",8,"Alabando a Dios\ncon mucha alegría,\ny la rama le dejo\na José y María.",171,2,4,162,"Naranjas y limas",0,4,"ia",0,0,-1,0,69,69,"8894","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8895",8,"Los tres Reyes Santos\nal portal llegaron,\nrindieron coronas\ny se arrodillaron.",166,2,-1,162,"Estrofa suelta",0,4,"ao",41,0,-1,0,69,69,"8895","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8896",8,"Los tres Reyes Magos\nvienen del Oriente,\na darle homenaje\nal Omnipotente.",170,2,7,162,"Ésta es la Señora, Canto de Nochebuena",0,4,"ee",15,0,-1,0,69,69,"8896","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8897",8,"Los tres Reyes Magos\nvienen del Oriente\ny le traen al Niño\nsu leche caliente.",171,2,4,162,"Naranjas y limas",0,4,"ee",15,0,-1,0,69,69,"8897","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8898",8,"Los tres Reyes Magos\nvienen de La Habana\ny al Niño le traen\nsu linda manzana.",171,2,4,162,"Naranjas y limas",0,4,"aa",4,0,-1,0,70,70,"8898","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8899",8,"Los tres Reyes Magos\nvienen de Agua Dulce\ny al Niño le traen\nsu bolsa de dulces.",171,2,4,162,"Naranjas y limas",0,4,"ue",-1,0,-1,0,70,70,"8899","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8900",8,"Los tres Reyes Magos\nvienen de Tampico\ny al Niño le traen\nsu pala y su pico.",171,2,4,162,"Naranjas y limas",0,4,"io",141,0,-1,0,70,70,"8900","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8901",8,"¡Ay!, mi caballo tordillo,\nvámonos pronto a bañar,\npara quedar bendecidos\nen este día de San Juan.",166,2,-1,162,"Estrofa suelta",0,4,"a",-1,0,-1,0,70,70,"8901","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8902",8,"Señor, danos tu ayuda,\npara vencer con ventaja\na todos los que nos quieran\ncausar alguna desgracia.",177,2,18,163,"Estrofa suelta",0,4,"aa",-1,0,-1,0,71,71,"8902","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8903",8,"Válganos, Jesús,\ntu sacro misterio,\ntu vida y pasión,\nJesús Nazareno.",178,2,10,163,"A nuestro Padre Jesús Nazareno",0,4,"eo",-1,0,-1,0,71,71,"8903","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8905",8,"Ya llegamos, compañeros,\ntodos juntos como hermanos;\nMadre mía de Guadalupe,\néchanos tu bendición\na tus hijos mexicanos.",186,2,27,163,"La cruz",7,5,"ao",318,0,-1,0,71,71,"8905","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8906",8,"Ya llegamos, compañeros,\ntodos juntos como amigos;\nSanto Niñito de Atocha,\néchanos tu bendición\ncon tus sagradas manitas.",186,2,27,163,"La cruz",7,5,"ia",-1,0,-1,0,71,71,"8906","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8907",8,"Ya llegamos, compañeros;\nMadre mía de los Remedios,\néchanos tu bendición\ncon tus sagradas manitas.",186,2,27,163,"La cruz",5,4,"ia",-1,0,-1,0,71,71,"8907","",0,"","","",6,0,0,[],"",""],["frenk_t4-n8908",8,"Virgencita de San Juan,\néchanos tu bendición;\nvenimos desde otras tierras\na rendirte adoración.",166,2,-1,163,"Alabanzas a la Virgen de San Juan de los Lagos",0,4,"o",31,0,-1,0,71,71,"8908","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8909",8,"Venimos de la Huasteca\nhasta ti en peregrinación;\nla gente también allá peca\ny quiere implorar tu perdón.",169,2,8,163,"Estrofa suelta",1,4,"o",31,0,-1,0,71,71,"8909","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8911",8,"Santo Dios, santo inmortal,\nsanto fuerte y adorado,\nlíbranos de todo mal,\nmi Jesús sacramentado.",166,2,-1,163,"Estrofa suelta",1,4,"ao",14,0,-1,0,72,72,"8911","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8912",8,"Por tus gracias, soberana,\npor tu infinita piedad,\nsalva, reina soberana,\nVirgen de la Soledad,\na la nación mexicana.",166,2,-1,163,"Estrofa suelta",7,5,"aa",4,0,-1,0,72,72,"8912","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8913",8,"Patroncita mexicana,\nhoy traigo otra petición:\nhaz que mi patria esté sana\nde la maligna ambición.",169,2,8,163,"Estrofa suelta",1,4,"o",31,0,-1,0,72,72,"8913","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8914",8,"Y eres, Guadalupe,\nreina de las Indias;\nbendice este reino\ncon tus manos lindas.",166,2,-1,163,"Canción de los indios a la Guadalupana",0,4,"ia",-1,0,-1,0,72,72,"8914","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8916",8,"¡Ay, Madre de los Dolores!,\ntú me has de acompañar;\nvoy a traerte tus flores\npara venirte a rezar;\ncuídame en mi canoíta,\nque no me vaya yo a ahogar.",166,2,-1,163,"Los paseos de Santa Anita",9,6,"a",21,0,-1,0,72,72,"8916","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8917",8,"A ti, celestial princesa,\nVirgen, sagrada María,\nyo te agradezco en este día\nalma, vida y corazón;\nmírame con compasión,\n¡no me dejes, madre mía!",181,2,15,163,"‘‘Bendita sea tu pureza",9,6,"ia",0,0,-1,0,72,72,"8917","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8918",8,"Cuando goces placeres y encantos\nen el cielo de tanta ventura,\nnunca olvides jamás, Virgen pura,\nnunca, nunca, te olvides de mí.",166,2,-1,163,"Estrofa suelta",3,4,"i",-1,0,-1,0,72,72,"8918","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8919",8,"Vamos siguiendo los pasos\nen esta larga estación;\nrecíbenos en tus brazos,\nSeñor de la Expiación.",186,2,27,163,"Estrofa suelta",1,4,"o",31,0,-1,0,72,72,"8919","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8920",8,"Estrella brillante,\nluz del peregrino,\nestrella, ilumina\nhoy este camino.",166,2,-1,163,"Estrella brillante",0,4,"io",199,0,-1,0,73,73,"8920","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8921",8,"Tú has de ser nuestra madrina\nen el juicio universal;\nóyenos, graciosa Niña,\nen tu reino celestial.",170,2,7,163,"Caminatas",0,4,"a",1,0,-1,0,73,73,"8921","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8922",8,"¡Oh, Señor del cielo,\npor tu sacra imagen,\nhumildes pedimos\nnos mandes consuelo.",178,2,10,163,"A nuestro Padre Jesús Nazareno",5,4,"eo",10,0,-1,0,73,73,"8922","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8923",8,"Yo te amo, Jesús,\ny te quiero adorar;\nte pido que vengas\nmi sueño a velar.",168,2,11,163,"Estrofa suelta",0,4,"a",21,0,-1,0,73,73,"8923","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8924",8,"Niño chiquito y hermoso,\ntriunfante glorioso,\nmerced te pido,\ncomo rey poderoso,\nque la pena que tengo\nme la vuelvas gozo.",172,2,23,163,"Estrofa suelta",9,6,"oo",156,0,-1,0,73,73,"8924","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8925",8,"Mi amado Jesús,\nhijo de María,\nduélete, Señor,\ndel que en ti confía,",178,2,10,163,"A nuestro Padre Jesús Nazareno",0,4,"ia",0,0,-1,0,73,73,"8925","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8926",8,"Madre mía de Guadalupe,\nme encomiendo a ti, Señora,\nque me voy en el enganche\nal estado de Sonora.",166,2,-1,163,"La canción del enganchado",0,4,"oa",107,0,-1,0,73,73,"8926","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8927",8,"Virgencita milagrosa,\nbien sabes mi padecer;\nde rodillas iré a verte\nsi me concedes volver.",166,2,-1,163,"Mis querencias",0,4,"e",20,0,-1,0,73,73,"8927","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8928",8,"Santo Niño del Fresnillo,\ntú me has de favorecer;\nSanto Niño de Plateros,\ntú me concedas volver.",166,2,-1,163,"Despedida de un norteño",0,4,"e",20,0,-1,0,73,73,"8928","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8929",8,"Le pido al señor San Carlos,\nque me lo ha de conceder,\ny una vela le he de encender\nsi me hace ese milagro.",166,2,-1,163,"La caña brava",3,4,"ao",-1,0,-1,0,73,73,"8929","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8930a",8,"Santa Bárbara doncella,\nque en el cielo fuiste estrella,\nlíbranos del rayo\ny también de la centella.",166,2,-1,163,"Estrofa suelta",0,4,"ea",6,0,-1,0,74,74,"8930a","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8932",8,"Aléjate, Satanás,\nque en mí poder no tendrás,\nni en mi muerte te hallarás,\nque el día de la santa cruz\ndije mil veces, “Jesús”.",166,2,-1,163,"Estrofa suelta",7,5,"u",270,0,-1,0,74,74,"8932","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8934",8,"Por tus cinco llagas,\nmi amado Señor,\nperdón te pedimos\nllenos de dolor.",178,2,10,163,"A nuestro Padre Jesús Nazareno",0,4,"o",72,0,-1,0,74,74,"8934","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8935",8,"Duérmete, bien mío,\nduérmete, Señor;\nde nuestros pecados\ndanos el dolor.",166,2,-1,163,"Canto de Nochebuena",0,4,"o",72,0,-1,0,74,74,"8935","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8936",8,"Ya se llegó el fatal día\nde nuestra ejecución;\nVirgen de la Soledad,\ndadnos, por Dios, contrición.",166,2,-1,163,"Estrofa suelta",0,4,"o",31,0,-1,0,74,74,"8936","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8937",8,"Virgen Guadalupana,\ndeja llorar de emoción,\npues ya mi madre está sana,\ngracias a tu bendición.",169,2,8,163,"Estrofa suelta",1,4,"o",31,0,-1,0,74,74,"8937","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8938",8,"Suba, suba, suba\nla Virgen al cielo;\nbaje, baje, baje,\na damos consuelo.",171,2,4,163,"Naranjas y limas",0,4,"eo",10,0,-1,0,74,74,"8938","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8939",8,"A la Virgen Magdalena\nle pido que me bendiga;\nle ruego, porque es muy buena,\nque hasta el sepulcro me siga,\ndonde el cuerpo se cercena.",191,2,1,163,"Estrofa suelta",7,5,"ea",59,0,-1,0,75,75,"8939","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8940",8,"Del cielo viene bajando\nuna flor que así se tupe,\npara que nos acompañe\nla Virgen de Guadalupe.",168,2,11,163,"Estrofa suelta",0,4,"ue",271,0,-1,0,75,75,"8940","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8941",8,"Del cielo viene bajando\nuna flor de mil colores,\npara que nos acompañe\nla Virgen de los Dolores.",168,2,11,163,"Estrofa suelta, En el portal de Belén",0,4,"oe",5,0,-1,0,75,75,"8941","",0,"","","",4,0,0,[],"",""],["frenk_t4-n8942",8,"Desde su alta mansión\nel Creador te está mirando,\ny desde ella te está enviando\nsu sagrada bendición.",166,2,-1,163,"Las mañanitas",11,4,"o",31,0,-1,0,75,75,"8942","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8943",8,"Yo pedí aguinaldo\ny al señor Jesús,\ny me dio los clavos\nque tenía en la cruz.",171,2,4,163,"Naranjas y limas",0,4,"u",109,0,-1,0,75,75,"8943","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8945",8,"Pajarillo, clarín de la selva,\nque cantas al alba con tanto primor,\nsi encontrares al Pastor Divino,\nle dirás que triunfe de nuestro opresor.",166,2,-1,163,"Canto de Nochebuena",3,4,"o",72,0,-1,0,75,75,"8945","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8947",8,"De San Juan quiero la pluma,\nde San Francisco, el cordón,\nde Santa Rita, la espina\ny de Jesús, el corazón.",189,2,5,163,"Estrofa suelta",0,4,"o",31,0,-1,0,75,75,"8947","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8948",8,"Ya viene el agua sonando,\nel viento la desbarata;\nserá por nuestro pecado,\npor eso el agua dilata.",169,2,8,163,"Estrofa suelta",0,4,"aa",74,0,-1,0,75,75,"8948","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8949",8,"Virgencita morenita,\nla madre de los mexicanos,\nmadrecita santa y buena,\na ti besamos las manos.",175,2,6,164,"A la Santísima Virgen de Guadalupe",0,4,"ao",318,0,-1,0,76,76,"8949","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8950",8,"Buenos días, paloma blanca,\nhoy te vengo a saludar,\nsaludando a tu belleza\nen tu reino celestial.",170,2,7,164,"Caminatas; Buenos días, paloma blanca; Estrofa suelta",0,4,"a",-1,0,-1,0,76,76,"8950","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8951",8,"Eres madre del Creador,\nque a mi corazón encantas,\ngracias te doy con amor,\nbuenos días, paloma blanca.",170,2,7,164,"Caminatas",0,4,"aa",-1,0,-1,0,76,76,"8951","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8952",8,"Reluciente como el alba,\npura, sencilla, sin mancha.\n¡qué gusto recibe mi alma!\nBuenos días, paloma blanca.",170,2,7,164,"Caminatas",0,4,"aa",-1,0,-1,0,76,76,"8952","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8953",8,"Las jerarquías del empíreo,\nen compañía del Señor,\nsaludando, fresco lirio:\n“Buenos días, hermosa flor”.",170,2,7,164,"Caminatas",3,4,"o",72,0,-1,0,76,76,"8953","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8954",8,"Niña linda, Niña santa,\ntu dulce nombre alabar;\nporque sois tan sacrosanta,\nyo te vengo a saludar.",170,2,7,164,"Caminatas; Mañanitas a la Virgen de la Defensa",1,4,"a",21,0,-1,0,76,76,"8954","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8955",8,"Eres hermosa doncella,\nasí Dios te dibujó;\nte saludo, aurora bella,\nahora que ya amaneció.",170,2,7,164,"Caminatas",1,4,"o",2,0,-1,0,76,76,"8955","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8956",8,"Te saludo, Señora,\ncon mucho gusto y amor,\ndiciéndote en esta hora:\n“Buenos días, hermosa flor”.",170,2,7,164,"Caminatas",1,4,"o",72,0,-1,0,77,77,"8956","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8957",8,"Del cielo eres la grandeza\ndel regocijo de Dios;\nhoy digamos con presteza:\n“Buenos días, hermosa flor”.",170,2,7,164,"Caminatas",0,4,"o",-1,0,-1,0,77,77,"8957","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8958",8,"Buenos días, fragante rosa,\nmatizada de dolzuras,\nla más pura y más hermosa\nentre todas las criaturas.",170,2,7,164,"Caminatas",1,4,"ua",238,0,-1,0,77,77,"8958","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8959",8,"Sapientísima señora,\nen ti pongo mi esperanza;\nbella reluciente aurora,\nbuenos días, paloma blanca.",170,2,7,164,"Caminatas’T",0,4,"aa",-1,0,-1,0,77,77,"8959","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8960",8,"Los ángeles en el cielo,\nmadre de Dios sacrosanta,\ntodos por siempre te digan:\n“Buenos días, paloma blanca”.",170,2,7,164,"Caminatas",0,4,"aa",-1,0,-1,0,77,77,"8960","",0,"","","",10,0,0,[],"",""],["frenk_t4-n8961",8,"¡Dios te salve, aurora hermosa!,\n¡Dios te salve, luz del día!,\n¡Dios te salve, gran señora!,\n¡y Dios te salve, María!",167,2,2,164,"Ave María",0,4,"ia",0,0,-1,0,77,77,"8961","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8962",8,"Mi dulce refugio,\ndivino y sagrario,\n¡oh, divina aurora!,\nvengo a tu santuario.",170,2,7,164,"Caminatas",0,4,"ao",25,0,-1,0,77,77,"8962","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8963",8,"Buenos días te los dé Dios,\nPadre de mi corazón,\nte venimos a saludar\ncon todita esta reunión.",190,2,20,164,"Canción a un santo",0,4,"o",31,0,-1,0,77,77,"8963","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8964",8,"Jesús, Jesús amoroso,\nte saludamos confiados,\nvemos tu pecho hermoso\npor nuestro amor sangrado.",182,2,21,164,"Danza de los tecuanes",0,4,"ao",-1,0,-1,0,77,77,"8964","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8965",8,"De allá vengo, Niño lindo,\na darte los buenos días,\na saludar a tu padre\ny a la santa de María.",166,2,-1,164,"Canto de Nochebuena",0,4,"ia",-1,0,-1,0,77,77,"8965","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8966",8,"Salve, Niño hermoso,\nsalve, luz del cielo,\ndel hombre consuelo,\ndel Padre estupor.",181,2,15,164,"Saludo al Niño, Canto de Nochebuena",5,4,"o",-1,0,-1,0,78,78,"8966","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8967",8,"Ábrase la puerta\ndel bello portento,\npara saludar\neste nacimiento.",169,2,8,164,"Naranjas y limas",0,4,"eo",94,0,-1,0,78,78,"8967","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8969",8,"Salve, cruz bendita,\nmadero sagrado,\ndonde cayó al fin\nmi Jesús amado.",166,2,-1,164,"Estrofa suelta",0,4,"ao",14,0,-1,0,78,78,"8969","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8970",8,"Virgen de los mexicanos,\ntraemos nuestros cariños,\ntodos cual buenos hermanos\ncomo lo hacíamos de niños",175,2,6,164,"A la Santísima Virgen de Guadalupe",1,4,"io",625,0,-1,0,78,78,"8970","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8971",8,"Adiós, mi madre querida,\nla Virgen Guadalupana;\nadiós, mi patria amorosa,\nRepública Mexicana.",166,2,-1,164,"Despedida de un norteño",0,4,"aa",4,0,-1,0,78,78,"8971","",0,"","","",5,0,0,[],"",""],["frenk_t4-n8972",8,"Ya nos vamos, Madrecita,\nya nos vamos de verdad,\nporque mi tierra está lejos;\n¿cuándo vamos a llegar?",171,2,4,164,"A la Virgen de Guadalupe",0,4,"a",-1,0,-1,0,78,78,"8972","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8973",8,"Adiós, adiós, madre mía,\nMadre de consolación,\nse llegó ya el triste día\nde ser mi separación.",166,2,-1,164,"Estrofa suelta",1,4,"o",31,0,-1,0,78,78,"8973","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8974",8,"“Adiós”, dicen los vivientes\nen esta hora tan cercana;\nmadre mía Guadalupana,\n“adiós” te dicen las gentes.",166,2,-1,164,"Estrofa suelta",11,4,"ee",252,0,-1,0,78,78,"8974","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8975",8,"Ya nos vamos, Madrecita,\nya nos vamos tu moler,\nporque pronto mi papá\nya nos pide de comer.",171,2,4,164,"A la Virgen de Guadalupe",0,4,"e",20,0,-1,0,78,78,"8975","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8976",8,"Ya nos vamos, Madrecita,\nya nos vamos despidiendo,\npara que en nuestro camino\ntú nos vayas socorriendo.",171,2,4,164,"A la Virgen de Guadalupe",0,4,"eo",52,0,-1,0,79,79,"8976","",0,"","","",3,0,0,[],"",""],["frenk_t4-n8977",8,"Adiós, Señor milagroso,\nmás brillante que un lucero;\nadiós, templo primoroso,\nhasta el año venidero.",166,2,-1,164,"Estrofa suelta",1,4,"eo",38,0,-1,0,79,79,"8977","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8978",8,"Adiós, mi Padre querido,\nhasta el año venidero;\nadiós, Cristo aparecido,\nde Chalma hermoso lucero.",166,2,-1,164,"Estrofa suelta",1,4,"eo",38,0,-1,0,79,79,"8978","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8979",8,"Adiós, Padre mío,\nadiós, mi alimento;\nen tu sangre pura\nencuentro sustento.",178,2,10,164,"A nuestro Padre Jesús Nazareno",0,4,"eo",94,0,-1,0,79,79,"8979","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8980",8,"Adiós, Señor de Plateros,\ntus visitantes se van;\nadiós, retratos que están\npor milagros verdaderos.",166,2,-1,164,"Estrofa suelta",11,4,"eo",22,0,-1,0,79,79,"8980","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8981",8,"Adiós, ¡oh, Padre Jesús!,\ncon tu bendición me voy;\nalúmbrame con tu luz:\n¿qué no ves que tu siervo soy?",169,2,8,164,"Feria de Huaxpaltepec",1,4,"o",112,0,-1,0,79,79,"8981","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8982",8,"Ya nos retiramos,\nNiño quiquitito,\nen tu altar dejamos\nlindos regalitos.",170,2,7,164,"Estrofa suelta",0,4,"io",-1,0,-1,0,79,79,"8982","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8983",8,"Adiós, Niñito hermoso,\nadiós, Niñito querido,\nNiñito milagroso,\nde ti yo ya me despido.",166,2,-1,164,"Canto de Nochebuena",1,4,"io",101,0,-1,0,79,79,"8983","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8984",8,"Adiós, lindo frailecito,\nhasta el año venidero;\nesta sí es noche de gloria,\nporque ya nació el lucero.",166,2,-1,164,"Canto de Nochebuena",0,4,"eo",38,0,-1,0,79,79,"8984","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8985",8,"¡Oh, Santo Niño de Atocha!,\nya nos vamos con tristeza;\nen tu santuario dejamos\nnuestro amor con gran presteza.",175,2,6,164,"Estrofa suelta",0,4,"ea",108,0,-1,0,79,79,"8985","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8986",8,"San Antonio milagroso,\nde Calpulalpan bendito,\nadiós, mi padre glorioso,\ncon tu niño Jesusito.",166,2,-1,164,"Estrofa suelta",1,4,"io",119,0,-1,0,79,79,"8986","",0,"","","",2,0,0,[],"",""],["frenk_t4-n8987",8,"Adiós, relicario santo,\ndime adiós, porque me voy;\nen saliendo de este encanto,\npalabras al cielo doy\nde no adorar otro santo\ncomo el que adorando estoy.",169,2,8,164,"Estrofa suelta",9,6,"o",112,0,-1,0,80,80,"8987","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8988",8,"Nos vamos a retirar\ncon dolor y sentimiento;\nen este lugar dejamos\nnuestro gran remordimiento.",175,2,6,164,"Estrofa suelta",0,4,"eo",94,0,-1,0,80,80,"8988","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8989",8,"Yo me vine pa San Francisco,\ny me caigo y me levanto;\nalumbrándolos tres luces\ny alabé ya Santo Niño.",169,2,8,164,"San Francisco",5,4,"io",-1,0,-1,0,80,80,"8989","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8990",8,"Cuando el diablo supo\nque Cristo nació\nen el mismo instante\ncolerín le dio.",169,2,8,165,"Naranjas y limas’’",0,4,"o",2,0,-1,0,84,84,"8990","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8991",8,"Ya los Reyes Magos\nvienen de Sayula,\ny le traen al Niño\nsu pala y su mula.",171,2,4,165,"Naranjas y limas",0,4,"ua",547,0,-1,0,84,84,"8991","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8992",8,"Los tres Reyes Magos\nvienen del Oriente,\nvienen preguntando\npor un inocente.",171,2,4,165,"Naranjas y limas",0,4,"ee",15,0,-1,0,84,84,"8992","",0,"","","",8,0,0,[],"",""],["frenk_t4-n8993",8,"Te traigo yo un rosario\ncon cuentas de papelillo,\ny al venirlo caminando, -\nel muchacho lo ha perdido.",190,2,20,165,"Canción a un santo",0,4,"io",-1,0,-1,0,84,84,"8993","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8994",8,"Te traía yo un becerro\namarrado de una pata,\ny al traerlo en el camino,\nse le reventó la reata.",190,2,20,165,"Canción a un santo",0,4,"aa",74,0,-1,0,84,84,"8994","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8995",8,"Hasta Otumba llegué\na buscarte al camposanto;\n¡ayl, como no te encontré,\nme puse a rogarle a un palo\nestaba rete con fe.",171,2,4,165,"La leva",7,5,"e",77,0,-1,0,84,84,"8995","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8996",8,"Estaba San Bruno\nhaciendo oración,\ny el santo de mi alma\nasí se quedó.",175,2,6,165,"Estrofa suelta",0,4,"o",-1,0,-1,0,84,84,"8996","",0,"","","",1,0,0,[],"",""],["frenk_t4-n8997",8,"Arriba del cielo\nestá un canapé,\nen donde se sienta\nseñor San José.",178,2,10,165,"Canción de cuna",0,4,"e",77,0,-1,0,84,84,"8997","",0,"","","",15,0,0,[],"",""],["frenk_t4-n8998",8,"Arriba del cielo\nestá un baldoquín,\npor donde se asoma\nseñor San Joaquín.",166,2,-1,165,"Canción de cuna",0,4,"i",211,0,-1,0,85,85,"8998","",0,"","","",15,0,0,[],"",""],["frenk_t4-n8999",8,"Arriba del cielo\nhay un tulipán,\npor donde se asoma\nSan Pedro y San Juan.",171,2,4,165,"Naranjas y limas",0,4,"a",147,0,-1,0,85,85,"8999","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9000",8,"Arriba del cielo\nestá una azotea,\npor donde se asoma\nSanta Dorotea.",168,2,11,165,"Estrofa suelta",0,4,"ea",54,0,-1,0,85,85,"9000","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9001",8,"Arriba del cielo\nhay muchos piñones,\nque están repartiendo\nlos Santos Varones.",178,2,10,165,"Canción de cuna",0,4,"oe",34,0,-1,0,85,85,"9001","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9002",8,"Arriba del cielo\nestá una sandía,\nque está rebanándola\nSanta Lucía.",178,2,10,165,"Canción de cuna",6,4,"ia",0,0,-1,0,85,85,"9002","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9003",8,"Arriba del cielo\nestá una granada,\nque está desgranándola\nSanta Librada.",178,2,10,165,"Canción de cuna",6,4,"aa",-1,0,-1,0,85,85,"9003","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9004",8,"Arriba del cielo\nformaron ovejas,\nSan Pedro lo supo,\nse fue de cabeza.",171,2,4,165,"Naranjas y limas",0,4,"ea",-1,0,-1,0,85,85,"9004","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9005",8,"Arriba del cielo\nmataron novillo,\nlo supo San Pedro\ny llevó los cuchillos.",171,2,4,165,"Naranjas y limas",0,4,"io",-1,0,-1,0,85,85,"9005","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9006",8,"Arriba del cielo\nmataron gallina,\nlo supo San Pedro\ny se fue con Martina.",171,2,4,165,"Naranjas y limas",0,4,"ia",11,0,-1,0,85,85,"9006","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9007",8,"Arriba del cielo\nmataron conejo,\nSan Pedro lo supo,\ncompró vino añejo.",171,2,4,165,"Naranjas y limas",0,4,"eo",264,0,-1,0,85,85,"9007","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9008",8,"Arriba del cielo\nmataron tortugas,\nlo supo San Pedro,\ncompró la pechuga.",171,2,4,165,"Naranjas y limas",0,4,"ua",-1,0,-1,0,86,86,"9008","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9009",8,"Arriba del cielo\nmataron totoles,\nlo supo San Pedro,\nbotó los frijoles.",171,2,4,165,"Naranjas y limas",0,4,"oe",27,0,-1,0,86,86,"9009","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9010",8,"Arriba del cielo\nhicieron tamales,\nSan Pedro lo supo,\ncompró cuatro reales.",166,2,-1,165,"Naranjas y limas",0,4,"ae",26,0,-1,0,86,86,"9010","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9011",8,"Voy a hacer una escalera,\npara subir hasta el cielo\ny sorprender a San Pedro\ncocinando y con babero.",168,2,11,165,"Estrofa suelta",0,4,"eo",-1,0,-1,0,86,86,"9011","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9012",8,"San Francisco, dame atole,\npero no de nixtamal;\naunque sea atole de leche,\ncon un pedazo de pan.",176,2,3,165,"Estrofa suelta",0,4,"a",-1,0,-1,0,86,86,"9012","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9013",8,"Dichoso Cristobalazo,\nSantazo de cuerpo entero,\ny no como otros santitos,\nque ni se ven en el cielo.",166,2,-1,165,"Estrofa suelta",0,4,"eo",-1,0,-1,0,86,86,"9013","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9014",8,"Hercúleo Cristobalazo,\nforzudo como un Sansón,\ncon tu enorme cabezón\ny tu nervudo pescuezo.",166,2,-1,165,"Estrofa suelta",5,4,"eo",-1,0,-1,0,86,86,"9014","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9015",8,"Hazme grueso y vigoroso,\nhombrazo de cuerpo entero,\ny no como esos tipitos\nque casi besan el suelo.",166,2,-1,165,"Estrofa suelta",0,4,"eo",-1,0,-1,0,86,86,"9015","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9016",8,"La campana de mi pueblo\nllama a misa a los creyentes;\nunos van con devoción\ny otros a pelar los dientes.",169,2,8,165,"Estrofa suelta",0,4,"ee",252,0,-1,0,87,87,"9016","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9017",8,"Los tres Reyes Magos\nvinieron de Oriente,\ncomiendo tortillas\ny pelando los dientes.",166,2,-1,165,"Estrofa suelta, Naranjas y limas",0,4,"ee",-1,0,-1,0,87,87,"9017","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9018",8,"Los tres Reyes Magos\nvienen del Oriente,\npreguntando dónde\nvenden aguardiente.",171,2,4,165,"Naranjas y limas",0,4,"ee",15,0,-1,0,87,87,"9018","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9019",8,"Y era de nogal,\ny era de nogal el santo,\nhijo de un cabrón,\npor eso pesaba tanto.",168,2,11,165,"Estrofa suelta",0,4,"ao",30,0,-1,0,87,87,"9019","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9020a",8,"Cuando Dios se determina\na matar a los mortales,\nya no bastan los cordiales\nni los caldos de gallina.",189,2,5,166,"Estrofa suelta",11,4,"ia",11,0,-1,0,90,90,"9020a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9020b",8,"Cuando la Muerte se inclina\na llevarse a los mortales,\nno vale la medicina\nni vidas artificiales,\nni los caldos de gallina\ncon todos sus materiales.",167,2,2,166,"El querreque",9,6,"ae",26,0,-1,0,90,90,"9020b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9021",8,"Subí a la torre del puerto\na ver la suerte del hombre:\na cualquiera le recuerdo,\naunque sea de gran renombre,\nque la suerte de los hombres\nes acabar siendo muerto.",171,2,4,166,"El siquisirí",9,6,"eo",-1,0,-1,0,90,90,"9021","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9022",8,"Aquí se acaba el orgullo,\ntambién la infernal malicia,\naquí se pela la pava\ncon la Divina Justicia.",189,2,5,166,"Estrofa suelta",0,4,"ia",391,0,-1,0,90,90,"9022","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9023",8,"Termina aquí el engreimiento,\nla altivez y altanería;\nse derriba aquí el cimiento,\ny se acaba la arquería\nde aquella torre de viento.",189,2,5,166,"Estrofa suelta",7,5,"eo",94,0,-1,0,90,90,"9023","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9024",8,"Piensa en la extrema partida\ndel morir, ¡oh lance fuerte!\n¡Ay, cuán amarga es la muerte\na quien fue dulce la vida!",166,2,-1,166,"Estrofa suelta",11,4,"ia",37,0,-1,0,90,90,"9024","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9025",8,"De la cruz de las sílabas\nse ve muy bien el calvario;\nsi piensan dejar el mundo,\npreparen su novenario.",166,2,-1,166,"Mi tierra es León, Guanajuato",0,4,"ao",25,0,-1,0,90,90,"9025","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9026",8,"Aprender a morir primero\nantes que la muerte llegue,\nque en la eternidad sólo vive\nel que, estando en vida, muere.",182,2,21,166,"Estrofa suelta",0,4,"ee",-1,0,-1,0,91,91,"9026","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9027",8,"Y no se descuiden,\ntodos mis amigos,\nporque si ella viene,\nsomos perdidos.",166,2,-1,166,"Que dice la media muerte",6,4,"io",-1,0,-1,0,91,91,"9027","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9028",8,"Y no se descuiden,\nviejos y muchachos,\nporque si ella viene,\nlos hará pedazos.",166,2,-1,166,"Que dice la media muerte",0,4,"ao",-1,0,-1,0,91,91,"9028","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9029",8,"Que no se descuiden,\nhombres y mujeres,\nporque si ella viene,\nya no habrá placeres.",166,2,-1,166,"Que dice la media muerte",0,4,"ee",-1,0,-1,0,91,91,"9029","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9030",8,"Que sube y que baja\ny que llega hasta Ixtlán.\n¿Adónde van los muertos?\n¡Quién sabe adónde irán!",166,2,-1,166,"El sube y baja",0,4,"a",147,0,-1,0,91,91,"9030","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9031",8,"Murió el vale Bej araño,\nque era un gran compositor,\ny todo el género humano\nlo ha sentido con dolor,\nporque se murió un cristiano\nde lo bueno a lo mejor.",171,2,4,166,"Zapateado",9,6,"o",72,0,-1,0,91,91,"9031","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9032",8,"No sé qué tienen las flores (Llorona),\nlas flores del camposanto,\nque cuando las mece el viento (Llorona)\nparece que están llorando.",168,2,11,166,"La Llorona",3,4,"ao",-1,0,-1,0,91,91,"9032","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9033a",8,"Pobre flor, ¡qué mal naciste,\ncon tan despreciada suerte!\nAl primer paso que diste\ntropezaste con la muerte.",169,2,8,166,"Estrofa suelta",1,4,"ee",134,0,-1,0,91,91,"9033a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9034",8,"Ya se murió el trovador,\nsu nombre pasó a la historia;\nlos versos que él dejó\nyo los cargo en la memoria;\nSan Pedro se lo llevó\npara tenerlo en la gloria.",171,2,4,166,"Zapateado, El pájaro cú",9,6,"oa",126,0,-1,0,92,92,"9034","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9035",8,"Muchachos, cojan modelo\nantes que muera Juanito;\n¡áhi si lo ven en el suelo,\nle rezarán un bendito\ny lo encomiendan al cielo\na este pobre muchachito!",169,2,8,166,"El siquisirí",9,6,"io",119,0,-1,0,92,92,"9035","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9036",8,"Si Dios me diera licencia\nde abrir esa sepultura,\nsacar a mis dos hermanos\nMáximo Ramón, Ventura.",169,2,8,166,"La Zandunga",0,4,"ua",17,0,-1,0,92,92,"9036","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9038a",8,"Un huerfanito lloraba\ny ausente de su mamá;\n“Cállese, que áhi viene ya,\npues anda en un mand adito:\nse fue pa la eternidad”.",175,2,6,166,"El huerfanito",7,5,"a",-1,0,-1,0,92,92,"9038a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9038b",8,"Triste llora un huerfanito\nla muerte de su mamá;\nle dice el más grandecito:\n“No llores, que áhi viene ya;\nse fue por un momentito\ncon rumbo a la eternidad”.",168,2,11,166,"El huerfanito",9,6,"a",-1,0,-1,0,92,92,"9038b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9039",8,"El huérfano está indino,\nque no se puede aguantar;\nlo echaremos a la calle,\na que busque donde estar.",171,2,4,166,"El huérfano",0,4,"a",21,0,-1,0,92,92,"9039","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9040",8,"Estando amarrando un gallo,\nse me reventó el cordón.\n¿Si será mi muerte un rayo,\no me matará un bribón,\nde esos que andan a caballo\nvalidos de la ocasión?",184,2,14,166,"Estando amarrando",9,6,"o",31,0,-1,0,92,92,"9040","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9042",8,"Mientras tengan perfume las flores,\nolviden dolores y vengan a amar,\nrecordando que tal vez mañana\nclarín de campaña nos llame a luchar.",166,2,-1,166,"Clarín de campaña",3,4,"a",21,0,-1,0,93,93,"9042","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9043",8,"Mira, Muerte, no seas inhumana,\nno vengas mañana, déjame vivir,\nrecordando que tal vez mañana\nclarín de campaña nos llame a morir.",168,2,11,166,"Clarín de campaña",3,4,"i",157,0,-1,0,93,93,"9043","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9044",8,"Del primer punto al segundo\nyo nunca me despidiera;\nos dedico mi concurso\ny regreso a mis fronteras;\n¡ay, qué bonito es el mundo!\n¡ay, lástima que yo me muera!",166,2,-1,166,"La leva",9,6,"ea",-1,0,-1,0,93,93,"9044","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9045",8,"La Muerte a rigor me llama,\nme quiere quitar la vida;\nella se arrima a la cama,\ndiciéndole a mi querida;\n“Alístalo, que mañana\ntempranito es la salida”.",171,2,4,166,"El siquisirí",9,6,"ia",37,0,-1,0,93,93,"9045","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9047",8,"Oigan mi último quejido\ny mi postrimer lamento:\n“¡Adiós, mundo, que contento\nlargos años he vivido!”",166,2,-1,166,"Estrofa suelta",11,4,"io",101,0,-1,0,93,93,"9047","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9048",8,"Al amanecer la aurora\ntriste me senté a llorar,\nno más de considerar\nque tierra me he de volver.",187,2,12,166,"La señora",5,4,"e",-1,0,-1,0,93,93,"9048","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9049",8,"Yo no le temo a la muerte,\nque el morir es natural;\nsólo le temo a la cuenta\nque a mi Dios le tengo que dar.",169,2,8,166,"Estrofa suelta",0,4,"a",-1,0,-1,0,93,93,"9049","",0,"","","",12,0,0,[],"",""],["frenk_t4-n9050",8,"Adiós, mi padre y mi madre,\ny todos mis hermanitos;\nyo buena voy pa la gloria,\na ver a los angelitos.",166,2,-1,166,"Estrofa suelta",0,4,"io",254,0,-1,0,93,93,"9050","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9051",8,"Por caja quiero un sarape,\npor cruz mis dobles cananas,\ny escriben sobre mi tumba\nmi último adiós con mil balas.",166,2,-1,166,"La cama de piedra",0,4,"aa",-1,0,-1,0,94,94,"9051","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9052",8,"Y en mi cabecera pones\nun letrero colorado,\ny en el letrero que diga:\n“Y aquí murió el desgraciado”.",187,2,12,166,"El caballito",3,4,"ao",14,0,-1,0,94,94,"9052","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9053",8,"Un pelado se halló medio\ny de gusto se murió,\ny en las ansias de la muerte\nhasta su medio perdió.",166,2,-1,167,"Estrofa suelta",0,4,"o",2,0,-1,0,98,98,"9053","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9054",8,"¡Ay, muerte, no vengas hora,\nporque estoy enfandangado!\nVendrás la semana que entra,\nque ya estoy desocupado.",166,2,-1,167,"Estrofa suelta, El jarabe",0,4,"ao",14,0,-1,0,98,98,"9054","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9055",8,"Viene la Muerte, luciendo\nmil llamativos colores;\nven, dame un beso, paloma,\nque ando huérfano de amores.",166,2,-1,167,"La muerte",0,4,"oe",5,0,-1,0,98,98,"9055","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9056",8,"El mundo es una arenita,\ny el sol es una chispita;\ny a mí me encuentran tomando\ncon la Muerte en la cantina.",166,2,-1,167,"La muerte",0,4,"ia",-1,0,-1,0,98,98,"9056","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9057",8,"Se va la Muerte cantando\npor entre las nopaleras;\n¿en qué quedamos, pelona?,\n¿me llevas o no me llevas?",166,2,-1,167,"La muerte",0,4,"ea",-1,0,-1,0,98,98,"9057","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9058",8,"La Muerte me hace conquista\nde diferente manera;\nyo no la pierdo de vista,\nporque ella es muy traicionera:\nme quiere poner en lista\nonde están las calaveras.",171,2,4,167,"El Balajú; El siquisirí, Zapateado",9,6,"ea",-1,0,-1,0,98,98,"9058","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9059",8,"Cuando el amor se confiesa,\ny un amigo es el rival,\nal fin triunfa la nobleza,\ncuando es firme la amistad,\ny siendo amigo del alma,\nterminó la enemistad.",171,2,4,168,"La morena",9,6,"a",16,0,-1,0,102,102,"9059","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9060",8,"Traigo un gran remordimiento,\n¿y cuándo lo doy a saber?\nY si digo lo que siento,\nse me vaya ella a ofender,\ny eso es lo que yo no intento:\nmis amistades perder.",171,2,4,168,"El Balajú",9,6,"e",20,0,-1,0,102,102,"9060","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9061",8,"Toda mi vida yo he sido franco\ny siempre he hablado con la verdad,\ny desde luego no hay motivo\npara que piérdamos la amistad.",173,2,17,168,"Indita mía",3,4,"a",16,0,-1,0,102,102,"9061","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9062",8,"Vengo lleno de contento,\ncontagiado de alegría:\nse acabó mi sentimiento\nque con Pascual yo tenía.",171,2,4,168,"La morena",1,4,"ia",0,0,-1,0,102,102,"9062","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9063",8,"Con gusto tiendo la mano\ncomo prueba de amistad,\nque Teodoro es un hermano\na quien quiero de verdad.",171,2,4,168,"La morena",1,4,"a",16,0,-1,0,102,102,"9063","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9064",8,"Conteste usted, compañerito,\nconteste, y no tenga vergüenza,\nque si en algo se turbare,\naquí estoy a su defensa.",170,2,7,168,"Estrofa suelta",3,4,"ea",622,0,-1,0,102,102,"9064","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9065",8,"Tan cuchillero y atrevido\nes mi querido manís,\nque le dicen El Temido\npor el interior del país.",166,2,-1,168,"Estrofa suelta",3,4,"i",58,0,-1,0,102,102,"9065","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9067",8,"Dos jirones de vapor\nque del lago se levantan\ny al juntarse allá en el cielo\nforman una nube blanca:\nésas somos tú y yo.",168,2,11,168,"Estrofa suelta",7,5,"o",-1,0,-1,0,103,103,"9067","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9068",8,"En el cielo hay una nube,\nen el mar un animal,\nen la tierra hay una amiga\nque te quiere de verdad.",174,2,9,168,"Estrofa suelta",0,4,"a",-1,0,-1,0,103,103,"9068","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9069",8,"No quiero perlas del mar,\nni rubíes del oriente,\nsólo quiero tu amistad,\nque perdure eternamente.",174,2,9,168,"Estrofa suelta",0,4,"ee",15,0,-1,0,103,103,"9069","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9070",8,"La amistad es una perla\nmuy difícil de encontrar;\nya que tú y yo la tenemos,\nla debemos conservar.",168,2,11,168,"Estrofa suelta",0,4,"a",21,0,-1,0,103,103,"9070","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9071",8,"No importa la lejanía\ndonde existe la verdad:\nuna sincera amistad\ncomo la tuya y la mía.",168,2,11,168,"Estrofa suelta",11,4,"ia",0,0,-1,0,103,103,"9071","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9072",8,"Como dos pájaros que vuelan\nen el su vuelo no pararán,\ndos amigos que se aprecian\nno se olvidarán.",168,2,11,168,"Estrofa suelta",3,4,"a",147,0,-1,0,103,103,"9072","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9073",8,"Dos flores en el agua\nno se marchitan;\ndos amigas que se quieren\nno se olvidan.",168,2,11,168,"Estrofa suelta",6,4,"ia",-1,0,-1,0,103,103,"9073","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9076",8,"Dos pingüinos en el agua\nno se pueden resbalar;\ndos amigas que se quieren\nno se pueden olvidar.",168,2,11,168,"Estrofa suelta",0,4,"a",21,0,-1,0,104,104,"9076","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9077",8,"Las flores en el campo\ncrecen de dos en dos;\nnadie se quiere tanto,\ncomo nosotros dos.",174,2,9,168,"Estrofa suelta",0,4,"o",-1,0,-1,0,104,104,"9077","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9078",8,"En el campo crecen las amapolas\nde dos en dos,\npero ninguna se quiere tanto\ncomo nosotras dos.",168,2,11,168,"Estrofa suelta",3,4,"o",-1,0,-1,0,104,104,"9078","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9079",8,"Cuando tengas un gatito,\nllámale Mimí,\njálale la cola\ny acuérdate de mí.",168,2,11,168,"Estrofa suelta",0,4,"i",23,0,-1,0,104,104,"9079","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9080",8,"Cuando vayas por la calle\ny te encuentres un tostón,\nacuérdate de mí,\nque te quise de a montón.",168,2,11,168,"Estrofa suelta",0,4,"o",31,0,-1,0,104,104,"9080","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9081",8,"Cuando estés en la cocina,\ny el humo te haga llorar,\nacuérdate de tu amigo,\nque nunca te ha de olvidar.",168,2,11,168,"Estrofa suelta",0,4,"a",21,0,-1,0,104,104,"9081","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9082",8,"Cuando estés en la cocina,\ny el humo te está ahogando,\nacuérdate de tu amiga,\nque de ti se está acordando.",168,2,11,168,"Estrofa suelta",0,4,"ao",33,0,-1,0,104,104,"9082","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9083",8,"Cuando vayas en la calle,\ncomiendo chicharrón,\nacuérdate de tu amiga\nde todo corazón.",168,2,11,168,"Estrofa suelta",0,4,"o",31,0,-1,0,104,104,"9083","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9084",8,"Cuando vayas por la calle\ny te encuentres una lata,\nacuérdate de tu amiga,\nque te dio tanta lata.",174,2,9,167,"Estrofa suelta",0,4,"aa",-1,0,-1,0,108,108,"9084","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9085",8,"Cuando vayas al cine,\ny la película ya comenzó,\nacuérdate de tu amigo,\nque tanta lata te dio.",174,2,9,167,"Estrofa suelta",3,4,"o",2,0,-1,0,108,108,"9085","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9086",8,"Cuando te vayas a Nueva York\ny veas las cascadas,\nacuérdate de tu amigo,\nque se ríe a carcajadas.",166,2,-1,167,"Estrofa suelta",3,4,"aa",282,0,-1,0,108,108,"9086","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9087",8,"Cuando vayas a un rancho\ny veas una vaca,\nacuérdate de tu amiga,\nque siempre metía la pata.",182,2,21,167,"Estrofa suelta",0,4,"aa",-1,0,-1,0,108,108,"9087","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9088",8,"Cuando vayas por la calle\ny te encuentres un melón,\nacuérdate de tu amiga,\nque le gusta el vacilón.",174,2,9,167,"Estrofa suelta",0,4,"o",31,0,-1,0,108,108,"9088","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9089",8,"Cuando estés en tu cocina,\nhaciendo tus ricos panes,\nacuérdate de tu amiga,\nque le gustan los volcanes.",168,2,11,167,"Estrofa suelta",0,4,"ae",444,0,-1,0,108,108,"9089","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9090",8,"Cuando andes en bicicleta\ndale duro a los pedales,\ny acuérdate de tu amiga,\nque le gustan los tamales.",168,2,11,167,"Estrofa suelta",0,4,"ae",26,0,-1,0,108,108,"9090","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9091",8,"Tengo un perrito en mi casa,\nque le nombran el Quiquí,\ny cuando voy a la plaza\nsiempre me acuerdo de ti.",171,2,4,167,"El perro",1,4,"i",23,0,-1,0,109,109,"9091","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9092",8,"Eres mi amiga más querida,\neres mi amiga más adorada,\nporque siempre me disparas\nuna tostada.",168,2,11,167,"Estrofa suelta",3,4,"aa",-1,0,-1,0,109,109,"9092","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9093",8,"Dos pelotas en el agua\nque no dejan de flotar\nson dos amigas que se estiman\ny no pueden enflacar.",168,2,11,167,"Estrofa suelta",0,4,"a",21,0,-1,0,109,109,"9093","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9094",8,"Tú eres de oro,\ntus amigas son de plata,\ntus amigos son de cobre,\ny yo soy de hoja de lata.",168,2,11,167,"Estrofa suelta",3,4,"aa",74,0,-1,0,109,109,"9094","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9095",8,"Dicen que el coco es muy bueno,\nguisado en especia fina,\npero yo digo que no;\nes más buena la gallina.",171,2,4,169,"El coco",0,4,"ia",11,0,-1,0,112,112,"9095","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9096",8,"Dicen que el coco es muy bueno,\nguisado y allá en Perote,\npero yo digo que no:\nque es más bueno el guajolote.",171,2,4,169,"El coco",0,4,"oe",292,0,-1,0,112,112,"9096","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9097",8,"Dicen que el coco es muy bueno,\nguisado en especia de agua,\ny yo digo que es mentira:\nque es más buena la chachagua.",171,2,4,169,"El coco",0,4,"aa",383,0,-1,0,112,112,"9097","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9098",8,"A la tripa, tripa (retripa),\ntripa de venao,\nmi mamá no quiere (Canelo)\nque coma pescao,\ny si acaso como (Canelo),\nque sea bacalao.",171,2,4,169,"El Canelo",9,6,"ao",98,0,-1,0,112,112,"9098","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9099",8,"Andando pescando meros\nen un estero salado,\nle dije a mi compañero:\n“Éste es el mero pescado,\nque se agarra con trabajo\ny se come con cuidado”.",169,2,8,169,"Estrofa suelta, Al pasar por los laureles; La Petenera",9,6,"ao",-1,0,-1,0,112,112,"9099","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9100",8,"Muy agradable se bebe\nal tenerse mucha sed;\n¡qué sabrosa es la aguanieve,\nmás sabrosa que el café:\nse pasa muy suave y breve!",175,2,6,169,"El aguanieve",7,5,"ee",474,0,-1,0,112,113,"9100","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9101",8,"¡Qué sabrosa es la aguanieve,\ny más en camino real!\nCon mucho gusto se bebe,\nse refresca el paladar,\ny el alma se conmueve.",175,2,6,169,"El aguanieve",7,5,"ee",474,0,-1,0,113,113,"9101","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9102",8,"Una dicha muy completa\nhace sentir la aguanieve;\naunque esté el hombre de dieta,\njamás a dañar se atreve:\nlo dice Benito Izeta.",175,2,6,169,"El aguanieve",7,5,"ea",200,0,-1,0,113,113,"9102","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9103a",8,"Coco de la caña dulce,\ncoco de la caña hueca,\ndéjame tomarla,\nque quiero beberla.",171,2,4,169,"El coco",0,4,"ea",-1,0,-1,0,113,113,"9103a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9103b",8,"De la caña dulce,\nde la caña brava,\ndéjame tomarla;\nes el aguamiel,\ncoco de mi vida,\ncoco de la Lerma.",171,2,4,169,"El coco",9,6,"ea",-1,0,-1,0,113,113,"9103b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9106",8,"¡Ay, qué sabrosos romeros!,\nqué bueno está el guajolote;\ntoma, mi chata, otros fierros,\nvamos a entrarle al pulcote;\nal cabo cada año es eso:\nhay que hacer nuestro borlote.",166,2,-1,169,"Los paseos de Santa Anita",9,6,"oe",292,0,-1,0,113,113,"9106","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9107",8,"Adiós, frijoles bien fritos,\nque con gordas tienen quite,\ncuando mis tripas dan gritos\nbebiendo pulque tlachique.",166,2,-1,169,"Las mañanitas",0,4,"ie",-1,0,-1,0,113,113,"9107","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9108",8,"Los salmones me atormentan,\nla ensalada es mi consuelo,\ncon el pulque se contentan\nmis pulmones en el suelo.",166,2,-1,169,"Las mañanitas",1,4,"eo",10,0,-1,0,113,113,"9108","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9109",8,"De este atolito de leche\ny tamales de manteca\ntodo el mundo se aproveche,\nque por esto no se peca.",166,2,-1,169,"El jarabe",1,4,"ea",594,0,-1,0,114,114,"9109","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9110",8,"Yo no quiero uvas,\ntampoco cervezas,\nyo quiero ésas\nque están allá arriba.",171,2,4,169,"Naranjas y limas",3,4,"ia",-1,0,-1,0,114,114,"9110","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9111",8,"Y si vas al melonar,\nme cortarás un melón,\npero no vayas a darle (mi vida)\nuna rebanada al tejón.",166,2,-1,169,"El tejón",3,4,"o",31,0,-1,0,114,114,"9111","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9112",8,"Si fueres a Coahuayana,\ntráeme un melón y una lima,\nla lima que no esté verde\ny el melón, con sarna encima.",166,2,-1,169,"Coahuayana",3,4,"ia",302,0,-1,0,114,114,"9112","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9113",8,"Cuando quieras comer frutas,\nprefiere sólo cajeras;\nde aguacates no te embutas,\nporque te salen ojeras.",185,2,13,169,"Estrofa suelta",1,4,"ea",103,0,-1,0,114,114,"9113","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9114",8,"Si quieres comer iguana,\nvamos para Coalcomán;\nverás allí las inditas\ncomiéndolas en pipián.",192,2,22,169,"La iguana",0,4,"a",147,0,-1,0,114,114,"9114","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9116",8,"El viejo anciano con el violín,\nde la barba blanca, me dijo así:\n“Estos juiles no son para ti,\nson para mi china que los va a freír”.",171,2,4,169,"Los juiles",3,4,"i",-1,0,-1,0,114,114,"9116","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9117",8,"He de volver en mi cuaco\ncon mi sarape en la silla;\nespero que tú me encuentres\ncon chile en unas tortillas,\nhechas todas enchiladas\ny un poco de marranilla.",181,2,15,169,"La voltereta",9,6,"ia",-1,0,-1,0,114,114,"9117","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9118",8,"Un estudiante en Valencia\nse puso a pintar el sol,\ny del hambre que tenía,\npintó un pan de munición.",178,2,10,170,"Que viva la rumba",0,4,"o",-1,0,-1,0,118,118,"9118","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9119",8,"Si la mar fuera de atole\ny sus olas de tortilla,\nanduvieran las mujeres\nrecogiendo en las orillas.",169,2,8,170,"Estrofa suelta",0,4,"ia",-1,0,-1,0,118,118,"9119","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9120",8,"Del cielo cayó un bistec,\nuntado de mantequilla,\ny en cada esquina decía:\n“Cómetelo con tortilla”.",168,2,11,170,"Estrofa suelta",0,4,"ia",-1,0,-1,0,118,118,"9120","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9122",8,"Cogí un hermoso jonote,\ngrande sin comparación;\nme comí un pedazo en mosto\nde ese grande animalón.",169,2,8,170,"Estrofa suelta",0,4,"o",31,0,-1,0,118,118,"9122","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9123",8,"¡Qué mal he comido hoy!,\nla causa de estar a dieta:\nme comí un peso de pan,\ndos arrobas de galletas.",169,2,8,170,"Estrofa suelta",0,4,"ea",-1,0,-1,0,118,118,"9123","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9124",8,"Ya me voy pa la Quebrada\na matar un tiburón,\npara que coma Padilla\ncon su cuate Castejón.",166,2,-1,170,"La Sanmarqueña",0,4,"o",31,0,-1,0,118,118,"9124","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9125",8,"Taquitos de rana verde,\ntortas de culebra brava;\ndale un taco a este pobre,\nque ya so le cae la baba.",168,2,11,170,"La Sanmarqueña",0,4,"aa",28,0,-1,0,118,118,"9125","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9126",8,"—Amada Marcelina,\n¿dónde estás, que no te alcanzo?\n—Estoy en la cocina,\nguisando los garbanzos.",171,2,4,170,"El Colás",0,4,"ao",-1,0,-1,0,119,119,"9126","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9127",8,"—Amada Marcelina,\n¿dónde estás, que no te veo?\n—Estoy en la cocina,\nguisando los fideos.",171,2,4,170,"El Colás",0,4,"eo",-1,0,-1,0,119,119,"9127","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9128",8,"Amada Marcelina,\nmujer de don Rufino,\nla que hace los tamales\nde carne de cochino.",171,2,4,170,"El Colás",0,4,"io",199,0,-1,0,119,119,"9128","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9129",8,"Amada Marcelina,\nmujer de don Conejo,\nno quiere que yo coma\ntamales de cangrejo.",171,2,4,170,"El Colás",0,4,"eo",264,0,-1,0,119,119,"9129","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9130",8,"Comadre Marcelina,\nmujer de don Manuel,\nquería que yo comiera\nlos tamales de curel.",171,2,4,170,"El Colás",0,4,"e",32,0,-1,0,120,120,"9130","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9131",8,"Amada Margarita,\nmujer de Nicolás,\nque quieres que me coma\nlos tamales de alcatraz.",166,2,-1,170,"El Colás",0,4,"a",253,0,-1,0,120,120,"9131","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9132",8,"Amada Margarita,\nmujer de don Simón,\nque quiere que me coma\ntamales de ratón.",171,2,4,170,"El Colás",0,4,"o",31,0,-1,0,120,120,"9132","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9133",8,"Por esta calle derecha,\nme convidan a almorzar\nzopilotes en conserva,\nlagartijas en pipián.",171,2,4,170,"El guapo",0,4,"a",-1,0,-1,0,120,120,"9133","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9134",8,"Antenoche fui a tu casa\ny me diste de cenar\ncucarachas en vinagre\ny ratones en pipián.",178,2,10,170,"El capotín",0,4,"a",-1,0,-1,0,120,120,"9134","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9135",8,"Antenoche fui a tu casa,\nque me dieras un consejo,\ny me diste de cenar\nlas orejas del conejo.",169,2,8,170,"Estrofa suelta",0,4,"eo",264,0,-1,0,120,120,"9135","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9136",8,"El día que hiciste el arroz de leche\nla cocinera se emborrachó:\nen vez de azúcar, le echó jalapa,\ny hasta la gata se vomitó.",166,2,-1,170,"Buscando peces",3,4,"o",2,0,-1,0,121,121,"9136","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9137",8,"Si para comer tasajo\ntengo que chingar el lomo,\nchingue su madre el lomo,\ny mejor no como.",169,2,8,170,"Estrofa suelta",0,4,"oo",349,0,-1,0,121,121,"9137","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9138",8,"Ahí viene la ronda\nde los borrachos,\nescondan sus muchachas,\nque no los miren ir.",176,2,3,171,"Las muchachas",3,4,"i",-1,0,-1,0,124,124,"9138","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9139",8,"Ya me invitaba a tomar,\npobrecito arrierito,\ny áhi como estaba viejito,\nyo no lo quise aceptar.",171,2,4,171,"Los arrieros",3,4,"a",21,0,-1,0,124,124,"9139","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9140",8,"Una pipa me dio un beso:\nyo no se lo quería dar,\nporque le hedía el pescuezo,\nlicorera de la mar.",176,2,3,171,"El listoncillo",1,4,"a",21,0,-1,0,124,124,"9140","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9141",8,"Allá le mando al muchacho,\npara que lo mande usted,\nél es flojo y es borracho.\nno le gusta andar a pie;\nle gusta el trote del macho,\naunque lo zangolotee.",166,2,-1,171,"Estrofa suelta",9,6,"ee",-1,0,-1,0,124,124,"9141","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9142",8,"Andaba este Lucio Vázquez\nque se arrastraba de risa,\ny andaba tan borrachito,\nque se quedó sin camisa.",166,2,-1,171,"Los pavos reales",0,4,"ia",68,0,-1,0,124,124,"9142","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9143",8,"Mira el borracho de Andrés\ncómo anda con las casadas,\nsabiendo que la crudez\nse cura con enchiladas\ny una copa de jerez.",171,2,4,171,"El borracho",7,5,"e",150,0,-1,0,124,124,"9143","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9144",8,"María Justa anda borracha,\nmetiéndose en las tienditas,\nempeñando las enaguas\npara comprar botellitas.",166,2,-1,171,"Las campanitas; Estrofa suelta",0,4,"ia",258,0,-1,0,124,124,"9144","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9146",8,"La vida de los borrachos\nes una vida muy sana:\ncomienzan con el domingo\ny salen con la semana.",173,2,17,171,"El borracho",0,4,"aa",4,0,-1,0,125,125,"9146","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9147",8,"La vida de los borrachos\nes una vida tranquila:\ncomienzan con la cerveza\ny acaban con la tequila.",173,2,17,171,"El borracho",0,4,"ia",427,0,-1,0,125,125,"9147","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9148",8,"No dejen el aguardiente,\nésta es más segura ley:\ntomen del vino sabroso\nque proviene del maguey.",166,2,-1,171,"Estrofa suelta",0,4,"e",133,0,-1,0,125,125,"9148","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9150",8,"Cuando ya está uno tomado\ny la cabeza caliente,\nnada importa el fin del mundo,\nni que se acabe la gente.",166,2,-1,171,"Estrofa suelta",0,4,"ee",15,0,-1,0,125,125,"9150","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9151",8,"Que el que está borracho siempre\ny así la muerte lo atrapa:\nno siente ni cómo llega\nsi está ebrio con mazapa.",166,2,-1,171,"Estrofa suelta",0,4,"aa",297,0,-1,0,125,125,"9151","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9152",8,"No nos arredre el morir\npor una crudez injusta,\npues al que es hijo de Baco\njamás la muerte le asusta.",166,2,-1,171,"Estrofa suelta",0,4,"ua",626,0,-1,0,125,125,"9152","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9153",8,"Borrachos todos los días\nnada nos harán las penas,\ny con el dios Baco, unidos,\nnos liguen dulces cadenas.",166,2,-1,171,"Estrofa suelta",0,4,"ea",62,0,-1,0,125,125,"9153","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9154",8,"Es buena la cervecita\npara el que está desvelado;\nyo prefiero un tequilita,\nque es bueno para lo hinchado,\ny hasta lo panzón se quita.",167,2,2,171,"El querreque; La leva; La madrugada",7,5,"ia",50,0,-1,0,126,126,"9154","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9155",8,"¡Ay, morena, morena!,\nya me duele la cabeza;\nel remedio que te pido\nes una copa de cerveza.",176,2,3,171,"La morenita",0,4,"ea",108,0,-1,0,126,126,"9155","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9156",8,"Si se siente usted malito,\nbien puede aliviarse al trote,\nsi se toma un caballito,\nde ésa la cerveza “Quijote”.",166,2,-1,171,"La leva",1,4,"oe",292,0,-1,0,126,126,"9156","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9157",8,"La cerveza popular\nes dondequiera el azote:\nla toma y no le hace mal,\nsiempre y cuando sea “Quijote”,\nla famosa “Colosal”.",191,2,1,171,"La leva",7,5,"a",1,0,-1,0,126,126,"9157","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9158",8,"Paseo con mis amigos:\n¡qué gusto tan rastrero!\nEllos comprando vino,\nbebiendo yo el primero.",176,2,3,171,"El borracho impertinente",0,4,"eo",38,0,-1,0,126,126,"9158","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9159",8,"¡Qué bonitos gorgoritos,\nlos que hacen una botella!,\npero más bonitos son\nlos tragos que doy en ella.",178,2,10,171,"Los gorgoritos",0,4,"ea",6,0,-1,0,126,126,"9159","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9160",8,"A mí no me gusta el ponche,\nporque tiene mucho anís;\na mí me gusta el colonche,\nel colonche de San Luis.",178,2,10,171,"El sombrero ancho; Estrofa suelta",1,4,"i",58,0,-1,0,126,126,"9160","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9161a",8,"¿Cuál es el mejor licor\ndel whisky y el aguardiente?\nYo digo que el aguardiente,\nporque ése emborracha al presidente,\ntambién al gobernador.",166,2,-1,171,"El querreque",7,5,"o",72,0,-1,0,126,126,"9161a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9162",8,"Las píldoras “Laverán”\nya no las quiere la gente,\nporque dice un alemán\nque es mejor un aguardiente\nque cuatro piezas de pan\ny un chocolate caliente.",171,2,4,171,"La guacamaya",9,6,"ee",15,0,-1,0,127,127,"9162","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9163",8,"Con un polvo y otro polvo\nse formó una polvareda;\nuna copa y otra copa\nhacen una borrachera.",166,2,-1,171,"Con un polvo y otro polvo",0,4,"ea",-1,0,-1,0,127,127,"9163","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9164",8,"En lo profundo del mar\nsuspiraba una ballena\ny en el suspiro decía:\n“El que la seca, la llena”.",169,2,8,171,"Estrofa suelta",0,4,"ea",59,0,-1,0,127,127,"9164","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9165a",8,"Soy albañil, es muy cierto,\npero si soy parrandero,\na mí no me llora el cantinero\ncuando una copa yo bebo\nes porque traigo dinero.",166,2,-1,171,"El albañü’T",7,5,"eo",-1,0,-1,0,127,127,"9165a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9165b",8,"Soy albañil, es muy cierto,\npero si soy parrandero,\na mí no me llora el muerto\nni me grita el cantinero;\ncuando una copa yo oferto\nes porque traigo dinero.",166,2,-1,171,"El albañil",9,6,"eo",-1,0,-1,0,127,127,"9165b","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9166",8,"Y aquí se apagó el candil,\nseñores, hasta mañana;\nse despide este albañil,\nya se va a ganar más lana,\npa hacerle gasto al barril\nlos seis días de la semana.",166,2,-1,171,"El albañil",9,6,"aa",4,0,-1,0,127,127,"9166","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9167",8,"De todos soy descendiente\ncuando me pongo a tomar:\nmi padre es el aguardiente,\nmi padrino es el mezcal,\nel refino es mi pariente\ny el pulque, hermano carnal.",171,2,4,171,"El querreque",9,6,"a",1,0,-1,0,127,127,"9167","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9168",8,"A mí nada se me olvida,\ntodo lo cargo en la mente;\nahora que voy de partida\nte voy a dejar presente,\nque en mi casa la comida\nla guisan con aguardiente.",171,2,4,171,"Zapateado",9,6,"ee",15,0,-1,0,128,128,"9168","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9169",8,"Si lo fueras a mi casa,\nvieras el mesa tendida,\ncon su cántaro el tesgüino\ny su botella de vino.",172,2,23,171,"Canción de un indito",5,4,"io",199,0,-1,0,128,128,"9169","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9170",8,"Y échale agua, cielo viejo,\npa que nazcan magueyitos;\nno le hace que nazcan ciegos,\ncon que nazcan borrachitos;\nya viene el estado seco;\nhay que echar otros traguitos.",166,2,-1,171,"Los paseos de Santa Anita",9,6,"io",254,0,-1,0,128,128,"9170","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9172",8,"A caballo, bien armado\ny con muchos tecolines,\na beber he de llevarte\nla tuba de los Martínez.",166,2,-1,171,"El tubero",0,4,"ie",627,0,-1,0,128,128,"9172","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9173",8,"Esta noche corro gallo\nhasta no encontrar velorio,\npara preguntarle al muerto\nsi hay pulque en el purgatorio.",187,2,12,171,"La presumida. Estrofa suelta",0,4,"oo",551,0,-1,0,128,128,"9173","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9174",8,"Para mí todo es una gloria,\neste cantar es muy rudo;\npara mal de mi memoria,\ntodos los días ando crudo.",167,2,2,171,"Estrofa suelta, El caballito",1,4,"uo",191,0,-1,0,128,128,"9174","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9175",8,"Si el día lunes me amanece\nmi estómago encrudecido,\nme curo antes de que empiece\ncon la cuchara a hacer ruido,\ny al medio día, si se ofrece,\nme echo un pulmex decidido.",166,2,-1,171,"El albañil",9,6,"io",101,0,-1,0,128,128,"9175","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9176",8,"Una vez tenía un dolor,\na mí me dieron la ruda;\ncomo quedé con la duda,\nyo le pregunté al doctor\ncon qué se cura la cruda.",167,2,2,171,"La azucena",7,5,"ua",144,0,-1,0,128,128,"9176","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9177",8,"Cantando y tomando vino,\nparado yo en una esquina,\nse me acaban las botellas\ny me meto a las cantinas.",166,2,-1,171,"El valiente de San Juan del Río",0,4,"ia",-1,0,-1,0,129,129,"9177","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9178",8,"Yo bebo vino, yo me emborracho,\ntambién le entro al vino mezcal;\nentro a las tiendas, bebo mis copas,\nunas de a medio, otras de a real.",166,2,-1,171,"Paloma blanca*’",3,4,"a",1,0,-1,0,129,129,"9178","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9179",8,"Soy un borracho imprudente,\nun borracho de confianza;\npero le digo a la gente\n—pero se lo digo de chanza—:\n“Cuando miro el aguardiente\nhasta me gruñe la panza”.",175,2,6,171,"La huazanga",9,6,"aa",163,0,-1,0,129,129,"9179","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9180",8,"Soy borracho y pertinente,\nque al tomar no hace tonteras;\nuna copa de aguardiente\nquisiera que se volviera\nun arroyo permanente,\ny que de él me mantuviera.",169,2,8,171,"La morena",9,6,"ea",44,0,-1,0,129,129,"9180","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9181",8,"Toda mi vida he sido borracho:\n¿qué haré yo con mi suerte infeliz?\nY si al morir me trajeran una copa,\nsubiría a la gloria más feliz.",166,2,-1,171,"El borracho",3,4,"i",335,0,-1,0,129,129,"9181","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9182",8,"Tengo hambre, y no sé por qué,\nserá porque no he comido;\nsi no tienen de comer,\ndemen aunque sea un café:\naguardiente no les pido,\nporque ya me emborraché.",175,2,6,171,"El fandanguito",9,6,"e",77,0,-1,0,129,129,"9182","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9183",8,"Si me emborracho,\nes porque a mí me gusta el trago;\nsi tomo vino,\nyo a naiden le pido fiado.",166,2,-1,171,"El abandonado",3,4,"ao",-1,0,-1,0,129,129,"9183","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9184",8,"Mucho me gusta el rompope,\nni lo quiero inventar,\nporque, empezando a tomar,\nparece que ando al galope.\nEl vino y el tejocote\nme lo dan por medicina;\neso es lo que a mí me arruina,\nporque lo tomo en deseo;\nal tomar lo que yo veo,\nyo me arrimé a una cantina.",171,2,4,171,"Zapateado",18,10,"ia",11,0,-1,0,129,129,"9184","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9186",8,"Ándele, señora,\nsírvame un café;\nhoy ando borracho,\nmañana pagaré.",176,2,3,171,"El borracho impertinente",0,4,"e",77,0,-1,0,130,130,"9186","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9187",8,"Las copas son de a quinto:\nno les tomo sabor;\npóngamelas más fuertes,\nque para mí es mejor.",176,2,3,171,"El borracho impertinente. Estrofa suelta",0,4,"o",72,0,-1,0,130,130,"9187","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9188",8,"Y oiga, señor dependiente,\ndueño de este cachivache,\ndespácheme a lo decente,\naunque con él me emborrache:\nuna copa de aguardiente\ny el resbalón, de tepache.",171,2,4,171,"La tarasca",9,6,"ae",531,0,-1,0,130,130,"9188","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9189",8,"Una copa de aguardiente\nque yo me vaya bebiendo;\nya me voy, mañana vengo\ncon la hoja del laurel.",169,2,8,171,"El cascabel",5,4,"e",-1,0,-1,0,130,130,"9189","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9190",8,"A los hombres, pa su nana,\nlos muchachos, al montón,\ny como soy borrachón,\nme tomo una a su salud.",177,2,18,171,"Estrofa suelta",5,4,"u",-1,0,-1,0,130,130,"9190","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9191a",8,"Acaba de anochecer,\ny a una tienda voy entrando;\nesos que me están mirando\ndicen que llego a beber\ny a seguirme emborrachando.",171,2,4,171,"El siquisirí",7,5,"ao",33,0,-1,0,130,130,"9191a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9191b",8,"Acaba de amanecer,\ny a una tienda voy entrando;\nlos que no me pueden ver\nno más se quedan mirando;\ndicen: “Ésa va a beber,\ny aguardiente está tomando”.",166,2,-1,171,"El Cupido",9,6,"ao",33,0,-1,0,130,130,"9191b","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9192",8,"Andando de vagabundo,\nme encontré a Santo Tomás,\ny me dijo a lo profundo:\n“Mira qué borracho vas:\nése es el gusto del mundo,\nechando copas nada más”.",187,2,12,171,"El borrachito; La huazanga; Estrofa suelta",9,6,"a",51,0,-1,0,130,130,"9192","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9193",8,"Siendo un borracho de casta,\npor cantinas y cantones\nando, que el hambre me arrastra\nen busca de unos bocoles;\nfui a rasguñar la canasta\nen busca de unos tochones.",167,2,2,171,"El borracho",9,6,"oe",-1,0,-1,0,130,130,"9193","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9194",8,"Siendo un borracho de casta,\nandando en la borrachera,\nya cuando el hambre me arrastra,\ny por un simple tontera,\nfui a rasguñar la canasta,\nfui a dar con la ratonera.",167,2,2,171,"El borracho",9,6,"ea",44,0,-1,0,131,131,"9194","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9195",8,"Me dicen el borrachito\nporque me paso tomando;\na la vuelta voy cantando;\ntambién le hago al borrachito:\nme voy paso a pasito.",171,2,4,171,"El borracho",7,5,"io",119,0,-1,0,131,131,"9195","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9196",8,"Me dicen que soy borracho,\npero yo no he de pedir\nque por favor me la curen,\naunque me vaya a morir.",166,2,-1,171,"El borrachito",0,4,"i",157,0,-1,0,131,131,"9196","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9197",8,"Estoy borracho,\ndice la gente,\nestoy borracho\ncon aguardiente.",166,2,-1,171,"El borrachito",6,4,"ee",15,0,-1,0,131,131,"9197","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9198",8,"Estoy borracho,\ndice don Juan,\nestoy borracho\ncon catalán.",166,2,-1,171,"El borrachito",6,4,"a",147,0,-1,0,131,131,"9198","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9200",8,"¡Y ay, ay, ay, ayl,\n¡qué borracho vengo!\nY ábreme la puerta,\nque me ando cayendo:\nde ventanas y paredes\nme he venido deteniendo.",166,2,-1,171,"Con un polvo y otro polvo",9,6,"eo",52,0,-1,0,131,131,"9200","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9201",8,"No se canse de quererme,\nque aunque tome yo tequila,\nno me ha de ver campaneando\ncomo badajo de esquila.",166,2,-1,171,"La chaparrita",0,4,"ia",427,0,-1,0,131,131,"9201","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9202",8,"Valentina, Valentina,\nrendido estoy a tus pies;\nsi es porque me ves borracho,\nmañana ya no me yes.",166,2,-1,171,"La Valentina^",0,4,"e",218,0,-1,0,131,131,"9202","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9203",8,"Si porque bebo tequila,\nmañana tomo jerez;\nsi porque me ves borracho,\nmañana ya no me ves.",166,2,-1,171,"La Valentina",0,4,"e",218,0,-1,0,131,131,"9203","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9204",8,"Si es porque tomo tequila,\nmañana tomo jerez;\nsi me han de matar mañana,\nque me maten de una vez.",166,2,-1,171,"La Valentina’H",0,4,"e",150,0,-1,0,132,132,"9204","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9205",8,"Adiós y adiós,\nadiós, aguardiente, adiós;\nya siento que estoy borracho (aguardiente):\nsea por ’l amor de Dios.",187,2,12,171,"La diosa",3,4,"o",87,0,-1,0,132,132,"9205","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9206",8,"Me dicen que estoy borracho,\ny eso es purita mentira,\npues apenas seis botellas\nme he tomado de tequila.",166,2,-1,171,"El borrachito",0,4,"ia",-1,0,-1,0,132,132,"9206","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9207",8,"¡Caray, qué borracho vengo!,\npor más que no traigo nada;\nsi yo borracho anduviera,\ntodito me bamboleara.",166,2,-1,171,"El borracho’T",0,4,"aa",-1,0,-1,0,132,132,"9207","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9208",8,"Ando borracho,\nme ando cayendo;\nno tengo nada,\nno más me ando haciendo.",177,2,18,171,"Estrofa suelta",6,4,"eo",52,0,-1,0,132,132,"9208","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9210",8,"¿Pa qué me sirve la vida,\ncuando la traigo amargada?\nYo la cambio por tequila,\nque pa mí no vale nada.",166,2,-1,171,"No más me aguanto",0,4,"aa",49,0,-1,0,132,132,"9210","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9211",8,"Mientras tengan licor las botellas,\nbrindemos con ellas hasta emborrachar,\nrecordando que tal vez mañana\nclarín de campaña nos llame a pelear.",168,2,11,171,"Clarín de campaña",3,4,"a",21,0,-1,0,132,132,"9211","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9212",8,"Mientras tengan licor las botellas,\nbebamos en ellas hasta concluir,\nolvidando que tal vez mañana\nla ronca campana nos llame a morir.",166,2,-1,171,"Clarín de campaña",3,4,"i",157,0,-1,0,132,132,"9212","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9213",8,"Ya el mundo se va a acabar,\nsegún están anunciando;\npara no sentir el susto,\nvámonos emborrachando.",166,2,-1,171,"Estrofa suelta",0,4,"ao",33,0,-1,0,132,132,"9213","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9215",8,"En fin, amigos y amigas,\nvámonos emborrachando;\nporque todos nos anuncian\nque el mundo se está acabando.",166,2,-1,171,"Estrofa suelta",0,4,"ao",33,0,-1,0,133,133,"9215","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9216",8,"Todo el que al vicio se entrega,\naunque haya sido hombre honrado,\nvive desacreditado,\nhasta otros extremos llega.",169,2,8,171,"Estrofa suelta",11,4,"ea",257,0,-1,0,133,133,"9216","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9217",8,"El aguardiente de caña\nes un hombre majadero,\nque se sube a la cabeza,\ncomo si fuera sombrero.",171,2,4,171,"El aguardiente",0,4,"eo",38,0,-1,0,133,133,"9217","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9218",8,"El hombre que es borracho\nespera y desespera,\ny no más anda pensando\nen la pura borrachera.",176,2,3,171,"El borracho impertinente; Estrofa suelta",0,4,"ea",44,0,-1,0,133,133,"9218","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9219",8,"Cuando el borracho no cae,\nno ha de faltar quien lo tumbe;\naunque a mí nada me incumbe,\npero les diré que no hay\nborracho que coma lumbre.",167,2,2,171,"El borracho",7,5,"ue",-1,0,-1,0,133,133,"9219","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9220",8,"Cuando tomo el aguardiente\npido la copa y la pago,\ny le digo al dependiente:\n“Quítese, que traigo trago;\nen mi juicio soy decente,\nborracho, no sé lo que hago”.",171,2,4,171,"El borracho; Estrofa suelta",9,6,"ao",207,0,-1,0,133,133,"9220","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9221",8,"Dicen que soy borracho,\nque no me puedo tener en pie:\n¡maldita la taberna\ny quien en cascos puso el café!",178,2,10,171,"Cuánto me has hecho sufrir",3,4,"e",77,0,-1,0,133,133,"9221","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9222",8,"Cantinas, muchas cantinas\nrecorro de arriba abajo;\nestoy hasta el mero fondo,\nno puedo caer más bajo.",166,2,-1,171,"Que me lleve el diablo",0,4,"ao",168,0,-1,0,133,133,"9222","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9223",8,"Me encontré con la huesuda,\nsin saber que era la muerte;\nme dijo la testaruda:\n“No bebas el aguardiente;\nvas a morir de una cruda:\n¡qué amarga será tu suerte!”",167,2,2,171,"El querreque",9,6,"ee",-1,0,-1,0,134,134,"9223","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9224",8,"Yo soy el arriero torpe,\nque me quedo en la calle volando,\npor andar en la cantina\ny andarme emborrachando.",171,2,4,171,"Los arrieros",3,4,"ao",33,0,-1,0,134,134,"9224","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9225",8,"Por andar de borracho,\nperdí yo mi camisa:\ny eso más merezco\npor andar en la bebida.",166,2,-1,171,"El borracho impertinente",0,4,"ia",-1,0,-1,0,134,134,"9225","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9226",8,"Por andar de borracho,\nperdí yo mi frazada:\ny eso más merezco\npor andar en la paseada.",176,2,3,171,"El borracho impertinente",0,4,"aa",49,0,-1,0,134,134,"9226","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9227",8,"Por andar de borracho,\nperdí yo mis zapatos:\ny eso y más merezco\npor andar en malos pasos.",176,2,3,171,"El borracho impertinente",0,4,"ao",-1,0,-1,0,134,134,"9227","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9228",8,"Por andar de borracho,\nperdí yo mi sombrero:\ny eso más merezco\npor andar de mitotero.",176,2,3,171,"El borracho impertinente",0,4,"eo",-1,0,-1,0,134,134,"9228","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9229",8,"Por andar de borracho,\nperdí mis pantalones:\ny eso y más merezco\npor andar en vacilones.",166,2,-1,171,"Estrofa suelta, El borracho impertinente",0,4,"oe",34,0,-1,0,134,134,"9229","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9230",8,"Ya voy a dejar de beber,\nporque me dicen “El briago”;\nsólo les quiero hacer ver\nque no nada más yo lo hago:\na las mujeres también\nles gusta tomarse un trago.",171,2,4,171,"El siquisirí",9,6,"ao",207,0,-1,0,134,134,"9230","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9231",8,"Adiós, pues, mis cuatezones,\nadiós, mis pulques curados;\nya me mojé los calzones;\nya me voy avergonzado;\nhasta el año venidero,\nsi no estoy adifuntado.",166,2,-1,171,"Los paseos de Santa Anita",9,6,"ao",14,0,-1,0,134,134,"9231","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9233",8,"Mi madre me regañaba\ncuando yo me emborrachaba;\nsiempre la hallaba afligida,\ny le decía: “Ya no llores,\na mí no me pasa nada”.",167,2,2,171,"El huerfanito",7,5,"aa",-1,0,-1,0,135,135,"9233","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9234",8,"Mi mamá a mí me regaña,\nporque soy muy testarudo;\nme dice: “Deja esa maña,\nese vicio tan agudo”.\n¡Me gusta tanto la caña,\nque quisiera ser embudo!",166,2,-1,171,"El pájaro cú; La Cecilia, El huerfanito",9,6,"uo",191,0,-1,0,135,135,"9234","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9235",8,"A la tripa, tripa (caramba),\ntripa de mapache,\nmi mamá no quiere (Canelo)\ny si acaso lo hago (caramba)\nque sea con tepache.",171,2,4,171,"El Canelo",7,5,"ae",531,0,-1,0,135,135,"9235","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9236",8,"A la tripa, tripa (retripa),\ntripa de cochino,\nmi mamá no quiere (Canelo)\nque yo tome vino,\ny si acaso tomo (Canelo),\nque sea del refino.",171,2,4,171,"El Canelo",9,6,"io",199,0,-1,0,135,135,"9236","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9237",8,"Aunque quites la escalera,\npara que ya no suba,\nhe de subirme a la palma\npara beberme la tuba.",166,2,-1,171,"El tubero",0,4,"ua",628,0,-1,0,135,135,"9237","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9240",8,"Como que te vienes,\ncomo que te vas;\npero vida mía,\n¡qué borracho estás!",166,2,-1,171,"El palmero",0,4,"a",51,0,-1,0,136,136,"9240","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9242",8,"Andando en la borrachera,\nme dijo una con valor:\n“Usted será pagador,\npero es pelón si se encuera”.",166,2,-1,171,"Estrofa suelta",11,4,"ea",44,0,-1,0,136,136,"9242","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9243",8,"Venía todo tembeleque,\nya la cruda me mataba;\ny como dijo el querreque;\ncuando yo tenía le daba,\ny ahora que no tengo ¿de qué?",191,2,1,172,"El querreque",7,5,"e",-1,0,-1,0,140,140,"9243","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9244",8,"Ya no quiero ser borracho,\nya me voy a separar;\nya no tomo en chiquihuite,\nporque se puede tirar.",176,2,3,172,"El borracho",0,4,"a",21,0,-1,0,140,140,"9244","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9245",8,"Ya no quiero ser borracho,\nya voy a cambiar de vida;\nya no tomo en chiquihuite,\nporque todo se me tira.",166,2,-1,172,"El borracho",0,4,"ia",-1,0,-1,0,140,140,"9245","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9246",8,"Ya no quiero ser borracho,\nya me voy a detener\npor ventanas y paredes\npara no dejarme caer.",173,2,17,172,"El borracho",0,4,"e",20,0,-1,0,140,140,"9246","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9247",8,"No iré a rezar al templo,\nporque estoy cojo;\niré a la pulquería,\npoquito a poco.",166,2,-1,172,"Estrofa suelta",6,4,"oo",-1,0,-1,0,140,140,"9247","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9248",8,"Nunca dejen de pasearse,\nni se aflijan de tontera;\nbeber, no más hasta caerse;\nlo demás es borrachera.",166,2,-1,172,"Estrofa suelta",0,4,"ea",44,0,-1,0,140,140,"9248","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9249",8,"Es cierto que soy un briago,\nno se me puede quitar;\ny si yo les pido un trago,\nno me lo deben negar,\nporque si yo pido fiado,\nnunca les he de pagar.",175,2,6,172,"La huazanga",9,6,"a",21,0,-1,0,140,140,"9249","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9250",8,"El día veinte de febrero\nhubo carrera citada;\nlos Manueles en acuerdo\nla sonaron muy mentada.",166,2,-1,173,"Estrofa suelta",0,4,"aa",49,0,-1,0,144,144,"9250","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9251",8,"Dos elegantes gallillos\nvan a pelear con honor:\nel giro mexicanillo\ncontra el barbón español;\nsuéltenlos ya con la idea;\nun golpe sea el desafío,\na ver cuál cacaraquea.",166,2,-1,173,"Estrofa suelta",4,7,"ea",54,0,-1,0,144,144,"9251","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9252",8,"Gallerito, gallerito,\nvete pa bajo del río,\nvete a las peleas formales\nque se hacen en el Bajío,\ndonde los hombres son machos\ny le entran al desafío.",166,2,-1,173,"El gallerito’’",9,6,"io",3,0,-1,0,144,144,"9252","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9253",8,"Gallerito, gallerito,\nque ganaste la partida,\nque tratándose de gallos,\nte juegas hasta la vida;\ngallerito, gallerito,\nde mi tierra tan querida.",166,2,-1,173,"El gallerito",9,6,"ia",37,0,-1,0,144,144,"9253","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9254",8,"Gallerito, gallerito,\ndel palenque de Silao,\nno le temas al grandote,\naunque lo veas colorado,\nque nunca ha habido chipote\nque salga del mismo lado.",166,2,-1,173,"El gallerito",9,6,"ao",14,0,-1,0,144,144,"9254","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9255",8,"Entren y vayan entrando;\nse va y se fue y no lo reclamo.\nAl ir ganando\nse va pagando,\ny al ir perdiendo\nse va recogiendo.",166,2,-1,173,"El cubilete",9,6,"eo",52,0,-1,0,144,144,"9255","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9256",8,"Entren y vayan entrando,\nvayan todos apostando;\ncon cinco se sacan seis\ny con seis se sacan diez.",166,2,-1,173,"El cubilete",5,4,"e",-1,0,-1,0,144,144,"9256","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9259",8,"Voy a comprar mi baraja\npara enseñarme a jugar,\njugando a todas las briscas,\nmenos malilla y conquián.",166,2,-1,173,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,145,145,"9259","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9260",8,"Ya salió a bailar\nla sota y el rey,\nmi caballo blanco,\nconcha de carey.",171,2,4,173,"Los arrieros",0,4,"e",133,0,-1,0,145,145,"9260","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9261",8,"A la sota y al caballo\nsiempre apuesto mi dinero;\na la sota por bonita\ny al caballo por ligero.",169,2,8,173,"El novillo despuntado; El conejo; El dos",0,4,"eo",38,0,-1,0,145,145,"9261","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9262",8,"La sota de la baraja\nes mi mera prometida,\nporque ella jamás se raja,\npuesto que tiene salida.",166,2,-1,173,"Los vaqueros",1,4,"ia",37,0,-1,0,145,145,"9262","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9264",8,"Por el alto doy cincuenta,\npor el entre pie, el de diez,\npor el mete y saca, cinco,\npor el dale y dale, tres.",166,2,-1,173,"Por lo alto doy cincuenta",0,4,"e",218,0,-1,0,145,145,"9264","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9266",8,"Ven, mi querido dos,\ncompañerito del cuatro;\néste es mi querido dos,\ncompañerito del cuatro.",176,2,3,173,"El dos",1,4,"ao",-1,0,-1,0,146,146,"9266","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9267",8,"Éste es mi querido dos,\nque diga la preferida;\nen ella juego mi dinero,\nsi es posible, hasta la vida.",176,2,3,173,"El dos",0,4,"ia",37,0,-1,0,146,146,"9267","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9269",8,"¡Qué de malas, qué de malas\nen el juego siempre estoy!\nSi voy chicas, vienen grandes,\ny si grandes, chicas son.",166,2,-1,173,"Estrofa suelta",0,4,"o",-1,0,-1,0,146,146,"9269","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9270",8,"Si me llevan a enterrar,\nno teniendo más alhajas,\njugaré hasta la mortaja\npor no dejar de jugar.",166,2,-1,173,"Estrofa suelta",5,4,"a",21,0,-1,0,146,146,"9270","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9271",8,"Ya Margarita se va,\nya se puso su sombrero;\ndice que aquí nos veremos\nel día primero de enero.",168,2,11,174,"Ya no quiero ser sereno",0,4,"eo",-1,0,-1,0,150,150,"9271","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9272",8,"Ya Margarita se va,\nya está haciendo su maleta;\ndice que aquí nos veremos\nel día primero de mayo.",168,2,11,174,"Ya no quiero ser sereno",5,4,"ao",-1,0,-1,0,150,150,"9272","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9273",8,"Margarita ya se va,\nya se va, ya se la llevan,\na la tierra de los indios,\na comer carne de yegua.",168,2,11,174,"Margarita",0,4,"ea",-1,0,-1,0,150,150,"9273","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9274",8,"Ya la guarecita se va,\nya se montó en su mula;\ndice que no ha de volver\nhasta llegar a Capula.",166,2,-1,174,"Felicitación indígena’",0,4,"ua",547,0,-1,0,150,150,"9274","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9275",8,"Ya la guarecita se va,\nya se cargó a su muchacho;\ndice que no volverá\nhasta llegar a su rancho.",176,2,3,174,"Felicitación indígena",0,4,"ao",-1,0,-1,0,150,150,"9275","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9276",8,"Ya la guarecita se va,\nya se cargó su quimil;\ndice que no ha de volver\nhasta los truenos de abril.",176,2,3,174,"Felicitación indígena",0,4,"i",290,0,-1,0,150,150,"9276","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9277",8,"Ya la guarecita se va,\ndice que no ha de venir\nhasta llegar a Taretán,\na comer panocha prieta.",176,2,3,174,"Felicitación indígena",5,4,"ea",-1,0,-1,0,150,150,"9277","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9278",8,"La meca le dijo al meco:\n—¿Por qué estás tan colorado?\n—De comer naranjas agrias\ny pasearme en El Venado.",178,2,10,174,"Los mecos",0,4,"ao",14,0,-1,0,150,150,"9278","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9279a",8,"La meca le dijo al meco:\n—¿Por qué estás tan amarillo?\n—De comer guayabas verdes\ny pasear por el saltillo.",178,2,10,174,"Los mecos",0,4,"io",228,0,-1,0,151,151,"9279a","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9280",8,"—Cihualteco, ¿de ónde vienes?,\ndime, ¿para dónde vas?\n—Tengo tres días caminando\npara el puerto de San Blas.",166,2,-1,174,"El Cihualteco",0,4,"a",51,0,-1,0,151,151,"9280","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9281",8,"Al otro lado del mar\nhay una tienda, “La Unión”,\ncon un letrero que dice:\n“Ya se va la embarcación”.",178,2,10,174,"La embarcación",0,4,"o",31,0,-1,0,151,151,"9281","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9282a",8,"Balajú se fue a la guerra\ny no me quiso llevar;\nle dijo a su compañera:\n“Vámonos a navegar”.",171,2,4,174,"El Balajú",0,4,"a",21,0,-1,0,151,151,"9282a","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9283",8,"Balajú se va mañana,\nque no me quiere llevar;\n¡ay, el pobre Balajú!,\nque yo me ten’ que quedar.",171,2,4,174,"El Balajú",0,4,"a",21,0,-1,0,151,151,"9283","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9284",8,"Levántense, valedores,\nque es muy larga la jomada,\nque a las tres de la mañana\nllegaremos a Tlaxcala.",182,2,21,174,"El carnaval",0,4,"aa",-1,0,-1,0,151,151,"9284","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9285",8,"Campanitas del santuario,\n¡cuándo se repicarán!,\ny que avisen que nos vamos\npara Villa de San Juan.",166,2,-1,174,"cuándo se repicarán!, y que avisen que nos vamos para Villa de San Juan. [Las campanitas",0,4,"a",147,0,-1,0,152,152,"9285","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9286",8,"Vámonos a otros lugares,\na la estación del verano,\na ver las chinas del brazo,\ny una cerveza en la mano.",171,2,4,174,"El Ahualulco",0,4,"ao",-1,0,-1,0,152,152,"9286","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9287",8,"Si vamos a Tlalixcoyan,\ntenemos que darnos prisa;\nel tiempo hay que aprovecharlo;\nhay que visitar a Galo,\na Lino, José y a Tirsa.",171,2,4,174,"Estampa jarocha",7,5,"ia",-1,0,-1,0,152,152,"9287","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9288",8,"¡Ay, vámonos en el trenl,\n¡ay, vámonos en el carro!,\nque yo fumaré tabaco,\nporque no traigo cigarro.",171,2,4,174,"La manta",0,4,"ao",-1,0,-1,0,152,152,"9288","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9289",8,"Y arriba y arriba,\ny allá vas tú,\ny en el tren de Alvarado\npa Veracruz.",171,2,4,174,"La bamba’7",6,4,"u",-1,0,-1,0,152,152,"9289","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9290",8,"Ándale, chulo Jerez,\nantes de que yo me vaya;\ntú sabes que no hay un día\nde Veracruz a Celaya.",171,2,4,174,"El Jerez",0,4,"aa",404,0,-1,0,152,152,"9290","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9291",8,"Guajito, vente, pues,\nvámonos, vámonos a Santa Inés;\nguajito, toma un real,\ncompra tus dulces en el portal.",166,2,-1,174,"El guajito",3,4,"a",1,0,-1,0,152,152,"9291","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9292",8,"[Ay!, vuela, revuela, vuela\ny revuela sin cesar;\nvámonos para otra tierra,\nque aquí no quieres estar.",171,2,4,174,"La guacamaya",0,4,"a",21,0,-1,0,152,152,"9292","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9293",8,"Me embarqué en una falúa,\nen un barco navegué;\nanda, vete tú por agua,\nque yo por tierra me iré.",169,2,8,174,"Estrofa suelta",0,4,"e",77,0,-1,0,152,152,"9293","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9294",8,"Cuando salí de La Habana,\n¡válgame Dios!,\nnadie supo mi salida,\nsino tú y yo.",168,2,11,174,"La paloma",6,4,"o",-1,0,-1,0,152,152,"9294","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9295",8,"Me voy para Mazatlán,\nchaparrita, quédate a Dios,\nvoy a ver a mis amigos,\nque me mandan saludar.",173,2,17,174,"La chaparrita",5,4,"a",-1,0,-1,0,153,153,"9295","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9296",8,"Ya mi Julia ya lo sabe,\nya le puse un telegrama;\nadiós, todos mis amigos,\nporque ya me voy mañana.",173,2,17,174,"Julia",0,4,"aa",-1,0,-1,0,153,153,"9296","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9297",8,"De mañana en ocho días\nsólo Dios dónde estaré;\notros aires me darán,\notros suelos pisaré.",187,2,12,174,"Estrofa suelta",0,4,"e",77,0,-1,0,153,153,"9297","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9298",8,"De mañana en ocho días\nsabe Dios dónde estaremos;\notros aires nos darán\ny otras tierras pisaremos.",175,2,6,174,"De mañana en ocho días",0,4,"eo",127,0,-1,0,153,153,"9298","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9299",8,"Cuando voy a la Huasteca\nvoy corriendo por el plan;\nen mi caballo retinto\nvoy con rumbo a Ahuatitlán.",167,2,2,174,"Las chaparreras",0,4,"a",147,0,-1,0,153,153,"9299","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9300",8,"El sol calienta la roca,\nya se muere el zacatal,\ny ya siento un ansia loca\nde llegar a mi jacal.",166,2,-1,174,"La potranca colorada",1,4,"a",1,0,-1,0,153,153,"9300","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9301",8,"El sábado fui al baile,\nel domingo me regresé;\nfui en mi caballo prieto\ny en él me devolví.",190,2,20,174,"Canción del venado",5,4,"i",-1,0,-1,0,153,153,"9301","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9302",8,"Me pasé a ver los costeños,\na ver dónde quedo bien;\nando penando de sueño,\nse me atravesó un vaivén.",166,2,-1,174,"La india",0,4,"e",242,0,-1,0,153,153,"9302","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9303",8,"Dicen que una palomita\nse pasó la mar volando;\nyo también me lo pasara\nen un barco navegando.",171,2,4,174,"El palomo",0,4,"ao",33,0,-1,0,153,153,"9303","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9304",8,"Como dicen los pajaritos:\n“El barco lo manda Dios”;\ndía a día me lo pasara\nen un barco navegando.",166,2,-1,174,"El pájaro cú",5,4,"ao",-1,0,-1,0,153,153,"9304","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9305",8,"En Guaymas desembarqué\nen un buque nacional,\ny 'hora cantarán alegres\nlos pájaros cardenal.",166,2,-1,174,"Viborita de la mar; Al pasar por los laureles; La callejera’’",0,4,"a",1,0,-1,0,154,154,"9305","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9306",8,"Me voy y me voy,\nme voy a embarcar,\ncon los marineros\nque van a la mar.",170,2,7,174,"La Malagueña curreña",0,4,"a",21,0,-1,0,154,154,"9306","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9307",8,"Yo ya me voy\npara la costa,\ndonde aterriza\nese Mendoza.",169,2,8,174,"Jamiltepec",6,4,"oa",-1,0,-1,0,154,154,"9307","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9308",8,"De tierras lejanas vengo\ny a tierras lejanas voy;\nóigame usted, señorito,\nmire lo triste que estoy.",178,2,10,174,"En el nombre sea de Dios",0,4,"o",112,0,-1,0,154,154,"9308","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9309",8,"Oigan y oigan y oigan,\nqué silbidos da;\nparece que va llegando\nal pueblo de La Piedad.",166,2,-1,174,"El tren",0,4,"a",-1,0,-1,0,154,154,"9309","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9310",8,"Oigan, señores, el tren,\noigan el tren caminar;\nparece que va llegando\nal puerto de Mazatlán.",173,2,17,174,"El tren’’",0,4,"a",-1,0,-1,0,154,154,"9310","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9311",8,"Qué silbidos da el tren\ncuando llega a la estación;\ntintineos de la campana,\nal ir de la población.",166,2,-1,174,"En busca de Margarita",0,4,"o",31,0,-1,0,154,154,"9311","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9312",8,"¡Ay, trenecito!, ya llegaste,\nconociste tu lugar;\nen durmientes y en el riel\nmuy bien que puedes andar.",166,2,-1,174,"En busca de Margarita",0,4,"a",21,0,-1,0,154,154,"9312","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9313",8,"Cuemavaca es mi tierra,\ny a México vine a dar;\nen el tren con gusto vine:\nhasta me puse a cantar.",166,2,-1,174,"En busca de Margarita",0,4,"a",21,0,-1,0,154,154,"9313","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9314",8,"Ya vine, ya estoy aquí,\nacabado de llegar,\ny ahorita me vengo apeando\ndel Ferrocarril Central.",186,2,27,174,"Baile de la muñeca; En busca de Margarita",3,4,"a",-1,0,-1,0,154,154,"9314","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9315",8,"Cuando llegué a Buenavista\nyo no me quería bajar,\ny me dijo el conductor:\n“Llegó usté a la capital”.",166,2,-1,174,"En busca de Margarita",0,4,"a",-1,0,-1,0,155,155,"9315","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9316",8,"Yo con la idea de bajarme\nal salir de la estación;\nlos maloras cargadores\nno perdieron la ocasión.",166,2,-1,174,"En busca de Margarita",0,4,"o",31,0,-1,0,155,155,"9316","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9317",8,"Y estando solo, dormido,\nen la cárcel una noche,\nsoñé que ya había salido,\nque andaba paseando en coche\npor los Estados Unidos.",171,2,4,174,"El siquisirí",7,5,"io",-1,0,-1,0,155,155,"9317","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9318",8,"Anoche al infierno fui,\ntambién en la gloria estuve,\ncon lo que más me entretuve;\nno sé ni cómo volví.",166,2,-1,175,"Estrofa suelta",11,4,"i",23,0,-1,0,158,158,"9318","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9319",8,"Ya me voy para San Juan,\na poner una fondita;\nsi me salen los ladrones,\n¡ay, qué susto, comadrita!",178,2,10,175,"Estrofa suelta",0,4,"ia",50,0,-1,0,158,158,"9319","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9320",8,"Yo me quiero divertir\nen La Habana,\ncon tu hermana\nen la población.",168,2,11,175,"El cateto",3,4,"o",-1,0,-1,0,158,158,"9320","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9321",8,"Viniendo de Veracruz\nme encontré con Don Quijote\ny con el llamado Huizote\ny también con don Jesús.",171,2,4,175,"El pájaro cú",11,4,"u",270,0,-1,0,158,158,"9321","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9323",8,"Me embarqué en un coche urbano\na recorrer la nación,\ntodo el país mexicano\ny varia congregación,\ny por falta de un areoplano\nno llegué hasta tu balcón.",171,2,4,175,"La morena",9,6,"o",31,0,-1,0,158,158,"9323","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9324",8,"Conocí la embarcación\ndonde venía el Rey de Hungría;\nallí conocí al patrón,\nque era el que la dirigía;\nera Cristóbal Colón,\nque de la Europa venía.",167,2,2,175,"La Petenera; La sirena",9,6,"ia",0,0,-1,0,159,159,"9324","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9325",8,"Yo me vine de Turquía\nen un barco muy chiquito,\ny como venía solito,\nel viento me devolvía;\npara llegar a Tampico\nun caimán traiba de guía.",175,2,6,175,"El caimán",9,6,"ia",0,0,-1,0,159,159,"9325","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9326",8,"Mi voluntad no declina,\nni tampoco mi intención\nde comprarme una tonina\nen forma de un hidroavión,\npara pasearme por China\ny también por el Japón.",166,2,-1,175,"Estás en la plenitud",9,6,"o",31,0,-1,0,159,159,"9326","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9327",8,"Una vez yo me embarqué\nen un barco japonés,\ny al pasar por Alemania,\nme dijo un sabio francés:\n“En la costa americana\nalumbra el sol al revés”.",168,2,11,175,"La Petenera",9,6,"e",218,0,-1,0,159,159,"9327","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9328",8,"Comencé desde el océano:\nFrancia, París y Holanda;\ninspeccioné en aeroplano:\nSuecia, Noruega e Islandia\ny todo el Mediterráneo.",175,2,6,175,"La Petenera",7,5,"ao",-1,0,-1,0,159,159,"9328","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9329",8,"Vide a Lima y Puerto Bello,\nPanamá y el Guayaquil,\nBuenos Aires y Alguarico\ny la corte de Madrid.",171,2,4,175,"Estrofa suelta",0,4,"i",-1,0,-1,0,159,159,"9329","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9330",8,"Francia, París y España,\nRoma, Londres y Turquía,\npero Asia nos acompaña,\nPuerto Rico y Oceania;\nhay también la Gran Bretaña,\nÁfrica y la tierra mía.",175,2,6,175,"La Petenera",9,6,"ia",0,0,-1,0,159,159,"9330","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9331",8,"En el monte, siendo chico,\nme espantó a mí un animal,\ny ahora, grande, me explico\nque era el águila imperial,\ncon la serpiente en el pico,\nparada en ese nopal.",166,2,-1,176,"La morena",9,6,"a",1,0,-1,0,162,162,"9331","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9332",8,"iViva México, señores!,\n¡viva la Guadalupana!,\n¡y que viva para siempre\nla bandera mexicana!",186,2,27,176,"Baile de la muñeca’’",0,4,"aa",4,0,-1,0,162,162,"9332","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9333",8,"Verde, blanco y colorado,\nde eso es hecha la bandera,\npues no se ha hecho como quiera:\nha costado sangre y plata;\ny yo le digo a mi chata\nque Oaxaca nunca pierde\ny cuando pierde arrebata.",169,2,8,176,"Estrofa suelta",4,7,"aa",74,0,-1,0,162,162,"9333","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9334",8,"Ya no quiero ser sereno,\nni tampoco militar:\nlo que quiero es la bandera\nde la patria nacional.",178,2,10,176,"Ya no quiero ser sereno",0,4,"a",-1,0,-1,0,162,162,"9334","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9335",8,"El pabellón mexicano,\nel de las Tres Garantías.\n¡Viva Hidalgo, Benito Juárez\ny también Porfirio Díaz!",169,2,8,176,"Estrofa suelta",0,4,"ia",476,0,-1,0,162,162,"9335","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9336",8,"El tata cura que te dio vida\nmurió enseñando la libertad,\nque era insorgente moy decidida\ny que fue coco del Majestad.",166,2,-1,176,"Amo nequi",3,4,"a",16,0,-1,0,162,162,"9336","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9337",8,"Aunque mi México esté\ndébil por revoluciones,\npa defenderlo sus hijos\náenen sus buenos calzones.",166,2,-1,176,"El novillo despuntado",0,4,"oe",34,0,-1,0,162,162,"9337","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9338",8,"Que cese ya la discordia,\nque la paz impere un día,\npues la patria sufre mucho\npor la ambición tan impía.",166,2,-1,176,"Estrofa suelta",0,4,"ia",0,0,-1,0,163,163,"9338","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9339",8,"Por un cabo doy dos reales,\npor un sargento, un tostón,\npor el general Morelos\ndoy todo mi corazón.",166,2,-1,176,"Canción de Morelos; Estrofa suelta",0,4,"o",31,0,-1,0,163,163,"9339","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9340",8,"¡Viva don Pedro Moreno,\nel del fuerte del Sombrero!,\nque, no conociendo el miedo,\nen la lucha fue el primero.",166,2,-1,176,"¡Viva don Pedro Moreno!",0,4,"eo",-1,0,-1,0,163,163,"9340","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9341",8,"Aquí en Cuautla venceremos,\npues peleamos con afán;\npor eso los gachupines\ntienen ganas de volar.",166,2,-1,176,"Canción de Morelos",0,4,"a",-1,0,-1,0,163,163,"9341","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9342",8,"¡Viva y viva y viva\nel indio guerrero\ny los cincuenta mil flecheros\nde ese cerrillo de San Gremal!",166,2,-1,176,"A la Virgen de Guadalupe",3,4,"a",-1,0,-1,0,163,163,"9342","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9345",8,"Dicen los americanos\nque esta noche han de guerrear;\nyo prometo que les curo\nlas heridas con mezcal.",178,2,10,176,"El capotín",0,4,"a",-1,0,-1,0,163,163,"9345","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9346",8,"Soy soldado de Guerrero,\n¡viva la Federación!\nPor eso cantando digo:\n“¡Viva la Federación!”",176,2,3,176,"San Juan Betamo",0,4,"o",-1,0,-1,0,164,164,"9346","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9347",8,"Antes había unos soldados\nmuy valientes, sin comparación,\nque salían a guerrear contra Francia,\ndefendiendo la Federación.",178,2,10,176,"Don Simón",3,4,"o",31,0,-1,0,164,164,"9347","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9348",8,"Pa los fuertes de Loreto\ncomenzaron a tirar\nesas tropas de franceses,\nque gritaban sin cesar;\na los nuestros les decían:\n—¿Qué es de las piezas de pan?\n—¡Aguárdenlas, que áhi les van!",166,2,-1,176,"Las torres de Puebla",4,7,"a",147,0,-1,0,164,164,"9348","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9349",8,"Nos están tirando,\nnos están matando,\ncon una fuerza muy grande;\ncon rifles de a doce,\nde trece y catorce\ny pólvora diariamente.",166,2,-1,176,"Canción de Porfirio Díaz",9,6,"ee",-1,0,-1,0,164,164,"9349","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9350",8,"—¿Dónde estás, Zaragoza valiente?\n¿Dónde está tu lucido escuadrón?\n—A luchar por la patria ha marchado\na luchar y a morir con honor.",166,2,-1,176,"Las torres de Puebla",3,4,"o",-1,0,-1,0,164,164,"9350","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9351",8,"Con las barbas de Forey\nvoy a hacer un vaquerillo,\npa ponérselo al caballo\ndel valiente don Porfirio.",166,2,-1,176,"La cucaracha",0,4,"io",-1,0,-1,0,164,164,"9351","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9352",8,"Había alguien con honor,\nun coronel de Puebla,\nque llegando me contó:\n“Aunque a esta tierra no vuelva,\nme despido con honor”.",169,2,8,176,"Zapateado",7,5,"o",-1,0,-1,0,164,164,"9352","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9353",8,"El soldado del norte es muy pobre:\nsu vestido, una tosca mezclilla,\nsu divisa, una blusa amarilla,\npero nunca su patria vendió.",166,2,-1,176,"Las torres de Puebla",3,4,"o",-1,0,-1,0,164,164,"9353","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9354",8,"Arévalo está muy malo,\ncon dolores de barriga;\nFidencia lo va a curar\ncon piezas de artillería.",189,2,5,176,"Estrofa suelta",0,4,"ia",-1,0,-1,0,164,164,"9354","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9355",8,"No quiero paz,\nno quiero nada;\nlo que quiero son balazos\ncon el general Lozada.",166,2,-1,176,"Los colorados",3,4,"aa",49,0,-1,0,164,164,"9355","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9356",8,"Ya Zaragoza murió,\nya lo llevan a enterrar,\ncon su espada en la cintura,\nvestido a lo militar.",168,2,11,176,"El corrido de Zaragoza",0,4,"a",21,0,-1,0,165,165,"9356","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9357",8,"Ya con ésta me despido,\nrecemos una oración;\nque Dios reciba en su seno\ny les otorgue el perdón\na los que mueren con honra,\ncon inaudito valor.",166,2,-1,176,"Corrido de los rfiártires de Veracruz",9,6,"o",-1,0,-1,0,165,165,"9357","",0,"","","",72,0,0,[],"",""],["frenk_t4-n9358",8,"Despierta, Pedro Moreno,\nmira lo que está pasando:\nson las tropas de Negrete,\nque al Fuerte lo van rodeando.",166,2,-1,176,"¡Viva don Pedro Moreno!",0,4,"ao",33,0,-1,0,165,165,"9358","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9359",8,"¡Ay, rema, ay, rema!\n¡ay rema, que se hace tarde!\nNo se lo vaya a llevar (¡ay, mamá!)\nel señor don Juan Lagarde.",166,2,-1,176,"Canción de Morelos",3,4,"ae",344,0,-1,0,165,165,"9359","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9360",8,"¡Ay, rema, ay, rema!,\n¡ay, rema pa la ribera!\nNo se lo vaya a llevar (¡ay, mamá!)\nel Pelón de la Barrera.",166,2,-1,176,"Canción de Morelos",3,4,"ea",44,0,-1,0,165,165,"9360","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9361",8,"Rema, nanita, rema,\ny rema, y vamos remando;\nque los gachupines vienen\ny nos vienen avanzando.",166,2,-1,176,"Canción de Morelos",0,4,"ao",33,0,-1,0,165,165,"9361","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9362",8,"Bonito San Juan Betamo,\ncuando la luna salió;\ncuando Álvaro se vistió\nse oyeron los cañonazos.",176,2,3,176,"San Juan Betamo",5,4,"ao",-1,0,-1,0,165,165,"9362","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9363",8,"El mosquito americano\nahora acaba de llegar;\ndicen que vino a pasear\na este suelo mexicano.",166,2,-1,176,"Estrofa suelta",11,4,"ao",81,0,-1,0,165,165,"9363","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9364",8,"Los gringos de sopetón\nle entraron a la pelea;\nsi no amarran su correa,\nse les cae el pantalón.",185,2,13,176,"Estrofa suelta",11,4,"o",31,0,-1,0,165,165,"9364","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9367",8,"Corriendo el tiempo creció el piltoncle,\nse puso fraque, comió bistec;\nindio ladino vende a to patria\ny guri guri con el francés.",166,2,-1,176,"Amo nequi",3,4,"e",-1,0,-1,0,166,166,"9367","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9368",8,"Si a tu ventana llega\nun burro flaco,\ntrátalo con desprecio,\nque es un austríaco.",166,2,-1,176,"Estrofa suelta",6,4,"io",-1,0,-1,0,166,166,"9368","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9369",8,"Toca el clarín de campaña a la guerra,\nsalga el valiente guerrero a pelear;\ncorrerán los arroyos de sangre:\nque gobierne un tirano, jamás.",166,2,-1,176,"La Adelita",3,4,"a",-1,0,-1,0,166,166,"9369","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9370",8,"Me voy a la guerra, que el yaqui sabe pelear\npor defender su santa libertad,\ny que regresa después a su linda tierra:\nSonora libre siempre será.",166,2,-1,176,"Amo nequi",3,4,"a",-1,0,-1,0,166,166,"9370","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9371",8,"Adiós, mi papá y mi mamá, ya me voy,\ny a mis hermanitos los voy a dejar;\nsi muero en campaña, mi sangre la doy\npara que toditos tengan libertad.",166,2,-1,176,"Corrido del General Amaro",3,4,"a",-1,0,-1,0,166,166,"9371","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9373",8,"A la leva, leva, leva,\na la leva, leva iría;\nel que no fuera a la leva\nde cobarde pasaría.",166,2,-1,176,"La indita",1,4,"ia",0,0,-1,0,167,167,"9373","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9374",8,"A la leva, leva, leva,\na la leva, leva, andando;\nel que no fuera a la leva\nde cobarde irá pasando.",166,2,-1,176,"La indita",1,4,"ao",33,0,-1,0,167,167,"9374","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9375",8,"A la leva, leva, leva,\ny a la leva, leva iré,\ny si no voy a la leva,\npor cobarde pasaré.",166,2,-1,176,"La indita",1,4,"e",77,0,-1,0,167,167,"9375","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9376",8,"A la leva y más a la leva,\ny a la leva ¿quién no va?\nEl que no fuera a la leva\nse quedará por detrás.",171,2,4,176,"La indita",3,4,"a",-1,0,-1,0,167,167,"9376","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9377",8,"De San Martín, Tampacán,\nde Tanquián y San Vicente\ntodos los días pasa gente\na la fracción de Tamán.",175,2,6,176,"Estrofa suelta",11,4,"a",147,0,-1,0,167,167,"9377","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9378",8,"El corazón del dorado\nse hizo para padecer;\ncon su cuete bien fajado\nnada tiene que temer.",172,2,23,176,"Los Dorados",1,4,"e",20,0,-1,0,167,167,"9378","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9379a",8,"Tengo mi par de caballos\npara la Revolución,\nuno se llama “El Morito”\ny otro se llama “El Gorrión”.",176,2,3,176,"El muchacho alegre; La rielera",0,4,"o",31,0,-1,0,167,167,"9379a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9379b",8,"Tengo mi par de caballos\npara la Revolución,\nuno se nombra “El Canario”,\notro se nombra “El Gorrión”:\n¡caballos, qué buenos son!",167,2,2,176,"El caballito",7,5,"o",31,0,-1,0,167,167,"9379b","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9380",8,"Con los Dorados de Villa\nya me voy para la guerra,\ny áhi les dejo a mis amigos\nel corrido de “La higuera”.",166,2,-1,176,"La higuera",3,4,"ea",-1,0,-1,0,167,167,"9380","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9381",8,"Aquí se acaba el corrido,\nya me voy para Nogales,\ndonde se venden las habas\na cuatro por cinco reales,\ndonde nos morimos todos\no volvemos generales.",181,2,15,176,"''La voltereta",9,6,"ae",26,0,-1,0,168,168,"9381","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9382",8,"Bonitas conchitas\ncolor amapola;\nyo dejé a mis padres\npor irme a la bola.",166,2,-1,176,"Las conchitas",0,4,"oa",321,0,-1,0,168,168,"9382","",0,"","","",12,0,0,[],"",""],["frenk_t4-n9383",8,"Ándale, caballo blanco,\nsácame de este arenal,\nporque me vienen siguiendo\nlas tropas de Mariscal",166,2,-1,176,"Estrofa suelta",0,4,"a",1,0,-1,0,168,168,"9383","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9386",8,"¡Válgame Dios! ¿qué será esto?,\n¡válgame Dios! ¿qué será?\nUnos, que viva Jalisco,\ny otros, que la libertad.",173,2,17,176,"El pinacate",0,4,"a",-1,0,-1,0,168,168,"9386","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9387",8,"Todos dicen: “¡Viva! ¡viva!”,\nyo no sé quién vivirá:\nunos, que viva el gobierno\ny otros, que la libertad.",176,2,3,176,"San Juan Betamo",0,4,"a",-1,0,-1,0,168,168,"9387","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9388",8,"¡Válgame Dios! ¿qué será esto?,\n¡válgame Dios! ¿qué será?,\nque unos se pronuncian hora,\ny otros mañana lo harán.",166,2,-1,176,"El pinacate",0,4,"a",-1,0,-1,0,168,168,"9388","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9389",8,"Dicen que los federales\ntienen la vida vendida;\nténganla o nunca la tengan,\nfederales de mi vida.",166,2,-1,176,"Ya el águila se voló",0,4,"ia",37,0,-1,0,168,168,"9389","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9390",8,"Como que quiere llover,\ncomo que quiere hacer aire;\ny el que no quiera a Carranza\nque vaya a San Juan y baile.",171,2,4,176,"Manuelita",0,4,"ae",-1,0,-1,0,169,169,"9390","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9391",8,"Si tanto me quieres,\ncon tanta esperanza,\nvámonos juntos\na ver a Carranza.",180,2,25,176,"La chinita maderista; Estrofa suelta",6,4,"aa",163,0,-1,0,169,169,"9391","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9392",8,"Si tú me quisieras\ncomo yo te quiero,\niríamos los dos\na pelear por Madero.",176,2,3,176,"La chinita maderista",0,4,"eo",38,0,-1,0,169,169,"9392","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9393",8,"Si vieras, chinita,\ny ¡ay!, cuánto te quiero,\nno más porque dices:\n“¡Que viva Madero!”",176,2,3,176,"La chinita maderista",0,4,"eo",38,0,-1,0,169,169,"9393","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9395",8,"Estaban las tres pelonas\ndebajo de unos portales,\ngritando: “¡Viva Carranza,\npadre de los federales!”",166,2,-1,176,"Las tres pelonas",0,4,"ae",26,0,-1,0,169,169,"9395","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9396",8,"Estaban las tres pelonas\nsentadas en una esquina,\ny una a la otra se decían:\n“¡Que viva Tomás Urbina!”",166,2,-1,176,"Las tres pelonas",0,4,"ia",-1,0,-1,0,169,169,"9396","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9397",8,"Estaban las tres pelonas\nsentadas en su balcón,\ny una a la otra se decían:\n“¡Que viva Alvaro Obregón!”",179,2,26,176,"Las tres pelonas",0,4,"o",31,0,-1,0,169,169,"9397","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9398",8,"Estaban las tres pelonas.\nsentadas en una silla,\ny una a la otra se decían:\n“¡Que viva Francisco Villa!”",179,2,26,176,"Las tres pelonas",0,4,"ia",-1,0,-1,0,169,169,"9398","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9399",8,"—¿Dónde vas, Isabel?\n—Al Café de la Unión,\na tomar una copa\npor la Constitución.",173,2,17,176,"¿Dónde vas, Isabel?’’",0,4,"o",31,0,-1,0,170,170,"9399","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9400",8,"Una guacamaya pinta\nle dijo a una de alas verdes:\n“Si quieres tener dinero,\nvámonos con los rebeldes”.",166,2,-1,176,"Estrofa suelta",0,4,"ee",-1,0,-1,0,170,170,"9400","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9401",8,"Una guacamaya vieja\nle dijo a una más muchacha:\n“Si quieres ganar dinero,\nvamos pa Guayalejo”.",169,2,8,176,"La guacamaya",5,4,"eo",-1,0,-1,0,170,170,"9401","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9402",8,"Una guacamaya vieja\nle dijo a una más muchacha:\n“Si quieres tener dinero,\nvámonos con los del hacha”.",171,2,4,176,"La guacamaya",0,4,"aa",556,0,-1,0,170,170,"9402","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9403",8,"—Úrsula, ¿qué andas haciendo\npor la Calle Real, borracha?\n—Señor, me ando divirtiendo\ncon los señores del hacha.",166,2,-1,176,"Estrofa suelta, Úrsula",1,4,"aa",556,0,-1,0,170,170,"9403","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9404",8,"Santa Anna para mandar\nes la primera persona,\ny el más hábil general\na su lado vale anona.",166,2,-1,176,"Estrofa suelta",0,4,"oa",7,0,-1,0,170,170,"9404","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9405",8,"El Cerro de las Campanas,\norgullo del queretano,\ndonde don Benito Juárez,\ncon las leyes en la mano,\nahí le tostó las habas\nal pobre Maximiliano.",166,2,-1,176,"El queretanito’’",9,6,"ao",81,0,-1,0,170,170,"9405","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9406",8,"Allá va la cuacaracha\nderecho para Guerrero,\nporque quiere conocer\nese Mariano Romero.",166,2,-1,176,"La cucaracha",0,4,"eo",38,0,-1,0,170,170,"9406","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9407",8,"Éste es el caballo prieto\nque Pancho Villa ensillaba;\ncuando oía silbar los trenes\nse paraba y relinchaba.",166,2,-1,176,"El caballo prieto",0,4,"aa",28,0,-1,0,170,170,"9407","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9408",8,"Mi padrino fue Zapata,\nél me llevó a bautizar,\naquel que le dio a la patria\nsu vida y su libertad.",166,2,-1,176,"Al compás del 30-30",0,4,"a",-1,0,-1,0,170,170,"9408","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9409",8,"Necesito un automóvil\npara hacer la caminata\nal lugar donde mandó\na la Convención Zapata.",166,2,-1,176,"La cucaracha’’",0,4,"aa",74,0,-1,0,171,171,"9409","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9410",8,"¡Pobre Pancho Villa!,\nfue muy triste su destino:\nmorir en una emboscada\ny a la mitad del camino.",168,2,11,176,"La muerte de Pancho Villa",0,4,"io",199,0,-1,0,171,171,"9410","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9411",8,"La águila, siendo animal,\nse retrató en el dinero;\npa sentarse en el nopal\npidió licencia primero\nal Congreso General.",192,2,22,176,"Desde la sierra se ven",7,5,"a",1,0,-1,0,171,171,"9411","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9412",8,"Santa Anna va caminando\ncon pasos de guajolote,\na vender a su señor\ncomo Judas Iscariote.",166,2,-1,176,"Estrofa suelta",0,4,"oe",292,0,-1,0,171,171,"9412","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9413",8,"De Santa Anna y Satanás\nson de una misma opinión;\nuno azote del infierno\ny el otro de la nación.",166,2,-1,176,"Estrofa suelta",0,4,"o",31,0,-1,0,171,171,"9413","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9414",8,"Santa Anna dijo en el puerto,\ncuando ya se iba a embarcar:\n“Áhi les dejo el gallo muerto,\nacábenle de pegar”.",176,2,3,176,"San Juan Betamo",1,4,"a",21,0,-1,0,171,171,"9414","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9415",8,"Ya se va el gobernador\nen armón y carretilla,\npara pegarle en la torre\nal ladrón Francisco Villa.",168,2,11,176,"La cucaracha",0,4,"ia",162,0,-1,0,171,171,"9415","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9416",8,"Voy a contar las hazañas\ndel gran general Zapata:\ntiene tan negras entrañas,\nque después que roba mata.",169,2,8,176,"Estrofa suelta",1,4,"aa",-1,0,-1,0,171,171,"9416","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9417",8,"De nada nos ha servido\nla nueva Constitución,\nporque seguimos bailando,\nsin querer, el mismo son.",189,2,5,176,"Estrofa suelta",0,4,"o",31,0,-1,0,171,171,"9417","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9418",8,"Soy soldado de Iturbide,\nvisto las tres garantías,\nhago las guardias descalzo\ny ayuno todos los días.",166,2,-1,176,"Estrofa suelta",0,4,"ia",214,0,-1,0,171,171,"9418","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9419",8,"Santa Anna quere corona:\nse la haremos de hojalata;\npa que la tenga de oro,\nle ha de costar la otra pata.",166,2,-1,176,"Santa Anna",0,4,"aa",74,0,-1,0,172,172,"9419","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9420",8,"Santa Anna quiere corona:\nse la haremos de papel,\nporque la de oro que había\nera de Santa Isabel.",166,2,-1,176,"Estrofa suelta, Guadalajara en un llano; Santa Anna",0,4,"e",32,0,-1,0,172,172,"9420","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9421",8,"¡Ay, que sí, ay, que no!\nSanta Anna quere corona;\n¡ay, que sí, ay, que no!,\n¡malaya pero si no!",173,2,17,176,"Santa Anna",5,4,"o",-1,0,-1,0,172,172,"9421","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9422",8,"Ya el águila se voló,\nya el nopal quedó solito,\nya Santa Anna pegó el grito,\nya el Congreso se acabó.",166,2,-1,176,"Ya el águila se voló; Estrofa suelta",11,4,"o",2,0,-1,0,172,172,"9422","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9423",8,"¡Qué bonita guacamaya,\nazul, amarilla y verde,\nque peleó contra Santa Anna (chatita)!\nMi gallito nunca pierde.",170,2,7,176,"La guacamaya; Estrofa suelta",3,4,"ee",154,0,-1,0,172,172,"9423","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9424",8,"¡Qué bonita guacamaya,\ntan olorosa a alcanfor,\nque peleó contra Santa Anna (chatita),\npara traer a Comonfort!",170,2,7,176,"La guacamaya; Estrofa suelta",3,4,"o",-1,0,-1,0,172,172,"9424","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9425",8,"Soy indita, soy indiana,\nsoy indita michoacana,\nsoy indita desertora\nde las tropas de Orellana.",166,2,-1,176,"La indita",0,4,"aa",4,0,-1,0,172,172,"9425","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9426",8,"Ahí viene el indio Juárez,\nsentado en su sillón,\nlimpiándole las botas\nal joven Miramón.",166,2,-1,176,"Estrofa suelta",0,4,"o",31,0,-1,0,172,172,"9426","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9427",8,"“¡Ah, qué acción hemos perdido!”\ndecía un federal llorando;\nla cosa está de orejita,\nsegún estamos mirando;\nganando nuestro gallito,\ndestapó cacaraqueando.",166,2,-1,176,"Estrofa suelta",9,6,"ao",33,0,-1,0,172,172,"9427","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9428",8,"¡Ay, pobrecitos polkitos!,\nbuen petardo se han pegado:\nque pensaban ir por lana\ny salieron trasquilados.",166,2,-1,176,"Estrofa suelta",0,4,"ao",-1,0,-1,0,172,172,"9428","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9429",8,"El gran bandido Orihuela,\nderrotado en esta bola,\ncon turca de capichola\nen su rocín va que vuela.",166,2,-1,176,"Estrofa suelta",11,4,"ea",167,0,-1,0,173,173,"9429","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9430",8,"Ya mataron a Salinas,\nhora ¿qué dirá Tomás”\nLo mataron los indito\nlos inditos de Atoyac.",166,2,-1,176,"La india",0,4,"a",-1,0,-1,0,173,173,"9430","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9431",8,"Ya vienen los mecos\npa Guadalajara;\nel meco más grande\nya se bate en retirada.",173,2,17,176,"Los mecos",0,4,"aa",-1,0,-1,0,173,173,"9431","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9432",8,"Como pájaro vulcano,\nse vio triste prisionero\nel Archiduque extranjero,\nmonarca Maximiliano.",166,2,-1,176,"Estrofa suelta",11,4,"ao",81,0,-1,0,173,173,"9432","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9433",8,"—¡Inés, Inés!\n—Yo no me llamo así;\nyo me llamo Carlota,\nCarlota Emperatriz.",166,2,-1,176,"Los cangrejos",3,4,"i",-1,0,-1,0,173,173,"9433","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9434",8,"Y sí, y sa,\n¡viva la libertad!\nLos mochos que perdieron\n“¡Querétaro!” dirán.",166,2,-1,176,"Los cangrejos; Despedimiento de Maximiliano",3,4,"a",-1,0,-1,0,173,173,"9434","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9435",8,"Marchaban los cangrejos,\nmarchaban al compás,\ny el paso de adelante\nlo daban para atrás.",178,2,10,176,"Los cangrejos",0,4,"a",51,0,-1,0,173,173,"9435","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9436",8,"¡Ay!, General Félix Díaz,\n¡quién a ti te lo dijera,\nque tú pusiste la hamaca\npara que otro se meciera!",166,2,-1,176,"Estrofa suelta",0,4,"ea",44,0,-1,0,173,173,"9436","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9437",8,"Don Porfirio Díaz\nnos mandó solicitar,\nque nos esperaba\na la otra orilla del mar.",166,2,-1,176,"Canción de Porfirio Díaz",0,4,"a",21,0,-1,0,173,173,"9437","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9438",8,"Yo ya me voy, ya me voy,\nme voy para Veracruz,\nque ya perdieron los indios\ndel pueblo de Santa Cruz.",166,2,-1,176,"Los indios mayas",0,4,"u",109,0,-1,0,173,173,"9438","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9439",8,"Yo ya me voy, ya me voy,\nme voy pa Guadalajara,\nporque los indios no quieren\nla gorda tan martajada.",166,2,-1,176,"Los indios mayas’’",0,4,"aa",-1,0,-1,0,174,174,"9439","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9440",8,"Yo ya me voy, ya me voy\nal otro lado del mar,\nque ya no tienen los indios\nni camino que agarrar.",166,2,-1,176,"Los indios mayas",0,4,"a",21,0,-1,0,174,174,"9440","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9441",8,"Yo ya me voy, ya me voy,\nya me voy con mucho gusto,\nporque ya los indios mayas\nse están muriendo de susto.",166,2,-1,176,"Los indios mayas",0,4,"uo",497,0,-1,0,174,174,"9441","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9442",8,"Yo ya me voy, ya me voy,\nquédate con Dios, trigueña,\nporque ya los indios mayas\nestán sirviendo de leña.",166,2,-1,176,"Los indios mayas",0,4,"ea",291,0,-1,0,174,174,"9442","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9443",8,"Yo ya me voy, ya me voy,\npor el tiempo del invierno,\nporque ya los indios mayas\nestán mirando el infierno.",166,2,-1,176,"Ix>s indios mayas",0,4,"eo",225,0,-1,0,174,174,"9443","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9444",8,"Huertistas y felicistas\ny también los zapatistas\nse rindieron, se humillaron\na las fuerzas carrancistas.",166,2,-1,176,"La Julia",0,4,"ia",629,0,-1,0,174,174,"9444","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9445",8,"Ya se van los carrancistas,\nya se van para Saltillo,\na darle a los federales\nen el merito fundillo.",168,2,11,176,"La cucaracha",0,4,"io",228,0,-1,0,174,174,"9445","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9446",8,"Ya se van los carrancistas,\nya se van a Sombrerete,\na darle a los federales\nen el meritito ojete.",168,2,11,176,"La cucaracha",0,4,"ee",285,0,-1,0,174,174,"9446","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9447",8,"Con las barbas de Carranza\nvoy a hacer una toquilla,\npa ponérsela al sombrero\nde su padre Pancho Villa.",166,2,-1,176,"La cucaracha",0,4,"ia",162,0,-1,0,174,174,"9447","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9448",8,"Lloraban los maderistas\ny al perder un mazapán de coco:\n“Muchachos, adentro, adentro,\nque nos persiguen los otros”.",166,2,-1,176,"Los maderistas",3,4,"oo",-1,0,-1,0,174,174,"9448","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9449",8,"Centinela del castillo,\nrecuerda y toca la diana:\nmira que te están poniendo\ncañones en la bocana.",166,2,-1,176,"Los maderistas’’",0,4,"aa",4,0,-1,0,175,175,"9449","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9450",8,"Dicen que los carrancistas\nse parecen al alacrán:\ncuando ven a los villistas\ndan el piquete y se van.",166,2,-1,176,"La rielera",1,4,"a",147,0,-1,0,175,175,"9450","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9451",8,"Una cosa me da risa:\nPancho Villa sin camisa;\nya se van los carrancistas,\nporque vienen los villistas.",166,2,-1,176,"La cucaracha’’",0,4,"ia",629,0,-1,0,175,175,"9451","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9452",8,"La cucaracha no vuela,\nporque le hace falta un pie,\nporque se comió la tortilla\ndel general Juan José.",166,2,-1,176,"La cucaracha’’",0,4,"e",77,0,-1,0,175,175,"9452","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9453",8,"Los norcoreanos están\nusando bombas torpedo;\npero ¿cuándo ganarán?\nCuando San Juan baje el dedo.",166,2,-1,176,"Estrofa suelta",1,4,"eo",304,0,-1,0,175,175,"9453","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9454",8,"Ya los pueblos se preparan\na vivir de otra manera,\ncon su fuerza organizada,\nque promete nueva era.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"ea",44,0,-1,0,175,175,"9454","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9456",8,"Por el filo de la sierra\nvino un vaquero cantando:\n“El peón que no se organiza\nse queda de hambre temblando”.",166,2,-1,176,"El toro",0,4,"ao",33,0,-1,0,175,175,"9456","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9457",8,"Vamos, vamos, no se aplomen,\nesos que tanto gritaban\ny le prometían al pueblo\nque en la lucha lo ayudaban.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"aa",39,0,-1,0,175,175,"9457","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9458",8,"No hagamos ahora lo mismo\nque los ratones caseros,\nque, en cuanto se asoma el gato,\ncada cual a su agujero.",166,2,-1,176,"Estrofa suelta",0,4,"eo",-1,0,-1,0,175,175,"9458","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9459",8,"Compañeros campesinos,\ntengan, pues, delicadeza:\nhay que pelear con los ricos,\naunque tengan su riqueza.",170,2,7,176,"Estrofa suelta",0,4,"ea",108,0,-1,0,176,176,"9459","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9460",8,"¿Qué culpa tiene el huizache\nde haber nacido en el llano?\nValen más los de huarache\nque de choclo americano.",168,2,11,176,"El huizache",1,4,"ao",81,0,-1,0,176,176,"9460","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9461",8,"Yo vide pelear un toro\ncon una garza morena.\nEl amo siempre se chupa\nla sangre de nuestra vena:\n¡ni que fuéramos nosotros\nabejas de su colmena!",166,2,-1,176,"El toro",9,6,"ea",59,0,-1,0,176,176,"9461","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9462",8,"Los toros son los que braman\ndebajo de los ocotes;\nlos amos son los que maman\nnuestra cosecha de elotes.",166,2,-1,176,"El toro",1,4,"oe",565,0,-1,0,176,176,"9462","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9463",8,"Amigos, tengo un muchacho,\nque al amo no le daré,\nporque mi hijo no es macho\npara que lo jinetee.",166,2,-1,176,"El toro",5,4,"ee",-1,0,-1,0,176,176,"9463","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9464",8,"Por áhi viene el caporal\ncon el machete en la mano,\ngritándole a los vaqueros:\n“Hay que ajusticiar al amo”.",166,2,-1,176,"El toro",0,4,"ao",-1,0,-1,0,176,176,"9464","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9465",8,"Échales bien la lazada\na esa punta de panzones,\nque se van quedando atrás,\na gozar de los millones.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"oe",34,0,-1,0,176,176,"9465","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9467",8,"Trae una lengua muy larga,\npara darle un revolcón\na los ricos testarudos\nque tengan mal corazón.",166,2,-1,176,"Estrofa suelta",0,4,"o",31,0,-1,0,176,176,"9467","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9468",8,"Todos los días que amanece\nle pido a mi Dios eterno\nque se muera un cabrón rico,\npa que se vaya al infierno.",169,2,8,176,"Estrofa suelta",0,4,"eo",225,0,-1,0,176,176,"9468","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9469",8,"Ya verán cómo se mueren,\nricos, ¡hijos del dinero!\nYo no vengo a ver si puedo,\nsino porque puedo vengo.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"eo",-1,0,-1,0,177,177,"9469","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9470",8,"¡Ya verán, monjas y curas,\nque se mantienen del pueblo!\nYo no vengo a ver si puedo,\nsino porque puedo vengo.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"eo",-1,0,-1,0,177,177,"9470","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9471",8,"¡También ustedes, soldados,\nmantenidos del gobierno!\nYo no vengo a ver si puedo,\nsino porque puedo vengo.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"eo",-1,0,-1,0,177,177,"9471","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9472",8,"Prepara tu carabina,\nque ya se nos van quedando\nlos políticos gallinas,\nque siempre se andan rajando.",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"ao",33,0,-1,0,177,177,"9472","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9473",8,"¡Qué desgraciados serán\nesos que entran al gobierno\nno más a robar el dinero\nque tanto le cuesta al pueblo!",166,2,-1,176,"Yo no vengo a ver si puedo",0,4,"eo",-1,0,-1,0,177,177,"9473","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9475",8,"“La raspa” la bailó\nCamacho con Almazán,\ny ahora resultó\nPadilla con Alemán.",168,2,11,176,"La raspa",1,4,"a",147,0,-1,0,177,177,"9475","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9476",8,"De testigo pongo aquí al siglo veinte,\ncomo certero y seguro,\npara que noticie del hecho presente\nde lo pasado y futuro.",166,2,-1,177,"Historia del pronunciamiento del General Emiliano Zapata",3,4,"uo",248,0,-1,0,178,178,"9476","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9477",8,"¡Ea, ea, toma, toma!,\n¡corre, muchacho!,\nque allí está el oro;\néchale mano,\ndánoslo todo.",166,2,-1,177,"El toro",7,5,"oo",-1,0,-1,0,178,178,"9477","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9478",8,"Éste es un son que bailaba Carmelita;\naquellos tiempos, los tiempos de don Simón,\nque amarraban los perros con longaniza\ny ni siquiera les ponían atención.",171,2,4,177,"La yerbabuena",3,4,"o",31,0,-1,0,178,178,"9478","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9479",8,"Los señores cuando iban al templo\noían misa con gran devoción,\ny llevaban también su rosario\ny rezaban alguna oración.",178,2,10,177,"Don Simón",3,4,"o",31,0,-1,0,178,178,"9479","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9480",8,"Y hoy los soldados todos quieren ser\nde banqueta y lucir el pompón;\npero a la hora de los cocolazos,\n¡Qué carreras, señor don Simón!",178,2,10,177,"Don Simón",3,4,"o",31,0,-1,0,178,178,"9480","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9481",8,"Todas las arañas tienen\nsu santo de devoción,\nsu lamparita colgada\ny su escoba en el rincón.",166,2,-1,177,"Estrofa suelta",0,4,"o",31,0,-1,0,178,178,"9481","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9482",8,"Las señoras de allá en aquel tiempo\nnunca usaban botín de tacón,\ny hora que usan tamaña colota,\n¡ay, que tiempos, señor don Simón!",178,2,10,177,"Don Simón",3,4,"o",31,0,-1,0,178,178,"9482","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9483",8,"A la moda van entrando\ntoditas en general;\ncomo anden aparentando,\n¡qué importa que se vean mal!",171,2,4,177,"Estrofa suelta",1,4,"a",1,0,-1,0,178,178,"9483","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9484",8,"A las meseras y gatas\nen mis coplas las recorto,\nque aunque sean ñengas y flacas,\npresumen de pelo corto.",166,2,-1,177,"El vacilón",0,4,"oo",630,0,-1,0,179,179,"9484","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9485",8,"Se visten a lo fifí\ny se creen muy galanes,\ncon su pantalón balón,\ncomo las naguas de olanes.",166,2,-1,177,"Los tarzanes",0,4,"ae",444,0,-1,0,179,179,"9485","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9487",8,"Carolina, Carolina,\nno adoptes tal pretensión;\nsi te cortas la melena,\n¡qué dirá la población!",166,2,-1,177,"El vacilón",0,4,"o",31,0,-1,0,179,179,"9487","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9488",8,"Carolina, Carolina,\nno te vayas a pelar,\npara evitar mil molestias\ny no tener que pagar.",166,2,-1,177,"El vacilón",0,4,"a",21,0,-1,0,179,179,"9488","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9489",8,"[Qué decreto tan bonito,\nseñores, nos va a venir:\nque al hombre lo han de pedir\ny lo han de traer decentito!",166,2,-1,177,"Estrofa suelta",11,4,"io",119,0,-1,0,179,179,"9489","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9491",8,"—¿Dónde vas, Isabel?\n—Al Café de la Luz,\na tomar una copa\ncon don Juan de la Cruz.",173,2,17,177,"¿Dónde vas, Isabel?",0,4,"u",109,0,-1,0,179,179,"9491","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9492",8,"—¿Dónde vas, Isabel?\n—Al Café de la Unión,\na tomar chocolate\ncon Miguel Miramón.",188,2,24,177,"¿Dónde vas, Isabel?",0,4,"o",31,0,-1,0,179,179,"9492","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9494",8,"El caballito de Troya\nestá que se cae de risa,\nde ver a la estatua nueva\nsin sombrero y cacariza.",166,2,-1,177,"Estrofa suelta",0,4,"ia",420,0,-1,0,180,180,"9494","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9495",8,"Cuatro palomitas blancas\nparadas en un pretil,\nmirando a los sinvergüenzas\ncasándose a lo civil.",178,2,10,177,"Cuatro palomitas blancas",0,4,"i",290,0,-1,0,180,180,"9495","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9496",8,"Las ocho son en palacio,\nlas siete en la catedral;\nya no sé ni en qué hora vivo:\ntodo por la hora oficial.",166,2,-1,177,"Chula la mañana",0,4,"a",1,0,-1,0,180,180,"9496","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9497",8,"La pata de Santa Anna\nla llevan a enterrar;\ncon pitos y tambores\nla van a acompañar.",179,2,26,177,"Estrofa suelta",0,4,"a",21,0,-1,0,180,180,"9497","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9498",8,"La cucaracha, señores,\nsiempre fue una mascotilla\ny además, linda muchacha,\nque llevaba Pancho Villa.",166,2,-1,177,"La cucaracha",0,4,"ia",162,0,-1,0,180,180,"9498","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9499",8,"Los gringos inventaron\nlos aeroplanos,\npara que se mataran (cielito lindo)\nlos mexicanos:\nsin esperanza,\nporque en uno de ellos (cielito lindo)\nmurió Carranza.",175,2,6,177,"Cielito lindo",4,7,"aa",163,0,-1,0,180,180,"9499","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9500",8,"Que sí, que no, que ha de ser,\nque el día diez ha de temblar;\nque no, que no ha de temblar:\nasí ¿quién ha de entender?",166,2,-1,177,"Estrofa suelta",11,4,"e",20,0,-1,0,180,180,"9500","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9501",8,"¡Qué niguas ha habido este año!,\nno se pueden soportar;\nen Cabo Verde y Los Caños\ny en el cuartel general.",171,2,4,177,"Estrofa suelta",0,4,"a",-1,0,-1,0,180,180,"9501","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9502",8,"Yo creo semilla no habrá\npara el año venidero;\nsi este grillo no se va,\nes perdido el mundo entero.",171,2,4,177,"Estrofa suelta",1,4,"eo",38,0,-1,0,180,180,"9502","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9503",8,"Ya la plata se murió,\nya la llevan a enterrar;\nse la llevan para el Norte,\nque allá va a resucitar.",166,2,-1,177,"Estrofa suelta",0,4,"a",21,0,-1,0,180,180,"9503","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9504",8,"Se admiran las cucarachas\nque en esta triste nación\ntanta plata de las minas\nse volvió ya de cartón.",166,2,-1,177,"La cucaracha",0,4,"o",31,0,-1,0,181,181,"9504","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9505",8,"Ésta es la cucaracha patona,\nque por el hambre está eriza,\ny a todos los mexicanos\nnos dejó hasta sin camisa.",166,2,-1,177,"La cucaracha",3,4,"ia",68,0,-1,0,181,181,"9505","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9506",8,"La cucaracha, la cucaracha\nya no puede caminar,\nporque no tiene, porque le falta\ndinero para gastar.",166,2,-1,177,"La cucaracha",3,4,"a",21,0,-1,0,181,181,"9506","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9507",8,"Oigan con gusto estos versos,\nescuchen con atención:\nya la pobre cucaracha\nno consigue ni un tostón.",166,2,-1,177,"La cucaracha",0,4,"o",31,0,-1,0,181,181,"9507","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9508",8,"Ya la triste cucaracha\nno más gana tres cuartillas,\nse las come de escamocha,\nno ajusta pa las tortillas.",166,2,-1,177,"La cucaracha",0,4,"ia",294,0,-1,0,181,181,"9508","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9509",8,"Señores, la cucaracha\nya no puede ni ir a misa,\nporque ya vendió las enaguas,\nel rebozo y la camisa.",166,2,-1,177,"La cucaracha",0,4,"ia",68,0,-1,0,181,181,"9509","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9510",8,"La cucaracha, la cucaracha\nya no puede parrandear,\nporque no tiene para las gordas,\nmenos para vacilar.",166,2,-1,177,"La cucaracha",3,4,"a",21,0,-1,0,181,181,"9510","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9511",8,"La cucaracha, la cucaracha\nya no puede caminar,\nporque no tiene, porque le falta\nmarihuana que fumar.",166,2,-1,177,"La muerte de Pancho Villa; La cucaracha",3,4,"a",21,0,-1,0,181,181,"9511","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9512",8,"La cucaracha, la cucaracha\nya no quiere caminar,\nporque no puede y ya no quiere\ntantas plagas aguantar.",166,2,-1,177,"La cucaracha",3,4,"a",21,0,-1,0,181,181,"9512","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9513",8,"La manta la dan muy cara\ntoditos los usureros;\nlos rebozos, los zapatos,\nvestidos y los sombreros.",166,2,-1,177,"La cucaracha",0,4,"eo",22,0,-1,0,181,181,"9513","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9514",8,"Muchísimos comerciantes\n—hablo de ellos en presencia-\ndan sus mercancías muy caras,\nporque no tienen conciencia.",166,2,-1,177,"La cucaracha’’",0,4,"ea",46,0,-1,0,182,182,"9514","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9515",8,"Todo se ha puesto muy caro\ncon esta revolución:\nvenden la leche por onzas,\ny por gramos, el carbón.",166,2,-1,177,"La cucaracha",0,4,"o",31,0,-1,0,182,182,"9515","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9516",8,"Dan cinco chiles por medio,\ndiez jitomates, tostón,\ny toditos se cobijan\ncon esta revolución.",166,2,-1,177,"La cucaracha'T",0,4,"o",31,0,-1,0,182,182,"9516","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9517",8,"Todito se ha puesto caro\nen la presente ocasión;\nlos frijoles y la masa,\nla manteca y el carbón.",166,2,-1,177,"La cucaracha",0,4,"o",31,0,-1,0,182,182,"9517","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9518",8,"También el pan y tortillas\ndan caro sin compasión:\nsiete tortillas por medio,\ndiez galletas un tostón.",166,2,-1,177,"La cucaracha",0,4,"o",31,0,-1,0,182,182,"9518","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9519",8,"Se escasearon los garbanzos,\ny la harina, de ribete;\nlos pambazos de a centavo\nlos venden a uno por siete.",166,2,-1,177,"La cucaracha",0,4,"ee",285,0,-1,0,182,182,"9519","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9520",8,"Ya no comemos gallinas,\nni tampoco guajolotes;\nya escondieron todo el maíz;\nnos dejaron los olotes.",166,2,-1,177,"La cucaracha",0,4,"oe",565,0,-1,0,182,182,"9520","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9521",8,"Los tacos valían tres fierros\naquí y en Guadalajara;\nahora vale uno de a cinco,\npues la manteca está cara.",166,2,-1,177,"La cucaracha",3,4,"aa",57,0,-1,0,182,182,"9521","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9522",8,"¡Ay, amigos, valedores!,\n¿qué haremos con la brujez?\n¡Ya no hay para los frijoles,\nni para carne de res!",166,2,-1,177,"La cucaracha",0,4,"e",218,0,-1,0,182,182,"9522","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9523",8,"¡Qué fuerte está la ranquera,\naparceros, valedores!\nYa no se consigue un peso\npara gordas y frijoles.",166,2,-1,177,"La cucaracha’’",0,4,"oe",-1,0,-1,0,182,182,"9523","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9524",8,"Al llegar este momento\nme pongo a considerar\nlo caro que está el sustento\ny en lo que viene a parar.",166,2,-1,177,"Estrofa suelta",1,4,"a",21,0,-1,0,182,182,"9524","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9526",8,"Hemos visto a catrincitos\nque del “Buen Tono” fumaban;\nahora compran del manojo,\npues el hambre ya está brava.",166,2,-1,177,"La cucaracha",0,4,"aa",-1,0,-1,0,183,183,"9526","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9527",8,"Ahora hay unos catrincitos,\nde esos que comían gallina,\nahora los vemos hambrientos,\nespulgándose en la esquina.",166,2,-1,177,"La cucaracha",0,4,"ia",11,0,-1,0,183,183,"9527","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9528",8,"Se han visto unos catrincitos\nde bastón, levita y piocha,\nque se van hasta Tepito\na comer pura escamocha.",166,2,-1,177,"La cucaracha",0,4,"oa",441,0,-1,0,183,183,"9528","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9529",8,"Se han mirado a las rotitas,\nde esas catrinas polveadas,\nque le meten muy macizo\na las gordas martajadas.",166,2,-1,177,"La cucaracha",0,4,"aa",282,0,-1,0,183,183,"9529","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9530",8,"Si son todas las rotitas,\nde esas muy bien perfumadas,\nhoy le meten muy del duro\na las gordas enchiladas.",166,2,-1,177,"La cucaracha",0,4,"aa",282,0,-1,0,183,183,"9530","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9531",8,"Hasta las bellas catrinas,\nde esas de chongo postizo,\nlas vemos llevar la masa,\nformadas como chorizos.",166,2,-1,177,"La cucaracha",0,4,"io",-1,0,-1,0,183,183,"9531","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9532",8,"Las catrinas pretenciosas\nvan al molino de prisa;\ntodas se ponen formadas,\ntiesas como longaniza.",166,2,-1,177,"La cucaracha",0,4,"ia",420,0,-1,0,183,183,"9532","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9533",8,"Si Dios me diera permiso\nen esta amable sociedad,\ngozaríamos de paz y contento\ny también de tranquilidad.",187,2,12,177,"El aguajacado",3,4,"a",16,0,-1,0,183,183,"9533","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9534",8,"Ya viene Calleja\ncon sus batallones,\nagarrando viejas\npor los callejones.",182,2,21,178,"Estrofa suelta",0,4,"oe",34,0,-1,0,186,186,"9534","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9535",8,"“¡Chinga tu madre, Francisco Villa!”,\nasí le dijo el mocho Obregón;\n“chíngala a veinte, chíngala a treinta”,\ny así empezó la Revolución.",168,2,11,178,"Tu madre es puta, tu padre es gacho",3,4,"o",31,0,-1,0,186,186,"9535","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9536",8,"Cuando vayas a la Villa\nno te acerques a la orilla,\npues te sale Pancho Villa\ny te quita la tortilla.",168,2,11,178,"Estrofa suelta",0,4,"ia",162,0,-1,0,186,186,"9536","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9537",8,"La cucaracha, la cucaracha\nya no quiere caminar;\nlos que combaten contra Villa\nse los lleva la cucaracha.",176,2,3,178,"La cucaracha",3,4,"aa",-1,0,-1,0,186,186,"9537","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9538",8,"Santa Anna cayó al infierno\ncomo tortilla tostada;\nporque ya no lo aguantaron,\nse lo llevó la [chingada],",173,2,17,178,"Santa Anna",0,4,"aa",49,0,-1,0,186,186,"9538","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9539",8,"Santa Anna cayó al infierno,\nardiendo como tecata,\nlos diablos le preguntaron:\n“¿Qué hiciste con la otra pata?”",173,2,17,178,"Santa Anna",0,4,"aa",74,0,-1,0,186,186,"9539","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9540",8,"Si Adelita se casara con Carranza\ny Pancho Villa con Álvaro Obregón,\nyo me casaba con Adelita,\n¡y se acababa la Revolución!",168,2,11,178,"La muerte de Pancho Villa",3,4,"o",31,0,-1,0,186,186,"9540","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9541",8,"Agarra la carta, Cecilia,\nmírala letra por letra;\nen la letra va diciendo:\n“¡Viva Dios y viva Petra!”",166,2,-1,178,"La india; Ahora pregunto, pregunto",0,4,"ea",631,0,-1,0,186,186,"9541","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9542",8,"Estaban las tres pelonas\nsentadas en su ventana,\nesperando a Pancho Villa\npa que les diera una hermana.",166,2,-1,178,"‘‘Las tres pelonas",0,4,"aa",4,0,-1,0,187,187,"9542","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9543",8,"Estaban las tres pelonas\nsentadas en un sofá,\ny la gorda y la flaca,\ny la guaje de Soledad.",166,2,-1,178,"‘‘Las tres pelonas",0,4,"a",-1,0,-1,0,187,187,"9543","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9544",8,"Estaban las tres pelonas\nsentadas en su balcón,\ny la flaca y la gorda\ny la mula de Concepción.",166,2,-1,178,"Las tres pelonas",0,4,"o",31,0,-1,0,187,187,"9544","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9545",8,"La Habana se va a perder:\nla culpa tienen las bellas,\nel billar y las barajas,\nlas copas y las botellas.",166,2,-1,178,"El sargento",0,4,"ea",89,0,-1,0,187,187,"9545","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9546",8,"Arriba del cielo\ny hay unos tecolines,\npor donde se asoma\nseñor Ruiz Cortines.",171,2,4,178,"Naranjas y limas",0,4,"ie",272,0,-1,0,187,187,"9546","",0,"","","",15,0,0,[],"",""],["frenk_t4-n9547",8,"Carambada valerosa,\nmujer de gran bizarría,\nel Bajío repetirá\ntus hazañas a porfía.",166,2,-1,179,"La Carambada",0,4,"ia",0,0,-1,0,190,190,"9547","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9548",8,"Con sus pistolas al cinto,\ncon su puñal afilado,\nla valiente Carambada\natacó hasta la Acordada.",166,2,-1,179,"La Carambada",5,4,"aa",49,0,-1,0,190,190,"9548","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9549",8,"La Carambada fue airada\na pelear a todo vuelo,\ny, pecherona y bragada,\nlos dejó mirando el cielo.",166,2,-1,179,"La Carambada",1,4,"eo",10,0,-1,0,190,190,"9549","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9550",8,"La Carambada decía:\n“Soy el terror de esta zona;\nya no tiembles, vida mía,\nyo te pondré tu corona”.",166,2,-1,179,"La Carambada",1,4,"oa",7,0,-1,0,190,190,"9550","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9551",8,"La Carambada ya viene,\nla Carambada ya va;\n¡válgame San Apapucio,\nnos va a llevar la tostada!",166,2,-1,179,"La Carambada",5,4,"aa",-1,0,-1,0,190,190,"9551","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9552",8,"¡Adentro, adentro, muchachos,\nque Guzmán está peleando!\nEn el monte la..........\nlleva su treinta arrastrando.",166,2,-1,179,"Ahora pregunto, pregunto",0,4,"ao",33,0,-1,0,190,190,"9552","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9553",8,"Lelo, como era de gusto,\nles dijo: “Muchachos, vamos”,\nsin saber que el mal intento\nya lo traían en las manos.",170,2,7,179,"Estrofa suelta",0,4,"ao",-1,0,-1,0,190,190,"9553","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9554",8,"Dicen los de Barrazuela:\n“Vámonos recio a la cuesta;\nsolamente Juan Urbano\nnos hizo dar media vuelta”.",166,2,-1,179,"Ahora pregunto, pregunto; La india",0,4,"ea",-1,0,-1,0,191,191,"9554","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9555",8,"Tu hermosa Costa Chica\ncon sangre se ha empapado\nde seres inocentes\nque mueren sin cesar.",170,2,7,179,"Estrofa suelta",5,4,"a",-1,0,-1,0,191,191,"9555","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9557",8,"El día veintitrés de mayo,\nen ese Tecuicatlán,\nagarraron al calero,\nporque le formaron plan.",166,2,-1,179,"El calero",0,4,"a",147,0,-1,0,191,191,"9557","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9558",8,"Ya lamentan otro muerto\nen nuestra bella tierruca,\nsiendo el delincuente el Tuerto,\nque jugó y mató de nuca;\nresultó la pura yuca,\nmuy valiente, muy varón,\nmató del primer jalón;\naunque tuerto y desalado,\nno sufrió ni un arañón.\n¡Queda este año jubilado!",171,2,4,179,"Estrofa suelta",18,10,"ao",14,0,-1,0,191,191,"9558","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9559",8,"[El] amigo Manuel Hernández\nse la sacó con la de él:\nmandó a matar a Santiago\ny a Rosa y a nombre de él.",166,2,-1,179,"Arbolito del camino",3,4,"e",-1,0,-1,0,191,191,"9559","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9560",8,"Llegué a una panadería\ny oí que estaban hablando,\ny eran los hijos de Adán,\nque se estaban atrancando,\nporque los querían robar.",173,2,17,179,"Los panaderos",7,5,"a",-1,0,-1,0,191,191,"9560","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9561",8,"Se acabó la robadera\nen la hacienda del Rosario;\nya se acabó la alcancía\nque tenía el monte Calvario;\n¡ahora a ver quién ha de ir\na rezar hasta el Santuario!",169,2,8,179,"Estrofa suelta",9,6,"ao",25,0,-1,0,191,191,"9561","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9562",8,"Los tulises de hace un año\nsalían a robar las líneas;\nlos tulises de hoy en día\nsalen a robar gallinas.",178,2,10,179,"Los tulises’T",0,4,"ia",-1,0,-1,0,191,191,"9562","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9563",8,"Los tulises de hace un año\nsalían a robar los reales;\nlos tulises de hoy en día\nsalen a robar tamales.",166,2,-1,179,"Los tulises",3,4,"ae",26,0,-1,0,192,192,"9563","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9564",8,"¡Oh, Madre Guadalupana!,\npon tu gracia soberana\ny échale tu bendición\nal ladrón que va a salir,\nque va a morir.\nLas cinco son.",173,2,17,179,"La valona del preso",9,6,"o",31,0,-1,0,192,192,"9564","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9565",8,"Monjitas, rogad a Dios\npor un pobre ajusticiado,\nque se mira sentenciado\nal suplicio más atroz.",166,2,-1,179,"Estrofa suelta",11,4,"o",280,0,-1,0,192,192,"9565","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9566",8,"¡Ay, qué ruido de candados!,\n¡ay, qué subir y bajar!\n¡Ay, ya vienen los soldados\nque me van a fusilar!",173,2,17,179,"La valona del preso",1,4,"a",21,0,-1,0,192,192,"9566","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9567",8,"Soy con gusto ajusticiado,\npues grande justicia ha sido:\npienso que me han condenado,\nno por haberla matado,\nsí por haberla querido.",173,2,17,179,"La valona del preso",7,5,"io",101,0,-1,0,192,192,"9567","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9568",8,"¡Ay, qué sonido de llaves!,\n¡ay, qué altura de paderes!\n¡Ay, si en esta cárcel me hallo,\nla culpa son las mujeres!",166,2,-1,179,"La valona del preso",0,4,"ee",55,0,-1,0,192,192,"9568","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9569",8,"Árboles que están en frente,\nya estoy cansado de ustedes,\nporque no me dejan ver\nmás que mis cuatro paredes.",168,2,11,179,"La Sanmarqueña",0,4,"ee",378,0,-1,0,192,192,"9569","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9570",8,"Ya te he dicho que a la cárcel\nno me vayas a llorar:\nya que no me quitas penas,\nno me las vengas a dar.",176,2,3,179,"La mañanita alegre; La chirriona; Palomas que andan volando",0,4,"a",21,0,-1,0,192,192,"9570","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9571",8,"Oiga usted, señor prefecto,\ndéme used mi libertad,\nque no es la primer mujer\nque con un hombre se va.",166,2,-1,179,"La presa’’",0,4,"a",-1,0,-1,0,193,193,"9571","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9572",8,"Si el alcaide me hiciera un favor,\nde soltarme los grillos tantito,\npara darle a mi bien un besito;\n¡cárcel dura de amarga prisión!",166,2,-1,179,"Hasta cuándo, Heliodora, hasta cuándo",3,4,"o",-1,0,-1,0,193,193,"9572","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9573",8,"Del cielo cayó una alianza\ndestinada para mí;\nno pierdo las esperanzas\nque me ha de sacar de aquí\nel juez de primera instancia.",176,2,3,179,"Estrofa suelta",7,5,"aa",-1,0,-1,0,193,193,"9573","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9574",8,"No tengas pena por eso,\npreso en la cárcel estoy;\nno dejo de ser quien soy,\nni he de ser el primer preso.",170,2,7,179,"Estrofa suelta",11,4,"eo",48,0,-1,0,193,193,"9574","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9576",8,"¡Qué noches tan negras\npara la prisión!\nSuenan las cadenas,\nlate el corazón.",166,2,-1,179,"Escaleras de la cárcel",0,4,"o",31,0,-1,0,193,193,"9576","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9577",8,"Escaleras de la cárcel,\nescalón por escalón,\nunos suben y otros bajan\na dar su declaración.",166,2,-1,179,"Escaleras de la cárcel",0,4,"o",31,0,-1,0,193,193,"9577","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9578",8,"Si a las Recogidas fueres,\nsal a la puerta y verás\nuna Santa Magdalena,\ny a ella te encomendarás.",166,2,-1,179,"La presa",0,4,"a",51,0,-1,0,193,193,"9578","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9579",8,"—Tan, tan, tocan la puerta;\nportera, mire quién es;\n—Una pobrecita presa\nque nos manda nuestro juez.",166,2,-1,179,"La presa",0,4,"e",150,0,-1,0,193,193,"9579","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9580",8,"Señora, pase adelante,\nvea su metate cuál es,\ny si no trae cuatro reales,\nvaya doblando los pies.",176,2,3,179,"La presa",3,4,"e",218,0,-1,0,194,194,"9580","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9581",8,"En este lugar maldito,\ndonde impera la tristeza,\nno se castiga el delito:\nse castiga la pobreza.",169,2,8,179,"Estrofa suelta",1,4,"ea",108,0,-1,0,194,194,"9581","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9582",8,"Centinelas de la cárcel,\n¡cuánta lata dan ahí,\ncon esos gritos de alerta,\nque no dejan ni dormir!",166,2,-1,179,"Escaleras de la cárcel",0,4,"i",-1,0,-1,0,194,194,"9582","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9583",8,"Hay pájaros advertidos\nen el campo, es la verdad,\nque cantan muy afligidos,\ncon gusto y serenidad;\n¡y yo, con mis cinco sentidos,\ntengo menos libertad!",171,2,4,179,"El pájaro cú",9,6,"a",16,0,-1,0,194,194,"9583","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9584",8,"Un preso cantó una tarde\nuna muy triste canción:\n“Que si mis padres vivieran,\nno estuviera yo en prisión:\nya por mí hubieran hablado\ny me echarían su bendición”.",186,2,27,179,"El huerfanito",9,6,"o",31,0,-1,0,194,194,"9584","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9585",8,"Estando preso en la cárcel,\nun cadáver vi pasar:\nera mi madre sagrada,\nque llevaban a enterrar.",175,2,6,179,"El huerfanito",0,4,"a",21,0,-1,0,194,194,"9585","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9586a",8,"Cuando estaba yo en la cárcel\nsolito me entretenía,\ncontando los eslabones\nque mi cadena tenía.",166,2,-1,179,"Escaleras de la cárcel",0,4,"ia",0,0,-1,0,194,194,"9586a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9588",8,"En medio de un encinal\nme iban a dar mi sentencia,\ny el ángel de tu inocencia\nfue el que me vino a salvar.",167,2,2,179,"Estrofa suelta",5,4,"a",-1,0,-1,0,195,195,"9588","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9589",8,"Preso me llevan\npara el presidio de San Juan;\nse valieron de El Manchado\npara poderme desterrar.",178,2,10,179,"Se acabaron mis paseadas",3,4,"a",-1,0,-1,0,195,195,"9589","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9590",8,"Ya me llevan a presidio,\nya me llevan a embarcar;\nmadrecita de mi vida,\nmadre de mi corazón,\nruégale a Dios tan divino\nque salga de esta prisión.",186,2,27,179,"El huerfanito",9,6,"o",31,0,-1,0,195,195,"9590","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9592",8,"“¡Y ay, qué bonito!\n—me dije a mi corazón—,\nque me llevan prisionero\npara la Villa de León.”",166,2,-1,179,"El cuervo",0,4,"o",31,0,-1,0,195,195,"9592","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9593",8,"Vuela, vuela, vuela,\npájaro galán,\ncuando me llevaron preso\nde aquí para Yucatán.",171,2,4,179,"La guacamaya",0,4,"a",147,0,-1,0,195,195,"9593","",0,"","","",17,0,0,[],"",""],["frenk_t4-n9594",8,"Vuelan, vuelan, vuelen,\ncomo yo volé\ncuando preso me llevaban\nde Tula a San Andrés.",171,2,4,179,"La guacamaya",0,4,"e",-1,0,-1,0,195,195,"9594","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9595",8,"Vuela, vuela, vuela,\ncomo yo volaba\ncuando me llevaban preso\nde Veracruz a Orizaba.",171,2,4,179,"La guacamaya",0,4,"aa",28,0,-1,0,195,195,"9595","",0,"","","",17,0,0,[],"",""],["frenk_t4-n9597",8,"¡Ay, de toda la reunión!,\nlo que me maravilla\nuna cruel compasión;\nregalaré cuartilla\ncuando esté en la prisión\nde allá de la Mixtequilla,",169,2,8,179,"El siquisirí",9,6,"ia",162,0,-1,0,196,196,"9597","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9598",8,"En la punta de aquel cerro\ntengo un vaso de aguardiente,\ndonde se lavan las manos\nlas hijas del presidente.",169,2,8,180,"Estrofa suelta",0,4,"ee",15,0,-1,0,200,200,"9598","",0,"","","",21,0,0,[],"",""],["frenk_t4-n9599",8,"Yo vide bajar un indio\ncon su carga de madera;\nmás atrás venía la indita,\nque hasta alzaba polvareda.",176,2,3,180,"La indita",0,4,"ea",-1,0,-1,0,200,200,"9599","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9600",8,"Yo vide cargar a un indio\ncon su lacito de a tlaco;\nyo no me admiro del indio,\nsino de verlo tan flaco.",176,2,3,180,"La indita",1,4,"ao",423,0,-1,0,200,200,"9600","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9601",8,"Alejandro se paseaba\npor el barrio noche y día,\ny sólo le acompañaban\nAntonio y José María.",166,2,-1,180,"Estrofa suelta",0,4,"ia",0,0,-1,0,200,200,"9601","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9602",8,"Ya me voy para mi casa,\nque hace días yo compré,\ny si ustedes no sabían,\nahora se los diré.",174,2,9,180,"Estrofa suelta",0,4,"e",77,0,-1,0,200,200,"9602","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9603",8,"Ahora sí, muchachos,\nya se pueden ir,\npara que mañana\nlos dejen venir.",168,2,11,180,"Estrofa suelta",0,4,"i",157,0,-1,0,200,200,"9603","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9604",8,"Ya me voy, porque no traigo\nlicencia para quedarme;\náhi mañana volveré\ncon licencia de mi padre,\ny entonces me quedaré.",171,2,4,180,"Los chiles verdes’’",7,5,"e",77,0,-1,0,200,200,"9604","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9605",8,"Cuando la niña\nestá en el asilo,\n¡qué contento está\npapá y mamá!",166,2,-1,180,"El asilo",6,4,"a",9,0,-1,0,200,200,"9605","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9606",8,"¡Pobrecito tío Cipriano!,\nsu vivir es un tormento;\nno puede llegar temprano,\nen platicar pierde el tiempo.",171,2,4,180,"Estrofa suelta",0,4,"eo",-1,0,-1,0,201,201,"9606","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9607",8,"Dice la india que no viene,\naunque la manden llamar;\ndice que se ha de sentar\nsobre la húmeda arena.",171,2,4,180,"‘‘La indita’’",5,4,"ea",-1,0,-1,0,201,201,"9607","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9608",8,"Del carpintero su hija,\ndel herrero la mujer,\ncomieron de nueve huevos,\ny ellos tocaron a tres.",171,2,4,180,"El carpintero",0,4,"e",-1,0,-1,0,201,201,"9608","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9609",8,"Señores, áhi va la bola,\nquién sabe a quién tumbará;\na que ninguna le da,\ncomo dijo Tía Canchóla;\nhasta el martes se sabrá\na ver quién le da a la bola.",166,2,-1,180,"Estrofa suelta",9,6,"oa",321,0,-1,0,201,201,"9609","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9610",8,"Tome usted la zarzaparrilla\ny píldoras de Bristól,\ntome usted las Jesusitas,\nque son del mejor sabor.",178,2,10,180,"‘‘La zarzaparrilla",0,4,"o",-1,0,-1,0,201,201,"9610","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9611",8,"De cualquier puerto o ciudad\nque tú vengas por aquí,\nte saluda cordialmente\nJoyería Luis Aquí.",185,2,13,180,"Estrofa suelta",0,4,"i",-1,0,-1,0,201,201,"9611","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9612",8,"Cuando vuelvas a tu tierra,\nperegrino visitante,\nrecuerda algo importante\nque tú viste desde aquí:\nes un letrero muy grande\ny que dice “Luis Aquí”.",185,2,13,180,"Estrofa suelta",9,6,"i",-1,0,-1,0,201,201,"9612","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9613",8,"Yo puse una librería\ncon los libros muy baratos,\ny en cada esquina decía:\n“Aquí se vende barato”.",168,2,11,180,"La librería",0,4,"ao",-1,0,-1,0,201,201,"9613","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9614",8,"Si yo tuviera dinero\ncomo estrella en el espacio,\nel primer gasto que hiciera\nhacería un gran palacio,\ncuatro ventanas y acerca,\ny en cada esquina un descanso",169,2,8,180,"La morena",9,6,"ao",-1,0,-1,0,201,201,"9614","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9615",8,"Si yo tuviera dinero\ncomo el buen Mercantil,\nel primer gasto que hiciera\nsería un ferrocarril,\ncon unos durmientes de acero\ny los rieles de marfil.",169,2,8,180,"El siquisirf",9,6,"i",290,0,-1,0,202,202,"9615","",0,"","","",6,0,0,[],"",""],["frenk_t4-n9617",8,"Ya mi primo se equivoca,\nno sé si será de sueño;\npero aquí tiene a su prima,\nque lo saca del empeño.",166,2,-1,180,"La guacamaya",0,4,"eo",138,0,-1,0,202,202,"9617","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9618",8,"—Manuelita, Manuelita,\ndime la edad que tú tienes.\n—Apenas cumplo quince años\nel dieciséis de septiembre.",171,2,4,180,"Manuelita",0,4,"ee",-1,0,-1,0,202,202,"9618","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9619",8,"Allá vienen las indias\ncon sus jicaras de bate,\ncosiendo sus colotones\ncon hilo de malacate.",166,2,-1,180,"El malacate",0,4,"ae",384,0,-1,0,202,202,"9619","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9620",8,"Indita que lavando estaba,\nlavando su posaguanco,\ndecía que no lo dejaba\nhasta no dejarlo blanco.",169,2,8,180,"Indita del alma; Estrofa suelta",1,4,"ao",303,0,-1,0,202,202,"9620","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9621",8,"—¿Qué andas haciendo, Vicenta,\npor las orillas del mar?\n—Ando buscando un aguaje\npa lavar mi delantar.",178,2,10,180,"Vicenta",0,4,"a",21,0,-1,0,202,202,"9621","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9622",8,"Lo que se precia en tener\ntoda mujer mexicana:\nsu rebozo de bolita,\nmedalla guadalupana,\nsu mantilla a la española\ny su almohadilla poblana.",166,2,-1,180,"Estrofa suelta",9,6,"aa",4,0,-1,0,202,202,"9622","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9623",8,"—Úrsula, ¿qué estás haciendo?\n—Remendando mi camisa,\nporque si no la remiendo,\nmañana no voy a misa.",169,2,8,180,"Úrsula",1,4,"ia",68,0,-1,0,202,202,"9623","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9624",8,"Antenoche pasé por tu casa,\npregunté lo que estabas haciendo,\nme dijeron que estabas cosiendo\nun vestido rojo de manta de a real.",176,2,3,180,"No bajes al agua",3,4,"a",-1,0,-1,0,202,202,"9624","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9625",8,"¡Ay!, chivarras coloradas,\nacabadas de teñir;\nno me las pongo de noche,\nporque no puedo dormir.",178,2,10,180,"Las chivarras",0,4,"i",157,0,-1,0,203,203,"9625","",0,"","","",3,0,0,[],"",""],["frenk_t4-n9626",8,"¡Ay, sí, ay, no!,\nme gusta tu malacó;\nsi tú no te lo pones,\nme lo voy a poner yo.",171,2,4,180,"Cielito lindo",3,4,"o",2,0,-1,0,203,203,"9626","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9628",8,"Tengo un sombrero\nde piel de conejo,\nque no le queda\nmás de barbiquejo.",174,2,9,180,"Estrofa suelta",6,4,"eo",264,0,-1,0,203,203,"9628","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9629",8,"Si mi sombrero se enchina,\nserá por el mal cuidado;\nen llegando a la esquina,\nsombrero, cáete a tu lado.",169,2,8,180,"Estrofa suelta",1,4,"ao",14,0,-1,0,203,203,"9629","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9630",8,"—Dicen que me voy pa China:\n¿no se les ofrece nada?\n—No se te vaya a olvidar\nmi gorrita galoneada.",166,2,-1,180,"El chinaco’T",0,4,"aa",49,0,-1,0,203,203,"9630","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9631",8,"Si vienes a Yucatán,\ntrae tu vestido ligero,\nporque hace mucho calor,\ny hay que andarse casi en cueros.",166,2,-1,180,"Estrofa suelta",0,4,"eo",-1,0,-1,0,203,203,"9631","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9632",8,"Pa que el sol no nos ponga morenas,\nsombreritos debemos llevar;\nbajaremos tempranito al baño,\ny en seguida iremos a almorzar.",166,2,-1,180,"Los baños",3,4,"a",21,0,-1,0,203,203,"9632","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9633",8,"—¿De dónde venites?\n—De Tacubaya.\n—¿Qué me trajites?\n—Una papaya.",171,2,4,180,"Chumba que chumba",6,4,"aa",404,0,-1,0,203,203,"9633","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9634",8,"—¿De dónde venites?\n—De Cartagena.\n—¿Qué me trajites?\n—Una azucena.",171,2,4,180,"Chumba que chumba",6,4,"ea",59,0,-1,0,203,203,"9634","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9635",8,"Cuando el barco costeño (mi vida)\nvenía silbando,\nera por los chorritos de agua (mi vida)\nque venía echando.",166,2,-1,180,"Adiós, Acapulco",3,4,"ao",33,0,-1,0,204,204,"9635","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9637",8,"Izó bandera la mira,\nno sé qué vapor será:\nsi será de San Francisco,\nsi será de Panamá.",166,2,-1,180,"Estrofa suelta",0,4,"a",9,0,-1,0,204,204,"9637","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9638",8,"Los barcos están varados\nporque no les pega el viento,\ny no han podido llegar\nbarquitos a Barlovento.",171,2,4,180,"El coco",0,4,"eo",94,0,-1,0,204,204,"9638","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9639a",8,"Los barcos que están varados\nporque no les sopla el Sur,\ny por eso no han entrado\nlos barcos a Veracruz.",171,2,4,180,"El coco",0,4,"u",-1,0,-1,0,204,204,"9639a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9641",8,"Atilín, Atilín,\natilín, tin, tin,\nque repiquen campanas\nde Medellín.",166,2,-1,180,"La bamba",6,4,"i",211,0,-1,0,204,204,"9641","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9642",8,"Quitilín, quitilín,\nquintán, quintán,\nque repiquen campanas\nde Matitlán.",171,2,4,180,"La bamba",6,4,"a",147,0,-1,0,204,204,"9642","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9643a",8,"Pues alhuite, alhuite, alhuite,\npues alhuite, alhuite, alhuate,\n¿qué fue lo que me trajiste?,\n¿qué fue lo que me dejaste?",171,2,4,180,"La indita’’",0,4,"ae",-1,0,-1,0,205,205,"9643a","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9644",8,"¡Ay sí, ay no, ay sí, ay no!,\nde veras sí, de veras no;\nlo que te dije se me olvidó,\nal cabo sí y al cabo no.",173,2,17,180,"El Cihualteco",3,4,"o",2,0,-1,0,205,205,"9644","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9645",8,"Tepalca, tepalca, tepalca, sí,\ntepalca, tepalca, tepalca, no;\nyo tenía mi tepalcano,\npero ahora lo tengo, y no.",166,2,-1,180,"De la arena nace el agua",3,4,"o",-1,0,-1,0,205,205,"9645","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9647",8,"Andándome yo paseando\npor esa ciudad de trancas,\noí una voz que me dijo:\n“¡Anselmo!, ¡Anselmo, llévame en ancas!”",178,2,10,180,"Anselmo",3,4,"aa",443,0,-1,0,205,205,"9647","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9648",8,"Andándome yo paseando\npor ese rancho de Cuevas,\noí una voz que me dijo:\n“¡Anselmo!, ¡Anselmo!,\nAnselmo, ¿qué no me llevas?’",178,2,10,180,"Estrofa suelta",7,5,"ea",632,0,-1,0,205,205,"9648","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9649",8,"Por aquí pasó el nahual,\ncon barriga de petate\ny sus ojos de cristal;\ncon sus alas de petate\ny barriga de costal.",178,2,10,180,"El nahual",7,5,"a",1,0,-1,0,205,205,"9649","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9650",8,"Dicen que el agua salada\ntiene varias erupciones;\nla cosa está comprobada,\nque mantiene a tiburones\ny a la sirena encantada.",175,2,6,180,"La Petenera",7,5,"aa",49,0,-1,0,205,205,"9650","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9651",8,"Don Pedro se casó anoche\ny en la madrugada enviudó;\nen busca de su mujer,\nun malaco encontró.",179,2,26,180,"Estrofa suelta",3,4,"o",2,0,-1,0,205,205,"9651","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9652",8,"Estrella de la mañana,\nque iluminas decadente;\nyo le dije a una gitana:\n“Adivíneme la suerte;\nno sé si estaré en mi cama\no Dios me mande la muerte”.",169,2,8,180,"Zapateado",9,6,"ee",134,0,-1,0,206,206,"9652","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9653",8,"Ese Filadelfo Robles\ntenía la sombra pesada;\nque él andando con su brosa\nni los perros le ladraban.",170,2,7,180,"Estrofa suelta",0,4,"aa",-1,0,-1,0,206,206,"9653","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9654",8,"El reloj marca la hora,\nya la campana sonó,\nson las dos de la mañana\ny el primer gallo cantó.",166,2,-1,180,"Alabanzas para difuntos",0,4,"o",2,0,-1,0,206,206,"9654","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9655",8,"En los versos del cantar\nhay uno que a mí me gusta:\nes de tontos que se asustan\ncon su sombra al caminar.",166,2,-1,180,"Maldita sea mi suerte",5,4,"a",21,0,-1,0,206,206,"9655","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9656",8,"Yo me paseo en carretón,\ny otros se pasean en coche;\nsi son hijos de familia,\n¿para qué salen de noche?",166,2,-1,180,"Esta guitarra es de fierro",3,4,"oe",337,0,-1,0,206,206,"9656","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9657",8,"Quisiera ser basilisco\npor horas y por momentos,\nmatar a quien yo quisiera\ny descansara mi cuerpo.",166,2,-1,180,"Estrofa suelta",0,4,"eo",-1,0,-1,0,206,206,"9657","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["frenk_t4-n9658",8,"—¿Quién torció ese tronconcito,\ntan derecho que venía?\n—Es que hay árboles torcidos:\nellos fueron, vida mía.",166,2,-1,180,"El tronconcito",0,4,"ia",0,0,-1,0,206,206,"9658","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9659",8,"¡Alma mía de mis corrales,\ncuando el indio los vendió!\nNo tuvo la culpa el indio,\nsino quien se las compró.",169,2,8,180,"La indita",0,4,"o",2,0,-1,0,206,206,"9659","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9660",8,"Andando yo con Sotelo,\nme sucedió una de malas;\nde allá me vine solito,\nél se quedó en Tacubaya.",166,2,-1,180,"La víbora; La india",0,4,"aa",-1,0,-1,0,206,206,"9660","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9661",8,"Pobrecita de esta india,\ntodos le dirán de tú;\nse la llevaron sus padres\npara el pueblo de Sichú.",181,2,15,180,"La indita",0,4,"u",73,0,-1,0,206,206,"9661","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9662",8,"Venderemos toro y vaca,\nvenderemos la becerra,\ntoditito venderemos (mi vida),\ntodito menos la tierra.",166,2,-1,180,"La higuera; Estrofa suelta",3,4,"ea",80,0,-1,0,207,207,"9662","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9663",8,"Venderemos la vaquita,\nvenderemos el becerro,\nvenderemos todo el rancho,\nmi china, menos la sierra.",166,2,-1,180,"Estrofa suelta",5,4,"ea",-1,0,-1,0,207,207,"9663","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9664",8,"Venderemos toro y vaca,\nvenderemos la marrana,\ntoditito venderemos (mi vida),\ntodito, menos la cama.",168,2,11,180,"La higuera",3,4,"aa",-1,0,-1,0,207,207,"9664","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9665",8,"¡Ay, madrecita del alma!,\n¿por qué me dejas cruzar\nsolita la nopalera,\ndonde se pierde cualquera\ny onde me van a matar?",178,2,10,180,"El tigre de Álica’T",7,5,"a",21,0,-1,0,207,207,"9665","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9666",8,"¡Huyuy!, ¡qué miedo me da!,\ndonde me iban a robar;\n¡ayayay!, en el pedregal,\nen ese mero pedregal,\n¡ay!, me iban a fusilar,\ny hasta me iban a encuerar.",166,2,-1,180,"El pedregal",9,6,"a",21,0,-1,0,207,207,"9666","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9667",8,"Y en ese Plan de Barrancas,\ndonde se ganan pesetas\nempedrando los caminos\npara que pasen carretas,\ndonde me iban a robar\nlos de la nueva Secreta.",166,2,-1,180,"Las barrancas",9,6,"ea",-1,0,-1,0,207,207,"9667","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9668",8,"Y ¿qué te lo pareciera\nque vinieran lo ladrone,\nse llevaran to mogier,\nte dejaran sin calzone?",169,2,8,180,"Amo nequi",0,4,"oe",613,0,-1,0,207,207,"9668","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9669",8,"Hasta la barra se supo\nque yo había muerto en Barrera:\n¡arregao me hubiera muerto!,\n¡bonitas las chingaderas!",169,2,8,180,"Estrofa suelta",0,4,"ea",-1,0,-1,0,207,207,"9669","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9670",8,"—Hombre, José, ¿qué sentías?\n—Los efectos de la muerte.\n—Dime en verdad, ¿qué creías?\n—Que algún barreno muy fuerte\nme había cortado los días.",175,2,6,180,"Estrofa suelta",7,5,"ia",214,0,-1,0,207,207,"9670","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9671",8,"Dichoso tú, padre Adán,\ntú que en el mundo viviste\ny nunca jamás temiste\nal maldito “qué dirán”.",166,2,-1,180,"Estrofa suelta",11,4,"a",147,0,-1,0,208,208,"9671","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9672",8,"Yo no quisiera vivir\nal pie de la carretera,\nporque no dejan dormir\nlos carros con la ruidera,\ny no te quiero decir\nen el día la polvadera.",171,2,4,180,"Zapateado, El siquisirf’’",9,6,"ea",44,0,-1,0,208,208,"9672","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9673",8,"Monisquita Juan José,\n¿para qué lo quiere usted?,\n¿para qué llevas mi [a]tole\na orillas de un tacolole?",166,2,-1,180,"La indita",5,4,"oe",619,0,-1,0,208,208,"9673","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9674",8,"Me gusta el tono del bajo\ncuando le dan al colón;\n¿dónde está mi terreno\ncuando anduve de cabrón?",166,2,-1,180,"La india",0,4,"o",31,0,-1,0,208,208,"9674","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9675",8,"Y aunque yo soy artillero,\nya yo no sé ni qué hacer,\nporque he sido muy grosero:\nme lo ha dicho mi mujer.",171,2,4,180,"Los artilleros",1,4,"e",20,0,-1,0,208,208,"9675","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9676",8,"Buscas buen caballo\npara tu yegua,\ny das tu hija\nal primero que llega.",168,2,11,180,"Estrofa suelta",3,4,"ea",-1,0,-1,0,208,208,"9676","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9677",8,"Cuando pasa mi compadre\nme dice: “¿Qué haces áhi?\nApúrese, compadre,\nque otra esperanza no hay”.",174,2,9,180,"Estrofa suelta",1,4,"a",469,0,-1,0,208,208,"9677","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9678",8,"¿Para qué vas y vienes\na la botica,\nsi el dolor de cabeza\nno se te quita?",166,2,-1,180,"Anda, niña, anda, niña",6,4,"ia",-1,0,-1,0,208,208,"9678","",0,"","","",7,0,0,[],"",""],["frenk_t4-n9679",8,"—Muchacho, no digas eso,\nporque te van a azotar.\n—A mí no me azota nadien,\nmi mamá me ha de ayudar.",166,2,-1,180,"El muchacho",0,4,"a",21,0,-1,0,208,208,"9679","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9682",8,"—Levántale, Bartolito,\npor vida de tu nobleza;\n—No me hagas que me levante\ny te rompa la cabeza.",179,2,26,180,"Estrofa suelta",0,4,"ea",108,0,-1,0,209,209,"9682","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9683",8,"¡Válgame Dios, Cautiverio,\ndónde venistes a dar!\n'Taba quieto el hormiguero,\nlo has venido a alborotar.",189,2,5,180,"Estrofa suelta",0,4,"a",21,0,-1,0,209,209,"9683","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9684",8,"Si el patrón ya quiere esposa,\nque no nos traiga una fiera;\nél se merece otra cosa,\naunque la traiga de fuera.",167,2,2,180,"La calandria",1,4,"ea",44,0,-1,0,209,209,"9684","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9685",8,"Me puse en un espiadero,\nvide un venado por la orilla;\náhi me dice el compañero:\n“Apúntele a la rodilla,\nporque necesito el cuero\npara retovar mi silla”.",171,2,4,180,"Me puse en un espiadero; Estrofa suelta",9,6,"ia",162,0,-1,0,209,209,"9685","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9686",8,"Cuando los carros estaban\nal pie de la nopalera,\nlos caballos se paraban\nen sus patitas traseras.",178,2,10,180,"El tigre de Alica",0,4,"ea",-1,0,-1,0,209,209,"9686","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9687",8,"Pero con un buen menguante\ny que haya un buen temporal,\ny la familia me dice\ny el sereno me hace mal.",171,2,4,180,"El buscapiés",0,4,"a",1,0,-1,0,209,209,"9687","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9688",8,"A orillas del Papaloapan\nsoñé que estaba cantando,\ny mugiendo iban las vacas,\npor el río atravesando.",171,2,4,180,"A orillas del Papaloapan",0,4,"ao",33,0,-1,0,209,209,"9688","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9689",8,"El rosal se había encelado,\nporque la rosa cantaba;\néste se había enamorado\nde algo que no le tocaba,\npues un clavel colorado\nera el que la cortejaba.",175,2,6,180,"La Rosita",9,6,"aa",28,0,-1,0,209,209,"9689","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9690",8,"¡Ay, que le da y que le da,\nque le da para allá abajo!\n¡Ay, que le da y que le da,\nque le da para allá arriba!\nMe gusta la libertad,\nporque nadien se castiga.",170,2,7,180,"La Petenera",9,6,"ia",-1,0,-1,0,209,209,"9690","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9691",8,"Que éste era un viejo y una vieja,\nse fueron a los melones,\nse hallaron las matas secas\ny se dieron de coscorrones.",178,2,10,181,"Estrofa suelta",3,4,"oe",34,0,-1,0,212,212,"9691","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9692",8,"Una vieja y un viejo\nestaban jugando,\ny el viejo con miedo\nsalió chillando.",171,2,4,181,"La bamba",6,4,"ao",33,0,-1,0,212,212,"9692","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9693",8,"Una vieja y un viejito\ny andaban en aeroplano;\nla viejita le decía:\n“¡Ay, viejo!, dame la mano”.",167,2,2,181,"El caimán viejo",3,4,"ao",81,0,-1,0,212,212,"9693","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9694",8,"Una vieja y un viejito\npaseaban en bicicleta,\ny el viejito le decía:\n—“Viejita, no seas coqueta”.",167,2,2,181,"El caimán viejo",0,4,"ea",200,0,-1,0,212,212,"9694","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9695",8,"Una vieja y un viejito\nestaban dando consejos;\nla viejita le decía:\n“¡Ay, viejo!, yo no te dejo”.",167,2,2,181,"El caimán viejo",0,4,"eo",-1,0,-1,0,212,212,"9695","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9696",8,"Una vieja y un viejito\nestaban cortando manzanas,\ny el viejito le decía:\n—“Viejita, te tengo ganas”.",167,2,2,181,"El caimán viejo",0,4,"aa",263,0,-1,0,212,212,"9696","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9697",8,"Una vieja y un viejito\nse cayeron en un pozo,\ny la viejita decía:\n“¡qué viejito más sabroso!”",166,2,-1,181,"La cucaracha; El chilero",0,4,"oo",160,0,-1,0,212,212,"9697","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9698",8,"Una vieja y un viejito\njugaban beisbol a solas,\ny la vieja le decía:\n“Dame la base por bolas”.",174,2,9,181,"Estrofa suelta",0,4,"oa",317,0,-1,0,213,213,"9698","",0,"","","",9,0,0,[],"",""],["frenk_t4-n9699",8,"Una vieja se cayó\nen una fosa muy honda;\nun viejito la sacó\ncon la punta de la monda.",174,2,9,181,"El tarachi",1,4,"oa",182,0,-1,0,213,213,"9699","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9700",8,"Amigos, pongan atención,\nles cantaré una triste historia,\npero los lamentos y la situación\nen que se halla una pobre vieja.",169,2,8,181,"|Ay, amigos!, pongan atención",3,4,"ea",-1,0,-1,0,213,213,"9700","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9701",8,"Una vieja que yo conocía\ndebajo la cama y un gato tenía;\ncada vez que la vieja rezaba\ny el gato maullaba y así le decía.",171,2,4,181,"La vieja; La niña y su gato; Estrofa suelta",3,4,"ia",0,0,-1,0,213,213,"9701","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9702",8,"Y una vieja que yo conocía\ndebajo de la cama fandango tenía;\ncada vez que la vieja almorzaba\nfandango cenaba, fandango tenía.",171,2,4,181,"La vieja",3,4,"ia",-1,0,-1,0,213,213,"9702","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9703",8,"Una vieja se cayó\ncuando bailaba jarana,\ny al caer la xnuk, sufrió\nuna paliza soberana;\noigan cómo sucedió:\nuinn, dzop, léem, pajchán y azotó.",185,2,13,181,"Estrofa suelta",9,6,"o",2,0,-1,0,213,213,"9703","",0,"","","",4,0,0,[],"",""],["frenk_t4-n9704",8,"En la torre de una iglesia\nuna vieja se cayó;\nnada le pasó en los pies,\npues con la cabeza cayó.",168,2,11,181,"Estrofa suelta",0,4,"o",-1,0,-1,0,213,213,"9704","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9705",8,"Una vieja llorando decía:\n“¡Ay, Jerú, pero ay, ay, ay!,\npero los gustos que yo antes tenía:\nme pagaban, pues, de esta manera”.",169,2,8,181,"¡Ay, amigos!, pongan atención",3,4,"ea",-1,0,-1,0,213,213,"9705","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9706",8,"“¿Qué puede ser que no sea?”\ndijo una vieja en un rancho:\n“aunque me lo dejen ancho,\nmi corazón lo desea”.",166,2,-1,181,"Estrofa suelta",11,4,"ea",54,0,-1,0,214,214,"9706","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9707",8,"Una vieja muy revieja\nse agachaba y se lo veía;\nse daba la palmada:\n“¡Qué bueno estás todavía!”",169,2,8,181,"Estrofa suelta",3,4,"ia",0,0,-1,0,214,214,"9707","",0,"","","",5,0,0,[],"",""],["frenk_t4-n9708",8,"Por estas calles derechas\nvi correr un limón;\npa las muchachas, un beso,\ny a las viejas, un guantón.",166,2,-1,181,"Estrofa suelta",0,4,"o",31,0,-1,0,215,215,"9708","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9709",8,"Por esta calle derecha\ncorre el agua, y no la vemos;\nháganse a un lado, los viejos,\nque a los jóvenes queremos.",174,2,9,181,"Estrofa suelta",0,4,"eo",-1,0,-1,0,215,215,"9709","",0,"","","",8,0,0,[],"",""],["frenk_t4-n9710",8,"Pájaro, pájaro, pájaro\nde las alas azulejas;\nsi se mueren las muchachas,\n¿qué haremos con las viejas?",166,2,-1,181,"Chula la mañana",0,4,"ea",496,0,-1,0,215,215,"9710","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9711",8,"Una vieja lloraba,\npero quedito,\nporque decía que amaba (cielito lindo)\ny a un jovencito.\nNo era parejo:\nera ratón tiemito (cielito lindo)\npa gato viejo.",168,2,11,181,"‘‘Cielito lindo",4,7,"eo",264,0,-1,0,215,215,"9711","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9712a",8,"De La Habana han venido\nnuevos despachos:\nque se casen las viejas\ncon los muchachos.",171,2,4,181,"La bamba",6,4,"ao",463,0,-1,0,215,215,"9712a","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9713",8,"De La Habana han venido\nnuevos refranes:\nque se casen las viejas\ncon los tarzanes.",168,2,11,181,"La bamba",6,4,"ae",444,0,-1,0,215,215,"9713","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9715",8,"Me casé con una vieja,\n¡mal haya la chuchería!\nTodo el día me regañaba,\ntoda la noche tosía.",178,2,10,181,"Pregón del ante",0,4,"ia",0,0,-1,0,216,216,"9715","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9716",8,"Al lado de una laguna\nvide un gato sin orejas;\nlo que no hacen las muchachas\nhacen las malditas viejas.",176,2,3,181,"La sandía; ’El gavilancito. Estrofa suelta",0,4,"ea",496,0,-1,0,216,216,"9716","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9717",8,"Viejas, ¡cómo no se mueren!\nCabecitas de algodón,\nno le dan producto al mundo,\nni al diablo ni a la nación.",169,2,8,181,"Estrofa suelta",0,4,"o",31,0,-1,0,216,216,"9717","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9718",8,"Las viejas achicharradas\ncoquetean de a montón,\nse mandan pintar las canas\ny se cortan su mechón.",166,2,-1,181,"El vacilón",0,4,"o",31,0,-1,0,216,216,"9718","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9719",8,"La moda de las tusadas\nha invadido la nación:\nhasta a viejas arrugadas\nles gusta esa pretensión.",166,2,-1,181,"El vacilón",1,4,"o",31,0,-1,0,216,216,"9719","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9720",8,"También van las viejecitas\nque pasan de ochenta y tantos\na pedir que no las dejen\npara vestir a los santos.",171,2,4,181,"El framhoyán",0,4,"ao",618,0,-1,0,216,216,"9720","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9721",8,"Me dijo una vieja fea:\n“¡No se acerque, no me arrugue!,\n¡retire, por Dios, la mano!,\nsi no compra, no mallugue”.",166,2,-1,181,"La potranquita",0,4,"ue",633,0,-1,0,216,216,"9721","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9722",8,"¿Y quién culpa a los nopales\nde tener tantas espinas?\n¿Qué culpa tienen los viejos\nque las viejas sean endinas?",166,2,-1,181,"Los bueyes",0,4,"ia",243,0,-1,0,217,217,"9722","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9723",8,"Vieja mentirosa,\nse ha robado a mi hija;\n¡cómo no se lleva\nesa lagartija!",168,2,11,181,"Estrofa suelta",0,4,"ia",219,0,-1,0,217,217,"9723","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9724",8,"Una vieja retevieja\nsentada en una azotea\nse la llevaron los perros,\ncreyendo que era zalea.",177,2,18,181,"Canción de Porfirio Díaz",0,4,"ea",54,0,-1,0,217,217,"9724","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9725",8,"Una vieja se cagaba\ndetrás de la nopalera,\ny las tunitas bailaban\nal son de la pedorrera.",169,2,8,181,"Estrofa suelta, La Sanmarqueña",0,4,"ea",44,0,-1,0,217,217,"9725","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9726",8,"Una vieja se echó un pedo\ny del pedo tiró un burro;\n¡ah, qué recabrona vieja!,\n¡qué fuerza tenía en el culo!",169,2,8,181,"Estrofa suelta",0,4,"uo",-1,0,-1,0,217,217,"9726","",0,"","","",2,0,0,[],"",""],["frenk_t4-n9727",8,"Una vieja salió a mear\natrás de un palo de papayo;\nel sapo se estaba riendo\nporque [vido a?] su tocayo.",166,2,-1,181,"El gusto’*",0,4,"ao",293,0,-1,0,217,217,"9727","",0,"","","",1,0,0,[],"",""],["frenk_t4-n9728",8,"Los gatos y los ratones\njamás se han podido ver;\na los yernos y a las suegras\nque los manden a Belén.",166,2,-1,182,"Las chivarras",0,4,"e",-1,0,-1,0,218,218,"9728","",0,"","","",1,0,0,[],"",""]]);
